  ui_story_1_1_10_dialog_content = "<color=#e8d9bb>Dia <color=#FFB400>6.055</color>.</color>",
  ui_story_1_1_X1_dialog_content = "<color=#e8d9bb>\"Informe seu nome e confirme.\"</color>",
  ui_story_1_1_18_dialog_content = "<color=#FFB400>Soroz</color>...?",
  ui_story_1_1_X2_dialog_content = "Sim, PlayerName.",
  ui_story_1_1_A1_dialog_content = "Algo fora do comum no perímetro?",
  ui_story_1_1_A2_dialog_content = "Sinais fracos se aproximando. Talvez outra horda de <color=#FFB400>Eclipsitas</color>, como sempre.",
  ui_story_1_1_A3_dialog_content = "Deixa pra lá. Quero tentar reiniciar mais uma vez.",
  ui_story_1_1_A4_dialog_content = "Devo negar seu pedido, PlayerName.",
  ui_story_1_1_A5_dialog_content = "Muitas tentativas foram feitas, isso está afetando seu estado mental...",
  ui_story_1_1_A6_dialog_content = "Mas estamos quase sem energia, e precisamos sair daqui!",
