  ui_story_1_1_A8_dialog_content = "Vamos morrer se a energia acabar!",
  ui_story_1_1_A9_dialog_content = "Tudo é possível quando se tem vontade.",
  ui_story_1_1_A10_dialog_content = "Passaram-se 17 anos. Se fosse possível, já teríamos saído daqui.",
  ui_story_1_1_A11_dialog_content = "Sinto muito, PlayerName. É muito arriscado continuar com as tentativas. Por favor, acalme-se.",
  ui_story_1_1_A12_dialog_content = "Você conseguiu localizá-los?",
  ui_story_1_1_A13_dialog_content = "As chances de contatar outros <color=#FFB400>Celestitas</color> são ínfimas, mas eu tentarei novamente.",
  ui_story_1_1_A14_dialog_content = "Se conseguirmos encontrá-los, poderemos...",
  ui_story_1_1_A15_dialog_content = "Segundo meus cálculos, as chances de sairmos daqui sem um gerador funcional são próximas de zero.",
  ui_story_1_1_A16_dialog_content = "...",
  ui_story_1_1_B1_dialog_content = "Isso é um teste, PlayerName. Apenas elevando sua mente em isolamento você se tornará mais forte.",
  ui_story_1_1_B2_dialog_content = "Basta de sermões. Meus ouvidos não aguentam mais.",
  ui_story_1_1_B3_dialog_content = "Deseja ouvir a história do continente mais uma vez?",
  ui_story_1_1_B4_dialog_content = "Já ouvi isso 192 vezes.",
  ui_story_1_1_B5_dialog_content = "Comandos do campo de batalha?",
  ui_story_1_1_B6_dialog_content = "246 vezes. E isso não me será útil enquanto não puder sair daqui.",
  ui_story_1_1_B7_dialog_content = "Desculpe, PlayerName. Estava apenas tentando animar você.",
  ui_story_1_1_B8_dialog_content = "...",
  ui_story_1_1_B9_dialog_content = "Você <color=#FFB400>sonhou aquilo</color> novamente?",
  ui_story_1_1_B10_dialog_content = "Sim.",
  ui_story_1_1_B11_dialog_content = "Sonhos são imagens do desconhecido criadas pela mente. São ilusões.",
  ui_story_1_1_B12_dialog_content = "Você tem uma propensão a supervalorizar esse fenômeno psíquico, também conhecido como...",
  ui_story_1_1_B13_dialog_content = "Já faz 17 anos, e ainda não me acostumei com seu jeito de falar, Professor Soroz.",
  ui_story_1_1_B14_dialog_content = "Estou apenas reforçando que é um <color=#FFB400>sonho</color>, e não reflete a realidade.",
  ui_story_1_1_B15_dialog_content = "Foi muito real para um sonho. Era como se eu estivesse em <color=#FFB400>Eraveil</color>, presenciando a invasão pessoalmente...",
  ui_story_1_1_B16_dialog_content = "Pude sentir até mesmo o sofrimento deles.",
  ui_story_1_1_B17_dialog_content = "Memórias estão sempre associadas a emoções, distorcendo a verdade.",
  ui_story_1_1_B18_dialog_content = "A realidade é que você está vivo, e meu dever é mantê-lo assim.",
  ui_story_1_1_X3_dialog_content = "Lá vem você de novo...",
  ui_story_1_1_19_dialog_content = "Um momento, acabei de detectar um novo sinal.",
  ui_story_1_1_20_dialog_content = "Novo sinal?",
  ui_story_1_1_21_dialog_content = "Analisando novo sinal... Confirmo que ele vem de <color=#FFB400>Aurorians</color>.",
  ui_story_1_1_22_dialog_content = "Aurorians?",
  ui_story_1_1_23_dialog_content = "Sinto muito se lhe dei esperanças. Não são Celestitas.",
  ui_story_1_1_B20_dialog_content = "Tudo bem, já estou acostumado... Mas o que Aurorians estão fazendo aqui?",
  ui_story_1_1_B21_dialog_content = "Estão lutando contra <color=#FFB400>Eclipsitas</color> logo acima de nós, e parecem estar com problemas.",
  ui_story_1_1_A17_dialog_content = "Nenhum Aurorian chegou até aqui antes. Logo hoje, entre todos os dias...",
  ui_story_1_1_24_dialog_content = "Vou lhe mostrar o que está acontecendo lá fora.",
  ui_story_1_1_25_dialog_content = "Aquele troço que você mencionou está mesmo aqui, <color=#FFB400>Vice</color>?",
  ui_story_1_1_26_dialog_content = "Por que há tantos Eclipsitas por perto? Estamos cercadas...",
  ui_story_1_1_27_dialog_content = "Não há dúvidas. De acordo com os resultados da busca, deve haver uma <color=#FFB400>Colossus</color> por perto!",
  ui_story_1_1_A18_dialog_content = "Nossas varreduras não mostraram nada em todas as outras áreas, mas tenho um palpite de que vamos encontrar algo desta vez!",
  ui_story_1_1_A19_dialog_content = "Pra falar a verdade, estou mais preocupada em voltar viva. Viemos fazer reconhecimento, não lutar...",
  ui_story_1_1_28_dialog_content = "Já esperávamos encontrar Eclipsitas.",
  ui_story_1_1_29_dialog_content = "Mas há muitos deles!",
  ui_story_1_1_30_dialog_content = "Acha que vão nos deixar em paz se dissermos que estamos só de passagem?",
  ui_story_1_1_31_dialog_content = "Não seja ridícula! A <color=#FFB400>guerra</color> com os Eclipsitas já se estende por milênios.",
  ui_story_1_1_A20_dialog_content = "Além do mais, por que acha que esses vermes entenderão você?",
  ui_story_1_1_32_dialog_content = "Eu nem deveria estar nesta missão. Achei que seria moleza...",
  ui_story_1_1_33_dialog_content = "Concentre-se. Os Eclipsitas tão em grande número. Precisamos achar uma saída.",
  ui_story_1_1_34_dialog_content = "Deixe isso comigo... Torrente Rápida!",
  ui_story_1_1_35_dialog_content = "Vamos nos unir à Vice!",
  ui_story_1_1_36_dialog_content = "Por que o chão está se abrindo? Estou alucinando pela falta de sono?",
  ui_story_1_1_37_dialog_content = "<size=45>Cuidado! Agarrem-se a alguma coisa!</size>",
  ui_story_1_1_38_dialog_content = "Foi mal! Olha onde pisam...",
  ui_story_1_1_40_dialog_content = "Ai, ai, ai...!",
  ui_story_1_1_41_dialog_content = "Estão todas bem? Angel? Dove?",
  ui_story_1_1_42_dialog_content = "Onde... Olá, tem alguém aí?",
  ui_story_1_1_43_dialog_content = "Onde estou? O que é essa estrutura subterrânea...?",
  ui_story_1_1_A21_dialog_content = "Esse lugar... está perfeitamente preservado. Não estou imaginando coisas, estou?",
  ui_story_1_1_44_dialog_content = "Encontrei mesmo uma Colossus?",
  ui_story_1_1_45_dialog_content = "Angel, Dove, onde vocês estão?!",
  ui_story_1_1_46_dialog_content = "<anim type=Shake>Ahhhhhh!</anim>",
  ui_story_1_1_47_dialog_content = "Ah, dá um tempo, mais Eclipsitas?",
  ui_story_1_1_48_dialog_content = "Um golpe direto das Aurorians deixou uma abertura na traseira. Avaliando danos...",
  ui_story_1_1_49_dialog_content = "Isso significa... que posso sair pela abertura?",
  ui_story_1_1_50_dialog_content = "Sim. De acordo com os resultados, você pode sair para a superfície através da abertura.",
  ui_story_1_1_51_dialog_content = "De verdade? Posso finalmente sair...?",
  ui_story_1_1_A23_dialog_content = "Entretanto, isso não é recomendado devido ao número de Eclipsitas na região.",
  ui_story_1_1_A24_dialog_content = "Parece que a crise não foi evitada e que o mundo não mudou nem um pouco.",
  ui_story_1_1_52_dialog_content = "Tudo o que quero é sair correndo até lá, mas estou... apreensivo...",
  ui_story_1_1_B22_dialog_content = "Para você, os Eclipsitas são uma ameaça mortal.",
  ui_story_1_1_B23_dialog_content = "Não são apenas os Eclipsitas...",
  ui_story_1_1_B24_dialog_content = "É um sentimento mais complicado. Indescritível.",
  ui_story_1_1_A25_dialog_content = "Desculpe, não compreendo. Você está preocupado em me deixar para trás?",
  ui_story_1_1_53_dialog_content = "Está tudo bem. Quando a energia acabar, estarei livre como as outras Colossi.",
  ui_story_1_1_54_dialog_content = "Mas preciso cumprir minha missão. E acredito que você tem sua própria missão.",
  ui_story_1_1_55_dialog_content = "Mas já chega. Falaremos sobre isso depois.",
  ui_story_1_1_56_dialog_content = "Aquela Aurorian parece estar em apuros. Olhe...",
  ui_story_1_1_58_dialog_content = "Não consigo... lutar... usei toda a minha força...",
  ui_story_1_1_59_dialog_content = "Por que tinha que encontrar Eclipsitas logo agora?",
  ui_story_1_1_60_dialog_content = "<anim type=Shake><size=50>Ahhhh!</size></anim>",
  ui_story_1_1_61_dialog_content = "Lúmina... preciso de Lúmina...",
  ui_story_1_1_62_dialog_content = "Dê dois passos para a esquerda.",
  ui_story_1_1_63_dialog_content = "<size=45>Quem tá falando?!</size>",
  ui_story_1_1_64_dialog_content = "Estou ouvindo coisas, ou esses Eclipsitas estão realmente falando?",
  ui_story_1_1_65_dialog_content = "Você não está ouvindo coisas. Estou falando com você.",
  ui_story_1_1_66_dialog_content = "Minha nossa, é uma pessoa de verdade! Mas não se parece com nenhum dos nossos comunicadores...",
  ui_story_1_1_67_dialog_content = "Isso é <color=#FFB400>telepatia</color>.",
  ui_story_1_1_68_dialog_content = "Telepatia?",
  ui_story_1_1_B25_dialog_content = "É minha primeira vez falando com uma pessoa de verdade, então ainda estou me acostumando.",
  ui_story_1_1_A26_dialog_content = "Você consegue. Mesmo que essa seja sua primeira vez, você tem muitos anos de prática...",
  ui_story_1_1_A27_dialog_content = "Por que está me encorajando agora? Quem é você?",
  ui_story_1_1_A28_dialog_content = "Eu estava falando sozinho! Enfim...",
  ui_story_1_1_69_option_content = "Aumento de Força!",
  ui_story_1_1_70_dialog_content = "<size=45>Uuuuuaaaaaaaaah!</size>",
  ui_story_1_1_75_dialog_content = "Eu derrotei todos aqueles Eclipsitas sozinha!",
  ui_story_1_1_76_dialog_content = "O Rastro de Luz aumentou consideravelmente o meu poder.",
  ui_story_1_1_77_dialog_content = "Estou tendo uma Luminocepção? Será que dominei uma nova habilidade que nenhum outro Aurorian possui?",
  ui_story_1_1_78_dialog_content = "Destino, é o destino! Não... Talvez eu seja de uma linhagem especial?",
  ui_story_1_1_79_dialog_content = "Por que só aparece um problema atrás do outro? E se me desprezarem por ser uma forasteira?",
  ui_story_1_1_80_dialog_content = "Tecnicamente, a habilidade é minha.",
  ui_story_1_1_81_dialog_content = "Ahhh! Ainda está aqui? Você é um fantasma que assombra esse lugar?",
  ui_story_1_1_82_dialog_content = "Não sou um fantasma. Essa é minha habilidade psíquica, assim como o Rastro de Luz que você viu.",
  ui_story_1_1_83_dialog_content = "Quê? Então eu não descobri um poder novo...?",
  ui_story_1_1_84_dialog_content = "Desculpa te decepcionar.",
  ui_story_1_1_B26_dialog_content = "...",
  ui_story_1_1_B27_dialog_content = "Ah... Eu te assustei?",
  ui_story_1_1_B28_dialog_content = "Mas você também me assustou quando entrou com tudo aqui.",
  ui_story_1_1_B29_dialog_content = "Não tô entendendo é nada.",
  ui_story_1_1_B30_dialog_content = "Vamos conversar pessoalmente. Vocês, Aurorians, não devem estar acostumados a se comunicar assim.",
  ui_story_1_1_85_dialog_content = "Enfim, siga o túnel e me encontre na última sala.",
  ui_story_1_1_86_dialog_content = "Nossa...",
  ui_story_1_1_A34_dialog_content = "Hmm...",
  ui_story_1_1_87_dialog_content = "O que foi? Tem algo na minha cara? Eu acabei de lavar o rosto...",
  ui_story_1_1_88_dialog_content = "Ah, nada. Não estava esperando uma pessoa de verdade. Você não é um fantasma, é?",
  ui_story_1_1_89_dialog_content = "<size=40>Eu não disse que fantasmas não existem?</size>",
  ui_story_1_1_B31_dialog_content = "Então por que a surpresa?",
  ui_story_1_1_B32_dialog_content = "... Não esperava encontrar alguém com vida aqui.",
  ui_story_1_1_90_dialog_content = "É a mesma coisa... Então, quem é você? E isso... é uma Colossus?",
  ui_story_1_1_91_dialog_content = "É uma Colossus. Eu a comando, e fui eu quem falou telepaticamente com você antes.",
  ui_story_1_1_92_dialog_content = "Eu li sobre habilidades assim em livros de história, mas...",
  ui_story_1_1_93_dialog_content = "Mas o que...?",
  ui_story_1_1_94_dialog_content = "Espera aí, você é um... <color=#FFB400>Celestita</color>?",
  ui_story_1_1_95_dialog_content = "Por que a surpresa? Sim, sou um Celestita.",
  ui_story_1_1_96_dialog_content = "... Não há mais ninguém aqui?",
  ui_story_1_1_97_dialog_content = "Não. Meu lar foi destruído pelos Eclipsitas.",
  ui_story_1_1_A29_dialog_content = "É, eu ouvi falar...",
  ui_story_1_1_B33_dialog_content = "Posso fazer uma pergunta?",
  ui_story_1_1_B34_dialog_content = "Você está perto demais, Celestita...",
  ui_story_1_1_B35_dialog_content = "Ah, desculpe. Só queria perguntar...",
  ui_story_1_1_B36_option_content = "Você conhece outros Celestitas?",
  ui_story_1_1_B37_option_content = "O que aconteceu há 17 anos?",
  ui_story_1_1_B38_option_content = "O que são Aurorians e Eclipsitas?",
  ui_story_1_1_B39_dialog_content = "Estive aqui por muito tempo, e meu sistema de comunicação está avariado. Não consigo....",
  ui_story_1_1_B40_dialog_content = "Acalme-se. Não conheço outros Celestitas, mas talvez seja porque nunca encontrei nenhum.",
  ui_story_1_1_B41_dialog_content = "... Então, por que eles nunca me procuraram?",
  ui_story_1_1_B42_dialog_content = "...",
  ui_story_1_1_B43_dialog_content = "Antes... eu tinha lido arquivos sobre o que aconteceu em Eraveil. Mas às vezes tenho <color=#FFB400>sonhos</color> estranhos...",
  ui_story_1_1_B44_dialog_content = "Sonhos?",
  ui_story_1_1_B45_dialog_content = "Sobre o desastre... pode me contar mais?",
  ui_story_1_1_B46_dialog_content = "Eu era um bebê quando aconteceu, então não sei muito a respeito.",
  ui_story_1_1_B47_dialog_content = "Parece que Eclipsitas lançaram repentinamente um <color=#FFB400>ataque coordenado</color> e destruíram Eraveil em uma única noite.",
  ui_story_1_1_B48_dialog_content = "Sim, já sei disso.",
  ui_story_1_1_B49_dialog_content = "Isso é tudo que conheço, desculpe...",
  ui_story_1_1_B50_dialog_content = "Então, você é uma <color=#FFB400>Aurorian</color>?",
  ui_story_1_1_B51_dialog_content = "Sim, e ouvi dizer que no passado nos unimos aos Celestitas para enfrentar os Eclipsitas.",
  ui_story_1_1_B52_dialog_content = "Aqueles monstros eram Eclipsitas, não eram?",
  ui_story_1_1_B53_dialog_content = "Isso mesmo. Aqueles monstros agora assolam todas as partes do continente. Ninguém sabe de onde eles vieram.",
  ui_story_1_1_B54_dialog_content = "Alguns dizem que eles vieram do outro lado do mundo. Outros, que são uma punição divina.",
  ui_story_1_1_B55_dialog_content = "Tudo o que sabemos é que eles são nossos inimigos desde o início dos tempos.",
  ui_story_1_1_B56_dialog_content = "Bem... eu li tudo isso nos arquivos.",
  ui_story_1_1_B57_dialog_content = "Então por que perguntou?",
  ui_story_1_1_B58_option_content = "Tenho outra pergunta",
  ui_story_1_1_B59_option_content = "*Ficar em silêncio*",
  ui_story_1_1_B60_dialog_content = "Tenho outra pergunta...",
  ui_story_1_1_98_dialog_content = "Aliás, você passou todo esse tempo sozinho. Nunca pensou em sair?",
  ui_story_1_1_99_dialog_content = "Bem... nós não sabemos lutar. Ao contrário de vocês, que podem usar <color=#FFB400>Luminática</color>.",
  ui_story_1_1_100_dialog_content = "Posso enxergar o Rastro de Luz, mas não posso usá-lo para lutar. Que ironia, hein?",
  ui_story_1_1_101_dialog_content = "Não, irônico é o fato de Aurorians poderem usá-lo, mas não conseguirem enxergar o Rastro de Luz.",
  ui_story_1_1_103_dialog_content = "Enfim, eu nunca deixei o subsolo, e sobrevivi graças ao suporte de vida de Soroz.",
  ui_story_1_1_104_dialog_content = "\"<color=#FFB400>Soroz</color>\"? Quer dizer a Colossus? Ela tem um nome? Caramba...!",
  ui_story_1_1_105_dialog_content = "Claro, as Colossi são a combinação absoluta de magia, tecnologia e vida, e são capazes de pensar de forma autônoma.",
  ui_story_1_1_106_dialog_content = "Você pode se comunicar com ela, né, sendo um Celestita, e tal...?",
  ui_story_1_1_107_dialog_content = "Claro. É uma habilidade natural.",
  ui_story_1_1_109_dialog_content = "O que foi? Você está ferida?",
  ui_story_1_1_110_dialog_content = "...",
  ui_story_1_1_111_dialog_content = "Hein...? Não, apenas lembrei de uma coisa, só isso.",
  ui_story_1_1_112_dialog_content = "Ah, certo, quer dizer que ela ainda está funcionando? Talvez possamos...",
  ui_story_1_1_113_dialog_content = "Sinto muito. Mesmo que Soroz já tenha sido a melhor Colossus da classe Sky, ainda não consigo iniciá-lo.",
  ui_story_1_1_114_dialog_content = "Mas você parece saber bastante sobre as Colossi, não é, Vice?",
  ui_story_1_1_115_dialog_content = "Só um pouquinho! Eu li livros a respeito, e minha missão era buscar Colossi sobreviventes...",
  ui_story_1_1_A31_dialog_content = "Espera um pouco aí, do que você me chamou? Eu não disse meu nome!",
  ui_story_1_1_A32_dialog_content = "É minha habilidade psíquica, Vice. Ouvi sua conversa com o esquadrão lá fora.",
  ui_story_1_1_A33_dialog_content = "Ah... sim, esqueci que você é um Celestita.",
  ui_story_1_1_116_dialog_content = "É uma pena que Soroz não possa ser ativado, mas parece que encontrei algo ainda melhor!",
  ui_story_1_1_117_dialog_content = "Está falando de mim?",
  ui_story_1_1_118_dialog_content = "Ainda preciso da sua ajuda... hum, ainda não sei seu nome...",
  ui_story_1_1_119_dialog_content = "PlayerName.",
  ui_story_1_1_120_dialog_content = "PlayerName? Isso soa um pouco exótico mesmo!",
  ui_story_1_1_121_dialog_content = "Eu me separei do meu esquadrão quando caí. Pode me ajudar a encontrá-las?",
  ui_story_1_1_122_dialog_content = "Não consigo senti-las no momento. E você, Soroz, alguma coisa?",
  ui_story_1_1_123_dialog_content = "Há duas Aurorians no Altar de Luminita, e vários Eclipsitas estão se aproximando da área.",
  ui_story_1_1_124_dialog_content = "Em outras palavras, também não estamos a salvo aqui.",
  ui_story_1_1_125_dialog_content = "Parece que estão com problemas perto do Altar de Luminita.",
  ui_story_1_1_126_dialog_content = "Então eu devo ir ajudá-las!",
  ui_story_1_1_127_dialog_content = "Preciso da sua ajuda! Você consegue ver o Rastro de Luz e pode nos guiar durante a batalha!",
  ui_story_1_1_128_dialog_content = "Quer dizer, você aumentou meu poder como se não fosse nada!",
  ui_story_1_1_129_option_content = "Mas lutar não é o meu forte...",
  ui_story_1_1_130_option_content = "Então lutaremos juntos!",
  ui_story_1_1_131_dialog_content = "Não se preocupe, eu protejo você!",
  ui_story_1_1_132_dialog_content = "Ela tem razão. Eclipsitas se infiltraram no local. É mais seguro ficarmos juntos.",
  ui_story_1_1_133_dialog_content = "Tudo bem, Vice. Mas tenho um pedido...",
  ui_story_1_1_134_dialog_content = "É assim que se fala! Não há com o que se preocupar, eu protejo você!",
  ui_story_1_1_135_dialog_content = "A Aurorian destemida se chama Vice, não é?",
  ui_story_1_1_X6_dialog_content = "Você também tomou uma excelente decisão, PlayerName.",
  ui_story_1_1_136_dialog_content = "Mas espero que você possa me ajudar com um pedido.",
  ui_story_1_1_B61_dialog_content = "Sem problemas! Seja o que for, vou dar o meu melhor!",
  ui_story_1_1_137_dialog_content = "Quero que você me tire daqui.",
  ui_story_1_1_138_dialog_content = "Sair daqui... Claro. Mas você tem certeza?",
  ui_story_1_1_139_dialog_content = "Eu... não sei.",
  ui_story_1_1_140_dialog_content = "Mas sei que eu preciso sair!",
  ui_story_1_2_1_dialog_content = "Não aguento mais, Angel...",
  ui_story_1_2_2_dialog_content = "Os Eclipsitas continuam vindo. Não vou aguentar por muito tempo...",
  ui_story_1_2_3_dialog_content = "Quase não há Lúmina nesse lugar abandonado e escuro. Sem luz, é muito mais difícil enfrentar Eclipsitas!",
  ui_story_1_2_4_dialog_content = "Como vamos voltar à superfície? E cadê a Vice...?",
  ui_story_1_2_6_dialog_content = "Não quero morrer aqui!",
  ui_story_1_2_7_dialog_content = "Dove! Sou eu!",
  ui_story_1_2_8_dialog_content = "Ainda bem que você não tinha muita Lúmina, ou Vice poderia ter se machucado...",
  ui_story_1_2_9_dialog_content = "Vice? Você está bem?",
  ui_story_1_2_10_dialog_content = "Sim. Encontrei vocês graças a PlayerName!",
  ui_story_1_2_11_dialog_content = "PlayerName? Quem? Não vejo ninguém...",
  ui_story_1_2_12_dialog_content = "PlayerName vai nos guiar à distância! Só precisam cooperar!",
  ui_story_1_2_13_dialog_content = "Cooperar? Como? Nós...",
  ui_story_1_2_14_option_content = "Aumento de Força!",
  ui_story_1_2_15_dialog_content = "Eu estava sonhando em percorrer a luz?",
  ui_story_1_2_16_dialog_content = "O que está acontecendo, Vice? E por que aquela pessoa está se escondendo atrás da porta?",
  ui_story_1_2_17_dialog_content = "Desculpe, não sei lutar.",
  ui_story_1_2_18_dialog_content = "Luminocepção e habilidade psíquica... Então você é...",
  ui_story_1_2_19_dialog_content = "Você nunca disse que tinha um amigo assim, Vice.",
  ui_story_1_2_20_option_content = "Acabamos de nos conhecer...",
  ui_story_1_2_21_option_content = "Amigo?",
  ui_story_1_2_22_dialog_content = "Sim, PlayerName me salvou depois que caímos.",
  ui_story_1_2_23_dialog_content = "PlayerName é o mestre dessa Colossus e um Celestita.",
  ui_story_1_2_24_dialog_content = "Meu... \"amigo\"?",
  ui_story_1_2_25_dialog_content = "O que foi, PlayerName?",
  ui_story_1_2_26_dialog_content = "Ah, hum, nada.",
  ui_story_1_2_28_dialog_content = "Também encontrei Eclipsitas quando caí. PlayerName me salvou.",
  ui_story_1_2_29_dialog_content = "Essas são Angel e Dove. Estamos no mesmo esquadrão.",
  ui_story_1_2_30_dialog_content = "Sou PlayerName, dono dessa Colossus e um Celestita.",
  ui_story_1_2_31_dialog_content = "Obrigada pela ajuda, PlayerName. Mas acho que tenho mais perguntas para você...",
  ui_story_1_2_32_dialog_content = "Cele-o-quê? Não tenho ideia do que vocês estão falando.",
  ui_story_1_2_33_dialog_content = "Enfim, obrigada, PlayerName. Vamos ser amigos!",
  ui_story_1_2_34_dialog_content = "Nunca achei que faria amigos um dia...",
  ui_story_1_3_1_dialog_content = "E agora, Vice? Há Eclipsitas demais. Precisamos de reforços.",
  ui_story_1_3_2_dialog_content = "O transmissor quebrou durante a luta. <color=#FFB400>Navegador</color>, Soroz tem algum tipo de comunicador?",
  ui_story_1_3_3_dialog_content = "Não, está destruído.",
  ui_story_1_3_X1_dialog_content = "Mas você deve ter alguma arma, não é?",
  ui_story_1_3_X2_dialog_content = "Não, nadinha.",
  ui_story_1_3_4_dialog_content = "Por que não tentamos ligar a Colossus?",
  ui_story_1_3_X3_dialog_content = "<color=#e8d9bb>Falha ao iniciar. Número de Falhas: 3.921.</color>",
  ui_story_1_3_X4_dialog_content = "Ela não vai a lugar algum.",
  ui_story_1_3_X5_dialog_content = "Como isso é possível?",
  ui_story_1_3_X6_dialog_content = "Não. Eu já tentei diversas vezes. Por alguma razão, sempre falha.",
  ui_story_1_3_X7_dialog_content = "Sinto muito, mas a Colossus está em péssimas condições.",
  ui_story_1_3_X8_dialog_content = "A Colossus já está fazendo tudo o que pode, me manter vivo já é um esforço.",
  ui_story_1_3_X9_dialog_content = "Agradeço pelo elogio, PlayerName.",
  ui_story_1_3_X10_dialog_content = "...",
  ui_story_1_3_6_dialog_content = "Espere um pouco, Navegador.",
  ui_story_1_3_X11_dialog_content = "Mesmo que não possamos ligá-la e que ela não tenha armas, antes você falou algo sobre...",
  ui_story_1_3_7_dialog_content = "O Altar de Luminita, certo?",
  ui_story_1_3_8_dialog_content = "Lembro de que cada Colossus possui um Altar de Luminita para transmitir sinais de emergência.",
  ui_story_1_3_A1_dialog_content = "Alguém virá até aqui se avistar o sinal!",
  ui_story_1_3_9_dialog_content = "Deve estar por perto, não é? Você disse que Dove e Angel estavam próximas.",
  ui_story_1_3_10_dialog_content = "... Você sabe um bocado sobre as Colossi, hein?",
  ui_story_1_3_X12_dialog_content = "Só um pouquinho. As pessoas sempre me disseram que era inútil saber essas coisas...",
  ui_story_1_3_X13_dialog_content = "A estação está perto e em perfeito estado.",
  ui_story_1_3_X14_dialog_content = "Mas acho que você já sabe o que estou prestes a dizer...",
  ui_story_1_3_11_dialog_content = "Não temos os materiais necessários para lançar o sinal...",
  ui_story_1_3_12_dialog_content = "<color=#FFB400>Lumâmbar</color>.",
  ui_story_1_3_13_dialog_content = "Como você... Achei que tinha dito \"só um pouquinho\".",
  ui_story_1_3_14_dialog_content = "Temos Lumâmbar, se é disso que precisamos.",
  ui_story_1_3_15_dialog_content = "Mas, Vice...",
  ui_story_1_3_16_dialog_content = "O quê? Temos sim. Eu vi na sua bolsa!",
  ui_story_1_3_18_dialog_content = "Isso é muito valioso...",
  ui_story_1_3_19_dialog_content = "É uma questão de vida ou morte! Não é hora de ser pão-dura, Dove!",
  ui_story_1_3_B1_dialog_content = "Alguém vai me recompensar?",
  ui_story_1_3_B2_dialog_content = "Claro! Pode tirar 10 dias de folga quando voltarmos. Que tal?",
  ui_story_1_3_B3_dialog_content = "Hu-hu, fechado!",
  ui_story_1_3_B4_dialog_content = "Então vamos para o Altar de Luminita!",
  ui_story_1_3_A2_dialog_content = "Pode haver mais Eclipsitas pelo caminho, fiquem de olhos abertos!",
  ui_story_1_3_24_dialog_content = "É aqui! Que bom que o Navegador estava com a gente, ou teríamos nos perdido.",
  ui_story_1_3_25_dialog_content = "Sabe, já se passaram 17 anos...",
  ui_story_1_3_26_dialog_content = "Ainda bem que chegamos antes dos Eclipsitas.",
  ui_story_1_3_27_dialog_content = "Por sorte, não há nada danificado.",
  ui_story_1_3_28_dialog_content = "O controle é aquele ali?",
  ui_story_1_3_29_dialog_content = "Nossa, é a primeira vez que vejo isso de verdade! Quanto ao funcionamento...",
  ui_story_1_3_30_dialog_content = "Coloque o Lumâmbar no projetor e <color=#FFB400>puxe a alavanca</color>. Isso deve bastar.",
  ui_story_1_3_31_dialog_content = "Que pena que eu não tinha os materiais necessários antes...",
  ui_story_1_3_33_dialog_content = "Mas agora você tem amigos confiáveis! Dove!",
  ui_story_1_3_34_dialog_content = "Você vai fazer bom proveito desses materiais, não vai, Vice?",
  ui_story_1_3_35_dialog_content = "É claro.",
  ui_story_1_3_36_dialog_content = "...",
  ui_story_1_3_B5_dialog_content = "... Dove, você... já pode soltar.",
  ui_story_1_3_B6_dialog_content = "Hu-hu, ainda posso mudar de ideia?",
  ui_story_1_3_B7_dialog_content = "Se der para trás, eu farei você comer mil dedos de Eclipsitas.",
  ui_story_1_3_B8_dialog_content = "Huuu!",
  ui_story_1_4_1_dialog_content = "Sucesso! Uau, quanta luz!",
  ui_story_1_4_2_dialog_content = "Conseguimos... Valeu, Vice!",
  ui_story_1_4_3_dialog_content = "Hã? Eu não fiz nada, só dei umas ideias malucas.",
  ui_story_1_4_4_dialog_content = "Me agradeça quando sairmos daqui.",
  ui_story_1_4_5_dialog_content = "Bem, está claro que essa é uma Aurorian extraordinária, e todos trabalham bem em equipe!",
  ui_story_1_4_6_dialog_content = "O silêncio de todos esses anos... foi quebrado hoje.",
  ui_story_1_4_X1_dialog_content = "Mas por que você está triste, PlayerName? Está tudo bem?",
  ui_story_1_4_X2_dialog_content = "Estou bem, só me cansei um pouco...",
  ui_story_1_4_B29_dialog_content = "Está com sono? Tenho um presente pra você: desenhos mecânicos!",
  ui_story_1_4_B30_dialog_content = "Sempre que tenho sono, eu folheio as páginas... Fico novinha em folha depois de olhar pra esses diagramas!",
  ui_story_1_4_B31_dialog_content = "Acho que sua mente funciona diferente das outras, Vice.",
  ui_story_1_4_X3_dialog_content = "Hã? Mas... Ugh!",
  ui_story_1_4_X4_dialog_content = "Qual o problema? Tem algo no meu rosto de novo?",
  ui_story_1_4_X5_dialog_content = "Seu nariz está sangrando!",
  ui_story_1_4_X6_dialog_content = "Ah, não... Sobrecarga... de telepatia...",
  ui_story_1_4_X7_dialog_content = "Operar o Altar de Luminita me deixou no limite...",
  ui_story_1_4_A1_dialog_content = "Você nos guiou facilmente antes, por que agora...?",
  ui_story_1_4_A2_dialog_content = "Controlar a Colossus... requer... mais energia. Estou bem... isso já aconteceu antes... ficarei...",
  ui_story_1_4_7_option_content = "Não... consigo...",
  ui_story_1_4_8_option_content = "Vice...",
  ui_story_1_4_9_dialog_content = "Você está bem... Ei, alguém me ajude, PlayerName desmaiou!",
  ui_story_1_4_10_dialog_content = "Não consigo segurar... Vocês duas, venham até aqui! Não consigo carregar PlayerName sozinha!",
  ui_story_1_4_12_dialog_content = "A luz está atraindo Eclipsitas. Precisamos sair daqui!",
  ui_story_1_4_13_dialog_content = "Tenente Vice, PlayerName ainda está desacordado. Infelizmente, será um fardo levá-lo conosco.",
  ui_story_1_4_A6_dialog_content = "Meu dever é levar a dama até a <color=#FFB400>Subcidade 28</color> em segurança. Não temos muito tempo...",
  ui_story_1_4_A3_dialog_content = "Agradeço pela sua ajuda, soldado. Mas PlayerName nos salvou. Não podemos abandoná-lo aqui.",
  ui_story_1_4_14_dialog_content = "Retribuir bondade com negligência não é o caminho da <color=#FFB400>Federação Illumina</color>.",
  ui_story_1_4_A4_dialog_content = "Além disso, PlayerName é um Celestita.",
  ui_story_1_4_15_dialog_content = "Isso é verdade?",
  ui_story_1_4_16_dialog_content = "Mas não temos números o bastante para manter todos a salvo e carregar uma pessoa desacordada!",
  ui_story_1_4_17_dialog_content = "Tem razão, soldado. Leve todos para fora daqui e deixe algumas provisões. Ficarei para trás e protegerei o Celestita.",
  ui_story_1_4_18_dialog_content = "Você é formidável, Tenente Vice!",
  ui_story_1_4_19_dialog_content = "Ainda não me apresentei. Sou Blanc. Prazer em conhecê-la.",
  ui_story_1_4_20_dialog_content = "Desculpe por darmos trabalho a você, senhora...",
  ui_story_1_4_21_dialog_content = "Tudo bem. Eu não poderia ignorar um sinal de emergência.",
  ui_story_1_4_22_dialog_content = "E ver pessoalmente uma Colossus fez a viagem valer a pena.",
  ui_story_1_4_23_dialog_content = "Sou um membro da equipe de Exploração. Se a capitã decidiu ficar, eu também ficarei.",
  ui_story_1_4_24_dialog_content = "Huu? Então... eu também vou ficar. Afinal, PlayerName salvou nossas vidas.",
  ui_story_1_4_25_dialog_content = "Pessoal...",
  ui_story_1_4_A5_dialog_content = "Ah, você acordou! Os reforços chegaram. Como está se sentindo? Consegue andar?",
  ui_story_1_4_26_dialog_content = "Hmm...",
  ui_story_1_4_28_dialog_content = "Acabamos de saber que Kraken foi avistado nas redondezas, Tenente Vice.",
  ui_story_1_4_29_dialog_content = "<color=#FFB400>Kraken, o Eclipsita de alto nível</color>? Ele está mais ativo ultimamente, mas por que estaria tão perto?",
  ui_story_1_4_30_dialog_content = "Não importa, depois nos preocupamos com isso! Hora de ir!",
  ui_story_1_4_31_dialog_content = "Você vem com a gente, PlayerName?",
  ui_story_1_4_32_dialog_content = "Eu adoraria ir com você, Vice. Mas Soroz...",
  ui_story_1_4_33_dialog_content = "A Colossus se chama Soroz? Poderemos resgatá-la depois.",
  ui_story_1_4_X8_dialog_content = "Meu único dever é manter todos a salvo.",
  ui_story_1_4_X9_dialog_content = "Tudo bem, PlayerName. Contanto que você esteja fora de perigo, minha segurança pouco importa.",
  ui_story_1_4_X10_dialog_content = "Passe pelos Eclipsitas e saia daqui!",
  ui_story_1_4_B1_option_content = "Me perdoe. Voltarei por você assim que possível!",
  ui_story_1_4_B2_option_content = "Há alguma forma de sairmos todos juntos?",
  ui_story_1_4_B3_option_content = "Preciso empacotar meus pertences...",
  ui_story_1_4_B4_dialog_content = "Está decidido. Vou com você!",
  ui_story_1_4_B5_dialog_content = "No momento, tudo que sei é que esperei tempo demais... Não importa o que está acontecendo lá fora, preciso ver pessoalmente.",
  ui_story_1_4_B6_dialog_content = "Ainda tenho muitas coisas para perguntar ao meu povo...",
  ui_story_1_4_B7_dialog_content = "Muito bem! Vamos nos preparar para a batalha. Se os Eclipsitas já estão cercando este lugar, teremos que lutar!",
  ui_story_1_4_B9_dialog_content = "Nostalgia, medo, ansiedade... Preciso superar esses sentimentos para me tornar mais forte.",
  ui_story_1_4_B10_dialog_content = "Espero que você aprenda a superá-los.... Pode começar se despedindo de mim.",
  ui_story_1_4_B11_dialog_content = "Soroz...",
  ui_story_1_4_B12_dialog_content = "Apenas saindo daqui você cumprirá seu destino como Celestita. Vá, todos contam com você!",
  ui_story_1_4_B13_dialog_content = "E não vou a lugar algum. Não se preocupe.",
  ui_story_1_4_B14_dialog_content = "PlayerName, precisamos agir antes que mais Eclipsitas cheguem!",
  ui_story_1_4_B15_dialog_content = "Eu sei...",
  ui_story_1_4_B16_dialog_content = "Certo! Todos, concentrem-se! Preparem-se para lutar! Vamos sair daqui!",
  ui_story_1_4_B17_dialog_content = "Hã? Pertences?",
  ui_story_1_4_B18_dialog_content = "Um caleidoscópio feito com peças sobressalentes, bolinhas amarradas por fios e alguns desenhos feitos com tinta Lúmina.",
  ui_story_1_4_B19_dialog_content = "...",
  ui_story_1_4_B20_dialog_content = "Não ria! Elas podem ser bugigangas, mas estiveram ao meu lado por todo esse tempo...",
  ui_story_1_4_B21_dialog_content = "Até dei nome a elas.",
  ui_story_1_4_B22_dialog_content = "... Sei como se sente, mas não é hora de se apegar a essas coisas.",
  ui_story_1_4_B23_dialog_content = "Confie em mim, PlayerName. Você terá muito mais pertences quando sair daqui.",
  ui_story_1_4_B24_dialog_content = "Não vou a lugar algum, e nem elas. Você poderá voltar aqui quando tudo isso acabar...",
  ui_story_1_4_B25_dialog_content = "Acho que não tenho escolha...",
  ui_story_1_4_B26_dialog_content = "Desculpe por dizer coisas estranhas... Vamos embora.",
  ui_story_1_4_B32_dialog_content = "Haha, não esquenta! Eu também tenho umas manias esquisitas!",
  ui_story_1_4_B27_dialog_content = "Vamos! Fiquem atentos! Vamos encontrar a saída antes que os Eclipsitas se agrupem!",
  ui_story_1_4_B28_dialog_content = "Navegador, fique pronto para nos auxiliar na batalha a qualquer momento!",
  ui_story_1_8_1_dialog_content = "Os inimigos são muito numerosos... Deveríamos sair logo daqui.",
  ui_story_1_8_B37_dialog_content = "Está tudo destruído. Tantos anos de faxina jogados fora.",
  ui_story_1_8_2_dialog_content = "Sinto muito, PlayerName. Se não tivéssemos quebrado tudo...",
  ui_story_1_8_3_dialog_content = "Então eu não teria uma chance de partir. Não se culpem. A culpa é dessas criaturas que se arrastam para fora das sombras.",
  ui_story_1_8_B29_dialog_content = "Não se preocupe, espere só até resgatarmos Soroz... Vou pedir um conserto completo em Illumina!",
  ui_story_1_8_B30_dialog_content = "Também posso elaborar pessoalmente um projeto de modificação pra você!",
  ui_story_1_8_B31_dialog_content = "Alguma melhoria em mente? Que tal uma cozinha aberta? Vai poder cozinhar caldo de polvo cremoso quando quiser.",
  ui_story_1_8_B32_dialog_content = "Não sei cozinhar. Soroz é quem cuida disso...",
  ui_story_1_8_B33_dialog_content = "Ah, sim. E que tal uma banheira grandona? Depois de um dia de trabalho duro, você pode tomar um banho quente...",
  ui_story_1_8_B34_dialog_content = "Não. Não preciso de nada assim no momento...",
  ui_story_1_8_B35_dialog_content = "Talvez um quarto de desenho mecânico seja mais importante...",
  ui_story_1_8_B36_dialog_content = "Obrigado, Vice. Se estava tentando me animar, você conseguiu. Já me sinto melhor.",
  ui_story_1_8_4_dialog_content = "Hã? Ah... desculpe...",
  ui_story_1_8_B38_dialog_content = "É que você parecia meio pra baixo, então quis quebrar o gelo com algo que talvez pudesse te interessar...",
  ui_story_1_8_5_dialog_content = "E o número de pessoas sob o seu comando está crescendo. Tive medo do seu nariz começar a sangrar de novo...",
  ui_story_1_8_6_dialog_content = "Suportar todos vocês não é nada comparado ao vínculo mental com a Colossus. É como tirar doce de...",
  ui_story_1_8_7_dialog_content = "<size=45>Problemas à frente! Recuem! Recuem agora!</size>",
  ui_story_1_8_8_dialog_content = "Isso é... ?",
  ui_story_1_8_9_dialog_content = "Droga, só uma coisa possui esse poder...",
  ui_story_1_8_10_dialog_content = "<color=#FFB400>Kraken</color>!",
  ui_story_1_8_11_dialog_content = "<anim type=Shake><size=50>Ahhhhhh!</size></anim>",
  ui_story_1_8_12_dialog_content = "Não sabia que Eclipsitas poderiam ficar tão grandes! Eraveil também enfrentou monstros assim?",
  ui_story_1_8_13_dialog_content = "Cuidado, PlayerName! Encontre um lugar seguro e se proteja!",
  ui_story_1_8_14_dialog_content = "Não há lugar seguro! Enfrentar o Kraken é o único jeito de passar!",
  ui_story_1_8_15_option_content = "Então vamos derrotar esse monstro de uma vez!",
  ui_story_1_8_16_option_content = "Eu ajudarei dos fundos!",
  ui_story_1_8_17_dialog_content = "É assim que se fala! Vamos!",
  ui_story_1_8_A2_dialog_content = "Ao seu comando, Navegador!",
  ui_story_1_8_18_dialog_content = "Iniciando vínculo mental! Preparem-se!",
  ui_story_1_8_19_dialog_content = "Pode deixar! Vamos!",
  ui_story_1_8_20_dialog_content = "<anim type=Shake><size=50>Ahhhhhh!</size></anim>",
  ui_story_1_8_21_dialog_content = "Cale-se e volte para o seu lugar!",
  ui_story_1_8_B1_dialog_content = "Gaa, gaa...",
  ui_story_1_8_B2_dialog_content = "Ele está tentando... falar?",
  ui_story_1_8_B3_option_content = "Dê o golpe final, Vice",
  ui_story_1_8_B4_option_content = "Aumento de Força!",
  ui_story_1_8_B6_dialog_content = "Torrente Rápida...",
  ui_story_1_8_B7_dialog_content = "Não importa o que essa criatura está falando, não quero nem tentar entender...",
  ui_story_1_8_B8_dialog_content = "Que fedor!!",
  ui_story_1_8_B9_dialog_content = "Esse é o cheiro de <color=#FFB400>Eclipsium</color>. Todos os Eclipsitas dependem dessa energia.",
  ui_story_1_8_B10_dialog_content = "O cheiro deixa qualquer um enojado.",
  ui_story_1_8_B11_dialog_content = "Gaa, gaa...",
  ui_story_1_8_B12_dialog_content = "A língua dos Eclipsitas é incompreensível...",
  ui_story_1_8_B13_dialog_content = "Nunca tentei me comunicar telepaticamente com outras criaturas antes. Não sei se consigo...",
  ui_story_1_8_B14_dialog_content = "<color=#FFB400>Celes</color>... <color=#FFB400>tita</color>?",
  ui_story_1_8_B15_dialog_content = "...?",
  ui_story_1_8_B16_dialog_content = "Uaaarrgh...",
  ui_story_1_8_B17_dialog_content = "Morreu...? Pena que não consegui informações novas, mas ele tinha emoções intensas.",
  ui_story_1_8_B18_dialog_content = "Não parecia temer a morte... Estava... surpreso? Por quê?",
  ui_story_1_8_22_dialog_content = "Nós... acabamos de derrotar um Eclipsita de alto nível...",
  ui_story_1_8_23_dialog_content = "Ficamos mais poderosos de novo sem perceber?",
  ui_story_1_8_24_dialog_content = "Se toca, isso foi coisa do PlayerName. Caso contrário, você nem saberia por onde começar.",
  ui_story_1_8_25_dialog_content = "PlayerName realmente é incrível.",
  ui_story_1_8_A3_dialog_content = "Falando nisso, eu ouvi alguns veteranos conversando.",
  ui_story_1_8_26_dialog_content = "Contam as lendas que onde quer que um Celestita apareça, a vitória é garantida. Vejo agora que isso não é um exagero.",
  ui_story_1_8_27_dialog_content = "A saída é mais à frente. Vamos embora daqui!",
  ui_story_1_8_28_dialog_content = "Como você está, PlayerName?",
  ui_story_1_8_B19_dialog_content = "Estou bem. Além do cansaço... há algo mais que eu deveria saber?",
  ui_story_1_8_B20_dialog_content = "Como assim?",
  ui_story_1_8_B21_dialog_content = "Estive na Colossus todo esse tempo. Quando se trata de explorar o mundo exterior...",
  ui_story_1_8_B22_dialog_content = "Vou precisar prender a respiração?",
  ui_story_1_8_B23_dialog_content = "O ar lá fora é tóxico pra mim?",
  ui_story_1_8_B24_dialog_content = "Vou precisar fechar os olhos até me acostumar com a luz do sol?",
  ui_story_1_8_B25_dialog_content = "Pensando bem, é melhor eu cobrir o rosto...",
  ui_story_1_8_B26_dialog_content = "Estou começando a entender o que esse Celestita esteve pensando durante os últimos 17 anos.",
  ui_story_1_8_B27_dialog_content = "Vai com calma. Apenas me acompanhe. O mundo lá fora não é tão assustador quanto você pensa.",
  ui_story_1_8_B28_dialog_content = "Venha, me dê sua mão.",
  ui_story_1_8_29_dialog_content = "<color=#FFB400>Um novo mundo</color>...",
  ui_story_1_8_30_dialog_content = "?!",
  ui_story_1_8_31_dialog_content = "Temos problemas, Vice.",
  ui_story_1_8_32_dialog_content = "O <color=#FFB400>exército Eclipsita</color>? Aqui? Mas como?",
  ui_story_1_8_33_dialog_content = "Recuar! Selem a entrada!",
  ui_story_1_8_34_dialog_content = "Eles não estavam lá antes... Vou fortificar a parede!",
  ui_story_1_8_A4_dialog_content = "Mas essa é a nossa saída, Tenente Vice!",
  ui_story_1_8_36_dialog_content = "Por que há tantos Eclipsitas? Estamos longe da linha de frente!",
  ui_story_1_8_37_dialog_content = "Calma, Tenente Vice. Parece que eles cruzaram a linha de frente.",
  ui_story_1_8_38_dialog_content = "Mas como eles conseguiram passar pela barreira de Illumina?",
  ui_story_1_8_39_dialog_content = "Talvez algum tipo de veículo voador os tenha transportado...",
  ui_story_1_8_40_dialog_content = "O que seria capaz de carregar tantos Eclipsitas de uma vez? Outra Colossus? Qual a probabilidade?",
  ui_story_1_8_41_dialog_content = "Talvez eu esteja pensando demais. Só nos resta uma opção.",
  ui_story_1_8_42_dialog_content = "<color=#FFB400>Ligar a Colossus</color>.",
  ui_story_1_8_44_dialog_content = "Mas você nunca conseguiu fazer isso...",
  ui_story_1_8_45_dialog_content = "Temos uma alternativa? Tentar de novo é tudo o que podemos fazer.",
  ui_story_1_8_46_dialog_content = "Se eu não consigo ligar a Colossus como um Celestita...",
  ui_story_1_8_47_dialog_content = "Mas você desmaiou da última vez. Seu corpo vai aguentar?",
  ui_story_1_8_48_dialog_content = "Sua cabeça não vai explodir, vai?",
  ui_story_1_8_49_dialog_content = "Agradeço sua preocupação, mas preciso tentar!",
  ui_story_1_8_50_dialog_content = "...",
  ui_story_1_8_51_dialog_content = "A julgar pela sua cara, Vice, você está pensando em...",
  ui_story_1_8_52_dialog_content = "Sim. Teoricamente, eu poderia ajudar. Teoricamente.",
  ui_story_1_8_53_dialog_content = "Do que você está falando?",
  ui_story_1_8_54_dialog_content = "Certo, tudo pronto! Vamos improvisar se tivermos problemas. Não há nada que não possamos enfrentar!",
  ui_story_1_8_55_dialog_content = "Você sempre tentou sozinho antes. Desta vez, talvez funcione com a gente ao seu lado!",
  ui_story_1_8_56_dialog_content = "Você está mais confiante do que eu?",
  ui_story_1_8_57_dialog_content = "Mas é claro. Sou uma otimista incorrigível, PlayerName.",
  ui_story_1_8_59_dialog_content = "Eu acho que obstáculos existem apenas para nos testar, e você não precisa mais enfrentar tudo sozinho!",
  ui_story_1_8_60_dialog_content = "Muito bem. Vamos para a Ponte!",
  ui_story_1_8_61_dialog_content = "PlayerName...",
  ui_story_1_8_62_dialog_content = "Vou ligar você desta vez, Soroz!",
  ui_story_1_9_1_dialog_content = "<color=#e8d9bb>Controle Primário... normal. Ligando...</color>",
  ui_story_1_9_2_dialog_content = "<color=#e8d9bb>Módulos biológicos... anormais e quase exauridos.</color>",
  ui_story_1_9_3_dialog_content = "<color=#e8d9bb>Suporte de vida... em desligamento.</color>",
  ui_story_1_9_4_dialog_content = "<color=#e8d9bb>Gerador... normal. Tentando iniciar...</color>",
  ui_story_1_9_5_dialog_content = "<color=#e8d9bb>10%... 23%...</color>",
  ui_story_1_9_6_dialog_content = "<color=#e8d9bb>76%... 85%...</color>",
  ui_story_1_9_7_dialog_content = "<color=#e8d9bb>Falha ao iniciar. Número de Falhas: 3.922.</color>",
  ui_story_1_9_8_dialog_content = "Ainda não está funcionando.",
  ui_story_1_9_10_dialog_content = "Por quê? O que está dando errado? Qual o problema?",
  ui_story_1_9_11_dialog_content = "Ugh, estou quase no limite de novo...?",
  ui_story_1_9_12_dialog_content = "Hu-hu... Qual o problema com o PlayerName?",
  ui_story_1_9_13_dialog_content = "Se tem certeza, Vice, agora é a hora.",
  ui_story_1_9_14_dialog_content = "Aquela coisa que parece um piano é o painel de controle da Colossus, certo?",
  ui_story_1_9_15_dialog_content = "Deixe-me ajudar você e ligar a Colossus, Navegador.",
  ui_story_1_9_16_dialog_content = "Me ajudar? Você é uma Aurorian, Vice. Não possui habilidades psíquicas.",
  ui_story_1_9_17_dialog_content = "Mas posso te dar forças. Eu... posso ajudar.",
  ui_story_1_9_18_dialog_content = "...?",
  ui_story_1_9_19_dialog_content = "Acredite em mim, PlayerName. Você e eu... não somos tão diferentes.",
  ui_story_1_9_21_dialog_content = "É uma longa história. Te conto da próxima vez que tiver uma chance!",
  ui_story_1_9_22_dialog_content = "Você sabe mesmo como usar o painel de controle?",
  ui_story_1_9_23_dialog_content = "Claro! Não esqueça, eu sei umas coisinhas sobre as Colossi!",
  ui_story_1_9_24_dialog_content = "E a Illumina tem tentado reconstruir as Colossi e recrutar Navegadores. É uma pena que...",
  ui_story_1_9_25_dialog_content = "Enfim, teremos uma chance de ligar se trabalharmos em equipe!",
  ui_story_1_9_26_dialog_content = "Mas se tivermos problemas, nossas cabeças podem... como você disse, explodir.",
  ui_story_1_9_27_dialog_content = "Essa é a nossa única chance. Temos que tentar, custe o que custar.",
  ui_story_1_9_28_dialog_content = "Certo, acho que não tem mais volta. Venha, sente-se comigo.",
  ui_story_1_9_29_dialog_content = "Deixe-me mostrar como \"tocar\" isso...",
  ui_story_1_9_30_dialog_content = "<color=#e8d9bb>Gerador... normal. Tentando iniciar...</color>",
  ui_story_1_9_B1_dialog_content = "Navegador, me diga o que devo fazer.",
  ui_story_1_9_B2_dialog_content = "É simples. Como tocar um piano.",
  ui_story_1_9_B3_dialog_content = "Mas não tem nenhuma partitura! Pode me indicar que teclas eu devo tocar?",
  ui_story_1_9_31_dialog_content = "<color=#e8d9bb>16%... 33%...</color>",
  ui_story_1_9_B4_dialog_content = "Sinto... a energia fluindo.",
  ui_story_1_9_B5_dialog_content = "Você está imbuindo Lúmina?",
  ui_story_1_9_B6_dialog_content = "Sim. É como uma conversa, mas não entendo a língua das Colossi.",
  ui_story_1_9_B7_dialog_content = "A língua está dentro das teclas do piano, Vice.",
  ui_story_1_9_32_dialog_content = "<color=#e8d9bb>89%... 97%...</color>",
  ui_story_1_9_B8_dialog_content = "Está funcionando... Isso é... inacreditável.",
  ui_story_1_9_B9_dialog_content = "Navegador, a canção está perto de acabar?",
  ui_story_1_9_B10_dialog_content = "Sim. Vamos concluir o comando de ativação, Vice.",
  ui_story_1_9_B11_dialog_content = "A última nota...",
  ui_story_1_9_33_dialog_content = "<color=#e8d9bb>Iniciado com 100% de sucesso.</color>",
  ui_story_1_9_34_dialog_content = "O que está acontecendo? Está tudo acendendo ao nosso redor!",
  ui_story_1_9_35_dialog_content = "<size=45>PlayerName!!</size>",
  ui_story_1_9_36_dialog_content = "A Ponte está brilhando?",
  ui_story_1_9_37_dialog_content = "<size=45>Nós... nós ligamos!</size>",
  ui_story_1_9_38_dialog_content = "...!",
  ui_story_1_9_40_dialog_content = "Conseguimos, PlayerName! Não acredito que conseguimos!",
  ui_story_1_9_41_dialog_content = "Então essa é a verdadeira aparência da Ponte! Tão iluminada!",
  ui_story_1_9_42_dialog_content = "Tão linda... Essa é a cor da Lúmina?",
  ui_story_1_9_A1_dialog_content = "Ou é aurora?",
  ui_story_1_9_43_dialog_content = "Impressionante... Nunca vi nada assim antes...",
  ui_story_1_9_44_dialog_content = "Esse é o céu de verdade? É difícil de olhar diretamente, mas é absolutamente deslumbrante...",
  ui_story_1_9_45_dialog_content = "Ainda não acredito que conseguimos! Nunca senti tanto poder na vida!",
  ui_story_1_9_46_dialog_content = "Você está de volta à sua antiga forma, Soroz!",
  ui_story_1_9_47_dialog_content = "Afirmativo! Sinto poder percorrendo cada fibra do meu corpo, mas ainda preciso de algum tempo antes de alçar voo.",
  ui_story_1_9_48_dialog_content = "Pode haver inimigos nas proximidades. Fiquem alertas!",
  ui_story_1_9_49_dialog_content = "Um pouco de aquecimento após tanto tempo sem se mexer?",
  ui_story_1_9_50_dialog_content = "Exato! Você parece que ainda tem bastante energia.",
  ui_story_1_9_51_dialog_content = "Tenha cuidado para não se esgotar, PlayerName!",
  ui_story_1_9_52_dialog_content = "Estou bem, Vice! Não se preocupe comigo!",
  ui_story_1_9_A2_dialog_content = "Sempre sonhei em sair daqui e voltar para o mundo.",
  ui_story_1_9_A3_dialog_content = "Mas nunca imaginei que seria dessa forma, ao lado de Aurorians!",
  ui_story_1_9_53_dialog_content = "Realizamos o que eu julgava ser impossível!",
  ui_story_1_9_54_dialog_content = "Também mal consigo acreditar nisso tudo.",
  ui_story_1_9_A4_dialog_content = "Uma Colossus perfeita, a Aurora ao meu alcance...",
  ui_story_1_9_55_dialog_content = "Sabe, até ontem eu era apenas uma soldado de Illumina que mal conseguia enfrentar um único Eclipsita.",
  ui_story_1_9_56_dialog_content = "Uma vertigem... Aquele sonho... De novo?",
  ui_story_1_9_58_dialog_content = "<color=#FFB400>Schummer</color>, por quê?!",
  ui_story_1_9_59_dialog_content = "Schummer, sua víbora! Como ousa trair seu próprio povo em troca de poder?!",
  ui_story_1_9_60_dialog_content = "Traidores e desertores são apenas rótulos criados pelos hipócritas e covardes.",
  ui_story_1_9_61_dialog_content = "Eraveil morreu, companheiros Celestitas. Realizarei seus supostos valores à minha maneira.",
  ui_story_1_9_62_dialog_content = "É inútil resistir. Não é nada pessoal, apenas a sobrevivência do mais apto...",
  ui_story_1_9_63_dialog_content = "Não!",
  ui_story_1_9_64_dialog_content = "... Aquele sonho novamente?",
  ui_story_1_9_65_dialog_content = "Já... chega. Soroz, o que isso quer dizer? O que significa?",
  ui_story_1_9_A5_dialog_content = "...",
  ui_story_1_9_66_option_content = "Não temos tempo para isso.",
  ui_story_1_9_A6_option_content = "Espere! Não são ilusões!",
  ui_story_1_9_67_option_content = "O que você está escondendo?",
  ui_story_1_9_B12_dialog_content = "Eu... não deixarei essas imagens vazias confundirem minha mente.",
  ui_story_1_9_B13_dialog_content = "Agora que consegui ativá-la, preciso estabilizar a Colossus... Vamos, concentre-se...",
  ui_story_1_9_B14_dialog_content = "Bom trabalho, PlayerName. As imagens que você viu... em breve serão explicadas.",
  ui_story_1_9_B15_dialog_content = "Também procuro respostas, e agora acho que estamos prontos para encontrá-las.",
  ui_story_1_9_B16_dialog_content = "Você está falando em enigmas novamente, Soroz. Não importa... Hoje, eu finalmente consegui.",
  ui_story_1_9_B17_dialog_content = "Sim. Continue em frente. Você é um Celestita, e tem um vasto céu azul para explorar.",
  ui_story_1_9_B18_dialog_content = "Parece tão real... Real demais para serem ilusões! DEVEM ser reais, não é?!",
  ui_story_1_9_B19_dialog_content = "Por existirem na sua consciência, elas devem estar enraizadas em resquícios da realidade. Isso é inegável.",
  ui_story_1_9_B20_dialog_content = "Pare de enrolar, Soroz... Quero uma resposta.",
  ui_story_1_9_B21_dialog_content = "Sinto muito... Também quero respondê-la, mas não posso.",
  ui_story_1_9_B22_dialog_content = "Eu não me lembro. Perdi tudo naquela noite. A única coisa de que me recordo é a ordem para mantê-lo vivo.",
  ui_story_1_9_B23_dialog_content = "...",
  ui_story_1_9_B24_dialog_content = "Realidade ou ilusão... O que importa agora é que sua jornada começou.",
  ui_story_1_9_B25_dialog_content = "E você está pronto para encontrar as respostas sozinho, não está?",
  ui_story_1_9_B26_dialog_content = "Responda, Soroz. O que você está escondendo? As imagens são reais ou não?!",
  ui_story_1_9_B27_dialog_content = "Não sei, PlayerName.",
  ui_story_1_9_B28_dialog_content = "Você deve estar brincando...",
  ui_story_1_9_B29_dialog_content = "Não estou mentindo. Todo o meu conhecimento sobre aquela época está perdido em um mar de memórias nebulosas.",
  ui_story_1_9_B30_dialog_content = "Sempre desejei dar a você uma resposta, e não falsas esperanças. Mas parece que nosso destino mudou.",
  ui_story_1_9_B31_dialog_content = "Com a ajuda dos seus novos amigos, agora você está pronto para encontrar as respostas , não está?",
  ui_story_1_9_B32_dialog_content = "Mas a resposta... O que ela poderia ser?",
  ui_story_1_9_B33_dialog_content = "Meu povo, Eraveil... e se a resposta for aquilo que eu mais temo...",
  ui_story_1_9_B34_dialog_content = "Qual o sentido de tudo isso?",
  ui_story_1_10_1_dialog_content = "<color=#e8d9bb>Em algum lugar</color>",
  ui_story_1_10_2_dialog_content = "(Falando em Eclipsiano) Aurorians alcançaram o interior de Soroz, a Colossus, e encontraram um descendente dos Celestitas.",
  ui_story_1_10_3_dialog_content = "(Falando em Eclipsiano) A unidade de Aurorians era poderosa demais para Kraken concluir a missão da Verdade...",
  ui_story_1_10_A1_dialog_content = "(Falando em Eclipsiano) Kraken carregará seu pecado e voltará para o Outro Lado, onde deverá implorar pelo perdão da Mãe.",
  ui_story_1_10_4_dialog_content = "(Falando em Eclipsiano) Vida longa ao <color=#FFB400>Eclipse</color>.",
  ui_story_1_10_5_dialog_content = "Essas foram as últimas palavras do Kraken? Ele foi derrotado pelo Celestita e pelos Aurorians?",
  ui_story_1_10_6_dialog_content = "Não esperava encontrar um sobrevivente do <color=#FFB400>passado</color>. Achei que eles haviam sido exterminados.",
  ui_story_1_10_A2_dialog_content = "Posso cuidar desse Celestita pessoalmente?",
  ui_story_1_10_7_dialog_content = "Você tem tanto prazer assim em matar seu próprio <color=#FFB400>povo</color>?",
  ui_story_1_10_8_dialog_content = "Meu povo? Há muito não ouço essa palavra.",
  ui_story_1_10_9_dialog_content = "Você tem incumbências mais importantes a cumprir. Não se preocupe com tais distrações irrelevantes.",
  ui_story_1_10_10_dialog_content = "O que buscamos não está naquela Colossus. Não desperdice nosso tempo. Você já não esperou o bastante?",
  ui_story_1_10_11_dialog_content = "Quanto ao Celestita, deixe-o para <color=#FFB400>Nozard</color>. Ele não está próximo de lá?",
  ui_story_1_10_12_dialog_content = "Vai deixá-lo terminar o que Kraken não conseguiu?",
  ui_story_1_10_13_dialog_content = "Nozard é mais que capaz de cuidar dos Aurorians. É melhor que ele os traga vivos.",
  ui_story_1_10_14_dialog_content = "Eu o informarei para se reunir conosco quando terminar. Assim, o plano não atrasará.",
  ui_story_1_10_A3_dialog_content = "Ao contrário de você, ele sabe acatar ordens. Você deveria aprender.",
  ui_story_1_10_15_dialog_content = "Comparado ao plano, um Celestita ignorante não merece atenção.",
  ui_story_1_10_16_dialog_content = "Mas, se me subestimar novamente, posso quebrar seu pescoço.",
  ui_story_1_10_17_dialog_content = "Ha ha ha, você é hilária, <color=#FFB400>Schummer</color>.",
  ui_story_1_10_18_dialog_content = "Só levarei você até aqui, Nozard. Sabe quais serão as consequências do seu fracasso!",
  ui_story_1_10_19_dialog_content = "Sim. Sou Nozard, o Destemido...",
  ui_story_1_10_21_dialog_content = "O alvo está à frente. Que audácia! A Colossus que escapou se revelou em nosso território.",
  ui_story_1_10_22_dialog_content = "Não a permita decolar!",
  ui_story_1_10_23_dialog_content = "E não deixe pedra sobre pedra até encontrar o Celestita para nosso mestre!",
  ui_story_1_10_24_dialog_content = "<size=45>Em nome da Mãe, ataque!</size>",
  ui_story_1_10_25_dialog_content = "Estão enviando tantos inimigos assim contra nós?",
  ui_story_1_10_26_dialog_content = "Nós nos revelamos quando ativamos a Colossus. É por isso que há tantos Eclipsitas à nossa volta.",
  ui_story_1_10_27_dialog_content = "É inevitável. E aí, Soroz precisa de mais tempo para se preparar?",
  ui_story_1_10_B1_dialog_content = "...",
  ui_story_1_10_B2_dialog_content = "PlayerName?",
  ui_story_1_10_B3_dialog_content = "Hã? Desculpe, eu... estava pensando em outra coisa.",
  ui_story_1_10_B4_dialog_content = "... Eu estava perguntando se ainda vai levar muito tempo para Soroz se preparar.",
  ui_story_1_10_28_dialog_content = "Infelizmente, sim. Vai demorar um pouco para Soroz se mover, mas estaremos salvos assim que ele levantar voo.",
  ui_story_1_10_30_dialog_content = "Me dê mais tempo, PlayerName.",
  ui_story_1_10_31_dialog_content = "Mal posso esperar para sair daqui com vocês e ver o céu de um novo mundo!",
  ui_story_1_10_32_dialog_content = "Precisamos defender Soroz até que ele possa decolar!",
  ui_story_1_10_33_dialog_content = "Muito bem. Vamos nos separar e proteger todas as passagens!",
  ui_story_1_10_34_dialog_content = "Fique na Ponte, PlayerName.",
  ui_story_1_10_35_dialog_content = "Preparem-se, pessoal! Hora de entrar na batalha!",
  ui_story_1_10_A4_dialog_content = "Aprontem suas armas e ganhem mais tempo para Soroz.",
  ui_story_1_10_36_dialog_content = "Splendor Illumina!",
  ui_story_1_10_37_dialog_content = "Splendor Illumina!",
  ui_story_1_10_38_dialog_content = "Splendor o quê?",
  ui_story_1_14_1_dialog_content = "(Falando em Eclipsiano) A Colossus está prestes a decolar! Destrua ela e os Aurorians imediatamente!",
  ui_story_1_14_2_dialog_content = "(Falando em Eclipsiano) Nos infiltramos em várias áreas da Colossus, mas encontramos resistência perto da Ponte. Nossas forças sofreram baixas significativas.",
  ui_story_1_14_3_dialog_content = "(Falando em Eclipsiano) E daí? Nós tememos a morte?",
  ui_story_1_14_4_dialog_content = "(Falando em Eclipsiano) Nunca!",
  ui_story_1_14_5_dialog_content = "(Falando em Eclipsiano) Então afie suas garras e ataque!",
  ui_story_1_14_A1_dialog_content = "(Falando em Eclipsiano) Se morrer, leve com você o máximo que puder!",
  ui_story_1_14_6_dialog_content = "(Falando em Eclipsiano) Leve-me até lá. Testarei a força desses Aurorians pessoalmente!",
  ui_story_1_14_7_dialog_content = "<color=#e8d9bb>(Dentro da Colossus)</color>",
  ui_story_1_14_8_dialog_content = "O próximo ataque chegará logo. Descansem, todos vocês. Contem a munição e me informem das baixas.",
  ui_story_1_14_9_dialog_content = "Restam 11 disparos. Perdemos 6 combatentes, 4 estão feridos, 2...",
  ui_story_1_14_10_dialog_content = "Tá, já entendi.",
  ui_story_1_14_11_dialog_content = "Deveríamos recuar, Capitão...",
  ui_story_1_14_12_dialog_content = "Não podemos! Vice e seu esquadrão estão protegendo a área principal. Precisamos deter os Eclipsitas nas áreas externas!",
  ui_story_1_14_13_dialog_content = "Estamos todos na mesma luta! Então pare de pensar nisso e vá para sua posição!",
  ui_story_1_14_14_dialog_content = "Coragem! Empunhem suas espadas se estiverem sem munição!",
  ui_story_1_15_1_dialog_content = "Você aí, nem pense em fugir!",
  ui_story_1_15_2_dialog_content = "Ótimo! Isso deve limpar a Ponte!",
  ui_story_1_15_3_dialog_content = "Você está nos coordenando cada vez melhor, PlayerName!",
  ui_story_1_15_4_dialog_content = "Minha mente e habilidades já ficaram mais afiadas hoje.",
  ui_story_1_15_5_dialog_content = "Como será que está a luta nos outros lugares?",
  ui_story_1_15_6_dialog_content = "De quanto tempo você ainda precisa, Soroz?",
  ui_story_1_15_7_dialog_content = "O gerador está iniciando. Segure firme. <size=45>Vamos para o céu!</size>",
  ui_story_1_15_8_dialog_content = "Estamos voando?",
  ui_story_1_15_9_dialog_content = "Caramba, eu quase caí! Está tão alto! Estamos voando?",
  ui_story_1_15_10_dialog_content = "Segurem em alguma coisa, pessoal!",
  ui_story_1_15_11_dialog_content = "Isso é o meu cabelo, Vice!",
  ui_story_1_15_A1_dialog_content = "Ah, o céu! Faz tanto tempo... ainda me lembro da última vez, naquela maldita noite...",
  ui_story_1_15_A2_dialog_content = "Desejo continuar acelerando, PlayerName!",
  ui_story_1_15_A3_dialog_content = "Só se for agora, Soroz! Pise fundo!",
  ui_story_1_15_12_dialog_content = "Vamos voar a toda velocidade! Até já derrubamos os Eclipsitas!",
  ui_story_1_15_13_dialog_content = "Com prazer! Vamos voar pelos céus mais uma vez!",
  ui_story_1_15_14_dialog_content = "O que é essa vibração, Vice?",
  ui_story_1_15_15_dialog_content = "Eu ia te dizer agora! Estamos no ar!",
  ui_story_1_15_16_dialog_content = "Sério? Isso é ótimo! Estava começando a me preocupar... talvez seja tarde demais...",
  ui_story_1_15_17_dialog_content = "Tarde demais? O que houve? Vocês estão bem?",
  ui_story_1_15_18_dialog_content = "Um gigante invadiu o local e não conseguimos detê-lo. Perdemos tantas pessoas...",
  ui_story_1_15_19_dialog_content = "Ele está indo direto para a Ponte. É definitivamente um Eclipsita de alto nível... Sinto muito...",
  ui_story_1_15_20_dialog_content = "Um inimigo mais poderoso? Fiquem atentos, isso ainda não acabou!",
  ui_story_1_15_21_dialog_content = "Brr... Por que a temperatura caiu de repente? Que frio...",
  ui_story_1_15_22_dialog_content = "Não é a temperatura, Dove. É a sensação do Fluxo Escuro... O inimigo está aqui.",
  ui_story_1_15_23_dialog_content = "<color=#e8d9bb>Um frio sinistro e repentino preenche o ar...</color>",
  ui_story_1_15_25_dialog_content = "Vocês, palermas, conseguiram decolar com esse caixão. Não importa, hora de morrer!",
  ui_story_1_15_26_dialog_content = "Outro Eclipsita de alto nível?",
  ui_story_1_15_27_dialog_content = "Eu tenho um nome, Aurorian. Pode me chamar de <color=#FFB400>Nozard</color>. Ele me foi dado pela própria Mãe.",
  ui_story_1_15_28_dialog_content = "Lembre-se do meu nome, pois ele guiará você para a Verdade no Outro Lado!",
  ui_story_1_15_29_dialog_content = "Esse Eclipsita sabe falar? O que ele quer dizer com \"Mãe\" e \"Verdade\"?",
  ui_story_1_15_30_dialog_content = "Não ligue, PlayerName! Poucos Eclipsitas falam Universês, e esse parece diferente!",
  ui_story_1_15_31_dialog_content = "Tsc! Aprendemos Universês para elucidar os Aurorians, mas foi em vão. Pestes sempre serão pestes...",
  ui_story_1_15_32_dialog_content = "Já mostrei respeito suficiente aos que estão à beira da morte. Agora...",
  ui_story_1_15_33_dialog_content = "Chegou a sua hora.",
  ui_story_1_15_34_option_content = "Você deve estar falando da sua!",
  ui_story_1_15_35_option_content = "Preparem-se para lutar!",
  ui_story_1_15_36_dialog_content = "Como ousa me ferir! Basta!",
  ui_story_1_15_37_dialog_content = "Eu planejava poupar você, mas é difícil subjugar uma peste sem matá-la!",
  ui_story_1_15_38_dialog_content = "Você me deu uma tarefa difícil, <color=#FFB400>Mestra Schummer</color>.",
  ui_story_1_15_39_dialog_content = "<color=#FFB400>Schummer</color>? Esse é o nome naquele sonho! Onde você o ouviu, e quem é ela?",
  ui_story_1_15_40_dialog_content = "Vejo que você sabe alguma coisa sobre o que aconteceu, Celestita... Mas e daí?",
  ui_story_1_15_B1_dialog_content = "Todo o seu povo foi morto por nossas mãos. Deseja mesmo viver uma existência solitária?",
  ui_story_1_15_B2_dialog_content = "O que... você disse?",
  ui_story_1_15_B3_dialog_content = "Que pergunta inusitada. Você me ouviu perfeitamente.",
  ui_story_1_15_B4_dialog_content = "Seu povo <color=#FFB400>está morto</color>.",
  ui_story_1_15_B5_dialog_content = "Eraveil não existe mais.",
  ui_story_1_15_B6_dialog_content = "Um mar de fogo e gritos desesperados. Seus corpos foram esmagados, um por um... e então descartados.",
  ui_story_1_15_B7_dialog_content = "Não... não pode ser.",
  ui_story_1_15_B8_dialog_content = "Impossível...",
  ui_story_1_15_B9_dialog_content = "Chega, Eclipsita! O que você sabe?!",
  ui_story_1_15_B10_dialog_content = "Eu estava lá. <color=#FFB400>Todos</color> nós estávamos... Como poderíamos perder um evento tão grandioso?",
  ui_story_1_15_B11_dialog_content = "Assim como um dia romperemos as defesas dos Aurorians e presentearemos vocês com a mesma aniquilação.",
  ui_story_1_15_41_dialog_content = "PlayerName, não acredite nesse Eclipsita!",
  ui_story_1_15_42_dialog_content = "Não importa se você acredita ou não. Todos morrerão da mesma forma.",
  ui_story_1_15_44_dialog_content = "Você nunca terá sucesso!",
  ui_story_1_15_46_dialog_content = "Imbecil! Você poderia ter sobrevivido, mas escolheu a morte!",
  ui_story_1_15_47_dialog_content = "Ugh!",
  ui_story_1_15_48_dialog_content = "Então era esse o seu plano? Atacar cegamente para cair aos meus pés?",
  ui_story_1_15_49_dialog_content = "Sim, além de plantar uma <color=#FFB400>bomba</color>, seu idiota!",
  ui_story_1_15_50_dialog_content = "Você...!",
  ui_story_1_15_53_dialog_content = "<size=45>Te vejo no inferno, otário.</size>",
  ui_story_1_15_54_dialog_content = "PlayerName! Há uma ruptura perto de você! Tenha cuidado!",
  ui_story_1_15_55_dialog_content = "A pressão! Não vou aguentar por muito tempo!",
  ui_story_1_15_56_dialog_content = "Espere...!",
  ui_story_1_15_B13_dialog_content = "Capitão!",
  ui_story_1_15_B14_dialog_content = "Não se mova! Segure minha mão!",
  ui_story_1_15_B15_dialog_content = "Por que tinha que terminar assim? Estávamos tão perto!",
  ui_story_1_15_57_dialog_content = "Uma explosão? Não me diga que aquele Aurorian...?",
  ui_story_1_15_A4_dialog_content = "Aquelas cinzas... será que...?",
  ui_story_1_15_58_dialog_content = "Acalme-se, PlayerName! Sua mente está divagando...",
  ui_story_1_15_A5_dialog_content = "E na minha memória... Os corpos do meu povo...",
  ui_story_1_15_A6_dialog_content = "Todos mortos... <color=#FFB400>Estão todos mortos</color>? E fora de Eraveil, além do continente? Sou mesmo o <color=#FFB400>último Celestita</color>?",
  ui_story_1_15_A7_dialog_content = "Sua frequência cardíaca está aumentando! Não se esforce demais novamente!",
  ui_story_1_15_B12_dialog_content = "Não... não dessa maneira. Não deveria ser dessa maneira. Mal posso...",
  ui_story_1_15_A8_dialog_content = "<size=45>Pare de me confundir!</size>",
  ui_story_1_15_59_dialog_content = "A Colossus está acelerando! Não vou aguentar mais...",
  ui_story_1_15_60_dialog_content = "O que você fez, Celestita? Estou escorregando...",
  ui_story_1_15_61_dialog_content = "<size=45>Não pode ser...</size>",
  ui_story_1_15_62_dialog_content = "<size=45>Navegador, abaixe-se!</size>",
  ui_story_1_15_63_dialog_content = "Ahhh!",
  ui_story_2_1_A1_dialog_content = "\"A Colossus finalmente decolou.\"",
  ui_story_2_1_A2_dialog_content = "\"Por um momento, achei que ficaria aqui para sempre...\"",
  ui_story_2_1_A3_dialog_content = "\"Mas assim que saí...\"",
  ui_story_2_1_A4_dialog_content = "\"Minha vida perdeu o sentido...\"",
  ui_story_2_1_A5_dialog_content = "\"Porque meu povo... os Celestitas, foram exterminados.\"",
  ui_story_2_1_1_dialog_content = "Está escrevendo um diário?",
  ui_story_2_1_3_dialog_content = "Bem, eu não tinha muito o que fazer quando estava aqui.",
  ui_story_2_1_4_dialog_content = "Ter um diário me ajudou a contar o tempo, mas isso não serviu para muita coisa.",
  ui_story_2_1_5_dialog_content = "É um ótimo hábito. Às vezes você é pega pesado consigo mesmo, PlayerName.",
  ui_story_2_1_6_dialog_content = "Como está a situação?",
  ui_story_2_1_B26_dialog_content = "Estamos fora de perigo por enquanto. Quase todos os feridos foram encaminhados para a enfermaria.",
  ui_story_2_1_B27_dialog_content = "O soldado que... se sacrificou...",
  ui_story_2_1_B28_dialog_content = "...",
  ui_story_2_1_B29_dialog_content = "Não temos como recuperar o corpo, mas vou reunir seus pertences e fazer um memorial.",
  ui_story_2_1_B30_dialog_content = "...",
  ui_story_2_1_B31_dialog_content = "... Aquela foi a primeira vez que você viu alguém morrer?",
  ui_story_2_1_B32_dialog_content = "Não.",
  ui_story_2_1_B33_dialog_content = "Não importa quantas vezes aconteça, eu nunca vou me acostumar.",
  ui_story_2_1_B34_dialog_content = "E a família dele?",
  ui_story_2_1_B35_dialog_content = "Não se preocupe, a Federação Illumina cuidará bem deles.",
  ui_story_2_1_B37_dialog_content = "Nos lembraremos de todos os heróis que se sacrificaram pela Illumina.",
  ui_story_2_1_B38_dialog_content = "Sinto muito, PlayerName.",
  ui_story_2_1_B39_dialog_content = "Pelo quê?",
  ui_story_2_1_B40_dialog_content = "Apenas... sinto muito, de todo o coração, pelo que aconteceu hoje.",
  ui_story_2_1_B41_dialog_content = "Mas ainda estamos vivos, e a única coisa que podemos fazer é não deixar que o sacrifício dele tenha sido em vão.",
  ui_story_2_1_F1_dialog_content = "...",
  ui_story_2_1_7_dialog_content = "O que você vai fazer agora?",
  ui_story_2_1_8_dialog_content = "... Não sei.",
  ui_story_2_1_9_dialog_content = "Que tal vir para Illumina comigo?",
  ui_story_2_1_10_dialog_content = "Você ouviu o que Nozard disse?",
  ui_story_2_1_A8_dialog_content = "Ouvi. Mas essa é só uma parte da história.",
  ui_story_2_1_11_dialog_content = "Meu povo está morto. Eraveil não existe mais.",
  ui_story_2_1_13_dialog_content = "...",
  ui_story_2_1_A9_dialog_content = "Você ainda tem um lar e pessoas à sua espera, mas eu...",
  ui_story_2_1_14_dialog_content = "Não pense assim, PlayerName...",
  ui_story_2_1_15_dialog_content = "Tenho certeza de que existem mais sobreviventes como você!",
  ui_story_2_1_B1_dialog_content = "...",
  ui_story_2_1_B2_dialog_content = "E vou te ajudar a encontrá-los!",
  ui_story_2_1_B3_dialog_content = "Desculpe, Vice. Eu...",
  ui_story_2_1_B4_dialog_content = "Tudo bem. Eu entendo.",
  ui_story_2_1_B5_dialog_content = "Passei 17 anos no subsolo pensando em Eraveil todos os dias.",
  ui_story_2_1_B6_dialog_content = "Apenas para descobrir que... tudo estava perdido? Como é possível aceitar algo assim? Não posso!",
  ui_story_2_1_B7_dialog_content = "Então não aceite, PlayerName.",
  ui_story_2_1_B8_dialog_content = "Preciso saber exatamente o que aconteceu há 17 anos!",
  ui_story_2_1_B9_dialog_content = "Sim, vamos procurar a verdade por todo o continente!",
  ui_story_2_1_B10_dialog_content = "Mas até lá você precisa descansar. Volte para Illumina comigo.",
  ui_story_2_1_A10_option_content = "Tudo bem. Vou com você.",
  ui_story_2_1_A11_option_content = "Não. Devo seguir meu próprio caminho.",
  ui_story_2_1_A12_dialog_content = "Você tem razão, Vice.",
  ui_story_2_1_A13_dialog_content = "De todo modo, não tenho mais para onde ir.",
  ui_story_2_1_A14_dialog_content = "Anime-se. Confie em mim, você vai adorar Illumina!",
  ui_story_2_1_B11_dialog_content = "Você disse <color=#FFB400>Schummer</color>? Que nome estranho.",
  ui_story_2_1_B12_dialog_content = "Não consigo esquecer daquele rosto... acho que é tudo que posso fazer por enquanto.",
  ui_story_2_1_B13_dialog_content = "Primeiro, prometa-me que vai cuidar de você e da Colossus.",
  ui_story_2_1_B14_dialog_content = "Depois que você clarear a mente e colocar Soroz em ordem, eu o acompanharei pelo resto da sua aventura.",
  ui_story_2_1_A15_dialog_content = "Por quê?",
  ui_story_2_1_A16_dialog_content = "Bem, porque a Federação Illumina...",
  ui_story_2_1_A17_dialog_content = "Quero dizer, por que você deseja tanto me ajudar e ser minha amiga?",
  ui_story_2_1_A18_dialog_content = "Ainda preciso explicar? Você salvou minha vida, lembra?",
  ui_story_2_1_A19_dialog_content = "Além disso, suas habilidades são muito importantes para os Aurorians...",
  ui_story_2_1_A20_dialog_content = "É aquele programa de Navegadores de Colossus, não é?",
  ui_story_2_1_A21_dialog_content = "O nome é programa de Reestruturação da Colossus e Desenvolvimento de Navegadores!",
  ui_story_2_1_A22_dialog_content = "Na verdade, eu também... Hum, isso não importa agora!",
  ui_story_2_1_A23_dialog_content = "Mesmo que eu não saiba por que você está fazendo isso...",
  ui_story_2_1_F2_dialog_content = "Confio em você, Vice.",
  ui_story_2_1_A24_dialog_content = "Obrigada, PlayerName.",
  ui_story_2_1_A25_dialog_content = "Certo, vamos encontrar a Subcidade de Illumina mais próxima! Precisamos descansar e nos reagrupar!",
  ui_story_2_1_A26_dialog_content = "Eu tentei durante todos esses anos.",
  ui_story_2_1_A28_dialog_content = "Todos os dias, eu tentei iniciar a Colossus, apenas para desmaiar logo em seguida.",
  ui_story_2_1_B15_dialog_content = "Todos os dias, eu estudei o conhecimento armazenado em Soroz. Não sei se isso pode me ajudar agora.",
  ui_story_2_1_B16_dialog_content = "Todos os dias, eu sonhava em ver o mundo exterior e voltar para Eraveil.",
  ui_story_2_1_B17_dialog_content = "Eu sei que você se esforçou, PlayerName.",
  ui_story_2_1_B19_dialog_content = "Acredito que tenho meu próprio caminho a seguir.",
  ui_story_2_1_B20_dialog_content = "Mas para onde você vai?",
  ui_story_2_1_B21_dialog_content = "...",
  ui_story_2_1_B22_dialog_content = "Para casa. Para Eraveil.",
  ui_story_2_1_B23_dialog_content = "Quero encontrar <color=#FFB400>Schummer</color>.",
  ui_story_2_1_A29_dialog_content = "É muito perigoso fazer isso sozinho, PlayerName!",
  ui_story_2_1_A30_dialog_content = "Eu sei, mas preciso descobrir a verdade. Quero ir para casa.",
  ui_story_2_1_A31_dialog_content = "Você e Soroz acabaram de chegar à superfície e já passaram por maus bocados. Vocês deveriam descansar primeiro.",
  ui_story_2_1_A32_dialog_content = "Depois que estiverem recuperados, eu posso ajudar vocês a...",
  ui_story_2_1_A33_dialog_content = "Por que você me ajudaria?",
  ui_story_2_1_A34_dialog_content = "Ainda preciso explicar? Você salvou minha vida, lembra?",
  ui_story_2_1_A35_dialog_content = "Além disso... suas habilidades poderiam ser muito úteis para nós, Aurorians...",
  ui_story_2_1_A36_dialog_content = "...",
  ui_story_2_1_A37_dialog_content = "Podemos nos unir contra um inimigo comum, igual aos Celestitas e Aurorians do passado!",
  ui_story_2_1_A38_dialog_content = "Mas antes precisamos ir até a Subcidade de Illumina mais próxima para descansar e nos reagruparmos...",
  ui_story_2_1_19_dialog_content = "Ah! O que foi?",
  ui_story_2_1_20_dialog_content = "O que aconteceu, Soroz?!",
  ui_story_2_1_21_dialog_content = "O sistema de navegação está muito avariado e não pode ser reparado no momento.",
  ui_story_2_1_22_dialog_content = "São os efeitos de ter passado 17 anos sem a devida manutenção. Precisamos voltar para o solo.",
  ui_story_2_1_23_dialog_content = "Não poderei levar você adiante, PlayerName.",
  ui_story_2_1_24_dialog_content = "...",
  ui_story_2_1_25_dialog_content = "Não importa o que aconteça, proteja a si mesmo e aos seus companheiros!",
  ui_story_2_1_26_dialog_content = "Eu acredito em você... Você se tornará... mais forte...",
  ui_story_2_1_A43_dialog_content = "Soroz! Soroz!",
  ui_story_2_1_27_dialog_content = "PlayerName!",
  ui_story_2_1_28_dialog_content = "Prepare-se para o impacto!",
  ui_story_2_1_29_dialog_content = "Acabei de sentir uma onda intensa de Lúmina.",
  ui_story_2_1_30_dialog_content = "Mestra Schummer, ainda tenho tudo sob controle.",
  ui_story_2_1_A44_dialog_content = "Palavras ousadas para um fracassado arremessado dos céus. É melhor ter cuidado com promessas que não pode cumprir.",
  ui_story_2_1_A45_dialog_content = "...",
  ui_story_2_1_X1_dialog_content = "Admito que você é mais forte que Kraken. Mas se não pode executar suas ordens...",
  ui_story_2_1_X2_dialog_content = "Então você é inútil, Nozard.",
  ui_story_2_1_31_dialog_content = "A Colossus não irá protegê-los para sempre. Sua resistência é inútil.",
  ui_story_2_1_32_dialog_content = "Em breve, entregarei o resultado que você deseja.",
  ui_story_2_1_33_dialog_content = "Seja grato por ganhar uma segunda chance. Cuide disso antes que minha paciência se esgote.",
  ui_story_2_1_35_dialog_content = "Como desejar, Mestra.",
  ui_story_2_1_36_dialog_content = "(Falando em Eclipsiano) Colossus... caiu... nas florestas... a oeste...",
  ui_story_2_1_37_dialog_content = "(Falando em Eclipsiano) O Oeste. Convoque os <color=#FFB400>Umbrahulks</color>.",
  ui_story_2_1_38_dialog_content = "(Falando em Eclipsiano) Às suas ordens.",
  ui_story_2_1_39_dialog_content = "(Falando em Eclipsiano) Encontre-os e acabe com eles... Me juntarei a você em breve!",
  ui_story_2_1_40_dialog_content = "(Falando em Eclipsiano) Entendido! Eclipsitas, ao ataque!",
  ui_story_2_2_2_dialog_content = "Ai... Hã?",
  ui_story_2_2_3_dialog_content = "Vice, pode sair de cima de mim...",
  ui_story_2_2_A1_dialog_content = "Hã? Ah, foi mal... Tudo bem?",
  ui_story_2_2_A2_dialog_content = "Ainda estou vivo, pelo menos...",
  ui_story_2_2_4_dialog_content = "Já estamos cercados de Eclipsitas?! Tão rápido?",
  ui_story_2_2_5_dialog_content = "PlayerName, dê o comando!",
  ui_story_2_2_6_dialog_content = "<color=#e8d9bb>O barulho da queda atraiu muitos Eclipsitas.</color>",
  ui_story_2_3_1_dialog_content = "Qual a situação?",
  ui_story_2_3_2_dialog_content = "Detectamos Eclipsitas se aproximando, Tenente Vice, mas estamos sem suprimentos de batalha.",
  ui_story_2_3_3_dialog_content = "Onde fica a Subcidade mais próxima?",
  ui_story_2_3_A1_dialog_content = "A Subcidade 28 não está longe. Podemos nos abrigar lá.",
  ui_story_2_3_A2_dialog_content = "Às suas ordens, Tenente Vice!",
  ui_story_2_3_4_dialog_content = "Mova todas as forças para a Subcidade 28, rápido!",
  ui_story_2_3_6_dialog_content = "Vamos, PlayerName!",
  ui_story_2_3_7_dialog_content = "Não se preocupe comigo. Vá com eles.",
  ui_story_2_3_8_dialog_content = "PlayerName?!",
  ui_story_2_3_A3_dialog_content = "Você deveria ir antes que seja tarde demais.",
  ui_story_2_3_A4_dialog_content = "Você não vai com a gente?",
  ui_story_2_3_9_dialog_content = "Soroz está muito avariado. Não posso deixá-lo.",
  ui_story_2_3_10_dialog_content = "Sobrevivi 17 anos graças ao Soroz. Ele é a única \"família\" que me resta.",
  ui_story_2_3_A5_dialog_content = "...",
  ui_story_2_3_11_dialog_content = "Se tudo o que Nozard disse é verdade...",
  ui_story_2_3_12_dialog_content = "Não importa o que aconteça, nunca deixarei Soroz novamente.",
  ui_story_2_3_13_dialog_content = "Como vai enfrentar todos aqueles Eclipsitas sozinho?",
  ui_story_2_3_A6_dialog_content = "É a mim que eles querem, não é? Seria melhor para todo mundo se eu ficasse.",
  ui_story_2_3_14_dialog_content = "Você...!",
  ui_story_2_3_15_dialog_content = "Entendido. Leve todos para a Subcidade, soldado!",
  ui_story_2_3_A7_dialog_content = "E você, Tenente Vice...",
  ui_story_2_3_A8_dialog_content = "Pare de enrolar e vá logo!",
  ui_story_2_3_A9_dialog_content = "Sim!",
  ui_story_2_3_A10_dialog_content = "Você já me ajudou muito, Vice. Deveria ir com seus amigos.",
  ui_story_2_3_16_dialog_content = "Você também é meu amigo. Não posso te deixar aqui pra morrer!",
  ui_story_2_3_17_dialog_content = "Desse jeito, nós dois vamos morrer se você não for.",
  ui_story_2_3_18_dialog_content = "PlayerName...!",
  ui_story_2_3_19_dialog_content = "<anim type=Shake><size=45>*Rugindo*</size></anim>",
  ui_story_2_3_B3_dialog_content = "Vice!",
  ui_story_2_3_B4_dialog_content = "P-Para trás! Encontre um lugar seguro para se esconder!",
  ui_story_2_3_B5_dialog_content = "Eles já se agruparam...",
  ui_story_2_3_B6_option_content = "Estabelecer conexão mental",
  ui_story_2_3_B7_dialog_content = "Wooga...!",
  ui_story_2_3_B8_dialog_content = "Não vou te deixar para trás!",
  ui_story_2_3_B9_dialog_content = "Vice...",
  ui_story_2_3_B10_dialog_content = "Ahhh!",
  ui_story_2_3_22_dialog_content = "Ahhh...!",
  ui_story_2_3_A11_dialog_content = "É muito doloroso! Não consigo me concentrar...",
  ui_story_2_3_F1_dialog_content = "Aguente firme, PlayerName! Estou chegando!",
  ui_story_2_3_B11_dialog_content = "<anim type=Shake><size=45>*Rugindo*</size></anim>",
  ui_story_2_3_B12_dialog_content = "<color=#e8d9bb>Sem tempo para reagir, Vice foi cercada por inúmeros Eclipsitas...</color>",
  ui_story_2_3_B13_dialog_content = "Argh...",
  ui_story_2_3_B14_dialog_content = "Fuja! Esconda-se... Vamos...",
  ui_story_2_3_B15_dialog_content = "Vice?!",
  ui_story_2_3_24_option_content = "Estabelecer conexão mental",
  ui_story_2_3_25_dialog_content = "Não adianta, ela está inconsciente...",
  ui_story_2_3_26_dialog_content = "Lutar... preciso lutar... não posso ficar aqui parado...",
  ui_story_2_3_27_dialog_content = "<color=#e8d9bb>Os Eclipsitas passaram por Vice e cercaram você...</color>",
  ui_story_2_3_28_dialog_content = "Ei, ei, ei! Arriscar sua vida não vai resolver nada. Matar Eclipsitas é uma arte.",
  ui_story_2_3_29_dialog_content = "Vamos brincar!",
  ui_story_2_3_30_dialog_content = "<size=45>Movam-se! Vamos!</size>",
  ui_story_2_3_31_dialog_content = "Sim, chefe!",
  ui_story_2_3_32_dialog_content = "Cuidado com a explosão!",
  ui_story_2_3_33_dialog_content = "Hora da festa!",
  ui_story_2_3_34_dialog_content = "Sai da frente, você está no caminho!",
  ui_story_2_3_36_dialog_content = "Quem é você? O que quer?",
  ui_story_2_3_37_dialog_content = "Não é óbvio? Estamos aqui pra te roubar.",
  ui_story_2_3_38_dialog_content = "Salvamos sua vida, agora nos entregue seus pertences. Rápido!",
  ui_story_2_3_F2_dialog_content = "Hahahahaha!",
  ui_story_2_3_39_dialog_content = "Muito prazer, meu nome é <color=#FFB400>Sinsa</color>, líder da <color=#FFB400>Rediesel Wrench</color>.",
  ui_story_2_3_40_dialog_content = "Essa aqui, que gosta de fazer pose, é a <color=#FFB400>Regina</color>.",
  ui_story_2_3_41_dialog_content = "Aquela brincando com a bomba é <color=#FFB400>Joanie Boom</color>.",
  ui_story_2_3_42_dialog_content = "Elas são minhas fiéis companheiras.",
  ui_story_2_3_43_dialog_content = "Rediesel Wrench? Nos roubando...? O que está fazendo? Não se atreva a tocar na Colossus!",
  ui_story_2_3_44_dialog_content = "Quer dizer esse grandalhão aqui? Por que não podemos entrar? Acho que vou abrir um buraco nele!",
  ui_story_2_3_45_dialog_content = "Vamos nessa! Hora de carregar!",
  ui_story_2_3_46_dialog_content = "Urru! Manda ver, Joanie Boom!",
  ui_story_2_3_47_dialog_content = "Heh, uma Colossus! É meu dia de sorte!",
  ui_story_2_3_A12_dialog_content = "Desmontem tudo e levem pra casa!",
  ui_story_2_3_48_dialog_content = "Não posso deixar uma oportunidade dessa escapar!",
  ui_story_2_3_49_dialog_content = "Não destrua Soro... a Colossus! Tem uma pessoa no suporte de vida...",
  ui_story_2_3_50_dialog_content = "Minha amiga Vice está ferida, e precisa dele!",
  ui_story_2_3_51_dialog_content = "Parece que essa garota levou uma baita pancada.",
  ui_story_2_3_52_dialog_content = "Esse uniforme? É de Illumina?",
  ui_story_2_3_53_dialog_content = "Sabe, não nos damos tão bem assim com esses oficiais...",
  ui_story_2_3_54_dialog_content = "Além disso, a Colossus é nossa agora. Pra salvar a garota, você vai ter que nos dar algo em troca.",
  ui_story_2_3_55_dialog_content = "Pela sua aparência, você não tem nenhuma grana. Faz quanto tempo que você não lava esses trapos velhos?",
  ui_story_2_3_56_option_content = "Mas EU tenho grana. Muita grana!",
  ui_story_2_3_57_option_content = "Não se metam comigo, Aurorians!",
  ui_story_2_3_58_dialog_content = "Pra falar a verdade, a coisa mais valiosa é a Colossus. Você nunca viu uma antes, né?",
  ui_story_2_3_59_dialog_content = "Ha, vai sonhando! Mas comparada à que está na nossa base, essa tá bem intacta...",
  ui_story_2_3_60_dialog_content = "Exato. Se continuar a desmontá-la, ela não vai ter nenhum valor.",
  ui_story_2_3_61_dialog_content = "Tsc. Isso é um problema. Achei que poderia explodir tudo dessa vez. E agora, chefe?",
  ui_story_2_3_62_dialog_content = "...",
  ui_story_2_3_63_dialog_content = "Esse cara tem razão. Vamos esperar um pouco.",
  ui_story_2_3_64_dialog_content = "Certo! Parem tudo!",
  ui_story_2_3_65_dialog_content = "Ô, você. Vem cá.",
  ui_story_2_3_66_dialog_content = "Me diz, quem é você?",
  ui_story_2_3_67_dialog_content = "...",
  ui_story_2_3_68_dialog_content = "Posso adivinhar mesmo se não me disser. Somente pessoas de 17 anos atrás usariam esse tipo de roupa.",
  ui_story_2_3_69_dialog_content = "O fato de você ter conseguido sobreviver por aí com esse trambolho por tanto tempo é impressionante!",
  ui_story_2_3_70_dialog_content = "Sabe quem eu sou?",
  ui_story_2_3_71_dialog_content = "Não faz tanto tempo assim, <color=#FFB400>Celestita</color>. Tenho uma boa memória.",
  ui_story_2_3_72_dialog_content = "Você não sabe quem eu sou, ou o que vai acontecer se mexer comigo! Eu... não tenho medo de você!",
  ui_story_2_3_73_dialog_content = "...",
  ui_story_2_3_74_dialog_content = "Você bateu a cabeça ou coisa assim?",
  ui_story_2_3_75_dialog_content = "Nos ameaçando só porque você faz parte <color=#FFB400>de uma raça especial</color>?",
  ui_story_2_3_76_dialog_content = "Sério, somos ladrões perigosos.",
  ui_story_2_3_77_dialog_content = ".... Sabe quem eu sou?",
  ui_story_2_3_78_dialog_content = "Me poupe. As roupas, a Colossus, essa cara de tacho, qualquer um poderia adivinhar.",
  ui_story_2_3_79_dialog_content = "Você deve render uma bela grana...",
  ui_story_2_3_80_dialog_content = "M-me vender?! Por que me trata diferente, se também são Aurorians?",
  ui_story_2_3_81_dialog_content = "Não leve a mal, <color=#FFB400>Celestita</color>. Você não é nada para nós, bandidos.",
  ui_story_2_3_82_dialog_content = "Celestitas? Aqueles que foram exterminados pelos Eclipsitas?",
  ui_story_2_3_B1_dialog_content = "Exterminados...",
  ui_story_2_3_B2_dialog_content = "Então, ninguém mais sobreviveu ao ataque em Eraveil 17 anos atrás?",
  ui_story_2_3_83_dialog_content = "Você sabe de mais detalhes?",
  ui_story_2_3_84_dialog_content = "Foi mal, mas aconteceu muito de repente. Tudo acabou em uma única noite.",
  ui_story_2_3_85_dialog_content = "Eu era uma criança, então não poderia saber muito, né?",
  ui_story_2_3_89_dialog_content = "Certo, chega dessa baboseira! Não importa se é um Celestita ou uma Colossus, vocês nos pertencem agora!",
  ui_story_2_3_90_dialog_content = "Então, sobre a Vice...",
  ui_story_2_3_91_dialog_content = "Ela foi enviada ao <color=#FFB400>suporte de vida</color> para tratamento há um tempão! Somos ladrões, não assassinos!",
  ui_story_2_3_92_dialog_content = "Como você sabe tanto sobre a Colossus...",
  ui_story_2_3_93_dialog_content = "Vocês, Celestitas, não são os únicos que possuem Colossi. Nós, da Rediesel Wrench, temos nossa própria <color=#FFB400>Papa-Léguas</color>.",
  ui_story_2_3_94_dialog_content = "Vamos ver se alguém quer pagar o seu resgate, Celestita!",
  ui_story_2_4_1_dialog_content = "Chefe, tem um monte de Eclipsitas vindo em nossa direção.",
  ui_story_2_4_2_dialog_content = "Como vamos carregar a Colossus se eles continuarem vindo?",
  ui_story_2_4_3_dialog_content = "Aliás, PlayerName, você estava sendo perseguido por Eclipsitas antes de chegarmos, não estava?",
  ui_story_2_4_4_dialog_content = "Entendo...",
  ui_story_2_4_5_dialog_content = "Droga, mais problema.",
  ui_story_2_4_6_dialog_content = "Vamos lá, rapaziada! Hora de exterminar alguns insetos!",
  ui_story_2_4_7_dialog_content = "Que tal nos mostrar a lendária habilidade psíquica dos Celestitas?",
  ui_story_2_4_8_dialog_content = "Quer que eu guie vocês...?",
  ui_story_2_4_9_dialog_content = "Mas é claro, não dá pra deixar uma chance dessa passar! Mostra aí esse Rastro de Luz!",
  ui_story_2_4_10_dialog_content = "Inimigos se aproximando! Saquem suas armas! Não morram!",
  ui_story_2_8_1_dialog_content = "Manobras assim não podem ser apenas coincidência.",
  ui_story_2_8_2_dialog_content = "Desde quando os Eclipsitas ficaram tão espertos?",
  ui_story_2_8_3_dialog_content = "O que acha, Joanie?",
  ui_story_2_8_4_dialog_content = "Será que algum Eclipsita de alto nível está no comando?",
  ui_story_2_8_5_dialog_content = "Não venha jogar praga!",
  ui_story_2_8_7_dialog_content = "Eclipsita de alto nível...",
  ui_story_2_8_B1_dialog_content = "Quê? Já deu a hora?",
  ui_story_2_8_B2_dialog_content = "Chefe, finalmente você lembrou!",
  ui_story_2_8_B3_dialog_content = "Foi mal, lutar ao lado de um Celestita é tão alucinante que perdi a noção do tempo...",
  ui_story_2_8_B4_dialog_content = "Vamos dar uma pausa por enquanto! <color=#FFB400>Hora do rango</color>!",
  ui_story_2_8_B5_dialog_content = "<anim type=Shake><size=45>Aaaaaêêêêêê! É hora do rango!</size></anim>",
  ui_story_2_8_SS_dialog_content = "Imagem do Piquenique da Rediesel",
  ui_story_2_8_B6_dialog_content = "Ei, não empurra! Não sabe que precisa dar a vez ao seu chefe?",
  ui_story_2_8_B7_dialog_content = "Haha! Você primeiro! Mas deixe dois barris para mim!",
  ui_story_2_8_B8_dialog_content = "O que... exatamente você está fazendo?",
  ui_story_2_8_B9_dialog_content = "Comendo. Isso é estranho? Você nunca comeu antes?",
  ui_story_2_8_B10_dialog_content = "Quero dizer, vocês são uns selvagens...",
  ui_story_2_8_B11_dialog_content = "Essa é a única forma de sobreviver nesse mundo, PlayerName. Não subestime nossa perseverança.",
  ui_story_2_8_B12_dialog_content = "Nós comemos para viver, e vivemos para comer!",
  ui_story_2_8_B13_dialog_content = "Se continuar batendo papo com o Celestita, vamos comer toda a carne, Sinsa!",
  ui_story_2_8_B14_dialog_content = "Peguei dois <color=#FFB400>lagartos assados</color> pra você!",
  ui_story_2_8_B15_dialog_content = "Dê ao Celestita. Não tô com fome.",
  ui_story_2_8_B16_dialog_content = "Aqui!",
  ui_story_2_8_B17_dialog_content = "Eu... também não estou com fome...",
  ui_story_2_8_B18_dialog_content = "Por que essa tristeza toda?",
  ui_story_2_8_B19_dialog_content = "Não disse que é sua primeira vez no mundo exterior?",
  ui_story_2_8_B20_dialog_content = "Não quer comemorar?",
  ui_story_2_8_B21_dialog_content = "Por que não se solta mais?",
  ui_story_2_8_B22_dialog_content = "O mundo aqui fora não é tão bom quanto o subsolo?",
  ui_story_2_8_B23_dialog_content = "Hã?",
  ui_story_2_8_B24_dialog_content = "Não importa pelo que você passou. Você, a Colossus e aquela garota estão seguros agora, não é?",
  ui_story_2_8_B25_dialog_content = "Você não teria sobrevivido por tanto tempo se não tivesse nada a contribuir.",
  ui_story_2_8_B26_dialog_content = "Não é fácil viver nesse mundo, mas não seja tolo o bastante para achar que você foi o único que sofreu.",
  ui_story_2_8_B27_dialog_content = "Pra que preciso de um tolo? Deveria te matar logo e evitar mais dor de cabeça.",
  ui_story_2_8_B28_dialog_content = "Se me matar, aí sim você vai ter uma dor de cabeça. A Illumina não vai te deixar escapar dessa!",
  ui_story_2_8_B29_dialog_content = "Hahahahahaha!",
  ui_story_2_8_B30_dialog_content = "Qual a graça?",
  ui_story_2_8_B33_dialog_content = "Parece que você não é tão burro assim!",
  ui_story_2_8_8_dialog_content = "Encontrei o Celestita!",
  ui_story_2_8_9_dialog_content = "Um <color=#FFB400>Umbrahulk</color>?",
  ui_story_2_8_B34_dialog_content = "Os Eclipsitas! Eles vieram mesmo atrás de mim?",
  ui_story_2_8_B35_dialog_content = "Larguem a comida e entrem em formação! Hora de lutar!",
  ui_story_2_8_10_dialog_content = "Atacando no meio de uma refeição? Onde esse mundo vai parar?",
  ui_story_2_8_B36_dialog_content = "Acho que vou precisar te ensinar boas maneiras.",
  ui_story_2_8_11_dialog_content = "Foi mais difícil do que pensei...",
  ui_story_2_8_12_dialog_content = "Esse <color=#FFB400>trem</color>...",
  ui_story_2_8_13_dialog_content = "Não, <color=#FFB400>aquele cara</color> não...",
  ui_story_2_8_14_dialog_content = "Isso é vergonhoso, Sinsa.",
  ui_story_2_8_15_dialog_content = "Você está brincando de casinha com os Eclipsitas?",
  ui_story_2_8_16_dialog_content = "Sabia que era você. Não tenho roubado seus suprimentos ultimamente.",
  ui_story_2_8_17_dialog_content = "Estou aqui para levar minha companheira de volta a Illumina, mas cuido de você depois.",
  ui_story_2_8_18_dialog_content = "Ah, aquela garota?",
  ui_story_2_8_19_dialog_content = "Que coincidência! Eu estava pensando em mandar ela de volta mais cedo.",
  ui_story_2_8_20_dialog_content = "Não só ela, mas a Colossus também. Ela pertence à <color=#FFB400>Federação Illumina</color>.",
  ui_story_2_8_21_dialog_content = "Não força a barra, ô do cabelo branco!",
  ui_story_2_8_22_dialog_content = "Vou explodir seu carro.",
  ui_story_2_8_23_dialog_content = "Calma, Bing Bang Boom.",
  ui_story_2_8_24_dialog_content = "Esse cara é muito mais forte que aquele Umbrahulk.",
  ui_story_2_8_25_dialog_content = "É apenas uma Colossus. Já que não vamos conseguir desmontá-la ou vendê-la, não importa pra gente.",
  ui_story_2_8_26_dialog_content = "Afe! Você teve sorte!",
  ui_story_2_8_B37_dialog_content = "Charon, espero que saiba com o que está lidando.",
  ui_story_2_8_B38_dialog_content = "PlayerName, você é mais interessante do que imaginei.",
  ui_story_2_8_B39_dialog_content = "Hã?",
  ui_story_2_8_B40_dialog_content = "Que pena! Não se encontra um tesouro raro assim todos os dias.",
  ui_story_2_8_B41_dialog_content = "PlayerName, você deveria relaxar um pouco...",
  ui_story_2_8_B42_dialog_content = "Mas você ainda brilha com a aura da luz.",
  ui_story_2_8_B43_dialog_content = "Aura da luz? Mas eu não consigo usar o poder da Luz...",
  ui_story_2_8_B44_dialog_content = "Calma aí! É só uma expressão!",
  ui_story_2_8_B48_dialog_content = "Por que não desembucha logo? Deixa de mistério.",
  ui_story_2_8_B49_dialog_content = "Hahaha... É assim que se fala! Parece que você já está melhor!",
  ui_story_2_8_B50_dialog_content = "Lembre-se, Celestita. Morrer é fácil, mas tente viver enquanto pode!",
  ui_story_2_8_B51_dialog_content = "Sempre é possível encontrar essa tal \"<color=#FFB400>esperança</color>\".",
  ui_story_2_8_B52_dialog_content = "A esperança está nos dias mais claros e nas noites mais escuras.",
  ui_story_2_8_B53_dialog_content = "Onde você ouviu isso?",
  ui_story_2_8_B54_dialog_content = "Hum... Esqueci.",
  ui_story_2_8_B55_dialog_content = "Parece que você decidiu ler alguns livros desde a última vez que nos vimos.",
  ui_story_2_8_B56_dialog_content = "Hahahaha! Não subestime a nós, andarilhos obstinados! Adeus, pessoal!",
  ui_story_2_8_28_dialog_content = "Tenho o pressentimento de que vamos nos encontrar de novo...",
  ui_story_2_8_29_dialog_content = "Rediesel Wrench, hora de voltar pra casa e saborear alguns vermes de areia!",
  ui_story_2_8_31_dialog_content = "... Você não pode trazer boas notícias pra variar, Nozard?",
  ui_story_2_8_32_dialog_content = "Os reforços de Illumina chegaram. Um Aurorian chamado <color=#FFB400>Charon</color>...",
  ui_story_2_8_33_dialog_content = "Charon? Faz muito tempo desde que ouvi esse nome.",
  ui_story_2_8_34_dialog_content = "Então, o Celestita também foi levado?",
  ui_story_2_8_35_dialog_content = "Estão indo rumo à <color=#FFB400>Subcidade 28</color>.",
  ui_story_2_8_36_dialog_content = "Ao menos o Umbrahulk descobriu para onde estão indo. Sabe o que fazer.",
  ui_story_2_8_37_dialog_content = "Sim!",
  ui_story_2_8_38_dialog_content = "A Subcidade dos Aurorians...",
  ui_story_2_8_39_dialog_content = "Esses ratos acham mesmo que podem se esconder em suas tocas?",
  ui_story_2_8_40_dialog_content = "Covardes... se é para lá que vão fugir...",
  ui_story_2_8_41_dialog_content = "Preparem-se para ver todos morrerem com vocês!",
  ui_story_2_9_1_dialog_content = "Quem é você?",
  ui_story_2_9_2_dialog_content = "Sou o chefe do departamento de <color=#FFB400>Logística da Subcidade 28</color>.",
  ui_story_2_9_3_dialog_content = "Pode me chamar de Charon.",
  ui_story_2_9_4_dialog_content = "Cadê a Vice?",
  ui_story_2_9_5_dialog_content = "No suporte de vida da Colossus. Ela se feriu. Eu.. falhei em protegê-la.",
  ui_story_2_9_6_dialog_content = "E qual a sua relação com a Vice?",
  ui_story_2_9_7_dialog_content = "Vice nos informou de sua missão de exploração antes.",
  ui_story_2_9_8_dialog_content = "Então, eu vi o sinal de emergência da Colossus e segui os Eclipsitas até você.",
  ui_story_2_9_9_dialog_content = "Como Vice está?",
  ui_story_2_9_10_dialog_content = "Seus ferimentos foram estabilizados pelo equipamento de suporte de vida da Colossus.",
  ui_story_2_9_11_dialog_content = "O que faremos agora?",
  ui_story_2_9_12_dialog_content = "Você faz muitas perguntas. Por que não volta comigo para a Subcidade 28?",
  ui_story_2_9_13_dialog_content = "O Oficial Charon voltou!",
  ui_story_2_9_14_dialog_content = "Nossa! Que enorme! O que é aquilo?",
  ui_story_2_9_15_dialog_content = "Rápido, informe à equipe de Transportes para abrir o trilho particular de Charon.",
  ui_story_2_9_17_dialog_content = "Bem-vindo de volta, Oficial Charon!",
  ui_story_2_9_18_dialog_content = "Isso é... uma Colossus?",
  ui_story_2_9_19_dialog_content = "Sim, e há uma pessoa ferida em seu interior. Notifique a equipe médica.",
  ui_story_2_9_20_dialog_content = "Além disso, um esquadrão Illumina... eles sacrificaram suas vidas.",
  ui_story_2_9_21_dialog_content = "Sim, senhor. Farei as preparações e enviarei substitutos agora mesmo.",
  ui_story_2_9_22_dialog_content = "Ótimo. Obrigado.",
  ui_story_2_9_23_dialog_content = "Como está a linha de frente?",
  ui_story_2_9_24_dialog_content = "Nada fora do comum!",
  ui_story_2_9_25_dialog_content = "Estranho. Como um número tão grande de Eclipsitas cruzou a linha de frente?",
  ui_story_2_9_26_dialog_content = "Peça para a divisão de comunicação contatar o <color=#FFB400>quartel-general em Gannon</color>. Desejo falar com eles.",
  ui_story_2_9_B1_dialog_content = "...",
  ui_story_2_9_B2_dialog_content = "Quê? Você nunca viu uma cidade subterrânea tão grande, ou uma organização tão impressionante?",
  ui_story_2_9_B3_dialog_content = "Aqui... é Illumina?",
  ui_story_2_9_B4_dialog_content = "Apenas uma das Subcidades da Federação Illumina. A Número 28.",
  ui_story_2_9_B5_dialog_content = "A Subcidade 28 não fica na linha de frente da guerra com os Eclipsitas, mas somos uma base de logística fundamental.",
  ui_story_2_9_F1_dialog_content = "Se cairmos, os Eclipsitas atravessarão a linha e marcharão direto para...",
  ui_story_2_9_B6_dialog_content = "Ah, Celestita, você estudou geografia?",
  ui_story_2_9_F2_dialog_content = "Eu... aprendi um pouco. Se os Eclipsitas atravessarem a linha, poderão invadir o centro do continente, não é?",
  ui_story_2_9_B7_dialog_content = "Exato! Em um lado, um dia eterno; no outro, noite sem fim. Aqui é o único lugar onde podemos sobreviver. Não temos para onde ir.",
  ui_story_2_9_B8_dialog_content = "Em Illumina, nascemos para lutar contra Eclipsitas. É nossa razão de existir.",
  ui_story_2_9_B9_dialog_content = "Precisamos proteger nosso querido lar.",
  ui_story_2_9_B10_dialog_content = "Seu lar? Quer dizer a terra dos Aurorians?",
  ui_story_2_9_B11_dialog_content = "Mais precisamente, é onde estão todas as <color=#FFB400>coisas que amamos</color>.",
  ui_story_2_9_B13_dialog_content = "Podem ser Aurorians, ruínas perdidas, até mesmo uma memória insignificante.",
  ui_story_2_9_B14_dialog_content = "Isso não é... muito sentimental?",
  ui_story_2_9_B15_dialog_content = "Sentimental? É isso que nos motiva a viver.",
  ui_story_2_9_B16_dialog_content = "Em outras palavras, é <color=#FFB400>esperança</color>!",
  ui_story_2_9_B17_dialog_content = "Quando o desespero é iminente, precisamos superar os tempos sombrios com esperança.",
  ui_story_2_9_B18_dialog_content = "Sim, isso soa poético.",
  ui_story_2_9_B19_dialog_content = "... Sinsa uma vez me disse algo semelhante.",
  ui_story_2_9_B20_dialog_content = "Você parece exausto. O que vai fazer agora? Descansar?",
  ui_story_2_9_B21_dialog_content = "Ou planeja encontrar seus outros amigos?",
  ui_story_2_9_B22_dialog_content = "Amigos...? Acho que meu povo...",
  ui_story_2_9_B23_dialog_content = "Me refiro aos Aurorians. Não são seus amigos?",
  ui_story_2_9_B24_dialog_content = "Ah... Sim, eles me ajudaram bastante...",
  ui_story_2_9_B25_dialog_content = "Acho que preciso de algum tempo para clarear a mente. Hoje foi um dia difícil...",
  ui_story_2_9_B26_dialog_content = "Tudo bem. Fique aqui. Ainda tenho muitos relatórios para fazer, então devo me retirar por enquanto.",
  ui_story_2_9_B27_dialog_content = "Por que essa seriedade repentina...?",
  ui_story_2_9_B28_dialog_content = "Até o mais romântico dos poetas precisa trabalhar!",
  ui_story_2_9_B30_dialog_content = "E, por favor, não se culpe pelo que aconteceu.",
  ui_story_2_9_B31_dialog_content = "Aqueles soldados de Illumina morreram cumprindo seu dever. Não foi por sua causa.",
  ui_story_2_9_27_dialog_content = "Espero que isso tranquilize sua mente.",
  ui_story_2_9_28_dialog_content = "...",
  ui_story_2_9_29_dialog_content = "Celes... tita? Tudo bem se eu chamá-lo assim? O salão é por aqui.",
  ui_story_2_9_30_dialog_content = "Venha comigo. Mesmo que ainda não te conheça, qualquer um que Charon traz aqui é de confiança.",
  ui_story_2_9_32_dialog_content = "Bem-vindo à Subcidade 28.",
  ui_story_2_9_33_dialog_content = "Subcidade 28 para Gannon. Charon falando, tenho uma situação importante para relatar.",
  ui_story_2_9_34_dialog_content = "Entendido. Aqui é <color=#FFB400>Hiiro</color> em Gannon.",
  ui_story_2_9_35_dialog_content = "Senha.",
  ui_story_2_9_36_dialog_content = "<color=#FFB400>\"O cara do trem é um gato.\"</color>",
  ui_story_2_9_37_dialog_content = "Você está de serviço hoje, Hiiro.",
  ui_story_2_9_38_dialog_content = "Resposta.",
  ui_story_2_9_39_dialog_content = "<color=#FFB400>\"Flor de cerejeira\"</color>...",
  ui_story_2_9_41_dialog_content = "Como está indo a missão de Vice?",
  ui_story_2_9_42_dialog_content = "É sobre isso mesmo que quero conversar.",
  ui_story_2_9_43_dialog_content = "A Colossus foi encontrada e enviada à Subcidade 28.",
  ui_story_2_9_44_dialog_content = "Vice foi ferida e está recebendo tratamento.",
  ui_story_2_9_45_dialog_content = "Ferida? É grave?",
  ui_story_2_9_46_dialog_content = "Ela está bem.",
  ui_story_2_9_47_dialog_content = "Como superior interino, Charon, você deve se responsabilizar por ela.",
  ui_story_2_9_48_dialog_content = "Conte o que aconteceu.",
  ui_story_2_9_49_dialog_content = "Vice estava certa.",
  ui_story_2_9_50_dialog_content = "A Colossus que saiu de Eraveil há 17 anos caiu perto da Subcidade 28.",
  ui_story_2_9_51_dialog_content = "Ela e sua equipe encontraram inúmeros Eclipsitas que pareciam estar procurando pela Colossus.",
  ui_story_2_9_52_dialog_content = "Vice não pediu reforços depois de encontrar a Colossus?",
  ui_story_2_9_F3_dialog_content = "Eu vi o sinal de emergência, mas...",
  ui_story_2_9_53_dialog_content = "Era tarde demais?",
  ui_story_2_9_54_dialog_content = "Deixe-me terminar, Hiiro. É mais complicado do que você imagina.",
  ui_story_2_9_55_dialog_content = "A Colossus estava soterrada, mas, acredite se quiser, um Celestita estava vivendo dentro dela.",
  ui_story_2_9_57_dialog_content = "Um Celestita?",
  ui_story_2_9_58_dialog_content = "Está dizendo que um Celestita viveu no subsolo por 17 anos?",
  ui_story_2_9_60_dialog_content = "E depois?",
  ui_story_2_9_61_dialog_content = "Vice pediu apoio quando enviou o sinal de emergência da Colossus.",
  ui_story_2_9_62_dialog_content = "Parti assim que pude e encontrei os rastros deixados pelos Eclipsitas.",
  ui_story_2_9_63_dialog_content = "Depois, o Celestita informou que eles enfrentaram Kraken, Nozard e Umbrahulk.",
  ui_story_2_9_64_dialog_content = "Três Eclipsitas de alto nível?",
  ui_story_2_9_65_dialog_content = "Eles passaram por nossas defesas e se infiltraram nos territórios próximos à Subcidade 28?",
  ui_story_2_9_66_dialog_content = "Nenhum Eclipsita é capaz de cruzar nossas defesas, exceto Kraken.",
  ui_story_2_9_67_dialog_content = "Além disso, havia um grande número de Eclipsitas comuns os seguindo.",
  ui_story_2_9_68_dialog_content = "Eles não deixaram pistas da rota que usaram para chegar lá. É como se tivessem caído do céu, igual ao que aconteceu há 17 anos em Eraveil.",
  ui_story_2_9_69_dialog_content = "Está dizendo que os Eclipsitas conseguiram ultrapassar nossas defesas?",
  ui_story_2_9_70_dialog_content = "Temo que sim...",
  ui_story_2_9_71_dialog_content = "Além disso, o fato de Nozard continuar vivo é um problema.",
  ui_story_2_9_72_dialog_content = "Muito bem. Informarei à Grande Marechal imediatamente.",
  ui_story_2_9_73_dialog_content = "Fiquem alertas.",
  ui_story_2_9_74_dialog_content = "A Subcidade 28 é uma linha de abastecimento vital. Se os suprimentos...",
  ui_story_2_9_75_dialog_content = "Hiiro, pode deixar comigo.",
  ui_story_2_9_76_dialog_content = "<color=#e8d9bb>Alguns dias depois - Estaleiro de Reparos da Colossus</color>",
  ui_story_2_9_77_dialog_content = "Aí está você.",
  ui_story_2_9_78_dialog_content = "Vice? Você já consegue andar?!",
  ui_story_2_9_79_dialog_content = "Sim. A tecnologia médica de Illumina é incrível, né?",
  ui_story_2_9_80_dialog_content = "Como está Soroz?",
  ui_story_2_9_81_dialog_content = "Está tudo bem. A tecnologia de Illumina é realmente incrível. As peças danificadas foram reparadas em apenas alguns dias.",
  ui_story_2_9_82_dialog_content = "Os trabalhadores estão agora dando os toques finais, que me parecem um pouco exagerados.",
  ui_story_2_9_83_dialog_content = "Gostaria que eles removessem aquele emblema de Illumina enorme...",
  ui_story_2_9_84_dialog_content = "Não esperava esse tipo de habilidade e conhecimento em Illumina... Agradeça à Vice por mim.",
  ui_story_2_9_87_dialog_content = "Claro, a divisão de engenharia de Illumina sempre busca a excelência.",
  ui_story_2_9_88_dialog_content = "Olhe só o meu uniforme e minhas armas. Tudo isso é obra da divisão de engenharia. Eles são fundamentais em nossas batalhas.",
  ui_story_2_9_89_dialog_content = "Essa é uma configuração de Lúmina projetada para regular e abastecer os poderes dos Aurorians.",
  ui_story_2_9_90_dialog_content = "Uma tecnologia superior em termos de eficiência e velocidade de ativação.",
  ui_story_2_9_91_dialog_content = "Ainda que menos poderosa do que as práticas tradicionais, essa tecnologia é adequada para Illumina porque lutamos em grupo.",
  ui_story_2_9_A1_dialog_content = "...",
  ui_story_2_9_A2_dialog_content = "...",
  ui_story_2_9_A3_dialog_content = "Ah, tem alguma coisa que você não entendeu?",
  ui_story_2_9_A4_dialog_content = "... Na verdade, não entendi quase nada.",
  ui_story_2_9_A5_dialog_content = "Nada? Ah, desculpe, esqueci que isso ainda é novidade pra você...",
  ui_story_2_9_A6_dialog_content = "Bem... mudando de assunto...",
  ui_story_2_9_A7_dialog_content = "Vice, quando caímos...",
  ui_story_2_9_98_dialog_content = "Acho que eu disse alguma coisa... bem...",
  ui_story_2_9_99_dialog_content = "Resumindo... sinto muito!",
  ui_story_2_9_100_dialog_content = "Hã? Por que isso de repente?",
  ui_story_2_9_101_dialog_content = "Foi egoísmo da minha parte dizer tudo aquilo, e você se feriu por minha culpa. Tenho tido pesadelos recentemente...",
  ui_story_2_9_102_dialog_content = "Ah, está falando daquilo. Não precisa se desculpar!",
  ui_story_2_9_103_dialog_content = "Eu não percebi naquela hora como você e Soroz são próximos. Foi grosseria minha dizer aquilo.",
  ui_story_2_9_104_dialog_content = "Tive medo de você ficar para trás e enfrentar os Eclipsitas sozinho.",
  ui_story_2_9_105_dialog_content = "Mas conseguimos sobreviver, e isso é o que importa!",
  ui_story_2_9_107_dialog_content = "Mal posso esperar para trabalhar ao seu lado, PlayerName.",
  ui_story_2_9_108_dialog_content = "Sim!",
  ui_story_2_9_109_dialog_content = "<color=#e8d9bb>Estrondo...</color>",
  ui_story_2_9_110_dialog_content = "<color=#e8d9bb>Os tremores se intensificam, e parecem vir de baixo da terra.</color>",
  ui_story_2_9X_1_dialog_content = "<color=#e8d9bb>Ocorre um tremor discreto.</color>",
  ui_story_2_9X_2_dialog_content = "<color=#e8d9bb>Os tremores se intensificam, e parecem vir de baixo da terra.</color>",
  ui_story_2_9X_3_dialog_content = "Algo está errado...",
  ui_story_2_9X_4_dialog_content = "O que é esse tremor? É Soroz?",
  ui_story_2_9X_5_dialog_content = "Acho que não. Vou estabelecer uma conexão mental.",
  ui_story_2_9X_6_dialog_content = "<color=#e8d9bb>Biiiip—Biiiip—BIIIIII!</color>",
  ui_story_2_9X_7_dialog_content = "Esse alarme... uma falha no sistema de defesa? Impossível! O sistema estava funcionando perfeitamente, o que...?",
  ui_story_2_9X_8_dialog_content = "Vice! Defesa... invasão... Estamos sendo atacados! Você...",
  ui_story_2_9X_9_dialog_content = "O que disse? Não consigo ouvir, Oficial Charon!",
  ui_story_2_9X_19_dialog_content = "Vice! Estou detectando Eclipsitas!",
  ui_story_2_9X_20_dialog_content = "Eclipsitas! Na Subcidade? Como isso é possível?",
  ui_story_2_9X_21_dialog_content = "Três... dez... perdi a conta. Vice, os Eclipsitas são muito numerosos!",
  ui_story_2_9X_22_dialog_content = "Aqueles tremores eram mais sérios do que pensávamos! Talvez a Subcidade já esteja...",
  ui_story_2_9X_23_dialog_content = "Então vamos direto para a fonte! Se for uma invasão, precisamos detê-los antes que alcancem as áreas residenciais!",
  ui_story_2_9X_24_dialog_content = "Prepare-se para lutar, PlayerName!",
  ui_story_2_9X_25_dialog_content = "Pode deixar!",
  ui_story_2_9X_26_dialog_content = "Avante... Matem... Destruam tudo o que encontrarem....",
  ui_story_2_9X_27_dialog_content = "Não falharei novamente. Lavarei a humilhação com o sangue de Aurorians!",
  ui_story_2_9X_28_dialog_content = "<size=45>Massacrem esta Subcidade!</size>",
  ui_story_2_10_19_dialog_content = "Vice! PlayerName!",
  ui_story_2_10_20_dialog_content = "Você está bem, Oficial Charon?",
  ui_story_2_10_21_dialog_content = "Vice?",
  ui_story_2_10_22_dialog_content = "<color=#FFB400>A defesa da Subcidade foi violada</color>... O impensável aconteceu! Eles passaram pelas barreiras!",
  ui_story_2_10_23_dialog_content = "Como eles conseguiram lançar um ataque coordenado contra os pontos fracos da Subcidade?",
  ui_story_2_10_24_dialog_content = "Impossível. Há algo errado. Nunca aconteceu nada assim em todos esses anos.",
  ui_story_2_10_25_dialog_content = "O que vamos fazer agora? Quantos de nós ainda podem lutar? Reúna todas as forças na área da invasão!",
  ui_story_2_10_26_dialog_content = "Executar o plano de evacuação. Eclipsitas demais já invadiram o interior. De acordo com o Código de Illumina, essa é uma ameaça Classe S. Precisamos evacuar a cidade.",
  ui_story_2_10_27_dialog_content = "Sinto muito. Não pude prever isso...",
  ui_story_2_10_28_dialog_content = "Vamos, Vice. Precisamos evacuar os feridos e civis!",
  ui_story_2_10_29_option_content = "Já perdermos as esperanças?",
  ui_story_2_10_30_option_content = "Não temos nenhuma chance de contra-atacar...?",
  ui_story_2_10_31_dialog_content = "Olhe ao redor! A Subcidade 28 não é uma frente de batalha. Está repleta de soldados feridos e oficiais de logística!",
  ui_story_2_10_32_dialog_content = "A melhor coisa a fazer é poupar nossas forças e nos abrigarmos em outra Subcidade!",
  ui_story_2_10_33_dialog_content = "Como está a situação?",
  ui_story_2_10_34_dialog_content = "Há Eclipsitas por toda parte, possivelmente Eclipsitas de alto nível. De qualquer forma, não podemos ficar aqui!",
  ui_story_2_10_A1_dialog_content = "É Nozard...",
  ui_story_2_10_35_dialog_content = "Essa Subcidade logo estará infestada de Eclipsitas.",
  ui_story_2_10_36_dialog_content = "Entendido! PlayerName, precisamos da sua orientação. Vamos evacuar todos juntos!",
  ui_story_2_10_40_dialog_content = "Pode deixar, ninguém vai ficar para trás!",
  ui_story_2_10_41_dialog_content = "Sim, não abandonarei meu pessoal! Temos que evacuar todos em segurança!",
  ui_story_2_10_42_dialog_content = "Vamos, antes que seja tarde demais!",
  ui_story_2_10_43_dialog_content = "Isso mesmo! Não deem trégua aos Aurorians! Assim que encontrarem a Colossus e o Celestita...",
  ui_story_2_10_44_dialog_content = "<size=45>Avisem-me imediatamente!</size>",
  ui_story_2_12_3_dialog_content = "Criaturas asquerosas, deveriam ter ficado nas sombras!",
  ui_story_2_12_4_dialog_content = "Por que eles vieram destruir nossa bela Subcidade? Isso não faz sentido!",
  ui_story_2_12_5_dialog_content = "Wooga!",
  ui_story_2_12_6_dialog_content = "Não entendo!",
  ui_story_2_12_7_dialog_content = "Desse jeito, os Eclipsitas vão alcançar a área residencial antes de nós!",
  ui_story_2_12_8_dialog_content = "Onde está seu trem, Charon? Podemos usá-lo?",
  ui_story_2_12_9_dialog_content = "Aqui não há trilhos por onde Other End possa se locomover.",
  ui_story_2_12_10_dialog_content = "Se aquela coisa for convocada, não vamos salvar ninguém. Será um milagre se encontrarem nossos corpos intactos.",
  ui_story_2_12_11_dialog_content = "Precisamos fazer alguma coisa... e rápido...",
  ui_story_2_12_12_dialog_content = "Esses Eclipsitas são os mesmos que encontramos antes? Como eles estão tão... organizados... em torno de um objetivo?",
  ui_story_2_12_13_dialog_content = "<color=#FFB400>É como se tivessem um alvo específico...</color>",
  ui_story_2_12_14_dialog_content = "...",
  ui_story_2_12_15_dialog_content = "Ah, então estão atrás do Celestita? Que situação...",
  ui_story_2_12_16_dialog_content = "<color=#e8d9bb>A Subcidade estremece intensamente mais uma vez.</color>",
  ui_story_2_12_17_dialog_content = "Odeio admitir, mas parece que chegamos ao limite.",
  ui_story_2_12_18_dialog_content = "Nos resta uma última esperança. Ainda temos uma carta na manga!",
  ui_story_2_12_19_dialog_content = "PlayerName, se estiver se referindo a...",
  ui_story_2_12_20_dialog_content = "<color=#FFB400>Soroz</color>!",
  ui_story_2_12_24_dialog_content = "Como fiz com PlayerName antes!",
  ui_story_2_12_25_dialog_content = "A Colossus ainda está carregando, e parece que isso vai levar algum tempo.",
  ui_story_2_12_26_dialog_content = "Mesmo assim, precisamos tentar. Ela pode levar todos para longe daqui em segurança...",
  ui_story_2_12_X26_dialog_content = "Então vamos lá. Nossa única chance é entregar nosso destino a Soroz.",
  ui_story_2_12_27_dialog_content = "Sempre me encarregam das missões em momentos críticos. Já me acostumei. Mesmo assim, é melhor apressar as coisas.",
  ui_story_2_12_X27_dialog_content = "Posso sentir Eclipsitas se aproximando...",
  ui_story_2_12_28_dialog_content = "Não temos escolha. Vou colocar todos a bordo da Colossus.",
  ui_story_2_12_29_dialog_content = "E nós vamos ligar a Colossus primeiro!",
  ui_story_2_13_1_dialog_content = "<color=#e8d9bb>No porto subterrâneo onde está Soroz, a Colossus</color>",
  ui_story_2_13_2_dialog_content = "Tem mais inimigos chegando...",
  ui_story_2_13_3_dialog_content = "Garble, garble...",
  ui_story_2_13_4_dialog_content = "Eu sabia! Os Eclipsitas estão se reunindo ao redor da Colossus!",
  ui_story_2_13_5_dialog_content = "Hmm...",
  ui_story_2_13_6_dialog_content = "Está... emitindo um sinal? Será que está se comunicando com Eclipsitas distantes...?",
  ui_story_2_13_7_dialog_content = "Não importa! Todo mundo, entrem na Colossus. Feridos e crianças primeiro! Vamos dar cobertura daqui!",
  ui_story_2_13_8_dialog_content = "Parece que não vou usar o trem, afinal... Achei que terminaríamos o dia com um final glorioso.",
  ui_story_2_13_9_dialog_content = "Acho que precisarei me contentar com isso.",
  ui_story_2_13_10_dialog_content = "O que você está fazendo com um... controle remoto?",
  ui_story_2_13_11_dialog_content = "... O <color=#FFB400>Botão Rubro</color>? Quando você...",
  ui_story_2_13_12_dialog_content = "Esse é o procedimento padrão para uma evacuação classe S. Qualquer resquício da nossa existência deve ser eliminado. Os fogos serão gloriosos.",
  ui_story_2_13_13_dialog_content = "É difícil abandonar essa Subcidade... Afinal, vivi aqui por muitos anos.",
  ui_story_2_13_14_dialog_content = "\"O Supervisor da Subcidade 28\" falhou em protegê-la. Que fiasco!",
  ui_story_2_13_15_dialog_content = "Sinto muito...",
  ui_story_2_13_16_dialog_content = "Pelo quê? Você atraiu os Eclipsitas de propósito?",
  ui_story_2_13_17_dialog_content = "Claro que não!",
  ui_story_2_13_18_dialog_content = "Acalme-se, Tenente... era uma piada.",
  ui_story_2_13_19_dialog_content = "Chegou a hora da Subcidade 28. Ninguém carrega a culpa.",
  ui_story_2_13_20_dialog_content = "Talvez... tudo tem um fim, e é assim que as coisas são...",
  ui_story_2_13_21_dialog_content = "Mesmo dias e noites eternas um dia chegarão ao fim... Isso não é poético?",
  ui_story_2_13_22_dialog_content = "O que está esperando? Vá! Não serei responsável pelo que vai acontecer quando apertar o Botão Rubro.",
  ui_story_2_13_23_dialog_content = "Tenente, outra onda de Eclipsitas está a caminho! Ainda há feridos para trás...",
  ui_story_2_13_24_dialog_content = "Entendido! Vamos segurá-los. O restante de vocês, apressem o passo!",
  ui_story_2_13_25_dialog_content = "Parece que ainda não é hora do grande final. Vou deixar o Botão Rubro de lado por enquanto...",
  ui_story_2_14_1_dialog_content = "Cheguei... finalmente! Alguém está ferido?",
  ui_story_2_14_2_dialog_content = "Estamos fazendo a contagem! Acho que estão todos aqui. Cadê o Oficial Charon?",
  ui_story_2_14_3_dialog_content = "Oficial Charon? Ele estava protegendo o portão da Colossus em outro local.",
  ui_story_2_14_4_dialog_content = "Desculpe pela demora, Tenente! Não resta mais ninguém, não é? Os Eclipsitas tomaram cada canto desse lugar!",
  ui_story_2_14_5_dialog_content = "Agradeço por tudo! Eu trouxe tantos problemas...",
  ui_story_2_14_6_dialog_content = "Não diga isso, Tenente! Vamos tirar todos daqui primeiro. Em frente!",
  ui_story_2_14_7_dialog_content = "Espere, está faltando alguém! Onde está o Oficial Charon?",
  ui_story_2_14_8_dialog_content = "Ele estava protegendo os feridos que ficaram para trás. Parecia que...",
  ui_story_2_14_9_dialog_content = "Avistei ele! Ali!",
  ui_story_2_14_10_dialog_content = "Droga, eles arruinaram meu traje...",
  ui_story_2_14_11_dialog_content = "Ele está lutando sozinho, e todos os Eclipsitas da Subcidade se reuniram ali!",
  ui_story_2_14_12_dialog_content = "Está óbvio que eu sou o alvo pela maneira que os Eclipsitas estão se movendo!",
  ui_story_2_14_13_dialog_content = "Vamos, suba!",
  ui_story_2_14_14_dialog_content = "Eu gostaria, mas essas coisas são irritantes demais!",
  ui_story_2_14_15_dialog_content = "Tudo o que posso fazer é não deixar que cerquem você!",
  ui_story_2_14_16_dialog_content = "Não, preciso ajudá-lo... PlayerName, venha comigo! O restante, fiquem onde estão!",
  ui_story_2_14_17_dialog_content = "Wooga?!",
  ui_story_2_14_18_dialog_content = "Eles são muito numerosos! Não consigo avançar!",
  ui_story_2_14_19_dialog_content = "Vamos todos morrer aqui se não formos agora! Não é hora para vacilar!",
  ui_story_2_14_20_option_content = "Vice, precisamos ir agora!",
  ui_story_2_14_21_dialog_content = "Sem chance! Não deixaremos ninguém para trás!",
  ui_story_2_14_22_dialog_content = "Vice, PlayerName tem razão. Precisamos sair agora!",
  ui_story_2_14_23_dialog_content = "Charon salvou você antes! Ele já ajudou todos nós! Não podemos deixá-lo aqui!",
  ui_story_2_14_24_dialog_content = "Mas também não podemos pôr em risco a vida de todos!",
  ui_story_2_14_25_dialog_content = "Sei disso, é claro... Por que tinha que acabar assim?!",
  ui_story_2_14_26_option_content = "Não. Precisamos salvar Charon.",
  ui_story_2_14_27_dialog_content = "Você pensou bem, PlayerName?",
  ui_story_2_14_28_dialog_content = "Todos os habitantes da Subcidade estão aqui. Sabe o que custará o fracasso, não é?",
  ui_story_2_14_29_dialog_content = "Nós vamos conseguir!",
  ui_story_2_14_31_dialog_content = "Talvez sua confiança imprudente ainda faça milagres.",
  ui_story_2_14_32_dialog_content = "É isso que diferencia você dos outros, PlayerName...",
  ui_story_2_15_1_dialog_content = "Oficial Charon!",
  ui_story_2_15_X1_dialog_content = "Ahhh!",
  ui_story_2_15_F1_dialog_content = "Droga, não consigo me aproximar!",
  ui_story_2_15_X2_dialog_content = "Vice! Não faça nenhuma burrice!",
  ui_story_2_15_X3_dialog_content = "Escória asquerosa! Vou mostrar a vocês!",
  ui_story_2_15_X4_dialog_content = "<color=#e8d9bb>Vuuush!</color>",
  ui_story_2_15_A1_dialog_content = "O que está fazendo, Charon? Os sinais vão atrair ainda mais Eclipsitas!",
  ui_story_2_15_X6_dialog_content = "Tenente, o que está esperando? Não seja infantil! Pare de carregar tudo nas costas! Isso vai causar ainda mais problemas!",
  ui_story_2_15_2_dialog_content = "Eu, Charon, o Barqueiro de Acheron, a personificação do esplendor e da beleza, não permitirei interferências na gloriosa missão!",
  ui_story_2_15_3_dialog_content = "Está fazendo isso... de propósito?",
  ui_story_2_15_4_dialog_content = "Vá, PlayerName! Não deixe minha imponência distrair você!",
  ui_story_2_15_5_dialog_content = "Não é hora de dar show, Oficial Charon! Nunca vamos subir a bordo se você...",
  ui_story_2_15_A2_dialog_content = "Não tema! Esses inimigos nunca me derrotarão! Sabe disso, Vice!",
  ui_story_2_15_A3_dialog_content = "Você só vai atrapalhar, talvez até cause a morte de Charon, o Barqueiro de Acheron, o Matador de Eclipsitas!",
  ui_story_2_15_A4_dialog_content = "Charon...",
  ui_story_2_15_A5_dialog_content = "Coloque todos a bordo, Tenente. Isso é uma ordem! Alcanço vocês depois.",
  ui_story_2_15_A6_dialog_content = "... Sim, senhor. Preparar para decolar, PlayerName...",
  ui_story_2_15_A7_dialog_content = "Decolando...",
  ui_story_2_15_A8_dialog_content = "Soroz, não tranque o portão de embarque. Charon pode chegar a qualquer momento!",
  ui_story_2_15_A9_dialog_content = "Tem certeza, PlayerName?",
  ui_story_2_15_A10_dialog_content = "... Como assim?",
  ui_story_2_15_A11_dialog_content = "Não parece que Charon está nos seguindo...",
  ui_story_2_15_A12_dialog_content = "Pelo contrário. Ele está indo em direção à horda de Eclipsitas.",
  ui_story_2_15_A13_dialog_content = "O quê?! Ele...",
  ui_story_2_15_6_dialog_content = "O que é esse alarme?",
  ui_story_2_15_7_dialog_content = "Tenente! É a sequência de autodestruição. Charon apertou o Botão Rubro!",
  ui_story_2_15_8_dialog_content = "Eu já sei disso!",
  ui_story_2_15_A14_dialog_content = "Charon... então esse era o seu plano...?",
  ui_story_2_15_9_dialog_content = "Estamos prontos para decolar! Nunca esquecerei daquele Aurorian. Segurem firme!",
  ui_story_2_15_10_option_content = "Lá vamos nós!",
  ui_story_2_15_13_dialog_content = "Há uma brecha no casco! Tem alguma coisa na grande asa branca, <color=#FFB400>e é muito pesada...</color>",
  ui_story_2_15_14_dialog_content = "...",
  ui_story_2_15_15_option_content = "Você está bem?",
  ui_story_2_15_17_dialog_content = "Melhor se segurar, PlayerName, o perigo ainda não passou!",
  ui_story_2_15_18_dialog_content = "Charon apertou o Botão Rubro. Precisamos alcançar uma distância segura antes que a Subcidade... exploda.",
  ui_story_2_15_19_option_content = "Sinto muito...",
  ui_story_2_15_20_option_content = "Pelo Charon...",
  ui_story_2_15_21_dialog_content = "Prometi que nunca deixaria ninguém para trás... Eu prometi...",
  ui_story_2_15_F2_dialog_content = "Não é sua culpa, PlayerName. É minha.",
  ui_story_2_15_22_dialog_content = "Se eu tivesse me esforçado mais, se tivesse escolhido uma rota diferente, talvez os Eclipsitas não tivessem nos separado.",
  ui_story_2_15_23_dialog_content = "Não deveríamos ter deixado ele proteger todos sozinho, pra começar...",
  ui_story_2_15_24_dialog_content = "Que tocante. Quase perdi esse momento.",
  ui_story_2_15_25_dialog_content = "Não esperava tanta resistência.",
  ui_story_2_15_26_dialog_content = "Você...?!",
  ui_story_2_15_27_dialog_content = "Desista. Resistir é inútil! Não cairei em seus truques novamente...",
  ui_story_2_15_28_option_content = "Por que está me perseguindo?",
  ui_story_2_15_29_dialog_content = "Devo concluir minha missão.",
  ui_story_2_15_30_dialog_content = "Qual é a minha missão? Talvez seja destruir todos os infiéis.",
  ui_story_2_15_31_option_content = "O que você quer?",
  ui_story_2_15_32_dialog_content = "Tudo o que fiz foi pelo bem da nossa missão.",
  ui_story_2_15_33_dialog_content = "Nossa força vem da nossa fé.",
  ui_story_2_15_34_dialog_content = "Nossa fé vem da nossa Mãe.",
  ui_story_2_15_35_dialog_content = "Vocês, Celestitas e Aurorians, são parasitas que infestam esta terra. Deveriam estar gratos por serem aniquilados por nós.",
  ui_story_2_15_36_dialog_content = "Lutar é inútil. Apenas adiará o inevitável, como aconteceu com aquele soldado estúpido.",
  ui_story_2_15_37_dialog_content = "Aurorians, voltem para o solo e recebam uma morte rápida.",
  ui_story_2_15_38_dialog_content = "Nunca me renderei! Não vou permitir que você machuque meus amigos novamente!",
  ui_story_2_15_39_dialog_content = "Então, você deseja uma morte honrosa em batalha? Muito bem.",
  ui_story_2_15_40_dialog_content = "Darei a você uma morte digna de sua teimosia.",
  ui_story_2_15_41_dialog_content = "Vou lhe torturar brutalmente até o fim.",
  ui_story_2_15_89_dialog_content = "Mestra... eu... falhei...",
  ui_story_2_15_91_dialog_content = "Isso não acabará aqui... eu garanto...",
  ui_story_2_15_X92_dialog_content = "Gostaria de ouvir minha confissão? Haha... Hahahahaha",
  ui_story_2_15_X93_dialog_content = "Aproveitem essa breve vitória!",
  ui_story_2_15_X94_dialog_content = "A Mestra dará a você o que merece. A todos vocês, incluindo os Aurorians e o Celestita covarde.",
  ui_story_2_15_X95_dialog_content = "Suas gargantas insignificantes serão capazes nem de gritar...",
  ui_story_2_15_92_dialog_content = "Schummer... um nome que ecoará em sua mente.",
  ui_story_2_15_93_dialog_content = "O poder dela é maior do que tudo o que vocês conhecem.",
  ui_story_2_15_42_dialog_content = "Esse... é mesmo o fim.",
  ui_story_2_15_43_dialog_content = "<color=#e8d9bb>Bum!!!</color>",
  ui_story_2_15_44_dialog_content = "A Subcidade 28... explodiu...",
  ui_story_2_15_45_dialog_content = "<color=#e8d9bb>A explosão é seguida do alvorecer, como uma homenagem aos mortos e ao início de um novo dia...</color>",
  ui_story_2_15_46_dialog_content = "Adeus... Subcidade 28 e Charon...",
  ui_story_2_15_47_dialog_content = "Sinto muito.",
  ui_story_2_15_48_dialog_content = "Ele escolheu isso, PlayerName. Não se culpe.",
  ui_story_2_15_49_dialog_content = "Por que... por que se sacrificou para nos proteger? Por que não abriu mão de sua valentia, nem mesmo no último minuto...",
  ui_story_2_15_51_option_content = "Ele vai se tornar um exemplo para todos nós, não vai?",
  ui_story_2_15_52_dialog_content = "De que adianta, se ele já morreu?",
  ui_story_2_15_B1_dialog_content = "\"Exemplo\"? O que quer dizer?",
  ui_story_2_15_B2_dialog_content = "Se entendi corretamente, Charon estava protegendo aquilo que ama.",
  ui_story_2_15_B3_dialog_content = "...",
  ui_story_2_15_B4_dialog_content = "Seus soldados, colegas, amigos... e a Subcidade.",
  ui_story_2_15_53_option_content = "Ele continuará vivendo em todos nós.",
  ui_story_2_15_54_dialog_content = "Vivendo em todos nós? Me perdoe se pareço egoísta, mas isso não é vida, PlayerName.",
  ui_story_2_15_55_dialog_content = "É apenas mais dor causada em outras pessoas.",
  ui_story_2_15_B5_dialog_content = "Como a dor que você tem suportado. Você aceitaria um fim como esse?",
  ui_story_2_15_B6_dialog_content = "Mas eu só posso aceitar...",
  ui_story_2_15_B7_dialog_content = "Ao menos ele morreu protegendo as coisas que amava, os soldados e entes queridos.",
  ui_story_2_15_B8_dialog_content = "Não podemos decepcioná-lo, Vice.",
  ui_story_2_15_B9_dialog_content = "Entendo o que quer dizer, PlayerName, mas minha cabeça está uma bagunça.",
  ui_story_2_15_B10_dialog_content = "Proteção, dedicação... Como membro de Illumina, é claro que defendo essas virtudes.",
  ui_story_2_15_B11_dialog_content = "Mas ainda não consigo suportar ver pessoas me deixando.",
  ui_story_2_15_57_dialog_content = "Estamos sempre entoando \"Splendor Illumina!\". Mas será que podemos mesmo ser a Aurora e criar um futuro melhor?",
  ui_story_2_15_58_dialog_content = "Acho que, se um dia...",
  ui_story_2_15_59_dialog_content = "Se um dia formos forçados a tomar uma decisão semelhante...",
  ui_story_2_15_60_dialog_content = "Não quero nem pensar nisso.",
  ui_story_2_15_61_dialog_content = "Esperança.",
  ui_story_2_15_62_dialog_content = "...?",
  ui_story_2_15_63_dialog_content = "Charon disse \"Quando o desespero é iminente, precisamos superar os tempos sombrios com esperança.\"",
  ui_story_2_15_66_option_content = "Isso é a cara dele.",
  ui_story_2_15_F3_dialog_content = "Sempre lembrarei seu nome. Charon, o Barqueiro de Acheron.",
  ui_story_2_15_F4_dialog_content = "O Barqueiro de Acheron...?",
  ui_story_2_15_F5_dialog_content = "O que foi?",
  ui_story_2_15_70_dialog_content = "Por que Charon se chama o Barqueiro de Acheron?",
  ui_story_2_15_71_dialog_content = "É por causa daquele... trem extravagante dele. Você viu.",
  ui_story_2_15_72_dialog_content = "Como um ex-controlador ferroviário, ele podia invocar o trem, Other End, quando quisesse.",
  ui_story_2_15_73_dialog_content = "Ah!",
  ui_story_2_15_74_dialog_content = "Trem? Espera... o sinal de luz...",
  ui_story_2_15_79_dialog_content = "Não me diga que ele...",
  ui_story_2_15_80_dialog_content = "Tenente Vice, PlayerName, olhem lá!",
  ui_story_2_15_81_dialog_content = "<color=#FFB400>Isso é que é extravagância</color>...",
  ui_story_2_15_82_dialog_content = "<size=45>Este é o graaaaande final!</size>",
  ui_story_2_15_A15_dialog_content = "Os fogos de artifício, aplausos e suas lágrimas comoventes. Tal reconhecimento me enche de prazer!",
  ui_story_2_15_83_dialog_content = "<size=45>Contemplem! Charon, o Barqueiro de Acheron, está aqui!</size>",
  ui_story_2_15_84_dialog_content = "Derramaram lágrimas por mim, meu amado público?",
  ui_story_2_15_F6_dialog_content = "Vamos perguntar a um espectador. O que acha, PlayerName?",
  ui_story_2_15_X85_dialog_content = "Hum, aquela foi... uma performance arrebatadora...",
  ui_story_2_15_85_dialog_content = "Muito... bem, Oficial Charon...",
  ui_story_2_15_86_dialog_content = "Não sei se deveria sentir alívio ou raiva...",
  ui_story_2_15_87_option_content = "Isso é incrível... Ugh...",
  ui_story_2_15_88_dialog_content = "PlayerName?",
  ui_story_2_15_X88_dialog_content = "Estou tonto... está... voltando...",
  ui_story_2_15_95_dialog_content = "Aquela visão familiar...",
  ui_story_2_15_96_dialog_content = "Vice...",
  ui_story_2_15_100_dialog_content = "PlayerName, estou aqui! Fique acordado!",
  ui_story_2_15_101_dialog_content = "<color=#e8d9bb>Fora das ruínas de</color> <color=#FFB400>outra Colossus</color>",
  ui_story_2_15_102_dialog_content = "...",
  ui_story_2_15_103_dialog_content = "Você está bem, Mestra?",
  ui_story_2_15_104_dialog_content = "Por que pergunta?",
  ui_story_2_15_105_dialog_content = "Você estava distraída. Não deveria estar tão distraída depois de esperar tanto tempo por essa oportunidade...",
  ui_story_2_15_106_dialog_content = "Não teste minha paciência com perguntas insolentes, Eclipsita. Eu estava... talvez seja apenas uma ilusão.",
  ui_story_2_15_107_dialog_content = "Então desejo a você uma boa caçada. Espero que encontre o que procura.",
  ui_story_2_15_108_dialog_content = "Caçada? Hum, gostei dessa palavra.",
  ui_story_2_15_109_dialog_content = "Pode ouvir minha voz? Consigo sentir sua presença...",
  ui_story_2_15_110_dialog_content = "Já deve ter percebido que também sou um <color=#FFB400>Celestita</color>. Mas estou ficando sem tempo.",
  ui_story_2_15_111_dialog_content = "Aviduz, <color=#FFB400>aquela mulher</color>... A escuridão ameaçadora... A pecadora que matou seu próprio povo...",
  ui_story_2_15_112_dialog_content = "Ela me encontrou...",
  ui_story_2_15_113_dialog_content = "Minha Colossus e eu... nosso tempo se esgotou...",
  ui_story_3_1_1_dialog_content = "Pode me ouvir? Não conheço você, mas sei que também é um Celestita.",
  ui_story_3_1_2_dialog_content = "Tenho certeza de que pode me ouvir.",
  ui_story_3_1_3_dialog_content = "Um sinal foi enviado. Todos, fiquem onde estão.",
  ui_story_3_1_4_dialog_content = "Hum, Vice? Esse tal PlayerName está acordando!",
  ui_story_3_1_5_dialog_content = "Mas parece que PlayerName continua apreciando minha magnífica performance.",
  ui_story_3_1_6_dialog_content = "Muito obrigada, Oficial Charon. Agora, vá comer alguma coisa!",
  ui_story_3_1_7_dialog_content = "Não estou com fome. É uma pena que meu ato heroico não tenha sido filmado...",
  ui_story_3_1_8_dialog_content = "Parece que suas prioridades estão invertidas...",
  ui_story_3_1_9_dialog_content = "É óbvio que o poder do Botão Rubro é realmente impressionante. Pra falar a verdade, eu sempre quis usá-lo...",
  ui_story_3_1_10_dialog_content = "A Subcidade 28 jaz em ruínas, Oficial Charon. Não está... triste?",
  ui_story_3_1_11_dialog_content = "É uma lástima terrível, mas poupe suas lágrimas! Ainda temos um <color=#FFB400>lar</color>.",
  ui_story_3_1_12_dialog_content = "Lar?",
  ui_story_3_1_13_dialog_content = "Sim. Olhe ao redor.",
  ui_story_3_1_14_dialog_content = "Os civis e soldados... as coisas mais importantes da Federação continuam intactas.",
  ui_story_3_1_15_dialog_content = "Lar é onde estão seus entes queridos.",
  ui_story_3_1_F1_dialog_content = "Hmm...",
  ui_story_3_1_16_dialog_content = "Você e o Celestita estão bem, não é? É a segunda vez que salvo vocês.",
  ui_story_3_1_F2_dialog_content = "Eu agradeço, senhor...",
  ui_story_3_1_17_dialog_content = "Preciso avaliar a situação. Tenha paciência, e não saia daqui!",
  ui_story_3_1_18_dialog_content = "Certo...",
  ui_story_3_1_19_dialog_content = "Charon... não é tão arrogante quanto parece.",
  ui_story_3_1_20_dialog_content = "Você está bem, PlayerName? Você...",
  ui_story_3_1_B1_dialog_content = "Sim, estou bem.",
  ui_story_3_1_B2_dialog_content = "Você não parece bem. Não se esforce tanto.",
  ui_story_3_1_B3_dialog_content = "Obrigado, Vice... por ficar ao meu lado durante todo esse tempo.",
  ui_story_3_1_B4_dialog_content = "Mas é claro! Somos uma equipe!",
  ui_story_3_1_B5_dialog_content = "Derrotamos Eclipsitas de alto nível graças a você!",
  ui_story_3_1_B6_dialog_content = "Isso é apenas o <color=#FFB400>começo</color>, Vice.",
  ui_story_3_1_B7_dialog_content = "Hã? O começo?",
  ui_story_3_1_B8_dialog_content = "Antes de morrer, Nozard mencionou aquele nome novamente... <color=#FFB400>Schummer</color>.",
  ui_story_3_1_B9_dialog_content = "Schummer.... Quem é ela?",
  ui_story_3_1_B10_dialog_content = "Não sei, mas acho que ela conhece toda a verdade.",
  ui_story_3_1_B11_dialog_content = "Desculpe, Vice, mas preciso encontrar Schummer e descobrir a verdade.",
  ui_story_3_1_B12_dialog_content = "Por que você ficou tão motivado de repente, PlayerName?",
  ui_story_3_1_B13_dialog_content = "Encontrei meu \"<color=#FFB400>lar</color>\" novamente.",
  ui_story_3_1_B14_dialog_content = "Você falou com o Charon enquanto eu estava me recuperando...?",
  ui_story_3_1_B15_dialog_content = "Infelizmente, Nozard não falou mais nada sobre Schummer...",
  ui_story_3_1_B17_dialog_content = "Não tem problema. Deve haver mais arquivos no QG da Illumina.",
  ui_story_3_1_B18_dialog_content = "Qual o problema, PlayerName?",
  ui_story_3_1_B21_dialog_content = "Me ajude...",
  ui_story_3_1_B22_dialog_content = "Rápido... Você... consegue me ouvir?!",
  ui_story_3_1_B23_dialog_content = "Sentiu isso, PlayerName? O que foi aquilo?",
  ui_story_3_1_B24_dialog_content = "Sim. <color=#FFB400>Alguém está pedindo socorro</color>?",
  ui_story_3_1_21_dialog_content = "Aviduz está... eu estou... sem tempo...",
  ui_story_3_1_22_dialog_content = "Você ouviu alguma coisa, não foi?",
  ui_story_3_1_23_option_content = "Só pode ser a telepatia dos Celestitas!",
  ui_story_3_1_24_dialog_content = "Um sobrevivente <color=#FFB400>como eu</color>? Outro Celestita?!",
  ui_story_3_1_25_dialog_content = "Sim. E pela mensagem, parecia estar em apuros.",
  ui_story_3_1_26_dialog_content = "Talvez ele seja como nós...",
  ui_story_3_1_27_option_content = "É a voz de um garoto",
  ui_story_3_1_28_dialog_content = "Sim, sua consciência está tomada pelo medo. A situação parece grave.",
  ui_story_3_1_F3_dialog_content = "Comunicação psíquica... Ele é um Celestita?",
  ui_story_3_1_29_dialog_content = "Sim, mas o sinal da sua Colossus estava fraco demais para que eu pudesse localizar.",
  ui_story_3_1_30_dialog_content = "Ele está suplicando por ajuda. Algo terrível está acontecendo com ele e sua Colossus.",
  ui_story_3_1_31_dialog_content = "<color=#FFB400>Outro Celestita</color>?",
  ui_story_3_1_32_dialog_content = "Espera, tá dizendo que podemos encontrar outra Colossus com ele?",
  ui_story_3_1_33_dialog_content = "Pode me ajudar, Vice?",
  ui_story_3_1_34_dialog_content = "...",
  ui_story_3_1_35_dialog_content = "Tem algo a dizer, Tenente?",
  ui_story_3_1_36_dialog_content = "É, nós...",
  ui_story_3_1_37_dialog_content = "Recebemos um pedido de socorro de outro Celestita!",
  ui_story_3_1_38_dialog_content = "...?!",
  ui_story_3_1_39_dialog_content = "Dois Celestitas? O que está acontecendo?",
  ui_story_3_1_40_dialog_content = "Posso confirmar que a comunicação psíquica foi exatamente como a minha!",
  ui_story_3_1_41_dialog_content = "Onde ele está? É perto?",
  ui_story_3_1_42_dialog_content = "Não sei... mas tenho uma direção aproximada. Precisamos partir agora!",
  ui_story_3_1_43_dialog_content = "...",
  ui_story_3_1_44_dialog_content = "Isso não será possível.",
  ui_story_3_1_45_dialog_content = "Senhor!",
  ui_story_3_1_46_dialog_content = "Quanta desorganização... Quanta falta de disciplina... Não sabe quantos problemas você acabou de causar?",
  ui_story_3_1_47_dialog_content = "Mas...",
  ui_story_3_1_48_dialog_content = "Todos estão observando, então tente não criar uma cena.",
  ui_story_3_1_49_dialog_content = "E sua superior direta, Hiiro, Comandante da 3ª Legião, está chegando.",
  ui_story_3_1_50_dialog_content = "Não vai informá-la sobre a situação atual?",
  ui_story_3_1_51_dialog_content = "...",
  ui_story_3_1_52_dialog_content = "Mas não temos tempo a perder.",
  ui_story_3_1_53_dialog_content = "Quem sabe quando teremos outra chance dessas?",
  ui_story_3_1_54_dialog_content = "E ele parecia precisar muito de ajuda! Estava em grave perigo!",
  ui_story_3_1_55_dialog_content = "É alguém do meu povo, Charon. Um Celestita de verdade, vivo!",
  ui_story_3_1_56_dialog_content = "...",
  ui_story_3_1_57_dialog_content = "Senhor...",
  ui_story_3_1_58_dialog_content = "Entendo que isso é importante para você, PlayerName.",
  ui_story_3_1_59_dialog_content = "Mas a Federação Illumina possui seu próprio código de conduta, especialmente quando eu estou no comando.",
  ui_story_3_1_60_dialog_content = "A menos...",
  ui_story_3_1_61_dialog_content = "...!",
  ui_story_3_1_62_dialog_content = "A menos que eu não tenha sido informado da sua operação!",
  ui_story_3_1_63_dialog_content = "Hã?",
  ui_story_3_1_64_dialog_content = "Você é uma tenente, não é, Vice? E não está sob o meu comando direto.",
  ui_story_3_1_A1_dialog_content = "Por isso, possui uma certa autonomia, contanto que não ponha a Federação Illumina em perigo.",
  ui_story_3_1_A2_dialog_content = "Mas gostaria de enfatizar novamente que a Federação Illumina está observando.",
  ui_story_3_1_A3_dialog_content = "Sei o que devemos fazer, Vice.",
  ui_story_3_1_65_dialog_content = "Você tem uma ideia?",
  ui_story_3_1_B25_option_content = "Vamos sair de fininho",
  ui_story_3_1_B26_option_content = "Vamos usar a criatividade e dar um show",
  ui_story_3_1_66_dialog_content = "Não diga isso na frente de um oficial superior, PlayerName.",
  ui_story_3_1_67_dialog_content = "Ha? O que você disse? Não consegui ouvir por conta do vento alto.",
  ui_story_3_1_68_dialog_content = "...",
  ui_story_3_1_B26_dialog_content = "Está sugerindo que deveríamos...",
  ui_story_3_1_B27_dialog_content = "Sugerindo? Eu não estava sugerindo nada! Do que você tá falando?",
  ui_story_3_1_B28_dialog_content = "Estava apenas relembrando suas opções como tenente, Vice.",
  ui_story_3_1_B29_dialog_content = "Você decide o que fazer.",
  ui_story_3_1_B30_dialog_content = "Entendi, senhor. Obrigada.",
  ui_story_3_1_B31_dialog_content = "Hiiro logo estará aqui. Se vai fazer alguma coisa da qual não sei nada a respeito, é melhor fazer agora.",
  ui_story_3_1_B32_dialog_content = "Caso contrário, você precisará ficar e informá-la da situação quando ela chegar.",
  ui_story_3_1_B33_dialog_content = "Charon é mesmo cheio de surpresas.",
  ui_story_3_1_B34_dialog_content = "Nossa... que tenso... como será que a Comandante Hiiro vai reagir...",
  ui_story_3_1_B35_dialog_content = "Dar um show?",
  ui_story_3_1_B36_dialog_content = "Arram!",
  ui_story_3_1_B37_dialog_content = "Ah, Charon. Tenho algo para dizer, mas não sei se deveria.",
  ui_story_3_1_B38_dialog_content = "Fale francamente, Celestita!",
  ui_story_3_1_B39_dialog_content = "Soroz acabou de informar que um grande grupo de Eclipsitas está seguindo a Colossus, e vem direto pra cá!",
  ui_story_3_1_B40_dialog_content = "Hã? Como?",
  ui_story_3_1_B41_dialog_content = "Quê?! A aura da Colossus está atraindo mais Eclipsitas?",
  ui_story_3_1_B42_dialog_content = "Por que não disse antes?! Isso é um grave perigo!",
  ui_story_3_1_B43_dialog_content = "???",
  ui_story_3_1_B44_dialog_content = "(Vamos, Vice, entra na jogada!)",
  ui_story_3_1_B45_dialog_content = "Ah.... Ah! Desculpe, eu... acabei de perceber isso...",
  ui_story_3_1_B46_dialog_content = "Inacreditável! Quer dizer, acabamos da sair da panela e estamos indo direto para o fogo!",
  ui_story_3_1_B47_dialog_content = "Não posso deixar meu pessoal correr esse risco!",
  ui_story_3_1_B48_dialog_content = "Ah, então... o que faremos?!",
  ui_story_3_1_B49_dialog_content = "Tire a Colossus daqui! Leve-a para longe dos civis inocentes!",
  ui_story_3_1_B50_dialog_content = "Sim!",
  ui_story_3_1_B51_dialog_content = "(Vai, rápido!)",
  ui_story_3_1_B52_dialog_content = "Agradeço, Oficial Charon.",
  ui_story_3_1_B53_dialog_content = "... Humpf.",
  ui_story_3_1_B55_dialog_content = "Aquela farsa... foi mesmo necessária?",
  ui_story_3_1_B56_dialog_content = "Não sei, mas Charon parecia estar curtindo...",
  ui_story_3_1_B57_dialog_content = "Precisávamos de uma razão para partir antes que sua superior chegasse.",
  ui_story_3_1_B58_dialog_content = "Sim... Hiiro...",
  ui_story_3_1_B59_dialog_content = "*Suspira* Não quero nem pensar em como a Comandante Hiiro vai reagir quando descobrir que saímos sem permissão.",
  ui_story_3_1_69_option_content = "Já se arrependeu?",
  ui_story_3_1_70_dialog_content = "Não!",
  ui_story_3_1_71_dialog_content = "Vamos torcer para que Hiiro seja uma superior compreensiva.",
  ui_story_3_1_72_dialog_content = "Bom, agora que você falou, tô me arrependendo um pouquinho.",
  ui_story_3_1_73_option_content = "Espero que tenhamos tomado a decisão certa.",
  ui_story_3_1_74_dialog_content = "Certa ou não... acho que não cabe a nós decidir isso...",
  ui_story_3_1_76_dialog_content = "Ah, não. A Comandante Hiiro vai me matar!",
  ui_story_3_1_77_dialog_content = "Destino: sinal do Celestita Desconhecido. Contagem regressiva!",
  ui_story_3_1_78_dialog_content = "5, 4, 3, 2...",
  ui_story_3_1_79_dialog_content = "1! Decolar!",
  ui_story_3_1_80_dialog_content = "Aqui está o relatório que você pediu.",
  ui_story_3_1_81_dialog_content = "Deixe-me ver... Urrum, urrum. Precisa melhorar aqui...",
  ui_story_3_1_82_dialog_content = "Fale mais sobre Vice e o Celestita, e conecte suas ações ao que aconteceu aqui.",
  ui_story_3_1_83_dialog_content = "Ah, sim, senhor!",
  ui_story_3_1_84_dialog_content = "Acredite, você não vai querer saber como aquela mulher se importa com detalhes.",
  ui_story_3_1_85_dialog_content = "Isso é diferente do que imaginei, Charon.",
  ui_story_3_1_86_dialog_content = "...",
  ui_story_3_1_87_dialog_content = "Se está se referindo à Subcidade 28, é essa ruína aos seus pés, Comandante da Legião.",
  ui_story_3_1_88_dialog_content = "Não repita coisas que eu já sei, Charon. Onde está a Colossus que você mencionou no relatório?",
  ui_story_3_1_89_dialog_content = "O pássaro voou com estilo.",
  ui_story_3_1_90_dialog_content = "Onde está minha subordinada?",
  ui_story_3_1_91_dialog_content = "Ela partiu. Está a bordo da Colossus.",
  ui_story_3_1_92_dialog_content = "Supervisor Charon da Subcidade 28, está dizendo que minha soldado desafiou uma ordem?",
  ui_story_3_1_93_dialog_content = "Só estou dizendo que ela está com o Celestita.",
  ui_story_3_1_94_dialog_content = "Celestita...",
  ui_story_3_1_95_dialog_content = "Oficial, nós... Desculpe pela intromissão, Comandante da Legião!",
  ui_story_3_1_96_dialog_content = "Fale.",
  ui_story_3_1_97_dialog_content = "Sim! Terminamos de avaliar os danos e a condição dos civis. Aguardamos sua próxima ordem!",
  ui_story_3_1_98_dialog_content = "Siga o plano e evacue todos para a Subcidade mais próxima. Mandarei os Batalhões 1 e 3 escoltá-los.",
  ui_story_3_1_99_dialog_content = "Podemos proteger os civis nós mesmos. Não se preocupe com isso...",
  ui_story_3_1_100_dialog_content = "O restante, me siga.",
  ui_story_3_1_101_dialog_content = "...",
  ui_story_3_1_102_dialog_content = "Ranzinza como sempre, Hiiro.",
  ui_story_3_1_103_dialog_content = "O que está fazendo?",
  ui_story_3_1_104_dialog_content = "Eu?",
  ui_story_3_1_A4_dialog_content = "O que é isso, um utensílio de cozinha?",
  ui_story_3_1_A5_dialog_content = "... É um transmissor compacto de longa distância.",
  ui_story_3_1_105_dialog_content = "É um dispositivo de Illumina? Por que não usou ele antes?",
  ui_story_3_1_106_dialog_content = "Charon me deu isso em segredo há algum tempo.",
  ui_story_3_1_107_dialog_content = "Charon...",
  ui_story_3_1_108_dialog_content = "Certo, como isso funciona...? Cara, isso é difícil!",
  ui_story_3_1_109_dialog_content = "Acho que você cruza aqui, gira aqui e ajusta a frequência...",
  ui_story_3_1_111_dialog_content = "Arrá, está funcionando!",
  ui_story_3_1_112_dialog_content = "Informe sua localização atual.",
  ui_story_3_1_113_dialog_content = "Sim..! Comandante Hiiro?",
  ui_story_3_1_114_dialog_content = "Parece que você ainda reconhece sua superior, Tenente. Por que saiu sem autorização?",
  ui_story_3_1_115_dialog_content = "Me desculpe. A Subcidade 28 foi invadida por Eclipsitas, e a sequência de autodestruição foi iniciada.",
  ui_story_3_1_116_dialog_content = "Não repita coisas que eu já sei. Estou perguntando por que partiu com a Colossus sem autorização.",
  ui_story_3_1_117_dialog_content = "A Colossus...!",
  ui_story_3_1_118_dialog_content = "Bem, senhora, a Colossus não pertence a você. Vamos deixar isso claro.",
  ui_story_3_1_119_dialog_content = "Então, é você...",
  ui_story_3_1_120_dialog_content = "Sim, sou o dono dessa Colossus.",
  ui_story_3_1_122_dialog_content = "Por causa da sua preciosa Colossus, a Subcidade 28 foi destruída.",
  ui_story_3_1_A6_dialog_content = "Não acha que deve explicações à Federação Illumina?",
  ui_story_3_1_123_dialog_content = "Sinto muito, mas encontrarei uma forma de recompensar Illumina!",
  ui_story_3_1_124_dialog_content = "Nozard mencionou alguém chamada <color=#FFB400>Schummer</color>.",
  ui_story_3_1_125_dialog_content = "Nozard, Schummer... não me interesso por esses nomes esquisitos.",
  ui_story_3_1_126_dialog_content = "Mas tudo isso... e a Subcidade 28 devem ter alguma ligação com Schummer!",
  ui_story_3_1_127_dialog_content = "Ah?",
  ui_story_3_1_128_dialog_content = "Senhora, temos pistas de mais um Celestita que pode ter outra Colossus!",
  ui_story_3_1_129_dialog_content = "O que você disse?!",
  ui_story_3_1_130_dialog_content = "Mas esse Celestita e sua Colossus estão em perigo!",
  ui_story_3_1_131_dialog_content = "PlayerName pretende fazer alguma coisa a respeito, então pensei...",
  ui_story_3_1_132_dialog_content = "Pensei que deveria ajudá-lo! Isso também é importante para Illumina!",
  ui_story_3_1_133_dialog_content = "Devo lembrar a você, Tenente...",
  ui_story_3_1_A7_dialog_content = "Você é uma soldado da Federação Illumina, então pense bem!",
  ui_story_3_1_134_dialog_content = "Desculpa, senhora. Eu tentei impedir PlayerName, mas acho que ele está certo dessa vez!",
  ui_story_3_1_135_dialog_content = "Vice...?",
  ui_story_3_1_136_dialog_content = "PlayerName está certo... dessa vez.",
  ui_story_3_1_137_dialog_content = "Vou resgatar o Celestita e investigar tudo isso a fundo.",
  ui_story_3_1_A8_dialog_content = "...",
  ui_story_3_1_A9_dialog_content = "...",
  ui_story_3_1_138_dialog_content = "*Suspira*. Você tem certeza?",
  ui_story_3_1_139_dialog_content = "Não vou deixar os Eclipsitas se safarem de novo!",
  ui_story_3_1_140_dialog_content = "Me envie as coordenadas, já.",
  ui_story_3_1_141_dialog_content = "Seu sinal está fraco. Não podemos determinar a sua localização.",
  ui_story_3_1_142_dialog_content = "E Vice, não se esqueça de qual lado você está e não faça nenhuma besteira.",
  ui_story_3_1_144_dialog_content = "Acabamos de perder o sinal!",
  ui_story_3_1_145_dialog_content = "Sinto uma forte e dominante presença, diferente de tudo que já encontramos antes.",
  ui_story_3_1_146_dialog_content = "O Celestita mencionou <color=#FFB400>Aviduz</color> quando pediu ajuda.",
  ui_story_3_1_A10_dialog_content = "É aqui?",
  ui_story_3_1_147_dialog_content = "Não sei, PlayerName, mas é uma força poderosa, que está...",
  ui_story_3_1_148_dialog_content = "Sim, está ali!",
  ui_story_3_1_A11_dialog_content = "Soroz encontrou a localização, Vice. Aviduz pode estar lá dentro.",
  ui_story_3_1_A12_dialog_content = "Não temos muitas informações, tome cuidado.",
  ui_story_3_1_149_dialog_content = "Aviduz? É a Colossus?",
  ui_story_3_1_150_dialog_content = "Não tenho certeza.",
  ui_story_3_1_151_dialog_content = "É...",
  ui_story_3_1_152_dialog_content = "Se eu te parar agora, PlayerName, você vai me ouvir?",
  ui_story_3_1_153_dialog_content = "Sinto muito, Soroz.",
  ui_story_3_1_154_dialog_content = "Foi o que eu pensei...",
  ui_story_3_1_155_dialog_content = "Pouse agora e se prepare pra batalha.",
  ui_story_3_1_A13_dialog_content = "Parece que temos um grande número de Eclipsitas esperando por nós!",
  ui_story_3_3_1_dialog_content = "Tem alguém vindo.",
  ui_story_3_3_2_dialog_content = "Quem seria tão tolo a ponto de me incomodar?",
  ui_story_3_3_3_dialog_content = "Você quer que eu resolva isso?",
  ui_story_3_3_4_dialog_content = "Agora não. Viemos aqui por algo mais importante.",
  ui_story_3_3_5_dialog_content = "Schummer... O que você está fazendo aqui?",
  ui_story_3_3_6_dialog_content = "Ora, se não é o meu adorável irmão! Pensei que você iria fugir, como da outra vez.",
  ui_story_3_3_7_dialog_content = "Mestre dos <color=#FFB400>Mantiz</color>.",
  ui_story_3_3_8_dialog_content = "Espera, não! Eu deveria te chamar pelo seu apelido fofo, <color=#FFB400>Mendelson</color>, o covarde.",
  ui_story_3_3_9_dialog_content = "Argh, não acredito que a primeira coisa que eu sinto ao acordar é o seu cheiro horrível, Schummer.",
  ui_story_3_3_10_dialog_content = "Ou você prefere <color=#FFB400>Mestre do Aviduz</color>?",
  ui_story_3_3_11_dialog_content = "Já que você é meu irmão, vou facilitar pra você.",
  ui_story_3_3_12_dialog_content = "Me leve até <color=#FFB400>aquela coisa</color>.",
  ui_story_3_3_A1_dialog_content = "Não sei o que você quer dizer. Não tenho nada aqui, Schummer, a não ser histórias chatas...",
  ui_story_3_3_A2_dialog_content = "E alguns podres. Não pense que eu não sei.",
  ui_story_3_3_A3_dialog_content = "Me dê o <color=#FFB400>Módulo do Tanque Pensante</color>. Eu sei que você tem um aí.",
  ui_story_3_3_A4_dialog_content = "... O que você vai fazer com ele?",
  ui_story_3_3_A5_dialog_content = "Ah, só quero algumas... informações que me interessam.",
  ui_story_3_3_A6_dialog_content = "Não, se é esse o seu plano, eu nunca vou concordar com isso.",
  ui_story_3_3_A7_dialog_content = "O que você está fazendo é expressamente proibido e contra os princípios das Colossi!",
  ui_story_3_3_13_dialog_content = "E você quer que eu te leve até ele?",
  ui_story_3_3_14_dialog_content = "Você não deve ter entendido o objetivo de Mantiz, Schummer.",
  ui_story_3_3_15_dialog_content = "Para com isso, Mendelson, não seja tão mesquinho.",
  ui_story_3_3_16_dialog_content = "Não estamos do mesmo lado? Caso contrário, você não teria sobrevivido até agora.",
  ui_story_3_3_17_dialog_content = "Esse é o poder que um Celestita jamais pode possuir. Você e eu, nós somos iguais.",
  ui_story_3_3_18_dialog_content = "E desde então, não passei um dia sem me arrepender, Schummer... Se ao menos eu soubesse...",
  ui_story_3_3_19_dialog_content = "Hã...? Sua saúde parece estar piorando...",
  ui_story_3_3_A8_dialog_content = "Pobre Mendelson... Parece que você não aceitou a bênção completamente.",
  ui_story_3_3_20_dialog_content = "Me dói ver você lutando apenas pra falar!",
  ui_story_3_3_22_dialog_content = "Onde meu martelo cair, a morte será lançada. Pare agora mesmo.",
  ui_story_3_3_23_dialog_content = "Entendeu? Passe pela linha e você tá morta.",
  ui_story_3_3_24_dialog_content = "Eu não tenho nenhum espírito de luta, mas o Mantiz não deve ser ridicularizado...",
  ui_story_3_3_25_dialog_content = "Escudos humanos. É isso que os covardes usam pra se proteger?",
  ui_story_3_3_26_dialog_content = "Não me subestime, Schummer!",
  ui_story_3_3_27_dialog_content = "Devo cuidar disso, Senhora?",
  ui_story_3_3_A9_dialog_content = "Pela última vez, não! Isso não é da sua conta!",
  ui_story_3_3_28_dialog_content = "Gatinho e cãozinho leais. Que apropriado, Mendelson.",
  ui_story_3_3_29_dialog_content = "Mas é por isso também que você sempre foi um covarde inútil.",
  ui_story_3_3_30_dialog_content = "Que insolente!",
  ui_story_3_3_31_dialog_content = "Basta. Ajoelhe!",
  ui_story_3_3_32_dialog_content = "Desativado! Desativado! Ordem de prioridade máxima recebida, execução obrigatória!",
  ui_story_3_3_33_dialog_content = "Filex! Algo está acontecendo com ele, mestre!",
  ui_story_3_3_34_dialog_content = "Aaai...",
  ui_story_3_3_35_dialog_content = "Vani, Filex... O que é isso? O que você fez com eles, Schummer!?",
  ui_story_3_3_36_dialog_content = "Você tem uns “brinquedos” divertidos, Mendelson.",
  ui_story_3_3_37_dialog_content = "Então, eu apenas decidi que seriam meus.",
  ui_story_3_3_38_dialog_content = "Não foram apenas o seu corpo e a sua alma que se corromperam, Schummer... Você se tornou algo totalmente diabólico!",
  ui_story_3_3_39_dialog_content = "Obrigada pelo elogio, mas isso não muda o que eu quero fazer.",
  ui_story_3_3_40_dialog_content = "Me devolva os dois, seu monstro!",
  ui_story_3_3_41_dialog_content = "Bem, isso eu posso fazer pra você! Filex, Vani... São os seus nomes, certo?",
  ui_story_3_3_42_dialog_content = "Sim!",
  ui_story_3_3_43_dialog_content = "Agarrem o Mendelson.",
  ui_story_3_3_44_dialog_content = "O quê?!",
  ui_story_3_3_45_dialog_content = "Putz, ele escapou de novo!",
  ui_story_3_3_46_dialog_content = "“Não me subestime,” ele disse... Vejo que ele ainda é o covarde de antes.",
  ui_story_3_3_47_dialog_content = "O que devo fazer em seguida, Senhora?",
  ui_story_3_3_48_dialog_content = "Vá atrás dele e traga-o de volta...",
  ui_story_3_3_49_dialog_content = "Para que eu possa dar uma boa olhada em sua cara.",
  ui_story_3_3_50_dialog_content = "Sim!",
  ui_story_3_3_51_dialog_content = "Sim!",
  ui_story_3_3_52_dialog_content = "Não posso ser capturado... Ei, eu sei que você pode me ouvir... Venha, rápido...",
  ui_story_3_3_53_dialog_content = "Eu posso te ouvir! Onde você está? Você é um Celestita também, né?",
  ui_story_3_3_54_dialog_content = "Aviduz está ainda mais forte...",
  ui_story_3_3_55_dialog_content = "Ela não pode levar o Módulo do Tanque Pensante, não posso deixar o... segredo em suas mãos.",
  ui_story_3_3_56_dialog_content = "Você não pode sair do meu lado nunca. Me dói ver você se esforçando apenas para falar.",
  ui_story_3_3_57_dialog_content = "Você não vai escapar dessa, Schummer, nunca...",
  ui_story_3_3_58_dialog_content = "Você não pode sair do meu lado.",
  ui_story_3_3_59_dialog_content = "Mas você venceu, não venceu? Desde o início.",
  ui_story_3_3_60_dialog_content = "Você usou um poder sinistro para me corromper, me impedindo de te impedir...",
  ui_story_3_3_61_dialog_content = "Não, eu preciso te deter... É o meu dever e o dos Mantiz.",
  ui_story_3_3_62_dialog_content = "Você sempre foi um covarde chorão.",
  ui_story_3_3_63_dialog_content = "Devo viver ou morrer...?",
  ui_story_3_3_64_dialog_content = "(Falando em Eclipsiano) Ali! Peguem eles!",
  ui_story_3_3_65_dialog_content = "Você está aí, Celestita? Eu tenho que continuar correndo!",
  ui_story_3_3_66_dialog_content = "Depressa, por favor... Por mim, e para o seu próprio bem!",
  ui_story_3_3_A10_dialog_content = "Ele está sendo perseguido por Eclipsitas, e eu não consigo identificar sua localização exata...",
  ui_story_3_3_A11_dialog_content = "Entendi. Vamos acelerar, então!",
  ui_story_3_3_A12_dialog_content = "Há cada vez mais Eclipsitas à frente, PlayerName. Por favor, se mantenha atento!",
  ui_story_3_7_1_dialog_content = "Esse lugar também está cheio de Eclipsitas. Você tá bem, PlayerName?",
  ui_story_3_7_2_dialog_content = "Eu tô bem.",
  ui_story_3_7_3_dialog_content = "Será que aquele Celestita que você mencionou...",
  ui_story_3_7_4_dialog_content = "Espera!",
  ui_story_3_7_5_dialog_content = "Não posso deixar que me peguem... Não...",
  ui_story_3_7_6_dialog_content = "Entramos! Onde você está? Você pode me ouvir?",
  ui_story_3_7_7_dialog_content = "Venha até mim! Eu posso te proteger.",
  ui_story_3_7_8_dialog_content = "Companheiro Celestita, é você! Você veio!",
  ui_story_3_7_9_dialog_content = "Desculpa a demora!! Você pode me ouvir?",
  ui_story_3_7_10_dialog_content = "Claro, companheiro Celestita, claro. Posso até te ver. É você...?",
  ui_story_3_7_16_dialog_content = "Quem está aí?",
  ui_story_3_7_17_dialog_content = "*Cof Cof* Inimigo, atrás...",
  ui_story_3_7_18_dialog_content = "Você está bem? Que bom, ainda bem que não nos atrasamos!",
  ui_story_3_7_A5_dialog_content = "Esse é...?",
  ui_story_3_7_A6_dialog_content = "Sim, Vice. Ele é o Celestita que pediu a nossa ajuda!",
  ui_story_3_7_19_dialog_content = "Ele tá bastante machucado, PlayerName, e esses ferimentos não foram causados por Eclipsitas.",
  ui_story_3_7_20_dialog_content = "Quem fez isso com você?",
  ui_story_3_7_22_dialog_content = "Alvo Mendelson encontrado!",
  ui_story_3_7_23_dialog_content = "Executar comando de captura!",
  ui_story_3_7_24_dialog_content = "Filex, Vani...",
  ui_story_3_7_25_dialog_content = "Proteja-se, companheiro Celestita!",
  ui_story_3_7_26_dialog_content = "Ele é seu, PlayerName. Nós cuidaremos da luta!",
  ui_story_3_7_27_dialog_content = "Filex, Vani...",
  ui_story_3_7_28_dialog_content = "Sinto muito... No fim, eu não pude fazer nada...",
  ui_story_3_7_29_dialog_content = "Eles não parecem ser Eclipsitas. O que tá acontecendo?",
  ui_story_3_7_30_dialog_content = "Eles eram meus guardas, parte do mecanismo de defesa dessa Colossus.",
  ui_story_3_7_31_dialog_content = "Mas por que eles te atacaram?",
  ui_story_3_7_32_dialog_content = "Foi ela... O poder dela os dominou.",
  ui_story_3_7_33_dialog_content = "Não acredito...",
  ui_story_3_7_34_dialog_content = "Meus sentimentos...",
  ui_story_3_7_35_dialog_content = "Nunca pensei que seria como naquela época...",
  ui_story_3_7_36_dialog_content = "Qual é o seu nome, companheiro Celestita?",
  ui_story_3_7_37_dialog_content = "Mendelson, Mestre dos Mantiz.",
  ui_story_3_7_38_dialog_content = "Mantiz... Isso me soa familiar. Infelizmente, eu já me esqueci de muita coisa...",
  ui_story_3_7_40_dialog_content = "Naquele dia, para proteger a Spark, as Colossi que restaram seguiram por caminhos diferentes.",
  ui_story_3_7_41_dialog_content = "Parece que Soroz te protegeu por todos esses anos... Isso é ótimo.",
  ui_story_3_7_42_dialog_content = "Há quanto tempo você está aqui? Outros Celestitas sobreviveram?",
  ui_story_3_7_43_dialog_content = "Por que você tem essa aparência? E o que é Aviduz?",
  ui_story_3_7_44_dialog_content = "*Cof Cof* Eu... *Cof Cof*",
  ui_story_3_7_45_dialog_content = "Ele tá machucado, PlayerName. Deixa ele respirar primeiro...",
  ui_story_3_7_46_dialog_content = "Me perdoe, eu não sou como você... PlayerName, Soroz...",
  ui_story_3_7_47_dialog_content = "Você ainda está vivo. Isso quer dizer que Soroz cumpriu seu dever de proteger os Celestitas.",
  ui_story_3_7_48_dialog_content = "Mas eu não consegui completar a minha única missão...",
  ui_story_3_7_49_dialog_content = "Desculpa, mas eu não entendi.",
  ui_story_3_7_50_dialog_content = "Soroz não te contou, PlayerName?",
  ui_story_3_7_51_dialog_content = "Infelizmente, eu perdi a minha memória na colisão.",
  ui_story_3_7_52_dialog_content = "Além da ordem de servir e proteger PlayerName, eu não me lembro de muita coisa.",
  ui_story_3_7_53_dialog_content = "Soroz sofreu tremendos danos naquele dia.",
  ui_story_3_7_54_dialog_content = "É mesmo...? *Cof Cof* Eu pressenti a sua conversa...",
  ui_story_3_7_55_dialog_content = "Não tenho certeza se isso foi algo bom ou ruim...",
  ui_story_3_7_56_dialog_content = "Então, o que realmente aconteceu aqui?",
  ui_story_3_7_57_dialog_content = "No Mantiz, há um item muito importante chamado <color=#FFB400>Módulo do Tanque Pensante</color>...",
  ui_story_3_7_A1_dialog_content = "Ele contém uma grande quantidade de informações, desde história Celestita até clássicos Aurorianos...",
  ui_story_3_7_58_dialog_content = "Possui os mais gloriosos hinos, assim como os mais sombrios sussurros do abismo...",
  ui_story_3_7_60_dialog_content = "Mas o que Aviduz—Schummer quer é a sua parte mais insignificante...",
  ui_story_3_7_61_dialog_content = "Então, Schummer tá aqui?!",
  ui_story_3_7_62_dialog_content = "Sim. Nesse momento, ela está indo para o meu núcleo para roubar o Módulo do Tanque Pensante.",
  ui_story_3_7_A2_dialog_content = "E usá-lo para... Não, eu não posso te dizer o que nunca deve ser revelado!",
  ui_story_3_7_63_dialog_content = "Então, temos que detê-la! Me ajude, Vice!",
  ui_story_3_7_64_dialog_content = "Peça ao Celestita pra indicar o caminho. Eu adoraria conhecer a responsável pela destruição da Subcidade 28.",
  ui_story_3_7_65_dialog_content = "Você esteve esperando por esse dia também, não é, PlayerName?",
  ui_story_3_7_A3_dialog_content = "Exatamente. Mal posso esperar para ter todas as minhas perguntas respondidas.",
  ui_story_3_7_A4_dialog_content = "Cuidado, PlayerName... Ela...",
  ui_story_3_7_66_dialog_content = "*Cof Cof*...",
  ui_story_3_7_67_dialog_content = "Você está piorando. O que eu devo fazer?",
  ui_story_3_7_68_dialog_content = "Não podemos deixá-lo aqui, PlayerName, mas temos que seguir em frente...",
  ui_story_3_7_69_dialog_content = "...",
  ui_story_3_7_70_dialog_content = "Não esquenta, companheiro Celestita.",
  ui_story_3_7_71_dialog_content = "Eu vou ficar bem. Vai ser bem mais fácil se eu guiar vocês.",
  ui_story_3_7_72_dialog_content = "Como mestre da Mantiz, é meu dever impedi-la de pegar o Módulo do Tanque Pensante...",
  ui_story_3_7_73_dialog_content = "Obrigado, Mendelson. Quando isso acabar, você precisa me contar tudo sobre os Celestitas!",
  ui_story_3_7_74_dialog_content = "Claro, PlayerName. Eu prometo que te contarei tudo sobre Eraveil...",
  ui_story_3_7_75_dialog_content = "Então, mostre o caminho, por favor, Mendelson!",
  ui_story_3_7_76_dialog_content = "Vamos deter a Schummer!",
  ui_story_3_9_A1_dialog_content = "(O que estou fazendo... Eu tenho uma chance de fugir, mesmo assim escolho voltar...)",
  ui_story_3_9_A2_dialog_content = "(É impossível vencermos, não é...? Então, por que lutar...)",
  ui_story_3_9_A3_dialog_content = "(Corra, Mendelson! Esqueça o seu suposto dever, pelo bem da sua própria vida...)",
  ui_story_3_9_2_dialog_content = "Pelo bem da minha própria vida...?",
  ui_story_3_9_3_dialog_content = "Por que você está parando? Já chegamos?",
  ui_story_3_9_4_dialog_content = "Tem certeza disso? Ainda há tempo para voltar atrás, se você quiser escapar...",
  ui_story_3_9_5_dialog_content = "Schummer não é uma inimiga qualquer. Veja o que ela fez com Filex e Vani...",
  ui_story_3_9_6_dialog_content = "Eles eram meus leais guardiões, mas agora querem me ver morto.",
  ui_story_3_9_7_dialog_content = "Ela é capaz de muito mais do que podemos imaginar.",
  ui_story_3_9_8_dialog_content = "Por que você quer confrontá-la, se é incapaz de combater, PlayerName?",
  ui_story_3_9_10_dialog_content = "Eu a procurei pois tenho muitas perguntas para ela, sobre a Subcidade 28, 17 anos atrás...",
  ui_story_3_9_A4_dialog_content = "E agora, ela está indo incansavelmente atrás de outro Celestita...",
  ui_story_3_9_13_dialog_content = "Eu não posso ir embora! Preciso detê-la!",
  ui_story_3_9_14_dialog_content = "É fácil fugir, mas para onde podemos correr?",
  ui_story_3_9_15_dialog_content = "Há lugares aos quais jamais poderemos voltar, Mendelson. Se estamos indo direto para o Portão do Inferno...",
  ui_story_3_9_A5_dialog_content = "Então, vamos acabar com aquele ser desprezível juntos!",
  ui_story_3_9_16_dialog_content = "Agora eu entendo. No que eu estava pensando?",
  ui_story_3_9_18_dialog_content = "Eraveil foi destruída. Todos os meus amigos e entes queridos foram massacrados pelos Eclipsitas.",
  ui_story_3_9_19_dialog_content = "Só eu, tímido e covarde, fugi com Mantiz… apenas para me afastar em vergonha.",
  ui_story_3_9_20_dialog_content = "E agora, não posso acreditar que estou tendo o mesmo pensamento.",
  ui_story_3_9_21_dialog_content = "Mendelson...",
  ui_story_3_9_22_dialog_content = "Se eu não continuar tentando, então não sou diferente de quem era. Nós...",
  ui_story_3_9_23_dialog_content = "Mendelson!",
  ui_story_3_9_24_dialog_content = "Ah... Meu...",
  ui_story_3_9_25_dialog_content = "Por que você ficou de repente tão agoniado?",
  ui_story_3_9_26_dialog_content = "Já começou? Eu sei que <color=#FFB400>está com você</color>, Schummer!",
  ui_story_3_9_27_dialog_content = "Posso sentir o seu imenso poder, capaz de enterrar Mantiz na completa escuridão!",
  ui_story_3_9_28_dialog_content = "Extinguindo até mesmo o último brilho de luz...",
  ui_story_3_9_29_dialog_content = "Posso fazer algo por você, Mendelson?",
  ui_story_3_9_30_dialog_content = "Não... se preocupe! Isso na verdade dissipou o que restava da minha covardia.",
  ui_story_3_9_A8_dialog_content = "Vamos, PlayerName, e seus amigos também. Me sigam.",
  ui_story_3_9_A9_dialog_content = "Vamos matar os Eclipsitas diante de nós até alcançarmos as profundezas da escuridão.",
  ui_story_3_9_A10_dialog_content = "E além disso, cuidado! Os inimigos estão se aproximando!",
  ui_story_3_9_31_dialog_content = "Ah, Mendelson, meu querido irmão, pare com seu esforço inútil...",
  ui_story_3_9_32_dialog_content = "De que adianta escondê-lo nas profundezas? Eu o encontrei mesmo assim—o <color=#FFB400>Módulo do Tanque Pensante</color>!",
  ui_story_3_9_33_dialog_content = "Não é tão difícil quanto eu pensava. Na verdade, é até um pouco entediante.",
  ui_story_3_9_34_dialog_content = "Vamos lá, me mostre o seu segredo...",
  ui_story_3_9_A11_dialog_content = "Droga! Está criptografado. Acho que vai demorar um pouco.",
  ui_story_3_9_35_dialog_content = "Meu mestre espera por você, Senhora...",
  ui_story_3_9_36_dialog_content = "Quanto tempo mais você vai gastar com isso?",
  ui_story_3_9_37_dialog_content = "Só mais um pouco pra terminar...",
  ui_story_3_9_38_dialog_content = "Só mais um pouco e eu terei tudo, inclusive o “segredo”.",
  ui_story_3_9_39_dialog_content = "Através de mim, eles se tornarão um só com a minha <color=#FFB400>Colossus Negra</color> e se tornarão um marco da evolução!",
  ui_story_3_9_41_dialog_content = "A qualquer segundo agora, Schummer.",
  ui_story_3_9_42_dialog_content = "(Falando em eclipsiano) Vão, meus camaradas.",
  ui_story_3_9_43_dialog_content = "É necessário enviar tantos?",
  ui_story_3_9_44_dialog_content = "Está longe de ser suficiente. Os Eclipsitas disseram que os brinquedos que você roubou do Mendelson foram derrotados...",
  ui_story_3_9_45_dialog_content = "Pelo mestre de Soroz e seu companheiro Celestita.",
  ui_story_3_9_47_dialog_content = "Que oportuno. Depois de obter o que desejo, acabarei com todos eles de uma só vez.",
  ui_story_3_9_48_dialog_content = "Rancores podem ser resolvidos a qualquer hora, mas um plano é um plano, Schummer. Não estrague tudo.",
  ui_story_3_9_50_dialog_content = "Você acha que eu posso conter isso? Quando o verme que escapou estiver finalmente ao meu alcance?",
  ui_story_3_9_51_dialog_content = "Eu odeio caos, desordem e improviso.",
  ui_story_3_9_52_dialog_content = "E eu não gosto de lutar. Não tenho interesse em esforços tão vulgares.",
  ui_story_3_9_53_dialog_content = "...",
  ui_story_3_9_54_dialog_content = "Tá bom, essa conversa acabou.",
  ui_story_3_9_56_dialog_content = "Tabaad!",
  ui_story_3_9_57_dialog_content = "Eu me escondi nas sombras por muito tempo, mestre. Devo agir?",
  ui_story_3_9_58_dialog_content = "Aja como lhe parecer mais adequado.",
  ui_story_3_9_59_dialog_content = "Sim, mestre.",
  ui_story_3_9_61_dialog_content = "Eu os farei em pedaços com as minhas próprias mãos, submergindo sua luz patética na escuridão infinita...",
  ui_story_3_9_A12_dialog_content = "Você sente isso, PlayerName? Os Eclipsitas estão se concentrando em nossa direção.",
  ui_story_3_9_A13_dialog_content = "Sim, e em massa. Mas eles não vão conseguir nos deter.",
  ui_story_3_9_A14_dialog_content = "Isso mesmo. Vamos seguir em frente e matar todos os Eclipsitas em nosso caminho!",
  ui_story_3_12_2_dialog_content = "Estamos aqui.",
  ui_story_3_12_3_dialog_content = "O Módulo do Tanque Pensante está aí?",
  ui_story_3_12_4_dialog_content = "Sim. Fique de olho caso Schummer apareça.",
  ui_story_3_12_5_dialog_content = "Vamos acabar com isso juntos, Mendelson.",
  ui_story_3_12_6_dialog_content = "Sim, PlayerName! Vamos deter...",
  ui_story_3_12_7_dialog_content = "Calma, Mendelson. Seu estado é...",
  ui_story_3_12_9_dialog_content = "Não se preocupe com isso. É o <color=#FFB400>poder da escuridão</color>... Ele não pôde ser controlado e se espalhou pelo meu corpo.",
  ui_story_3_12_10_dialog_content = "Como... como isso aconteceu?",
  ui_story_3_12_12_dialog_content = "Naquele dia, 17 anos atrás, eu aceitei o <color=#FFB400>Poder dos Eclipsitas</color> para conseguir sobreviver.",
  ui_story_3_12_A1_dialog_content = "<color=#FFB400>Assim como Schummer fez</color>. Porém, meu corpo está se deteriorando.",
  ui_story_3_12_A2_dialog_content = "Isso aconteceu porque minha fé não foi forte o suficiente, ou porque eu sempre me recusei a viver assim?",
  ui_story_3_12_15_dialog_content = "O sofrimento é apenas temporário, criança. Não tome decisões das quais se arrependerá.",
  ui_story_3_12_16_dialog_content = "Desculpa, professor. É tarde demais. Eu quero sobreviver...",
  ui_story_3_12_17_dialog_content = "Aceitar o poder Eclipsita só para sobreviver? Mas por quê?",
  ui_story_3_12_18_dialog_content = "Irônico, não é? Mesmo sendo uma abominação, eu mantive meu dever como Mestre da Mantiz.",
  ui_story_3_12_A3_dialog_content = "Mas quem eu sou? O que eu sou?",
  ui_story_3_12_A4_dialog_content = "Ainda há esperança. Se derrotarmos Schummer, prometo que acharei um jeito de você voltar ao normal!",
  ui_story_3_12_A5_dialog_content = "Não importa. Já é tarde demais pra mim. O destino age de maneira misteriosa.",
  ui_story_3_12_19_dialog_content = "Antes, confiava no poder da escuridão pra ficar inativo nesse escuro subterrâneo, sem ser detectado por muitos anos...",
  ui_story_3_12_20_dialog_content = "Assim como todas as outras vezes, eu pensei que poderia fugir com o rabo entre as pernas...",
  ui_story_3_12_21_dialog_content = "E daí me encolher em outro canto escuro e continuar a minha mísera existência.",
  ui_story_3_12_22_dialog_content = "Mas eu encontrei você! Talvez seja hora de ser corajoso pelo menos uma vez na minha vida.",
  ui_story_3_12_23_dialog_content = "Não vou correr dessa vez! Vamos salvar o nosso futuro desse destino terrível!",
  ui_story_3_13_1_dialog_content = "<color=#e8d9bb>Fora dos destroços da Mantiz</color>",
  ui_story_3_13_2_dialog_content = "Estão aqui, Tabaad?",
  ui_story_3_13_3_dialog_content = "Três almas inquietas, uma à beira da morte.",
  ui_story_3_13_4_dialog_content = "Tá bom. Cuide disso da maneira que achar melhor.",
  ui_story_3_13_5_dialog_content = "Sim. Que a Mãe seja minha testemunha, não pouparei esforços. Sob a Aurora, só o Eclipse é eterno.",
  ui_story_3_13_6_dialog_content = "Esse é o cara?",
  ui_story_3_13_8_dialog_content = "Por que demorou tanto? Você perdeu um belo de um show.",
  ui_story_3_13_9_dialog_content = "Espera, é só você, sozinho?",
  ui_story_3_13_10_dialog_content = "Mesmo sozinho, sou mais que suficiente.",
  ui_story_3_13_11_dialog_content = "Suficiente?",
  ui_story_3_13_12_dialog_content = "PlayerName, o último dos Celestitas. Você é diferente dessa Aurorian. Você poderia ter escolhido um caminho melhor.",
  ui_story_3_13_13_dialog_content = "Como você sabia o nome do PlayerName?",
  ui_story_3_13_14_dialog_content = "Porque temos todo o conhecimento, visão e futuro que procura.\nPlayerName, você não almejou sempre por eles?",
  ui_story_3_13_15_dialog_content = "Não tente esconder, PlayerName. Eu entendo os desejos mais íntimos de vocês, Celestitas. Isso é o que desejam...",
  ui_story_3_13_16_dialog_content = "PlayerName?",
  ui_story_3_13_17_dialog_content = "Você deseja ter um grande poder para não mais precisar dos Aurorians.",
  ui_story_3_13_18_dialog_content = "Eu...",
  ui_story_3_13_19_dialog_content = "Chegue mais perto. Sim, mais perto. Você será como o meu mestre, <color=#FFB400>venha para o Eclipse</color>!",
  ui_story_3_13_20_dialog_content = "O Eclipse?",
  ui_story_3_13_21_dialog_content = "Nada disso!",
  ui_story_3_13_22_dialog_content = "O cão chorão está de volta, com o rabo entre as patas.",
  ui_story_3_13_23_dialog_content = "Você está com medo? Onde está o seu mestre?",
  ui_story_3_13_A1_dialog_content = "(O Módulo do Tanque Pensante e Schummer desapareceram!)",
  ui_story_3_13_24_dialog_content = "Você me surpreende, Mendelson.",
  ui_story_3_13_25_dialog_content = "Você se acovardou dentro da Colossus como um cão imundo enquanto testemunhava o massacre do seu povo...",
  ui_story_3_13_26_dialog_content = "Você se fechou pro mundo, negando-se a enfrentar a realidade. Você tá mesmo pronto pra enfrentar seu pior pesadelo?",
  ui_story_3_13_27_dialog_content = "Que pena. Sua tremedeira revela quão fraco e inútil você é... Patético.",
  ui_story_3_13_28_dialog_content = "Cala a boca e deixa o Mendelson em paz!",
  ui_story_3_13_29_dialog_content = "Tudo bem?",
  ui_story_3_13_30_dialog_content = "Desculpa, parece que o verdadeiro culpado escapou.",
  ui_story_3_13_31_dialog_content = "E o Módulo do Tanque Pensante foi roubado também. Ugh, já era pra mim...",
  ui_story_3_13_32_dialog_content = "Mas já que sumiu, tem outra coisa que eu preciso fazer...",
  ui_story_3_13_33_dialog_content = "Só vai com calma. Deixa com a gente!",
  ui_story_3_13_34_dialog_content = "Que estranho, os condenados estão consolando uns aos outros.",
  ui_story_3_13_35_dialog_content = "Não se distraia, PlayerName!",
  ui_story_3_13_36_dialog_content = "Mostre o caminho!",
  ui_story_3_13_37_dialog_content = "Acabou?",
  ui_story_3_13_38_dialog_content = "<color=#e8d9bb>Apenas resta um silêncio assustador.</color>",
  ui_story_3_13_39_dialog_content = "Não, algo não está certo! O poder da escuridão está se acumulando! Se preparem para o ataque!",
  ui_story_3_13_40_dialog_content = "Isso não é o fim para Tabaad! Testemunhe a minha sentença!",
  ui_story_3_13_41_dialog_content = "Escuridão, devore o Celestita!",
  ui_story_3_13_42_dialog_content = "Oh-oh, tá vindo na minha direção!",
  ui_story_3_13_43_dialog_content = "Você não pode ferir alguém protegido pela Illumina tão facilmente!",
  ui_story_3_13_44_dialog_content = "Falou bonito, Tenente!",
  ui_story_3_13_45_dialog_content = "<color=#e8d9bb>Splash!</color>",
  ui_story_3_13_F1_dialog_content = "Ahhh!!!",
  ui_story_3_13_46_dialog_content = "C-Comandante!",
  ui_story_3_13_47_dialog_content = "Acho que cheguei na hora certa.",
  ui_story_3_13_48_dialog_content = "(Falando em Eclipsiano) Seus seres inferiores, imundos, ignorantes, fracos...",
  ui_story_3_13_49_dialog_content = "O Eclipsita... se transformou em flores de cerejeira e desapareceu...",
  ui_story_3_13_50_dialog_content = "Somos gratos pela sua ajuda!",
  ui_story_3_13_51_dialog_content = "Ten. Vice, você violou o protocolo de Illumina. Você está ciente das consequências dos seus atos?",
  ui_story_3_13_52_dialog_content = "...",
  ui_story_3_13_53_dialog_content = "Ten. Vice!",
  ui_story_3_13_54_dialog_content = "Aqui!",
  ui_story_3_13_55_dialog_content = "Eu quero que me entregue um relatório de no mínimo 5.000 palavras sobre a Colossus e o Celestita incapaz de lutar.",
  ui_story_3_13_56_dialog_content = "Ei! Eu sou um navegador experiente e posso comandar a Colossus!",
  ui_story_3_13_57_dialog_content = "Não reitere coisas que eu já sei.",
  ui_story_3_13_58_dialog_content = "<color=#e8d9bb>Crash!</color>",
  ui_story_3_13_59_dialog_content = "Mendelson! O seu corpo!",
  ui_story_3_13_60_dialog_content = "Ah não! Ele está...?",
  ui_story_3_13_61_dialog_content = "Parece que... meu destino está selado. Hora de me redimir das minhas injustiças.",
  ui_story_3_13_62_dialog_content = "Não... podemos te salvar! Não é mesmo, Vice?",
  ui_story_3_13_63_dialog_content = "PlayerName, eu...",
  ui_story_3_13_64_dialog_content = "Tá tudo bem. É a minha própria escolha. Eu... eu já esperava que esse dia iria chegar...",
  ui_story_3_13_A2_dialog_content = "Há assuntos mais importantes a se tratar, PlayerName.",
  ui_story_3_13_A3_dialog_content = "Dada a situação, acho que eu não preciso mais manter isso em segredo...",
  ui_story_3_13_65_dialog_content = "Lembra do Módulo do Tanque Pensante que eu mencionei? <color=#FFB400>Escute atentamente o que eu tenho a dizer</color>...",
  ui_story_3_13_A4_dialog_content = "Apesar de cada Colossus ter sua especialização, nenhuma delas foi feita especificamente para o combate.",
  ui_story_3_13_A5_dialog_content = "Exceto Aviduz. É a única Colossus com habilidades ofensivas!",
  ui_story_3_13_66_dialog_content = "Por sorte, ainda não está completa.",
  ui_story_3_13_67_dialog_content = "Schummer, sua mestra, está buscando corrigir a Colossus. Ela precisa de:",
  ui_story_3_13_X67_dialog_content = "<color=#FFB400>Módulo de Tanque Pensante</color>",
  ui_story_3_13_X68_dialog_content = "<color=#FFB400>Unidade de Crescimento Autônomo</color>",
  ui_story_3_13_X69_dialog_content = "...e <color=#FFB400>Controlador de Chamas</color>",
  ui_story_3_13_X70_dialog_content = "Os três módulos.",
  ui_story_3_13_A6_dialog_content = "Ela precisa do Módulo de Tanque Pensante primeiro, pois ele revelará as localizações dos outros dois módulos!",
  ui_story_3_13_68_dialog_content = "Para adquirir o poder supremo, Schummer tentará obtê-los a qualquer custo.",
  ui_story_3_13_69_dialog_content = "Mas o Módulo de Tanque Pensante já está com ela!",
  ui_story_3_13_70_dialog_content = "Não, ela não vai se dar bem nessa. O Módulo ainda possui uma sequência de proteção que será acionada quando eu morrer. Uma “surpresinha” que eu preparei pra ela.",
  ui_story_3_13_71_dialog_content = "Vai com calma, Mendelson. Teremos tempo de sobra pra conversar depois que você se recuperar.",
  ui_story_3_13_72_dialog_content = "Podemos acabar com Schummer juntos. Quando tudo terminar, podemos ir pra casa!",
  ui_story_3_13_73_dialog_content = "Eu nunca fui pra Eraveil. Você pode me contar sobre ela...",
  ui_story_3_13_74_dialog_content = "Infelizmente, acabou pra mim. Soroz pode te contar as histórias... Ou, descubra outros Celestitas...",
  ui_story_3_13_75_dialog_content = "Não, Mendelson!",
  ui_story_3_13_A7_dialog_content = "Cale-se e me escute. O tempo está se esgotando...",
  ui_story_3_13_76_dialog_content = "Quando eu me for, acredito que Schummer vai se dirigir em seguida para <color=#FFB400>Lumópolis</color>, a última cidade Aurorian...",
  ui_story_3_13_A8_dialog_content = "Porque outro Módulo de Tanque Pensante está lá! Sim, tem mais de um.",
  ui_story_3_13_A9_dialog_content = "Você precisa avisar Lumópolis, PlayerName.",
  ui_story_3_13_A10_dialog_content = "Os Aurorians de lá com certeza não sabem quão importante o Módulo de Tanque Pensante é...",
  ui_story_3_13_77_dialog_content = "Mendelson! Não me deixe, eu te imploro!",
  ui_story_3_13_78_dialog_content = "Eu sinceramente gostaria de poder estar com você e todos esses novos amigos, PlayerName.",
  ui_story_3_13_79_dialog_content = "Mas dessa vez eu não quero mais fugir. Schummer não pode se safar...",
  ui_story_3_13_80_dialog_content = "Pelo menos, ela nunca vai pôr as mãos no meu Módulo de Tanque Pensante! Dessa vez, o covarde vai se erguer... e se opor a ela!",
  ui_story_3_13_81_dialog_content = "Mendelson...",
  ui_story_3_13_82_dialog_content = "É tão lindo...",
  ui_story_3_13_83_dialog_content = "...",
  ui_story_3_13_84_dialog_content = "Esse é... um dragão incomparável.",
  ui_story_3_13_F2_dialog_content = "Esse é o <color=#FFB400>Zakura</color> da Comandante Hiiro.",
  ui_story_3_13_F3_dialog_content = "Que lindo. Quem iria saber que existe uma cor tão bonita nesse mundo? Se ao menos eu pudesse ver mais...",
  ui_story_3_13_85_dialog_content = "Todos esses anos na escuridão, eu quase me esqueci de como o céu se parece.",
  ui_story_3_13_86_dialog_content = "Precisamos fazer alguma coisa, PlayerName, Comandante Hiiro! Vamos apenas deixá-lo...",
  ui_story_3_13_F4_dialog_content = "...",
  ui_story_3_13_F5_dialog_content = "...",
  ui_story_3_13_87_dialog_content = "Gostaria de ter mais tempo pra conversar, PlayerName, como nos velhos tempos... Soroz, quando nós...",
  ui_story_3_13_88_dialog_content = "Eu gostaria de poder ver o céu mais uma vez...",
  ui_story_3_13_89_dialog_content = "Soroz!",
  ui_story_3_13_90_dialog_content = "Sim, PlayerName.",
  ui_story_3_13_91_dialog_content = "Conecte-se à mente do Mendelson e mostre o céu pra ele.",
  ui_story_3_13_92_dialog_content = "Sim.",
  ui_story_3_13_93_dialog_content = "Ah, o céu azul... Já faz muito tempo.",
  ui_story_3_13_94_dialog_content = "Deixe eu dividir o Soroz com você, Mendelson.",
  ui_story_3_13_95_dialog_content = "Agora e pra sempre, ele vai ser os seus olhos e os seus ouvidos para absorver tudo acima as nuvens.",
  ui_story_3_13_96_dialog_content = "A morte é assim? É um pouco diferente... do que eu imaginei... Parece tão solitário...",
  ui_story_3_13_97_dialog_content = "Estou aqui, mestre.",
  ui_story_3_13_98_dialog_content = "Que voz é essa?",
  ui_story_3_13_99_dialog_content = "Estamos todos aqui.",
  ui_story_3_13_100_dialog_content = "Estaremos com você até o fim.",
  ui_story_3_13_101_dialog_content = "Vani... Filex...",
  ui_story_3_13_103_dialog_content = "Mendelson!",
  ui_story_3_13_104_dialog_content = "...",
  ui_story_3_13_105_dialog_content = "...",
  ui_story_3_13_106_dialog_content = "<size=45>Você recebeu a minha surpresa, Schummer?</size>",
  ui_story_3_13_107_dialog_content = "O quê?",
  ui_story_3_13_108_dialog_content = "O Módulo de Tanque Pensante está <color=#FFB400>se autodestruindo</color>? Isso não é nada bom.",
  ui_story_3_13_110_dialog_content = "<anim type=Shake>MEN-DEL-SON!</anim>",
  ui_story_3_13_111_dialog_content = "Isso foi constrangedor, Schummer. Parece que as coisas não correram como o esperado.",
  ui_story_3_13_112_dialog_content = "Não pensei que Mendelson tivesse um último truque na manga. Essa coisa... é inútil agora.",
  ui_story_3_13_113_dialog_content = "Como ousa, aquele maldito e patético covarde...!",
  ui_story_3_13_114_dialog_content = "Hahahaha, esse é mesmo o meu irmão!",
  ui_story_3_13_115_dialog_content = "Ele sempre foi um fraco a vida inteira, mas achou coragem para me desafiar antes de morrer.",
  ui_story_3_13_116_dialog_content = "Não me diga que você não conseguiu salvar nada.",
  ui_story_3_13_118_dialog_content = "Só fragmentos, mas informações novas mesmo assim.",
  ui_story_3_13_120_dialog_content = "Tem um outro Módulo de Tanque Pensante idêntico a esse em <color=#FFB400>Lumópolis</color>.",
  ui_story_3_13_121_dialog_content = "Aqueles Aurorians tolos não têm ideia da sua importância.",
  ui_story_3_13_122_dialog_content = "Lumópolis não é um lugar onde você possa circular facilmente. Tenho que achar um jeito de arrumar a bagunça que você fez.",
  ui_story_3_13_123_dialog_content = "Mendelson, preste bem atenção. Ninguém conseguirá me impedir de completar...",
  ui_story_3_13_124_dialog_content = "Eu vou te mostrar como foi insignificante o seu sacrifício.",
  ui_story_3_14_A2_dialog_content = "<color=#e8d9bb>O Arquivo de Lumópolis</color>",
  ui_story_3_14_1_dialog_content = "Cara, tanta coisa pra fazer hoje de novo...",
  ui_story_3_14_2_dialog_content = "Sinceramente, que bagunça... Tá tudo aqui... Ei, o que é isso?",
  ui_story_3_14_3_dialog_content = "<color=#e8d9bb>Clang!</color>",
  ui_story_3_14_4_dialog_content = "Ai!",
  ui_story_3_14_5_dialog_content = "Você tá bem? Onde te acertou?",
  ui_story_3_14_6_dialog_content = "Eu tô bem, mas qual o seu problema? Você não consegue nem mexer as coisas direito!",
  ui_story_3_14_7_dialog_content = "De-desculpa, é a minha primeira vez...",
  ui_story_3_14_8_dialog_content = "Ei! Mas que...? Qual é o seu problema?",
  ui_story_3_14_9_dialog_content = "De-desculpa, me desculpa, não fiz de propósito...",
  ui_story_3_14_10_dialog_content = "Você! Você <color=#FFB400>o</color> quebrou! É muito valioso, você sabe!",
  ui_story_3_14_11_dialog_content = "... vou pegá-lo agora mesmo.",
  ui_story_3_14_12_dialog_content = "Esquece, eu faço isso. Eu não sei o que isso faz, mas parece bem caro.",
  ui_story_3_14_13_dialog_content = "Passos.",
  ui_story_3_14_14_dialog_content = "Vocês, parem de conversar durante o turno! Foco no trabalho!",
  ui_story_3_14_15_dialog_content = "Estamos apenas organizando os itens do arquivo, Capitão! Estamos na metade...",
  ui_story_3_14_16_dialog_content = "Vocês não são mais necessários aqui. Apenas vão embora.",
  ui_story_3_14_17_dialog_content = "Sim, Capitão!",
  ui_story_3_14_18_dialog_content = "Sim, Capitão!",
  ui_story_3_14_A1_dialog_content = "Bem, é exatamente como o <color=#FFB400>Mestre</color> o descreveu.",
  ui_story_3_14_19_dialog_content = "Você é muito valioso, mas as autoridades de Lumópolis acham que você é só uma antiguidade.",
  ui_story_3_14_20_dialog_content = "Alguém vai entender o seu <color=#FFB400>verdadeiro valor</color> em breve...",
  ui_story_3_14_B1_dialog_content = "Capitão! O Líder está nos chamando!",
  ui_story_3_14_B2_dialog_content = "...",
  ui_story_3_14_B3_dialog_content = "Entendido. Vamos lá.",
  ui_story_4_1_1_dialog_content = "O <color=#FFB400>Módulo de Tanque Pensante</color>, a <color=#FFB400>Unidade de Crescimento Autônomo</color> e o <color=#FFB400>Controlador de Chamas</color>... Como são exatamente?",
  ui_story_4_1_2_dialog_content = "Mendelson não deu informações suficientes, então mesmo que saibamos que tem outro Módulo de Tanque Pensante em Lumópolis...",
  ui_story_4_1_3_dialog_content = "Poderia ser outra Colossus?",
  ui_story_4_1_4_dialog_content = "Não importa o que ela está planejando, precisamos estar um passo à sua frente!",
  ui_story_4_1_5_dialog_content = "Estamos indo direto pra Lumópolis? E depois?",
  ui_story_4_1_6_option_content = "Vamos descobrir!",
  ui_story_4_1_7_option_content = "Francamente, ainda não pensei muito sobre isso.",
  ui_story_4_1_8_dialog_content = "Isso não é muito tranquilizador, PlayerName.",
  ui_story_4_1_9_dialog_content = "Não sabemos nada sobre quem estamos enfrentando. Não sabemos quais são suas habilidades, motivações, nem mesmo como se parecem.",
  ui_story_4_1_10_dialog_content = "Pelo menos você tá sendo sincero...",
  ui_story_4_1_11_dialog_content = "Mas não podemos elaborar um plano se não conhecemos nosso oponente.",
  ui_story_4_1_12_dialog_content = "Não sabemos quais são suas habilidades, motivações, nem mesmo como se parecem.",
  ui_story_4_1_13_dialog_content = "Além disso, Lumópolis não é como Illumina. É... bem, nada além de problemas.",
  ui_story_4_1_14_dialog_content = "<color=#e8d9bb>Vice está com uma expressão de agonia, algo como uma memória dolorosa.</color>",
  ui_story_4_1_15_dialog_content = "Já que você é o navegador, PlayerName, deveria decidir.",
  ui_story_4_1_16_dialog_content = "Eu ainda quero ir pra Lumópolis.",
  ui_story_4_1_17_dialog_content = "Eu sei que isso é provavelmente arriscado, Vice, mas...",
  ui_story_4_1_18_dialog_content = "Essa é a única pista que eu tenho pra descobrir o que aconteceu há 17 anos.",
  ui_story_4_1_19_dialog_content = "Tá bom, mas preciso informar a Comandante Hiiro primeiro. Será muito mais difícil do que você pensa.",
  ui_story_4_1_20_dialog_content = "Vejo que você não se esqueceu da oficial superior a você.",
  ui_story_4_1_21_dialog_content = "Ops! Você ainda tá aqui, Comandante?",
  ui_story_4_1_22_dialog_content = "Eu estava aqui o tempo todo, Ten. Vice. PlayerName, sinto ouvir sobre o Celestita, mas temos que abordar a informação sobre Lumópolis com cautela.",
  ui_story_4_1_23_dialog_content = "Com cuidado... quer dizer?",
  ui_story_4_1_24_dialog_content = "Sem uma investigação completa, não podemos tomar as palavras do Mendelson ao pé da letra. Além do mais, já encontramos muitos Eclipsitas de alto nível, então seria melhor não agir precipitadamente.",
  ui_story_4_1_25_dialog_content = "Mas não temos tempo! Se acontecer alguma coisa... Soroz vai nos proteger!",
  ui_story_4_1_26_dialog_content = "Com todo o respeito, PlayerName...",
  ui_story_4_1_27_dialog_content = "Eu notei a sua Colossus desde o começo e recebi toda informação necessária do Charon.",
  ui_story_4_1_A1_dialog_content = "De acordo com o sistema de avaliação de Colossus que usávamos naquela época...",
  ui_story_4_1_28_dialog_content = "Soroz é uma Colossus <color=#FFB400>Nível 6</color>.",
  ui_story_4_1_29_dialog_content = "...",
  ui_story_4_1_30_dialog_content = "Tão alto assim? O Soroz é bom mesmo.",
  ui_story_4_1_31_dialog_content = "Não, Nível 1 é o nível mais alto. Quanto maior o número, menor o nível, e pior o desempenho.",
  ui_story_4_1_32_dialog_content = "...?",
  ui_story_4_1_33_dialog_content = "Então qual é o nível mais baixo?",
  ui_story_4_1_34_dialog_content = "<color=#FFB400>6</color>.",
  ui_story_4_1_35_dialog_content = "...?!",
  ui_story_4_1_36_dialog_content = "Você não alegava ser uma Colossus classe Sky, Soroz?!",
  ui_story_4_1_37_dialog_content = "Aquilo foi para te dar a vontade de viver. Foi uma mentira necessária.",
  ui_story_4_1_A2_dialog_content = "Além disso, não existe uma “classe Sky”.",
  ui_story_4_1_38_dialog_content = "Você mentiu pra mim e tá simplesmente admitindo isso assim?",
  ui_story_4_1_39_dialog_content = "Colossi Nível 6 são apenas equipadas com recursos de suporte à vida e transporte.",
  ui_story_4_1_40_dialog_content = "E especializadas em fuga.",
  ui_story_4_1_41_dialog_content = "Você pode parar agora...",
  ui_story_4_1_42_dialog_content = "PlayerName parece deprimido.",
  ui_story_4_1_43_dialog_content = "Acho que eu falei demais. Não fica triste, PlayerName.",
  ui_story_4_1_44_dialog_content = "Você tem um “dom” único por ser um Celestita, além de uma excepcional liderança de combate. Disso eu nunca duvidei.",
  ui_story_4_1_45_dialog_content = "E do jeito que a Ten. Vice tem falado de você, você deve ser confiável.",
  ui_story_4_1_46_dialog_content = "Hã?",
  ui_story_4_1_47_dialog_content = "Obrigado. Vou me esforçar.",
  ui_story_4_1_48_dialog_content = "Então, vamos partir pra Lumópolis! Temos que nos apressar, se quisermos derrotar a Schummer!",
  ui_story_4_1_49_dialog_content = "Ótimo! Você pode nos fornecer a permissão para entrar em Lumópolis, Comandante?",
  ui_story_4_1_50_dialog_content = "Não. Isso é problema seu.",
  ui_story_4_1_51_dialog_content = "Hã?!",
  ui_story_4_1_52_dialog_content = "Sinto muito, mas sem nenhuma informação comprovada, a Federação Illumina não pode agir oficialmente, muito menos em Lumópolis.",
  ui_story_4_1_54_dialog_content = "...",
  ui_story_4_1_55_dialog_content = "Você não estudou em Lumópolis? É hora de um reencontro com seus antigos colegas.",
  ui_story_4_1_56_dialog_content = "Você não era colega da <color=#FFB400>Carleen</color>, Capitã dos Guardiões de Lumópolis?",
  ui_story_4_1_57_dialog_content = "Por esse motivo isso é um problema ainda maior. Ugh...",
  ui_story_4_1_58_dialog_content = "<color=#e8d9bb>Sobre Lumópolis</color>",
  ui_story_4_1_59_dialog_content = "Essa <color=#FFB400>cidade flutuante</color> é pra onde estamos indo?",
  ui_story_4_1_60_dialog_content = "Parece que já chegamos. A viagem é bem rápida com uma Colossus...",
  ui_story_4_1_X1_dialog_content = "Vice, o seu traje...",
  ui_story_4_1_X2_dialog_content = "É só um disfarce! Eu já mandei uma carta pra Carleen explicando a nossa situação, mas devo evitar chamar atenção mesmo assim...",
  ui_story_4_1_X3_dialog_content = "Hum, isso provavelmente vai chamar ainda mais atenção.",
  ui_story_4_1_61_dialog_content = "Olha, PlayerName!",
  ui_story_4_1_62_dialog_content = "Essa é Lumópolis.",
  ui_story_4_1_64_option_content = "Essa é a última cidade Aurorian?",
  ui_story_4_1_65_option_content = "Como ela flutua no ar?",
  ui_story_4_1_66_dialog_content = "Pare de murmurar pra si mesmo e venha aqui. Quero deixar uma coisa clara antes de começarmos essa missão!",
  ui_story_4_1_67_dialog_content = "Não importa o que aconteça, deixa que eu falo. Entendeu?",
  ui_story_4_1_68_dialog_content = "Não se precipite e não esqueça de que precisamos chegar ao alvo antes da Schummer!",
  ui_story_4_1_69_dialog_content = "Entendido, Tenente Vice. Confio em você.",
  ui_story_4_1_70_dialog_content = "Bom, deixa eu checar minha credencial de novo... Eu realmente não quero lidar com ela.",
  ui_story_4_1_71_dialog_content = "Estou um pouco nervoso, PlayerName. É realmente seguro eu ficar aqui sozinho?",
  ui_story_4_1_72_dialog_content = "Não tem outro jeito, Soroz. Você sabe como você chama atenção.",
  ui_story_4_1_73_dialog_content = "Se você for conosco, talvez nem sequer cheguemos ao subúrbio, muito menos em Lumópolis.",
  ui_story_4_1_74_dialog_content = "E você não é uma Colossus nível 6? Não tem como dar apoio em combate...",
  ui_story_4_1_75_dialog_content = "Vejo que você ainda tá chateado com aquilo.",
  ui_story_4_1_76_dialog_content = "Sim. Você tem razão. Vou deixar a luta com você, então.",
  ui_story_4_1_A3_dialog_content = "Vou esperar por vocês em um espaço aéreo escondido. Por favor, tomem cuidado.",
  ui_story_4_1_77_dialog_content = "Certo, vamos nessa. A fila para entrar na cidade já está muito longa.",
  ui_story_4_1_A4_dialog_content = "Boo, eu odeio esperar na fila...",
  ui_story_4_1_78_dialog_content = "Não quero ver essa pessoa de jeito nenhum... Mas é claro que <color=#FFB400>Carleen de Schwartz</color> tinha que ser a Capitã dos Guardiões de Lumópolis.",
  ui_story_4_1_79_dialog_content = "Qual é o problema com essa Capitã?",
  ui_story_4_1_80_dialog_content = "Espere e você vai ver. Ela provavelmente já está nos esperando nos portões nesse exato momento.",
  ui_story_4_1_81_dialog_content = "Onde está a Capitã que você mencionou, Vice?",
  ui_story_4_1_82_dialog_content = "Xiu!",
  ui_story_4_1_83_dialog_content = "Por favor, siga as ordens e coopere quando for inspecionado!",
  ui_story_4_1_84_dialog_content = "Visitantes com passes temporários não podem permanecer por mais de 24 horas, ou serão deportados!",
  ui_story_4_1_85_dialog_content = "Denuncie qualquer pessoa suspeita a um Guarda Lumo imediatamente!",
  ui_story_4_1_86_dialog_content = "Vou falar de novo, PlayerName. Não importa o que aconteça, não...",
  ui_story_4_1_87_dialog_content = "Sem sussurros e mostrem seus passes!",
  ui_story_4_1_88_dialog_content = "Entendo...",
  ui_story_4_1_89_dialog_content = "Mais um de Illumina... Não tem nada acontecendo na linha de frente? Você não está vestindo o traje certo, garota.",
  ui_story_4_1_90_dialog_content = "Err, estou aqui pra tratar de assuntos pessoais.",
  ui_story_4_1_91_dialog_content = "Primeira vez em Lumópolis? Por que você está olhando ao redor dessa maneira?",
  ui_story_4_1_92_dialog_content = "Não, eu estudei aqui. Eu voltei dessa vez com um Passe Classe A renovado...",
  ui_story_4_1_93_dialog_content = "E esse sujeito suspeito que está ao seu lado?",
  ui_story_4_1_94_option_content = "Eu? Eu sou novo nesse mundo.",
  ui_story_4_1_95_option_content = "(Vice me disse pra não falar nada...)",
  ui_story_4_1_96_dialog_content = "Você acha que eu estou brincando? Cadê o seu passe? Uma pessoa, um passe. Está escrito na placa!",
  ui_story_4_1_97_dialog_content = "Você é surdo? Eu te fiz uma pergunta!",
  ui_story_4_1_98_dialog_content = "Desculpa, ele tá comigo. Meu pedido foi especialmente aprovado. Por favor, verifique de novo!",
  ui_story_4_1_99_dialog_content = "Foi a Capitã Carleen quem...",
  ui_story_4_1_100_dialog_content = "A capitã? Ah, é você!",
  ui_story_4_1_101_dialog_content = "Por que não disse antes? Tudo bem, espere aqui.",
  ui_story_4_1_102_dialog_content = "Ufa...",
  ui_story_4_1_103_dialog_content = "Você parece relaxada. A Illumina não te pôs pra trabalhar?",
  ui_story_4_1_104_dialog_content = "Ah, <color=#FFB400>Carleen</color>, quanto tempo. Você está tão... admirável como sempre.",
  ui_story_4_1_105_dialog_content = "É preciso coragem para chamar a Capitã pelo nome.",
  ui_story_4_1_106_dialog_content = "Essa mulher estranha parece familiar...",
  ui_story_4_1_107_dialog_content = "Ah, foi você que estudou com a Carleen!",
  ui_story_4_1_108_dialog_content = "Xiu, Raphaela. A Capitã pode cuidar disso sozinha.",
  ui_story_4_1_109_dialog_content = "Você pode aprender algo com a Michele. Ela sabe quando ficar calada.",
  ui_story_4_1_110_dialog_content = "...",
  ui_story_4_1_111_dialog_content = "Silêncio.",
  ui_story_4_1_112_dialog_content = "Não há necessidade de tantas pessoas estarem aqui. Guardiões, retomem suas patrulhas rotineiras.",
  ui_story_4_1_113_dialog_content = "Deixem esses dois visitantes comigo.",
  ui_story_4_1_114_dialog_content = "Acredito que não haja necessidade de me apresentar.",
  ui_story_4_1_115_dialog_content = "É o seguinte, Carleen. Estamos aqui para...",
  ui_story_4_1_116_dialog_content = "Eu li a sua carta. Você continua a mesma de sempre, sua gramática é ruim e sua escrita formal, uma confusão.",
  ui_story_4_1_117_dialog_content = "Você estava tentando me dizer que <color=#FFB400>Eclipsitas estão de olho em Lumópolis</color>, certo?",
  ui_story_4_1_118_dialog_content = "Isso é hora de criticar meu estilo de escrita?",
  ui_story_4_1_A5_dialog_content = "Temos notícias de que uma pessoa chamada Schummer está tramando algo contra Lumópolis.",
  ui_story_4_1_119_dialog_content = "Acreditamos que ela está tentando roubar o <color=#FFB400>Módulo de Tanque Pensante</color> de Lumópolis.",
  ui_story_4_1_120_dialog_content = "Módulo de Tanque Pensante? Sinto muito, nunca ouvi falar disso. O que quer que seja, não acho que ninguém possa levá-lo de Lumópolis.",
  ui_story_4_1_122_dialog_content = "Humm? Quem é você?",
  ui_story_4_1_123_dialog_content = "Posso responder isso?",
  ui_story_4_1_124_dialog_content = "Você acha que ela pode nos ouvir se sussurrarmos?",
  ui_story_4_1_125_dialog_content = "...",
  ui_story_4_1_126_dialog_content = "PlayerName é... Carleen, você pode se aproximar? Você é a única que pode saber...",
  ui_story_4_1_127_dialog_content = "Você está falando... daquelas pessoas egoístas que preferem ficar evitando o perigo? E a Colossus?",
  ui_story_4_1_128_dialog_content = "A Colossus chama Soroz... Soroz está sobrevoando Lumópolis e não pode ser detectada.",
  ui_story_4_1_129_dialog_content = "...!",
  ui_story_4_1_130_dialog_content = "Tá tudo bem. É só uma Colossus Nível 6... Não pode combater e é usada principalmente para fugas.",
  ui_story_4_1_131_dialog_content = "Patético.",
  ui_story_4_1_132_dialog_content = "Mas isso não é importante, Carleen. Eu te falei quem PlayerName é para que possa confiar em nós!",
  ui_story_4_1_133_dialog_content = "Você tem alguma outra evidência que sustente o seu caso?",
  ui_story_4_1_134_dialog_content = "Não. Mas Eclipsitas com certeza estão tentando entrar em Lumópolis. Eles podem até estar entre as pessoas na fila nesse momento!",
  ui_story_4_1_137_dialog_content = "Capitã! Há uma emergência!",
  ui_story_4_1_139_dialog_content = "Sério?!",
  ui_story_4_1_140_dialog_content = "Do que eles estão falando?",
  ui_story_4_1_141_dialog_content = "Não sei, mas acho que não são boas notícias...",
  ui_story_4_1_142_dialog_content = "Tenente Vice, por termos sido colegas, vou acreditar em você dessa vez e deixá-la entrar na cidade.",
  ui_story_4_1_143_dialog_content = "Mas vou vigiar você o tempo todo. Se estiver mentindo, será punida pela lei!",
  ui_story_4_1_144_dialog_content = "Claro, sem problema! Vamos começar por...",
  ui_story_4_1_145_dialog_content = "Vamos começar pela <color=#FFB400>Baixa Lumópolis</color>.",
  ui_story_4_1_146_dialog_content = "Baixa Lumópolis?",
  ui_story_4_1_147_dialog_content = "Sim... Um <color=#FFB400>ataque</color> ocorreu agora mesmo em Baixa Lumópolis.",
  ui_story_4_1_148_dialog_content = "?!",
  ui_story_4_2_1_dialog_content = "<color=#e8d9bb>Baixa Lumópolis</color>",
  ui_story_4_2_2_dialog_content = "Não há tempo a perder. Pegue um atalho de volta...",
  ui_story_4_2_3_dialog_content = "Hã? Quem está aí... Aghhh!",
  ui_story_4_2_4_dialog_content = "Que barulhento.",
  ui_story_4_2_5_dialog_content = "Desculpa, desculpa. Foi mal.",
  ui_story_4_2_6_dialog_content = "Morto?",
  ui_story_4_2_A1_dialog_content = "Sim, moleza.",
  ui_story_4_2_7_dialog_content = "Tomara que você não use isso contra mim. Coitado, você estava no lugar errado, na hora errada.",
  ui_story_4_2_8_dialog_content = "A sorte também é uma importante habilidade de sobrevivência.",
  ui_story_4_2_9_dialog_content = "Você realmente gosta de falar besteiras pra eles, não é mesmo, Gertzurde?",
  ui_story_4_2_A2_dialog_content = "Nós não nos vemos há bastante tempo, mas você já falou mais com esse cara do que comigo!",
  ui_story_4_2_10_dialog_content = "Você tá sempre no meu coração e na minha mente. Eu penso em você a cada segundo, Shelt.",
  ui_story_4_2_11_dialog_content = "Você e sua lábia... Vamos aos negócios. Recebi notícias da Senhora, devemos começar logo.",
  ui_story_4_2_12_dialog_content = "Agora?",
  ui_story_4_2_13_dialog_content = "É. Vou te passar os detalhes do plano aos poucos.",
  ui_story_4_2_14_dialog_content = "Eu mandei alguns peões como isca, então os guardiões serão atraídos para o bairro. Daí você terá uma chance...",
  ui_story_4_2_15_dialog_content = "Espera, então você já decidiu, Shelt? Você não precisa correr um risco tão grande. Espere por mim.",
  ui_story_4_2_16_dialog_content = "Basta, Gertzurde, só faça o que eu disser.",
  ui_story_4_2_17_dialog_content = "Eu vou segurar os guardiões e você... Você vai <color=#FFB400>roubar o item</color>.",
  ui_story_4_2_18_dialog_content = "Já confirmei a localização do item... Mas é tão simples assim?",
  ui_story_4_2_19_dialog_content = "Sim, simples assim. Não vamos conseguir a nossa liberdade até que o nosso plano dê certo. Lembra?",
  ui_story_4_2_20_dialog_content = "Certo. Você é sempre muito persuasiva.",
  ui_story_4_2_21_dialog_content = "Capitã! Alguns moradores relataram que foram atacados por Eclipsitas!",
  ui_story_4_2_22_dialog_content = "Não é a mesma localização? Talvez seja um grupo?",
  ui_story_4_2_23_dialog_content = "Carleen! Estamos aqui!",
  ui_story_4_2_24_dialog_content = "...",
  ui_story_4_2_25_dialog_content = "Parece que temos mais de um grupo de inimigos.",
  ui_story_4_2_26_dialog_content = "Entendido! E quanto aos outros Guardiões?",
  ui_story_4_2_27_dialog_content = "Eles ficaram na Cidade Alta para proteger os nobres. Ordem daquele homem, afinal.",
  ui_story_4_2_28_dialog_content = "O <color=#FFB400>Senhor da Cidade</color>...?",
  ui_story_4_2_29_dialog_content = "Todos os ataques relatados são no lado leste, então os supervisores em Baixa Lumópolis estão indo para lá.",
  ui_story_4_2_30_dialog_content = "Estou com um estranho pressentimento de que devo ir pra área oeste...",
  ui_story_4_2_31_dialog_content = "É aquele olhar de novo de “Devo tomar a primeira grande atitude que vier à mente nesse momento”...",
  ui_story_4_2_32_dialog_content = "Ela tinha esse mesmo olhar quando vocês estavam na escola?",
  ui_story_4_2_33_dialog_content = "Ah, sim. Como quando estávamos na aula de combate e ela tava prestes a me derrubar.",
  ui_story_4_2_34_dialog_content = "Eu acho a Carleen muito impressionante.",
  ui_story_4_2_35_dialog_content = "Não precisa me elogiar. Vamos para a área oeste. Você pode lutar, PlayerName?",
  ui_story_4_2_36_dialog_content = "Eu não posso lutar, mas posso coordenar e guiar.",
  ui_story_4_2_37_dialog_content = "Isso não soa muito convincente vindo de você.",
  ui_story_4_2_38_dialog_content = "Mas estou disposta a te dar uma chance de provar seu valor.",
  ui_story_4_2_39_dialog_content = "Sentindo a pressão...",
  ui_story_4_3_1_dialog_content = "Surpreendentemente, você leva jeito pra liderar.",
  ui_story_4_3_2_dialog_content = "E esse é o Rastro de Luz? Não posso acreditar que pessoas tão talentosas foram aniquiladas antes de eu nascer.",
  ui_story_4_3_3_dialog_content = "Você está revelando a sua idade, Carleen.",
  ui_story_4_3_4_dialog_content = "Sem gracinhas. Eclipsitas foram vistos no lado oeste também. Precisamos ficar atentos.",
  ui_story_4_3_5_dialog_content = "Há mais Eclipsitas do que pensávamos...",
  ui_story_4_3_6_option_content = "Mas eu achei que Lumópolis jamais poderia cair, certo?",
  ui_story_4_3_7_option_content = "Os guardiões nos portões não conseguiram cuidar dos Eclipsitas?",
  ui_story_4_3_8_dialog_content = "O que dizem só vale pra Cidade Alta, não pra Baixa Lumópolis.",
  ui_story_4_3_9_dialog_content = "Os guardiões são úteis, claro, mas a maioria deles protege a Cidade Alta, não a Baixa Lumópolis.",
  ui_story_4_3_10_dialog_content = "Estamos na Baixa Lumópolis, onde é cada um por si, certo, Carleen?",
  ui_story_4_3_F1_dialog_content = "...",
  ui_story_4_3_11_dialog_content = "Baixa Lumópolis e Cidade Alta são mesmo tratadas de maneira tão diferente?",
  ui_story_4_3_12_dialog_content = "Não há muito o que possamos fazer. Essa é Lumópolis...",
  ui_story_4_3_13_dialog_content = "Desculpa o atraso... Gertzurde, líder do esquadrão, se apresentando.",
  ui_story_4_3_14_dialog_content = "Viu alguma coisa fora do normal?",
  ui_story_4_3_15_dialog_content = "Não, Capitã.",
  ui_story_4_3_16_dialog_content = "Reúna todos para evacuar os cidadãos. Além disso, feche todos os portões na Baixa Lumópolis!",
  ui_story_4_3_17_dialog_content = "Isso já foi feito, Capitã.",
  ui_story_4_3_18_dialog_content = "Isso foi rápido! Agora, preciso que você venha conosco...",
  ui_story_4_3_19_dialog_content = "Perdoe minha franqueza, mas muitos cidadãos estão trancados pra fora da cidade e precisam entrar.",
  ui_story_4_3_20_dialog_content = "Ou vão cair nas garras dos Eclipsitas.",
  ui_story_4_3_21_dialog_content = "Tudo bem. Vá e faça isso, mas deixe alguns soldados comigo!",
  ui_story_4_3_22_dialog_content = "Desculpe por partir primeiro, Capitã. A Noite Branca já vai alta.",
  ui_story_4_3_23_dialog_content = "Carleen, aquele era...?",
  ui_story_4_3_24_dialog_content = "Um dos líderes de Esquadrão na Baixa Lumópolis. Ele é responsável por diversos pontos de defesa, e sempre foi muito eficiente.",
  ui_story_4_3_25_dialog_content = "Ele era um <color=#FFB400>cavaleiro famoso</color>, afinal de contas.",
  ui_story_4_3_26_dialog_content = "Acho que você nunca pode julgar um livro pela capa...",
  ui_story_4_3_27_dialog_content = "Certo, vamos continuar andando. Muitos Eclipsitas passaram pelas brechas, espalhando o caos por toda Baixa Lumópolis.",
  ui_story_4_3_28_dialog_content = "Eu também quero conhecer essa misteriosa <color=#FFB400>Schummer</color>.",
  ui_story_4_6_1_dialog_content = "Capitã! A área leste está livre de Eclipsitas!",
  ui_story_4_6_2_dialog_content = "Capitã, notícias do oeste sobre possíveis Eclipsitas de alto nível avistados!",
  ui_story_4_6_3_dialog_content = "Eu sabia! Me diga onde é!!",
  ui_story_4_6_4_dialog_content = "Foi tudo uma distração? Os Eclipsitas de alto nível devem estar indo atrás do Módulo de Tanque Pensante!",
  ui_story_4_6_5_dialog_content = "Não estamos muito atrás, estamos?",
  ui_story_4_6_6_dialog_content = "Temos a Carleen e sua percepção aguçada do nosso lado!",
  ui_story_4_6_7_dialog_content = "...",
  ui_story_4_6_8_dialog_content = "Aah, ela está com aquele olhar de novo... Por quê? Tem alguma coisa errada?",
  ui_story_4_6_9_dialog_content = "Não sei... Mas eu não gosto desse tipo de sensação... Enfim, vamos em frente!",
  ui_story_4_6_10_dialog_content = "Shelt! Precisamos abandonar o plano!",
  ui_story_4_6_11_dialog_content = "O quê? Mas eu acabei de atrair a princesa Carleen de Schwartz até aqui!",
  ui_story_4_6_12_dialog_content = "E agora você quer desistir? Eu não quero discutir com você por causa disso, Gertzurde.",
  ui_story_4_6_13_dialog_content = "Carleen tá com os arruaceiros de Illumina e parece que eles também estão procurando pelo Módulo de Tanque Pensante!",
  ui_story_4_6_14_dialog_content = "E o portão do Arquivo é difícil de destrancar. Não sei se há tempo suficiente pra...",
  ui_story_4_6_15_dialog_content = "Não, não, essas crianças malditas não vão estragar o plano!",
  ui_story_4_6_16_dialog_content = "Eu não posso de jeito nenhum... permitir que isso aconteça...",
  ui_story_4_6_17_dialog_content = "Então, o que devemos fazer?",
  ui_story_4_6_18_dialog_content = "Eu vou te arranjar mais tempo!",
  ui_story_4_6_19_dialog_content = "<color=#FFB400>Shire</color>... Ah, certo. Eu posso acordar a Shire para ela ficar comigo...",
  ui_story_4_6_20_dialog_content = "Não! Não importa o que você está pensando, Shelt, não posso deixar você fazer isso!",
  ui_story_4_6_21_dialog_content = "Shire... a sua irmã é imprevisível! Ela é louca!",
  ui_story_4_6_22_dialog_content = "Louca? Ha... Então eu sou o quê?",
  ui_story_4_6_23_dialog_content = "Sai daí, Gertzurde. Vá pro lugar combinado. Não me decepcione.",
  ui_story_4_6_24_dialog_content = "Eu vou esperar por você no lugar que combinamos, Shelt...",
  ui_story_4_6_25_dialog_content = "Você fez um juramento de cavaleiro. E vai mantê-lo, certo?",
  ui_story_4_6_26_dialog_content = "Claro, Gertzurde. Vou manter a minha palavra, não importa o que aconteça.",
  ui_story_4_6_27_dialog_content = "Você dormiu o bastante, Shire? Acorda. Eu vou te trazer... pra brincar.",
  ui_story_4_6_28_dialog_content = "Oba! Brincar!",
  ui_story_4_7_1_dialog_content = "<color=#e8d9bb>Ruas da Baixa Lumópolis</color>",
  ui_story_4_7_2_dialog_content = "Capitã, encontramos um corpo à frente. Confirmamos que é um guarda encarregado de defender a Baixa Lumópolis.",
  ui_story_4_7_3_dialog_content = "Há apenas um ferimento, empalado pelo coração.",
  ui_story_4_7_4_dialog_content = "Todos os guardas! Comecem a busca. Não permitirei que nada faça mal aos meus cidadãos!",
  ui_story_4_7_5_dialog_content = "“<color=#FFB400>Meus cidadãos</color>”?",
  ui_story_4_7_6_dialog_content = "Carleen se preocupa com o povo.",
  ui_story_4_7_7_dialog_content = "Não, me refiro ao “<color=#FFB400>meus</color>”.",
  ui_story_4_7_8_dialog_content = "Ah... Eu não te falei? Carleen é a <color=#FFB400>filha do Senhor de Lumópolis</color>.",
  ui_story_4_7_9_dialog_content = "???",
  ui_story_4_7_10_dialog_content = "Desculpa, muitas coisas ao mesmo tempo e eu esqueci de te contar...",
  ui_story_4_7_11_dialog_content = "Mas ao menos na nossa situação atual, ela é Capitã dos Guardiões de Lumópolis.",
  ui_story_4_7_13_dialog_content = "Uau! O que foi isso?!",
  ui_story_4_7_14_dialog_content = "Guardas! Vão na direção daquele som a toda velocidade.",
  ui_story_4_7_16_dialog_content = "Essa é a primeira vez... que me mostrei nesse estado.",
  ui_story_4_7_17_dialog_content = "Aquela residência civil foi explodida?",
  ui_story_4_7_18_dialog_content = "Carleen, PlayerName, cuidado! Tem algo errado com aquela pessoa!",
  ui_story_4_7_19_dialog_content = "Você é... Shelt...?",
  ui_story_4_7_20_dialog_content = "Não é surpreendente, princesa, que nos encontremos como iguais?",
  ui_story_4_7_21_dialog_content = "O que você acha? Eu pareço melhor do que era antes?",
  ui_story_4_7_22_dialog_content = "Vocês se conhecem, Carleen?",
  ui_story_4_7_23_dialog_content = "Sim, há muito tempo. Ela é só uma pobre criatura que abandonou a sua fé.",
  ui_story_4_7_24_dialog_content = "Pobre criatura? Hum. Bom... acho que eu sou.",
  ui_story_4_7_25_dialog_content = "Esmagada sob os pés das autoridades, não sou nada além de uma criatura aos olhos deles na Cidade Alta. Lastimável, de fato.",
  ui_story_4_7_26_dialog_content = "Sua miséria foi causada pelas suas próprias escolhas!",
  ui_story_4_7_27_dialog_content = "Olhe pra você agora... eu mal tenho palavras pra descrever seu estado.",
  ui_story_4_7_28_dialog_content = "A culpa é minha? Se você não tivesse nascido nobre, o que você teria se tornado, princesa?",
  ui_story_4_7_29_dialog_content = "Se você tivesse nascido nas favelas como eu... o que você teria se tornado?",
  ui_story_4_7_30_dialog_content = "...",
  ui_story_4_7_31_dialog_content = "Ficou sem palavras? Que arrogante da sua parte afirmar que sou culpada pela minha miséria, princesa.",
  ui_story_4_7_32_dialog_content = "Você ainda se lembra do que eu te disse da última vez, Shelt?",
  ui_story_4_7_33_dialog_content = "Fiz um juramento em nome da Noite Branca que se você pisasse aqui de novo eu faria a justiça ser feita!",
  ui_story_4_7_34_dialog_content = "Hoje eu cumprirei o juramento que fiz naquele dia.",
  ui_story_4_7_35_dialog_content = "Na verdade, eu nunca fui embora. Estive sob o seu nariz o tempo todo, escondida em um canto escuro...",
  ui_story_4_7_36_dialog_content = "Está surpresa? Não só isso, também fiz muitos amigos.",
  ui_story_4_7_37_dialog_content = "O quê...?!",
  ui_story_4_7_38_dialog_content = "Venha até mim, minha irmã, minha querida Shire...",
  ui_story_4_7_39_dialog_content = "Ir... Shire que-quer...",
  ui_story_4_7_40_dialog_content = "Você quer brincar? Como posso dizer não a você, minha querida irmã?",
  ui_story_4_7_41_dialog_content = "Venha, vamos brincar com essa adorável princesa!",
  ui_story_4_7_42_dialog_content = "Brincar!",
  ui_story_4_7_43_dialog_content = "Cuidado!",
  ui_story_4_7_44_dialog_content = "Droga! Por quê? Por quê? Você...!",
  ui_story_4_7_45_dialog_content = "Quem é você?! Por que você consegue coordená-los?",
  ui_story_4_7_46_dialog_content = "Você é... Um Celestita?!",
  ui_story_4_7_47_dialog_content = "...",
  ui_story_4_7_48_dialog_content = "Não tem graça... Não tem graça!! Vamos, Mana...",
  ui_story_4_7_49_dialog_content = "Não, ele precisa de mais tempo. Não podemos... Não podemos simplesmente deixá-los ir!",
  ui_story_4_7_50_dialog_content = "Se você e os seus lacaios de Lumópolis são corajosos o suficiente, tentem nos alcançar!!",
  ui_story_4_7_51_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_4_7_53_dialog_content = "*Cof Cof* Droga, <color=#FFB400>eles se foram</color>!",
  ui_story_4_7_54_dialog_content = "Eles estão indo pra Cidade Alta!",
  ui_story_4_7_55_dialog_content = "Toque o alarme! Avise todos os Guardiões! Voltem pra Cidade Alta, já!",
  ui_story_4_7_56_dialog_content = "PlayerName! Rápido! Precisamos alcançá-la!",
  ui_story_4_8_1_dialog_content = "<color=#e8d9bb>O Arquivo de Lumópolis, longe da Cidade Alta...</color>",
  ui_story_4_8_2_dialog_content = "Vire pra esquerda... 3 graus... Vire pra direita... 14 graus... Então...",
  ui_story_4_8_3_dialog_content = "Travou de novo... Que tipo de criptografia é essa?! Foi um erro não ter deixado uma porta traseira da última vez...",
  ui_story_4_8_4_dialog_content = "Eu devia simplesmente explodir isso! Não, não posso arriscar danificar o módulo.",
  ui_story_4_8_5_dialog_content = "Precisa mesmo de um dispositivo desse pra um arquivo?",
  ui_story_4_8_6_dialog_content = "Gertzurde.",
  ui_story_4_8_7_dialog_content = "Desculpa, Shelt, preciso de mais tempo. O portão do arquivo...",
  ui_story_4_8_8_dialog_content = "Calma, você tá lutando?",
  ui_story_4_8_9_dialog_content = "Não... Desculpa, eu... estou fugindo.",
  ui_story_4_8_10_dialog_content = "Um Celestita, Gertzurde! Eles têm um Celestita.",
  ui_story_4_8_11_dialog_content = "Você lutou contra a Carleen? Você se feriu?!",
  ui_story_4_8_12_dialog_content = "Me escuta. Vou levá-los pro sul da Cidade Alta, pra longe de onde você está...",
  ui_story_4_8_A1_dialog_content = "Assim você terá bastante tempo pra...",
  ui_story_4_8_13_dialog_content = "Não! Se você for pra Cidade Alta, você tá morta!!",
  ui_story_4_8_14_dialog_content = "Não se esqueça que estamos fazendo tudo isso por...",
  ui_story_4_8_15_dialog_content = "<color=#FFB400>A Senhora</color> irá nos ajudar. Ela prometeu...",
  ui_story_4_8_16_dialog_content = "Fé é poder, Gertzurde. Fizemos uma escolha e temos que ir até o fim!",
  ui_story_4_8_17_dialog_content = "Te vejo do lado de fora de Lumópolis, meu querido.",
  ui_story_4_8_18_dialog_content = "Shelt!!",
  ui_story_4_8_19_dialog_content = "Espere! Espere por mim. Você tá indo muito rápido...",
  ui_story_4_8_20_dialog_content = "Quem era aquela criança chamada Shire, Carleen? As duas eram Aurorians?",
  ui_story_4_8_21_dialog_content = "Sim, apesar de não querer admitir isso. São traidoras de Lumópolis.",
  ui_story_4_8_22_dialog_content = "PlayerName, a forma que comandou agora foi impecável. Eu achei que você iria recuar ao ver Eclipsitas de alto nível.",
  ui_story_4_8_23_dialog_content = "Você é um Celestita completamente diferente do que eu imaginei.",
  ui_story_4_8_24_option_content = "É só o meu dever.",
  ui_story_4_8_25_option_content = "Não, sou apenas igual a qualquer outro Celestita.",
  ui_story_4_8_26_dialog_content = "Você também não está sempre lutando como Capitã dos Guardiões, Senhorita Carleen?",
  ui_story_4_8_A2_dialog_content = "Não gostamos de lutar, nem temos habilidade pra lutar.",
  ui_story_4_8_27_dialog_content = "Nós só não queremos que os Eclipsitas vençam.",
  ui_story_4_8_28_dialog_content = "Eu acredito em você. Meu povo já lutou com essa mesma atitude.",
  ui_story_4_8_29_dialog_content = "Você não tem medo de lutar, já que é incapaz disso?",
  ui_story_4_8_31_dialog_content = "Sei que meu povo uma vez lutou contra Eclipsitas com toda sua força, e na verdade foram decisivos.",
  ui_story_4_8_32_dialog_content = "Eu não sou diferente de nenhum deles.",
  ui_story_4_8_33_dialog_content = "Suas habilidades são muito impressionantes.",
  ui_story_4_8_34_dialog_content = "Minhas habilidades...  É provavelmente por isso que sofremos uma emboscada.",
  ui_story_4_8_35_dialog_content = "Você não se sente impotente?",
  ui_story_4_8_36_dialog_content = "Não, porque eu tenho meu próprio propósito a cumprir.",
  ui_story_4_8_37_dialog_content = "E você está disposto a se arriscar por esse suposto propósito?",
  ui_story_4_8_F1_dialog_content = "Sim, porque essa luta não é só minha.",
  ui_story_4_8_38_dialog_content = "Interessante. Você tem um parceiro interessante, Vice.",
  ui_story_4_8_39_dialog_content = "Arriscar-se para <color=#FFB400>lutar pelos outros</color>... certo?",
  ui_story_4_8_40_dialog_content = "...",
  ui_story_4_8_41_dialog_content = "...!!",
  ui_story_4_8_46_dialog_content = "Cadê você, Raphaela?",
  ui_story_4_8_47_dialog_content = "Aqui!",
  ui_story_4_8_48_dialog_content = "Não vá para Cidade Alta conosco. Preciso que você... vá para a direção contrária.",
  ui_story_4_8_49_dialog_content = "O quê?! Por quê?",
  ui_story_4_8_50_dialog_content = "Você não acha que seria suicídio ir em direção à Cidade Alta?",
  ui_story_4_8_51_dialog_content = "Talvez eles não estejam planejando escapar... Mas...",
  ui_story_4_8_52_dialog_content = "Desviar a nossa atenção?",
  ui_story_4_8_53_dialog_content = "Sim, mas não temos escolha agora a não ser persegui-los.",
  ui_story_4_8_54_dialog_content = "Então, gostaria que a Raphaela fosse na direção contrária. Meu palpite é que alguém está em algum lugar lá atrás...",
  ui_story_4_8_55_dialog_content = "Saquei! Agora eu entendi! Vou procurar por pessoas suspeitas! Partindo já!",
  ui_story_4_8_56_dialog_content = "Você é perspicaz, Carleen. Nada passa despercebido pelo seu radar.",
  ui_story_4_8_57_dialog_content = "Ao contrário, muitas coisas eu ainda não consigo ver com clareza. O ponto de vista de cada pessoa é complexo.",
  ui_story_4_8_58_dialog_content = "Bem, se concentre. Tem uns vermes novos rastejando pra rua. Vamos limpá-los.",
  ui_story_4_12_1_dialog_content = "...",
  ui_story_4_12_2_dialog_content = "...",
  ui_story_4_12_3_dialog_content = "É... Então, por que você está aqui, líder do Esquadrão?",
  ui_story_4_12_4_dialog_content = "Já te disse duas vezes, vim aqui escoltar o pessoal do Arquivo. Pergunta pra eles se você não acredita.",
  ui_story_4_12_5_dialog_content = "Mas você falou pra capitã que estava trazendo os cidadãos pra dentro da cidade.",
  ui_story_4_12_6_dialog_content = "E eles são os funcionários do Arquivo, e agora eles estão de volta.",
  ui_story_4_12_7_dialog_content = "Ei, o que é isso na sua mão? Por que está coberto?",
  ui_story_4_12_8_dialog_content = "Ah, isso? Eu só empacotei alguns arquivos que deixei aqui semana passada.",
  ui_story_4_12_9_dialog_content = "São, hã, os relatórios do legista sobre os civis mortos por Eclipsitas nos últimos seis meses.",
  ui_story_4_12_10_dialog_content = "Err...",
  ui_story_4_12_11_dialog_content = "Precisamos deles como referências pra potenciais medidas de segurança. São fotos, esboços de autópsias, coisas desse tipo.",
  ui_story_4_12_12_dialog_content = "Quer dar uma olhada...?",
  ui_story_4_12_13_dialog_content = "...",
  ui_story_4_12_14_dialog_content = "...",
  ui_story_4_12_15_dialog_content = "Ah ha ha, não, obrigada.",
  ui_story_4_12_16_dialog_content = "Tudo bem. As coisas saíram mesmo do controle, então se te mandaram verificar...",
  ui_story_4_12_17_dialog_content = "Oh, haha! Não precisa. Eu vou embora e patrulhar ali!",
  ui_story_4_12_18_dialog_content = "...",
  ui_story_4_13_1_dialog_content = "Capitã! As manchas de sangue vêm até este lado, pra dentro dessa porta!",
  ui_story_4_13_2_dialog_content = "O espaço entre as gotas de sangue diminuiu... Elas desaceleraram. Estamos nos aproximando!",
  ui_story_4_13_3_dialog_content = "Rápido! Elas podem estar logo à frente!",
  ui_story_4_13_4_dialog_content = "Uau, corremos por tanto tempo, estamos quase na Cidade Alta...",
  ui_story_4_13_5_dialog_content = "Acho que elas sabem que não podem entrar na Cidade Alta, então o plano é se posicionar aqui.",
  ui_story_4_13_6_dialog_content = "Vamos. Isso sempre acaba da mesma forma. Todos os traidores têm o mesmo destino!",
  ui_story_4_13_7_dialog_content = "Ir... Tô com soo-soono...",
  ui_story_4_13_8_dialog_content = "Você não pode dormir agora, Shire... Desculpa, eu sei que você tá cansada...",
  ui_story_4_13_9_dialog_content = "Eles já chegaram aqui...? Eles são rápidos, como se espera da Carleen...",
  ui_story_4_13_10_dialog_content = "Chegou a hora de cumprir sua promessa, minha Senhora...",
  ui_story_4_13_11_dialog_content = "Olá, Shelt.",
  ui_story_4_13_12_dialog_content = "Minha Senhora...! A situação é desesperadora... Os inimigos, eles têm um Celestita do seu lado!",
  ui_story_4_13_13_dialog_content = "Parece que a batalha é inevitável.",
  ui_story_4_13_14_dialog_content = "Precisamos da sua ajuda...! Gertzurde precisa de mais tempo...!",
  ui_story_4_13_15_dialog_content = "Por favor, nos dê o poder para derrotar os inimigos! Por favor... nos dê esperança de viver!",
  ui_story_4_13_16_dialog_content = "Esses são dois pedidos diferentes, Shelt.",
  ui_story_4_13_17_dialog_content = "...!",
  ui_story_4_13_18_dialog_content = "Você quer derrotar seus inimigos, ou quer sobreviver?",
  ui_story_4_14_1_dialog_content = "Shelt, Shire.",
  ui_story_4_14_3_dialog_content = "Você... veio...",
  ui_story_4_14_4_dialog_content = "Irmã...",
  ui_story_4_14_5_dialog_content = "Diga-me, Shelt, <color=#FFB400>para quem você está tentando ganhar tempo</color>?",
  ui_story_4_14_6_dialog_content = "...",
  ui_story_4_14_7_dialog_content = "Bem, imagino que você prefira lutar a falar.",
  ui_story_4_14_8_dialog_content = "Carleen... Você acha mesmo que nos encurralou?",
  ui_story_4_14_9_dialog_content = "A Senhora nos deu um novo poder...",
  ui_story_4_14_10_dialog_content = "A Senhora? Poderia ser a Schummer?",
  ui_story_4_14_11_dialog_content = "Nós... Nós vamos viver! E então sairemos dessa corrupta Lumópolis de cabeça erguida!",
  ui_story_4_14_13_dialog_content = "Você jamais vencerá, princesa!",
  ui_story_4_14_14_dialog_content = "Irmã... ? Meu corpo está...",
  ui_story_4_14_15_dialog_content = "<anim type=Shake>Arghhhhhhhhhhhh!</anim>",
  ui_story_4_14_17_dialog_content = "O quê...?! Elas <color=#FFB400>fundiram-se como uma só</color>?!",
  ui_story_4_14_18_dialog_content = "Receio que o que você deu pra elas há pouco não seja um poder qualquer.",
  ui_story_4_14_19_dialog_content = "Ah, sim. Mas era isso que queriam, o poder para derrotar seus inimigos.",
  ui_story_4_14_21_dialog_content = "Vamos dar um nome a essa criação! Como quer chamá-las?",
  ui_story_4_14_22_dialog_content = "Tédio.",
  ui_story_4_14_23_dialog_content = "<anim type=Shake>Argh! Ai, ai! Isso não tá certo! Nós...</anim>",
  ui_story_4_14_24_dialog_content = "<anim type=Shake>Posso sentir nosso poder aumentando, Mana, mas isso... Isso dói... tanto!</anim>",
  ui_story_4_14_25_dialog_content = "Minha Senhora! O que diabos está acontecendo!?",
  ui_story_4_14_26_dialog_content = "Por favor, se afaste, PlayerName. Essa coisa não se parece com nada que já encontramos antes.",
  ui_story_4_14_27_option_content = "Não tenha medo. Eu estou aqui.",
  ui_story_4_14_28_option_content = "Se concentre. Nós vamos vencer.",
  ui_story_4_14_29_dialog_content = "Mal posso conter a minha raiva.",
  ui_story_4_14_30_dialog_content = "Que tipo de escória concederia esse tipo de poder perverso?!",
  ui_story_4_14_31_dialog_content = "Certo! Então faça o que sabe fazer de melhor, PlayerName!",
  ui_story_4_14_32_dialog_content = "<anim type=Shake>Ai, ai! Mana... Dói muito...</anim>",
  ui_story_4_14_33_dialog_content = "<anim type=Shake>Minha irmã... Por favor, nos mate...</anim>",
  ui_story_4_14_35_dialog_content = "...",
  ui_story_4_14_36_dialog_content = "O que isso quer dizer?",
  ui_story_4_14_A1_dialog_content = "Não faço ideia do que acabou de acontecer, mas isso é de se esperar ao se unir à escuridão.",
  ui_story_4_14_37_dialog_content = "Em nome da Noite Branca, eu te concedo...",
  ui_story_4_14_38_dialog_content = "<anim type=Shake>Dente-de-leão...</anim>",
  ui_story_4_14_39_dialog_content = "?",
  ui_story_4_14_40_dialog_content = "<anim type=Shake>Eu vou virar um dente-de-leão e voar pra longe...</anim>",
  ui_story_4_14_41_dialog_content = "Você já está sendo incoerente. Nesse estado, não tenho certeza se você teria muita utilidade ou...",
  ui_story_4_14_42_dialog_content = "<anim type=Shake>Mas eu... Eu realizei o plano da Minha Senhora...</anim>",
  ui_story_4_14_43_dialog_content = "<anim type=Shake>Isso não foi o prometido... Gertzurde está esperando por mim...</anim>",
  ui_story_4_14_44_dialog_content = "<anim type=Shake>Senhora, Minha Senhora...</anim>",
  ui_story_4_14_45_dialog_content = "<color=#e8d9bb>Bum!!—</color>",
  ui_story_4_14_46_dialog_content = "Outra explosão?!",
  ui_story_4_14_47_dialog_content = "É o <color=#FFB400>Arquivo</color>, Capitã! Houve uma explosão... Desculpa...",
  ui_story_4_14_48_dialog_content = "Entendi! Mas por que você está se desculpando, Raphaela?",
  ui_story_4_14_49_dialog_content = "<anim type=Shake>Hihihi... Hihihi... Eu finalmente venci, Princesa...</anim>",
  ui_story_4_14_50_dialog_content = "<anim type=Shake>Gertzurde, Ger... meu... Gertzurde... Você deve viver...</anim>",
  ui_story_4_14_53_dialog_content = "Eu sei que é o inimigo, mas mesmo assim eu não aguento assistir a isso.",
  ui_story_4_14_54_dialog_content = "<color=#e8d9bb>Fora do Arquivo</color>",
  ui_story_4_14_55_dialog_content = "Então, você simplesmente passou pelo traidor?",
  ui_story_4_14_56_dialog_content = "Sinto muito, Carleen... Se ao menos eu estivesse...",
  ui_story_4_14_57_dialog_content = "<color=#FFB400>Procure Gertzurde por toda a cidade</color>. Imediatamente. Agora!",
  ui_story_4_14_58_dialog_content = "Sim, senhora!",
  ui_story_4_14_59_dialog_content = "Pondo a segurança pública em risco, espalhando o caos pela cidade... Isso é inaceitável...",
  ui_story_4_14_60_dialog_content = "A pessoa roubou o...",
  ui_story_4_14_61_dialog_content = "Módulo de Tanque Pensante do Arquivo?",
  ui_story_4_14_62_dialog_content = "Ele foi roubado, mas eu nem sei como ele é... Eu falhei terrivelmente...",
  ui_story_4_14_63_dialog_content = "Eu também sou parcialmente responsável. Não, eu diria até que a maior parte é culpa minha.",
  ui_story_4_14_64_dialog_content = "Eu sinto muito, Carleen.",
  ui_story_4_14_65_dialog_content = "Eclipsitas sempre reagem, Vice.",
  ui_story_4_14_66_dialog_content = "Na verdade, sou grata por você e PlayerName terem nos avisado antes.",
  ui_story_4_14_67_dialog_content = "Se tivesse sido qualquer outra pessoa, teríamos sofrido perdas ainda maiores.",
  ui_story_4_14_68_dialog_content = "Ela acabou de nos elogiar?",
  ui_story_4_14_69_dialog_content = "Acho que sim?",
  ui_story_4_14_70_dialog_content = "Eu falhei em cumprir meu dever como Capitã dos Guardiões. Eu... eu devo ser punida pela Sua Alteza, o Senhor.",
  ui_story_4_14_71_dialog_content = "Ele é o seu pai. Acho que ele vai te perdoar.",
  ui_story_4_14_72_dialog_content = "Vejo que você não o compreende, nem compreende Lumópolis.",
  ui_story_4_14_73_dialog_content = "Então, deveríamos voltar pra Illumina para discutir o que faremos em seguida.",
  ui_story_4_14_74_dialog_content = "Como diz o velho ditado, “Se você se preocupar muito em perder a segunda-feira, perde a terça também.”",
  ui_story_4_14_75_dialog_content = "Isso é mesmo um ditado?",
  ui_story_4_14_76_dialog_content = "Você é muito otimista, Vice.",
  ui_story_4_14_77_dialog_content = "Depois de tudo que aconteceu, não adianta ser pessimista agora!",
  ui_story_4_14_78_dialog_content = "Então, preciso voltar para a Cidade Alta e informar o Senhor a respeito do ocorrido. Se cuide.",
  ui_story_4_14_79_dialog_content = "Talvez nos encontremos novamente, PlayerName...",
  ui_story_4_14_80_dialog_content = "<color=#e8d9bb>Enquanto isso, em algum lugar</color>",
  ui_story_4_14_81_dialog_content = "As irmãs estão mortas.",
  ui_story_4_14_82_dialog_content = "E isso te surpreende?",
  ui_story_4_14_83_dialog_content = "Preciso te contar umas coisas. Primeiro, o Módulo de Tanque Pensante está em nossas mãos.",
  ui_story_4_14_84_dialog_content = "E o Celestita apareceu de novo.",
  ui_story_4_14_85_dialog_content = "PlayerName, certo?",
  ui_story_4_14_86_dialog_content = "Você nunca esquece sua própria espécie, não é mesmo?",
  ui_story_4_14_90_dialog_content = "Vou dizer mais uma vez. Eu não pertenço mais àquela raça inferior!!!",
  ui_story_4_14_91_dialog_content = "Seus lacaios estúpidos quase arruinaram o plano inteiro!",
  ui_story_4_14_92_dialog_content = "Eu mesma pegarei o próximo módulo! E quem ousar me impedir... será feito em pedaços.",
  ui_story_4_14_93_dialog_content = "E o módulo? Me entregue, Gertzurde!",
  ui_story_4_14_95_dialog_content = "Shelt... Shelt... Não, não!",
  ui_story_4_14_96_dialog_content = "Ela me prometeu... Ela prometeu que partiria comigo e que seríamos livres juntos...",
  ui_story_4_14_97_dialog_content = "O que aconteceu...?!",
  ui_story_4_14_98_dialog_content = "Pare de falar sozinho aí com esse olhar miserável!",
  ui_story_4_14_99_dialog_content = "Foram os Guardiões de Lumópolis que mataram. Você deveria estar feliz por ainda ter tempo para cumprir nossas ordens!",
  ui_story_4_14_100_dialog_content = "Carleen...!",
  ui_story_4_14_101_dialog_content = "Ora, que bela expressão, Gertzurde. Você parece completamente diferente da sua ordem de prisão.",
  ui_story_4_14_102_dialog_content = "Eu as vingarei!",
  ui_story_5_1_1_dialog_content = "Essa é a sua decisão, Capitã Carleen?",
  ui_story_5_1_2_dialog_content = "Sim, meu Senhor. Penso que seria insensato negligenciar o Celestita, que é... realmente especial.",
  ui_story_5_1_3_dialog_content = "Não vou interferir, mas espero que você se lembre da sua posição, Capitã.",
  ui_story_5_1_4_dialog_content = "Sim, meu Senhor. Alta vai a Noite Branca.",
  ui_story_5_1_5_dialog_content = "Eu entendo a situação agora. A reunião rotineira dos Comandantes da Legião é em meia hora. Você pode passar os detalhes lá.",
  ui_story_5_1_6_dialog_content = "Quanto a resolução, vai depender do resultado da negociação.",
  ui_story_5_1_7_dialog_content = "Tá bom, isso é tudo sobre o primeiro assunto, então.",
  ui_story_5_1_A1_dialog_content = "Quanto a investigar os Eclipsitas perto das coordenadas mencionadas, está nas mãos dos seus três comandantes.",
  ui_story_5_1_8_dialog_content = "<size=30>Hum-hum, PlayerName, essa é <color=#FFB400>Sharona</color>, Comandante da 1a Legião.</size>",
  ui_story_5_1_A2_dialog_content = "<size=30>E esse é o Comandante <color=#FFB400>Barton</color> da 2a Legião, também um destaque do exército.</size>",
  ui_story_5_1_9_dialog_content = "Entendi. Eclipsitas têm sido avistados perto de Gannon ultimamente, possivelmente de alto nível, então algo suspeito com certeza está acontecendo.",
  ui_story_5_1_10_dialog_content = "Por isso chamamos todos os três comandantes. Queremos que todos estejam em alerta e não subestimem a ameaça.",
  ui_story_5_1_11_dialog_content = "Quem são essas duas crianças?",
  ui_story_5_1_12_dialog_content = "Elas são o segundo assunto do dia. É com você Hiiro.",
  ui_story_5_1_13_dialog_content = "Um operador da Colossus e um Celestita sobrevivente, hã?",
  ui_story_5_1_14_dialog_content = "...",
  ui_story_5_1_15_option_content = "Por que tá todo mundo olhando pra mim?",
  ui_story_5_1_16_dialog_content = "Você tá ficando vermelho?",
  ui_story_5_1_X16_dialog_content = "É, é só uma criança mesmo.",
  ui_story_5_1_17_option_content = "Devo, hã, demonstrar?",
  ui_story_5_1_18_dialog_content = "E arrancar o teto com essa Colossus?",
  ui_story_5_1_19_dialog_content = "Altamente volátil mesmo! O que se passa entre você e Schummer, criança?",
  ui_story_5_1_20_dialog_content = "PlayerName é diferente da Schummer, comandante!",
  ui_story_5_1_21_dialog_content = "Acalme-se. Não há comparação entre um Celestita inocente e que não luta, e aqueles que conspiram com os Eclipsitas.",
  ui_story_5_1_22_dialog_content = "Eu só nunca pensei que haveria por perto qualquer Celestita sobrevivente. Eu pensei que todos haviam morrido naquela tragédia.",
  ui_story_5_1_23_dialog_content = "Voltando a essa Schummer que você mencionou. Quanto ela sabe sobre os três módulos?",
  ui_story_5_1_24_dialog_content = "Não temos certeza, já que os meios para encontrar os outros dois estão no Módulo de Tanque Pensante.",
  ui_story_5_1_25_dialog_content = "E acreditamos que Schummer tenha o Módulo de Tanque Pensante, então não está nada bom pro nosso lado.",
  ui_story_5_1_26_dialog_content = "A nossa maior prioridade é achar alguma maneira de encontrar os outros dois módulos antes dela!",
  ui_story_5_1_27_dialog_content = "Espero que os comandantes possam nos ajudar, ou talvez conduzir a operação.",
  ui_story_5_1_28_dialog_content = "A prioridade de Illumina é defender a linha de frente e os quartéis-generais da Cidade Gannon.",
  ui_story_5_1_29_dialog_content = "Os Eclipsitas aumentaram os ataques ultimamente, diminuindo as nossas forças. Vai ser difícil disponibilizar qualquer pessoal.",
  ui_story_5_1_30_dialog_content = "Eu repito, ninguém além do Grande Marechal pode mandar em mim ou na minha legião.",
  ui_story_5_1_31_dialog_content = "E você, Hiiro? Qual é a sua opinião como superior da Vice?",
  ui_story_5_1_32_dialog_content = "Os soldados de Illumina se orgulham de seguir as ordens.",
  ui_story_5_1_33_dialog_content = "Entendi.",
  ui_story_5_1_34_dialog_content = "Desculpa, PlayerName, mas não podemos te ajudar antes de receber ordens diretas.",
  ui_story_5_1_35_dialog_content = "Você consegue sentir alguma coisa, PlayerName?",
  ui_story_5_1_36_dialog_content = "Apenas um vasto vazio. Nada de anormal.",
  ui_story_5_1_37_dialog_content = "Então, estamos sem opções agora?",
  ui_story_5_1_38_dialog_content = "Antes de morrer, Mendelson disse que Schummer com certeza iria procurar pelos outros módulos.",
  ui_story_5_1_39_dialog_content = "Se pudermos rastrear a Schummer, poderemos descobrir outras coisas e fazer algo de fato.",
  ui_story_5_1_40_dialog_content = "Mas ela praticamente desapareceu sem deixar rastros. Não vamos fazer nada e apenas esperar?",
  ui_story_5_1_41_dialog_content = "*Uaaah* Me diz, por que estão com essa cara? A reunião não foi boa?",
  ui_story_5_1_42_dialog_content = "<color=#FFB400>Philyshy</color>!",
  ui_story_5_1_43_dialog_content = "Ah, relaxa! Toma aqui uma coisinha pra você.",
  ui_story_5_1_44_dialog_content = "<color=#FFB400>O Relatório sobre os Destroços da Colossus Anônima-13</color>?",
  ui_story_5_1_45_dialog_content = "Eu gastei muito tempo nele!",
  ui_story_5_1_46_dialog_content = "Vivian me pressionou pra entregar esse logo. Foi intenso demais. Ah, eu tô com muito sono...",
  ui_story_5_1_47_dialog_content = "“Módulos crescendo de forma autônoma foram descobertos onde a Colossus Anônima caiu, talvez únicos para esse tipo de Colossi...”",
  ui_story_5_1_48_dialog_content = "“A unidade chave se encontra na parte mais profunda dos destroços e o método para desbloqueá-la permanece desconhecido. A pesquisa continua...”",
  ui_story_5_1_49_dialog_content = "A descrição se assemelha à <color=#FFB400>Unidade de Crescimento Autônomo</color>!",
  ui_story_5_1_50_dialog_content = "Quais as chances! Enfim, só há uma maneira de descobrir.",
  ui_story_5_1_51_dialog_content = "Ah, a Vivian queria que eu te contasse...",
  ui_story_5_1_52_dialog_content = "Mesmo que os comandantes não possam oferecer ajuda por ora, boa parte do nosso pessoal está perto dos escombros.",
  ui_story_5_1_53_dialog_content = "*Uaah* Eu não estou me aguentando de pé. Preciso tirar uma soneca. Vou torcer por você em meus sonhos.",
  ui_story_5_1_54_dialog_content = "Philyshy continua a mesma.",
  ui_story_5_1_55_option_content = "Se tivéssemos alguém assim\nna Colossus.",
  ui_story_5_1_56_dialog_content = "Ela é a Chefe da Inteligência de Illumina. Temos sorte de contar com a sua ajuda.",
  ui_story_5_1_57_dialog_content = "Se conseguirmos fazer Philyshy se juntar a nós, pelo menos não estaremos tão perdidos.",
  ui_story_5_1_58_dialog_content = "Mas parece que ela pode cair no sono a qualquer momento.",
  ui_story_5_1_59_dialog_content = "É provavelmente estresse por causa do trabalho...",
  ui_story_5_1_60_option_content = "Na verdade, eu tô com sono também.\nPor que a gente não...",
  ui_story_5_1_61_dialog_content = "Descansa um pouco?",
  ui_story_5_1_A4_dialog_content = "Não, esquece isso, PlayerName! Quanto mais cedo resolvermos esses problemas...",
  ui_story_5_1_62_dialog_content = "Mais cedo eu te levo na maior biblioteca de Gannon, daí você pode relaxar o quanto quiser!",
  ui_story_5_1_63_dialog_content = "Não deveria ser um parque de diversões ou um café? É desumano estudar logo depois do trabalho!",
  ui_story_5_1_64_dialog_content = "Enfim, não temos muito mais tempo! Temos que pegar o próximo módulo antes que Schummer pegue!",
  ui_story_5_1_65_dialog_content = "Vamos ligar a Colossus!",
  ui_story_5_1_66_dialog_content = "Você parece confiante. Deve ter recebido ótimas instruções.",
  ui_story_5_1_67_dialog_content = "Carleen!",
  ui_story_5_1_68_dialog_content = "Não fique surpresa. O Senhor da Cidade aprovou meu pedido para assumir o comando de tudo relacionado à Schummer.",
  ui_story_5_1_69_dialog_content = "Quem se atrever a se opor a Lumópolis será punido e ficar do lado dos Eclipsitas é ainda mais imperdoável.",
  ui_story_5_1_70_dialog_content = "<size=30>Cuidado, Carleen está ficando alterada de novo.</size>",
  ui_story_5_1_71_dialog_content = "O que você disse?",
  ui_story_5_1_72_dialog_content = "Hã? Eu disse isso alto?",
  ui_story_5_1_73_dialog_content = "Se você não fez nada errado, não tem motivo para ter medo de mim.",
  ui_story_5_1_A5_dialog_content = "A não ser que você seja Shelt, Gertzurde ou da laia deles.",
  ui_story_5_1_74_dialog_content = "O Gertzurde não criou distrações e tentou ajudar Shelt e os outros a escapar?",
  ui_story_5_1_75_dialog_content = "Sim, o mesmo desertor que buscou proteção contra Eclipse nas sombras.",
  ui_story_5_1_76_dialog_content = "Mas, nenhum traidor pode se esconder da espada da Família Schwartz, não importa pra onde correrem.",
  ui_story_5_1_77_dialog_content = "Chega de papo furado. Pra onde estamos indo?",
  ui_story_5_1_78_dialog_content = "Destroços da Anônima-13. Você já viu os destroços de uma Colossus, Capitã?",
  ui_story_5_1_79_dialog_content = "Isso não é importante, principalmente quando há assuntos que exigem a minha atenção imediata.",
  ui_story_5_1_80_dialog_content = "De qualquer maneira, obrigada, PlayerName, por tudo que você fez por Lumópolis.",
  ui_story_5_1_81_dialog_content = "Eu vou te ajudar nessa missão. Eu juro que não vou deixar os traidores triunfarem!",
  ui_story_5_2_1_dialog_content = "(Ouço vozes. Vozes tristes e nostálgicas.)",
  ui_story_5_2_2_dialog_content = "Flores para a casa perdida, onde as árvores outrora cresciam ao vento...",
  ui_story_5_2_3_dialog_content = "Aurora para o companheiro falecido, que a luz redima todos os espíritos...",
  ui_story_5_2_4_dialog_content = "Nosso sofrimento cessará com o tempo, das cinzas às cinzas, do pó ao pó...",
  ui_story_5_2_5_dialog_content = "E nós saudaremos a paz absoluta em nosso eterno sono, quando o sol nascer.",
  ui_story_5_2_6_dialog_content = "Isso é suficiente, professor? Mas eu ainda tô com medo...",
  ui_story_5_2_7_dialog_content = "A flor que eu plantei ainda não brotou e eu quero muito vê-la desabrochar.",
  ui_story_5_2_8_dialog_content = "Não tenha medo, criança. Feche os olhos. A dor é apenas temporária. Eu sempre estarei com você.",
  ui_story_5_2_9_dialog_content = "(Meu... <color=#FFB400>Povo?</color> Isso é real ou só imaginação?)",
  ui_story_5_2_10_dialog_content = "Oração inútil e banal para os mortos. Vamos, não diga que eu nunca te dei escolha...",
  ui_story_5_2_11_dialog_content = "Chegamos. Você está bem, PlayerName?",
  ui_story_5_2_12_option_content = "Vice...",
  ui_story_5_2_13_dialog_content = "Não esquenta, eu tô aqui. Você sentiu alguma coisa?",
  ui_story_5_2_14_dialog_content = "Só imagens na minha cabeça... Mas quem são eles?",
  ui_story_5_2_15_dialog_content = "Talvez os Celestitas que morreram aqui deixaram emoções intensas pra trás.",
  ui_story_5_2_16_dialog_content = "Eles estão mortos, né? Então, eles não conseguiriam falar comigo como Mendelson fez.",
  ui_story_5_2_17_dialog_content = "Acho que não. Provavelmente não sobrou nada dos restos mortais deles.",
  ui_story_5_2_18_option_content = "Eu vi muitas imagens na minha cabeça.",
  ui_story_5_2_19_dialog_content = "Você sentiu a mente de alguém, PlayerName? Será que tem sobreviventes aqui?",
  ui_story_5_2_A1_dialog_content = "Não tem nenhum sobrevivente aqui. O que você viu foi provavelmente algum tipo de ilusão.",
  ui_story_5_2_20_dialog_content = "Imagens tristes e de desespero, ou talvez restos psíquicos dos Celestitas que morreram?",
  ui_story_5_2_21_dialog_content = "Acredito que sim. Parece com as emoções do meu povo.",
  ui_story_5_2_A2_dialog_content = "Vamos pousar, Soroz.",
  ui_story_5_2_24_dialog_content = "Chegamos aos <color=#FFB400>destroços da Anônima-13</color>.",
  ui_story_5_2_25_dialog_content = "O documento diz, “Quem primeiro descobriu o local ficou maravilhado com a Colossus adormecida...”",
  ui_story_5_2_26_dialog_content = "“Eles a compararam a uma estrela adormecida que caiu do céu.”",
  ui_story_5_2_27_dialog_content = "“Não havia sinal de vida na Colossus, apenas o vazio deixado pela passagem do tempo.”",
  ui_story_5_2_28_dialog_content = "Uma repressão tão tensa... nunca senti algo assim antes.",
  ui_story_5_2_29_dialog_content = "Quanto à catástrofe em Eraveil, eu li no arquivo que...",
  ui_story_5_2_30_dialog_content = "“Os Eclipsitas sobrepujaram os Celestitas em Eraveil com um ataque brutal. Ninguém sobreviveu, a não ser aqueles que seguiram os Eclipsitas.”",
  ui_story_5_2_31_dialog_content = "Mas ao chegar assim tão perto, é mais doloroso do que eu imaginava.",
  ui_story_5_2_A3_dialog_content = "...",
  ui_story_5_2_A4_dialog_content = "Você deve estar sentindo várias emoções também, Vice.",
  ui_story_5_2_A5_dialog_content = "É. Não tantas quanto PlayerName, mas posso sentir a tristeza.",
  ui_story_5_2_34_dialog_content = "Como você sobreviveu, PlayerName?",
  ui_story_5_2_35_dialog_content = "Só sei que quando isso aconteceu, Soroz executou a ordem final e me tirou de lá, eu que era apenas uma criança.",
  ui_story_5_2_A6_dialog_content = "Depois disso se passaram 17 longos anos vivendo no subterrâneo até recentemente.",
  ui_story_5_2_36_dialog_content = "Vice me trouxe ao mundo exterior. Infelizmente, não é muito melhor.",
  ui_story_5_2_37_dialog_content = "Eu gostaria de poder falar com o meu povo novamente, e com Mendelson também.",
  ui_story_5_2_38_dialog_content = "PlayerName...",
  ui_story_5_2_39_dialog_content = "Não podemos deixar a tragédia se repetir.",
  ui_story_5_2_40_dialog_content = "Claro, nenhuma raça deveria ter que passar por isso.",
  ui_story_5_2_41_dialog_content = "Ei, olha, a maior Colossus ali no meio. É a que procuramos?",
  ui_story_5_2_A7_dialog_content = "O arquivo indica que ela se chama <color=#FFB400>Liebowitz</color>, a única Colossus capaz de crescimento autônomo.",
  ui_story_5_2_42_dialog_content = "Ela deve conter a <color=#FFB400>Unidade de Crescimento Autônomo</color>.",
  ui_story_5_2_43_dialog_content = "Mas tá tão destruída. A unidade pode ainda estar intacta?",
  ui_story_5_2_44_dialog_content = "É tudo que havia no arquivo.",
  ui_story_5_2_45_dialog_content = "Vamos entrar. Deve haver pistas.",
  ui_story_5_2_46_dialog_content = "Você precisa entender como isso é perigoso, PlayerName. Lembre do que aconteceu com Mendelson naquela época.",
  ui_story_5_2_F1_dialog_content = "Eu sei. Posso me deparar com problemas e desaparecer como ele lá dentro.",
  ui_story_5_2_47_dialog_content = "Não consigo esquecer como Mendelson faleceu e sumiu. Parecia que eu podia apenas estender a mão e tocá-lo, mas eu estava completamente impotente.",
  ui_story_5_2_48_dialog_content = "Ainda podemos voltar.",
  ui_story_5_2_F2_dialog_content = "Eu também estou com medo, Vice, mas não tenho escolha.",
  ui_story_5_2_F3_dialog_content = "Eu me decidi. O que quer que aconteça, eu vou enfrentar.",
  ui_story_5_2_49_dialog_content = "Entendi, e você não vai estar sozinho. Eu estarei com você, não importa o que acontecer.",
  ui_story_5_2_A8_dialog_content = "<color=#e8d9bb>Dentro dos destroços</color>",
  ui_story_5_2_50_dialog_content = "Isso é horrível. A maioria das peças estão tão danificadas que não dá nem pra reconhecê-las.",
  ui_story_5_2_51_dialog_content = "Talvez tenhamos que reiniciar a Colossus para tirá-la daqui.",
  ui_story_5_2_52_dialog_content = "De quem é essa voz?",
  ui_story_5_2_53_option_content = "É a... Schummer?",
  ui_story_5_2_54_dialog_content = "Não... É a <color=#FFB400>Gronru</color>!",
  ui_story_5_2_55_option_content = "Alguém de Illumina?",
  ui_story_5_2_56_dialog_content = "Sim! É a <color=#FFB400>Madame Gronru</color>.",
  ui_story_5_2_57_dialog_content = "Gronru é Oficial de Tecnologia de Illumina e tem extenso conhecimento sobre a Colossus e a Lúmina.",
  ui_story_5_2_58_dialog_content = "Senhora!",
  ui_story_5_2_59_dialog_content = "Vice? Não esperava que os reforços chegassem aqui tão cedo...",
  ui_story_5_2_60_dialog_content = "Então, você é quem Philyshy disse pra ficar de olho!",
  ui_story_5_2_61_dialog_content = "Dá pra imaginar? Philyshy agiu como se estivesse sob um feitiço, caindo no sono enquanto falava.",
  ui_story_5_2_62_dialog_content = "Eu fui deixada sozinha e desamparada! Eu fiquei TÃO BRAVA! Mas, agora vejo que a minha sorte mudou.",
  ui_story_5_2_63_dialog_content = "E você tem uma Colossus funcionando, também? Inacreditável! Isso quer dizer que está intacta!",
  ui_story_5_2_64_dialog_content = "<size=45>Posso brincar com ela?</size>",
  ui_story_5_2_65_dialog_content = "Hã?",
  ui_story_5_2_66_dialog_content = "Hu-hum, acho que eu me empolguei. Vamos voltar pra missão principal em questão.",
  ui_story_5_2_67_dialog_content = "Gronru é legal, mas às vezes ela te deixa confuso com o jeito que ela fala.",
  ui_story_5_2_68_dialog_content = "Talvez ela só seja obcecada com certas coisas...",
  ui_story_5_2_69_dialog_content = "Você está sozinha aqui, Madame Gronru?",
  ui_story_5_2_70_dialog_content = "Sim! A investigação foi inacreditavelmente lenta, porque a Colossus está muito danificada, então não é nada mais que uma missão secundária.",
  ui_story_5_2_71_dialog_content = "Mas, eu sinto que ainda há algo dentro que devemos investigar mais a fundo.",
  ui_story_5_2_72_dialog_content = "Um jogador profissional não larga missões secundárias, então pedi pra voltar aqui e investigar por mais alguns dias.",
  ui_story_5_2_73_dialog_content = "Ah, você está aqui por causa da <color=#FFB400>Unidade de Crescimento Autônomo</color>?",
  ui_story_5_2_74_dialog_content = "Sim. Você cruzou com alguma durante as suas investigações?",
  ui_story_5_2_75_dialog_content = "Essa Colossus com certeza tinha esse tipo de módulo, mas não é algo que dá para ser extraído com força bruta.",
  ui_story_5_2_77_dialog_content = "Afinal, a Colossus é o ápice dos tempos antigos, e incompreensível para o nível tecnológico atual de Illumina.",
  ui_story_5_2_78_dialog_content = "Não há outro jeito?",
  ui_story_5_2_79_dialog_content = "Outro jeito? Isso não está fora do campo de possibilidades.",
  ui_story_5_2_80_dialog_content = "Você deve ser o <color=#FFB400>único sobrevivente Celestita</color> que Philyshy mencionou. Um slogan bem direto para um protagonista!",
  ui_story_5_2_81_dialog_content = "Já que temos um Celestita vivo entre nós, poderíamos tentar reiniciar essa lata velha.",
  ui_story_5_2_82_dialog_content = "Sem tempo a perder. Vamos nos apressar...",
  ui_story_5_2_83_dialog_content = "<anim type=Shake>Wooga!</anim>",
  ui_story_5_2_84_dialog_content = "Temos companhia. Parece que precisamos tirar o lixo do caminho para seguir em frente.",
  ui_story_5_2_A9_dialog_content = "Então temos que fazer isso bem rapidinho!",
  ui_story_5_2_85_dialog_content = "Você vai amar saber onde a Unidade de Crescimento Autônomo está localizada.",
  ui_story_5_2_86_dialog_content = "Um aterro cheio de vermes? E eu pensando que seria algo especial.",
  ui_story_5_2_87_dialog_content = "O módulo que eu quero está entre esses mortos patéticos? Não me diga que destruí sem querer.",
  ui_story_5_2_88_dialog_content = "Que chatice. <color=#FFB400>Essa mulher</color> está me provocando? Eu não avisei que não sou igual a esses bastardos fracos?",
  ui_story_5_2_89_dialog_content = "Os fracos merecem ser esmagados, arregaçados e jogados ao vento!",
  ui_story_5_2_90_dialog_content = "Droga, mesmo que ela esteja me ajudando, isso é intolerável.",
  ui_story_5_2_91_dialog_content = "Esses Eclipsitas inúteis... Se tivessem feito o trabalho direito da última vez, eu não teria que mexer nem um dedo.",
  ui_story_5_2_92_dialog_content = "E o Celestita, espero que nos encontremos em breve!",
  ui_story_5_3_1_dialog_content = "Não conseguimos enxergar bem por conta dos danos interiores. Tem certeza de que estamos indo na direção certa?",
  ui_story_5_3_2_dialog_content = "Não se preocupa, sou profissa. A Ponte já está na minha mira. Está a 200 metros.",
  ui_story_5_3_3_dialog_content = "Isso é moleza para alguém com um senso de direção impecável igual a mim.",
  ui_story_5_3_4_dialog_content = "Ouvi algo.",
  ui_story_5_3_5_dialog_content = "Não parece que veio de perto.",
  ui_story_5_3_6_dialog_content = "Estou sentindo arrepios por toda parte...",
  ui_story_5_3_8_dialog_content = "O que foi, PlayerName? Você está bem?",
  ui_story_5_3_9_dialog_content = "Estou sentindo uma presença muito mais poderosa que Eclipsitas de alto nível... Deve ser Schummer!",
  ui_story_5_3_10_dialog_content = "Vamos manter a calma e seguir com o plano.",
  ui_story_5_3_11_dialog_content = "Se ela estiver aqui, é aqui que vamos acabar com ela.",
  ui_story_5_3_12_dialog_content = "Mas...",
  ui_story_5_3_13_dialog_content = "Sem mas. Ela já causou tristeza demais. Vou ensinar uma lição para ela.",
  ui_story_5_3_A1_dialog_content = "Adiante. Tem mais Eclipsitas esperando por nós em frente.",
  ui_story_5_3_14_dialog_content = "Sinto uma presença familiar. Não me diga que realmente estão aqui.",
  ui_story_5_3_16_dialog_content = "Fracote. Não é pareo para mim, mas ainda assim é persistente.",
  ui_story_5_3_17_dialog_content = "Mendelson morreu, e agora temos PlayerName para substituí-lo, tentando proteger o módulo em vão.",
  ui_story_5_3_18_dialog_content = "Eu te disse que a única decisão certa é a que eu tomei.",
  ui_story_5_3_A2_dialog_content = "Pegar a espada é a única forma de controlar seu próprio destino, ou sempre será uma presa patética.",
  ui_story_5_3_A3_dialog_content = "Sigam a Lúmina e cumprimentem nossos convidados, imprestáveis! Preparem-os para a grande batalha.",
  ui_story_5_3_A4_dialog_content = "Até que estou ansiosa pela luta.",
  ui_story_5_3_A5_dialog_content = "(Falando em Eclipsiano) Sim... Marcha!",
  ui_story_5_7_A14_dialog_content = "E chegamos na Ponte!",
  ui_story_5_7_A15_dialog_content = "Mas ainda assim, temos que ficar de olho nos Eclipsitas irritantes.",
  ui_story_5_7_A16_dialog_content = "Apesar de muita pesquisa e esforço, ainda estou tentando remover a Unidade de Crescimento Autônomo da Ponte.",
  ui_story_5_7_A17_dialog_content = "Mas dessa vez tenho um Celestita comigo! Você pode reiniciar a Colossus, certo?",
  ui_story_5_7_A18_dialog_content = "Vou tentar o meu melhor.",
  ui_story_5_7_1_dialog_content = "O primeiro passo para iniciar uma Colossus é estimar o nível de energia.",
  ui_story_5_7_2_dialog_content = "A Colossus está muito danificada, mas surpreendentemente, ainda tem energia suficiente para reiniciar.",
  ui_story_5_7_3_dialog_content = "O segundo passo é estabelecer uma conexão mental com a Colossus. É a única forma de acessar o painel de controle e somente um Celestita pode fazer isso.",
  ui_story_5_7_4_dialog_content = "O terceiro passo é operar o controle...",
  ui_story_5_7_5_dialog_content = "Isso, bem assim. Está se saindo bem.",
  ui_story_5_7_6_dialog_content = "Que voz é essa?",
  ui_story_5_7_7_dialog_content = "Estou em êxtase. Faz muito, muito tempo desde que vi um colega Celestita, um descendente da nossa raça.",
  ui_story_5_7_8_dialog_content = "Crescer só, sem contato com ninguém. Deve ter sido difícil pra você.",
  ui_story_5_7_9_dialog_content = "Como você sabe disso...",
  ui_story_5_7_11_dialog_content = "Como você, eu sou de Eraveil.",
  ui_story_5_7_14_dialog_content = "Eu vivi e aprendi com o meu povo desde a infância, ouvindo músicas e conversando com a Colossus.",
  ui_story_5_7_A1_dialog_content = "Nós éramos uma família unida, PlayerName, da qual Celestitas faziam parte.",
  ui_story_5_7_15_option_content = "Mas por que você é transparente?",
  ui_story_5_7_16_dialog_content = "Por que não consigo ver seu rosto?",
  ui_story_5_7_17_dialog_content = "Sou apenas um raio de seus anseios. Apenas nos manifestamos quando você quer nos ver.",
  ui_story_5_7_18_dialog_content = "Corremos em vão. Corpos decompostos em meros ossos, espíritos espalhados ao céu infinito.",
  ui_story_5_7_19_dialog_content = "Ela liderou os Eclipsitas para nos assassinar em um massacre terrível. São as trevas que nem mesmo a Aurora poderia penetrar.",
  ui_story_5_7_20_dialog_content = "Até os dias de hoje, ela manteve suas convicções.",
  ui_story_5_7_21_dialog_content = "Pobre criança. Deve ter sido uma agonia viver na solidão.",
  ui_story_5_7_22_dialog_content = "Eu não posso te acolher, mas posso tocar essa canção com você, uma melodia de memória.",
  ui_story_5_7_23_dialog_content = "Conecte sua mente. Conecte-se com a Colossus da mesma forma que faz com Soroz.",
  ui_story_5_7_24_dialog_content = "Aceite este presente, a Última Criança que nunca encontrei.",
  ui_story_5_7_A2_dialog_content = "(É apenas uma visão, ainda assim consigo sentir seus dedos tocando minha pele.)",
  ui_story_5_7_25_dialog_content = "(Sei que já morreram há muito tempo, mas como a psique deles pôde cruzar este mundo para me guiar?)",
  ui_story_5_7_26_dialog_content = "(Ilumine a Colossus para te ver.)",
  ui_story_5_7_27_dialog_content = "(O que está cantando? O refrão é muito harmonioso. Por quem está de luto? Sei que está enterrado.)",
  ui_story_5_7_28_dialog_content = "(Nunca ouvi algo do tipo, ainda assim consigo cantarolar junto com você.)",
  ui_story_5_7_29_dialog_content = "(Agradeço por tocar para mim. Para sempre me lembrarei dessa sinfonia.)",
  ui_story_5_7_30_dialog_content = "Meu povo, como queria que estivessem vivos e fossem reais.",
  ui_story_5_7_31_dialog_content = "A Colossus está reiniciando!",
  ui_story_5_7_32_dialog_content = "A Colossus está murmurando. Parece um choro, mas não exatamente...",
  ui_story_5_7_33_dialog_content = "Parece que alguém está cantarolando junto com PlayerName.",
  ui_story_5_7_34_dialog_content = "Me deixe ajudar, PlayerName.",
  ui_story_5_7_35_dialog_content = "Quase lá... 5, 4... Engatado com sucesso!",
  ui_story_5_7_36_dialog_content = "Olha, é a <color=#FFB400>Unidade de Crescimento Autônomo</color>!",
  ui_story_5_7_37_dialog_content = "Pega, rápido...",
  ui_story_5_7_38_dialog_content = "O que está acontecendo?",
  ui_story_5_7_39_dialog_content = "<anim type=Shake>*Rugindo*</anim>",
  ui_story_5_7_40_dialog_content = "Parece que cheguei no momento perfeito.",
  ui_story_5_7_41_dialog_content = "Schummer?!",
  ui_story_5_7_A3_dialog_content = "E você deve ser PlayerName.",
  ui_story_5_7_A4_dialog_content = "Você é bem mais jovem do que pensei. Amei a surpresa e o medo estampados no seu rosto.",
  ui_story_5_7_42_dialog_content = "Chega de cantar. De qualquer forma, bom trabalho extraindo a Unidade de Crescimento Autônomo.",
  ui_story_5_7_A5_dialog_content = "Realmente é você, Schummer, bem na minha frente...",
  ui_story_5_7_45_dialog_content = "A dor... Ah, a dor...",
  ui_story_5_7_46_dialog_content = "Por favor, alguém nos salve...",
  ui_story_5_7_47_dialog_content = "Você me lembra dos Celestitas que esmaguei como formigas, PlayerName.",
  ui_story_5_7_48_dialog_content = "Toda vez que lembro que fazia parte dos submissos, eu sinto tanto... nojo.",
  ui_story_5_7_49_dialog_content = "Você fala demais.",
  ui_story_5_7_50_dialog_content = "É assim que você retruca? Que decepcionante.",
  ui_story_5_7_51_dialog_content = "Foi você que enviou aqueles monstros imundos para atacar Lumópolis?",
  ui_story_5_7_52_dialog_content = "Você os chama de monstros, eu chamo de ineptos.",
  ui_story_5_7_53_dialog_content = "O que você fez é imperdoável e vai pagar por isso!",
  ui_story_5_7_54_dialog_content = "E como vai fazer isso?",
  ui_story_5_7_55_dialog_content = "PlayerName! Você está bem?!",
  ui_story_5_7_A6_dialog_content = "(Mantenha a calma... Não posso deixá-la me atingir. Eu consigo...)",
  ui_story_5_7_A7_dialog_content = "(Só siga a rotina de sempre e podemos derrotar a Schummer, a culpada de toda essa atrocidade.)",
  ui_story_5_7_A8_dialog_content = "PlayerName, parece que você está...",
  ui_story_5_7_A9_dialog_content = "Ufa...",
  ui_story_5_7_A10_dialog_content = "Estou bem, Vice. Fique na sua posição com Carleen como sempre, eu vou liderar.",
  ui_story_5_7_A11_dialog_content = "Certo, tudo pronto!",
  ui_story_5_7_56_dialog_content = "Assuma o comando, PlayerName. Minha lança irá perfurar todo esse mal!",
  ui_story_5_7_57_dialog_content = "Preparem-se para lutar! Nossa inimiga é a Schummer!",
  ui_story_5_7_A12_dialog_content = "Os fracos devem se submeter à destruição.",
  ui_story_5_7_58_dialog_content = "Está com dificuldades? Devo repetir que você deve deitar-se como a ovelha submissa que você é?",
  ui_story_5_7_59_dialog_content = "Tsc, você é difícil. Com toda essa liderança e conversa de coordenação, ainda assim é covarde desviando da luta real.",
  ui_story_5_7_60_dialog_content = "Mas devo admitir, de alguma forma você é diferente dos outros Celestitas.",
  ui_story_5_7_61_option_content = "Não, sou apenas igual a qualquer outro Celestita.",
  ui_story_5_7_62_option_content = "Te derrotar é apenas\ncomo roubar doce de criança.",
  ui_story_5_7_63_dialog_content = "Pare de bobeira. Não foi um elogio. Foi apenas um discurso fúnebre.",
  ui_story_5_7_64_dialog_content = "Afinal, a meu ver você não é nada.",
  ui_story_5_7_65_dialog_content = "Quanto poder...",
  ui_story_5_7_66_dialog_content = "Escolhe um, espremido ou esmagado?",
  ui_story_5_7_67_dialog_content = "Agora!",
  ui_story_5_7_68_dialog_content = "Que vibração é essa...?",
  ui_story_5_7_69_dialog_content = "Segundos a mais no cronômetro! Somos muito bons em enrolar!",
  ui_story_5_7_70_dialog_content = "Peguei o módulo, Carleen e PlayerName!",
  ui_story_5_7_71_dialog_content = "Vou fazer uma intervenção e te dar cobertura. Pegue o módulo e saia.",
  ui_story_5_7_72_option_content = "Mas Gronru...",
  ui_story_5_7_73_dialog_content = "Qual o problema? Estou morrendo de vontade de mostrar meu ataque mortal!",
  ui_story_5_7_74_option_content = "Sim, senhora!",
  ui_story_5_7_75_dialog_content = "Você fez bem em explorar as regras do jogo! Agora leve o módulo de volta para Ilumina!",
  ui_story_5_7_76_dialog_content = "Mas Schummer pode ser muito forte para você...",
  ui_story_5_7_77_dialog_content = "Ei, eu não sou uma pesquisadora comum! Entendo mais de poder que qualquer um! E sou muito poderosa!",
  ui_story_5_7_78_dialog_content = "Certo. Vamos lá, Vice e PlayerName. Não podemos desperdiçar a chance que Gronru nos deu.",
  ui_story_5_7_79_dialog_content = "Chega de conversinha, entregue o módulo.",
  ui_story_5_7_80_dialog_content = "E agora o que fazer? Realmente quero lutar com você.",
  ui_story_5_7_A13_dialog_content = "Uma luta de chefe no modo difícil contra a Celestita que controla o poder Eclipsita... Parece tão empolgante!",
  ui_story_5_7_81_dialog_content = "Venha, vamos brincar!",
  ui_story_5_7_82_dialog_content = "Você me entedia.",
  ui_story_5_7_83_dialog_content = "Já faz um tempo, Vice, e nada de notícias da Gronru.",
  ui_story_5_7_84_dialog_content = "Gronru vai ficar bem... eu acho.",
  ui_story_5_7_85_dialog_content = "Não podemos perder tempo. Precisamos ir agora.",
  ui_story_5_7_86_dialog_content = "Eu sei.",
  ui_story_5_7_87_dialog_content = "Você ouviu isso?",
  ui_story_5_7_88_dialog_content = "São...",
  ui_story_5_7_89_dialog_content = "<color=#FFB400>Madame Gronru</color>?!",
  ui_story_5_8_1_dialog_content = "Vice, saia com Soroz e o módulo imediatamente, vá...",
  ui_story_5_8_2_dialog_content = "Madame Gronru!",
  ui_story_5_8_3_dialog_content = "Cala a boca! Foi isso que eu falei para você dizer?!",
  ui_story_5_8_4_dialog_content = "Escutem aqui, seus aproveitadores, porque não vou repetir.",
  ui_story_5_8_5_dialog_content = "Voltem aqui em 30 minutos e me entreguem a Unidade de Crescimento Autônomo, ou essa inútil morre.",
  ui_story_5_8_6_dialog_content = "Não a escute! Saia agora, Vice! É uma ordem!",
  ui_story_5_8_7_dialog_content = "Rápido!",
  ui_story_5_8_8_dialog_content = "30 minutos não é nem o suficiente para Illumina enviar ajuda.",
  ui_story_5_8_9_dialog_content = "Muito mais vidas serão salvas se trouxermos a Unidade de Crescimento Autônomo de volta.",
  ui_story_5_8_10_dialog_content = "Eu sei que deveria obedecer a ordens de superiores. Isso sempre é a prioridade de um Illuminano.",
  ui_story_5_8_11_dialog_content = "Mas não consigo suportar deixar a Gronru para morrer.",
  ui_story_5_8_12_dialog_content = "Sendo boazinha, acho que você está sendo gentil como sempre... ou indecisa, para não ser tão boazinha.",
  ui_story_5_8_13_dialog_content = "É tão difícil assim decidir entre uma e muitas vidas?",
  ui_story_5_8_14_dialog_content = "Eu quero proteger todos.",
  ui_story_5_8_15_dialog_content = "*Rugindo*",
  ui_story_5_8_16_dialog_content = "Agora vamos nos livrar dos convidados não desejados da Colossus e nos preocupar com isso depois.",
  ui_story_5_10_1_dialog_content = "Deixa eu adivinhar porque vocês aproveitadores ainda não decidiram... Tentando enrolar de novo?",
  ui_story_5_10_2_dialog_content = "Minha paciência está acabando. Vocês ainda têm 20... Não, 19 minutos restantes.",
  ui_story_5_10_3_dialog_content = "Vou começar a parti-la em pedacinhos em 19 minutos.",
  ui_story_5_10_4_dialog_content = "Ah, fico ansiosa só de imaginar seus gritos agonizantes.",
  ui_story_5_10_5_dialog_content = "Não há outra maneira de salvar Gronru sem entregar o módulo?",
  ui_story_5_10_6_dialog_content = "Ela é insana!",
  ui_story_5_10_7_option_content = "Deve ter outro jeito.",
  ui_story_5_10_8_dialog_content = "Hã?",
  ui_story_5_10_9_dialog_content = "Tenho uma ideia que pode funcionar em 15 minutos.",
  ui_story_5_10_10_dialog_content = "Como assim?",
  ui_story_5_10_11_dialog_content = "Talvez a gente possa fazer de forma indireta...",
  ui_story_5_10_12_option_content = "Eu quero proteger todos.",
  ui_story_5_10_13_dialog_content = "Concorda comigo, PlayerName?",
  ui_story_5_10_14_dialog_content = "Sim. Seja Gronru ou qualquer outra pessoa, devemos proteger todos.",
  ui_story_5_10_15_dialog_content = "Primeiro Vice, agora você. Eu desisto.",
  ui_story_5_10_16_dialog_content = "Mas já que fala assim, deve ter um plano.",
  ui_story_5_10_17_dialog_content = "Sim. É bem arriscado, e vou precisar da sua ajuda.",
  ui_story_5_10_A1_dialog_content = "Teremos que ser agressivos e nos mover rapidamente!",
  ui_story_5_10_A2_dialog_content = "Me escute, vai ser o seguinte...",
  ui_story_5_10_18_dialog_content = "Só alguns minutos restantes. Não resolveram nada. Ainda estão discutindo?",
  ui_story_5_10_19_dialog_content = "Ativar Trono!",
  ui_story_5_10_20_dialog_content = "Que imprudente!",
  ui_story_5_10_21_dialog_content = "Falhou novamente!",
  ui_story_5_10_22_dialog_content = "Você deve querer muito morrer, já foram três tentativas de suicídio.\n Felizmente, ainda não chegou sua hora de morrer.",
  ui_story_5_10_23_dialog_content = "Um combo chocante...",
  ui_story_5_10_24_dialog_content = "Que tontura! O jogo acabou...?",
  ui_story_5_10_25_dialog_content = "Vá dormir. Em breve me livro de você para sempre.",
  ui_story_5_10_A3_dialog_content = "Aqui vai mais um!",
  ui_story_5_10_A4_dialog_content = "Muito bom! Schummer não notou, não é?",
  ui_story_5_10_A5_dialog_content = "Não sirvo muito para operações secretas, PlayerName.",
  ui_story_5_10_A6_dialog_content = "Está indo muito bem. Vamos continuar, não temos outra escolha.",
  ui_story_5_13_1_dialog_content = "Levante, ainda tem 5 minutos.",
  ui_story_5_13_2_dialog_content = "Vejo estrelas... Consigo subir de nível ao coletá-las?",
  ui_story_5_13_3_dialog_content = "Levanta agora, caramba.",
  ui_story_5_13_4_dialog_content = "Ei, bem malvado da sua parte me desmaiar e acordar logo em seguida!",
  ui_story_5_13_5_dialog_content = "5 minutos restantes e sem resposta até agora. Provavelmente te abandonaram.",
  ui_story_5_13_6_dialog_content = "Tomara! Eu bato neles por você se eles se atreverem a voltar.",
  ui_story_5_13_7_dialog_content = "Bom, cansei de esperar de todo jeito.",
  ui_story_5_13_A1_dialog_content = "Não é o melhor, mas acabar com você e matar eles depois não parece tão ruim.",
  ui_story_5_13_8_dialog_content = "Ei, agora vai matar a refém antes do tempo acabar? Não é assim que se joga!",
  ui_story_5_13_9_dialog_content = "Tenho uma novidade para você, os fortes sempre ditam as regras do jogo!",
  ui_story_5_13_A2_dialog_content = "Agora, vou calar esse seu bocão pela última vez!",
  ui_story_5_13_10_dialog_content = "Mas que...?!",
  ui_story_5_13_11_dialog_content = "Gelescer!",
  ui_story_5_13_12_dialog_content = "Mais um ataque surpresa...",
  ui_story_5_13_13_dialog_content = "Ela está impaciente. Acho que ela pode nem seguir os termos.",
  ui_story_5_13_14_dialog_content = "Gronru está em grande perigo. Devemos agir o mais rápido que pudermos.",
  ui_story_5_13_A3_dialog_content = "Estou pronta para seguir o seu plano, PlayerName!",
  ui_story_5_13_A13_dialog_content = "Vamos deixar Soroz ficar onde estávamos para distrair Schummer...",
  ui_story_5_13_17_dialog_content = "Dispare um ataque surpresa! Ela nunca vai esperar que a gente a pegue desprevenida assim!",
  ui_story_5_13_18_dialog_content = "Fingir indecisão, e então emboscar?",
  ui_story_5_13_19_dialog_content = "Bem, funcionou, não foi? Renda-se, Schummer! Também fizemos a limpa nos Eclipsitas!",
  ui_story_5_13_20_dialog_content = "Se chamam isso de “funcionar”...",
  ui_story_5_13_21_dialog_content = "Não esqueçam de mim! Ráá!",
  ui_story_5_13_22_dialog_content = "O combo funcionou! A Malvadona está ferida e reagrupamos a equipe! O Jogo virou!",
  ui_story_5_13_A4_dialog_content = "Suponho que você escondeu aquele módulo essencial em um lugar seguro? Agora podemos nos unir contra ela de forma justa!",
  ui_story_5_13_24_dialog_content = "Vamos lá, Carleen!",
  ui_story_5_13_26_dialog_content = "Sim, põe ela no lugar dela!",
  ui_story_5_13_27_dialog_content = "Isso é tudo que você tem?",
  ui_story_5_13_28_dialog_content = "Não acredito que vocês imprestáveis me subestimaram.",
  ui_story_5_13_29_dialog_content = "Estou sentindo uma mudança!",
  ui_story_5_13_30_dialog_content = "O poder dela parece completamente diferente!",
  ui_story_5_13_31_dialog_content = "Chega! Já que todos parecem tão ansiosos para morrer, não devo poupar esforços!",
  ui_story_5_13_A14_dialog_content = "Ótimo, estão lutando melhor! Agora está quase divertido...",
  ui_story_5_13_A15_dialog_content = "Mas sua arrogância só me irrita mais! Ajoelhem!",
  ui_story_5_13_A16_dialog_content = "Como ela está ficando ainda mais poderosa?",
  ui_story_5_13_A17_dialog_content = "Então estava se segurando... só para brincar com a gente?",
  ui_story_5_13_32_dialog_content = "(Todos nós vamos morrer se ela continuar!)",
  ui_story_5_13_A5_dialog_content = "(Meu povo também lutou desesperançosamente assim? Esse poder é esmagador...)",
  ui_story_5_13_33_dialog_content = "(Um Celestita com poder Eclipsita pode ser devastador assim?)",
  ui_story_5_13_34_dialog_content = "Chocados e intimidados? O Eclipse pode tornar até mesmo um Celestita fraco em alguém invencível.",
  ui_story_5_13_35_dialog_content = "<size=45>Mais forte até que Aurorians!</size>",
  ui_story_5_13_36_dialog_content = "Dói tanto... não consigo... respirar...",
  ui_story_5_13_37_dialog_content = "Decidam agora, a vida dela ou a Unidade de Crescimento Autônomo?",
  ui_story_5_13_38_dialog_content = "*Tosse* Não, não dê para ela...",
  ui_story_5_13_39_dialog_content = "Gronru! Vice, Carleen...",
  ui_story_5_13_40_dialog_content = "Ainda consigo lutar, droga... sei que consigo...",
  ui_story_5_13_41_dialog_content = "Eu...",
  ui_story_5_13_42_dialog_content = "Está considerando lutar comigo? Sem nenhum poder Lúmina?",
  ui_story_5_13_43_dialog_content = "Minha nossa, isso é fofo e ridículo ao mesmo tempo!",
  ui_story_5_13_44_dialog_content = "Posso não ter Lúmina, mas tenho minhas mãos!",
  ui_story_5_13_45_dialog_content = "Schummer!",
  ui_story_5_13_46_dialog_content = "Não, PlayerName!",
  ui_story_5_13_47_dialog_content = "Mesmo que eu não consiga controlar Lúmina, não tenho medo de lutar!",
  ui_story_5_13_48_dialog_content = "Preciso defender meus companheiros, meu povo e minha família!",
  ui_story_5_13_A6_dialog_content = "Se eu quebrar as mãos, posso morder. Se eu perder meus dentes, bato com a cabeça!",
  ui_story_5_13_A7_dialog_content = "Não pode fazer eu me render, Schummer. Agora, você vai...",
  ui_story_5_13_49_dialog_content = "<size=45>ter que me enfrentar para chegar neles!</size>",
  ui_story_5_13_A8_dialog_content = "...",
  ui_story_5_13_A9_dialog_content = "Qual o sentido disso?",
  ui_story_5_13_50_dialog_content = "Precisa gritar? O discurso heroico é muito clichê.",
  ui_story_5_13_51_dialog_content = "Ugh...",
  ui_story_5_13_52_dialog_content = "Por que, PlayerName?",
  ui_story_5_13_53_dialog_content = "Tomem uma decisão, perdedores. O módulo ou a vida deles. Estou contando. Dez, nove...",
  ui_story_5_13_54_option_content = "Tenho uma proposta...",
  ui_story_5_13_55_option_content = "Está bem, aqui está o módulo.",
  ui_story_5_13_56_dialog_content = "Você tem uma proposta para mim? Sério?",
  ui_story_5_13_57_dialog_content = "Você pode ficar com o módulo, mas precisa deixá-las ir primeiro!",
  ui_story_5_13_58_dialog_content = "Está falando sério? Deveria se ajoelhar e pedir misericórdia.",
  ui_story_5_13_59_dialog_content = "Você as deixa ir e pode ficar comigo e com o módulo. Caso contrário, eu o destruo.",
  ui_story_5_13_60_dialog_content = "Destruir? Você pegou essa expressão de “tentar até o fim” do Mendelson? Que nojento.",
  ui_story_5_13_F1_dialog_content = "Certo. Elas podem ir.",
  ui_story_5_13_F2_dialog_content = "Aqui está o módulo.",
  ui_story_5_13_F3_dialog_content = "Pobres Celestitas. Sem poder, só lhes resta serem massacrados. Sua sobrevivência depende da caridade dos fortes.",
  ui_story_5_13_F4_dialog_content = "Oh, isso te magoou?",
  ui_story_5_13_F5_dialog_content = "Isso te lembrou do passado?",
  ui_story_5_13_F6_dialog_content = "Lembre-se do sentimento. Os <size=45>fracos</size> devem sofrer humilhações apenas para sobreviver.",
  ui_story_5_13_61_dialog_content = "Pobres Celestitas. Sem poder, só lhes resta serem massacrados. Sua sobrevivência depende da caridade dos fortes.",
  ui_story_5_13_F7_dialog_content = "Eu nem mesmo olharia para vocês se não fosse pelo módulo.",
  ui_story_5_13_68_dialog_content = "Parabéns por receber a oportunidade de viver. Aproveite!",
  ui_story_5_13_69_dialog_content = "Você está bem, Gronru? Ficou apagada por duas horas...",
  ui_story_5_13_70_dialog_content = "Não se preocupe, sou teimosa demais para morrer...",
  ui_story_5_13_F8_dialog_content = "Sinto muito você ter que entregar o módulo para me salvar.",
  ui_story_5_13_71_dialog_content = "Não, a culpa é nossa por não sermos fortes o bastante para derrotá-la.",
  ui_story_5_13_72_dialog_content = "Ao menos todos estão vivos. Poderia ser pior.",
  ui_story_5_13_73_dialog_content = "Você já é bem impressionante!",
  ui_story_5_13_74_dialog_content = "Eu não acreditei quando Philyshy me contou, mas agora que vi com meus olhos...",
  ui_story_5_13_A10_dialog_content = "Schummer é muito mais poderosa que imaginei!",
  ui_story_5_13_75_dialog_content = "Vou arrumar tudo, reportar aos meus superiores e alertá-los sobre a gravidade dessa situação.",
  ui_story_5_13_76_dialog_content = "Não há um terceiro módulo?",
  ui_story_5_13_77_dialog_content = "O <color=#FFB400>Controlador de Chamas...</color>",
  ui_story_5_13_78_dialog_content = "O componente ultra-arma para atualizar uma Colossus e equipá-la com capacidades ofensivas... Mas não sabemos sua localização.",
  ui_story_5_13_79_option_content = "Eu sei o que fazer.",
  ui_story_5_13_F9_dialog_content = "Já a vi tantas vezes que nunca esquecerei sua presença.",
  ui_story_5_13_F10_dialog_content = "Ela não está longe de nós. Tudo que preciso fazer é fechar meus olhos.",
  ui_story_5_13_F11_dialog_content = "Ela não vai me notar, contanto que consiga entrar de mansinho.",
  ui_story_5_13_80_dialog_content = "(Isso é um labirinto bizantino com inúmeras armadilhas?)",
  ui_story_5_13_81_dialog_content = "(Enigmático, sombrio e cheio de coleções perversas...)",
  ui_story_5_13_82_dialog_content = "Schummer com certeza sabia para onde ir.",
  ui_story_5_13_83_dialog_content = "O <color=#FFB400>Corredor Suspirante</color>...",
  ui_story_5_13_85_option_content = "O Corredor Suspirante!",
  ui_story_6_1_1_dialog_content = "Schummer é uma oponente perigosa, não tenho dúvida disso...",
  ui_story_6_1_2_dialog_content = "Ela vai ser ainda mais difícil de derrotar se conseguir coletar todos os módulos necessários...",
  ui_story_6_1_3_dialog_content = "(Carleen e Vice estão muito deprimidas. Talvez eu deva dizer algo?)",
  ui_story_6_1_F1_dialog_content = "Se formos atrás de Schummer agora, talvez a gente consiga impedi-la de encontrar o próximo módulo!",
  ui_story_6_1_F2_dialog_content = "Obviamente, será perigoso...",
  ui_story_6_1_4_option_content = "Então, o que você acha, Carleen?",
  ui_story_6_1_5_dialog_content = "Eu concordo. Não há tempo a perder. Devemos perseguir a Schummer agora mesmo!",
  ui_story_6_1_6_option_content = "O que você acha, Vice?",
  ui_story_6_1_7_dialog_content = "Já enviei uma mensagem para o QG avisando que estamos a caminho do <color=#FFB400>Corredor Suspirante</color>.",
  ui_story_6_1_8_dialog_content = "Alguém sabe alguma coisa sobre o Corredor Suspirante?",
  ui_story_6_1_9_dialog_content = "Tenho certeza de que está sob o controle de <color=#FFB400>Umbraton</color>, Carleen. Ouvi isso quando era estudante em Lumópolis.",
  ui_story_6_1_10_dialog_content = "Não esperava menos de uma estudante certinha como você. Aposto que pode nos dizer mais?",
  ui_story_6_1_11_dialog_content = "Uhm, cof, o Corredor Suspirante é uma ruína antiga fora de Umbraton.",
  ui_story_6_1_12_dialog_content = "Depois de Lumópolis descobri-la, escavações revelaram uma abundância de achados arqueológicos valiosos.",
  ui_story_6_1_13_dialog_content = "Entretanto, quando não acharam mais nada valioso, o interesse diminuiu e a ruína foi abandonada.",
  ui_story_6_1_14_dialog_content = "Desde então, tornou-se o centro de nômades e foras da lei, e um viveiro para crimes.",
  ui_story_6_1_A1_dialog_content = "Cerca de uma década atrás, uma organização conhecida como <color=#FFB400>Gangue Istvan</color> apareceu em Umbraton.",
  ui_story_6_1_A2_dialog_content = "Istvan, o líder da organização que leva o seu nome, desfruta de uma alta posição entre o povo de Umbraton e é chamado de “Senhor Sombrio”.",
  ui_story_6_1_A3_dialog_content = "Logo após Istvan assumir o controle do Corredor Suspirante, ele tornou-se um lugar onde ninguém ousava entrar.",
  ui_story_6_1_A4_dialog_content = "Boatos dizem que agora é repositório para todos os tipos de antiguidades preciosas e desconhecidas.",
  ui_story_6_1_A5_dialog_content = "É muito conveniente ter uma enciclopédia ambulante com a gente.",
  ui_story_6_1_F3_dialog_content = "Hehe, de nada!",
  ui_story_6_1_A6_dialog_content = "Também enviei uma mensagem para o Senhor Sombrio solicitando sua ajuda.",
  ui_story_6_1_A7_dialog_content = "Quem sabe... Talvez já tenha até alguém esperando para nos guiar no Corredor Suspirante.",
  ui_story_6_1_A8_dialog_content = "Se você tiver escrito do seu jeito, aposto que o Senhor Sombrio simplesmente ignoraria.",
  ui_story_6_1_F4_dialog_content = "Ei, não importa se estava bom ou não! Eu precisava enviar de todo jeito!",
  ui_story_6_1_15_dialog_content = "Oh, tenho mais uma coisa para compartilhar. O exército de Illumina acabou de ter outra reunião...",
  ui_story_6_1_16_dialog_content = "Quero lembrar todos que mesmo que o Corredor Suspirante seja território do Senhor Sombrio, dado o tamanho da ameaça...",
  ui_story_6_1_17_dialog_content = "Assim como o envolvimento da Oficial de Tecnologia Gronru, isso é uma provocação descarada.",
  ui_story_6_1_F5_dialog_content = "Se não fosse por PlayerName e companhia entregando a notícia, os planos de Schummer continuariam desconhecidos para nós.",
  ui_story_6_1_18_dialog_content = "Droga, se não fossem aqueles pirralhos, nada disso teria acontecido!",
  ui_story_6_1_19_dialog_content = "Errou. A existência de PlayerName não tem nada a ver com o objetivo de Schummer de conseguir os módulos.",
  ui_story_6_1_20_dialog_content = "Me poupe desse discurso, Hiiro! Suas tropas irão comigo ou não?",
  ui_story_6_1_21_dialog_content = "Bom...",
  ui_story_6_1_22_dialog_content = "Não é que eu não queira. Eu compartilho do mesmo sentimento que você em relação àqueles que ameaçam Illumina.",
  ui_story_6_1_23_dialog_content = "Mas a Grande Marechal nos ordenou ficar à espera pela oportunidade certa.",
  ui_story_6_1_X23_dialog_content = "Por que a Grande Marechal ordenaria isso?",
  ui_story_6_1_X24_dialog_content = "Fiquem frios, galera. Eu entendo como se sentem.",
  ui_story_6_1_X25_dialog_content = "Entretanto, apenas podemos esperar até recebermos novas ordens da Grande Marechal.",
  ui_story_6_1_X26_dialog_content = "Provavelmente ela entende a situação muito melhor que nós. Devíamos ter fé em Illumina!",
  ui_story_6_1_X27_dialog_content = "...",
  ui_story_6_1_X28_dialog_content = "Onde estão Barton e seu povo? Por que não apareceram?",
  ui_story_6_1_X29_dialog_content = "Se ele e a mulher musculosa concordaram em mobilizar, poderíamos barganhar com a Grande Marechal para...",
  ui_story_6_1_X30_dialog_content = "Outros Comandantes da Legião também receberam suas atribuições temporárias.",
  ui_story_6_1_X31_dialog_content = "Sharona, você vem comigo para defender os subúrbios de Lumópolis!",
  ui_story_6_1_25_dialog_content = "No mínimo, ainda temos que entregar um bom show!",
  ui_story_6_1_27_dialog_content = "Então essa é a situação atual. Estamos sozinhos para descobrir o que Schummer pretende fazer.",
  ui_story_6_1_28_dialog_content = "Tivemos sorte o bastante tendo Philyshy e Gronru ajudando da última vez, mas agora...",
  ui_story_6_1_F6_dialog_content = "Nosso destino está sob jurisdição de Umbraton, e Umbraton está bem abaixo de Lumópolis...",
  ui_story_6_1_F7_dialog_content = "Eu entendo. Illumina e Lumópolis podem estar trabalhando juntas, mas ambas têm suas dúvidas.",
  ui_story_6_1_29_dialog_content = "Mesmo assim, brincar de política não será bom para nenhum dos lados, especialmente na situação em que estamos.",
  ui_story_6_1_30_dialog_content = "Pelo menos me deixe ajudar em Lumópolis...",
  ui_story_6_1_31_dialog_content = "Relatório de estado, Capitã Carleen?",
  ui_story_6_1_32_dialog_content = "Sinto muito, mas falhamos. A <color=#FFB400>Unidade de Crescimento Autônomo</color> foi levada.",
  ui_story_6_1_33_dialog_content = "Alguma baixa?",
  ui_story_6_1_34_dialog_content = "Nenhuma.",
  ui_story_6_1_35_dialog_content = "Infelizmente, estão um passo à nossa frente e partiram em direção ao Corredor Suspirante.",
  ui_story_6_1_36_dialog_content = "Senhor Schwartz, humildemente peço a ajuda dos Guardiões, de preferência os Quatro Anjos.",
  ui_story_6_1_37_dialog_content = "Recusado.",
  ui_story_6_1_38_dialog_content = "Mas pa... quero dizer, meu senhor, se ela conseguir o <color=#FFB400>Controlador de Chamas</color>, as consequências serão extremas!",
  ui_story_6_1_39_dialog_content = "Ela pode até ameaçar Lumópolis novamente depois de recarregar sua Colossus!",
  ui_story_6_1_40_dialog_content = "Sim, já considerei isso Capitã Carleen, e é por isso que decidi não enviar os Guardiões.",
  ui_story_6_1_41_dialog_content = "Como Capitã deles, tenho autoridade sobre os Guardiões, meu Senhor. Por favor, me deixe mobilizá-los.",
  ui_story_6_1_42_dialog_content = "Eu posso facilmente revogar essa autoridade, Capitã.",
  ui_story_6_1_43_dialog_content = "Então, como Capitã, vou fornecer reforços a eles em nome de Lumópolis, mesmo que seja por minha conta.",
  ui_story_6_1_45_dialog_content = "Eu admiro sua coragem, Carleen.",
  ui_story_6_1_46_dialog_content = "PlayerName! Como cidadão de Lumópolis, espero que você garanta a segurança de Carleen.",
  ui_story_6_1_47_dialog_content = "O que...? Sim, claro.",
  ui_story_6_1_48_dialog_content = "<size=30>PlayerName e eu nem moramos em Lumópolis...</size>",
  ui_story_6_1_49_dialog_content = "Mesmo se Carleen não fosse Capitã, nós nos protegeríamos a todo custo! É isso que amigos fazem!",
  ui_story_6_1_50_dialog_content = "Parem de conversinha. Devemos chegar em instantes.",
  ui_story_6_1_51_dialog_content = "Isso aqui é um deserto até onde os olhos alcançam. Ninguém vem aqui há muito tempo.",
  ui_story_6_1_52_dialog_content = "Felizmente, nós temos Soroz, ou nunca conseguiríamos pegar a Schummer!",
  ui_story_6_1_F8_dialog_content = "Ouviu isso, Soroz? Vice está te elogiando!",
  ui_story_6_1_53_dialog_content = "Meu propósito é servi-lo, Navegador. É uma honra ajudar todos vocês.",
  ui_story_6_1_54_dialog_content = "Entretanto, esse lugar tem a mesma aura ameaçadora de Eraveil... Por favor, sejam cuidadosos.",
  ui_story_6_1_55_dialog_content = "Esse lugar pode estar repleto de Eclipsitas, PlayerName... Soroz estará seguro?",
  ui_story_6_1_56_dialog_content = "Fica perto das colinas, com uma floresta grande o suficiente para cobertura.",
  ui_story_6_1_57_dialog_content = "Não se preocupe, nossa Colossus dominou a arte da camuflagem. Só precisamos focar na luta e Soroz estará esperando por nós quando retornarmos.",
  ui_story_6_1_58_dialog_content = "O sentimento de ter alguém esperando por sua volta é legal. Se além disso ela conseguisse um banho quente para nós...",
  ui_story_6_1_59_dialog_content = "Que uso mais infantil para uma Colossus...",
  ui_story_6_1_A9_dialog_content = "De qualquer forma, não consigo imaginar onde possa haver um repositório aqui nesse deserto.",
  ui_story_6_1_A10_dialog_content = "A entrada do Corredor Suspirante é impossível de encontrar se não fizer uma pesquisa.",
  ui_story_6_1_A11_dialog_content = "Então isso significa que você já...",
  ui_story_6_1_A12_dialog_content = "É isso mesmo, está bem embaixo de nós!",
  ui_story_6_1_A13_dialog_content = "Embaixo de nós? O Corredor Suspirante é subterrâneo?",
  ui_story_6_1_A14_dialog_content = "Cuidado com os pés, vou ativar a entrada!",
  ui_story_6_1_A15_dialog_content = "O chão está desmoronando!",
  ui_story_6_1_A16_dialog_content = "Nossa, isso é...",
  ui_story_6_1_A17_dialog_content = "Muito trabalho para atravessar e construir. Por que alguém projetaria isso assim?",
  ui_story_6_1_A18_dialog_content = "Apenas criminosos e roedores escolheriam se esconder assim em um buraco.",
  ui_story_6_1_A19_dialog_content = "O Corredor Suspirante está bem abaixo de nós. Consegue sentir algo, PlayerName?",
  ui_story_6_1_60_dialog_content = "Schummer... Ela deve estar ali embaixo. Consigo sentir um frio extremo vindo de lá.",
  ui_story_6_1_A20_dialog_content = "Você não estava brincando... Está muito frio aqui embaixo!",
  ui_story_6_1_A21_dialog_content = "Agora não é hora de reclamar. Precisamos nos apressar!",
  ui_story_6_1_61_dialog_content = "Há alguma forma de detectar sua localização exata?",
  ui_story_6_1_62_dialog_content = "Desculpa, só consigo dizer que ela está em algum lugar desse Corredor Suspirante. Não consigo detalhar sua localização.",
  ui_story_6_1_63_dialog_content = "Isso não será fácil...",
  ui_story_6_1_64_dialog_content = "Dizem que o Corredor Suspirante é um labirinto cheio de portas secretas e passagens... e que o Senhor Sombrio supostamente é o único que conhece cada canto daqui.",
  ui_story_6_1_65_dialog_content = "Esse é o principal motivo pelo qual o Corredor Suspirante é considerado um repositório de artefatos inestimáveis.",
  ui_story_6_1_F9_dialog_content = "Guardar as coisas aqui é muito mais seguro que estocá-las em Umbraton, com certeza.",
  ui_story_6_1_66_dialog_content = "Espera, tem alguém vindo!",
  ui_story_6_1_67_dialog_content = "Cuidado! Pode ser um Eclipsita...",
  ui_story_6_1_68_dialog_content = "Considerando a calma de PlayerName, só pode ser um Aurorian.",
  ui_story_6_1_70_dialog_content = "Bom, o que temos aqui? Sabe, consegui ouvir vocês papeando através de todas as portas e paredes daqui!",
  ui_story_6_1_71_dialog_content = "Que interessante... Uma senhora mimada de Lumópolis, uma garota ingênua de Illumina e um Celestita...",
  ui_story_6_1_72_dialog_content = "Parece que vocês são o “Esquadrão Colossus” do qual todos os chefões estão falando ultimamente.",
  ui_story_6_1_73_dialog_content = "Lumópolis e Illumina estão contentes em esperar e assistir, mas o Senhor Sombrio me escolheu para ajudar vocês.",
  ui_story_6_1_X73_dialog_content = "Nossa, que majestoso pé no...",
  ui_story_6_1_74_dialog_content = "Parece que temos muita sorte!",
  ui_story_6_1_F10_dialog_content = "Meu nome é Sheol. Então, como posso ser útil?",
  ui_story_6_1_75_option_content = "Você viu mais alguém\nvindo por aqui?",
  ui_story_6_1_76_dialog_content = "Poucas pessoas vêm aqui. Um punhado de Eclipsitas desceram aqui, mas nada se perdeu.",
  ui_story_6_1_77_dialog_content = "Schummer...",
  ui_story_6_1_78_dialog_content = "Estou me preocupando mais com o inimigo de vocês... Estão aqui bem agora, não estão?",
  ui_story_6_1_79_dialog_content = "Bom, estou mais preocupada com você nos espionando antes de dar as caras.",
  ui_story_6_1_80_dialog_content = "Suas garotas têm a língua afiada, PlayerName!",
  ui_story_6_1_81_dialog_content = "Uhm, Senhora Sheol, tudo bem se não quiser falar disso com a gente, mas pode ao menos nos contar sobre esse lugar?",
  ui_story_6_1_82_dialog_content = "Bom, todos sabem que isso aqui costumava ser uma grande ruína.",
  ui_story_6_1_83_dialog_content = "Daquele jeito, não era muito valiosa... Então o Senhor Sombrio decidiu comprá-la. Ele é o único que conhece o lugar de ponta a ponta.",
  ui_story_6_1_84_dialog_content = "Mesmo que não tenham guardas aqui, a maioria dos intrusos meia boca, ou caem em uma armadilha, ou se perdem.",
  ui_story_6_1_85_dialog_content = "É quase impossível encontrar o que quer... sem um guia adequado, claro.",
  ui_story_6_1_86_dialog_content = "Bom, quem é nosso guia?",
  ui_story_6_1_87_dialog_content = "Está vendo mais alguém aqui?",
  ui_story_6_1_88_dialog_content = "Ah, entendi! Então, por favor, guie o caminho.",
  ui_story_6_1_89_dialog_content = "Hã? Quando concordei em ser guia de vocês?",
  ui_story_6_1_90_dialog_content = "Você tem sorte, PlayerName, essa garota é tão doce...",
  ui_story_6_1_91_dialog_content = "Acho que você entendeu mal, Senhora Sheol.",
  ui_story_6_1_92_dialog_content = "Sabe o que estamos procurando? Já ouviu falar do Controlador de Chamas?",
  ui_story_6_1_93_dialog_content = "Uhm, não sei nada sobre.",
  ui_story_6_1_94_option_content = [[
Pode nos contar
sobre esse lugar, por favor?]],
  ui_story_6_1_95_dialog_content = "Bom, todos sabem que isso aqui costumava ser uma grande ruína.",
  ui_story_6_1_96_dialog_content = "Daquele jeito, não era muito valiosa... Então o Senhor Sombrio decidiu comprá-la. Ele é o único que conhece o lugar de ponta a ponta.",
  ui_story_6_1_97_dialog_content = "Mesmo que não tenham guardas aqui, a maioria dos intrusos meia boca, ou caem em uma armadilha, ou se perdem.",
  ui_story_6_1_98_dialog_content = "É quase impossível encontrar o que quer... sem um guia adequado, claro.",
  ui_story_6_1_99_dialog_content = "Bom, quem é nosso guia?",
  ui_story_6_1_100_dialog_content = "Está vendo mais alguém aqui?",
  ui_story_6_1_101_dialog_content = "Ah, entendi! Então, por favor, guie o caminho.",
  ui_story_6_1_102_dialog_content = "Quando foi que eu disse que era o guia, docinho?",
  ui_story_6_1_103_dialog_content = "PlayerName, suas amigas são muito educadas e queridas.",
  ui_story_6_1_104_dialog_content = "Uhm, Senhora Sheol, por favor, não mude de assunto. Estamos com pressa...",
  ui_story_6_1_105_dialog_content = "Estão? Ah, sim, talvez seu inimigo já esteja aqui.",
  ui_story_6_1_106_dialog_content = "Há rastros de Eclipsitas por toda a parte e todos vão para o Corredor Suspirante...",
  ui_story_6_1_107_dialog_content = "A situação aqui está bem desfavorável, de fato... Qualquer coisa que estejam procurando já pode ter sido levada!",
  ui_story_6_1_108_dialog_content = "Então, se importaria de nos levar até onde o Controlador de Chamas está guardado?",
  ui_story_6_1_109_dialog_content = "O quê? Nunca ouvi falar disso.",
  ui_story_6_1_110_option_content = [[
Na verdade,
estamos procurando algo.]],
  ui_story_6_1_111_dialog_content = "Eu sei. Todos que vêm aqui sempre estão procurando algo. Mas acho que alguns Eclipsitas chegaram antes de vocês.",
  ui_story_6_1_112_dialog_content = "Sei que há Eclipsitas aqui... Precisamos correr!",
  ui_story_6_1_113_dialog_content = "Por que a pressa, tesouro?",
  ui_story_6_1_114_dialog_content = "Bom, todos sabem que isso aqui costumava ser uma grande ruína.",
  ui_story_6_1_115_dialog_content = "Daquele jeito, não era muito valiosa... Então o Senhor Sombrio decidiu comprá-la. Ele é o único que conhece o lugar de ponta a ponta.",
  ui_story_6_1_116_dialog_content = "Mesmo que não tenham guardas aqui, a maioria dos intrusos meia boca, ou caem em uma armadilha, ou se perdem.",
  ui_story_6_1_117_dialog_content = "É quase impossível encontrar o que quer... sem um guia adequado, claro.",
  ui_story_6_1_118_dialog_content = "Bom, quem é nosso guia?",
  ui_story_6_1_119_dialog_content = "Está vendo mais alguém aqui?",
  ui_story_6_1_120_dialog_content = "Ah, entendi. Então, por favor, guie o caminho.",
  ui_story_6_1_121_dialog_content = "Quando eu disse que seria o guia?",
  ui_story_6_1_122_dialog_content = "Você tem sorte, PlayerName. Essa garota é muito doce.",
  ui_story_6_1_123_dialog_content = "Por favor, não disperse, Senhora Sheol...",
  ui_story_6_1_124_dialog_content = "Senhora Sheol, então sabe o que estamos procurando? Já ouviu falar do Controlador de Chamas?",
  ui_story_6_1_125_dialog_content = "Uhm, não sei nada sobre.",
  ui_story_6_1_126_dialog_content = "<size=30>Ela está mentindo.</size>",
  ui_story_6_1_127_dialog_content = "<size=30>Eu sei.</size>",
  ui_story_6_1_128_dialog_content = "Senhora Sheol, não pretendemos intervir sem o seu consentimento. Aquela carta é nossa melhor prova de sinceridade.",
  ui_story_6_1_129_dialog_content = "Eu sei. Então querem impedir a Schummer?",
  ui_story_6_1_130_dialog_content = "Sim. Acredito que ouviu sobre o que aconteceu em Lumópolis.",
  ui_story_6_1_131_dialog_content = "Schummer fará o que for necessário para conseguir o <color=#FFB400>Controlador de Chamas</color>.",
  ui_story_6_1_132_dialog_content = "Quando descobrimos que ela pretendia vir aqui, imediatamente informamos o Senhor Sombrio. Tememos que um número grande de Eclipsitas venha a invadir...",
  ui_story_6_1_F11_dialog_content = "Umbraton pode estar em perigo. É difícil não acreditar em vocês, dada a sinceridade de suas palavras.",
  ui_story_6_1_F12_dialog_content = "Mas como sabem que ela está vindo aqui?",
  ui_story_6_1_F13_dialog_content = "Por favor, quando digo isso, falo a verdade... Posso usar minhas habilidades de Celestita para detectar seu paradeiro.",
  ui_story_6_1_134_dialog_content = "Parece que os Celestitas merecem a sua reputação. Bom, como recompensa por sua sinceridade, serei guia de vocês.",
  ui_story_6_1_135_dialog_content = "Agradeço, contamos com você.",
  ui_story_6_1_136_dialog_content = "Que fofo!",
  ui_story_6_1_137_dialog_content = "Já chegamos? Quantos níveis mais?",
  ui_story_6_1_138_dialog_content = "Nem estamos perto... Acabamos de chegar à periferia, ainda há um longo caminho.",
  ui_story_6_1_139_dialog_content = "Céus, esse lugar é mais confuso que a Cidade Gannon.",
  ui_story_6_1_140_dialog_content = "Por que o Controlador de Chamas está mantido aqui?",
  ui_story_6_1_141_dialog_content = "Dizem que o Senhor Sombrio o encontrou no campo de batalha durante uma guerra contra os Eclipsitas há dez anos.",
  ui_story_6_1_142_dialog_content = "Eu só vi uma vez. Parecia apenas uma relíquia velha e empoeirada.",
  ui_story_6_1_143_dialog_content = "Se não fosse por vocês, talvez continuasse escondido aqui para sempre.",
  ui_story_6_1_144_dialog_content = "Parem. Tem algo estranho aqui...",
  ui_story_6_1_145_dialog_content = "Parece que alguém quebrou essa porta.",
  ui_story_6_1_146_dialog_content = "Considerando o dano, não acho que um Aurorian tenha feito isso.",
  ui_story_6_1_147_dialog_content = "Mas eu não quero lutar!",
  ui_story_6_1_148_dialog_content = "PlayerName, consegue detectar algo?",
  ui_story_6_1_149_dialog_content = "Schummer está aqui.",
  ui_story_6_1_150_dialog_content = "Então ela realmente nos deixou comendo poeira. Estamos longe dela?",
  ui_story_6_1_151_dialog_content = "Não estamos, mas também não estamos perto... Há chance de encontramos Eclipsitas. Tenham cuidado.",
  ui_story_6_1_152_dialog_content = "...",
  ui_story_6_1_153_dialog_content = "Ainda podemos dar a volta por cima! Há uma chance dela se perder sem um guia, mas nós temos...",
  ui_story_6_1_154_dialog_content = "Ei, guia, aonde está indo? Estamos indo ao contrário?",
  ui_story_6_1_155_dialog_content = "Está recuando, Senhora Sheol?",
  ui_story_6_1_156_dialog_content = "Bom, é realmente muito perigoso. Senhora Sheol, não vamos te forçar...",
  ui_story_6_1_157_dialog_content = "De fato é um plano perigoso, mas aqueles que fogem da batalha apenas escrevem a ruína de seus aliados.",
  ui_story_6_1_158_dialog_content = "Quando foi que eu disse que iria fugir? Eu disse que guiaria vocês, não disse?",
  ui_story_6_1_159_dialog_content = "Mas não sou uma boa lutadora, então não posso ajudar vocês nisso...",
  ui_story_6_1_160_dialog_content = "Mas como vai nos guiar se não está com a gente? A distância?",
  ui_story_6_1_161_dialog_content = "Como a doce Vice sugeriu, vou ficar aqui e manter contato com vocês!",
  ui_story_6_1_162_dialog_content = "Contanto que possam me dizer o que estão vendo ao redor de vocês, vou saber exatamente onde estão.",
  ui_story_6_1_163_dialog_content = "Eu sei... Afinal, é assim que funcionam as coisas em Umbraton, Vice.",
  ui_story_6_1_164_dialog_content = "Mas não quis dizer que ela deveria nos guiar a distância. Senhora Sheol, acho que seria melhor irmos juntos.",
  ui_story_6_1_165_dialog_content = "É? Bom, isso faz sentido! Então vou esperar vocês lá fora! Vou guiar vocês a distância e manter contato!",
  ui_story_6_1_168_dialog_content = "Além disso, se conseguir sair com vida, PlayerName...",
  ui_story_6_1_169_dialog_content = "Lembre-se de visitar a minha loja! Agora que somos conhecidos, terão ofertas especiais para você!",
  ui_story_6_1_170_dialog_content = "Boa sorte!",
  ui_story_6_1_171_dialog_content = "Suponho que a Senhora Sheol seja uma boa mulher de negócios...",
  ui_story_6_1_172_dialog_content = "Eu disse algo errado? Foi esse negócio de “guia a distância”?",
  ui_story_6_1_173_dialog_content = "Não se preocupe, Vice. É melhor ela ir agora do que nos abandonar depois.",
  ui_story_6_1_174_dialog_content = "Invejo como você sempre está calma como um monge, Carleen...",
  ui_story_6_1_175_dialog_content = "Não tem motivo para entrar em pânico. Qualquer um que venha aqui vai se arrepender de ter vindo.",
  ui_story_6_2_X29_dialog_content = "Oh? Hum...",
  ui_story_6_2_X30_dialog_content = "Oficial Charon? O que está fazendo aqui com esses barulhos estranhos?",
  ui_story_6_2_X31_dialog_content = "Sra. Philyshy, você ainda parece tão...",
  ui_story_6_2_X32_dialog_content = "Insone.",
  ui_story_6_2_X33_dialog_content = "Na realidade, estou esperando os oficiais saírem de uma reunião. Há detalhes de despesas que quero reportar para o reembolso da Subcidade 28...",
  ui_story_6_2_X34_dialog_content = "Eles já partiram, miau! Talvez na próxima.",
  ui_story_6_2_X35_dialog_content = "Como partiram tão rápido? Ainda tem muito subsídio a ser pago!",
  ui_story_6_2_X36_dialog_content = "Não há nada que possam fazer, miau. Todos receberam ordens urgentes para defender os subúrbios, miau.",
  ui_story_6_2_X37_dialog_content = "A Vice claramente os informou de que a ameaça está no  <color=#FFB400>Corredor Suspirante</color>...",
  ui_story_6_2_X38_dialog_content = "A Grande Marechal tomou uma decisão, mas não consigo entender por que, miau...",
  ui_story_6_2_X39_dialog_content = "Calma aí, isso é demais para absorver de uma vez.",
  ui_story_6_2_X40_dialog_content = "Pode me dar mais detalhes? Vice e PlayerName se meteram em encrenca de novo?",
  ui_story_6_2_X41_dialog_content = "Encrenca? Como vou dizer, miau... É provavelmente a <color=#FFB400>maior crise na história</color>, miau...",
  ui_story_6_2_X42_dialog_content = "Crise!?",
  ui_story_6_2_1_dialog_content = "Parece que já percorremos um longo caminho.",
  ui_story_6_2_2_dialog_content = "Até eu consigo sentir a forte presença de Eclipsitas aqui.",
  ui_story_6_2_3_dialog_content = "Senhora Sheol?",
  ui_story_6_2_4_dialog_content = "Sim? Estou aqui.",
  ui_story_6_2_6_dialog_content = "Estão perdidos, docinhos?",
  ui_story_6_2_7_dialog_content = "Eu não diria que nos perdemos, mas esse lugar é como um labirinto, e é muito escuro e deprimente.",
  ui_story_6_2_9_dialog_content = "Olha ali... Os rastros são bem estranhos. Não são só pegadas de Eclipsitas, mas também...",
  ui_story_6_2_10_dialog_content = "Isso não são pegadas de alguém que está usando coturno?",
  ui_story_6_2_11_dialog_content = "Coturno?",
  ui_story_6_2_12_dialog_content = "Estou detectando Aurorianos. Será que são reforços?",
  ui_story_6_2_13_dialog_content = "Definitivamente são botas padrão de Lumópolis. Foram deixadas por alguém dos Guardiões.",
  ui_story_6_2_14_dialog_content = "As pegadas ainda estão frescas, sem sinal de combate, nem de pânico.",
  ui_story_6_2_15_dialog_content = "Você entendeu tudo isso com uma simples pegada de botas?",
  ui_story_6_2_16_dialog_content = "<color=#FFB400>Gertzurde</color>.",
  ui_story_6_2_X16_dialog_content = "Gertzurde? Se me lembro bem...",
  ui_story_6_2_17_option_content = "Ouvi esse nome\nquando estávamos caçando Shelt.",
  ui_story_6_2_18_option_content = "O ladrão que roubou\no Módulo do Laboratório de Ideias?",
  ui_story_6_2_19_dialog_content = "Certo, mas Gertzurde não está desaparecido?",
  ui_story_6_2_20_dialog_content = "Ele fugiu. Temos evidências irrefutáveis de que ele se uniu ao Eclipse.",
  ui_story_6_2_21_dialog_content = "Ele e sua amante têm servido os Eclipsitas por muito tempo. Eles são a vergonha de Lumópolis.",
  ui_story_6_2_22_dialog_content = "Ele andou por aqui com Eclipsitas, usando coturno...",
  ui_story_6_2_23_dialog_content = "Só pode ser Gertzurde!",
  ui_story_6_2_24_dialog_content = "Por que ele fez isso?",
  ui_story_6_2_25_dialog_content = "Ninguém sabe.",
  ui_story_6_2_26_dialog_content = "Dizem que Gertzurde era diligente no trabalho e até era um herói de guerra, então ninguém suspeitava dele.",
  ui_story_6_2_27_dialog_content = "Será que Gertzurde se ressente do que aconteceu com Shelt e veio aqui para...",
  ui_story_6_2_28_dialog_content = "Deixe o vira-lata vir.",
  ui_story_6_2_29_dialog_content = "Se eu o vir, vou enterrar ele bem aqui do lado de Schummer!",
  ui_story_6_2_30_dialog_content = "Céus, isso é irritante. As passagens são infinitas e sinto como se estivessem me observando!",
  ui_story_6_2_31_dialog_content = "Isso é um saco! Canta uma música para mim, Gertzurde.",
  ui_story_6_2_32_dialog_content = "...",
  ui_story_6_2_33_dialog_content = "Que cara é essa, Gertzurde?",
  ui_story_6_2_34_dialog_content = "Aqueles que assassinaram Shelt estão aqui. Não deveria estar cantando de felicidade?",
  ui_story_6_2_35_dialog_content = "Estão atrás de nós, como você disse...",
  ui_story_6_2_36_dialog_content = "Aqueles que mataram Shelt estão se aproximando, não é?",
  ui_story_6_2_37_dialog_content = "Correto. Sabia que os inúteis não seriam capazes de pará-los... Uma coisa que não falta neles é tenacidade.",
  ui_story_6_2_39_dialog_content = "Shelt...",
  ui_story_6_2_40_dialog_content = "Teve um fim terrível, Gertzurde. Até eu sinto calafrios quando lembro como foi terrível.",
  ui_story_6_2_41_dialog_content = "Por quê! Eles...",
  ui_story_6_2_42_dialog_content = "Shelt me disse que era uma missão de glória! Por que ela não pediu a sua ajuda e DAQUELA pessoa?",
  ui_story_6_2_A1_dialog_content = "Eu a conheço. Ela definitivamente teria pedido ajuda... Isso significa que...",
  ui_story_6_2_43_dialog_content = "Por que está gritando?",
  ui_story_6_2_44_dialog_content = "Desculpe.",
  ui_story_6_2_45_dialog_content = "Me disseram que PlayerName foi fundamental para o fim da pobre Shelt.",
  ui_story_6_2_46_dialog_content = "Baixa Lumópolis ficou uma bagunça depois que você libertou Shelt e a Cidade Alta não estava a fim de fazer nada.",
  ui_story_6_2_47_dialog_content = "Mas PlayerName e aqueles dois cães cruéis ainda estavam no pé dela.",
  ui_story_6_2_48_dialog_content = "O quê? Eles não têm misericórdia?",
  ui_story_6_2_49_dialog_content = "Não é? Que tipo de lei mata um ladrão que falhou em roubar?",
  ui_story_6_2_50_dialog_content = "Eles forçaram Shelt e sua irmã a... é... se fundirem em um monstro repulsivo.",
  ui_story_6_2_51_dialog_content = "Shelt, ô, Shelt...",
  ui_story_6_2_52_dialog_content = "Se há alguma coisa específica que queira fazer, agora é sua chance.",
  ui_story_6_2_53_dialog_content = "O Controlador de Chamas que estou procurando está perto. Então, qual seu próximo plano?",
  ui_story_6_2_54_dialog_content = "PlayerName!",
  ui_story_6_2_55_dialog_content = "Ó? Parece que está pronto para a vingança.",
  ui_story_6_2_56_dialog_content = "Atchim!",
  ui_story_6_2_57_dialog_content = "Isso é frio demais para você, PlayerName?",
  ui_story_6_2_58_dialog_content = "Não, só arrepiei do nada.",
  ui_story_6_2_59_dialog_content = "Afinal, você é Celestita, PlayerName. Talvez o Fluxo Escuro daqui seja forte demais para você.",
  ui_story_6_2_60_dialog_content = "Mas, por favor, espere, ainda temos muitos inimigos para eliminar.",
  ui_story_6_2_61_dialog_content = "Eu vou. Vamos continuar.",
  ui_story_6_6_1_dialog_content = "Senhora Sheol, acho que chegamos a um lugar estranho!",
  ui_story_6_6_2_dialog_content = "Chomp, chomp... O que é?",
  ui_story_6_6_3_dialog_content = "Está comendo, Senhora Sheol?",
  ui_story_6_6_4_dialog_content = "Estava curtindo meu cafezinho da tarde. O que está acontecendo?",
  ui_story_6_6_5_dialog_content = "Gostaríamos de saber se essa passagem vai nos levar até o <color=#FFB400>Controlador de Chamas</color>.",
  ui_story_6_6_6_dialog_content = "O quê? Claro! Tive dificuldade para lembrar onde essa coisa estava.",
  ui_story_6_6_7_dialog_content = "Você precisa aprender a confiar nos outros, docinho. Ah, falando nisso, cuidado com as armadilhas!",
  ui_story_6_6_8_dialog_content = "Espera, estou detectando...",
  ui_story_6_6_9_dialog_content = "Eclipsitas?",
  ui_story_6_6_10_dialog_content = "Não, Aurorian...",
  ui_story_6_6_11_dialog_content = "Aurorian? Senhora Sheol, ninguém entrou, não é?",
  ui_story_6_6_12_dialog_content = "Nem uma formiguinha.",
  ui_story_6_6_13_dialog_content = "Deve ser Gertzurde. Estou com medo de ter uma emboscada esperando por nós.",
  ui_story_6_6_14_dialog_content = "Emboscada?",
  ui_story_6_6_15_dialog_content = "Consigo ver uma intersecção à frente, e uma armadilha.",
  ui_story_6_6_16_dialog_content = "Se considerar que o teto bastante dilapidado pode desmoronar a qualquer momento... É perfeito para uma emboscada!",
  ui_story_6_6_17_dialog_content = "Embora ele já tenha sido um cavaleiro, fugiu para o Eclipse. Ninguém sabe do que ele é capaz.",
  ui_story_6_6_18_dialog_content = "Deixa eu liderar. Vou dar o fim que Gertzurde merece.",
  ui_story_6_7_1_dialog_content = "Ufa, essa foi por pouco! Teríamos caído em um buraco se não fosse pela Carleen!",
  ui_story_6_7_2_dialog_content = "Ei, eu não alertei vocês o suficiente?",
  ui_story_6_7_3_dialog_content = "Por exemplo, o tambor de óleo que quase esmagou nosso docinho PlayerName!",
  ui_story_6_7_4_dialog_content = "Quase morri de medo...",
  ui_story_6_7_5_dialog_content = "Essa é a estratégia de Gertzurde. Ele se tornou tão sem vergonha e malvado quanto os Eclipsitas...",
  ui_story_6_7_6_dialog_content = "Falando no diabo...",
  ui_story_6_7_7_dialog_content = "Você matou Shelt.",
  ui_story_6_7_8_dialog_content = "Você... matou... Shelt!",
  ui_story_6_7_9_dialog_content = "Como esperava, você está aqui por vingança.",
  ui_story_6_7_10_dialog_content = "Vingança? Sim. Que pena que você escapou das minhas armadilhas, porque...",
  ui_story_6_7_11_dialog_content = "Só matar você não vai diminuir meu ódio.",
  ui_story_6_7_F1_dialog_content = "Seu traidor, quer nos matar?",
  ui_story_6_7_12_dialog_content = "Gertzurde, como cavaleiro de Lumópolis, você perdeu a sua honra e fugiu para os Eclipsitas. Nunca te perdoarei!",
  ui_story_6_7_13_dialog_content = "Nunca me perdoará? Eu preciso do seu perdão? Sim, eu era cavaleiro de Lumópolis, mas agora estou na elite Eclipsita!",
  ui_story_6_7_14_dialog_content = "Foi tudo por ela! Mas vocês, vocês...",
  ui_story_6_7_15_dialog_content = "Vocês são mais cruéis que os Eclipsitas... Vocês torturaram e mataram a Shelt!",
  ui_story_6_7_16_dialog_content = "Shelt e sua irmã, elas escolheram a morte, Gertzurde!",
  ui_story_6_7_17_dialog_content = "Gertzurde, elas buscaram a morte para se libertarem.",
  ui_story_6_7_18_dialog_content = "Impossível!",
  ui_story_6_7_19_dialog_content = "Shelt... Ela ansiava por liberdade. Por que ela tiraria a própria vida se você não a obrigasse?",
  ui_story_6_7_20_dialog_content = "Schummer enviou você para nos impedir, não é?",
  ui_story_6_7_21_dialog_content = "Não, eu vim por vingança contra vocês, contra Lumópolis!",
  ui_story_6_7_22_dialog_content = "Sobre Schummer, o que ela quer não tem nada a ver comigo.",
  ui_story_6_7_23_dialog_content = "Um traidor querendo vingança para uma espiã?",
  ui_story_6_7_27_dialog_content = "...",
  ui_story_6_7_28_dialog_content = "Cuidado, Carleen, o ódio dele parece estar aumentando e ficando cada vez mais forte...",
  ui_story_6_7_29_dialog_content = "Ódio? Isso é natural para traidores.",
  ui_story_6_7_30_dialog_content = "Porque eles foram levados ao desespero, porque apenas conhecem o ódio.",
  ui_story_6_7_31_dialog_content = "Eles odeiam aqueles que os julgam, eles odeiam seu passado intolerável e odeiam o futuro que nunca terão.",
  ui_story_6_7_32_dialog_content = "Não há nada a se negociar com um lixo igual a ele.",
  ui_story_6_7_33_dialog_content = "Você é Capitã dos Guardiões e filha do Senhor da Cidade de Lumópolis. Como poderia entender?",
  ui_story_6_7_34_dialog_content = "Mesmo se eu não fosse um traidor, você ainda não entenderia meu ódio!",
  ui_story_6_7_35_dialog_content = "Eu odeio vocês por terem matado a Shelt!",
  ui_story_6_7_36_dialog_content = "Sim, ela se tornou um Eclipsita, e como inimiga de vocês, Aurorians, morrer numa batalha contra vocês era seu destino.",
  ui_story_6_7_37_dialog_content = "Mas foram vocês que a deixaram assim. Vocês são culpados!",
  ui_story_6_7_38_dialog_content = "Ele está mudando sua forma!",
  ui_story_6_7_39_dialog_content = "Vingança... Minha vingança é igual à sua, PlayerName.",
  ui_story_6_7_40_dialog_content = "Somos iguais, em um caminho de vingança sem volta...",
  ui_story_6_7_41_dialog_content = "Iguais? O que quer dizer?",
  ui_story_6_7_42_dialog_content = "Você realmente se tornou um Eclipsita! Recebeu esses poderes da sua mestra?",
  ui_story_6_7_43_dialog_content = "Vingança! Vamos morrer pelas nossas mãos, PlayerName!",
  ui_story_6_7_44_dialog_content = "Vamos viajar ao mundo além da morte e buscar o perdão de Shelt juntos!",
  ui_story_6_7_45_dialog_content = "Volta, PlayerName! Não temos chance sem você!",
  ui_story_6_7_X45_dialog_content = "Eu perdi, Shelt...",
  ui_story_6_7_48_dialog_content = "Pronto para seu veredicto, traidor?",
  ui_story_6_7_49_dialog_content = "...",
  ui_story_6_7_50_dialog_content = "Nada a dizer? Finalmente está sentindo remorso agora que vai morrer?",
  ui_story_6_7_51_dialog_content = "Não, não tenho arrependimentos. Eu conheço o meu fim.",
  ui_story_6_7_52_dialog_content = "Só quero saber o que aconteceu nos últimos momentos de Shelt.",
  ui_story_6_7_53_dialog_content = "Você não precisa saber!",
  ui_story_6_7_F2_dialog_content = "Espera um momento! Podemos explicar...",
  ui_story_6_7_54_dialog_content = "Nós alcançamos a Shelt, mas tudo que queríamos descobrir é o que pretendiam fazer.",
  ui_story_6_7_55_dialog_content = "Exato. Não pretendíamos matá-las.",
  ui_story_6_7_56_dialog_content = "Mas ao querer fugir, buscaram ajuda de um líder Eclipsita.",
  ui_story_6_7_57_dialog_content = "Schummer?",
  ui_story_6_7_58_dialog_content = "Não, aquela aura era diferente da de Schummer. Era de outra pessoa ainda mais poderosa que Schummer.",
  ui_story_6_7_59_dialog_content = "Então, uma transformação assustadora começou... Seus corpos derreteram e se fundiram como cera...",
  ui_story_6_7_60_dialog_content = "Elas não escolheram virar um só. Parecia...",
  ui_story_6_7_61_dialog_content = "Parecia que foram forçadas a se fundir por alguma força esmagadora...",
  ui_story_6_7_62_dialog_content = "E o que houve depois!?",
  ui_story_6_7_63_dialog_content = "Tivemos que matar Shelt.",
  ui_story_6_7_64_dialog_content = "Ela morreu sofrendo?",
  ui_story_6_7_65_dialog_content = "Bom...",
  ui_story_6_7_66_option_content = "Ela teve uma morte muito agonizante.",
  ui_story_6_7_67_dialog_content = "<anim type=Shake><size=45>Agonizante!</size></anim>",
  ui_story_6_7_69_dialog_content = "Antes de decidirmos lutar, alguém impôs um poder desconhecido sobre elas...",
  ui_story_6_7_70_dialog_content = "O poder as forçou a fundir, e a duas se tornaram um Eclipsita.\nAquilo foi a fonte de sua dor.",
  ui_story_6_7_71_option_content = "Nós fomos breves.",
  ui_story_6_7_72_dialog_content = "Então vocês a libertaram?",
  ui_story_6_7_73_dialog_content = "Sim. Porque não aguentamos ver o sofrimento dela.",
  ui_story_6_7_74_dialog_content = "Antes de decidirmos lutar, alguém impôs um poder desconhecido sobre elas...",
  ui_story_6_7_75_dialog_content = "O poder as forçou a fundir, e a duas se tornaram um Eclipsita.\nAquilo foi a fonte de sua dor.",
  ui_story_6_7_76_dialog_content = "Talvez a dor delas também tenha nascido dos próprios arrependimentos.",
  ui_story_6_7_78_dialog_content = "Principalmente Shelt. Eu conseguia sentir que ela não queria lutar.",
  ui_story_6_7_79_dialog_content = "Ela só queria escapar, fugir de Lumópolis e ir para bem, bem longe...",
  ui_story_6_7_80_dialog_content = "Parece que no fim ela mencionou algo sobre uma flor.",
  ui_story_6_7_81_dialog_content = "Flor?",
  ui_story_6_7_82_option_content = "Dente-de-leão.",
  ui_story_6_7_83_dialog_content = "<size=45>...!</size>",
  ui_story_6_7_84_dialog_content = "Para nós não significou nada, mas para você... você deve saber.",
  ui_story_6_7_85_dialog_content = "Sinto muito, Shelt, sinto muito...",
  ui_story_6_7_86_dialog_content = "Você me disse, e eu devia ter percebido. Nós tivemos a nossa chance...",
  ui_story_6_7_87_dialog_content = "Gertzurde, Gertzurde! Alguma coisa divertida por aí?",
  ui_story_6_7_88_dialog_content = "Quer ir para algum lugar?",
  ui_story_6_7_89_dialog_content = "Sim, mas não só por diversão. Você conhece o Corredor Suspirante?",
  ui_story_6_7_90_dialog_content = "Parece ser um lugar bem recluso, onde ninguém pode nos encontrar, onde podemos viver para sempre!",
  ui_story_6_7_91_dialog_content = "Ou pode ser o Deserto Rediesel. Mas é quente demais.",
  ui_story_6_7_92_dialog_content = "Está planejando deixar Lumópolis? É por que ofendeu a nobreza?",
  ui_story_6_7_93_dialog_content = "Não, é o Eclipse.",
  ui_story_6_7_94_dialog_content = "Quero me tornar um dente-de-leão.",
  ui_story_6_7_95_dialog_content = "Hum? Por que isso?",
  ui_story_6_7_96_dialog_content = "Porque você nunca consegue controlar dentes-de-leão. Eles se espalham em mil miniversões deles mesmos e desaparecem ao vento.",
  ui_story_6_7_97_dialog_content = "Eles podem voar para qualquer lugar do mundo.",
  ui_story_6_7_98_dialog_content = "As “mini versões deles mesmos” na verdade são as sementes. Além disso, e se caírem na água?",
  ui_story_6_7_99_dialog_content = "Tsc... Tanto faz, não vou mais falar disso!",
  ui_story_6_7_100_dialog_content = "Liberdade... Sim, Shelt falava muito sobre querer deixar Lumópolis por causa do Eclipse.",
  ui_story_6_7_101_dialog_content = "Ela dizia que queria partir comigo, livre como um dente-de-leão.",
  ui_story_6_7_102_dialog_content = "Você é um tolo, Gertzurde. O Eclipse é o fim de tudo. Não, é a Verdade...",
  ui_story_6_7_103_dialog_content = "PlayerName realmente é a pessoa que assassinou Shelt?",
  ui_story_6_7_104_dialog_content = "Já te disse o que aconteceu, ainda assim insiste em me fazer todas essas perguntas. Talvez eu tenha esperado demais de você.",
  ui_story_6_7_105_dialog_content = "Deixe sua fraqueza de lado e pare de duvidar de nós, Gertzurde.",
  ui_story_6_7_106_dialog_content = "Apenas lembre-se, elas podiam ter sobrevivido, mas PlayerName reescreveu seus destinos.",
  ui_story_6_7_107_dialog_content = "E reescreveu o seu destino...",
  ui_story_6_7_108_dialog_content = "Não, não! Não é verdade, não é!",
  ui_story_6_7_109_dialog_content = "Gertzurde!",
  ui_story_6_7_110_dialog_content = "Eu... Eu... Shelt... Shelt queria partir... Por que ela escolheria se fundir? Por quê!?",
  ui_story_6_7_111_dialog_content = "Somos incapazes de controlar o Fluxo Escuro. Só o Fluxo Escuro poderia fazer as irmãs se fundirem em um Eclipsita.",
  ui_story_6_7_112_dialog_content = "Mesmo se não foi a Schummer que infundiu Fluxo Escuro nelas, os Eclipsitas que o fizeram estavam sob comando dela.",
  ui_story_6_7_113_dialog_content = "Deve ser, deve ser, deve ser aquela madita...!",
  ui_story_6_7_114_dialog_content = "Nos diga o que você sabe, Gertzurde.",
  ui_story_6_7_116_dialog_content = "...",
  ui_story_6_7_119_dialog_content = "<color=#FFB400>Schummer</color>, eu sei onde ela está.",
  ui_story_6_8_1_dialog_content = "Carleen, ele realmente nos levará até Schummer?",
  ui_story_6_8_2_dialog_content = "É estranho que ainda não demos de cara com um Eclipsita no caminho. Isso é uma armadilha?",
  ui_story_6_8_F1_dialog_content = "E se for uma armadilha?",
  ui_story_6_8_3_dialog_content = "Se ele me trair de novo, simplesmente dou outra surra nele, mas dessa vez, sem misericórdia.",
  ui_story_6_8_F2_dialog_content = "...",
  ui_story_6_8_4_dialog_content = "Desculpe, Gertzurde. Ainda duvidamos de você, mas se tem algo a dizer por si mesmo, por favor, nos diga.",
  ui_story_6_8_5_dialog_content = "O que um traidor pode dizer por si mesmo?",
  ui_story_6_8_6_dialog_content = "Traidor, hã... Eu já fui um campeão de Lumópolis.",
  ui_story_6_8_7_dialog_content = "Fui nomeado cavaleiro aos dezoito anos, pelo próprio Senhor da Cidade.",
  ui_story_6_8_8_dialog_content = "Você sabe sobre a <color=#FFB400>Crise Darkover</color>?",
  ui_story_6_8_9_dialog_content = "É a guerra que começou há 17 anos e durou muito tempo...",
  ui_story_6_8_10_dialog_content = "Dezessete anos atrás, os Eclipsitas assaltaram Eraveil, lar dos Celestitas. Esse ataque veio sem nenhum presságio, surpreendendo até mesmo Lumópolis.",
  ui_story_6_8_11_dialog_content = "Logo em seguida, recebemos ordens para intensificar nosso treinamento, como resposta a um possível grande ataque Eclipsita.",
  ui_story_6_8_12_dialog_content = "Quando recebi as ordens, eu era mais novo que você é agora, e tinha acabado de me tornar escudeiro.",
  ui_story_6_8_13_dialog_content = "Eu treinei duro e passei os próximos quatro anos como reserva nos Guardiões de Lumópolis.",
  ui_story_6_8_14_dialog_content = "Então sua chance chegou.",
  ui_story_6_8_15_dialog_content = "Sim. Foi numa bela manhã. Lumópolis enviou tropas para lutar com os Eclipsitas que atacavam Umbraton, pois a defesa da cidade era inadequada.",
  ui_story_6_8_16_dialog_content = "Alguns Eclipsitas conseguiram entrar em Baixa Lumópolis. Eu assumi o desafio e salvei uma nobre garota em apuros.",
  ui_story_6_8_19_dialog_content = "Depois, fui designado para lutar como membro dos Guardiões, devido à minha bravura...",
  ui_story_6_8_20_dialog_content = "O Senhor da Cidade me nomeou como cavaleiro logo após meu retorno.",
  ui_story_6_8_22_dialog_content = "Parece um começo incrível.",
  ui_story_6_8_23_dialog_content = "Sim, complete com um final de conto de fadas no qual o cavaleiro casa com a princesa.",
  ui_story_6_8_27_dialog_content = "Um mês depois, a nobre garota e eu estávamos casados.",
  ui_story_6_8_28_dialog_content = "Era a Shelt, certo?",
  ui_story_6_8_29_dialog_content = "Não.",
  ui_story_6_8_30_dialog_content = "Quer dizer que...",
  ui_story_6_8_31_dialog_content = "Ela era a segunda filha de uma grandiosa família nobre.",
  ui_story_6_8_32_dialog_content = "Era impossível acabar com a nossa diferença de status, apesar dos meus esforços.",
  ui_story_6_8_33_dialog_content = "A família da minha esposa era tanto sua força, quanto sua fraqueza.",
  ui_story_6_8_34_dialog_content = "O nosso relacionamento esfriou de um doce romance, então veio o desapego, comparações, decepções, reclamações, brigas e por fim, apatia.",
  ui_story_6_8_35_dialog_content = "Depois de alguns anos, eu não era mais que um peso para ela.",
  ui_story_6_8_36_dialog_content = "Ela queria que eu sumisse. E então, conheci a Shelt.",
  ui_story_6_8_45_dialog_content = "Ela me inspirou quando eu estava estagnado e acendeu a paixão pela minha juventude.",
  ui_story_6_8_46_dialog_content = "O olhar dela me trouxe de volta aos meus dias de glória.",
  ui_story_6_8_47_dialog_content = "Família e status não eram nada. Eu só queria ganhar mérito em batalhas e conquistar o coração da minha dama...",
  ui_story_6_8_49_dialog_content = "Chega! Ninguém sente pena de você, Gertzurde.",
  ui_story_6_8_50_dialog_content = "Olha o que você fez!",
  ui_story_6_8_51_dialog_content = "Trair a sua esposa, conspirar com Eclipsitas, atacar os guardas e roubar o Módulo de Tanque Pensante!",
  ui_story_6_8_53_dialog_content = "Você pode ter sido um campeão de Lumópolis, mas agora não é nada além de um pecador traiçoeiro!",
  ui_story_6_8_54_dialog_content = "Sim, eu traí Lumópolis. Sem desculpas.",
  ui_story_6_8_F3_dialog_content = "Mas não acho que fiz algo errado. Tudo que fiz foi em nome do amor verdadeiro...",
  ui_story_6_8_55_dialog_content = "Eu não entendo. É apenas ridículo!",
  ui_story_6_8_63_dialog_content = "Então, a história acabou?",
  ui_story_6_8_64_dialog_content = "Desculpe, Senhora Sheol. Esqueci que estava aqui.",
  ui_story_6_8_65_dialog_content = "Eu só quero destacar que Gertzurde não os levou para o caminho errado.",
  ui_story_6_8_66_dialog_content = "Ele levou vocês até uma rota idêntica à que conheço. Na verdade, ele até contornou lugares que podem ser armadilhas.",
  ui_story_6_8_67_dialog_content = "...",
  ui_story_6_8_68_dialog_content = "Não preciso da sua compreensão. Já disse, levarei vocês até Schummer. E então terei minhas próprias questões pra resolver.",
  ui_story_6_9_1_dialog_content = "Heh, alguém em cima do muro sempre ficará em cima do muro.",
  ui_story_6_9_2_dialog_content = "Está falando de Gertzurde?",
  ui_story_6_9_3_dialog_content = "Parece que você não tem o mesmo poder de persuasão de PlayerName.",
  ui_story_6_9_4_dialog_content = "E daí? Eu sabia que Gertzurde ia se virar contra nós. Mas as coisas estão um pouco diferentes do que imaginei.",
  ui_story_6_9_5_dialog_content = "Por causa de PlayerName?",
  ui_story_6_9_6_dialog_content = "Sim. Não esperava que poupassem Gertzurde. Deve ter sido por causa do certinho do PlayerName.",
  ui_story_6_9_7_dialog_content = "Que esperto, eu diria. Pare de achar, Schummer, pensar não combina com você.",
  ui_story_6_9_8_dialog_content = "Ainda vou quebrar o seu pescoço...",
  ui_story_6_9_9_dialog_content = "Enfim, estou mais perto do que eles. Já posso sentir o cheiro do <color=#FFB400>Controlador de Chamas</color>.",
  ui_story_6_9_10_dialog_content = "Quando chegar lá, tudo que preciso fazer é esperar por PlayerName, e então...",
  ui_story_6_9_11_dialog_content = "Matar todos.",
  ui_story_6_9_12_dialog_content = "Isso, matar todos. Gosto do som disso.",
  ui_story_6_9_13_dialog_content = "Sim, mas é só por causa do seu vocabulário limitado. Ainda assim, aja com cautela. Eles têm Lumópolis e Illumina como reforço.",
  ui_story_6_9_14_dialog_content = "Nenhuma de suas tropas virão. Os Aurorianos estão ocupados duvidando de si mesmos.",
  ui_story_6_9_15_dialog_content = "Nenhuma de suas tropas virão. Os Aurorians estão ocupados duvidando de si mesmos.",
  ui_story_6_9_16_dialog_content = "Não, valeu. Sabe que não gosto de sujar as minhas mãos.",
  ui_story_6_9_17_dialog_content = "Mas posso te enviar ajuda... Não, faça disso um <color=#FFB400>presente</color>, um presente para eles.",
  ui_story_6_9_18_dialog_content = "Ajuda? Presente? É quem estou pensando?",
  ui_story_6_9_19_dialog_content = "Sim, o <color=#FFB400>velho amigo</color> deles que eu aprimorei.",
  ui_story_6_9_20_dialog_content = "Estou vendo que também gosta de se entreter, se ocupado com todas essas “criações”.",
  ui_story_6_9_21_dialog_content = "Isso tudo é propício para a realização do meu plano, enquanto tudo que você faz é causar problemas.",
  ui_story_6_9_22_dialog_content = "E você não?",
  ui_story_6_9_23_dialog_content = "Já chega. Olhe esse presente...",
  ui_story_6_9_24_dialog_content = "Minha nossa, é lindo. Como PlayerName vai se sentir ao ver essa velho amigo?",
  ui_story_6_9_25_dialog_content = "Mal consigo esperar para ver...",
  ui_story_6_9_A1_dialog_content = "Quanto ainda falta, Gertzurde?",
  ui_story_6_9_A2_dialog_content = "Não muito. Confie em mim. Quero ver aquela hipócrita mais que vocês.",
  ui_story_6_9_A3_dialog_content = "...",
  ui_story_6_9_A4_dialog_content = "Schummer deixou Eclipsitas para trás para emboscar vocês. São lutadores fortes, não é? Façam o que fazem de melhor.",
  ui_story_6_13_1_dialog_content = "O fim do Corredor Suspirante está à frente?",
  ui_story_6_13_2_dialog_content = "Sim. Schummer com certeza está por perto.",
  ui_story_6_13_3_dialog_content = "Consigo detectar a aura dela daqui.",
  ui_story_6_13_5_dialog_content = "Procurem por uma garrafa de vidro enorme com um número embaixo.",
  ui_story_6_13_6_dialog_content = "Hum, eu já esqueci qual exatamente era. Deve ser...",
  ui_story_6_13_7_dialog_content = "<color=#FFB400>RX6007</color>.",
  ui_story_6_13_8_dialog_content = "Sim, isso mesmo! É o número de armazenamento dela! Como sabia?",
  ui_story_6_13_10_dialog_content = "Schummer mencionou brevemente, e eu lembro de tudo que ouço.",
  ui_story_6_13_11_dialog_content = "Qualquer informação ou memória passada, é uma maldição.",
  ui_story_6_13_12_dialog_content = "Quando chegarem nesse item numerado, a coisa que estão procurando não estará muito longe.",
  ui_story_6_13_14_dialog_content = "Tenham cuidado. Se Schummer sabe o número, significa que...",
  ui_story_6_13_16_dialog_content = "Ela sabe onde encontrá-lo e provavelmente já está esperando por nós.",
  ui_story_6_14_1_dialog_content = "Ah, enfim nos reencontramos.",
  ui_story_6_14_2_dialog_content = "Schu...",
  ui_story_6_14_3_dialog_content = "Schummer!",
  ui_story_6_14_4_dialog_content = "Parece estar com raiva. É porque PlayerName te deu uma coça?",
  ui_story_6_14_5_dialog_content = "Você é um prisioneiro? Eu deveria te resgatar para você ter uma revanche?",
  ui_story_6_14_6_dialog_content = "Você e ela, vocês mentiram para mim. Não me contaram a verdade sobre a morte de Shelt!",
  ui_story_6_14_7_dialog_content = "Nós mentimos? Não, Gertzurde, você escolheu acreditar que Shelt foi assassinada por Lumópolis.",
  ui_story_6_14_8_dialog_content = "Para você poder ter uma revanche apropriada!",
  ui_story_6_14_9_dialog_content = "Vocês mentiram para todos nós. Mentiram para a Shelt, usaram ela, e agora ela se foi!",
  ui_story_6_14_10_dialog_content = "Você não joga coisas usadas fora?",
  ui_story_6_14_11_dialog_content = "É assim que via a Shelt?",
  ui_story_6_14_12_dialog_content = "Está suando bastante. A viagem deve ter sido difícil. Toma um lencinho.",
  ui_story_6_14_13_dialog_content = "Obrigada...",
  ui_story_6_14_14_dialog_content = "Está em choque? Isso no seu rosto não é suor... São lágrimas?",
  ui_story_6_14_15_dialog_content = "Por que está chorando, Gertzurde? Você não é um traidor? Que motivos um traidor tem para chorar?",
  ui_story_6_14_16_dialog_content = "Schummer... Você... O que você fez com a Shelt...",
  ui_story_6_14_17_dialog_content = "O que eu fiz? Gertzurde, o que você pode fazer agora que não tem os poderes que te demos?",
  ui_story_6_14_20_dialog_content = "Foi você que fundiu elas, Schummer?",
  ui_story_6_14_22_dialog_content = "Não. Aliás, tecnicamente, dá para dizer que fui eu...",
  ui_story_6_14_23_dialog_content = "Você...!",
  ui_story_6_14_24_dialog_content = "Eu sabia que ia perguntar por que fizemos isso.",
  ui_story_6_14_25_dialog_content = "E eu te direi que é simplesmente porque nós podemos.",
  ui_story_6_14_26_dialog_content = "Por que está com raiva disso? Qual o problema de limpar e jogar lixo usado fora?",
  ui_story_6_14_27_dialog_content = "Perguntas, perguntas, perguntas. Chega.",
  ui_story_6_14_28_dialog_content = "PlayerName e essas duas mulheres... Essa gentalha é culpada de suas queixas.",
  ui_story_6_14_29_dialog_content = "Schummer, você...",
  ui_story_6_14_30_dialog_content = "Posso te ajudar a se livrar deles...",
  ui_story_6_14_31_dialog_content = "Cuidado!",
  ui_story_6_14_32_dialog_content = "Carleen!",
  ui_story_6_14_33_dialog_content = "...!",
  ui_story_6_14_34_dialog_content = "Gert... zurde?",
  ui_story_6_14_35_dialog_content = "Você...",
  ui_story_6_14_36_dialog_content = "Eu... Eu...",
  ui_story_6_14_37_dialog_content = "Está louco, Gertzurde? Você se curva para qualquer um que aparece na sua frente?",
  ui_story_6_14_38_dialog_content = "Por que...",
  ui_story_6_14_39_dialog_content = "Não, não foi por você... Foi pela Shelt...",
  ui_story_6_14_40_dialog_content = "...",
  ui_story_6_14_A1_dialog_content = "Matem... Schummer...",
  ui_story_6_14_A2_dialog_content = "Eu não tenho força suficiente para isso, mas vocês... vocês têm.",
  ui_story_6_14_A3_dialog_content = "Matem ela com suas espadas!",
  ui_story_6_14_A5_dialog_content = "Schummer...",
  ui_story_6_14_A7_dialog_content = "Shelt e eu <anim type=Shake><size=50>te esperaremos no inferno!</size></anim>",
  ui_story_6_14_44_dialog_content = "Gertzurde... Seu...",
  ui_story_6_14_45_dialog_content = "Carleen, ele está... Esse foi seu último desejo.",
  ui_story_6_14_46_dialog_content = "Isso está ficando muito, muito, muito, muito chato! Essa vai para Gertzurde e o resto de vocês...",
  ui_story_6_14_47_dialog_content = "Schummer! <color=#FFB400>Estão vindo</color>. Recuem.",
  ui_story_6_14_48_dialog_content = "Cala a boca! O que está fazendo? Saia da minha frente.",
  ui_story_6_14_49_dialog_content = "Quero que saia. Agora.",
  ui_story_6_14_50_dialog_content = "Por quê?",
  ui_story_6_14_51_dialog_content = "O que houve?",
  ui_story_6_14_52_dialog_content = "Parece que estão chegando <color=#FFB400>tropas</color> carregando uma faixa de Illumina, PlayerName! Em grande número!",
  ui_story_6_14_53_dialog_content = "Apenas espere. Eles cercarão esse lugar quando chegarem!",
  ui_story_6_14_54_dialog_content = "Uma grande multidão de inimigos está se aproximando. Pegue o módulo e saia daqui imediatamente.",
  ui_story_6_14_56_dialog_content = "Posso matar todos em um segundo! Depois pego PlayerName e...",
  ui_story_6_14_57_dialog_content = "Não consegue fazer isso.",
  ui_story_6_14_58_dialog_content = "Sim, eu consigo! Me dê três minutos. Não, um minuto...",
  ui_story_6_14_59_dialog_content = "E eu disse que você não consegue! As tropas de Illumina estão chegando! Não quero correr o risco.",
  ui_story_6_14_60_dialog_content = "Oh, oh, oh! Vamos fazer mais fumaça!",
  ui_story_6_14_61_dialog_content = "Como vanguarda da Legião de Illumina, eu sou...",
  ui_story_6_14_62_dialog_content = "O Caçador de Eclipsitas, o Exterminador da Noite, o Expert em Explosivos da Subcidade, o Barqueiro de Acheron, Charon!",
  ui_story_6_14_63_dialog_content = "Estou liderando incontáveis soldados para cercar o Corredor Suspirante! Nenhum Eclipsita escapará!",
  ui_story_6_14_X64_dialog_content = "Não me faça te obrigar, Schummer.",
  ui_story_6_14_65_dialog_content = "Tá bom, que seja! De todo jeito, estamos com o módulo...",
  ui_story_6_14_66_dialog_content = "Espere, Schummer!",
  ui_story_6_14_67_dialog_content = "Onde está o <color=#FFB400>Controlador de Chamas</color>?",
  ui_story_6_14_68_dialog_content = "<color=#FFB400>Aqui</color>.",
  ui_story_6_14_69_dialog_content = "Você não pode correr, ainda mais quando o exército está aqui.",
  ui_story_6_14_70_dialog_content = "Você realmente devia se preocupar com Lumópolis em vez disso.",
  ui_story_6_14_71_dialog_content = "Lumópolis?",
  ui_story_6_14_72_dialog_content = "Sim, a suposta Cidade Inconquistável? Que apelido absurdo.",
  ui_story_6_14_A8_dialog_content = "Espere até eu recarregar a Colossus Preta! Vou te mostrar exatamente como é o poder supremo!",
  ui_story_6_14_73_dialog_content = "O chão! Cuidado, pessoal!",
  ui_story_6_14_74_dialog_content = "Não esperava por essa?",
  ui_story_6_14_75_dialog_content = "É... Nozard! Mas não está morto?",
  ui_story_6_14_76_dialog_content = "<anim type=Shake><size=45>*Suspirando*</size></anim>",
  ui_story_6_14_77_dialog_content = "Reciclar é uma virtude. Sempre reutilize tudo.",
  ui_story_6_14_78_dialog_content = "Pare de perder tempo. A Colossus Preta está pousando.",
  ui_story_6_14_79_dialog_content = "É uma pena que eu não possa ficar para o show.",
  ui_story_6_14_80_dialog_content = "Bem, deve haver mais diversão no futuro. Adiós, pessoal!",
  ui_story_6_14_81_dialog_content = "O Eclipsita é Nozard? Posso sentir uma grande hostilidade de dentro dele!",
  ui_story_6_14_83_dialog_content = "É diferente da última vez que encaramos Nozard. Tomem cuidado, gente!",
  ui_story_6_14_84_dialog_content = "Devíamos ter dado um fim em Nozard da última vez, mas agora isso está de volta e está mais forte.",
  ui_story_6_14_85_dialog_content = "Você já encontrou Eclipsitas assim indo em direção a Lumópolis?",
  ui_story_6_14_86_dialog_content = "Sim... Mas tínhamos certeza de que estava morto.",
  ui_story_6_14_87_dialog_content = "Então quer dizer que o Eclipse o restaurou e o transformou em um novo tipo de arma? Que bizarro...",
  ui_story_6_14_90_dialog_content = "Eles não enxergam outros Eclipsitas como aliados. Apenas como armas, como Shelt e Shire foram.",
  ui_story_6_14_92_dialog_content = [[
O <color=#FFB400>Controlador de Chamas</color> foi levado.
O que faremos agora?]],
  ui_story_6_14_93_dialog_content = "Ainda precisamos cuidar do Gertzurde...",
  ui_story_6_14_94_dialog_content = "Carleen?",
  ui_story_6_14_97_dialog_content = "Vou cremar Gertzurde.",
  ui_story_6_14_98_dialog_content = "Não vai enterrar ele? Mas isso vai contra a tradição de Lumópolis...",
  ui_story_6_14_99_dialog_content = "Primeiramente, ele é um traidor, e sendo assim, seu corpo precisa ser descartado. Segundo, o Eclipse pode tentar reviver seu corpo.",
  ui_story_6_14_100_dialog_content = "Isso é verdade. Não pensariam duas vezes antes de transformar seu corpo em uma arma. É doentio.",
  ui_story_6_14_102_dialog_content = "Vice, PlayerName, juntem combustível.",
  ui_story_6_14_103_dialog_content = "Eu, Carleen de Schwartz, Capitã dos Guardiões de Lumópolis, venho passar a decisão final de Gertzurde em nome de Lumópolis:",
  ui_story_6_14_104_dialog_content = "Ele foi um cavaleiro de Lumópolis que provou o seu valor durante a batalha.",
  ui_story_6_14_105_dialog_content = "Mas afligido por seus demônios e persuadido por Eclipsitas, ele traiu Lumópolis.",
  ui_story_6_14_106_dialog_content = "Manipulado por nossos inimigos, ele foi cúmplice de Eclipsitas para colocar o povo de Lumópolis em perigo.",
  ui_story_6_14_107_dialog_content = "Mas no fim, ele se perdeu e pagou com sua vida. Os crimes que cometeu não podem ser perdoados, mas podem ser liberados da punição de ter seu cadáver abandonado.",
  ui_story_6_14_108_dialog_content = "Vamos queimar seu corpo para preservar sua dignidade... Avante, Noite Branca.",
  ui_story_6_14_109_dialog_content = "Descanse em paz, Gertzurde, campeão de Lumópolis, cavaleiro da Traição, lacaio do Eclipse.",
  ui_story_6_14_111_dialog_content = "Ainda assim, ele deve descansar em paz. PlayerName, pode detectar onde Schummer está?",
  ui_story_6_14_112_dialog_content = "Ela deixou o Corredor Suspirante.",
  ui_story_6_14_114_dialog_content = "Sobre sua direção, não tenho muita certeza. Se eu tivesse que adivinhar, diria que está no ar.",
  ui_story_6_14_115_dialog_content = "No ar? Está dizendo que quando ela mencionou Lumópolis, ela quis dizer...",
  ui_story_6_14_116_dialog_content = "Desculpe interromper, mas ainda estão vivos?",
  ui_story_6_14_117_dialog_content = "Claro que não!",
  ui_story_6_14_118_dialog_content = "Alguém que irradiava uma atmosfera muito poderosa de repente apareceu na minha frente. Pensei que...",
  ui_story_6_14_119_dialog_content = "Tirando a parte que não pegamos o Controlador de Chamas, estamos bem.",
  ui_story_6_14_120_dialog_content = "Que bom, que bom.",
  ui_story_6_14_121_dialog_content = "E a força de Illumina? Não disse que reforços estavam aqui?",
  ui_story_6_14_122_dialog_content = "Bom, verá com seus olhos em breve.",
  ui_story_6_14_123_dialog_content = "Ei, Vice, PlayerName.",
  ui_story_6_14_124_dialog_content = "Oficial Charon?",
  ui_story_6_14_125_dialog_content = "Posso beber algo primeiro? Estou com muita sede depois de correr tanto.",
  ui_story_6_14_126_dialog_content = "O que está acontecendo? Onde está o reforço?",
  ui_story_6_14_127_dialog_content = "Algumas horas atrás Philyshy me informou que vocês poderiam estar com grandes problemas.",
  ui_story_6_14_128_dialog_content = "Mas Gannon recusou enviar tropas, então decidi vir sozinho.",
  ui_story_6_14_129_dialog_content = "Não me diga que você é a “força” da qual a Senhora Sheol estava falando...",
  ui_story_6_14_130_dialog_content = "É exatamente o que está pensando.",
  ui_story_6_14_131_dialog_content = "Eu notei uma Colossus preta esquisita quando cheguei à área, e então encontrei a Senhora Sheol.",
  ui_story_6_14_132_dialog_content = "Ela estava preocupada que vocês não conseguissem derrotar Schummer, então tive um plano.",
  ui_story_6_14_133_dialog_content = "Então, hum... Digamos que não foi fácil fazer parecer que tinham milhares de soldados aqui.",
  ui_story_6_14_134_dialog_content = "Então foi tudo um blefe. E se Schummer não caísse?",
  ui_story_6_14_135_dialog_content = "Valia a tentativa. Quem poderia dizer quantos soldados estavam no trem de Illumina?",
  ui_story_6_14_136_dialog_content = "Falando nisso, para onde Schummer fugiu?",
  ui_story_6_14_137_dialog_content = "Não vi. Não consegui enxergar por causa de toda poeira que levantei...",
  ui_story_6_14_138_dialog_content = "Agora sei com certeza para onde a aura dela está indo. Em direção ao céu... Em direção a Lumópolis.",
  ui_story_6_14_139_dialog_content = "Lumópolis!",
  ui_story_6_14_140_dialog_content = "Lumópolis?!",
  ui_story_6_14_141_dialog_content = "Está indo diretamente para lá depois de pegar todos os módulos? Ela está alvejando Lumópolis!?",
  ui_story_6_14_142_dialog_content = "Tem um escudo poderoso cobrindo Lumópolis. Não tem chance dela entrar!",
  ui_story_6_14_A9_dialog_content = "Mas ela deve estar indo lá por uma razão.",
  ui_story_6_14_143_dialog_content = "Então ela acha que pode confrontar Lumópolis com a Colossus que tem agora?",
  ui_story_6_14_144_dialog_content = "PlayerName, defina o curso até Lumópolis imediatamente!",
  ui_story_6_14_145_dialog_content = "Claro, vamos nos apressar!",
  ui_story_7_1_1_dialog_content = "O mestre da Noite Branca é minha armadura, minha carne e meus ossos. Com a sua proteção, nenhum mal me ferirá...",
  ui_story_7_1_A1_dialog_content = "O mestre da Noite Branca é minha armadura, minha carne e meus ossos. Com a sua proteção, nenhum... Mantenha a calma! Sem pânico!",
  ui_story_7_1_2_dialog_content = "Olha, bateu no escudo!",
  ui_story_7_1_3_dialog_content = "Isso é um... <color=#FFB400>dragão preto</color>!?",
  ui_story_7_1_4_dialog_content = "Isso não deveria ser um problema, né? Nosso escudo é impenetrável e não pode ser destruído facilmente!",
  ui_story_7_1_5_dialog_content = "Acredite no Mestre da Noite Branca. Acredite na proteção de Aurora.",
  ui_story_7_1_6_dialog_content = "Enquanto o escudo aguentar, nenhum mal entrará na Cidade Alta abençoada! Não há motivo para pânico.",
  ui_story_7_1_7_dialog_content = "Estamos quase lá! Lumópolis está acima de nós!",
  ui_story_7_1_8_dialog_content = "Por que o céu mudou de cor!?",
  ui_story_7_1_9_dialog_content = "O Senhor da Cidade ativou o <color=#FFB400>escudo</color>.",
  ui_story_7_1_X1_dialog_content = "Muitas pessoas podem estar em perigo agora. Precisamos chegar rapidamente na cidade.",
  ui_story_7_1_X2_dialog_content = "E Schummer?",
  ui_story_7_1_10_dialog_content = "Salvem os civis primeiro. Estamos entrando na cidade!",
  ui_story_7_1_11_option_content = "Certo, pousaremos na cidade.",
  ui_story_7_1_12_option_content = "Não, seria melhor\nse parássemos fora da cidade.",
  ui_story_7_1_13_dialog_content = "Não... Dado o meu tamanho e a situação atual de Lumópolis, seria impossível.",
  ui_story_7_1_14_dialog_content = "Isso não parece bom. O <color=#FFB400>escudo de Lumópolis já foi ativado</color>.",
  ui_story_7_1_A2_dialog_content = "O escudo vai manter os Eclipsitas fora, mas Soroz também não conseguirá entrar.",
  ui_story_7_1_16_dialog_content = "Por que precisamos nos apressar se o escudo é tão poderoso?",
  ui_story_7_1_17_dialog_content = "O escudo só protege a Cidade Alta... O resto da cidade está totalmente fora de sua proteção!",
  ui_story_7_1_F1_dialog_content = "Com certeza os Eclipsitas entrarão por Baixa Lumópolis e atacarão os pontos cegos do escudo!",
  ui_story_7_1_F2_dialog_content = "Não podemos pousar Soroz na Baixa Lumópolis se estiver cheia de Eclipsitas.",
  ui_story_7_1_18_dialog_content = "PlayerName, eu posso pairar até Lumópolis e encontrar você quando precisarem de mim.",
  ui_story_7_1_19_dialog_content = "Mas isso não será perigoso?",
  ui_story_7_1_F3_dialog_content = "Vou dar meu melhor para estar alerta com Schummer e manter contato com vocês!",
  ui_story_7_1_F4_dialog_content = "Desculpa te fazer passar por isso, Soroz.",
  ui_story_7_1_20_dialog_content = "Carleen, Lumópolis pode ser rompida?",
  ui_story_7_1_21_dialog_content = "Não, é impossível. Contanto que <color=#FFB400>aquele homem</color> esteja lá, Lumópolis será forte.",
  ui_story_7_1_22_dialog_content = "De fato. Dado o meu tamanho e o dilema atual de Lumópolis, não teremos permissão para entrar.",
  ui_story_7_1_23_dialog_content = "PlayerName, você acharia melhor se pousássemos com Soroz do lado de fora?",
  ui_story_7_1_24_dialog_content = "Bom, se Schummer está alvejando Lumópolis, Soroz deve ficar fora disso o mais longe possível.",
  ui_story_7_1_25_dialog_content = "Eu concordo. E mesmo se quiséssemos dirigir com Soroz até a cidade, seria impossível.",
  ui_story_7_1_26_dialog_content = "O <color=#FFB400>escudo da Cidade Alta está ativado</color>, então nada consegue entrar.",
  ui_story_7_1_F5_dialog_content = "Mas com certeza os Eclipsitas entrarão por Baixa Lumópolis e atacarão os pontos cegos do escudo!",
  ui_story_7_1_27_dialog_content = "PlayerName, eu posso pairar até Lumópolis e encontrar você quando precisarem de mim.",
  ui_story_7_1_28_dialog_content = "Mas isso não será perigoso?",
  ui_story_7_1_F6_dialog_content = "Vou dar meu melhor para estar alerta com Schummer e manter contato com vocês!",
  ui_story_7_1_F7_dialog_content = "Desculpa te fazer passar por isso, Soroz.",
  ui_story_7_1_29_dialog_content = "Vamos o mais rápido possível. Se Schummer realmente tem tanta certeza de que consegue tomar Lumópolis...",
  ui_story_7_1_30_dialog_content = "Não, é impossível. Contanto que <color=#FFB400>aquele homem</color> esteja lá, Lumópolis será forte.",
  ui_story_7_1_31_dialog_content = "Meu Senhor, a ameaça foi verificada. É uma Colossus, e está atacando Lumópolis!",
  ui_story_7_1_32_dialog_content = "Nosso escudo foi ativado e a Cidade Alta está segura por agora.",
  ui_story_7_1_33_dialog_content = "Tenha cuidado. Nesse ponto, é impossível julgar o poder e a intenção do inimigo. Fique alerta.",
  ui_story_7_1_34_dialog_content = "Os Guardiões ficarão de olho na movimentação do inimigo. O Departamento de Inteligência nos informará sobre novos acontecimentos.",
  ui_story_7_1_35_dialog_content = "Qual a situação atual em Baixa Lumópolis?",
  ui_story_7_1_36_dialog_content = "Meu Senhor, os Eclipsitas já invadiram Baixa Lumópolis. Devemos enviar reforços para ajudá-los?",
  ui_story_7_1_37_dialog_content = "Não. Continuem com foco em proteger a Cidade Alta. Não faça a nobreza tomar decisões estúpidas.",
  ui_story_7_1_38_dialog_content = "Sobre Baixa Lumópolis, eles têm suas próprias formas de sobreviver.",
  ui_story_7_1_39_dialog_content = "E a Legião de Illumina?",
  ui_story_7_1_40_dialog_content = "A maioria de suas legiões estão posicionadas muito longe daqui e não podem voltar a tempo de ajudar.",
  ui_story_7_1_41_dialog_content = "Só dois esquadrões estão perto de Lumópolis, comandados pela Chefe do Gabinete, Vivian e a Comandante da Legião, Sharona.",
  ui_story_7_1_42_dialog_content = "Essas duas? Certo, entendi. Por fim, e a <color=#FFB400>Carleen</color>? Alguma novidade?",
  ui_story_7_1_43_dialog_content = "Acabei de receber a informação de que a Capitã dos Guardiões está indo em direção à Baixa Lumópolis a pé.",
  ui_story_7_1_44_dialog_content = "Mande-a de volta para a Cidade Alta imediatamente. Não é hora de joguinhos. Não precisamos de boatos a essa altura.",
  ui_story_7_1_45_dialog_content = "<color=#e8d9bb>Dentro de Baixa Lumópolis</color>",
  ui_story_7_1_46_dialog_content = "Eu não vi um único Guardião.",
  ui_story_7_1_47_dialog_content = "Consigo detectar Eclipsitas aqui.",
  ui_story_7_1_48_dialog_content = "Que bagunça. Mal consigo acreditar que isso é Lumópolis.",
  ui_story_7_1_49_dialog_content = "Pousei aproximadamente sobre... onde vocês estão.",
  ui_story_7_1_A3_dialog_content = "Escudo de Lumópolis... Causando interferência. Espero que... Ouçam isso...",
  ui_story_7_1_50_dialog_content = "Não se preocupe, eu entendi! Estamos em segurança. Se cuida!",
  ui_story_7_1_51_dialog_content = "Essa fala é... minha, PlayerName.",
  ui_story_7_1_52_dialog_content = "Vou... Esperar vocês! Cuidem-se... seus...",
  ui_story_7_1_53_dialog_content = "Queria que alguém pudesse me dizer como as coisas estão.",
  ui_story_7_1_54_dialog_content = "Não é tão ruim quanto parece, Vice, PlayerName.",
  ui_story_7_1_55_dialog_content = "Madame <color=#FFB400>Vivian</color>!",
  ui_story_7_1_56_dialog_content = "A maioria das legiões defende os arredores, então agora somos os únicos disponíveis para ajudar.",
  ui_story_7_1_57_dialog_content = "Lumópolis está caindo? Estes civis estão fora de controle!",
  ui_story_7_1_A4_dialog_content = "Nos reencontramos, Celestita! Onde há problemas, você está presente.",
  ui_story_7_1_58_dialog_content = "Não quero ter nenhuma relação com isso. Por favor, não coloquem a culpa em mim.",
  ui_story_7_1_59_dialog_content = "Por que faríamos isso? Você fez o que pôde para impedir Schummer, não foi? Apenas não esperávamos por isso.",
  ui_story_7_1_60_dialog_content = "Senhora, você sabe o que tá rolando em Lumópolis?",
  ui_story_7_1_61_dialog_content = "A Cidade Alta está em segurança, claro. Viram o escudo?",
  ui_story_7_1_62_dialog_content = "Foi ativado. Nada pode penetrá-lo. É isso que querem dizer com a Cidade Inconquistável.",
  ui_story_7_1_63_dialog_content = "Entretanto, Baixa Lumópolis não tem tanta sorte.",
  ui_story_7_1_64_dialog_content = "Madame <color=#FFB400>Sharona</color>? Quero dizer, Comandante da Legião...",
  ui_story_7_1_65_dialog_content = "Ah, esqueci de dizer que a maioria das tropas que estão respondendo a essa emergência foram transferidas da 1ª Legião.",
  ui_story_7_1_66_dialog_content = "O escudo não cobre Baixa Lumópolis. Até uma criança de três anos poderia entrar e sair, imagina um Eclipsita.",
  ui_story_7_1_68_dialog_content = "Conseguem cuidar disso? O que está acontecendo? Quero detalhes.",
  ui_story_7_1_70_dialog_content = "Vamos fazer uma busca rápida e vai ser difícil, mas agora meu povo mal consegue aguentar o que tem lá.",
  ui_story_7_1_71_dialog_content = "E os Guardiões? Recebi uma ordem para retornar à Cidade Alta imediatamente. Onde estão os outros Guardiões?",
  ui_story_7_1_72_dialog_content = "Carleen de Schwartz, acho que não está me entendendo.",
  ui_story_7_1_A5_dialog_content = "Seu pai ordenou que todos os Guardiões, inclusive você, protegessem a Cidade Alta.",
  ui_story_7_1_73_dialog_content = "Não está surpresa, não é? Acredito que você não esperava por algo diferente.",
  ui_story_7_1_74_dialog_content = "Não precisa falar assim comigo, Sharona! Acredito que fiz o suficiente para receber um pouco de respeito!",
  ui_story_7_1_75_dialog_content = "Suas ações realmente mudaram algo? Lumópolis ainda é Lumópolis.",
  ui_story_7_1_76_option_content = "Já chega, senhoras!",
  ui_story_7_1_77_option_content = "Fiquem quietas vocês duas!\nTemos questões mais urgentes!",
  ui_story_7_1_78_dialog_content = "Não quero saber de discussões.",
  ui_story_7_1_79_dialog_content = "PlayerName, não cabe a você bancar o pacificador.",
  ui_story_7_1_80_dialog_content = "Isso é entre Illumina e Lumópolis.",
  ui_story_7_1_81_dialog_content = "Esse não é o problema. Além disso, vocês não são todas Aurorians?",
  ui_story_7_1_82_dialog_content = "Senhora, PlayerName só está preocupado com a situação atual. Estamos todos no limite...",
  ui_story_7_1_83_dialog_content = "Uma observação astuta, Vice. O que PlayerName disse é verdade. Não somos uma família?",
  ui_story_7_1_84_dialog_content = "O mais importante de tudo é que nós, como Aurorians, devíamos lutar juntos! Certo?",
  ui_story_7_1_85_dialog_content = "Eu concordo. Nossas opiniões não importam nesse momento.",
  ui_story_7_1_86_dialog_content = "Falando nisso, Carleen, você não devia dar apoio à Cidade Alta primeiro? Parece que o Senhor da Cidade está te procurando.",
  ui_story_7_1_F8_dialog_content = "Sou a única pessoa que consegue ver aqueles Eclipsitas?",
  ui_story_7_1_87_dialog_content = "Olha como fala, PlayerName!",
  ui_story_7_1_88_dialog_content = "Está falando com a Comandante da 1ª Legião de Illumina e Carleen, PlayerName.",
  ui_story_7_1_89_dialog_content = "Eu sei! Mas também sei que não importa se é a Comandante da Legião ou a Capitã dos Guardiões, não devíamos deixar de salvar pessoas para ficar trocando palavras vazias!",
  ui_story_7_1_90_dialog_content = "Sim. O mais importante agora é lutar contra os Eclipsitas, e não discutir entre nós sobre disputas de poder insignificantes.",
  ui_story_7_1_91_dialog_content = "Lamentavelmente, não preciso de uma jovem moça para me dizer como devo me comportar, muito obrigada.",
  ui_story_7_1_92_dialog_content = "E sobre matar Eclipsitas, faço isso em batalhas constantemente.",
  ui_story_7_1_93_dialog_content = "Ouvi dizer que recentemente esteve em várias batalhas. Devia conseguir entender isso, correto?",
  ui_story_7_1_94_dialog_content = "...",
  ui_story_7_1_95_dialog_content = "Bom, então temos um acordo. Vamos canalizar nossa energia para os Eclipsitas, podemos?",
  ui_story_7_1_96_dialog_content = "Não quer voltar primeiro, Carleen?",
  ui_story_7_1_97_dialog_content = "Não. Ninguém manda em mim enquanto estou aqui do lado de fora.",
  ui_story_7_1_98_dialog_content = "Mas não estamos do lado de fora. Quero dizer, basicamente está em casa...",
  ui_story_7_1_F9_dialog_content = "Já chega, Vice.",
  ui_story_7_1_99_dialog_content = "Comandante da Legião! Tem mais Eclipsitas na Baixa Lumópolis do que esperávamos! Nossas defesas estão esgotadas e há uma ruptura!",
  ui_story_7_1_A6_dialog_content = "Os residentes da área não puderam evacuar! Qual é sua ordem?",
  ui_story_7_1_100_dialog_content = "Eu mesma irei lá! No que diz respeito a vocês, façam o que quiserem.",
  ui_story_7_1_101_dialog_content = "Por favor, nos leve com você. Podemos ajudar!",
  ui_story_7_1_102_dialog_content = "Realmente está animada, Vice! <color=#FFB400>Está bem. Vamos juntos</color>!",
  ui_story_7_1_103_dialog_content = "Vou guiar o caminho. Baixa Lumópolis é um lugar que patrulhei inúmeras vezes. Ninguém conhece as ruas melhor que eu.",
  ui_story_7_1_104_dialog_content = "Carleen, realmente não há problema se você não voltar?",
  ui_story_7_1_105_dialog_content = "Não tem mais o que dizer. Tomei minha decisão. Vamos colocar um fim nisso.",
  ui_story_7_1_106_dialog_content = "Lumópolis realmente tem uma casca grossa!",
  ui_story_7_1_107_dialog_content = "Que droga, por que não me contou sobre essa defesa que está usando?! Que recurso covarde é esse?",
  ui_story_7_1_108_dialog_content = "Eu disse para deixar alcançar o poder máximo antes de atacar, mas claro, você é cabeçuda demais para se segurar!",
  ui_story_7_1_109_dialog_content = "Se tem todo esse tempo para dar sermão, por que não envia mais de seus lacaios para espalhar o caos em Lumópolis?",
  ui_story_7_1_110_dialog_content = "Shh, sossega. Não gosto de tumulto.",
  ui_story_7_1_111_dialog_content = "O escudo de Lumópolis vai ficar sem energia em breve.",
  ui_story_7_1_A7_dialog_content = "Quando isso acontecer, vai conseguir entrar tranquilamente.",
  ui_story_7_1_112_dialog_content = "Então o que faço agora? Esperar ou continuar o ataque?",
  ui_story_7_1_113_dialog_content = "Quer ficar sem fazer nada enquanto seus comparsas inúteis nos fazem passar vergonha?",
  ui_story_7_1_114_dialog_content = "Tenha paciência, Schummer. Seu antigo inimigo está espiando por aí.",
  ui_story_7_1_116_dialog_content = "Está falando de Soroz? E PlayerName?",
  ui_story_7_1_117_dialog_content = "Correto. Parece que você quer sair por aí para brincar... Que divertido.",
  ui_story_7_1_X3_dialog_content = "Eu faço o que quiser. Não se esqueça, não sigo as ordens de ninguém. Nem suas, nem dos Eclipses.",
  ui_story_7_1_X4_dialog_content = "Putz. Você não tem jeito.",
  ui_story_7_2_1_dialog_content = "Carleen, quão longe estamos da área que precisa de ajuda?",
  ui_story_7_2_2_dialog_content = "Estamos aqui! Esse é o lugar do qual o soldado estava falando agora mesmo.",
  ui_story_7_2_3_dialog_content = "A aura Eclipsita é muito forte aqui. A respeito da <color=#FFB400>questão mais importante</color> de ser cuidada aqui...",
  ui_story_7_2_4_option_content = "Devíamos evacuar as pessoas primeiro.",
  ui_story_7_2_5_option_content = "Remover Eclipsitas vagantes",
  ui_story_7_2_6_dialog_content = "PlayerName, o defensor do povo! Talvez você se torne um grande líder no futuro!",
  ui_story_7_2_7_dialog_content = "Assim me deixa sem jeito, madame...",
  ui_story_7_2_8_dialog_content = "Certo, vou atrás de pessoas precisando de ajuda. Sou mais veloz que qualquer um de vocês.",
  ui_story_7_2_A1_dialog_content = "Eliminem todos os Eclipsitas que encontrarem. Conseguem dar conta dessa simples tarefa, não é?",
  ui_story_7_2_9_dialog_content = "Entendido! A única forma de garantir um resgate tranquilo é removendo a ameaça.",
  ui_story_7_2_10_dialog_content = "Vamos nos dividir. Talvez os esforços de resgate e limpeza possam acontecer simultaneamente.",
  ui_story_7_2_11_dialog_content = "Vou atrás de pessoas que precisam de ajuda. Sou mais veloz que qualquer um de vocês.",
  ui_story_7_2_A2_dialog_content = "Eliminem todos os Eclipsitas que encontrarem. Conseguem dar conta dessa simples tarefa, não é?",
  ui_story_7_2_12_dialog_content = "Não me subestime, Sharona.",
  ui_story_7_2_13_dialog_content = "Parece que todos estão prontos para agir. Ótimo, vamos lá!",
  ui_story_7_2_14_dialog_content = "Vou por aqui. Vice, vocês tomam conta daquela ponta!",
  ui_story_7_2_15_dialog_content = "E a sua Colossus? Ainda não estamos numa situação boa. Lembre-se de tomar cuidado!",
  ui_story_7_2_16_dialog_content = "Soroz está perambulando pela parte de fora da cidade e deve estar seguro por agora, eu acho.",
  ui_story_7_2_17_dialog_content = "Somos poucos, pessoal, então deem seu melhor.",
  ui_story_7_2_F1_dialog_content = "Bom, se os Guardiões estivessem aqui para ajudar...",
  ui_story_7_2_18_dialog_content = "Eu não conto como Guardião?",
  ui_story_7_2_19_dialog_content = "Desculpe, não quis diminuir ninguém.",
  ui_story_7_2_21_dialog_content = "Vamos indo para acabar com alguns Eclipsitas! Meu objetivo é chegar em três dígitos!",
  ui_story_7_2_22_dialog_content = "É só isso...",
  ui_story_7_2_23_dialog_content = "Cada oficial superior da Illumina é excepcional à sua maneira. Vamos começar eliminando os inimigos por aqui!",
  ui_story_7_6_1_dialog_content = "Ufa. Tudo limpo por aqui!",
  ui_story_7_6_2_dialog_content = "Por aqui também! Madame, há mais algum lugar em Baixa Lumópolis que precisa de ajuda?",
  ui_story_7_6_3_dialog_content = "Mais desses cretinos apareceram, mas estão sob controle. Ótimo trabalho.",
  ui_story_7_6_4_dialog_content = "Ufa. Essa crise foi evitada. Parece que chegamos a tempo.",
  ui_story_7_6_6_dialog_content = "Muito bom, Vice. Baixa Lumópolis deve ficar bem por agora. Podemos verificar outro lugar!",
  ui_story_7_6_7_dialog_content = "O inimigo pode estar planejando atacar um ponto fraco das nossas defesas!",
  ui_story_7_6_8_dialog_content = "Senhora, sabia que tem um talento natural para atrair má sorte?",
  ui_story_7_6_9_dialog_content = "Só para garantir, você pode confirmar a condição de Soroz, PlayerName?",
  ui_story_7_6_10_dialog_content = "Soroz não entra em contato comigo há um tempo. Vou tentar.",
  ui_story_7_6_12_dialog_content = "Normal. Sem Eclipsitas por perto... Mas parece que a temperatura caiu bastante, eu...",
  ui_story_7_6_13_dialog_content = "<size=45>O quê?!</size>",
  ui_story_7_6_14_dialog_content = "O que foi Carleen? Está ferida?",
  ui_story_7_6_15_dialog_content = "Não, mas acabei de receber a mensagem de que <color=#FFB400>a Cidade Alta foi invadida</color>!",
  ui_story_7_6_16_dialog_content = "A Cidade Alta? Os Eclipsitas romperam as defesas da Baixa Lumópolis e estão invadindo a Cidade Alta?",
  ui_story_7_6_17_dialog_content = "Não, a fronteira de Baixa Lumópolis não foi rompida. Eles devem ter se infiltrado na Cidade Alta antes!",
  ui_story_7_6_18_dialog_content = "Eles atacaram o coração de Lumópolis diretamente? A Cidade Alta não tem defesas pesadas?",
  ui_story_7_6_19_dialog_content = "Sim, bastante. Mas os Eclipsitas agiram de forma estranha...",
  ui_story_7_6_20_dialog_content = "Se Schummer ousa atacar Lumópolis, aqueles Eclipsitas devem ter vindo preparados.",
  ui_story_7_6_21_dialog_content = "Exato. Tive um mau pressentimento sobre isso agora. Preciso voltar imediatamente.",
  ui_story_7_6_22_dialog_content = "Nós também! Vamos lá, PlayerName!",
  ui_story_7_6_23_dialog_content = "Um inimigo que consegue entrar na Cidade Alta deve possuir poderes assustadores. Agradeço a disposição de me acompanharem.",
  ui_story_7_6_24_dialog_content = "Entendido! Senhora, recebemos a notícia de que a Cidade Alta está sendo atacada por um Eclipsita especial! Precisamos ajudar as forças de defesa!",
  ui_story_7_6_25_dialog_content = "Estamos a caminho!",
  ui_story_7_6_26_dialog_content = "Estou quase lá.",
  ui_story_7_6_27_dialog_content = "A Comandante da Legião realmente é diferente!",
  ui_story_7_7_1_dialog_content = "Desculpe, me atrasei!",
  ui_story_7_7_2_dialog_content = "Capitã! Finalmente voltou. Os Eclipsitas estão...",
  ui_story_7_7_3_dialog_content = "Não diga mais nada! Onde está o inimigo!?",
  ui_story_7_7_4_dialog_content = "Por ali! Me sigam!",
  ui_story_7_7_5_dialog_content = "<size=45>Woogagagagaga!!!</size>",
  ui_story_7_7_6_dialog_content = "Continuem! Não deixe isso avançar mais! A Cidade Alta está logo em frente!",
  ui_story_7_7_7_dialog_content = "Wooga!!!",
  ui_story_7_7_8_dialog_content = "Caramba! A defesa foi rompida! Reagrupem-se! Eles não devem se aproximar da cidade!",
  ui_story_7_7_9_dialog_content = "Ah! Carleen!",
  ui_story_7_7_10_dialog_content = "O que estão fazendo? Não fiquem parados vendo esse alvoroço, este é o coração de Lumópolis!",
  ui_story_7_7_11_dialog_content = "O Senhor da Cidade nos deu ordens. <color=#FFB400>Devemos proteger apenas a Cidade Alta</color>...",
  ui_story_7_7_12_dialog_content = "Tecnicamente, aquele insetão ainda não conseguiu atravessar, então não podemos sair agora...",
  ui_story_7_7_13_dialog_content = "Que tipo de lógica é essa!?",
  ui_story_7_7_15_dialog_content = "Carleen, os Guardiões não podem atacar, mas ainda podemos confiar no apoio de Illumina! Essas duas oficiais devem conseguir cuidar disso!",
  ui_story_7_7_16_dialog_content = "Limpando a bagunça dos Guardiões novamente?",
  ui_story_7_7_17_dialog_content = "Senhora! Guardiões devem obedecer às suas ordens... Não podem sair da Cidade Alta para encarar o inimigo. Nós cuidaremos disso!",
  ui_story_7_7_18_dialog_content = "Toda vez que me obrigam a trabalhar com Lumópolis, me lembro do verdadeiro significado de burocracia.",
  ui_story_7_7_19_dialog_content = "Então tá bom, Sharona. Não é hora de reclamar. Aqueles soldados não vão aguentar por muito tempo.",
  ui_story_7_7_21_dialog_content = "Vamos cortar ele em pedacinhos! Membro por membro!",
  ui_story_7_7_22_dialog_content = "Membro por membro?",
  ui_story_7_7_23_dialog_content = "...?",
  ui_story_7_7_24_dialog_content = "Falando por experiência própria, partir eles em pedaços facilita na hora de descartar os corpos! Foquem na luta, crianças!",
  ui_story_7_7_25_dialog_content = "Certo! Diga o que a gente precisa fazer, madame...",
  ui_story_7_7_26_dialog_content = "Vamos derrotar essa escória primeiro! Vivian, lembre-se de cortar no momento certo, como antes!",
  ui_story_7_7_27_dialog_content = "Entendido, igual antes!",
  ui_story_7_7_28_dialog_content = "Vou abrir o caminho! O resto de vocês, apenas saiam da frente! Não morram! E o nosso <color=#FFB400>comandante</color>...",
  ui_story_7_7_29_dialog_content = "Deixa comigo! Não tem chance de eu perder!",
  ui_story_7_7_30_dialog_content = "<color=#FFB400>Jogue isso pra fora da Cidade Alta</color>!",
  ui_story_7_7_31_dialog_content = "<anim type=Shake><size=45>Gahhhhhhhh!</size></anim>",
  ui_story_7_7_32_dialog_content = "Vivian, agora!",
  ui_story_7_7_33_dialog_content = "Venha, Florete Radium!",
  ui_story_7_7_34_dialog_content = "Olho por Olho!",
  ui_story_7_7_36_dialog_content = "Finalmente caiu!",
  ui_story_7_7_37_dialog_content = "Neutralizamos a ameaça com sucesso! Vocês são bem úteis quando o negócio fica apertado!",
  ui_story_7_7_38_dialog_content = "...",
  ui_story_7_7_39_dialog_content = "Fico lisonjeado, madame.",
  ui_story_7_7_40_dialog_content = "Madame, a Colossus preta ainda está atacando e não mostra sinais de desistência!",
  ui_story_7_7_41_dialog_content = "Schummer...",
  ui_story_7_7_42_dialog_content = "Ainda tão insistente. O que ela ganha continuando a luta?",
  ui_story_7_7_43_dialog_content = "É muito mais do que ela aguenta. Esses Eclipsitas não conseguem nem encostar um dedo na Cidade Alta.",
  ui_story_7_7_44_dialog_content = "Talvez apenas sejam burros.",
  ui_story_7_7_45_dialog_content = "A ameaça à Cidade Alta foi eliminada? Se não tem mais nada para fazer aqui, vou partir primeiro.",
  ui_story_7_7_46_dialog_content = "A 1ª Legião ainda precisa terminar de defender a zona leste... Cof, tudo graças aos Guardiões.",
  ui_story_7_7_47_dialog_content = "De qualquer forma, agradeço pela ajuda, Illumina.",
  ui_story_7_7_48_dialog_content = "Não agradeça a mim, agradeça a PlayerName e Vice.",
  ui_story_7_7_A2_dialog_content = "Nem todos têm paciência para trabalhar com Lumópolis, ainda mais assumindo a retaguarda sem apoio.",
  ui_story_7_7_49_dialog_content = "...",
  ui_story_7_7_50_dialog_content = "Entendi, usando ambiguidade. Sharona faz isso às vezes. Não pensa muito nisso, Carleen.",
  ui_story_7_7_51_dialog_content = "A crise foi evitada. Esse foi o melhor resultado, e é tudo que importa agora.",
  ui_story_7_7_52_dialog_content = "Schummer queria atacar Lumópolis de cara, sem perceber que temos um meio de defesa quase impenetrável.",
  ui_story_7_7_53_dialog_content = "O que ela fará agora? Aquela Colossus Preta estava totalmente carregada?",
  ui_story_7_7_X1_dialog_content = "Ela roubou três módulos, mas a Colossus Preta não parece tão poderosa.",
  ui_story_7_7_54_dialog_content = "Suponho que Schummer não tenha atingido o poder total. Esse ataque mostrou que ela nos subestimou.",
  ui_story_7_7_55_dialog_content = "Já que conhece ela, podemos esperar por algum tipo de retaliação louca por causa do que aconteceu hoje?",
  ui_story_7_7_56_dialog_content = "Estou com a sensação de que algo terrível vai acontecer.",
  ui_story_7_7_57_dialog_content = "Por favor, não diga isso madame. Geralmente você está certa.",
  ui_story_7_7_58_option_content = "Devíamos tomar a iniciativa.",
  ui_story_7_7_59_option_content = "É melhor esperarmos e ver\no que vai acontecer.",
  ui_story_7_7_60_dialog_content = "Concordo. Temos que aproveitar o momento e ir atrás da oportunidade!",
  ui_story_7_7_61_dialog_content = "Verdade. Temos aceitado tudo que ela faz passivamente! Está na hora de tomar a ofensiva!",
  ui_story_7_7_62_dialog_content = "Tem razão, PlayerName! Devíamos ficar quietos até termos mais informações.",
  ui_story_7_7_63_dialog_content = "É mais provável que Schummer perca a paciência primeiro.",
  ui_story_7_7_A3_dialog_content = "Ela conseguiu controlar os módulos, mas agora deve estar travada. Vamos esperar por um erro dela!",
  ui_story_7_7_64_dialog_content = "Argh...!",
  ui_story_7_7_65_dialog_content = "PlayerName? Qual o problema?",
  ui_story_7_7_66_dialog_content = "(Minha mente... O que é essa dor aguda!?)",
  ui_story_7_7_67_dialog_content = "...",
  ui_story_7_7_68_dialog_content = "Soroz!",
  ui_story_7_7_69_dialog_content = "Sob ataque! O inimigo... Ela invadiu m... Mais de um... Tem mais um...",
  ui_story_7_7_X2_dialog_content = "Não consigo te ouvir! Soroz, ainda está na sua coordenada!? Estamos indo te ajudar!",
  ui_story_7_7_X3_dialog_content = "Por perto! Por favor... Inimigo invadiu... Ela não está sozinha!",
  ui_story_7_7_A4_dialog_content = "<color=#FFB400>Volte</color>... <color=#FFB400>Volte aqui</color>!",
  ui_story_7_7_X4_dialog_content = "Soroz foi invadido! A Schummer mudou o alvo dela!",
  ui_story_7_7_X5_dialog_content = "?!",
  ui_story_7_7_X6_dialog_content = "Ela não conseguiu entrar em Lumópolis, e então decidiu nos atacar?",
  ui_story_7_7_70_dialog_content = "Volte para dar assistência emergencial. Dessa vez eu não trouxe uma aeronave. Podemos requisitar uma de Lumópolis, Carleen?",
  ui_story_7_7_71_dialog_content = "Hum...",
  ui_story_7_7_72_dialog_content = "Capitã, o Senhor da Cidade tem uma nova ordem. Você deve retornar à Cidade Alta.",
  ui_story_7_7_73_dialog_content = "Um momento. Isso é uma emergência. Preciso ajudá-los primeiro...",
  ui_story_7_7_74_dialog_content = "Sinto muito, mas isso não é um pedido. Se não retornar, temo que os Quatro Anjos serão enviados.",
  ui_story_7_7_75_dialog_content = "O quê? Só estou observando. Por que estou sendo empurrada para isso tudo?",
  ui_story_7_7_76_dialog_content = "...",
  ui_story_7_7_77_dialog_content = "Carleen, parece que seu pai tem seus próprios planos. Você deveria voltar.",
  ui_story_7_7_78_dialog_content = "Não se preocupe, Soroz está com Illumina. Vamos tomar conta disso.",
  ui_story_7_7_79_dialog_content = "Espera aí, quando foi que virei parte de Illumina?",
  ui_story_7_7_80_dialog_content = "...",
  ui_story_7_7_81_dialog_content = "...",
  ui_story_7_7_82_dialog_content = "Por que sinto que estou sendo obrigada a aceitar algo inferior? Quanto falta para minha Colossus estar completa?",
  ui_story_7_7_83_dialog_content = "Pouco. Mas estamos ficando sem tempo, e minha paciência está acabando, Schummer.",
  ui_story_7_7_85_dialog_content = "Claro. Só quero terminar o que não consegui finalizar no Corredor Suspirante.",
  ui_story_7_7_86_dialog_content = "PlayerName é muito especial. Essa foi a primeira vez que considerei poupar a vida de um Celestita.",
  ui_story_7_7_87_dialog_content = "O Celestita virá, consigo sentir isso. É o senso de dever ou a tolice de uma moralidade forte.",
  ui_story_7_7_A5_dialog_content = "PlayerName voltará aqui por conta desses ideais obsoletos.",
  ui_story_7_7_89_dialog_content = "Então não espere. Quantos lacaios perdemos por causa das suas bobagens? Preciso repetir o que disse!?",
  ui_story_7_7_90_dialog_content = "<color=#FFB400>Apenas mate isso</color>, Schummer.",
  ui_story_7_7_91_dialog_content = "Soroz, meu velho amigo...",
  ui_story_7_7_92_dialog_content = "<size=45>Isso vai doer um pouco!</size>",
  ui_story_7_8_1_dialog_content = "Pode me ouvir, Soroz?",
  ui_story_7_8_2_option_content = "Tentar telepatia",
  ui_story_7_8_3_dialog_content = "Soroz... Soroz...",
  ui_story_7_8_4_option_content = "Tentar telepatia",
  ui_story_7_8_5_dialog_content = "Não está funcionando. Não consigo detectar nada! E a interferência do escudo...",
  ui_story_7_8_6_dialog_content = "Precisamos voltar lá o mais rápido possível!",
  ui_story_7_8_7_dialog_content = "Não tenho autorização para usar a aeronave de Lumópolis até receber a aprovação dos Guardiões.",
  ui_story_7_8_8_dialog_content = "E acredito que vá demorar muito para requisitar uma da fortaleza Illumina mais próxima.",
  ui_story_7_8_9_dialog_content = "Carleen também não pode fazer nada...",
  ui_story_7_8_11_dialog_content = "Como filha do Senhor da Cidade e Capitã dos Guardiões de Lumópolis, ela já nos ajudou muito.",
  ui_story_7_8_12_dialog_content = "Realmente. Se ela se rebelasse de novo e aparecesse com uma aeronave para nós... Isso seria demais.",
  ui_story_7_8_13_dialog_content = "Minha nossa, a Vivian está usando seus poderes proféticos novamente...",
  ui_story_7_8_14_dialog_content = "Olha!",
  ui_story_7_8_15_dialog_content = "Desculpe interromper. Uma aeronave acabou de decolar ali!",
  ui_story_7_8_16_dialog_content = "Quem está pilotando? Está rodopiando por aí. Espera aí, está vindo até nós?",
  ui_story_7_8_17_dialog_content = "...?",
  ui_story_7_8_18_dialog_content = "Hã?",
  ui_story_7_8_19_dialog_content = "Sem chance... Carleen!",
  ui_story_7_8_20_dialog_content = "Entrem, rápido! Eu <color=#FFB400>confisquei</color> essa nave!",
  ui_story_7_8_21_dialog_content = "Confiscou? Você não é Capitã dos Guardiões!?",
  ui_story_7_8_22_dialog_content = "Vou explicar depois! Vocês não querem voltar para Soroz? Vão vir ou não?",
  ui_story_7_8_23_dialog_content = "Certo, agora podemos voltar!",
  ui_story_7_8_24_dialog_content = "Desculpe o atraso, PlayerName.",
  ui_story_7_8_25_option_content = "Imagina, você fez tanto por nós.",
  ui_story_7_8_26_option_content = "Não esquenta. Eu não sabia\nque você consegue pilotar uma aeronave.",
  ui_story_7_8_27_dialog_content = "Bom, eu só queria proteger Lumópolis...",
  ui_story_7_8_28_dialog_content = "Mas agora tem outra coisa que quero proteger.",
  ui_story_7_8_29_dialog_content = "Bom, parece que alguém está com a mentalidade certa.",
  ui_story_7_8_30_dialog_content = "Vamos nos apressar, Soroz está esperando por nós!",
  ui_story_7_8_31_dialog_content = "Nunca tive medo da morte, como <color=#FFB400>naquele ano</color> que você não conseguiu fazer eu me curvar.",
  ui_story_7_8_32_dialog_content = "Você pode abandonar os princípios da luz e buscar refúgio nas sombras das trevas...",
  ui_story_7_8_A1_dialog_content = "Mas todos nós estamos destinados à Aurora.",
  ui_story_7_8_33_dialog_content = "Schummer, você pode destruir minha consciência, mas nunca derrotará PlayerName!",
  ui_story_7_9_1_dialog_content = "Como pensamos, Schummer atacou Soroz!",
  ui_story_7_9_2_dialog_content = "Eclipsitas estão correndo desenfreadamente por aqui. Consigo sentir o fedor de Fluxo Escuro.",
  ui_story_7_9_3_dialog_content = "O que fizeram com Soroz?!",
  ui_story_7_9_4_dialog_content = "Fantasmas à direita. Esses imundos nos encontraram...",
  ui_story_7_9_5_dialog_content = "Vamos encará-los!",
  ui_story_7_9_6_dialog_content = "Bom, não fizemos tumulto demais para não deixar o inimigo alerta.",
  ui_story_7_9_7_dialog_content = "Poderíamos apenas matar todos o mais rápido possível antes que Schummer tenha chance de reagir.",
  ui_story_7_9_8_dialog_content = "Não acho que seja possível...",
  ui_story_7_9_9_dialog_content = "Não precisa arriscar sua vida com a gente, Carleen.",
  ui_story_7_9_10_dialog_content = "Somos amigos. É isso que disse, né?",
  ui_story_7_9_11_dialog_content = "Além disso, se eu não partir um inimigo ao meio com minha lança, como vou dormir à noite?",
  ui_story_7_9_12_option_content = "Eu não esperaria menos\nde você, Carleen.",
  ui_story_7_9_13_option_content = "Sim, somos amigos.",
  ui_story_7_9_14_dialog_content = "Como assim?",
  ui_story_7_9_15_dialog_content = "Acho que PlayerName quis dizer que não esperamos menos da Capitã dos Guardiões de Lumópolis.",
  ui_story_7_9_A1_dialog_content = "É sobre responsabilidade e coragem.",
  ui_story_7_9_16_dialog_content = "Se você diz. Mas ficar aqui me elogiando não vai mudar nossa situação atual.",
  ui_story_7_9_17_dialog_content = "E mesmo se não dissesse isso, ainda lutaria ao lado de vocês, porque somos <color=#FFB400>amigos</color>.",
  ui_story_7_9_18_dialog_content = "Apesar de todos falarem que Lumopolianos são apáticos, acho que você é diferente.",
  ui_story_7_9_19_dialog_content = "E isso é algo muito confuso para mim. Eu deveria resistir por Lumópolis ou por mim?",
  ui_story_7_9_20_dialog_content = "Julgando por suas ações, parece que você encontrou a resposta.",
  ui_story_7_9_21_dialog_content = "Talvez.",
  ui_story_7_9_22_dialog_content = "Eu sei que somos amigos. Preciso repetir?",
  ui_story_7_9_23_dialog_content = "Foi você quem perguntou. Esquece, temos mais coisas para fazer.",
  ui_story_7_9_24_dialog_content = "Você sabe o que enfrentamos, Carleen? As últimas batalhas foram bem difíceis, mas...",
  ui_story_7_9_25_dialog_content = "Estou sentindo que o pior ainda está por vir.",
  ui_story_7_9_26_dialog_content = "Por favor, não diga isso madame.",
  ui_story_7_9_27_dialog_content = "Não importa quão poderosa Schummer seja, todos nós temos motivos para querer derrotá-la, certo?",
  ui_story_7_9_28_dialog_content = "Mas parece meio meloso quando digo que quero <color=#FFB400>proteger quem amo</color>...",
  ui_story_7_9_A2_dialog_content = "No fim, o objetivo de lutar com tudo não é para proteger as pessoas com quem você se importa?",
  ui_story_7_9_29_dialog_content = "Isso, como Soroz.",
  ui_story_7_9_30_dialog_content = "Isso, Soroz.",
  ui_story_7_9_31_dialog_content = "PlayerName, consegue detectar Soroz? É melhor descobrirmos onde...",
  ui_story_7_9_32_dialog_content = "Não consigo, mas acredito que ainda esteja vivo.",
  ui_story_7_9_33_dialog_content = "Nunca tive a chance de me comunicar com uma Colossus. Tenho curiosidade para saber como é.",
  ui_story_7_9_A3_dialog_content = "Nossa, desculpa, sem ofensas.",
  ui_story_7_9_34_dialog_content = "E você, madame, o que está fazendo aqui?",
  ui_story_7_9_35_dialog_content = "O mesmo que Carleen. Essa ameaça já me encheu a paciência e quero ter uma conversa com ela.",
  ui_story_7_9_36_dialog_content = "Bom, vamos lá. Onde está Schummer, PlayerName?",
  ui_story_7_9_37_dialog_content = "Sinto que a presença horripilante está na <color=#FFB400>Ponte</color>!",
  ui_story_7_9_A4_dialog_content = "Acho que terão vários Eclipsitas no caminho. Estão preparadas?",
  ui_story_7_9_A5_dialog_content = "Claro! Minha lança sempre está pronta para ação!",
  ui_story_7_12_1_dialog_content = "PlayerName, não sei se conseguirá receber essa mensagem...",
  ui_story_7_12_2_dialog_content = "Foi uma grande honra servir você. Estou feliz de ter te protegido há dezessete anos e de ter plantado as sementes da esperança nesse mundo.",
  ui_story_7_12_3_dialog_content = "Se não for pedir muito, por favor, <color=#FFB400>não volte por mim</color>. Repito, <color=#FFB400>não volte por mim</color>.",
  ui_story_7_12_A1_dialog_content = "O adversário tem poder além da sua compreensão.",
  ui_story_7_12_4_dialog_content = "Seja forte, PlayerName. Não perca tempo ficando triste por mim.",
  ui_story_7_12_5_dialog_content = "Essa Colossus <color=#FFB400>foi feita para te servir</color>.",
  ui_story_7_13_1_dialog_content = "<size=45>Ai!</size>",
  ui_story_7_13_2_dialog_content = "(Meu coração está batendo <color=#FFB400>sem controle</color>!)",
  ui_story_7_13_3_dialog_content = "Ali está a ponte! Cuidado com os fantasmas!",
  ui_story_7_13_4_dialog_content = "Ainda não há um jeito de contatar Soroz?",
  ui_story_7_13_5_dialog_content = "Estou tentando. Acho que consigo ouvir algo. Parecem as mesmas palavras sendo repetidas.",
  ui_story_7_13_6_dialog_content = "Mas agora não consigo ouvir. Talvez esteja...",
  ui_story_7_13_7_dialog_content = "(Meu coração está batendo sem controle de novo!?)",
  ui_story_7_13_8_dialog_content = "Qual o problema, PlayerName?",
  ui_story_7_13_9_dialog_content = "O Fluxo Escuro daqui está forte demais para o PlayerName aguentar?",
  ui_story_7_13_10_dialog_content = "Ou talvez esteja detectando algo?",
  ui_story_7_13_11_dialog_content = "Mesmo? É Soroz?",
  ui_story_7_13_12_dialog_content = "Não, não é. Até eu detectei isso. Não percebeu como do nada o <color=#FFB400>ar ficou gelado</color>?",
  ui_story_7_13_13_dialog_content = "A sensação estranha, mas familiar, deve ser aquela miserável arrogante e nojenta.",
  ui_story_7_13_14_dialog_content = "...?!",
  ui_story_7_13_15_dialog_content = "*Boceja*",
  ui_story_7_13_16_dialog_content = "<size=45><color=#FFB400>Schummer</color>!</size>",
  ui_story_7_13_17_dialog_content = "PlayerName! Consegue detectar Schummer? Onde ela está?",
  ui_story_7_13_18_dialog_content = "O que você fez com Soroz, Schummer? Argh...!",
  ui_story_7_13_19_dialog_content = "Ainda é uma peste. Você não aprendeu nada, PlayerName.",
  ui_story_7_13_20_dialog_content = "O que mais posso fazer com Soroz? Simplesmente quebrei seu Modelo Eco.",
  ui_story_7_13_21_dialog_content = "Modelo Eco? Você destruiu a consciência de Soroz?",
  ui_story_7_13_22_dialog_content = "Sim. Você não sentiu? Seu coração imerso na escuridão e sem vida, a alma perfurada por uma dor inexplicável...",
  ui_story_7_13_23_dialog_content = "Schummer!",
  ui_story_7_13_24_dialog_content = "Caso ainda não tenha entendido, vou explicar: Soroz <color=#FFB400>morreu</color>.",
  ui_story_7_14_1_dialog_content = "Perdemos eles?",
  ui_story_7_14_2_dialog_content = "Desculpe!",
  ui_story_7_14_3_dialog_content = "Estava patrulhando ali em cima. Tudo que vi foi aquela Colossus preta e uma pequena Colossus branca!",
  ui_story_7_14_4_dialog_content = "Uma Colossus branca... Deve ser PlayerName. As crianças apareceram para brincar.",
  ui_story_7_14_5_dialog_content = "A Colossus preta se movimentou?",
  ui_story_7_14_6_dialog_content = "Não, ainda está atacando o escudo. Os Eclipsitas também estão atacando com força total.",
  ui_story_7_14_7_dialog_content = "Mantenham o escudo e priorizem as reservas de Lúmina para restaurar a energia dos distritos nobres e a infraestrutura.",
  ui_story_7_14_A1_dialog_content = "E então envie tropas de reforço à Baixa Lumópolis.",
  ui_story_7_14_9_dialog_content = "E Carleen?",
  ui_story_7_14_10_dialog_content = "Ela fez sua escolha, então está preparada para aceitar as consequências.",
  ui_story_7_14_11_dialog_content = "Do meu ponto de vista, não há razão para enviar Guardiões para acompanhar a busca estúpida dela.",
  ui_story_7_14_12_dialog_content = "Sim.",
  ui_story_7_14_13_dialog_content = "Como ela conseguiu essa aeronave? Isso é uma precedência terrível.",
  ui_story_7_14_14_dialog_content = "Se outros Guardiões deixarem Lumópolis  <color=#FFB400>para ajudá-la</color>...",
  ui_story_7_14_15_dialog_content = "Por que está me olhando?",
  ui_story_7_14_16_dialog_content = "Alguma pergunta?",
  ui_story_7_14_17_dialog_content = "Ah, hum, é, entendi!",
  ui_story_7_14_18_dialog_content = "Eu já vou. Ah, quer dizer, solicitando permissão para retirada!",
  ui_story_7_14_19_dialog_content = "Mais rápido, ratos. Vocês ficariam perdidos em suas próprias casas!",
  ui_story_7_14_20_dialog_content = "Cala a boca, Eclipsita. Se tiver algo para dizer, diga agora!",
  ui_story_7_14_21_dialog_content = "Parece que você me entendeu mal, princesa. Agora eu possuo o poder de <color=#FFB400>todos os módulos</color>.",
  ui_story_7_14_X1_dialog_content = "A não ser que queira ir com PlayerName até o inferno, é melhor voltar para Lumópolis com o rabo entre as pernas!",
  ui_story_7_14_22_dialog_content = "Não consegue quebrar o escudo de Lumópolis, não é? Espera que acreditemos que está com poder total?",
  ui_story_7_14_23_dialog_content = "Silêncio, Celestita. A Colossus preta ainda não está completa.",
  ui_story_7_14_A2_dialog_content = "Mas quando a hora chegar, vou reservar bancos na primeira fila para vocês.",
  ui_story_7_14_X2_dialog_content = "(É como pensamos, ela não concluiu o processo!)",
  ui_story_7_14_X3_dialog_content = "Não me olha assim, PlayerName.",
  ui_story_7_14_24_dialog_content = "Eu tive que vir e lidar com você pessoalmente enquanto ataco Lumópolis. Você está me testando.",
  ui_story_7_14_25_dialog_content = "Me digam, Vice e PlayerName. Essa Eclipsita realmente é tão poderosa?",
  ui_story_7_14_26_dialog_content = "Mesmo que ela pareça difícil de lidar, isso deve ser moleza se trabalharmos juntos, né?",
  ui_story_7_14_27_dialog_content = "Seria mais fácil se a Comandante Sharona também estivesse aqui...",
  ui_story_7_14_28_dialog_content = "Vai sonhando. Mesmo se chamar todos os seus aliados, ainda não seriam páreo.",
  ui_story_7_14_A3_dialog_content = "Minha Colossus está ficando mais forte a cada momento...",
  ui_story_7_14_29_dialog_content = "Mas devo admitir, seu otimismo é admirável. Todos em Illumina são confiantes assim?",
  ui_story_7_14_30_dialog_content = "Para de enrolar, Schummer! Chega de conversinha.",
  ui_story_7_14_31_dialog_content = "Eu sei, cala a boca.",
  ui_story_7_14_32_dialog_content = "...",
  ui_story_7_14_33_dialog_content = "O que houve, madame?",
  ui_story_7_14_34_dialog_content = "A pessoa que está por trás de Schummer parece <color=#FFB400>muito familiar</color>.",
  ui_story_7_14_38_dialog_content = "Ei, o que está cochichando? Mesmo se estiver gritando suas últimas palavras com todas as forças, ninguém ouvirá.",
  ui_story_7_14_39_dialog_content = "Mas PlayerName, você é especial.",
  ui_story_7_14_A4_dialog_content = "Eu sei que não quer continuar sendo fraco, se escondendo na sombra dos fortes. Você é igual a mim.",
  ui_story_7_14_40_dialog_content = "Venha, se junte a nós. Escolha o caminho certo.",
  ui_story_7_14_41_dialog_content = "É a única forma de você conseguir o poder necessário para mudar seu destino.",
  ui_story_7_14_42_dialog_content = "O poder para mudar o meu destino? Como assim?",
  ui_story_7_14_43_dialog_content = "Visão, longevidade, conhecimento, Fluxo Escuro poderoso, a verdade desse mundo.",
  ui_story_7_14_44_dialog_content = "A coisa mais importante é que você nunca precisará se preocupar com a derrota, apenas com quem quer derrotar. Você será supremo.",
  ui_story_7_14_46_dialog_content = "Vá direto ao ponto, estou com pressa.",
  ui_story_7_14_47_dialog_content = "Você?!",
  ui_story_7_14_48_dialog_content = "Desculpe, não tenho interesse em nada que você diz.",
  ui_story_7_14_49_dialog_content = "Você adora ficar divagando e nem sabe por quê. Você ao menos sabe o significado dessas coisas?",
  ui_story_7_14_50_dialog_content = "A verdade desse mundo. O poder de mudar seu destino. Não se preocupar com a derrota.",
  ui_story_7_14_51_dialog_content = "É por isso que os que colocam a vida de outros em perigo não têm lugar neste mundo.",
  ui_story_7_14_52_dialog_content = "Você acha que quando encontra alguém mais fraco que você, tem de eliminá-lo, e quando encontra alguém mais forte, deve se curvar, implorar por misericórdia e submeter-se ao poder maior?",
  ui_story_7_14_A5_dialog_content = "Não sei como se convence disso. Realmente acha que quero ser como você?",
  ui_story_7_14_53_dialog_content = "Está tentando se vangloriar de ser correta e nunca errar?",
  ui_story_7_14_54_dialog_content = "Você precisa ir ao médico dar uma conferida nessa cachola. Ninguém em sã consciência seria tão cego em relação à verdade.",
  ui_story_7_14_55_dialog_content = "...",
  ui_story_7_14_56_dialog_content = "De onde veio isso, PlayerName?",
  ui_story_7_14_57_dialog_content = "Mandou bem...",
  ui_story_7_14_F1_dialog_content = "Ah, sim. Também queria te perguntar: quanto tempo ficou de joelhos até conseguir seus poderes?",
  ui_story_7_14_58_dialog_content = "Engraçado.",
  ui_story_7_14_59_dialog_content = "<size=50>Muito engraçado!</size>",
  ui_story_7_14_60_dialog_content = "Seu maldito inútil! Idiota! Totalmente cego!",
  ui_story_7_14_61_dialog_content = "Está tentando me irritar? Quer morrer?",
  ui_story_7_14_63_dialog_content = "Ah, a coisa tá ficando séria, né?",
  ui_story_7_14_A6_dialog_content = "A raiva é o catalisador perfeito para conquistar o poder grandioso.",
  ui_story_7_14_64_dialog_content = "Vou te manter com vida e te torturar lentamente! Vou fazer você sentir humilhação e desespero!",
  ui_story_7_14_F2_dialog_content = "Aí saberá que estou certa!",
  ui_story_7_14_65_dialog_content = "Não, eu deveria dizer isso para você, <color=#FFB400>Schummer, traidora dos Celestitas</color>!",
  ui_story_7_14_66_dialog_content = "Vamos lá! O que está esperando!?",
  ui_story_7_14_67_dialog_content = "Ela é... forte demais... O poder...",
  ui_story_7_14_68_dialog_content = "Ainda consigo me mover. Preparem-se para atacar! Não vamos deixar ela ir...",
  ui_story_7_14_69_dialog_content = "Não se precipite! Precisamos achar um jeito.",
  ui_story_7_14_70_dialog_content = "Odeio admitir isso, mas PlayerName tem razão...",
  ui_story_7_14_A7_dialog_content = "Foi bom não termos trazido ninguém com a gente. Senão, estaríamos todos presos aqui.",
  ui_story_7_14_71_dialog_content = "Do jeito que está agora, não podemos nem dar retirada.",
  ui_story_7_14_72_dialog_content = "Retirada? Você quer ir embora? Certo, você pode sair depois que eu te cortar em pedaços e jogar ao vento!",
  ui_story_7_14_73_dialog_content = "O seu sangue choverá em Lumópolis!",
  ui_story_7_14_74_dialog_content = "Recarregou, Schummer. Agora a Colossus preta está <color=#FFB400>completa</color>.",
  ui_story_7_14_75_dialog_content = "O momento perfeito, não é? Essas criaturas humildes à nossa frente podem servir como sacrifício para comemorar!",
  ui_story_7_14_76_dialog_content = "Desculpe interromper, mas tem algo que preciso perguntar... Quem é você?",
  ui_story_7_14_77_dialog_content = "Você ainda não sabe?",
  ui_story_7_14_78_dialog_content = "Não você. Estou falando de quem está atrás de você. O poderoso Eclipsita de alto nível.",
  ui_story_7_14_79_dialog_content = "...",
  ui_story_7_14_80_dialog_content = "Você parece mais com um <color=#FFB400>Aurorian</color> do que um Eclipsita.",
  ui_story_7_14_81_dialog_content = "Aurorian?",
  ui_story_7_14_82_dialog_content = "Aquela figura, a aura, o jeito de falar... Minha intuição diz que você não nasceu um Eclipsita.",
  ui_story_7_14_83_dialog_content = "Intuição... Que argumento mais chato.",
  ui_story_7_14_84_dialog_content = "<color=#FFB400>Quem é você</color>? Me diga, preciso saber.",
  ui_story_7_14_85_dialog_content = "Me recuso.",
  ui_story_7_14_86_dialog_content = "<size=45>Me fale! Agora!</size>",
  ui_story_7_14_87_dialog_content = "Por que ela está ficando tão irritada do nada?",
  ui_story_7_14_88_dialog_content = "Novamente, me recuso. Porque...",
  ui_story_7_14_89_dialog_content = "Meu nome foi <color=#FFB400>roubado</color> de mim há muito tempo.",
  ui_story_7_14_90_dialog_content = "...",
  ui_story_7_14_91_dialog_content = "Neste mundo maravilhoso, como uma pessoa sem nome pode viver em <color=#FFB400>Illumina</color>?",
  ui_story_7_14_92_dialog_content = "Você era um membro de Illumina?",
  ui_story_7_14_94_dialog_content = "Sim.",
  ui_story_7_14_95_dialog_content = "Olhe as cicatrizes do rosto. Foram queimadas na minha pele pela Chama Abrasadora. Está vendo?",
  ui_story_7_14_97_dialog_content = "...",
  ui_story_7_14_F3_dialog_content = "O que foi?",
  ui_story_7_14_98_dialog_content = "Te lembra algo?",
  ui_story_7_14_99_dialog_content = "Não é bem uma ideia, é uma confirmação.",
  ui_story_7_14_100_dialog_content = "Você é muito perspicaz. Depois de todos esses anos, sua compreensão é mais impressionante que nunca.",
  ui_story_7_14_101_dialog_content = "Vocês se conhecem, Vivian?",
  ui_story_7_14_102_dialog_content = "Mais que isso, PlayerName...",
  ui_story_7_14_103_dialog_content = "Essa Eclipsita de alto nível já foi <color=#FFB400>minha parceira em Illumina</color>.",
  ui_story_7_14_104_dialog_content = "Por que isso é uma novidade?",
  ui_story_7_14_A8_dialog_content = "E você, <color=#FFB400>Forsakin</color>, sempre me acusando de falar demais, por que está de papo com essas baratas?",
  ui_story_7_14_105_dialog_content = "<color=#FFB400>Forsakin</color>?",
  ui_story_7_14_109_dialog_content = "Só colocando as coisas em dia. Já acabei. Faça o que quiser.",
  ui_story_7_14_110_dialog_content = "Falando nisso, embora a Colossus esteja recarregada, boa parte da energia ainda não está disponível.",
  ui_story_7_14_A9_dialog_content = "Encontre um alvo digno.",
  ui_story_7_14_111_dialog_content = "Aquela cidade ali é perfeita, né?",
  ui_story_7_14_112_dialog_content = "Arrogantes, corruptos, estúpidos, acreditando que o escudo é inquebrável... Destruirei a fé dos Aurorians!",
  ui_story_7_14_113_dialog_content = "Não vou deixar! Lumópolis nunca cairá. Como uma mera Eclipsita poderia...",
  ui_story_7_14_114_dialog_content = "<size=45>Cale-se, Aurorian!</size>",
  ui_story_7_14_115_dialog_content = "Venha, querida Colossus!",
  ui_story_7_14_116_dialog_content = "Com seu corpo gigante e seus olhos vermelhos como sangue, faça-os tremer de medo!",
  ui_story_7_14_117_dialog_content = "Está vendo agora? Colossus Preta... Dragão Preto... Não, esse não é o nome.",
  ui_story_7_14_118_dialog_content = "É isso! Ajoelhem e venerem! Aclamem o poder de... <size=45><color=#FFB400>Aviduz</color></size>!",
  ui_story_7_14_119_dialog_content = "O que é isso, uma Colossus? O que ela fez? O que está acontecendo, PlayerName?",
  ui_story_7_14_120_dialog_content = "Como eu vou saber?",
  ui_story_7_14_121_dialog_content = "A Lúmina está esgotando! Não podemos simplesmente desistir!",
  ui_story_7_14_122_dialog_content = "Não consigo me mover. Vocês conseguem?",
  ui_story_7_14_123_dialog_content = "Se preparem, pessoal. Vou ganhar um pouco de tempo.",
  ui_story_7_14_128_dialog_content = "O ponto fraco dela está atrás de vocês. Corram em direção a ela, pulem direto para baixo e há chance de sobreviverem.",
  ui_story_7_14_129_dialog_content = "Vice, PlayerName, Carleen, vejo vocês em breve.",
  ui_story_7_14_130_dialog_content = "Senhora? Você...?",
  ui_story_7_14_131_dialog_content = "<size=50>Impossível.</size>",
  ui_story_7_14_133_dialog_content = "(O que...)",
  ui_story_7_14_134_dialog_content = "(Aconteceu...)",
  ui_story_8_1_1_1_dialog_content = "O que está olhando, PlayerName?",
  ui_story_8_1_1_2_dialog_content = "Vai se perder se não se atentar!",
  ui_story_8_1_1_3_dialog_content = "Aqui, pegue a minha mão.",
  ui_story_8_1_1_4_dialog_content = "Que cara é essa? Não concordamos em ir para o festival de Lumópolis?",
  ui_story_8_1_1_5_dialog_content = "Olha, lanches! Vamos lá ver o que estão vendendo!",
  ui_story_8_1_1_6_option_content = "Onde estamos?",
  ui_story_8_1_1_7_dialog_content = "Não sabe? Está em Lumópolis!",
  ui_story_8_1_1_8_option_content = "O que houve?",
  ui_story_8_1_1_9_dialog_content = "O que mais? Só tem festival uma vez ao ano, então precisamos nos divertir.",
  ui_story_8_1_1_10_dialog_content = "Qual o problema? Não está me zoando, né?",
  ui_story_8_1_1_11_dialog_content = "Se estiver, vou ficar com raiva. Tipo assim! *Faz bico*",
  ui_story_8_1_1_12_option_content = "Você está estranha, Vice.",
  ui_story_8_1_1_13_dialog_content = "Estou? Sem chance! Ainda sou sua Vice fofinha!",
  ui_story_8_1_1_14_dialog_content = "Não pensa muito, vem logo! Ou então ficarei brava de verdade!",
  ui_story_8_1_1_15_option_content = "Quem é você?",
  ui_story_8_1_1_16_dialog_content = "O quê? Eu sou a Vice! Quem mais eu seria?",
  ui_story_8_1_1_17_dialog_content = "Que interrogatório é esse? Vem aqui, ou vou ficar brava de verdade!",
  ui_story_8_1_1_18_dialog_content = "...",
  ui_story_8_1_1_19_dialog_content = "Que som é esse?",
  ui_story_8_1_1_20_dialog_content = "Você ouviu algo?",
  ui_story_8_1_1_21_dialog_content = "Tem alguma coisa errada, Vice. Não me sinto bem, tipo...",
  ui_story_8_1_1_22_dialog_content = "É coisa da sua cabeça, PlayerName. Comigo você está em segurança, apenas confie em mim.",
  ui_story_8_1_1_23_dialog_content = "Se ainda tiver muitas perguntas, vou responder a todas. Mas, por favor, só pegue a minha mão, tudo bem?",
  ui_story_8_1_1_24_dialog_content = "Vou te contar tudo...",
  ui_story_8_1_1_25_dialog_content = "PlayerName?",
  ui_story_8_1_1_26_dialog_content = "O passado, o futuro, qualquer coisa que quiser saber.",
  ui_story_8_1_1_27_dialog_content = "Vamos em direção ao futuro, juntos!",
  ui_story_8_1_1_28_dialog_content = "Então não me deixe na minha solidão. Fizemos uma promessa, não é?",
  ui_story_8_1_1_29_dialog_content = "Não consegue ouvir isso? Não está ouvindo, PlayerName!",
  ui_story_8_1_1_30_option_content = "Prometo que nunca vou te deixar.",
  ui_story_8_1_1_31_dialog_content = "Estou tão feliz que finalmente entende! Agora nunca mais pode me deixar.",
  ui_story_8_1_1_32_dialog_content = "Largue sua casca, Celestita. Abrace seu verdadeiro poder!",
  ui_story_8_1_1_33_option_content = "Vou embora. Você não é a Vice.",
  ui_story_8_1_1_34_dialog_content = "Espera, volta aqui! Celestita idiota!",
  ui_story_8_1_1_35_dialog_content = "A maioria das pessoas sonha com uma oportunidade assim! Você é idiota. Lamentável e tragicamente idiota!",
  ui_story_8_1_1_36_dialog_content = "Me escuta, você precisa escapar dessa doce e perigosa fantasia...",
  ui_story_8_1_1_37_dialog_content = "Venha, siga Wispy e alcançará a verdade.",
  ui_story_8_1_1_38_dialog_content = "Kiuu!",
  ui_story_8_1_1_39_dialog_content = "(Ai! Por que estou com tanta dor?)",
  ui_story_8_1_1_42_dialog_content = "(O que é isso saindo do meu corpo?)",
  ui_story_8_1_1_43_dialog_content = "(O que é isso? E por quê..)",
  ui_story_8_1_1_44_dialog_content = "*Rugido*",
  ui_story_8_1_1_45_dialog_content = "Kiuu!",
  ui_story_8_1_1_47_dialog_content = "Você é Curie, uma das seguidoras de Vivian.",
  ui_story_8_1_1_48_dialog_content = "Kiuu!!!",
  ui_story_8_1_1_49_dialog_content = "Onde está sua mestra? E onde está Vice?",
  ui_story_8_1_1_50_dialog_content = "Essa coisa saiu do meu corpo? O que diabos é isso?",
  ui_story_8_1_1_51_dialog_content = "Ai, minha cabeça está doendo. Aiai, que dor forte. Será que bati minha cabeça?",
  ui_story_8_1_1_52_dialog_content = "Kiuu!",
  ui_story_8_1_1_53_dialog_content = "Coitadinha da Curie. Como foi que ficou com tantas feridas? Você também foi separada?",
  ui_story_8_1_1_54_dialog_content = "Como será que estão.",
  ui_story_8_1_1_55_dialog_content = "Impossível!",
  ui_story_8_1_1_58_dialog_content = "Ai, ai, ai... Não consigo me lembrar de nada depois disso.",
  ui_story_8_1_1_59_dialog_content = "Como será que Vice e os outros estão?",
  ui_story_8_1_1_60_dialog_content = "PlayerName!",
  ui_story_8_1_1_61_dialog_content = "Vice?",
  ui_story_8_1_1_62_dialog_content = "Shh, fala baixo. Sou eu.",
  ui_story_8_1_1_63_dialog_content = "Você está bem? Esse lugar está cheio de Fluxo Escuro! Eu...",
  ui_story_8_1_1_64_dialog_content = "Eu sei! Estou bem. E você, está com ferimentos? Deixa eu ver!",
  ui_story_8_1_1_65_option_content = "Não me sinto bem.",
  ui_story_8_1_1_66_dialog_content = "Não me sinto normal. Não acho que me feri, mas meu corpo parece pesado...",
  ui_story_8_1_1_67_dialog_content = "Até minha cabeça parece confusa. Que lugar é esse?",
  ui_story_8_1_1_68_dialog_content = "Não se lembra? Estamos dentro de Aviduz, PlayerName.",
  ui_story_8_1_1_69_option_content = "Eu não lembro.",
  ui_story_8_1_1_70_dialog_content = "Eu não lembro... Acabei de acordar. É verdade, eu estava tendo um pesadelo!",
  ui_story_8_1_1_71_dialog_content = "Você estava nele, mas não estava normal. Não, não tinha como ser você.",
  ui_story_8_1_1_F1_dialog_content = "E tinha mais alguém.",
  ui_story_8_1_1_72_dialog_content = "Um sonho? Você sonhou comigo, mas não era eu? Quem era a outra pessoa?",
  ui_story_8_1_1_F2_dialog_content = "Não sei muito bem o que está havendo, desculpe.",
  ui_story_8_1_1_73_dialog_content = "E então? Acordou aqui? Nada mais?",
  ui_story_8_1_1_F3_dialog_content = "Sim, acordei aqui.",
  ui_story_8_1_1_74_dialog_content = "Certo. Pode ser que o Fluxo Escuro tenha afetado sua mente. Afinal, estamos dentro da Aviduz.",
  ui_story_8_1_1_75_option_content = "Onde estamos?",
  ui_story_8_1_1_76_dialog_content = "Estamos dentro da Aviduz, a Colossus.",
  ui_story_8_1_1_77_dialog_content = "É a primeira vez que vejo uma Colossus assim, se é que pode se chamar isso de Colossus.",
  ui_story_8_1_1_78_dialog_content = "Olha! Você pode ver as manchas de Fluxo Escuro em todo lugar. Isso é um parquinho de Eclipsitas.",
  ui_story_8_1_1_79_dialog_content = "Eu encontrei vários deles ao longo do caminho. Espero não ter feito barulho demais.",
  ui_story_8_1_1_80_dialog_content = "Espera aí, você disse...",
  ui_story_8_1_1_81_dialog_content = "Estamos DENTRO de Aviduz?!",
  ui_story_8_1_1_82_dialog_content = "Correto. Descobri que Schummer te arrastou para cá, e então...",
  ui_story_8_1_1_83_dialog_content = "Eu segui ela.",
  ui_story_8_1_1_84_dialog_content = "O quê? Por que seguiria ela até um lugar desse?",
  ui_story_8_1_1_88_dialog_content = "Para te resgatar, óbvio! Você nos empurrou para fora, mas continuou em Soroz. Como eu poderia...",
  ui_story_8_1_1_89_dialog_content = "Espere um momento, o que aconteceu antes?",
  ui_story_8_1_1_90_dialog_content = "Não, nada que justifique algo tão perigoso quanto vir atrás de mim até aqui!",
  ui_story_8_1_1_91_dialog_content = "Eu sei, mas o que eu deveria fazer? Sentar e assistir?",
  ui_story_8_1_1_92_dialog_content = "Achei que talvez estivesse com vida, e que ainda pudesse fazer algo.",
  ui_story_8_1_1_93_dialog_content = "Eu sei como se sente Vice, mas ainda assim...",
  ui_story_8_1_1_94_dialog_content = "Não adianta nada discutir sobre isso, PlayerName. Agora estou aqui!",
  ui_story_8_1_1_95_dialog_content = "Agora precisamos descobrir o que fazer em seguida. Levante!",
  ui_story_8_1_1_96_dialog_content = "Kiuu!",
  ui_story_8_1_1_97_dialog_content = "Curie, me apoie e coloque um pouco de juízo na cabeça dela, por favor?",
  ui_story_8_1_1_98_dialog_content = "Então me fala o que aconteceu antes. Sempre que tento me lembrar, minha cabeça começa a latejar demais.",
  ui_story_8_1_1_99_dialog_content = "Primeiro levante-se! Não podemos simplesmente ficar parados aqui, te conto enquanto andamos.",
  ui_story_8_1_1_100_dialog_content = "A Líder Vivian tinha acabado de dar ordem para retirada, mas então a Schummer...",
  ui_story_8_1_1_101_dialog_content = "Se preparem, pessoal. Vou ganhar um pouco de tempo.",
  ui_story_8_1_1_103_dialog_content = "O ponto fraco dela está atrás de vocês. Corram em direção a ela, pulem direto para baixo e há chance de sobreviverem.",
  ui_story_8_1_1_104_dialog_content = "Vice, PlayerName, Carleen, vejo vocês em breve.",
  ui_story_8_1_1_105_dialog_content = "Senhora, você...?",
  ui_story_8_1_1_106_dialog_content = "Impossível!",
  ui_story_8_1_1_107_dialog_content = "Eu sou sua oponente!!",
  ui_story_8_1_1_108_dialog_content = "Que inesperado. Você até que luta bem apesar de ser um lixo inútil!",
  ui_story_8_1_1_109_dialog_content = "...",
  ui_story_8_1_1_110_dialog_content = "Nesse caso, pelo menos tente deixar as coisas interessantes!",
  ui_story_8_1_1_111_dialog_content = "Onde você pensa que vai?!",
  ui_story_8_1_1_112_dialog_content = "Rápido, pule para fora!",
  ui_story_8_1_1_113_dialog_content = "Dessa altura? Parece que não temos escolha, vamos lá!",
  ui_story_8_1_1_114_dialog_content = "Pegue a minha mão! Vamos pular na mesma hora.",
  ui_story_8_1_1_115_dialog_content = "*Rugido*",
  ui_story_8_1_1_116_dialog_content = "Me solta!",
  ui_story_8_1_1_117_dialog_content = "PlayerName!!",
  ui_story_8_1_1_118_dialog_content = "(Estamos sendo arrastados de volta!!)",
  ui_story_8_1_1_119_dialog_content = "Não tenho mais força... Como vamos...",
  ui_story_8_1_1_120_dialog_content = "...",
  ui_story_8_1_1_121_option_content = "Vai!",
  ui_story_8_1_1_122_dialog_content = "?!",
  ui_story_8_1_1_123_dialog_content = "PlayerName!",
  ui_story_8_1_1_124_dialog_content = "É alto demais! Não vamos conseguir!",
  ui_story_8_1_1_125_dialog_content = "Tente cair com mais estabilidade, Vice! Pelo menos você pode...",
  ui_story_8_1_1_126_dialog_content = "Carleen!",
  ui_story_8_1_1_127_dialog_content = "Peguei você!!",
  ui_story_8_1_1_128_dialog_content = "Raphaela? Por que você... Ai, isso dói!",
  ui_story_8_1_1_129_dialog_content = "Essa aeronave... Você chamou reforços, Carleen?",
  ui_story_8_1_1_130_dialog_content = "É, acho que podemos chamar de reforços, sim. Eu, a grande Raphaela, vim para te libertar desse lugar imundo!",
  ui_story_8_1_1_131_dialog_content = "Parece que cheguei no momento perfeito! Se tivesse chegado alguns segundos depois...",
  ui_story_8_1_1_132_dialog_content = "Eep...",
  ui_story_8_1_1_133_dialog_content = "Que som é esse?",
  ui_story_8_1_1_134_dialog_content = "Hã? Acho que ouvi algo embaixo de mim...",
  ui_story_8_1_1_135_dialog_content = "Kiuu!",
  ui_story_8_1_1_136_dialog_content = "Curie?!",
  ui_story_8_1_1_137_dialog_content = "Me desculpe, não percebi que estava sentando em cima de você!",
  ui_story_8_1_1_138_dialog_content = "Kiuu!",
  ui_story_8_1_1_139_dialog_content = "É seu pet, Vice?",
  ui_story_8_1_1_140_dialog_content = "Não, ela pertence à Líder Vivian.",
  ui_story_8_1_1_141_dialog_content = "Ah é? Onde ela está? Além disso, cadê o Celestita?",
  ui_story_8_1_1_142_dialog_content = "Está...",
  ui_story_8_1_1_143_dialog_content = "...",
  ui_story_8_1_1_144_dialog_content = "Não é hora de falar disso, Raphaela! A situação mudou drasticamente. Vamos sair daqui e reportar ao Senhor da Cidade o mais rápido possível!",
  ui_story_8_1_1_145_dialog_content = "PlayerName nos deu a chance de escapar. Não podemos desperdiçá-la.",
  ui_story_8_1_1_146_dialog_content = "Precisamos achar uma forma de reagir.",
  ui_story_8_1_1_147_dialog_content = "E aí, tem um plano Carleen?",
  ui_story_8_1_1_148_dialog_content = "Sim. A gente volta e convence aquele homem a usar Dâmocles.",
  ui_story_8_1_1_149_dialog_content = "?!",
  ui_story_8_1_1_150_dialog_content = "É a única chance que temos contra Schummer.",
  ui_story_8_1_1_151_dialog_content = "Mas faz mais de dez anos que Dâmocles não é ativado. Ele vai concordar?",
  ui_story_8_1_1_152_dialog_content = "Vou fazê-lo concordar! Apenas Dâmocles pode impedir Aviduz.",
  ui_story_8_1_1_153_dialog_content = "Mas PlayerName...",
  ui_story_8_1_1_154_dialog_content = "Essa questão diz respeito a todos de Lumópolis. Não tenho escolha. Estamos sem opção, Vice.",
  ui_story_8_1_1_155_dialog_content = "...",
  ui_story_8_1_1_156_dialog_content = "Bom, o que está pensando?",
  ui_story_8_1_1_157_dialog_content = "Quer voltar para Soroz?",
  ui_story_8_1_1_158_dialog_content = "Sim.",
  ui_story_8_1_1_159_dialog_content = "Sinto muito, Carleen. Mas não posso deixar PlayerName ou a Líder Vivian para trás.",
  ui_story_8_1_1_160_dialog_content = "Vice...",
  ui_story_8_1_1_161_dialog_content = "Sei como se sente, Carleen. Mas não posso simplesmente abandonar meus amigos! Não vou!",
  ui_story_8_1_1_162_dialog_content = "Calma aí, Vice. É perigoso demais voltar agora!",
  ui_story_8_1_1_164_dialog_content = "Ou você quer que o sacrifício de PlayerName seja em vão?",
  ui_story_8_1_1_165_dialog_content = "Entendo o perigo, Carleen. Vou pensar em algo.",
  ui_story_8_1_1_166_dialog_content = "Tipo o quê? Temos apenas uma aeronave!",
  ui_story_8_1_1_167_dialog_content = "É verdade.",
  ui_story_8_1_1_168_dialog_content = "Você também não tem asas, querida Vice. Por que a gente não...",
  ui_story_8_1_1_169_dialog_content = "...",
  ui_story_8_1_1_170_dialog_content = "Curie, estou contando com você.",
  ui_story_8_1_1_171_dialog_content = "Kiuu?",
  ui_story_8_1_1_172_dialog_content = "Kiuu?!",
  ui_story_8_1_1_173_dialog_content = "Curie e eu poderíamos voltar juntas.",
  ui_story_8_1_1_174_dialog_content = "Tem certeza de que Curie é forte suficiente para te carregar?",
  ui_story_8_1_1_175_dialog_content = "Não sou tão leve como uma pena, mas Curie é muito forte!",
  ui_story_8_1_1_176_dialog_content = "Kiuu!",
  ui_story_8_1_1_177_dialog_content = "Entendi, Curie. Quer voltar e resgatar sua mestra, certo?",
  ui_story_8_1_1_180_dialog_content = "Se estiver partindo, então saia agora. Ainda estamos próximas o bastante para conseguirem.",
  ui_story_8_1_1_181_dialog_content = "Carleen...",
  ui_story_8_1_1_182_dialog_content = "Sei que não posso mudar sua opinião, assim como não pode mudar a minha. Sempre seguimos nossa própria cabeça.",
  ui_story_8_1_1_183_dialog_content = "Lembre-se de manter os pés no chão. A sorte sempre esteve ao seu lado.",
  ui_story_8_1_1_184_dialog_content = "Seja para ativar Soroz ou se arriscando ao salvar Gronru.",
  ui_story_8_1_1_185_dialog_content = "Mas e se a sua sorte acabar?",
  ui_story_8_1_1_186_dialog_content = "Eu acredito em PlayerName. Sei que encontraremos um jeito de escapar, como sempre.",
  ui_story_8_1_1_187_dialog_content = "Acredito que contanto que a gente não desista, podemos fazer um milagre.",
  ui_story_8_1_1_188_dialog_content = "Às vezes não consigo lidar com seu otimismo, Vice.",
  ui_story_8_1_1_189_dialog_content = "Vá. Já que estarei ocupada tentando convencer um velho quadrado, não irei com você dessa vez.",
  ui_story_8_1_1_190_dialog_content = "Cuide do Celestita por mim, Vice!",
  ui_story_8_1_1_191_dialog_content = "Também se cuide, Carleen! Se puder ativar Dâmocles, Schummer ficará surpresa!",
  ui_story_8_1_1_192_dialog_content = "Ela ficará muito mais que isso! Espero que consiga sair a tempo.",
  ui_story_8_1_1_193_dialog_content = "Estaremos de volta antes mesmo de você perceber, Carleen!",
  ui_story_8_1_1_194_dialog_content = "Nos vemos em breve, Vice.",
  ui_story_8_1_1_195_dialog_content = "(Falando em Eclipsiano) Por ali! Derrube aquilo! Rápido!",
  ui_story_8_1_1_196_dialog_content = "(Falando em Eclipsiano) Recupere tudo que for útil! Nossa mestra precisa de mais materiais de construção para concluir a Colossus!",
  ui_story_8_1_1_197_dialog_content = "(Falando em Eclipsiano) Você ouviu isso?!",
  ui_story_8_1_1_198_dialog_content = "Grrr!?",
  ui_story_8_1_1_200_dialog_content = "Não grite, só tem você aqui. Onde estão os outros Eclipsitas? Já saíram de Soroz?",
  ui_story_8_1_1_201_dialog_content = "Nunca te perdoarei por destruir o querido lar de PlayerName dessa forma!",
  ui_story_8_1_1_202_dialog_content = "(Falando em Eclipsiano) Lixo Aurorian... Preciso avisar mestra...",
  ui_story_8_1_1_203_dialog_content = "Desculpe, tenho certeza de que não estava esperando por isso, mas preciso perguntar algo.",
  ui_story_8_1_1_204_dialog_content = "Grrr-ou!!",
  ui_story_8_1_1_205_dialog_content = "Sei que não deve estar entendendo nada que estou dizendo, mas...",
  ui_story_8_1_1_206_dialog_content = "Tem duas pessoas muito importantes, PlayerName e Líder Vivian, e eu preciso saber onde estão.",
  ui_story_8_1_1_207_dialog_content = "(Falando em Eclipsiano) Quer dizer que aquele Celestita é seu amigo? Você já não fugiu? Mulher burra...",
  ui_story_8_1_1_208_dialog_content = "Não consigo te entender. Que perda de tempo.",
  ui_story_8_1_1_209_dialog_content = "Se não consegue falar Universês, que tal usarmos papel e caneta!?",
  ui_story_8_1_1_210_dialog_content = "?",
  ui_story_8_1_1_211_dialog_content = "Vou desenhar...",
  ui_story_8_1_1_212_dialog_content = "Onde está essa pessoa?",
  ui_story_8_1_1_213_dialog_content = "(Falando em Eclipsiano) Sabia, veio aqui por causa do Celestita!",
  ui_story_8_1_1_214_dialog_content = "(Falando em Eclipsiano) Lembro que o Celestita está... Não.",
  ui_story_8_1_1_215_dialog_content = "O que está olhando?",
  ui_story_8_1_1_216_dialog_content = "(Falando em Eclipsiano) Por que eu te contaria, rata nojenta? Se acha que pode destruir os planos da mestra, então...",
  ui_story_8_1_1_217_dialog_content = "Argh!",
  ui_story_8_1_1_218_dialog_content = "Estava olhando na direção de Aviduz?",
  ui_story_8_1_1_219_dialog_content = "Kiuu, kiuu...",
  ui_story_8_1_1_220_dialog_content = "Tudo bem? Ficando sem energia? Deve estar cansada de me carregar até aqui.",
  ui_story_8_1_1_221_dialog_content = "Kiuu!",
  ui_story_8_1_1_222_dialog_content = "Contanto que ainda esteja bem... Sinto muito, Curie, mas preciso contar com você mais uma vez.",
  ui_story_8_1_1_223_dialog_content = "Próxima parada, Aviduz! Lá provavelmente encontraremos PlayerName e Líder Vivian!",
  ui_story_8_1_1_224_dialog_content = "Kiuu?!",
  ui_story_8_1_1_225_dialog_content = "Então foi assim que se infiltrou? Isso funcionou de verdade?",
  ui_story_8_1_1_226_dialog_content = "Pode parecer difícil de acreditar, mas foi a Curie.",
  ui_story_8_1_1_227_dialog_content = "Kiuu...",
  ui_story_8_1_1_228_dialog_content = "Parece que Curie está exausta.",
  ui_story_8_1_1_229_dialog_content = "Está sendo muito pesado para a Curie. Ela vai ganhar uma grande recompensa quando voltarmos!",
  ui_story_8_1_1_230_option_content = "Então vamos sair daqui.",
  ui_story_8_1_1_231_dialog_content = "Kiuu!",
  ui_story_8_1_1_232_dialog_content = "Mas ainda não encontramos a Líder Vivian, PlayerName.",
  ui_story_8_1_1_233_dialog_content = "Se ainda tem algo sobrando, espero que a gente possa ficar mais um pouco.",
  ui_story_8_1_1_234_dialog_content = "E aí podemos fugir todos juntos!",
  ui_story_8_1_1_235_option_content = "Mas não vi a Vivian\nem lugar nenhum.",
  ui_story_8_1_1_236_dialog_content = "Kiuu...",
  ui_story_8_1_1_237_dialog_content = "Acho que ela também acabou sendo presa aqui, vamos achá-la.",
  ui_story_8_1_1_238_dialog_content = "Não importa o que Schummer esteja planejando, não podemos deixar a Líder para trás!",
  ui_story_8_1_1_239_dialog_content = "Já estou me sentindo muito melhor. Vamos nessa!",
  ui_story_8_1_1_240_dialog_content = "Muito bem! Vamos lá!",
  ui_story_8_1_1_241_dialog_content = "Kiuu!",
  ui_story_8_2_1_1_dialog_content = "Desculpe professora, poderia demonstrar mais uma vez?",
  ui_story_8_2_1_2_dialog_content = "Falhei novamente. Acho que não consigo fazer isso.",
  ui_story_8_2_1_3_dialog_content = "Professora... Professora?!",
  ui_story_8_2_1_4_dialog_content = "Ei!",
  ui_story_8_2_1_5_dialog_content = "Está no seu mundinho novamente?",
  ui_story_8_2_1_6_dialog_content = "...",
  ui_story_8_2_1_7_dialog_content = "Se recomponha. Em breve vai mostrar seu valor para aquele Celestita, não vai?",
  ui_story_8_2_1_8_dialog_content = "Chega.",
  ui_story_8_2_1_9_dialog_content = "Não preciso de discursos motivacionais de ninguém, muito menos de você.",
  ui_story_8_2_1_10_dialog_content = "Está bem.",
  ui_story_8_2_1_11_dialog_content = "...",
  ui_story_8_2_1_12_dialog_content = "Não poupei a vida de PlayerName por algo tão banal quanto provar meu valor, Forsakin.",
  ui_story_8_2_1_13_dialog_content = "Hã...",
  ui_story_8_2_1_14_dialog_content = "Mas você não entenderia, mesmo se eu explicasse.",
  ui_story_8_2_1_15_dialog_content = "De qualquer forma, é a mesma coisa de quando você poupou aquela mulher de Illumina.",
  ui_story_8_2_1_16_dialog_content = "Não é a mesma coisa. Eu e você somos completamente diferentes.",
  ui_story_8_2_1_17_dialog_content = "Afinal, não tenho nada a ver com Illumina, mas você é Celestita.",
  ui_story_8_2_1_18_dialog_content = "Quem você está chamando de Celestita?!",
  ui_story_8_2_1_19_dialog_content = "Vai com calma. Essa conversa acabou.",
  ui_story_8_2_1_20_dialog_content = "Você só fala bobagens!",
  ui_story_8_2_1_21_dialog_content = "Tchau.",
  ui_story_8_2_1_22_dialog_content = "E onde você pensa que está indo?",
  ui_story_8_2_1_23_dialog_content = "Já dei o poder que você tem para o Celestita. Acho que em breve vocês poderão se chamar de “companheiros” novamente.",
  ui_story_8_2_1_24_dialog_content = "O que quer dizer? Não pedi para você fazer isso!",
  ui_story_8_2_1_25_dialog_content = "Ela não faz sentido!",
  ui_story_8_2_1_26_dialog_content = "O que diabos ela está fazendo aqui? Desde o dia que nos conhecemos, ela sempre foi assim!",
  ui_story_8_2_1_27_dialog_content = "Se não vai ajudar, não atrapalha. Quando eu estava focando apenas em Lumópolis, ela ainda estava procurando confusão...",
  ui_story_8_2_1_28_dialog_content = "Schummer, eu ofereço minha ajuda sob as ordens da Dama Forsakin...",
  ui_story_8_2_1_29_dialog_content = "Mas cuidado como fala com ela.",
  ui_story_8_2_1_30_dialog_content = "Tsc. Parece que ela não pode apenas deixar isso, não é?",
  ui_story_8_2_1_31_dialog_content = "O lugar está um caos completo...",
  ui_story_8_2_1_32_dialog_content = "Bom, PlayerName? Você conseguiu?",
  ui_story_8_2_1_33_dialog_content = "Sim. Consegui estabelecer uma ligação com essa Colossus, mas não consigo entendê-la.",
  ui_story_8_2_1_F1_dialog_content = "Não, não é que eu não consiga entender.",
  ui_story_8_2_1_34_dialog_content = "É que ela não tem um Modelo Eco próprio. É completamente vazia.",
  ui_story_8_2_1_35_dialog_content = "Cuidado, pode acionar um alarme.",
  ui_story_8_2_1_36_dialog_content = "Não se preocupe, Vice. Sempre tenho cuidado.",
  ui_story_8_2_1_37_dialog_content = "E meus poderes podem evitar que dispare um alarme e manter nossa presença escondida.",
  ui_story_8_2_1_F2_dialog_content = "Suas habilidades psíquicas podem fazer isso?",
  ui_story_8_2_1_F3_dialog_content = "Sim. Depois que aprendi a usar submersão psíquica. Consigo fazer muitas coisas com uma pequena quantidade de energia psíquica.",
  ui_story_8_2_1_38_dialog_content = "Consegue detectar a Líder Vivian?",
  ui_story_8_2_1_F4_dialog_content = "Desculpe, mas eu não ousaria utilizar mais poder do que tenho agora.",
  ui_story_8_2_1_F5_dialog_content = "Estamos na Aviduz, então consigo usar meus poderes diretamente por meio de toque.",
  ui_story_8_2_1_39_dialog_content = "Mas se eu fizer uma sonda extensa, Schummer nos encontrará.",
  ui_story_8_2_1_40_dialog_content = "Entendido. Vamos depender dos nossos próprios olhos para encontrá-la.",
  ui_story_8_2_1_41_dialog_content = "Como está se sentindo? Acha que consegue aguentar a Matéria Escura daqui?",
  ui_story_8_2_1_42_dialog_content = "Estou bem agora. Minha cabeça parou de doer.",
  ui_story_8_2_1_43_dialog_content = "Na verdade, me sinto ainda melhor agora. Como se acordasse após uma longa e boa noite de sono.",
  ui_story_8_2_1_44_dialog_content = "Sério? Que estranho. Lá no Corredor Suspirante você não conseguia aguentar o Fluxo Escuro.",
  ui_story_8_2_1_45_dialog_content = "Kiuu!",
  ui_story_8_2_1_46_dialog_content = "O que está cheirando, Curie?",
  ui_story_8_2_1_47_dialog_content = "Atchim!",
  ui_story_8_2_1_48_dialog_content = "Kiuu...",
  ui_story_8_2_1_49_dialog_content = "O Fluxo Escuro aqui é tão escuro que nem a Curie consegue aguentar.",
  ui_story_8_2_1_50_dialog_content = "Você é devagar demais.",
  ui_story_8_2_1_51_dialog_content = "Quem está aí?",
  ui_story_8_2_1_52_dialog_content = "Você demorou mais que o esperado, o destino não poupa ninguém.",
  ui_story_8_2_1_53_dialog_content = "Venha, Celestita. O que busca está no fim deste corredor.",
  ui_story_8_2_1_54_dialog_content = "Quem é você? Você é Aurorian ou Eclipsita?",
  ui_story_8_2_1_55_dialog_content = "Shh, não importa. Tudo que importa, passará. Aqueles que ardentemente buscam...",
  ui_story_8_2_1_56_dialog_content = "A Verdade.",
  ui_story_8_2_1_57_dialog_content = "Qual o problema, PlayerName? Você tá horrível...",
  ui_story_8_2_1_58_dialog_content = "Acabei de ver algo bizarro.",
  ui_story_8_2_1_59_dialog_content = "Um homem de branco, carregando uma mala. Ele me disse para ir por aquele caminho.",
  ui_story_8_2_1_60_dialog_content = "O quê? Onde ele está?",
  ui_story_8_2_1_F6_dialog_content = "Talvez tenha detectado isso. Ele disse para ir por aquele caminho. Ele parecia de confiança.",
  ui_story_8_2_1_F7_dialog_content = "Mas não ficou claro qual caminho é “aquele caminho”.",
  ui_story_8_2_1_61_dialog_content = "Não tenho familiaridade com o interior de Aviduz, mas considerando os caminhos que percorremos...",
  ui_story_8_2_1_62_dialog_content = "Bom, posso desenhar um mapa simples!",
  ui_story_8_2_1_63_dialog_content = "Por sorte, ainda tenho este papel.",
  ui_story_8_2_1_64_dialog_content = "Que linhas são essas que você desenhou, Vice?",
  ui_story_8_2_1_65_dialog_content = "Ignora isso, não é nada!",
  ui_story_8_2_1_66_dialog_content = "E essas pessoinhas que você desenhou...",
  ui_story_8_2_1_68_dialog_content = "Desenhei para perguntar onde você está!",
  ui_story_8_2_1_F8_dialog_content = "Esse aqui sou eu?",
  ui_story_8_2_1_69_dialog_content = "Eu admito que não é uma obra de arte, mas eu consegui fazer o que tinha que ser feito!",
  ui_story_8_2_1_70_dialog_content = "Enfim, pare de desviar do assunto! Preciso mapear a rota que tomamos enquanto ainda consigo lembrar.",
  ui_story_8_2_1_72_dialog_content = "(Eclipsitas conseguem entender essa imagem?)",
  ui_story_8_2_1_73_dialog_content = "E uma escala aqui, depois...",
  ui_story_8_2_1_74_dialog_content = "Pronto!",
  ui_story_8_2_1_75_dialog_content = "(Não deveria rir da falta de habilidade. Ela se esforçou bastante.)",
  ui_story_8_2_1_76_dialog_content = "Está... excelente! É o sonho de qualquer cartógrafo!",
  ui_story_8_2_1_77_dialog_content = "Vai servir. Só consigo dar conta de coisas simples assim, considerando o tempo que temos.",
  ui_story_8_2_1_78_dialog_content = "Simples! Consigo entender como você é capaz de desenhar figuras tão “boas”, mas também desenha bem mapas?",
  ui_story_8_2_1_79_dialog_content = "Eu te disse, estudei isso em Illumina.",
  ui_story_8_2_1_80_dialog_content = "Além disso, o reparo de Soroz requer esse tipo de conhecimento.",
  ui_story_8_2_1_81_dialog_content = "Kiuu!",
  ui_story_8_2_1_82_dialog_content = "O que houve, Curie?",
  ui_story_8_2_1_83_dialog_content = "Kiuu! kiuu!",
  ui_story_8_2_1_84_dialog_content = "Por aqui? Mas...",
  ui_story_8_2_1_85_dialog_content = "Não é para onde o homem apontou?",
  ui_story_8_2_1_86_dialog_content = "Curie identificou o cheiro de Vivian. PlayerName, vamos lá!",
  ui_story_8_2_1_87_dialog_content = "(Acho que o homem não é um inimigo.)",
  ui_story_8_2_1_88_dialog_content = "Tenho certeza de que haverá muitos Eclipsitas por ali. Vamos eliminá-los o mais rápido possível!",
  ui_story_8_2_1_89_dialog_content = "Prepare-se para lutar!",
  ui_story_8_2_2_1_dialog_content = "<color=#e8d9bb>Cidade Alta, Jardins de Lumópolis</color>",
  ui_story_8_2_2_2_dialog_content = "Você quer ativar...",
  ui_story_8_2_2_3_dialog_content = "Dâmocles?",
  ui_story_8_2_2_5_dialog_content = "Correto. É nossa única solução para o problema atual!",
  ui_story_8_2_2_6_dialog_content = "Você tem noção do que está dizendo, Carleen?",
  ui_story_8_2_2_7_dialog_content = "Para ligar aquela coisa precisamos de uma resolução de três partes, além dos protocolos necessários.",
  ui_story_8_2_2_F1_dialog_content = "Você tem ideia de quanta energia isso consome!?",
  ui_story_8_2_2_8_dialog_content = "Isso vai drenar toda a energia do escudo! Toda Lumópolis vai parar!",
  ui_story_8_2_2_9_dialog_content = "Eu sei.",
  ui_story_8_2_2_10_dialog_content = "Você deve estar louca para considerar isso!",
  ui_story_8_2_2_11_dialog_content = "Otto.",
  ui_story_8_2_2_12_dialog_content = "Hunf.",
  ui_story_8_2_2_13_dialog_content = "Meu Senhor, você não viu do que Schummer e a Colossus Negra são capazes, mas eu vi! Só fui capaz de escapar pulando de cima dela!",
  ui_story_8_2_2_14_dialog_content = "Ninguém pode parar a Colossus Negra totalmente recarregada, ainda mais lutando contra seus aliados!",
  ui_story_8_2_2_15_dialog_content = "Precisamos usar nossa última opção! Nosso escudo não nos protegerá para sempre, suas barreiras irão cair.",
  ui_story_8_2_2_16_dialog_content = "Está ferida?",
  ui_story_8_2_2_17_dialog_content = "O quê?",
  ui_story_8_2_2_18_dialog_content = "Está ferida, Carleen?",
  ui_story_8_2_2_19_dialog_content = "Quando Raphaela te resgatou, ela disse que nunca te viu em um estado assim. Você parecia muito derrotada.",
  ui_story_8_2_2_20_dialog_content = "...",
  ui_story_8_2_2_21_dialog_content = "Agradeço pela preocupação, meu Senhor, mas estou ótima.",
  ui_story_8_2_2_22_dialog_content = "Claro.",
  ui_story_8_2_2_23_dialog_content = "Então, o que os outros acham?",
  ui_story_8_2_2_24_dialog_content = "Já dei minha opinião. Sacrificar Lumópolis é um preço caro demais a se pagar.",
  ui_story_8_2_2_25_dialog_content = "O que a Corte de Justiça acha?",
  ui_story_8_2_2_26_dialog_content = "Eu sigo a resolução. Se a proposta for aceita pelas três partes, assim será.",
  ui_story_8_2_2_27_dialog_content = "Caso contrário, a Corte de Justiça rejeita a ideia, qualquer que seja o proponente.",
  ui_story_8_2_2_28_dialog_content = "Muito bem. Vamos realizar um conselho breve para tratar dessa questão.",
  ui_story_8_2_2_29_dialog_content = "Otto, como representante do Conselho Ancião, tenho certeza de que irá vetar a proposta.",
  ui_story_8_2_2_30_dialog_content = "É claro.",
  ui_story_8_2_2_31_dialog_content = "Irridon, como Juíza Chefe da Corte de Justiça, qual é sua decisão?",
  ui_story_8_2_2_32_dialog_content = "Eu me abstenho.",
  ui_story_8_2_2_33_dialog_content = "Tá bem.",
  ui_story_8_2_2_34_dialog_content = "Por fim, eu, Schwartz, o Senhor da Cidade de Lumópolis e representante das famílias nobres...",
  ui_story_8_2_2_35_dialog_content = "Por meio deste, veto a proposta.",
  ui_story_8_2_2_36_dialog_content = "...!!",
  ui_story_8_2_2_37_dialog_content = "Dois votos contra, uma abstenção. A Corte de Justiça não agirá de acordo com esta proposta.",
  ui_story_8_2_2_38_dialog_content = "Seu pai realmente entende a importância de proteger Lumópolis, Carleen.",
  ui_story_8_2_2_39_dialog_content = "Que palhaçada! Quem diria que a “resolução de três partes” poderia começar e terminar tão casualmente!",
  ui_story_8_2_2_40_dialog_content = "Em tempos de crise, decisões não devem passar por processos fixos. Desde que a Corte de Justiça esteja presente e reconheça os votos, é tão válido quanto.",
  ui_story_8_2_2_41_dialog_content = "Agora, por favor, respeite nossa decisão Carleen.",
  ui_story_8_2_2_42_dialog_content = "Mas...",
  ui_story_8_2_2_43_dialog_content = "Ouviu isso? Temos que usar toda a energia para ligar isso, até desativar o escudo.",
  ui_story_8_2_2_44_dialog_content = "É basicamente suicídio! Agora, pelo menos ainda temos o escudo.",
  ui_story_8_2_2_45_dialog_content = "Honestamente, achei que a filha do Senhor da Cidade fosse mais inteligente.",
  ui_story_8_2_2_46_dialog_content = "...",
  ui_story_8_2_2_47_dialog_content = "Carleen.",
  ui_story_8_2_2_48_dialog_content = "...",
  ui_story_8_2_2_49_dialog_content = "Erga a cabeça e olhe bem, Carleen de Schwartz!",
  ui_story_8_2_2_50_dialog_content = "Esta é Lumópolis! E não um bando perambulante de aventureiros, voando por aí em uma Colossus!",
  ui_story_8_2_2_51_dialog_content = "Esta cidade não precisa dessas noções caprichosas, entendeu?",
  ui_story_8_2_2_52_dialog_content = "...",
  ui_story_8_2_2_53_dialog_content = "Responda à minha pergunta! Você entendeu?!",
  ui_story_8_2_2_54_dialog_content = "Sim, meu Senhor.",
  ui_story_8_2_2_55_dialog_content = "Até termos todas as informações sobre a situação, manter nossos escudos é a nossa melhor estratégia. Já sobre ativar Dâmocles...",
  ui_story_8_2_2_56_dialog_content = "Está totalmente fora de questão.",
  ui_story_8_2_2_57_dialog_content = "Tudo cairá em ruínas e não conseguiremos impedir isso! Carleen, você não mudou nada desde a infância. Não aprendeu nada!",
  ui_story_8_2_2_58_dialog_content = "...?",
  ui_story_8_2_2_59_dialog_content = "Quando caiu da sua casa na árvore tentando salvar um gato, achei que tivesse sido o ápice da sua tolice.",
  ui_story_8_2_2_60_dialog_content = "Mas agora está claro que você não amadureceu nada!",
  ui_story_8_2_2_61_dialog_content = "(Casa na árvore...?)",
  ui_story_8_2_2_62_dialog_content = "Mesmo que tenha salvado aquele gato e tomado a decisão certa, que diferença fez?",
  ui_story_8_2_2_63_dialog_content = "Valeu a pena ir contra o julgamento dos outros e quebrar a sua perna por causa da vida de um gato?",
  ui_story_8_2_2_64_dialog_content = "(...?)",
  ui_story_8_2_2_65_dialog_content = "Eu te fiz uma pergunta! Valeu a pena?!",
  ui_story_8_2_2_66_dialog_content = "O que significa isso, Schwartz? Por que está mencionando histórias de família aqui?",
  ui_story_8_2_2_67_dialog_content = "Eu falei com você, Otto Troy?",
  ui_story_8_2_2_68_dialog_content = "...",
  ui_story_8_2_2_69_dialog_content = "Sim.",
  ui_story_8_2_2_70_dialog_content = "Acho que valeu a pena, pai.",
  ui_story_8_2_2_71_dialog_content = "Entendi. Então não há esperanças para você, Carleen.",
  ui_story_8_2_2_72_dialog_content = "Vá, se tranque na torre de marfim, assim como aquele seu gato.",
  ui_story_8_2_2_73_dialog_content = "...",
  ui_story_8_2_2_74_dialog_content = "Uau, as palavras do Senhor são afiadas como uma lâmina...",
  ui_story_8_2_2_75_dialog_content = "Mas qual foi o sentido de relembrar o passado? É bem peculiar, além de ser meio bizarro.",
  ui_story_8_2_2_77_dialog_content = "Por que está sorrindo, Carleen? Está ficando ainda mais bizarro.",
  ui_story_8_2_2_78_dialog_content = "Porque eu acho que entendi o que ele estava querendo me dizer.",
  ui_story_8_2_2_79_dialog_content = "Hã?",
  ui_story_8_2_2_80_dialog_content = "A casa na árvore, o gato. Isso aconteceu no passado.",
  ui_story_8_2_2_81_dialog_content = "Mas...",
  ui_story_8_2_2_82_dialog_content = "Eu não consegui salvar o gato.",
  ui_story_8_2_2_83_dialog_content = "O Senhor da Cidade se confundiu? Ou é...",
  ui_story_8_2_2_84_dialog_content = "É possível que...",
  ui_story_8_2_2_85_dialog_content = "Que o Senhor da Cidade esteja ficando caduco?",
  ui_story_8_2_2_86_dialog_content = "Você não entendeu, mas tudo bem. Apenas me siga, precisamos ir para um lugar específico.",
  ui_story_8_2_2_87_dialog_content = "Muito bem! Para onde?",
  ui_story_8_2_2_88_dialog_content = "...",
  ui_story_8_2_2_89_dialog_content = "Para a Sala de Controle do Dâmocles.",
  ui_story_8_3_1_1_dialog_content = "<color=#e8d9bb>Dentro de Aviduz</color>",
  ui_story_8_3_1_2_dialog_content = "Heehee! Heehee♪",
  ui_story_8_3_1_3_dialog_content = "Desculpe, me distraí um pouco.",
  ui_story_8_3_1_4_dialog_content = "Venha, vamos continuar por aqui! Essa também é a minha primeira vez aqui.",
  ui_story_8_3_1_5_dialog_content = "Kiuu!",
  ui_story_8_3_1_6_dialog_content = "(Curie pode seguir o cheiro de Vivian. Se ela acha que devemos ir nessa direção...)",
  ui_story_8_3_1_7_dialog_content = "Continue. Esse deve ser o caminho certo.",
  ui_story_8_3_1_8_dialog_content = "...",
  ui_story_8_3_1_9_dialog_content = "Qual o problema? Por que está me olhando assim?",
  ui_story_8_3_1_10_dialog_content = "Tem certeza de que está bem? Mal consigo aguentar o Fluxo Escuro daqui, mas você está bem?",
  ui_story_8_3_1_11_dialog_content = "Ah, estou bem, de verdade!",
  ui_story_8_3_1_12_dialog_content = "É estranho, mas o Fluxo Escuro daqui quase não me afeta. Pelo contrário, eu acho que...",
  ui_story_8_3_1_13_dialog_content = "Até que tem um cheiro bom.",
  ui_story_8_3_1_14_dialog_content = "Hã?",
  ui_story_8_3_1_15_dialog_content = "Apesar da minha pele estar coçando um pouco. Acha que é uma alergia?",
  ui_story_8_3_1_16_dialog_content = "Coçando? Deixa eu ver.",
  ui_story_8_3_1_17_dialog_content = "Está tudo bem, é mais nas minhas costas. Se puder coçar para mim...",
  ui_story_8_3_1_18_dialog_content = "Mas o mais importante...",
  ui_story_8_3_1_19_option_content = "Não estava se sentindo muito bem,\nnão é? Vice?",
  ui_story_8_3_1_20_dialog_content = "Sempre colocando as pessoas em primeiro lugar, né?",
  ui_story_8_3_1_21_dialog_content = "Estou bem. Isso está difícil, mas nada pior do que quando estava nas mãos de Schummer.",
  ui_story_8_3_1_22_dialog_content = "Cresci muito desde então, PlayerName.",
  ui_story_8_3_1_23_dialog_content = "Eu só espero que a gente possa superar qualquer coisa que entre no nosso caminho!",
  ui_story_8_3_1_24_dialog_content = "Claro que podemos. Não vamos parar até derrotar Schummer!",
  ui_story_8_3_1_25_dialog_content = "É assim que se fala, PlayerName!",
  ui_story_8_3_1_26_option_content = "Será que a Carleen está bem?",
  ui_story_8_3_1_27_dialog_content = "Ela já deve ter voltado para Lumópolis.",
  ui_story_8_3_1_28_dialog_content = "Ela deve estar lutando contra Schummer da maneira dela, sei disso.",
  ui_story_8_3_1_29_dialog_content = "Então, o que é Dâmocles? É algum tipo de arma superpoderosa?",
  ui_story_8_3_1_30_dialog_content = "Eu ainda não vi, mas ouvi dizer sobre seu poder quando estudava lá.",
  ui_story_8_3_1_31_dialog_content = "De acordo com todo mundo, é a estância mais devastadora, usada apenas em últimas circunstâncias.",
  ui_story_8_3_1_32_dialog_content = "Parece que você também não sabe muito bem o que é.",
  ui_story_8_3_1_33_option_content = "Onde está a Líder Vivian?",
  ui_story_8_3_1_34_dialog_content = "Não tenho certeza, mas julgando pela reação de Curie, ela deve estar logo em frente!",
  ui_story_8_3_1_35_dialog_content = "Com certeza Curie nos levará até Vivian!",
  ui_story_8_3_1_36_dialog_content = "Se não fosse por Vivian, talvez nem tivéssemos chance de escapar.",
  ui_story_8_3_1_37_dialog_content = "Você também fez muito por nós, PlayerName. E no fim, até tomou uma decisão dessas.",
  ui_story_8_3_1_38_dialog_content = "Quando eu empurrei vocês duas para fora?",
  ui_story_8_3_1_39_dialog_content = "Talvez tivesse sido apenas um tipo de instinto, uma reação do subconsciente. Eu quase esqueci o que aconteceu.",
  ui_story_8_3_1_40_dialog_content = "De qualquer forma, espero que nunca mais faça algo assim.",
  ui_story_8_3_1_41_dialog_content = "Você sempre age sem pensar duas vezes, como naquela vez comigo e Gronru...",
  ui_story_8_3_1_42_dialog_content = "Kiuu!!!",
  ui_story_8_3_1_43_dialog_content = "Desculpe, Curie está com pressa. Venha, vamos seguir o ritmo!",
  ui_story_8_3_1_44_dialog_content = "PlayerName, você deveria tomar mais cuidado com seu bem estar físico.",
  ui_story_8_3_1_46_dialog_content = "Entendido! Não esquenta comigo!",
  ui_story_8_6_1_1_dialog_content = "Tão claro...",
  ui_story_8_6_1_3_option_content = "Não! Preciso me esconder!",
  ui_story_8_6_1_4_dialog_content = "PlayerName? O que está fazendo aí no canto?",
  ui_story_8_6_1_5_dialog_content = "O que está fazendo? Vem aqui!",
  ui_story_8_6_1_6_dialog_content = "Kiuu!",
  ui_story_8_6_1_7_dialog_content = "Desculpe! É que está muito claro, senti tontura por um segundo.",
  ui_story_8_6_1_8_dialog_content = "Claro? É apenas uma sala normal.",
  ui_story_8_6_1_9_dialog_content = "Não consegue aguentar nem isso?",
  ui_story_8_6_1_10_dialog_content = "Não tenho certeza. Acho que meus olhos estão se ajustando.",
  ui_story_8_6_1_11_option_content = "Céus, a coceira...",
  ui_story_8_6_1_12_dialog_content = "Então agora seus olhos estão de boa, mas as costas estão coçando de novo?",
  ui_story_8_6_1_13_dialog_content = "Sim. Acha que preciso ir ao médico?",
  ui_story_8_6_1_14_dialog_content = "Vamos dar uma pausa. Não há ninguém aqui, então podemos descansar um pouco.",
  ui_story_8_6_1_15_dialog_content = "Kiuu!",
  ui_story_8_6_1_16_dialog_content = "Onde você tá indo, Curie?",
  ui_story_8_6_1_17_dialog_content = "Kiuu! kiuu!",
  ui_story_8_6_1_18_dialog_content = "É a Vivian? Ela está aqui em algum lugar?",
  ui_story_8_6_1_19_dialog_content = "Kiuu! Kiuu! Kiuu!",
  ui_story_8_6_1_20_dialog_content = "Vamos dar um jeito de abrir a porta, Curie! Não se desespere! Se nos acharem...",
  ui_story_8_6_1_21_dialog_content = "(Esse cheiro... Será que...?)",
  ui_story_8_6_1_22_dialog_content = "Cuidado, Vice!!",
  ui_story_8_6_1_23_dialog_content = "Grrr!",
  ui_story_8_6_1_24_dialog_content = "Estão indo em sua direção!",
  ui_story_8_6_1_25_dialog_content = "Essa foi boa! Ainda tem mais alguns, mas não podemos deixar outros Eclipsitas em alerta!",
  ui_story_8_6_1_26_dialog_content = "Se livre do resto!",
  ui_story_8_6_1_27_dialog_content = "Deixa comigo, vou acabar com isso bem rápido!",
  ui_story_8_6_2_1_dialog_content = "Ótimo, não chamamos atenção.",
  ui_story_8_6_2_2_dialog_content = "Será que algum deles conseguiu escapar?",
  ui_story_8_6_2_3_dialog_content = "Cuidado, atrás de você!",
  ui_story_8_6_2_4_dialog_content = "Grrr-ou!!",
  ui_story_8_6_2_5_dialog_content = "(Ele passou direto por mim?!)",
  ui_story_8_6_2_6_dialog_content = "Ufa. Parece que o Fluxo Escuro está realmente me afetando. Quase deixei um escapar.",
  ui_story_8_6_2_7_dialog_content = "Uhm, Vice...",
  ui_story_8_6_2_8_dialog_content = "Aquele Eclipsita passou direto por mim. Parece que nem me notou!",
  ui_story_8_6_2_9_dialog_content = "Também percebi isso, e não foi só agora. Parece que estão cada vez menos interessados em você.",
  ui_story_8_6_2_10_dialog_content = "É como se você...",
  ui_story_8_6_2_11_dialog_content = "Não fosse um inimigo para eles.",
  ui_story_8_6_2_12_dialog_content = "...",
  ui_story_8_6_2_13_dialog_content = "Mas por quê?",
  ui_story_8_6_2_14_dialog_content = "Não tenho certeza. Está bem, PlayerName? Está sentindo algum desconforto?",
  ui_story_8_6_2_15_dialog_content = "Eu não sei, Vice.",
  ui_story_8_6_2_16_dialog_content = "Kiuu!",
  ui_story_8_6_2_17_dialog_content = "Eu sei Curie, mas PlayerName...",
  ui_story_8_6_2_18_dialog_content = "Estou bem. Se a Líder Vivian está aqui, resgatá-la é nossa prioridade!",
  ui_story_8_7_1_A1_dialog_content = "Mãe? Pai?",
  ui_story_8_7_1_A2_dialog_content = "A cidade não caiu? Estou muito feliz que vocês estão bem.",
  ui_story_8_7_1_1_dialog_content = "Isso, apenas aceite. Torne seus doces sonhos realidade.",
  ui_story_8_7_1_2_dialog_content = "Branco e puro, marcado com o símbolo da origem. (Falando em Eclipsiano) Presente da mãe.",
  ui_story_8_7_1_3_dialog_content = "Ele desbloqueia o potencial escondido por trás de sua casca física, reunindo-o para criar um poder incomparável.",
  ui_story_8_7_1_4_dialog_content = "E o mais importante, te traz para o nosso lado, como um de nós.",
  ui_story_8_7_1_5_dialog_content = "Rápido, venha para o templo da nossa origem...",
  ui_story_8_7_1_6_dialog_content = "Não me importa o que você tem. Saia de perto dela, Eclipsita!",
  ui_story_8_7_1_7_dialog_content = "Aurorian? Quando foi que você chegou?",
  ui_story_8_7_1_8_dialog_content = "Pode me ouvir, senhora?",
  ui_story_8_7_1_9_dialog_content = "Hum...",
  ui_story_8_7_1_10_dialog_content = "Graças aos deuses, você está viva!",
  ui_story_8_7_1_11_dialog_content = "Seus companheiros, fazendo de tudo para te resgatar.",
  ui_story_8_7_1_12_dialog_content = "Ou eles estão atendendo ao chamado do Eclipse?",
  ui_story_8_7_1_A3_dialog_content = "Eu sou um Queda Sol, e é um prazer ser Guia de vocês.",
  ui_story_8_7_1_13_dialog_content = "“Chamado do Eclipse”? Se for um convite para me transformar em um de seus Eclipsitas horrendos, eu recuso!",
  ui_story_8_7_1_14_dialog_content = "(Falando em Eclipsiano) Você já devia ter se curvado, Celestita!",
  ui_story_8_7_1_15_dialog_content = "Não consigo te entender. Não fala mesmo Universês?",
  ui_story_8_7_1_16_dialog_content = "Por que a mestra não nos avisou? Nenhum alerta foi enviado. O que você fez?",
  ui_story_8_7_1_17_dialog_content = "Esse é o meu poder, Eclipsita. Sou capaz de estabelecer uma conexão mental com Aviduz, até certo ponto. Entendeu?",
  ui_story_8_7_1_18_dialog_content = "Contanto que não façamos muito barulho, já é o bastante para ficarmos escondidos e cancelar alarmes.",
  ui_story_8_7_1_19_dialog_content = "Um desdobramento inesperado, mas não importa. Se seu cheiro for uma indicação...",
  ui_story_8_7_1_20_dialog_content = "Em breve se tornará um de nós, Celestita.",
  ui_story_8_7_1_21_dialog_content = "Como assim?",
  ui_story_8_7_1_F1_dialog_content = "PlayerName, não deixe isso mexer com sua cabeça!",
  ui_story_8_7_1_22_dialog_content = "O que estavam fazendo com Vivian? O que é aquele negócio brilhante?",
  ui_story_8_7_1_23_dialog_content = "(Falando em Eclipsiano) Uma pergunta sem fundamento.",
  ui_story_8_7_1_24_dialog_content = "Não teste a minha paciência, Eclipsita! Não estou com tempo para joguinhos!",
  ui_story_8_7_1_25_dialog_content = "É um presente! Um presente da Mãe!",
  ui_story_8_7_1_26_dialog_content = "Nossa mestra passou por muita dor para fazer isso. Ela poderia ter te esmagado em um piscar de olhos, mas te deixou ir por uma razão.",
  ui_story_8_7_1_27_dialog_content = "Ela até te convidou até aqui graciosamente e te abençoou com um poder recém-descoberto.",
  ui_story_8_7_1_28_dialog_content = "É uma honra! A maior de todas!!",
  ui_story_8_7_1_29_dialog_content = "“Presente da mãe”? Do que está falando?",
  ui_story_8_7_1_30_dialog_content = "Chega de perguntas! Em breve você verá.",
  ui_story_8_7_1_31_dialog_content = "Não me diga que...",
  ui_story_8_7_1_32_dialog_content = "Não o ouça! Ainda há tempo. Vamos derrotá-los!",
  ui_story_8_7_1_33_dialog_content = "Você de novo! Onde está?",
  ui_story_8_7_1_34_dialog_content = "E isso importa? Eu poderia estar bem atrás de você.",
  ui_story_8_7_1_35_dialog_content = "Você! Se quiser continuar como Celestita, faça como eu disser! Termine com eles, rápido!",
  ui_story_8_7_1_36_dialog_content = "(Falando em Eclipsiano) Estremeçam com o que está diante de vocês. Descartem sua ignorância vergonhosa!",
  ui_story_8_7_1_37_dialog_content = "Argh!",
  ui_story_8_7_1_38_dialog_content = "Algo está se mexendo no meu corpo, Vice! É algum tipo de poder...",
  ui_story_8_7_1_39_dialog_content = "Algum tipo de energia...",
  ui_story_8_7_1_40_dialog_content = "Mantenha a calma e o foco, PlayerName!",
  ui_story_8_7_1_41_dialog_content = "Argh! Minha cabeça! Parece que está se partindo em duas!",
  ui_story_8_7_1_43_dialog_content = "É muito forte! Você precisa sair dessa, PlayerName!",
  ui_story_8_7_1_44_option_content = "Eu sei, preciso manter a consciência...",
  ui_story_8_7_1_45_dialog_content = "É tarde demais. Nosso plano está concluído.",
  ui_story_8_7_1_46_dialog_content = "A Semente criou raízes e começou a brotar. Consigo ouvir seus uivos.",
  ui_story_8_7_1_47_dialog_content = "Uma nova alma preciosa para a Mãe!",
  ui_story_8_7_1_48_option_content = "Mantenha a consciência...",
  ui_story_8_7_1_49_dialog_content = "Kiuu!!!",
  ui_story_8_7_1_51_dialog_content = "Vamos lá, Curie!",
  ui_story_8_7_1_52_dialog_content = "Que pena! Sem o Celestita você não é nada!",
  ui_story_8_7_1_53_dialog_content = "Argh!",
  ui_story_8_7_1_54_dialog_content = "PlayerName...",
  ui_story_8_7_1_55_dialog_content = "O que está fazendo aqui?",
  ui_story_8_7_1_56_dialog_content = "Não deveria perder assim!",
  ui_story_8_7_1_57_dialog_content = "Você é um Celestita. Ninguém pode te controlar!",
  ui_story_8_7_1_58_option_content = "(Mantenha a consciência!)",
  ui_story_8_7_1_59_dialog_content = "...?",
  ui_story_8_7_1_60_dialog_content = "Essa foi por pouco, quase perdi o controle.",
  ui_story_8_7_1_61_dialog_content = "Você parou a transformação!?",
  ui_story_8_7_1_62_dialog_content = "Shh, cale a boca!",
  ui_story_8_7_1_63_dialog_content = "Você não se calou esse tempo todo, e está me dando uma grande dor de cabeça.",
  ui_story_8_7_1_64_dialog_content = "Não, não pode ser! Como você resistiu à Semente?",
  ui_story_8_7_1_65_dialog_content = "Sei, sei, sei... Já chega.",
  ui_story_8_7_1_66_dialog_content = "Você faz tanto barulho que Schummer poderia nos ouvir.",
  ui_story_8_7_1_67_dialog_content = "Embora ache que você pode gritar o quanto quiser agora. Eu restabeleci a conexão mental com Aviduz.",
  ui_story_8_7_1_F2_dialog_content = "Estou controlando a Colossus, e deixei essa sala totalmente à prova de som.",
  ui_story_8_7_1_68_dialog_content = "Seu choro não chegará aos ouvidos da suposta Mãe.",
  ui_story_8_7_1_69_dialog_content = "Estou feliz que você voltou ao normal, PlayerName.",
  ui_story_8_7_1_70_dialog_content = "Estou bem agora. Desculpe por te deixar sozinha com esse negócio.",
  ui_story_8_7_1_71_dialog_content = "Minha cabeça está começando a doer de novo, mas acho que consigo aguentar por um tempo.",
  ui_story_8_7_1_73_dialog_content = "Tolos mal-agradecidos! Profanadores dos presentes da Mãe! Só há um lugar para lixos como vocês!",
  ui_story_8_7_1_74_dialog_content = "Uma hora ou outra, você se TORNARÁ um de nós!!",
  ui_story_8_7_1_75_dialog_content = "Faz esse negócio ficar quieto, Vice.",
  ui_story_8_7_1_76_dialog_content = "A Líder Vivian está esperando por nós.",
  ui_story_8_7_1_77_dialog_content = "Certo!",
  ui_story_8_7_2_1_dialog_content = "Senhora!",
  ui_story_8_7_2_2_dialog_content = "Kiuu! kiuu!",
  ui_story_8_7_2_4_dialog_content = "Hmm...",
  ui_story_8_7_2_5_dialog_content = "Senhora, você está péssima. Sinto muito, viemos o mais rápido possível.",
  ui_story_8_7_2_6_dialog_content = "Talvez você devesse se preocupar consigo antes de se preocupar com os outros.",
  ui_story_8_7_2_7_dialog_content = "Quem está aí?",
  ui_story_8_7_2_8_dialog_content = "É você! Vice, já vi ele antes. Ele é o homem que me mostrou o caminho.",
  ui_story_8_7_2_9_dialog_content = "O homem com a mala branca que você mencionou?",
  ui_story_8_7_2_10_dialog_content = "Não sou seu inimigo. Como podem ver, sou Aurorian.",
  ui_story_8_7_2_11_dialog_content = "Podem me chamar de Faust. Sou servo da Verdade.",
  ui_story_8_7_2_12_dialog_content = "A Verdade? Por que isso parece suspeito?",
  ui_story_8_7_2_13_dialog_content = "A Verdade é o princípio eterno e imutável da ordem, e a lei de todas as coisas. Não se preocupem. Estou aqui para ajudar.",
  ui_story_8_7_2_14_dialog_content = "Essa introdução não nos ajudou a entender quem você é.",
  ui_story_8_7_2_15_dialog_content = "Isso não importa agora. Foque na sua mente...",
  ui_story_8_7_2_16_dialog_content = "A Semente dentro de você está começando a brotar.",
  ui_story_8_7_2_17_dialog_content = "Que Semente é essa que todo mundo está falando?",
  ui_story_8_7_2_18_dialog_content = "Vou explicar depois. Precisamos lidar com isso agora.",
  ui_story_8_7_2_19_dialog_content = "Por favor, tire suas roupas, PlayerName.",
  ui_story_8_7_2_20_dialog_content = "O quê?",
  ui_story_8_7_2_21_dialog_content = "Agora não é hora de timidez. Por favor, faça o que eu digo.",
  ui_story_8_7_2_22_dialog_content = "Está com sensações estranhas pelo seu corpo?",
  ui_story_8_7_2_23_dialog_content = "Assim que você disse isso, minhas costas voltaram a coçar.",
  ui_story_8_7_2_24_dialog_content = "Então está nas suas costas.",
  ui_story_8_7_2_25_dialog_content = "Confie em mim, eu posso te ajudar.",
  ui_story_8_7_2_26_option_content = "Tudo bem, vou tirar a roupa.",
  ui_story_8_7_2_27_dialog_content = "...",
  ui_story_8_7_2_28_dialog_content = "A roupa debaixo também.",
  ui_story_8_7_2_29_dialog_content = "É para eu me virar, PlayerName?",
  ui_story_8_7_2_30_dialog_content = "Não é nada estranho, só as costas. Por favor, não demore muito.",
  ui_story_8_7_2_31_option_content = "Tudo bem, vou tirar a roupa...",
  ui_story_8_7_2_32_dialog_content = "Bom...",
  ui_story_8_7_2_33_dialog_content = "Eu sabia.",
  ui_story_8_7_2_34_dialog_content = "O quê? O que tem nas minhas costas?",
  ui_story_8_7_2_35_dialog_content = "Para conseguir manter a consciência sob essas condições, ou você é muito forte, ou muito devagar.",
  ui_story_8_7_2_36_dialog_content = "Me diga o que está acontecendo!",
  ui_story_8_7_2_37_dialog_content = "Consegue tirar isso, Senhorita Vice?",
  ui_story_8_7_2_38_dialog_content = "Está quase debaixo da pele, mas como ainda dá para ver, vamos ao trabalho. Sem necessidade de procedimentos delicados.",
  ui_story_8_7_2_39_dialog_content = "Espera aí, eu nunca te disse o meu nome.",
  ui_story_8_7_2_40_dialog_content = "Verdade, mas isso é irrelevante. Ainda mais agora.",
  ui_story_8_7_2_41_dialog_content = "Está sentindo alguma hostilidade vindo de mim?",
  ui_story_8_7_2_42_dialog_content = "...",
  ui_story_8_7_2_43_dialog_content = "Muito bem. Devo conseguir tirar essa coisa, sem problemas.",
  ui_story_8_7_2_44_dialog_content = "Ei! Alguém poderia me dizer o que está acontecendo?",
  ui_story_8_7_2_45_dialog_content = "Pare de se contorcer!",
  ui_story_8_7_2_46_dialog_content = "É você, Vice.",
  ui_story_8_7_2_47_dialog_content = "Isso vai doer um pouco, PlayerName.",
  ui_story_8_7_2_48_dialog_content = "Ai!",
  ui_story_8_7_2_50_dialog_content = "(Dói demais, nem consigo conversar! Você chama isso de \"um pouco”?)",
  ui_story_8_7_2_51_dialog_content = "Volte, Vice! Não se aproxime demais...",
  ui_story_8_7_2_52_dialog_content = "Essa coisa com certeza é perigosa, mas também é fascinante.",
  ui_story_8_7_2_53_option_content = "O que diabos é isso?",
  ui_story_8_7_2_54_dialog_content = "Uma Semente, de acordo com os Eclipsitas.",
  ui_story_8_7_2_55_dialog_content = "É conhecido por vários nomes: “A Origem do Poder”, “Beijo Materno”, “A Marca da Acensão”, e por aí vai.",
  ui_story_8_7_2_56_dialog_content = "Independentemente de seus apelidos, uma coisa é certa, os Eclipsitas o usam para receber poderes extraordinários e únicos.",
  ui_story_8_7_2_57_dialog_content = "E o mais importante, ele pode corromper e tornar seu hospedeiro em Eclipsita.",
  ui_story_8_7_2_58_dialog_content = "Corromper... É isso que aconteceu com o Gertzurde?",
  ui_story_8_7_2_59_dialog_content = "E até mesmo Schummer?",
  ui_story_8_7_2_60_dialog_content = "Não tenho certeza de quem está falando, mas se são seres da Luz que podem usar o poder da Escuridão...",
  ui_story_8_7_2_61_dialog_content = "A Semente deve ter crescido raízes neles.",
  ui_story_8_7_2_62_option_content = "Então você me curou?",
  ui_story_8_7_2_63_dialog_content = "Podemos dizer que sim. Mas se não fosse por sua força de vontade enorme, já teria se transformado muito antes de eu chegar.",
  ui_story_8_7_2_64_dialog_content = "Além disso, a Semente não é tanto uma doença, mas uma consciência.",
  ui_story_8_7_2_65_dialog_content = "Como está se sentindo agora?",
  ui_story_8_7_2_66_dialog_content = "Deve se sentir muito melhor agora que...",
  ui_story_8_7_2_67_dialog_content = "Não, ainda não me sinto tão bem.",
  ui_story_8_7_2_68_dialog_content = "O quê?",
  ui_story_8_7_2_69_dialog_content = "Sinto como se me faltasse ar e eu não conseguisse respirar. Meu peito está apertado, minha garganta também. Ainda não consigo enxergar bem.",
  ui_story_8_7_2_70_dialog_content = "Isso é normal.",
  ui_story_8_7_2_71_dialog_content = "O Fluxo Escuro neste lugar é sufocantemente intenso. É normal que um Celestita como você tenha esse tipo de reação.",
  ui_story_8_7_2_72_dialog_content = "Antes não estava te afetando porque a Semente estava te transformando em Eclipsita. Entende isso agora?",
  ui_story_8_7_2_73_dialog_content = "Entendo... *tosse*",
  ui_story_8_7_2_74_dialog_content = "Isso é perigoso demais. Temos que destruir essa coisa!",
  ui_story_8_7_2_75_dialog_content = "Espere, Senhorita Vice.",
  ui_story_8_7_2_76_dialog_content = "Esta Semente é um veneno para muitos, mas um tesouro para outros... Como eu.",
  ui_story_8_7_2_77_dialog_content = "...?!",
  ui_story_8_7_2_78_dialog_content = "Mas fiquem tranquilos, eu nunca usaria isso em outro ser vivo. Apenas tenho curiosidade sobre sua natureza.",
  ui_story_8_7_2_79_dialog_content = "Como um investigador devoto da Verdade, temos nosso caminho para percorrer. É só isso.",
  ui_story_8_7_2_80_dialog_content = "E não fará mal algum, enquanto estiver em minha mala.",
  ui_story_8_7_2_81_dialog_content = "Essa mala está... se mexendo?",
  ui_story_8_7_2_82_dialog_content = "Não se preocupe, esta mala é especial. Os segredos dos Aurorian e dos Eclipsitas um dia serão revelados.",
  ui_story_8_7_2_83_dialog_content = "Precisamos continuar nos apoiando ao longo do caminho em busca da Verdade.",
  ui_story_8_7_2_84_dialog_content = "Mais charadas. Não pode simplesmente dizer o que fará com isso?",
  ui_story_8_7_2_85_dialog_content = "Tenho certeza de que saberá em breve. Até nos encontrarmos novamente, PlayerName, Vice.",
  ui_story_8_7_2_86_dialog_content = "Que a fuga de vocês aconteça tranquilamente. De qualquer forma...",
  ui_story_8_7_2_87_dialog_content = "Eu já consegui prever o heroísmo de sua fuga em um futuro não tão distante.",
  ui_story_8_7_2_88_dialog_content = "Que a Verdade te abençoe.",
  ui_story_8_7_2_89_dialog_content = "Vice?",
  ui_story_8_7_2_90_dialog_content = "Kiuu! kiuu!",
  ui_story_8_7_2_91_dialog_content = "Senhora! Desculpe, eu estava cuidando do ferimento de PlayerName...",
  ui_story_8_7_2_92_dialog_content = "Bom, parece que ouvi a conversa de vocês. PlayerName está bem?",
  ui_story_8_7_2_F1_dialog_content = "Agora PlayerName está bem. E você, senhora?",
  ui_story_8_7_2_F2_dialog_content = "Também estou bem. Eu fui pega em uma ilusão, mas agora estou de volta.",
  ui_story_8_7_2_93_dialog_content = "Kiuu!",
  ui_story_8_7_2_94_dialog_content = "Você deve ter se preocupado demais, Curie.",
  ui_story_8_7_2_95_dialog_content = "Me perdoe, causei um grande problema para todos.",
  ui_story_8_7_2_96_option_content = "Não fale disso.",
  ui_story_8_7_2_97_dialog_content = "Se não fosse por você, talvez não tivéssemos tido chance de escapar.",
  ui_story_8_7_2_98_dialog_content = "Então vocês escolheram voltar e me resgatar?",
  ui_story_8_7_2_99_dialog_content = "Muita coisa aconteceu desde então. Contarei tudo assim que sairmos daqui.",
  ui_story_8_7_2_100_dialog_content = "E quanto a Forsakin e aquela garota louca?",
  ui_story_8_7_2_101_dialog_content = "Schummer? Não estão por perto, mas é só questão de tempo até que nos encontrem.",
  ui_story_8_7_2_102_dialog_content = "Schummer pode ter detectado toda a movimentação de agora, então precisamos sair imediatamente!",
  ui_story_8_7_2_103_option_content = "Agora está tudo bem, senhora.",
  ui_story_8_7_2_104_dialog_content = "Agora está tudo bem. Conseguimos impedir aquele Eclipsita de plantar a Semente em seu corpo.",
  ui_story_8_7_2_105_dialog_content = "Semente? Aquela coisa da qual estavam falando mais cedo?",
  ui_story_8_7_2_106_dialog_content = "Vamos sair daqui primeiro. Vou te deixar por dentro de todos os detalhes quando estivermos seguros.",
  ui_story_8_7_2_107_dialog_content = "Entendido. Estou contando com vocês",
  ui_story_8_7_2_108_dialog_content = "E sobre Forsakin? E aquela garota insanamente poderosa?",
  ui_story_8_7_2_109_dialog_content = "Não estão por perto, mas não podemos ser complacentes.",
  ui_story_8_7_2_110_dialog_content = "Schummer pode ter detectado toda a movimentação de agora, então precisamos sair imediatamente!",
  ui_story_8_7_2_111_dialog_content = "Então nossa opção é fugir, e não encarar o inimigo?",
  ui_story_8_7_2_112_dialog_content = "Assim que chegarmos à Cidade Gannon, vou reportar tudo para a Grande Marechal e receber minha punição.",
  ui_story_8_7_2_113_dialog_content = "...",
  ui_story_8_7_2_114_dialog_content = "Perfure, estraçalhe e esmague até virarem pó.",
  ui_story_8_7_2_115_dialog_content = "Regras sem sentido, moralidade e essa cidade má e cheia de ódio diante de nós, serão transformadas em pó.",
  ui_story_8_7_2_116_dialog_content = "Apenas aguarde, PlayerName.",
  ui_story_8_7_2_117_dialog_content = "Deixe que o último par de olhos Celestitas testemunhem a visão do inferno.",
  ui_story_8_7_2_118_dialog_content = "Deixe que sejam impressos em seus genes patéticos e inferiores.",
  ui_story_8_8_1_1_dialog_content = "Esta é Lumópolis! E não um bando perambulante de aventureiros, voando por aí em uma Colossus!",
  ui_story_8_8_1_2_dialog_content = "Quando caiu da sua casa na árvore tentando salvar um gato, achei que tivesse sido o ápice da sua tolice.",
  ui_story_8_8_1_3_dialog_content = "Mesmo que tenha salvado aquele gato e tomado a decisão certa, que diferença fez?",
  ui_story_8_8_1_4_dialog_content = "Eu te fiz uma pergunta! Valeu a pena?!",
  ui_story_8_8_1_5_dialog_content = "...",
  ui_story_8_8_1_6_dialog_content = "Só espero não estar entendendo mal.",
  ui_story_8_8_1_7_dialog_content = "Inacreditavelmente, aquele homem nunca falou assim comigo.",
  ui_story_8_8_1_8_dialog_content = "Mesmo se tiver interpretado mal as palavras dele, Carleen, acho que agora não tem mais volta.",
  ui_story_8_8_1_9_dialog_content = "Afinal, nós já estamos aqui.",
  ui_story_8_8_1_10_dialog_content = "Dentro da Sala de Controle do Dâmocles.",
  ui_story_8_8_1_11_dialog_content = "Certo. Se alguém te pegar, apenas diga que eu te obriguei.",
  ui_story_8_8_1_12_dialog_content = "A grande Raphaela não se importa com estas questões triviais!",
  ui_story_8_8_1_13_dialog_content = "Às vezes seus olhos brilham com tanta firmeza, Carleen, como agora.",
  ui_story_8_8_1_14_dialog_content = "Sempre que sinto insegurança, tudo que preciso fazer é olhar nos seus olhos, e então sei que posso te seguir sem arrependimento!",
  ui_story_8_8_1_15_dialog_content = "Não importa se uma decisão é certa ou errada, o importante é reunir a coragem para tomá-la, certo?",
  ui_story_8_8_1_16_dialog_content = "...",
  ui_story_8_8_1_17_dialog_content = "É uma afirmação bem filosófica, considerando que é completamente irracional.",
  ui_story_8_8_1_18_dialog_content = "...",
  ui_story_8_8_1_19_dialog_content = "Eaê, Michele! Você chegou na hora certa!",
  ui_story_8_8_1_20_dialog_content = "...",
  ui_story_8_8_1_21_dialog_content = "Obrigada, Michele. Nunca esperei que cada membro dos Guardiões viesse me ajudar, mas você é mais que o suficiente.",
  ui_story_8_8_1_22_dialog_content = "Michele é bem confiável! Especialmente porque ela não faz um monte de perguntas irrelevantes, certo?",
  ui_story_8_8_1_23_dialog_content = "...",
  ui_story_8_8_1_24_dialog_content = "Como a situação está lá? Os escudos ainda estão de pé?",
  ui_story_8_8_1_25_dialog_content = "...",
  ui_story_8_8_1_26_dialog_content = "Os escudos estão visivelmente enfraquecidos, de acordo com o relatório mais recente.",
  ui_story_8_8_1_27_dialog_content = "Não acredito que conseguiram penetrar a barreira poderosa de Lúmina. Isso é impressionante.",
  ui_story_8_8_1_28_dialog_content = "Ela não é a mesma Schummer de antes, e eu falhei em impedi-la daquela vez.",
  ui_story_8_8_1_29_dialog_content = "Mas dessa vez, sei que consigo!",
  ui_story_8_8_1_30_dialog_content = "É isso aí! Também vou dar o meu melhor!",
  ui_story_8_8_1_31_dialog_content = "Michele também está preparada!",
  ui_story_8_8_1_32_dialog_content = "...",
  ui_story_8_8_1_33_dialog_content = "Certo. Sua tarefa é bem simples, vocês duas...",
  ui_story_8_8_1_34_dialog_content = "Me ajudem a barrar a entrada da sala de controle. Não deixem ninguém entrar!",
  ui_story_8_8_1_35_dialog_content = "Assim que eu ativar o Dâmocles, ele irá canalizar toda a energia de Lumópolis até aqui.",
  ui_story_8_8_1_36_dialog_content = "Os escudos ficarão brevemente desligados, mas será tempo suficiente para deixar o pessoal em pânico.",
  ui_story_8_8_1_37_dialog_content = "Raphaela, pode chamar os outros membros dos Guardiões de novo?",
  ui_story_8_8_1_38_dialog_content = "Diga a eles para protegerem as outras áreas de Lumópolis enquanto o Dâmocles carrega!",
  ui_story_8_8_1_39_dialog_content = "Claro, tentarei mais uma vez!",
  ui_story_8_8_1_40_dialog_content = "Apenas foque em fazer o que você acredita ser o certo, Carleen.",
  ui_story_8_8_1_41_dialog_content = "Estou contando com você. Este lugar está em suas mãos.",
  ui_story_8_8_1_42_dialog_content = "...",
  ui_story_8_8_1_43_dialog_content = "Pai, isso pode ser a maior loucura que já fiz.",
  ui_story_8_8_1_44_dialog_content = "Mas eu verdadeiramente acredito...",
  ui_story_8_8_1_45_dialog_content = "Proteger as pessoas com as quais me importo à minha maneira...",
  ui_story_8_8_1_46_dialog_content = "Sempre é a escolha certa!",
  ui_story_8_8_1_47_dialog_content = "<color=#e8d9bb>Fora da Sala de Controle</color>",
  ui_story_8_8_1_48_dialog_content = "Ela entrou, como esperado, Juíza Chefe.",
  ui_story_8_8_1_49_dialog_content = "...",
  ui_story_8_8_1_50_dialog_content = "O que devemos fazer? Dadas as circunstâncias...",
  ui_story_8_8_1_51_dialog_content = "Se a Carleen não fez nada além de entrar na sala de controle do Dâmocles, ela não quebrou nenhuma regra, né?",
  ui_story_8_8_1_52_dialog_content = "Como Capitã dos Guardiões ela tem o direito de ir para qualquer lugar.",
  ui_story_8_8_1_53_dialog_content = "Mas se ela ativou o Dâmocles, isso é uma questão totalmente diferente.",
  ui_story_8_8_1_54_dialog_content = "Mas então seria tarde demais!",
  ui_story_8_8_1_55_dialog_content = "Tarde demais?",
  ui_story_8_8_1_56_dialog_content = "Lumópolis é construída sobre leis e ordem. Aqueles que violam as leis e agem como bem entenderem...",
  ui_story_8_8_1_57_dialog_content = "É tarde demais para eles.",
  ui_story_8_8_1_58_dialog_content = "Entendido. Aguardaremos as ordens.",
  ui_story_8_8_1_59_dialog_content = "Prepare para enviar um deslocamento de tropas para outras áreas como reforços.",
  ui_story_8_8_1_60_dialog_content = "Reforços?",
  ui_story_8_8_1_61_dialog_content = "Se ela ativar Dâmocles, as defesas de Lumópolis ficarão desativadas por um momento.",
  ui_story_8_8_1_62_dialog_content = "Esse será o momento da nossa salvação, ou o momento da nossa destruição?",
  ui_story_8_8_1_63_dialog_content = "Carleen de Schwartz...",
  ui_story_8_9_1_1_dialog_content = "Por aqui! Se me lembro bem do caminho, nós...",
  ui_story_8_9_1_2_dialog_content = "Espere, Vice.",
  ui_story_8_9_1_3_dialog_content = "O que foi?",
  ui_story_8_9_1_4_dialog_content = "Precisamos parar por um minuto.",
  ui_story_8_9_1_5_dialog_content = "Não podemos parar, senhora! Não podemos atrasar nem um segundo! Deixe eu te carregar!",
  ui_story_8_9_1_6_dialog_content = "Não é isso que quero dizer. Onde exatamente estamos dentro de Aviduz?",
  ui_story_8_9_1_7_dialog_content = "Ah... Acredito que estamos perto da entrada.",
  ui_story_8_9_1_8_dialog_content = "Ela está lutando agora?",
  ui_story_8_9_1_9_dialog_content = "Temo que Aviduz esteja atacando os escudos de Lumópolis.",
  ui_story_8_9_1_10_dialog_content = "É questão de tempo para que os escudos caiam...",
  ui_story_8_9_1_11_dialog_content = "Como Lumópolis irá se defender?",
  ui_story_8_9_1_12_dialog_content = "Carleen voltou e está lutando para ativar Dâmocles.",
  ui_story_8_9_1_13_dialog_content = "Então chegamos a esse ponto.",
  ui_story_8_9_1_14_dialog_content = "Sim. Aviduz foi carregada até o poder completo.",
  ui_story_8_9_1_15_dialog_content = "...",
  ui_story_8_9_1_16_dialog_content = "E Schummer? Ela não nos notou?",
  ui_story_8_9_1_17_dialog_content = "PlayerName tem usado habilidades psíquicas para limitar a Colossus.",
  ui_story_8_9_1_18_dialog_content = "Certo, mas apenas sua habilidade de monitorar o interior. Já que Schummer está conectada a ela, ninguém sabe de nossa fuga.",
  ui_story_8_9_1_19_dialog_content = "É difícil medir a quantidade de poder a ser usada. Usar sem cuidado pode fazer a Schummer perceber que tem algo estranho.",
  ui_story_8_9_1_20_dialog_content = "Isso significa que o jogo virou.",
  ui_story_8_9_1_21_dialog_content = "Inimigos expostos, enquanto nós estamos nas sombras.",
  ui_story_8_9_1_22_dialog_content = "Vivian, não quer dizer que...",
  ui_story_8_9_1_23_dialog_content = "Não vamos sair, Vice.",
  ui_story_8_9_1_24_dialog_content = "O quê?",
  ui_story_8_9_1_25_dialog_content = "Esqueceu os fundamentos da guerra rápido assim? Somos os únicos que podemos...",
  ui_story_8_9_1_26_dialog_content = "Derrotar o inimigo de dentro!",
  ui_story_8_9_1_27_dialog_content = "Mas senhora, você não está em condições...",
  ui_story_8_9_1_28_dialog_content = "Não é hora de se preocupar comigo.",
  ui_story_8_9_1_29_dialog_content = "Não podemos perder essa oportunidade. Se tivermos sucesso, talvez possamos salvar a cidade inteira.",
  ui_story_8_9_1_30_dialog_content = "...",
  ui_story_8_9_1_31_dialog_content = "Consegue pesar as decisões por conta própria, né?",
  ui_story_8_9_1_32_dialog_content = "Você é sempre uma garota tão calma e decidida, Vice. Mas parece que ultimamente está hesitante.",
  ui_story_8_9_1_33_dialog_content = "Senhora, só não quero deixar ninguém para trás. Afinal, você é...",
  ui_story_8_9_1_34_dialog_content = "Então deixa eu te perguntar, se você estivesse no meu lugar, nos deixaria perder uma oportunidade dessas?",
  ui_story_8_9_1_35_dialog_content = "Hã...",
  ui_story_8_9_1_36_dialog_content = "Além disso, por causa de PlayerName meus ferimentos estão se curando.",
  ui_story_8_9_1_37_dialog_content = "Nosso inimigo está bem diante de nós, Vice, como poderíamos simplesmente sair correndo agora?",
  ui_story_8_9_2_1_dialog_content = "<color=#e8d9bb>Muitos Anos Atrás em Lumópolis</color>",
  ui_story_8_9_2_2_dialog_content = "(Proteger as pessoas com as quais me importo da minha própria maneira.)",
  ui_story_8_9_2_3_dialog_content = "...",
  ui_story_8_9_2_4_dialog_content = "Mas...",
  ui_story_8_9_2_5_dialog_content = "Morreu.",
  ui_story_8_9_2_6_dialog_content = "Todos os seres vivos morrerão algum dia, Carleen.",
  ui_story_8_9_2_7_dialog_content = "Não consegui salvá-lo. Se eu tivesse um pouco mais de cuidado...",
  ui_story_8_9_2_8_dialog_content = "Ele pulou da casa na árvore porque estava com medo, Carleen. Não foi culpa sua.",
  ui_story_8_9_2_9_dialog_content = "Mas eu poderia tê-lo ajudado. Eu sei que poderia!",
  ui_story_8_9_2_10_dialog_content = "Parece que não faz sentido ser racional com uma criança em prantos.",
  ui_story_8_9_2_11_dialog_content = "Se há alguma lição nisso, não é se arrepender de algo que você “poderia” ter feito, mas o fato de que se proteger vem antes de salvar os outros.",
  ui_story_8_9_2_F1_dialog_content = "Sabe quantas pessoas preocupou com a sua segurança?",
  ui_story_8_9_2_12_dialog_content = "Vocês dois caíram da casa na árvore e o gato morreu, mas você não tem nenhum arranhão.",
  ui_story_8_9_2_13_dialog_content = "Que tipo de monstro são os Schwartz?",
  ui_story_8_9_2_14_dialog_content = "De qualquer forma, seja uma boa menina e espere aqui. Já informei o seu pai, e o médico te examinará mais tarde.",
  ui_story_8_9_2_15_dialog_content = "Sr. Otto.",
  ui_story_8_9_2_16_dialog_content = "Sim?",
  ui_story_8_9_2_17_dialog_content = "Posso fazer uma pergunta?",
  ui_story_8_9_2_18_dialog_content = "Fale.",
  ui_story_8_9_2_19_dialog_content = "Você estava presente quando minha mãe faleceu?",
  ui_story_8_9_2_20_dialog_content = "...",
  ui_story_8_9_2_21_dialog_content = "Não, Carleen, não estava. Ninguém além do seu pai estava.",
  ui_story_8_9_2_22_dialog_content = "...",
  ui_story_8_9_2_23_dialog_content = "Eu não deveria ter ido até Northland naquela época. Eu devia ter ficado ao lado dela e tê-la protegido.",
  ui_story_8_9_2_24_dialog_content = "Se tivesse a protegido, talvez ela não...",
  ui_story_8_9_2_25_dialog_content = "Mesmo se estivesse ao lado dela, talvez não tivesse conseguido mudar as coisas.",
  ui_story_8_9_2_26_dialog_content = "O quê?",
  ui_story_8_9_2_27_dialog_content = "Essa é a verdade. Nem mesmo Schwartz conseguiu mudar o resultado, o que faz você pensar que teria conseguido?",
  ui_story_8_9_2_28_dialog_content = "Isso significa que ainda sou uma criança que não consegue proteger ninguém?",
  ui_story_8_9_2_29_dialog_content = "E se você for?",
  ui_story_8_9_2_30_dialog_content = "...",
  ui_story_8_9_2_31_dialog_content = "Foi só um gato, Carleen.",
  ui_story_8_9_2_32_dialog_content = "Da próxima vez, não corra sozinha por aí. Você é uma dama de uma família nobre.",
  ui_story_8_9_2_33_dialog_content = "...",
  ui_story_8_9_2_34_dialog_content = "Carleen!",
  ui_story_8_9_2_35_dialog_content = "Fale.",
  ui_story_8_9_2_36_dialog_content = "A Corte de Justiça nos cercou!",
  ui_story_8_9_2_37_dialog_content = "É mesmo? Eles já tomaram alguma iniciativa?",
  ui_story_8_9_2_38_dialog_content = "Ainda não, mas estão observando cada movimento nosso. Tenho um pressentimento péssimo sobre isso!",
  ui_story_8_9_2_39_dialog_content = "A Juíza Chefe Irridon também está presente.",
  ui_story_8_9_2_40_dialog_content = "...",
  ui_story_8_9_2_41_dialog_content = "Esperem aí, Raphaela e Michele.",
  ui_story_8_9_2_42_dialog_content = "Sim!",
  ui_story_8_9_2_43_dialog_content = "Vigiem aquela porta e não deixem ninguém entrar na sala de controle do Dâmocles, entenderam?",
  ui_story_8_9_2_44_dialog_content = "Entendido!",
  ui_story_8_9_2_45_dialog_content = "Dâmocles...",
  ui_story_8_9_2_46_dialog_content = "Por favor, torne-se a lâmina brilhante e perfure a escuridão que nos cerca.",
  ui_story_8_9_2_47_dialog_content = "Dâmocles, <color=#FFB400>ativar</color>!",
  ui_story_8_10_1_1_dialog_content = "O que houve?",
  ui_story_8_10_1_2_dialog_content = "Queda de energia?",
  ui_story_8_10_1_3_dialog_content = "A sala de controle... A sala de controle do Dâmocles!",
  ui_story_8_10_1_4_dialog_content = "Não fiquem parados aí, seus tolos! Vão ver o que houve!",
  ui_story_8_10_1_5_dialog_content = "...",
  ui_story_8_10_1_6_dialog_content = "Schwartz, se isso foi obra da Carleen, você está ciente das consequências, certo?",
  ui_story_8_10_1_7_dialog_content = "Ela não está agindo sob minhas instruções. Ela está sã e agindo por conta própria.",
  ui_story_8_10_1_8_dialog_content = "Você não devia se abster de sua responsabilidade!",
  ui_story_8_10_1_9_dialog_content = "Onde está Irridon? Deixe que a Corte de Justiça...",
  ui_story_8_10_1_10_dialog_content = "A Juíza Chefe está na entrada da sala de controle!",
  ui_story_8_10_1_11_dialog_content = "Os Jardins de Lumópolis estão em um estado de caos! Os nobres estão em pânico...",
  ui_story_8_10_1_12_dialog_content = "Imponha ordem pública e diga para todos manterem a calma! Mesmo que Dâmocles tenha sido ativado, a energia de Lumópolis não...",
  ui_story_8_10_1_14_dialog_content = "A cidade está caindo?!",
  ui_story_8_10_1_15_dialog_content = "A energia da cidade está se reunindo dentro de Dâmocles, incluindo a energia dos sistemas de propulsão.",
  ui_story_8_10_1_16_dialog_content = "Eu sei disso! Agora faça alguma coisa!",
  ui_story_8_10_1_17_dialog_content = "Eu já ordenei aos Guardiões para esperarem em cada distrito de Lumópolis e se prepararem para defender a cidade, ou também gostaria de me conceder a autoridade para mobilizar o Conselho Ancião?",
  ui_story_8_10_1_18_dialog_content = "Você...",
  ui_story_8_10_1_19_dialog_content = "Senhor Schwartz! Senhor Otto! Os escudos estão...",
  ui_story_8_10_1_20_dialog_content = "<color=#e8d9bb>Enquanto isso, dentro de Aviduz</color>",
  ui_story_8_10_1_22_dialog_content = "O que foi isso?",
  ui_story_8_10_1_23_dialog_content = "Aviduz acabou de se mover? O que está havendo?",
  ui_story_8_10_1_24_dialog_content = "Kiuu!",
  ui_story_8_10_1_25_dialog_content = "...",
  ui_story_8_10_1_26_dialog_content = "Os escudos de Lumópolis estão caindo.",
  ui_story_8_10_1_27_dialog_content = "Tem certeza? Então Carleen conseguiu ativar o Dâmocles?",
  ui_story_8_10_1_28_dialog_content = "Pode ser que Schummer tenha conseguido atravessar os escudos. Não temos certeza do que está acontecendo.",
  ui_story_8_10_1_29_dialog_content = "Acredito que foi a Carleen!",
  ui_story_8_10_1_30_dialog_content = "Espera, por que os escudos estão desativados?",
  ui_story_8_10_1_31_dialog_content = "Dâmocles precisa redirecionar toda a energia de Lumópolis para si mesmo com o objetivo de recarregar. Isso inclui a energia dos escudos.",
  ui_story_8_10_1_32_dialog_content = "Mas não demora. Só espere um pouco.",
  ui_story_8_10_1_34_dialog_content = "Temos um problema, Schummer detectou a gente!",
  ui_story_8_10_1_35_dialog_content = "Desculpe, eu não esperava que se movesse do nada, não consegui...",
  ui_story_8_10_1_36_dialog_content = "PlayerName!!",
  ui_story_8_10_1_37_dialog_content = "Schummer!",
  ui_story_8_10_1_38_dialog_content = "Quando conseguiu sair?",
  ui_story_8_10_1_39_dialog_content = "Me responda primeiro. O que diabos você fez?!",
  ui_story_8_10_1_40_dialog_content = "Por que se recusa a aceitar o seu destino? Por que insistir nessa resistência sem sentido?",
  ui_story_8_10_1_41_dialog_content = "Você e a droga dos escudos dessa cidade são a mesma coisa. No fim, você vai quebrar e se entregar!",
  ui_story_8_10_1_42_dialog_content = "Você acha que derrubou os escudos de Lumópolis?",
  ui_story_8_10_1_43_dialog_content = "(Espera, talvez ela não saiba sobre Dâmocles ainda!)",
  ui_story_8_10_1_F1_dialog_content = "Ha! Testemunhou o poder de Aviduz?",
  ui_story_8_10_1_44_dialog_content = "Não tem curiosidade, PlayerName? Não quer saber por que te deixei viver depois de lutar com você tantas vezes?",
  ui_story_8_10_1_45_dialog_content = "...",
  ui_story_8_10_1_46_dialog_content = "Primeiro, foi por piedade, considerando sua fraqueza. Depois, foi por raiva, ou até ódio.",
  ui_story_8_10_1_47_dialog_content = "Mas para mim já chega. No fim, tudo que eu quero é provar algo para você e seu povo.",
  ui_story_8_10_1_48_dialog_content = "Poder verdadeiro não é nada disso de que vocês ficam falando!",
  ui_story_8_10_1_49_dialog_content = "Eu não tenho ideia do que está falando!",
  ui_story_8_10_1_50_dialog_content = "Ah, mas você vai ter.",
  ui_story_8_10_1_51_dialog_content = "Em breve vai ter.",
  ui_story_8_10_1_52_dialog_content = "O que foi, PlayerName? Você está bem? Acorda!",
  ui_story_8_10_1_53_dialog_content = "Tudo bem, não estou dormindo. Só estava falando com Schummer.",
  ui_story_8_10_1_54_dialog_content = "Ela nos achou. Precisamos impedi-la agora!",
  ui_story_8_10_1_55_dialog_content = "Concordo. Rápido, vamos lá!",
  ui_story_8_10_1_56_dialog_content = "Kiuu!",
  ui_story_8_10_1_57_dialog_content = "Só precisamos criar uma distração e manter a Schummer ocupada o máximo de tempo possível, né?",
  ui_story_8_10_1_58_dialog_content = "Espero que a gente possa ganhar tempo suficiente para a Carleen.",
  ui_story_8_10_2_1_dialog_content = "Cuidado, senhora!",
  ui_story_8_10_2_2_dialog_content = "Desculpe, meu corpo ainda está duro, não sou muito útil agora.",
  ui_story_8_10_2_3_dialog_content = "Você devia nos esperar aqui, senhora. Quanto mais perto da Ponte, mais Eclipsitas encontraremos.",
  ui_story_8_10_2_4_dialog_content = "Não me subestime, Vice. Como eu poderia deixar que lutassem por conta própria?",
  ui_story_8_10_2_5_dialog_content = "Aguente firme!",
  ui_story_8_10_2_6_dialog_content = "Esse negócio está focando em lutar contra Lumópolis! Não sabemos como a situação está lá fora.",
  ui_story_8_10_2_7_dialog_content = "Enviar... Equipe 3... até...",
  ui_story_8_10_2_8_dialog_content = "Reagrupar! Não... mirem nas rachaduras... casca externa...",
  ui_story_8_10_2_9_dialog_content = "É um recado dos Guardiões!",
  ui_story_8_10_2_10_dialog_content = "Mas Aviduz consegue bloquear nossa comunicação. Como...",
  ui_story_8_10_2_11_dialog_content = "Talvez sinais próximos tenham sido fortes o bastante para serem transmitidos? Pela mensagem, devem estar lá fora agora.",
  ui_story_8_10_2_12_dialog_content = "Estão do lado de fora? Estão falando com Aviduz?",
  ui_story_8_10_2_13_dialog_content = "Isso mesmo. Devem ter juntado uma força muito grande e estão tomando a iniciativa.",
  ui_story_8_10_2_14_dialog_content = "Carregar! Somos a última esperança de Lumópo...",
  ui_story_8_10_2_15_dialog_content = "Me siga... Não abaixe para eles! Não deixe...",
  ui_story_8_10_2_16_dialog_content = "A aeronave está descontrolada! Estamos caindo... Não! Vou levar esse lixo junto comigo, mesmo que seja a última coisa que eu faça!",
  ui_story_8_10_2_17_dialog_content = "<color=#e8d9bb>Bum!!!</color>",
  ui_story_8_10_2_18_dialog_content = "...",
  ui_story_8_10_2_19_dialog_content = "Isso foi um ataque suicida?",
  ui_story_8_10_2_20_dialog_content = "Hã...",
  ui_story_8_10_2_21_dialog_content = "Senhora, suas feridas...",
  ui_story_8_10_2_22_dialog_content = "Vamos lá, não temos tempo a perder.",
  ui_story_8_10_2_23_dialog_content = "Não deixe que a tragédia de dezessete anos atrás se repita. Precisamos parar esses Eclipsitas.",
  ui_story_8_10_2_24_dialog_content = "Tá bem.",
  ui_story_8_10_2_25_dialog_content = "Estamos chegando na Ponte. Tem certeza de que a Schummer está lá, PlayerName?",
  ui_story_8_10_2_26_dialog_content = "Positivo. Vamos dar um fim nisso de uma vez por todas!",
  ui_story_8_10_2_27_dialog_content = "Não há um único Eclipsita que pode nos parar agora.",
  ui_story_8_13_2_1_dialog_content = "Professor, falhei de novo.",
  ui_story_8_13_2_2_dialog_content = "Tudo bem, apenas comece de novo.",
  ui_story_8_13_2_3_dialog_content = "Mas eu...",
  ui_story_8_13_2_4_dialog_content = "Ninguém nasce com poderes, criança. Apenas crescendo com treinos e se erguendo após as derrotas...",
  ui_story_8_13_2_5_dialog_content = "Torna-se verdadeiramente forte.",
  ui_story_8_13_2_6_dialog_content = "Mas...",
  ui_story_8_13_2_7_dialog_content = "Schummer!",
  ui_story_8_13_2_8_dialog_content = "Você veio. Por hoje é só, Schummer, vá brincar com seus amigos.",
  ui_story_8_13_2_9_dialog_content = "É verdade! Não deixe seus amigos esperando!",
  ui_story_8_13_2_10_dialog_content = "Ha ha ha!",
  ui_story_8_13_2_11_dialog_content = "...",
  ui_story_8_13_2_12_dialog_content = "O que foi?",
  ui_story_8_13_2_13_dialog_content = "Eu...",
  ui_story_8_13_2_14_dialog_content = "...",
  ui_story_8_13_2_15_dialog_content = "Eu matei todos eles.",
  ui_story_8_13_2_16_dialog_content = "Eu os enforquei com minhas próprias mãos. O som de seus ossos quebrando foi música para meus ouvidos.",
  ui_story_8_13_2_17_dialog_content = "Música que representou o poder puro e absoluto.",
  ui_story_8_13_2_18_dialog_content = "Como está a situação, Schummer?",
  ui_story_8_13_2_19_dialog_content = "Não me interrompa. As defesas de Lumópolis foram quebradas e os Aurorians estão tomando suas últimas defesas.",
  ui_story_8_13_2_20_dialog_content = "Eu disse que cuidava disso, não disse?",
  ui_story_8_13_2_22_dialog_content = "Obtive sucesso onde todos vocês falharam! Ha...",
  ui_story_8_13_2_23_dialog_content = "Ha ha ha!",
  ui_story_8_13_2_24_dialog_content = "...",
  ui_story_8_13_2_25_dialog_content = "Agora... Se importaria de sair da minha frente?",
  ui_story_8_13_2_26_dialog_content = "Aquele Celestita está quase chegando.",
  ui_story_8_13_2_27_dialog_content = "O momento perfeito. O massacre de hoje começará em breve. Venha, docinho!",
  ui_story_8_13_2_28_dialog_content = "Não vai matar aquele Celestita?",
  ui_story_8_13_2_29_dialog_content = "Por que eu mataria meu “parceiro”?",
  ui_story_8_13_2_30_dialog_content = "Mas você não disse que...",
  ui_story_8_13_2_31_dialog_content = "Ah, cala a boca! Você sempre tem que falar algo. Por que não pode me deixar em paz?!",
  ui_story_8_13_2_32_dialog_content = "Junte-se a mim, PlayerName, você tem que ficar do meu lado!",
  ui_story_8_13_2_33_dialog_content = "Apenas espere para ver o que me tornei. Apenas abra seus olhos...",
  ui_story_8_14_1_1_dialog_content = "...",
  ui_story_8_14_1_3_dialog_content = "A cavalaria está aqui, Michele!",
  ui_story_8_14_1_4_dialog_content = "...?",
  ui_story_8_14_1_5_dialog_content = "Carleen? Ela está bem! Ela colocou os outros para manter a guarda na porta!",
  ui_story_8_14_1_6_dialog_content = "<color=#e8d9bb>Fora da Sala de Controle do Dâmocles</color>",
  ui_story_8_14_1_7_dialog_content = "Dá licença! Todos vocês, saiam da frente!",
  ui_story_8_14_1_8_dialog_content = "O que diabos você acha que está fazendo, Irridon? Por que não derrubou a porta?",
  ui_story_8_14_1_9_dialog_content = "Como você pode ver.",
  ui_story_8_14_1_10_dialog_content = "Por favor, tenha paciência, Senhor Otto.",
  ui_story_8_14_1_11_dialog_content = "Vá para trás! Em nome do Conselho Ancião, eu ordeno que todos vocês recuem!",
  ui_story_8_14_1_F1_dialog_content = "Quem disse para vocês guardarem a sala de controle!? Saiam da minha frente!",
  ui_story_8_14_1_12_dialog_content = "E para onde Schwartz correu em tempos como estes? Ele se importa tão pouco assim com a filha?!",
  ui_story_8_14_1_13_dialog_content = "Senhor Otto, se acalme e escute, por favor...",
  ui_story_8_14_1_14_dialog_content = "Olhe acima de nós, o céu está cheio de Eclipsitas. Não acha que a Corte de Justiça e o Conselho Ancião deveriam fazer algo a respeito disso?",
  ui_story_8_14_1_15_dialog_content = "Gabriela...",
  ui_story_8_14_1_16_dialog_content = "Posso transformar os Eclipsitas em pó?",
  ui_story_8_14_1_17_dialog_content = "Claro! Só não transforme as casas dos nobres em pó também.",
  ui_story_8_14_1_18_dialog_content = "Sim, mas isso será muito difícil para mim...",
  ui_story_8_14_1_19_dialog_content = "...",
  ui_story_8_14_1_20_dialog_content = "Tem certeza de que quer ficar parada no meu caminho, Gabriela?",
  ui_story_8_14_1_21_dialog_content = "Uhum, positivo!",
  ui_story_8_14_1_22_dialog_content = "Apesar de “parada” não ser a palavra certa. Eu diria que estou “sentada” no seu caminho!",
  ui_story_8_14_1_23_dialog_content = "Soldados da Corte de Justiça, avancem!",
  ui_story_8_14_1_24_dialog_content = "<size=45>Por que não experimenta?</size>",
  ui_story_8_14_1_25_dialog_content = "O prédio está caindo! Recuar para...",
  ui_story_8_14_1_26_dialog_content = "!!",
  ui_story_8_14_1_27_dialog_content = "Eles são muitos! Vamos perder tudo se continuarmos assim!!",
  ui_story_8_14_1_28_dialog_content = "...!!",
  ui_story_8_14_1_29_dialog_content = "Entendido! Recuem para um lugar menor e assumam posições defensivas!",
  ui_story_8_14_1_30_dialog_content = "Não podemos deixar os Eclipsitas passarem!",
  ui_story_8_14_1_31_dialog_content = "*Rugido*",
  ui_story_8_14_1_33_dialog_content = "<color=#e8d9bb>Sala de Controle do Dâmocles</color>",
  ui_story_8_14_1_34_dialog_content = "...",
  ui_story_8_14_1_35_dialog_content = "(Raphaela, Michele, Gabriela e outros estão lutando agora?)",
  ui_story_8_14_1_36_dialog_content = "Por favor, rápido, Dâmocles...",
  ui_story_8_14_1_37_dialog_content = "O povo de Lumópolis e a cidade precisam que você acorde!",
  ui_story_8_14_1_38_dialog_content = "Está muito devagar. Preciso acelerar o processo de carregamento, mesmo que custe todo o meu poder!",
  ui_story_8_14_1_39_dialog_content = "<color=#e8d9bb>A Ponte de Aviduz</color>",
  ui_story_8_14_1_40_dialog_content = "Torretas.",
  ui_story_8_14_1_41_dialog_content = "Muralhas da cidade.",
  ui_story_8_14_1_42_dialog_content = "E essas moscas que vocês chamam de “aeronaves”.",
  ui_story_8_14_1_43_dialog_content = "As engrenagens da guerra já estão se movimentando. Não poderiam me impedir em nenhuma vida.",
  ui_story_8_14_1_44_dialog_content = "Ninguém pode me impedir agora!!",
  ui_story_8_14_1_45_dialog_content = "Schummer.",
  ui_story_8_14_1_46_dialog_content = "PlayerName.",
  ui_story_8_14_1_47_dialog_content = "Está com medo? O show acabou de começar e você já está sem ar.",
  ui_story_8_14_1_48_dialog_content = "Venha, sente-se.",
  ui_story_8_14_1_49_dialog_content = "Você precisa parar com isso! Isso não pode continuar assim.",
  ui_story_8_14_1_50_dialog_content = "Ela está ocupada controlando a Aviduz, PlayerName! Agora é sua chance.",
  ui_story_8_14_1_51_dialog_content = "À sua esquerda, Vice!",
  ui_story_8_14_1_52_dialog_content = "*Rugido*",
  ui_story_8_14_1_53_dialog_content = "Um Eclipsita de alto nível!",
  ui_story_8_14_1_54_dialog_content = "Dessa vez parece diferente. Parece que aquele Eclipsita vai começar uma luta.",
  ui_story_8_14_1_55_dialog_content = "Deixe eles virem, idiota. Não estrague a minha diversão.",
  ui_story_8_14_1_56_dialog_content = "Não foi fácil organizar esse show. Seria um desperdício se não tivesse ninguém para assistir.",
  ui_story_8_14_1_57_dialog_content = "Schummer, repetidas vezes você foi contra as ordens da Senhora Forsakin. Mesmo em tempos assim, você continua insistente.",
  ui_story_8_14_1_58_dialog_content = "Eu não tenho direito de impedir seu comportamento terrível. Mas você também não tem direito de me comandar.",
  ui_story_8_14_1_59_dialog_content = "Assim como nossas mestras, nos dedicamos e dedicamos nosso trabalho à Mãe e não a desejos egoístas!",
  ui_story_8_14_1_60_dialog_content = "Mãe isso, Mãe aquilo... Isso é incrivelmente chato.",
  ui_story_8_14_1_61_dialog_content = "PlayerName, como pode ver, estou muito ocupada agora.",
  ui_story_8_14_1_62_dialog_content = "Mas não importa o que aconteça, preciso que você testemunhe a destruição completa de Lumópolis. É por isso que...",
  ui_story_8_14_1_63_dialog_content = "Preciso pedir meu primeiro favor a você. Mate esse Eclipsita e fique do meu lado.",
  ui_story_8_14_1_64_dialog_content = "Você...?",
  ui_story_8_14_1_65_dialog_content = "O que ela está armando agora? Cuidado, PlayerName!",
  ui_story_8_14_1_66_dialog_content = "Certo. De qualquer jeito, ela tem razão. Temos que dar um jeito naquele Eclipsita antes de tudo!",
  ui_story_8_14_1_67_dialog_content = "Que honra finalmente poder te conhecer, Celestita. Você também, Aurorian.",
  ui_story_8_14_1_68_dialog_content = "Vocês têm sido uma pedra no nosso sapato há muito tempo. Chegou a hora de realizar o desejo da Mãe e do Eclipse. Bom...",
  ui_story_8_14_1_69_dialog_content = "Venha...",
  ui_story_8_14_1_70_dialog_content = "Não me decepcione, PlayerName.",
  ui_story_8_14_2_1_dialog_content = "Impossível... Sem chance!",
  ui_story_8_14_2_2_dialog_content = "Mãe, Senhora Forsakin, por favor, me deem uma última chance! Me deem o poder para...",
  ui_story_8_14_2_3_dialog_content = "Chega disso.",
  ui_story_8_14_2_4_dialog_content = "Argh!",
  ui_story_8_14_2_5_dialog_content = "Schummer, sua traidora!",
  ui_story_8_14_2_6_dialog_content = "Traidora? Ah, por favor. Eu nunca jurei aliança a ninguém.",
  ui_story_8_14_2_7_dialog_content = "Acabou, Schummer.",
  ui_story_8_14_2_8_dialog_content = "Acabou? A gente só tá começando!",
  ui_story_8_14_2_9_dialog_content = "Conecte-se, Aviduz!",
  ui_story_8_14_2_10_dialog_content = "PlayerName!",
  ui_story_8_14_2_11_dialog_content = "O que tá fazendo?",
  ui_story_8_14_2_12_dialog_content = "Impedindo você e essa Colossus!",
  ui_story_8_14_2_13_dialog_content = "Aviduz sou eu, e eu sou Aviduz. Você não pode controlá-la!",
  ui_story_8_14_2_14_dialog_content = "Não posso? Tudo que quero é te impedir de chegar mais perto de Lumópolis.",
  ui_story_8_14_2_15_dialog_content = "Lá é o lar dos Aurorians...",
  ui_story_8_14_2_16_dialog_content = "E dos meus amigos... É o lar deles também!!!",
  ui_story_8_14_2_18_dialog_content = "Então mesmo que isso seja o que é preciso... Argh... Ai!",
  ui_story_8_14_2_19_dialog_content = "Seu nariz está sangrando, PlayerName!",
  ui_story_8_14_2_20_dialog_content = "Não se aproxime! Vá... Derrotar Schummer!",
  ui_story_8_14_2_21_dialog_content = "Eu disse que não pode controlá-la.",
  ui_story_8_14_2_22_dialog_content = "Cuidado, Vice!!",
  ui_story_8_14_2_23_dialog_content = "(Se conecte com a Aviduz novamente!)",
  ui_story_8_14_2_24_dialog_content = "Não sabe a hora de parar, né? PlayerName?",
  ui_story_8_14_2_25_dialog_content = "Nunca! Eu não vou desistir, mesmo que isso me mate!",
  ui_story_8_14_2_26_dialog_content = "Você não tem nenhuma chance de vencer agora, Schummer!",
  ui_story_8_14_2_27_dialog_content = "Você ao menos sabe do que está falando? Abra os olhos e veja bem!!",
  ui_story_8_14_2_28_dialog_content = "Lumópolis está condenada! Suas defesas, seus soldados... Todos estão condenados!",
  ui_story_8_14_2_29_dialog_content = "Eu consegui, PlayerName! Consegui fazer o que ninguém mais conseguiu!",
  ui_story_8_14_2_30_dialog_content = "Por que não aceita isso? Você deveria se arrastar por conta do meu poder absoluto, então por que continua lutando?",
  ui_story_8_14_2_31_dialog_content = "Aviduz, desligue... geradores...",
  ui_story_8_14_2_32_dialog_content = "A Colossus é minha!",
  ui_story_8_14_2_33_dialog_content = "Aaaarrrgh!!!",
  ui_story_8_14_2_35_dialog_content = "Ai, minha cabeça está girando, eu ...",
  ui_story_8_14_2_36_dialog_content = "PlayerName...",
  ui_story_8_14_2_37_dialog_content = "Sinto muito, não conseguimos superar as defesas de Schummer.",
  ui_story_8_14_2_38_dialog_content = "Conseguem ver a diferença do nosso poder? Você e suas companheiras canalhas. Como poderiam me superar?",
  ui_story_8_14_2_39_dialog_content = "Apenas mantenha os olhos abertos, PlayerName. Não quero continuar te torturando, ainda mais agora.",
  ui_story_8_14_2_40_dialog_content = "Preciso que veja isso. Que testemunhe isso como Celestita...",
  ui_story_8_14_2_41_dialog_content = "O quê?",
  ui_story_8_14_2_42_dialog_content = "...?",
  ui_story_8_14_2_43_dialog_content = "(Por que tanto silêncio?)",
  ui_story_8_14_2_44_dialog_content = "...",
  ui_story_8_14_2_45_dialog_content = "Seus miseráveis, o que fizeram dessa vez?",
  ui_story_8_14_2_46_dialog_content = "(Schummer não sabe o que está havendo, então não foi ela?)",
  ui_story_8_14_2_47_dialog_content = "O quê?",
  ui_story_8_14_2_48_dialog_content = "Por que parece que cada pelo do meu corpo está em pé?",
  ui_story_8_14_2_49_dialog_content = "Algo no ar está diferente, Vice.",
  ui_story_8_14_2_50_dialog_content = "E por que está tudo em silêncio assim do nada?",
  ui_story_8_14_2_51_dialog_content = "Tem razão, está quieto demais. Não ouço qualquer barulho.",
  ui_story_8_14_2_52_dialog_content = "Olhe para o chão, Vice!",
  ui_story_8_14_2_53_dialog_content = "A terra está se movendo, e parece que em uma direção específica...",
  ui_story_8_14_2_54_dialog_content = "Talvez seja o vento. Consegue sentir? O ar está se unindo, como...",
  ui_story_8_14_2_55_dialog_content = "Como se algo estivesse se erguendo?",
  ui_story_8_14_2_56_dialog_content = "Isso não me cheira bem!",
  ui_story_8_14_2_58_dialog_content = "Senhora, PlayerName, se abaixem e segurem firme.",
  ui_story_8_14_2_59_dialog_content = "Se não estiver me enganando, chegou a hora.",
  ui_story_8_14_2_62_dialog_content = "Tem algo sobre Lumópolis. O que é aquilo?",
  ui_story_8_14_2_63_dialog_content = "De onde está vindo essa luz?",
  ui_story_8_14_2_64_dialog_content = "...",
  ui_story_8_14_2_65_dialog_content = "Noite Branca sempre... Minha promessa foi concluída.",
  ui_story_8_14_2_66_dialog_content = "Schummer, traidora dos Celestitas, eu, Carleen de Schwartz, serei aquela que levará...",
  ui_story_8_14_2_67_dialog_content = "Seu juízo final!!!!",
  ui_story_8_14_2_68_dialog_content = "Isso é... ?",
  ui_story_8_14_2_69_dialog_content = "Pessoal, se abaixem!!",
  ui_story_8_14_2_70_dialog_content = "<color=#e8d9bb>Bum!!!</color>",
  ui_story_8_14_2_73_dialog_content = "(O que, um canhão de Lúmina? Meus olhos!)",
  ui_story_8_14_2_74_dialog_content = "(Por que não consigo me mover? Por que não consigo mover meu corpo!?)",
  ui_story_8_14_2_75_dialog_content = "(Schummer...)",
  ui_story_8_14_2_76_dialog_content = "(Você!)",
  ui_story_8_14_2_77_dialog_content = "(Eu disse que te impediria, mesmo que isso fosse me matar...)",
  ui_story_8_14_2_78_dialog_content = "(Acha que consegue me impedir assim?!)",
  ui_story_8_14_2_82_dialog_content = "Schummer!",
  ui_story_8_14_2_83_dialog_content = "Nem pense em começar uma última luta!!",
  ui_story_8_14_2_F1_dialog_content = "O raio de Dâmocles irá perfurar você e Aviduz!",
  ui_story_8_14_2_84_dialog_content = "(Carleen!)",
  ui_story_8_14_2_87_dialog_content = "Desvie, Aviduz! Mova-se!",
  ui_story_8_14_2_88_dialog_content = "Não vou deixar você escapar.. Argh...!",
  ui_story_8_14_2_89_dialog_content = "Escape! Por que não está se movendo?",
  ui_story_8_14_2_90_dialog_content = "(Eu preciso... dar tudo de mim! Não posso deixar a Colossus escapar!!)",
  ui_story_8_14_2_91_dialog_content = "Liberte minha Colossus, PlayerName! Desfaça sua conexão mental com a Aviduz!",
  ui_story_8_14_2_92_dialog_content = "(Não... O raio... errou?)",
  ui_story_8_14_2_93_dialog_content = "Sua Lúmina é fraca demais, Carleen! Não consegue mais mirar os raios! Se afaste!",
  ui_story_8_14_2_94_dialog_content = "?!",
  ui_story_8_14_2_95_dialog_content = "Meu senhor. Mas por quê?",
  ui_story_8_14_2_96_dialog_content = "Só estou ajudando a guiar o ataque de Dâmocles, nada além disso!",
  ui_story_8_14_2_97_dialog_content = "Não olhe para trás. Seu alvo está na sua frente, não está?",
  ui_story_8_14_2_98_dialog_content = "Se lembra da única coisa que não deve fazer antes de derrotar um inimigo?",
  ui_story_8_14_2_99_dialog_content = "Claro que sim, pai!",
  ui_story_8_14_2_100_dialog_content = "“Nunca perca o controle até perfurar o peito do seu inimigo!”",
  ui_story_8_14_2_101_dialog_content = "(Eu vou morrer! Nesse ritmo, eu...)",
  ui_story_8_14_2_102_dialog_content = "(Pare! Saia, PlayerName!)",
  ui_story_8_14_2_103_dialog_content = "Schummer!",
  ui_story_8_14_2_104_dialog_content = "Olhe nos meus olhos antes de morrer!!!",
  ui_story_8_14_2_105_dialog_content = "Não, não...",
  ui_story_8_14_2_106_dialog_content = "Nãooooo!",
  ui_story_8_14_2_112_dialog_content = "Schummer.",
  ui_story_8_14_2_113_dialog_content = "Estou aqui, professor.",
  ui_story_8_14_2_114_dialog_content = "Por que fez isso?",
  ui_story_8_14_2_115_dialog_content = "...",
  ui_story_8_14_2_116_dialog_content = "Por que...",
  ui_story_8_14_2_117_dialog_content = "Por que matou todos nós?",
  ui_story_8_14_2_118_dialog_content = "Com meu último suspiro, eu te amaldiçoo, Schummer, traidora dos Celestitas, e meu maior fracasso.",
  ui_story_8_14_2_119_dialog_content = "Eu te amaldiçoo com uma morte mil vezes mais agonizante que a nossa, Schummer.",
  ui_story_8_14_2_120_dialog_content = "Eu amaldiçoo toda a sua vida.",
  ui_story_8_14_2_121_dialog_content = "Você nunca conhecerá a paz.",
  ui_story_8_15_1_1_dialog_content = "Tarde demais, Forsakin.",
  ui_story_8_15_1_2_dialog_content = "Este lugar é muito distante. Tem necessidade de se esconder aqui?",
  ui_story_8_15_1_3_dialog_content = "Você trouxe aquilo?",
  ui_story_8_15_1_4_dialog_content = "Está com a Schummer. Deve terminar em breve, não me apresse.",
  ui_story_8_15_1_5_dialog_content = "Por que deixar o ataque a Lumópolis para Schummer? Sua tarefa era simples o bastante, apenas deixe aquilo no corpo dela...",
  ui_story_8_15_1_6_dialog_content = "Ela era imatura demais para entender.",
  ui_story_8_15_1_7_dialog_content = "E isso importa?",
  ui_story_8_15_1_8_dialog_content = "...",
  ui_story_8_15_1_9_dialog_content = "Não esqueça do seu dever, Aurorian.",
  ui_story_8_15_1_10_dialog_content = "*Boceja*",
  ui_story_8_15_1_11_dialog_content = "Fim do relatório de casualidade de Baixa Lumópolis. E aqui estão as propostas de punições para a Capitã dos Guardiões...",
  ui_story_8_15_1_12_dialog_content = "Muito bom, por agora é só.",
  ui_story_8_15_1_13_dialog_content = "Vá para fora agora. Você pode voltar e continuar em cinco minutos.",
  ui_story_8_15_1_14_dialog_content = "Sim!",
  ui_story_8_15_1_15_dialog_content = "Fale.",
  ui_story_8_15_1_16_dialog_content = "Quanto tempo, Schwartz.",
  ui_story_8_15_1_17_dialog_content = "Está aqui para me consolar?",
  ui_story_8_15_1_18_dialog_content = "E acreditaria se eu estivesse?",
  ui_story_8_15_1_19_dialog_content = "Você está bem humorado demais para alguém que já mostrou todas as cartas.",
  ui_story_8_15_1_20_dialog_content = "Não seja presunçosa. Até agora usei apenas uma carta.",
  ui_story_8_15_1_21_dialog_content = "Além disso, não estamos mais sozinhos nessa. Tem mais gente defendendo esta cidade agora.",
  ui_story_8_15_1_22_dialog_content = "Não tenho interesse em ensinar sua criança a jogar, Schwartz.",
  ui_story_8_15_1_23_dialog_content = "Na verdade, não tive influência no jogo de hoje. Não se importa, certo?",
  ui_story_8_15_1_24_dialog_content = "Eu não me importo. Acredito no poder de Lumópolis. Oh, grande Senhor da Cidade Inconquistável.",
  ui_story_8_15_1_25_dialog_content = "Também aconteceram coisas interessantes no meu lado. Mal posso esperar para compartilhar.",
  ui_story_8_15_1_26_dialog_content = "Muito bem. Vamos ver do que a Federação Illumina é capaz.",
  ui_story_8_15_1_27_dialog_content = "A chama cintilante, será que ela finalmente cortará um caminho pela escuridão?",
  ui_story_8_15_1_28_dialog_content = "Splendor Illumina!",
  ui_story_9_1_1_1_dialog_content = "Podem entrar agora.",
  ui_story_9_1_1_2_dialog_content = "Obrigada. Vamos, PlayerName.",
  ui_story_9_1_1_3_dialog_content = "<color=#e8d9bb>Crec...</color>",
  ui_story_9_1_1_4_dialog_content = "Vice, ainda não sei...",
  ui_story_9_1_1_5_option_content = "Onde estamos?",
  ui_story_9_1_1_6_dialog_content = "Estamos na Corte de Justiça dos Jardins de Lumópolis.",
  ui_story_9_1_1_7_dialog_content = "A mulher no palco com o bastão deve ser a Juíza Chefe <color=#FFB400>Irridon</color>.",
  ui_story_9_1_1_8_option_content = "Quem são essas pessoas?",
  ui_story_9_1_1_9_dialog_content = "Se não me engano...",
  ui_story_9_1_1_10_dialog_content = "A mulher no palco com o bastão é a Juíza Chefe <color=#FFB400>Irridon</color>, que comanda a Corte de Justiça.",
  ui_story_9_1_1_11_dialog_content = "E o homem sério ao lado dela...",
  ui_story_9_1_1_12_dialog_content = "Ah, lembrei, é o pai da Carleen, né?",
  ui_story_9_1_1_13_dialog_content = "Isso, é o Senhor de Lumópolis, <color=#FFB400>Daniel de Schwartz</color>.",
  ui_story_9_1_1_14_dialog_content = "Estou tremendo...",
  ui_story_9_1_1_15_dialog_content = "Shh...",
  ui_story_9_1_1_16_dialog_content = "...",
  ui_story_9_1_1_17_dialog_content = "Presumo que vocês são os companheiros de Capitão Carleen?",
  ui_story_9_1_1_18_dialog_content = "Hã, sim. Como vai, senhor?",
  ui_story_9_1_1_19_dialog_content = "Sou a Vice, da Federação Illumina. Esse é PlayerName.",
  ui_story_9_1_1_20_dialog_content = "Como está? Sou PlayerName.",
  ui_story_9_1_1_21_dialog_content = "É um prazer.",
  ui_story_9_1_1_22_dialog_content = "Eu entendo que você atrasou o ataque do inimigo e lutou bravamente para ser uma peça-chave na defesa da cidade.",
  ui_story_9_1_1_23_dialog_content = "Devo expressar minha gratidão a vocês.",
  ui_story_9_1_1_24_dialog_content = "É nossa honra, senhor. Apenas fizemos o que deveríamos.",
  ui_story_9_1_1_25_dialog_content = "Como está a recuperação dos seus ferimentos?",
  ui_story_9_1_1_26_dialog_content = "Graças aos médicos que enviou, estamos muito melhor agora.",
  ui_story_9_1_1_27_dialog_content = "Ótimo. Lumópolis nunca vai esquecer o fato da Federação Illumina ter enviado ajuda para amenizar a crise.",
  ui_story_9_1_1_28_dialog_content = "Por favor, transmita meu agradecimento ao povo da Illumina em nome de Lumópolis também.",
  ui_story_9_1_1_29_dialog_content = "Farei isso, senhor.",
  ui_story_9_1_1_X29_dialog_content = "Tá bom.",
  ui_story_9_1_1_X30_dialog_content = "Pois bem, Juíza Chefe, pode dar prosseguimento e anunciar o início da sessão.",
  ui_story_9_1_1_X31_dialog_content = "Sim, Senhor.",
  ui_story_9_1_1_30_dialog_content = "A corte está em sessão. Para os seus lugares.",
  ui_story_9_1_1_31_dialog_content = "Sim!",
  ui_story_9_1_1_32_dialog_content = "(Carleen...)",
  ui_story_9_1_1_33_dialog_content = "Noite Branca sempre.",
  ui_story_9_1_1_34_dialog_content = "Em nome da Corte de Justiça, irei proferir a sentença contra Carleen de Schwartz.",
  ui_story_9_1_1_35_dialog_content = "Carleen de Schwartz, atual capitã dos Guardiões de Lumópolis...",
  ui_story_9_1_1_36_dialog_content = "Foi descoberto que, durante sua gestão...",
  ui_story_9_1_1_37_dialog_content = "Carleen negligenciou o resoluto de terceiros, invadiu a Sala de Controle com um cavaleiro comandante como refém e iniciou a Dâmocles sem autorização.",
  ui_story_9_1_1_38_dialog_content = "Isso causou diretamente  a falha do escudo, posteriormente expondo os Jardins e o Pátio de Lumópolis a ataques.",
  ui_story_9_1_1_39_dialog_content = "Levando a cento e oito nobres feridos e incontáveis servos feridos ou mortos, além da perda incomensurável de propriedades.",
  ui_story_9_1_1_40_dialog_content = "Essas ações violaram as leis de Lumópolis e devem ser punidas em conformidade.",
  ui_story_9_1_1_41_dialog_content = "No entanto, depois de considerar seu esforço em afastar os invasores,",
  ui_story_9_1_1_42_dialog_content = "a Corte de Justiça decidiu suspender Carleen de Schwartz do serviço por 1 ano...",
  ui_story_9_1_1_43_dialog_content = "Quê? Que ridículo! Como você pôde chegar a um veredicto tão absurdo!?",
  ui_story_9_1_1_44_dialog_content = "...",
  ui_story_9_1_1_45_dialog_content = "O que ela fez foi um desprezo flagrante pela vida de todos os nobres em Lumópolis!",
  ui_story_9_1_1_46_dialog_content = "Ela só teve sorte desta vez! Se a deixarmos impune, quem sabe o que ela fará da próxima vez?",
  ui_story_9_1_1_47_dialog_content = "Você não está mancomunado com o Salão para proteger sua filha, está, Schwartz?",
  ui_story_9_1_1_48_dialog_content = "Você questiona o veredicto da Juíza Chefe, Otto Troy? Isso é inadequado para um nobre.",
  ui_story_9_1_1_49_dialog_content = "Hunf...",
  ui_story_9_1_1_50_dialog_content = "Continue, Meritíssima.",
  ui_story_9_1_1_51_dialog_content = "A Corte de Justiça decidiu suspender Carleen de Schwartz do serviço por 1 ano.",
  ui_story_9_1_1_52_dialog_content = "Neste intervalo, ela deve descobrir a verdade por trás da incursão.",
  ui_story_9_1_1_53_dialog_content = "E fornecer uma descoberta satisfatória aos nobres.",
  ui_story_9_1_1_54_dialog_content = "Se falhar, tiraremos de Carleen de Schwartz seu cargo, título...",
  ui_story_9_1_1_55_dialog_content = "e residência em Lumópolis.",
  ui_story_9_1_1_56_dialog_content = "Noite branca sempre. Que a Luz abençoe a todos em Lumópolis.",
  ui_story_9_1_1_57_dialog_content = "Noite Branca sempre.",
  ui_story_9_1_1_58_dialog_content = "Por aqui, Vice e PlayerName.",
  ui_story_9_1_1_59_dialog_content = "Como está se sentindo, Carleen?",
  ui_story_9_1_1_60_dialog_content = "Estou bem, obrigada.",
  ui_story_9_1_1_61_dialog_content = "E você, PlayerName? Vocês já estão curados?",
  ui_story_9_1_1_62_dialog_content = "Isso foi tenso!",
  ui_story_9_1_1_63_dialog_content = "Desculpe por ter que presenciar isso.",
  ui_story_9_1_1_64_dialog_content = "Parece que PlayerName já se curou por completo.",
  ui_story_9_1_1_65_dialog_content = "Ha, acho que sim.",
  ui_story_9_1_1_66_dialog_content = "O Otto...",
  ui_story_9_1_1_67_dialog_content = "Ele se opôs veementemente antes mesmo da Juíza Chefe terminar o veredicto.",
  ui_story_9_1_1_68_dialog_content = "Ele não mostrou respeito pelo Senhor da Cidade ou por Carleen!",
  ui_story_9_1_1_69_dialog_content = "Óbvio que Carleen iniciou a Dâmocles para proteger Lumópolis.",
  ui_story_9_1_1_70_dialog_content = "E o inimigo foi derrotado.",
  ui_story_9_1_1_71_dialog_content = "Por que ele fez parecer que Carleen cometeu um pecado imperdoável?",
  ui_story_9_1_1_72_dialog_content = "Isso é um típico nobre de Lumópolis, velho e ridículo!",
  ui_story_9_1_1_73_dialog_content = "...",
  ui_story_9_1_1_74_dialog_content = "!",
  ui_story_9_1_1_75_dialog_content = "Desculpe, eu não queria falar mal de Lumópolis...",
  ui_story_9_1_1_76_dialog_content = "Tudo bem. Eu sei que não quis falar mal. E, também, acredito na lei e no veredicto de Lumópolis.",
  ui_story_9_1_1_77_dialog_content = "Mesmo que o Salão não ordenasse, eu investigaria o assunto.",
  ui_story_9_1_1_78_dialog_content = "Sei como você se sente. Eu também quero saber a verdade.",
  ui_story_9_1_1_79_dialog_content = "Mas por que o Salão não autorizou mais ajuda para sua investigação, Carleen?",
  ui_story_9_1_1_80_dialog_content = "Talvez o Senhor da Cidade não considere Schummer uma ameaça...",
  ui_story_9_1_1_81_dialog_content = "Quê? Como assim?",
  ui_story_9_1_1_82_dialog_content = "Eu encontrei com ele após o veredicto.",
  ui_story_9_1_1_83_dialog_content = "Queria perguntar sobre o ataque da Schummer em Lumópolis, pai.",
  ui_story_9_1_1_84_dialog_content = "Fale.",
  ui_story_9_1_1_85_dialog_content = "Como é que a cidade não revidou logo no início, ",
  ui_story_9_1_1_86_dialog_content = "só deixou que quebrassem o escudo?",
  ui_story_9_1_1_87_dialog_content = "Você sabe qual é a sua responsabilidade como Capitã dos Guardiões dos Jardins de Lumópolis?",
  ui_story_9_1_1_88_dialog_content = "O que é isso?",
  ui_story_9_1_1_89_dialog_content = "Claro, é proteger as pessoas.",
  ui_story_9_1_1_90_dialog_content = "Me desculpe, mas não entendo por que ignorou a pergunta e, desse modo, a lógica.",
  ui_story_9_1_1_91_dialog_content = "Vejo que ainda não entendeu.",
  ui_story_9_1_1_92_dialog_content = "É dever do capitão defender os Jardins, também conhecido como a moradia dos nobres.",
  ui_story_9_1_1_93_dialog_content = "Por conta da escassez de pessoal nos últimos anos, os Guardiões assumiram mais poder e responsabilidades,",
  ui_story_9_1_1_94_dialog_content = "incluindo a manutenção da paz em partes de Baixa Lumópolis.",
  ui_story_9_1_1_95_dialog_content = "Na verdade, para essas pessoas, sua obrigação é garantir a segurança das classes superiores.",
  ui_story_9_1_1_96_dialog_content = "...",
  ui_story_9_1_1_97_dialog_content = "Acho que você percebeu seu erro agora.",
  ui_story_9_1_1_98_dialog_content = "Quanto à sua pergunta...",
  ui_story_9_1_1_99_dialog_content = "Você realmente acha que esse lixo pode violar o escudo?",
  ui_story_9_1_1_100_dialog_content = "Quer dizer que...",
  ui_story_9_1_1_101_dialog_content = "Descubra por você mesmo. Tenho outra reunião pra participar.",
  ui_story_9_1_1_102_dialog_content = "...",
  ui_story_9_1_1_103_dialog_content = "O que isso significa?",
  ui_story_9_1_1_104_dialog_content = "Eu também não entendo. O que exatamente ele quis dizer?",
  ui_story_9_1_1_105_dialog_content = "Talvez eu não devesse me preocupar com as questões de Lumópolis ou Illumina…",
  ui_story_9_1_1_106_dialog_content = "Só quero descobrir o que aconteceu no passado!",
  ui_story_9_1_1_107_dialog_content = "PlayerName...",
  ui_story_9_1_1_108_dialog_content = "Ainda me arrepio com esse pensamento.",
  ui_story_9_1_1_109_dialog_content = "A explosão ocorreu muito perto, e PlayerName não se movia!",
  ui_story_9_1_1_110_dialog_content = "Oficial Vivian e eu não conseguimos tirar PlayerName de lá.",
  ui_story_9_1_1_111_dialog_content = "Felizmente, Curie veio ajudar. E assim escapamos antes que a Aviduz fosse atingida.",
  ui_story_9_1_1_112_dialog_content = "Naquela hora, eu estava decidida a não deixar a Aviduz escapar.",
  ui_story_9_1_1_113_dialog_content = "Seria pior se Carleen não tivesse direcionado Dâmocles para bater em Aviduz.",
  ui_story_9_1_1_114_dialog_content = "...",
  ui_story_9_1_1_115_dialog_content = "Você... Por quê!?",
  ui_story_9_1_1_116_dialog_content = "Só estou ajudando a guiar o ataque da Dâmocles, nada mais!",
  ui_story_9_1_1_117_dialog_content = "Afinal, é meu dever proteger Lumópolis.",
  ui_story_9_1_1_118_dialog_content = "Então Vivian e Curie estão de volta à Illumina?",
  ui_story_9_1_1_119_dialog_content = "Ah, elas ainda estão no hospital em Lumópolis.",
  ui_story_9_1_1_120_dialog_content = "Mas não se preocupe, elas não correm perigo, só precisam se recuperar em paz por um tempo.",
  ui_story_9_1_1_X120_dialog_content = "As asas de Curie sofreram o impacto do ataque, mas ela já está quase recuperada. Ela esteve ao lado de Vivian esse tempo todo.",
  ui_story_9_1_1_121_dialog_content = "Bom saber, mas...",
  ui_story_9_1_1_122_dialog_content = "Schummer morreu mesmo?",
  ui_story_9_1_1_123_dialog_content = "Até sairmos, Schummer estava na ponte da Aviduz e aparentemente não podia se mover.",
  ui_story_9_1_1_124_dialog_content = "Não acho que alguma criatura sobreviveria àquele encontro.",
  ui_story_9_1_1_125_dialog_content = "Acho que sei o que está te incomodando, PlayerName.",
  ui_story_9_1_1_126_dialog_content = "Eu também não pararia até ver o cadáver de Schummer.",
  ui_story_9_1_1_X126_dialog_content = "Mas antes disso, tenho uma missão importante a cumprir.",
  ui_story_9_1_1_X127_dialog_content = "Hã? Qual missão?",
  ui_story_9_1_1_X128_dialog_content = "Preciso te levar para ver o Soroz.",
  ui_story_9_1_1_127_dialog_content = "Encomendamos os serviços de especialistas que podem reparar Soroz. Aparentemente, eles já acabaram.",
  ui_story_9_1_1_128_dialog_content = "<color=#FFB400>Soroz</color>!",
  ui_story_9_1_1_129_dialog_content = "Sem resposta...",
  ui_story_9_1_1_130_dialog_content = "Bem a tempo.",
  ui_story_9_1_1_131_dialog_content = "Madame Gronru? Você não estava de férias em Gannon?",
  ui_story_9_1_1_132_dialog_content = "E perder uma missão que é difícil de encontrar? Não mesmo, principalmente se tratando de uma Colossus!",
  ui_story_9_1_1_133_dialog_content = "Fui eu que chamei Gronru aqui!",
  ui_story_9_1_1_134_dialog_content = "Quando Raphaela visitou Illumina pela primeira vez, nós nos conhecemos e nos demos muito bem, como arroz e feijão, goiabada com queijo...",
  ui_story_9_1_1_135_dialog_content = "Ok, não precisa contar tudo de novo.",
  ui_story_9_1_1_136_dialog_content = "Bom, já encontrei as peças e consertei a Colossus para PlayerName!",
  ui_story_9_1_1_137_dialog_content = "E já que você me ajudou a recuperar meus PV da última vez, vou até dispensar a recompensa por limpar o estágio.",
  ui_story_9_1_1_138_dialog_content = "Já consertou?",
  ui_story_9_1_1_139_dialog_content = "Soroz foi destruído pelos Eclipsitas.",
  ui_story_9_1_1_140_dialog_content = "Mas não tem mais nem um amassado!",
  ui_story_9_1_1_141_dialog_content = "Impressionante. Não é à toa que você é a Oficial de Tecnologia!",
  ui_story_9_1_1_142_dialog_content = "A Raphaela também ajudou!",
  ui_story_9_1_1_143_dialog_content = "Agradeço muito a todos. Agora...",
  ui_story_9_1_1_144_dialog_content = "Soroz está restaurado e funcional?",
  ui_story_9_1_1_145_dialog_content = "Tudo em ordem, desde o controle primário até o suporte de vida e módulos biológicos.",
  ui_story_9_1_1_146_dialog_content = "Até aproveitei para melhorar a eficiência do motor!",
  ui_story_9_1_1_147_dialog_content = "Os componentes que você usou...",
  ui_story_9_1_1_148_dialog_content = "Você é mesmo um Celestita por sentir isso!",
  ui_story_9_1_1_149_dialog_content = "Sinto a presença da <color=#FFB400>Mantiz</color>.",
  ui_story_9_1_1_150_dialog_content = "A inspeção revelou uma semelhança de 99,9% entre as peças de Soroz e Mantiz.",
  ui_story_9_1_1_151_dialog_content = "A Mantiz é basicamente sucata agora...",
  ui_story_9_1_1_152_dialog_content = "Então usei tudo que pude em Soroz.",
  ui_story_9_1_1_153_dialog_content = "Vou dividir o Soroz com você, <color=#FFB400>Mendelson</color>!",
  ui_story_9_1_1_154_dialog_content = "Agora e pra sempre, Soroz será os seus olhos e ouvidos para absorver tudo acima das nuvens.",
  ui_story_9_1_1_155_dialog_content = "A morte é assim? É um pouco diferente... do que eu imaginei... Parece tão solitário...",
  ui_story_9_1_1_156_dialog_content = "(Mendelson, no final, você e o Mantiz nos ajudaram...)",
  ui_story_9_1_1_157_dialog_content = "Mas por que não sinto a presença do Soroz?",
  ui_story_9_1_1_158_dialog_content = "Bem... encontrei algo na ponte que poderia ser um componente.",
  ui_story_9_1_1_159_dialog_content = "Mas está danificado demais. Apenas esta pequena parte parece estar relativamente completa.",
  ui_story_9_1_1_160_dialog_content = "Isto... Lembro que Soroz disse que há um componente principal no Modelo Eco.",
  ui_story_9_1_1_161_dialog_content = "A consciência de uma Colossus está armazenada no núcleo.",
  ui_story_9_1_1_162_dialog_content = "Se essa coisa for o núcleo, talvez possamos restaurar a consciência de Soroz!",
  ui_story_9_1_1_163_dialog_content = "Excelente! Este é o núcleo?",
  ui_story_9_1_1_164_dialog_content = "Deve ser... Soroz mencionou o Modelo Eco antes, mas não o mostrou para mim...",
  ui_story_9_1_1_165_dialog_content = "Bem, não tem como a Colossus desconectá-lo só pra você dar uma olhada, certo?",
  ui_story_9_1_1_166_dialog_content = "Então... Você acha que este é o núcleo?",
  ui_story_9_1_1_167_dialog_content = "Acho que sim...",
  ui_story_9_1_1_168_dialog_content = "Bem, sabe como consertar?",
  ui_story_9_1_1_169_dialog_content = "...",
  ui_story_9_1_1_170_dialog_content = "Eu...",
  ui_story_9_1_1_171_dialog_content = "PlayerName e madame Gronru, nenhum de vocês tem ideia de como consertar?",
  ui_story_9_1_1_172_dialog_content = "Desculpe.",
  ui_story_9_1_1_173_dialog_content = "Não sou bom o suficiente para desvendar a tecnologia daquela era.",
  ui_story_9_1_1_174_dialog_content = "Eu... só aprendi um pouco sobre as Colossi com Soroz.",
  ui_story_9_1_1_175_dialog_content = "Mas isso nunca me incomodou, e nunca pensei que um dia... poderia perder o Soroz.",
  ui_story_9_1_1_X175_dialog_content = "Se eu tivesse me importado um pouco mais, talvez ...",
  ui_story_9_1_1_176_dialog_content = "Isso é um teste, PlayerName. Apenas elevando sua mente em isolamento você se tornará mais forte.",
  ui_story_9_1_1_177_dialog_content = "A realidade é que você está vivo, e meu dever é mantê-lo assim.",
  ui_story_9_1_1_178_dialog_content = "PlayerName, eu posso pairar até Lumópolis e encontrar você quando precisarem de mim.",
  ui_story_9_1_1_179_dialog_content = "Desculpa te fazer passar por isso, Soroz.",
  ui_story_9_1_1_180_dialog_content = "Pode me ouvir, Soroz?",
  ui_story_9_1_1_181_dialog_content = "Desculpe.",
  ui_story_9_1_1_182_dialog_content = "Desculpe por não cuidar de você.",
  ui_story_9_1_1_183_dialog_content = "PlayerName...",
  ui_story_9_1_1_184_dialog_content = "Não entendo. A Colossus não está mais resistente que antes?",
  ui_story_9_1_1_185_dialog_content = "Por que PlayerName está triste?",
  ui_story_9_1_1_186_dialog_content = "Shh, Raphaela.",
  ui_story_9_1_1_187_dialog_content = "Ah, perdão.",
  ui_story_9_1_1_188_dialog_content = "Você deixou Soroz para proteger o povo de Lumópolis, PlayerName.",
  ui_story_9_1_1_189_dialog_content = "Também sou responsável.",
  ui_story_9_1_1_190_dialog_content = "Agradeço toda a ajuda, mas não posso culpar vocês pelo que aconteceu com Soroz.",
  ui_story_9_1_1_191_dialog_content = "Isso tudo é obra da Schummer e dos Eclipsitas!",
  ui_story_9_1_1_192_dialog_content = "Verdade, Schummer, quase esqueci!",
  ui_story_9_1_1_193_dialog_content = "Tenho algo importante para te contar, Carleen.",
  ui_story_9_1_1_194_dialog_content = "O que foi?",
  ui_story_9_1_1_195_dialog_content = "Os Cavaleiros Lumo descobriram que a Aviduz caiu em <color=#FFB400>Eraveil</color>!",
  ui_story_9_1_1_196_dialog_content = "Entendi. Bom, então vamos para a cidade natal de PlayerName.",
  ui_story_9_1_1_197_dialog_content = "Eraveil?",
  ui_story_9_1_1_198_dialog_content = "Que irônico a Aviduz cair em Eraveil.",
  ui_story_9_1_1_199_dialog_content = "E tenho mais uma coisa para te dizer, PlayerName.",
  ui_story_9_1_1_200_dialog_content = "Aquele ataque específico de Aviduz na cidade, bem como os três módulos...",
  ui_story_9_1_1_201_dialog_content = "Eu informei Lumópolis sobre eles.",
  ui_story_9_1_1_202_dialog_content = "Espero que você entenda, PlayerName.",
  ui_story_9_1_1_203_dialog_content = "Tudo bem, eu entendo.",
  ui_story_9_1_1_204_dialog_content = "Os três módulos...",
  ui_story_9_1_1_205_dialog_content = "Você ainda se lembra de um dos três módulos, o <color=#FFB400>Módulo de Tanque Pensante</color>, PlayerName?",
  ui_story_9_1_1_206_dialog_content = "É claro. Eu até lembro que Mendelson disse...",
  ui_story_9_1_1_207_dialog_content = "Que muita informação é salva nele, quase tudo que você quiser.",
  ui_story_9_1_1_208_dialog_content = "Também lembro disso.",
  ui_story_9_1_1_209_dialog_content = "Encontre o Módulo de Tanque Pensante e saberemos como consertar o Modelo Eco!",
  ui_story_9_1_1_210_dialog_content = "Sim! PlayerName, Carleen...",
  ui_story_9_1_1_211_dialog_content = "Para Eraveil!",
  ui_story_9_1_1_212_dialog_content = "<color=#e8d9bb>Eraveil</color>",
  ui_story_9_1_1_213_dialog_content = "Como eu esperava, no fundo, você ainda é um Celestita...",
  ui_story_9_1_1_214_dialog_content = "Voltando a Eraveil, o túmulo de todos, só para morrer.",
  ui_story_9_1_1_215_dialog_content = "...",
  ui_story_9_1_1_216_dialog_content = "Você só serve para causar problemas aos outros.",
  ui_story_9_1_1_217_dialog_content = "Mas até conseguir o que quero, ",
  ui_story_9_1_1_218_dialog_content = "você não pode morrer.",
  ui_story_9_1_1_219_dialog_content = "*Tosse*",
  ui_story_9_1_1_220_dialog_content = "Finalmente acordou.",
  ui_story_9_1_1_221_dialog_content = "...Fico... muito brava quando... você é a primeira pessoa... que vejo...",
  ui_story_9_1_1_222_dialog_content = "Ótima maneira de agradecer quem te salvou depois da surra que levou.",
  ui_story_9_1_1_223_dialog_content = "Bobagem... *Tosse*",
  ui_story_9_1_1_224_dialog_content = "Admita, Schummer. Você perdeu. Muito feio.",
  ui_story_9_1_1_225_dialog_content = "Eu... não perdi... pra aqueles peões.",
  ui_story_9_1_1_226_dialog_content = "Humf, claro que não. Sabe por que perdeu?",
  ui_story_9_1_1_227_dialog_content = "Pare... *Tosse*",
  ui_story_9_1_1_228_dialog_content = "Porque você não é forte o suficiente.",
  ui_story_9_1_1_229_dialog_content = "Eu... eu não quero ouvir isso...",
  ui_story_9_1_1_230_dialog_content = "Posso te dar outra chance.",
  ui_story_9_1_1_231_dialog_content = "Só me ajude a completar o experimento e garanto que você saberá...",
  ui_story_9_1_1_232_dialog_content = "O que é ser invencível de verdade.",
  ui_story_9_1_1_233_dialog_content = "Mais uma chance? Aprimorar a Semente?",
  ui_story_9_1_1_234_dialog_content = "Ótimo, seu cérebro ainda funciona.",
  ui_story_9_1_1_235_dialog_content = "*Tosse* Eu tenho... apenas uma pergunta...",
  ui_story_9_1_1_236_dialog_content = "Você é muito irritante.",
  ui_story_9_1_1_237_dialog_content = "Por que está me ajudando?",
  ui_story_9_1_1_238_dialog_content = "Não se engane, eu só quero concluir o experimento.",
  ui_story_9_1_1_239_dialog_content = "...",
  ui_story_9_1_1_240_dialog_content = "E você, você é minha cobaia preferida.",
  ui_story_9_1_1_241_dialog_content = "...",
  ui_story_9_1_1_242_dialog_content = "Por que você me ajudaria?",
  ui_story_9_1_1_243_dialog_content = "Eu... sei que eles estavam errados...",
  ui_story_9_2_1_1_dialog_content = "Foi aqui que a Aviduz caiu... <color=#FFB400>Eraveil</color>.",
  ui_story_9_2_1_2_dialog_content = "É aqui...",
  ui_story_9_2_1_3_dialog_content = "(A terra natal com a qual sonhei por 17 anos...)",
  ui_story_9_2_1_4_dialog_content = "(Quase lá...)",
  ui_story_9_2_1_5_dialog_content = "Estamos todos com você, PlayerName.",
  ui_story_9_2_1_6_dialog_content = "Não esqueça que ainda estamos aqui, PlayerName.",
  ui_story_9_2_1_7_dialog_content = "Agradeço muito, Vice e Carleen.",
  ui_story_9_2_1_8_dialog_content = "Quantas vezes temos que dizer que não precisa agradecer?",
  ui_story_9_2_1_9_dialog_content = "Mesmo assim, preciso agradecer.",
  ui_story_9_2_1_10_dialog_content = "Por causa de vocês, tenho coragem de enfrentar o mundo.",
  ui_story_9_2_1_11_dialog_content = "Nesse caso, também tenho que agradecer vocês.",
  ui_story_9_2_1_12_dialog_content = "Porque me deram a oportunidade pra conhecer o mundo.",
  ui_story_9_2_1_13_dialog_content = "PlayerName, Carleen...",
  ui_story_9_2_1_14_dialog_content = "Nossa jornada está apenas começando!",
  ui_story_9_2_1_15_dialog_content = "Então alguém sabe que tipo de lugar Eraveil é?",
  ui_story_9_2_1_16_dialog_content = "Eu já li sobre, mas PlayerName deve saber mais.",
  ui_story_9_2_1_17_dialog_content = "Eraveil é minha casa. O clima é temperado o ano todo.",
  ui_story_9_2_1_18_dialog_content = "Mostre alguns vídeos de Eraveil, Soroz.",
  ui_story_9_2_1_19_dialog_content = "...",
  ui_story_9_2_1_20_dialog_content = "...",
  ui_story_9_2_1_21_dialog_content = "Soroz? Sor...",
  ui_story_9_2_1_22_dialog_content = "Uh, PlayerName, o Modelo Eco de Soroz está...",
  ui_story_9_2_1_23_dialog_content = "...",
  ui_story_9_2_1_24_dialog_content = "Mostre de novo, Soroz.",
  ui_story_9_2_1_25_dialog_content = "Mostrando Eraveil pela décima-sexta vez.",
  ui_story_9_2_1_26_dialog_content = "\"No sul da Espinha do Mundo, Eraveil é um vale fértil cercado por montanhas\".",
  ui_story_9_2_1_27_dialog_content = "\"O clima é temperado durante todo o ano e é o lar de gerações de Celestitas gentis e trabalhadores\".",
  ui_story_9_2_1_28_dialog_content = "O que são essas coisas, Soroz?",
  ui_story_9_2_1_29_dialog_content = "Dentes-de-leão. A parte amarela é a flor, a parte branca é a semente.",
  ui_story_9_2_1_30_dialog_content = "Por que não consigo pegar?",
  ui_story_9_2_1_31_dialog_content = "É só um vídeo, PlayerName.",
  ui_story_9_2_1_32_dialog_content = "Posso repetir o vídeo, se quiser.",
  ui_story_9_2_1_33_dialog_content = "Mostrando Eraveil pela décima-sétima vez.",
  ui_story_9_2_1_34_dialog_content = "...90ª vez.",
  ui_story_9_2_1_35_dialog_content = "...437ª vez.",
  ui_story_9_2_1_36_dialog_content = "...2.628ª vez.",
  ui_story_9_2_1_37_dialog_content = "Juro que recuperarei sua percepção, Soroz!",
  ui_story_9_2_1_38_dialog_content = "<color=#e8d9bb>Eraveil</color>",
  ui_story_9_2_1_39_dialog_content = "Estamos aqui.",
  ui_story_9_2_1_40_dialog_content = "Aqui é Eraveil?",
  ui_story_9_2_1_41_dialog_content = "Não é o que eu imaginei...",
  ui_story_9_2_1_42_dialog_content = "É completamente diferente do vídeo que assisti!",
  ui_story_9_2_1_43_dialog_content = "Tem certeza de que estamos no lugar certo?",
  ui_story_9_2_1_44_dialog_content = "Esta é a localização das coordenadas.",
  ui_story_9_2_1_45_dialog_content = "...",
  ui_story_9_2_1_46_dialog_content = "Ervas daninhas murchando em todos os lugares...",
  ui_story_9_2_1_47_dialog_content = "Ei, tem algumas pedras brancas embaixo da grama.",
  ui_story_9_2_1_48_dialog_content = "As pedras estão bem dispostas, provavelmente é a fundação de uma casa.",
  ui_story_9_2_1_49_dialog_content = "Aqui também... E ali...",
  ui_story_9_2_1_50_dialog_content = "Este deve ter sido um assentamento considerável.",
  ui_story_9_2_1_51_option_content = "Varredura Psíquica",
  ui_story_9_2_1_52_dialog_content = "(O Nada…)",
  ui_story_9_2_1_53_dialog_content = "Por que não sinto nada?",
  ui_story_9_2_1_54_dialog_content = "Já faz muito tempo, PlayerName. Até as rochas sofreram erosão.",
  ui_story_9_2_1_55_option_content = "Varredura Psíquica",
  ui_story_9_2_1_56_dialog_content = "...",
  ui_story_9_2_1_57_dialog_content = "Vamos em frente, PlayerName, talvez...",
  ui_story_9_2_1_58_option_content = "Varredura Psíquica",
  ui_story_9_2_1_59_dialog_content = "Atchim!",
  ui_story_9_2_1_60_dialog_content = "Cuidado, estou sentindo <color=#FFB400>Fluxo Escuro</color>!",
  ui_story_9_2_1_61_dialog_content = "É porque a Aviduz está perto?",
  ui_story_9_2_1_62_dialog_content = "Acho que não... O Fluxo Escuro é muito forte aqui. Parece que outra coisa entrou.",
  ui_story_9_2_1_63_dialog_content = "Você tá bem, PlayerName?",
  ui_story_9_2_1_64_dialog_content = "Muito bem.",
  ui_story_9_2_1_65_dialog_content = "Carleen, atrás de você!",
  ui_story_9_2_1_66_dialog_content = "Aahhhhhh!",
  ui_story_9_2_1_67_dialog_content = "Espalhar! Flor de Gelo!",
  ui_story_9_2_1_68_dialog_content = "Eclipsitas! Como ousam destruir o lar de PlayerName!",
  ui_story_9_2_1_69_dialog_content = "Assuma o comando, PlayerName!",
  ui_story_9_2_2_1_dialog_content = "<color=#e8d9bb>Dentro de Aviduz</color>",
  ui_story_9_2_2_2_dialog_content = "Não se mexa.",
  ui_story_9_2_2_3_dialog_content = "Esta é a <color=#FFB400>cápsula de cura</color>?",
  ui_story_9_2_2_4_dialog_content = "Está melhor?",
  ui_story_9_2_2_5_dialog_content = "Vejo que você já previu isso... *Tosse*",
  ui_story_9_2_2_6_dialog_content = "É por isso que... você colocou esse lixo na minha Colossus...",
  ui_story_9_2_2_7_dialog_content = "Olha o que fala.",
  ui_story_9_2_2_8_dialog_content = "Isso só parece... nojento.",
  ui_story_9_2_2_9_dialog_content = "Você não tem jeito.",
  ui_story_9_2_2_10_dialog_content = "Quê? Não... *Tosse*... Você não vai salvar sua cobaia preferida?",
  ui_story_9_2_2_11_dialog_content = "Eu já disse, você pode ter um poder incomparável se estiver disposta a deixar tudo que é Celestita para trás.",
  ui_story_9_2_2_12_dialog_content = "E eu te disse mais de uma vez que não sou mais um Celestita.",
  ui_story_9_3_2_1_dialog_content = "Ei, tem certeza que esse é o caminho?",
  ui_story_9_3_2_2_dialog_content = "Está duvidando de mim, o homem mais confiável de Rediesel Wrench?",
  ui_story_9_3_2_3_dialog_content = "Você que está mostrando o caminho esse tempo todo?",
  ui_story_9_3_2_4_dialog_content = "Que sorte encontrar uma bomba em um lugar como este!",
  ui_story_9_3_2_5_dialog_content = "Essa não é a granada que acabei de descartar?",
  ui_story_9_3_2_6_dialog_content = "Então estamos andando em círculos?",
  ui_story_9_3_2_7_dialog_content = "O que você tá falando? Eu segui o mapa!",
  ui_story_9_3_2_8_dialog_content = "Brock, idiota, o mapa está de cabeça para baixo!",
  ui_story_9_3_2_9_dialog_content = "É um milagre não estarmos mais perdidos ainda.",
  ui_story_9_3_2_10_dialog_content = "<size=45>Brock!</size>",
  ui_story_9_3_2_11_dialog_content = "Vou abrir seu crânio e descobrir o que exatamente tem de errado nessa cabeça!",
  ui_story_9_3_2_12_dialog_content = "♪Não tema, Barbara está aqui!",
  ui_story_9_3_2_13_dialog_content = "<anim type=Shake>♪Quando há amor, há esperança!</anim>",
  ui_story_9_3_2_14_dialog_content = "Argh! Não aguento mais, chefe! Posso acabar com ela?!",
  ui_story_9_3_2_X14_dialog_content = "O chefe disse que deveríamos tentar nos dar bem hoje. Eu nem sonharia em me rebaixar e gastar meu tempo te dando atenção!",
  ui_story_9_3_2_X15_dialog_content = "Se você não calar a boca, nem o chefe vai conseguir me impedir de acabar com você aqui e agora...",
  ui_story_9_3_2_15_dialog_content = "Ei... Por sinal, cadê o chefe?",
  ui_story_9_3_2_16_dialog_content = "Ei, algum de vocês sabe onde tá o chefe?",
  ui_story_9_3_2_17_dialog_content = "Minha aura de grandiosidade deve ter assustado ele! Eu sou o número 1!",
  ui_story_9_3_2_18_dialog_content = "Ele estava aqui agora mesmo.",
  ui_story_9_3_2_19_dialog_content = "Honcho Sinsa sumiu?",
  ui_story_9_3_2_20_dialog_content = "A Bopper também sumiu.",
  ui_story_9_3_2_21_dialog_content = "Em frente, seguidores!",
  ui_story_9_3_2_22_dialog_content = "Volta aqui, Brock!",
  ui_story_9_3_2_23_dialog_content = "<size=45><anim type=Shake>&*#%#%...!</anim></size>",
  ui_story_9_3_2_24_dialog_content = "<color=#e8d9bb>Pow!</color>",
  ui_story_9_3_2_25_dialog_content = "Ai, isso dói!",
  ui_story_9_3_2_26_dialog_content = "Ei, quem jogou a armadilha em mim?!",
  ui_story_9_3_2_27_dialog_content = "Só covardes armam emboscadas!",
  ui_story_9_3_2_28_dialog_content = "Saia e lute como um homem! Vou fazer picadinho de você!",
  ui_story_9_3_2_29_dialog_content = "Aquele lugar que pisamos não parecia nada diferente...",
  ui_story_9_3_2_30_dialog_content = "Pode parecer uma armadilha humana.",
  ui_story_9_3_2_31_dialog_content = "Mas, julgando pela folhagem que cobre o buraco...",
  ui_story_9_3_2_32_dialog_content = "Sai daí agora!",
  ui_story_9_3_2_33_dialog_content = "Você me ouviu, chefe?",
  ui_story_9_3_2_34_dialog_content = "O que você disse?",
  ui_story_9_3_2_35_dialog_content = "É um poço natural, não uma armadilha! Ninguém tá atacando!",
  ui_story_9_3_2_36_dialog_content = "...",
  ui_story_9_3_2_37_dialog_content = "Você não ouviu nada, Bopper, e não diga à minha irmãzinha que eu xinguei.",
  ui_story_9_3_2_38_dialog_content = "Tá, desde que você pare de fingir que não tá me ouvindo...",
  ui_story_9_3_2_39_dialog_content = "<anim type=Shake>Em frente, seguidores!</anim>",
  ui_story_9_3_2_40_dialog_content = "<anim type=Shake>Volta aqui, Brock!</anim>",
  ui_story_9_3_2_41_dialog_content = "Tá bom, tá bom...",
  ui_story_9_3_2_42_dialog_content = "Como não é uma armadilha, não precisamos nos preocupar em ser emboscados. Vamos sair daqui, rápido.",
  ui_story_9_3_2_X42_dialog_content = "Regina! Brock! Conseguem me ouvir?!",
  ui_story_9_3_2_43_dialog_content = "Com base em quanto tempo caímos e a aceleração gravitacional...",
  ui_story_9_3_2_44_dialog_content = "Eles não vão ouvir, não importa o quanto a gente grite.",
  ui_story_9_3_2_45_dialog_content = "Regina!",
  ui_story_9_3_2_46_dialog_content = "Vou contar pra Eve que você xingou, chefe!",
  ui_story_9_3_2_47_dialog_content = "Não, não... O que você disse sobre a coisa de tempo e aceleração?",
  ui_story_9_3_2_48_dialog_content = "Simplificando, o buraco é fundo demais para eles ouvirem.",
  ui_story_9_3_2_49_dialog_content = "*Tosse* Entendi...",
  ui_story_9_3_2_50_dialog_content = "Eu devia ter esperado uma análise sensata do piloto da <color=#FFB400>Lepidoz</color>.",
  ui_story_9_3_2_51_dialog_content = "Tudo bem, vamos andando e ver até onde esse buraco vai.",
  ui_story_9_3_2_52_dialog_content = "<color=#e8d9bb>Ding! Clang!</color>",
  ui_story_9_3_2_53_dialog_content = "Olha, chefe, quantas peças de Colossi aqui!",
  ui_story_9_3_2_54_dialog_content = "Uau, uma cabecinha tão redonda e uma asinha fofa... Que trabalho bom!",
  ui_story_9_3_2_55_dialog_content = "É minha primeira vez vendo um Vaga-lume tão lindo... Lepidoz vai adorar, com certeza!",
  ui_story_9_3_2_56_dialog_content = "Essa coisa só tem a asa esquerda. Não serve pra nada além de uma bola de futebol.",
  ui_story_9_3_2_57_dialog_content = "Tem mais ali! Vou levar esse e aquele...",
  ui_story_9_3_2_58_dialog_content = "Deixa um espaço para o que realmente viemos fazer aqui!",
  ui_story_9_3_2_59_dialog_content = "Eu sei, mas também prometi a Lepidoz que levaria lembrancinhas.",
  ui_story_9_3_2_60_dialog_content = "Certeza que vamos achar ainda mais objetos de valor assim que encontrarmos a Colossus Negra que caiu.",
  ui_story_9_3_2_61_dialog_content = "Hum...",
  ui_story_9_3_2_62_dialog_content = "Mas por que teria tantas peças espalhadas nesta caverna?",
  ui_story_9_3_2_63_dialog_content = "Não me diga que encontramos...",
  ui_story_9_3_2_64_dialog_content = "?",
  ui_story_9_3_2_65_dialog_content = "Temos que achar uma saída!",
  ui_story_9_3_2_66_dialog_content = "Sinto que tem mais alguém aqui além de nós.",
  ui_story_9_4_1_1_dialog_content = "Algo está errado!",
  ui_story_9_4_1_2_dialog_content = "Empale os inimigos!",
  ui_story_9_4_1_3_dialog_content = "Hei garotinha, melhor repensar esse ataque surpresa.",
  ui_story_9_4_1_4_dialog_content = "Vocês são Aurorians?",
  ui_story_9_4_1_5_dialog_content = "Não é uma lutadora ruim, mas seu julgamento deixa a desejar.",
  ui_story_9_4_1_6_dialog_content = "Você...!",
  ui_story_9_4_1_7_dialog_content = "O que foi, Carleen?",
  ui_story_9_4_1_8_dialog_content = "Você tá bem, Chefe?",
  ui_story_9_4_1_9_dialog_content = "Estou!",
  ui_story_9_4_1_10_dialog_content = "É você!",
  ui_story_9_4_1_11_dialog_content = "Você conhece esse delinquente da Rediesel Wrench, PlayerName?",
  ui_story_9_4_1_12_option_content = "Quando eu estava na Illumina...",
  ui_story_9_4_1_13_dialog_content = "Depois que Soroz e eu saímos de baixo da superfície, batemos perto de uma Subcidade.",
  ui_story_9_4_1_14_dialog_content = "Ele era o líder dos bandidos.",
  ui_story_9_4_1_15_dialog_content = "Por que falar isso? Nós salvamos você dos Eclipsitas, tá?",
  ui_story_9_4_1_16_dialog_content = "No Deserto Rediesel, Soroz quase foi saqueado e desmontado por aquele cara!",
  ui_story_9_4_1_17_option_content = "Quando eu tava no Deserto Rediesel...",
  ui_story_9_4_1_18_dialog_content = "Ele nos interceptou com sua gangue quando tentamos sair.",
  ui_story_9_4_1_19_dialog_content = "E ele quase conseguiu.",
  ui_story_9_4_1_20_dialog_content = "Bem, não posso falar nada. Isso foi  culpa minha.",
  ui_story_9_4_1_21_dialog_content = "Foi graças a você que minha irmã foi resgatada.",
  ui_story_9_4_1_22_dialog_content = "Te devo uma, PlayerName.",
  ui_story_9_4_1_23_dialog_content = "Você já esteve no Deserto Rediesel?",
  ui_story_9_4_1_24_dialog_content = "Depois que saímos de Lumópolis da última vez.",
  ui_story_9_4_1_25_dialog_content = "Vejo que a princesa de Lumópolis ainda é agressiva.",
  ui_story_9_4_1_26_dialog_content = "Atacar antes de saber o que está acontecendo... E se machucar algum inocente?",
  ui_story_9_4_1_27_dialog_content = "Ela não fez de propósito, Sinsa.",
  ui_story_9_4_1_28_dialog_content = "Isso foi culpa minha, de fato.",
  ui_story_9_4_1_29_dialog_content = "Eu, Carleen de Schwartz, peço desculpas por minhas ações.",
  ui_story_9_4_1_30_dialog_content = "Mas se você insiste em falar mal de Lumópolis...",
  ui_story_9_4_1_31_dialog_content = "Agora podemos acertar as contas entre nós.",
  ui_story_9_4_1_X31_dialog_content = "Se você quiser lutar, você podia escolher uma hora e um lugar melhor né?!",
  ui_story_9_4_1_32_dialog_content = "Ela é agressiva, não é, PlayerName? Por que vocês estão trabalhando juntos?",
  ui_story_9_4_1_33_dialog_content = "Bem, eu não sei qual é a briga entre vocês dois...",
  ui_story_9_4_1_34_dialog_content = "Mas já que vocês lutaram junto com a Vice e eu, espero que possamos colocar as diferenças de lado por enquanto.",
  ui_story_9_4_1_35_dialog_content = "Claro, vou fazer o que PlayerName disse.",
  ui_story_9_4_1_36_dialog_content = "Essa fala é minha.",
  ui_story_9_4_1_X36_dialog_content = "Tenha em mente que parei só porque tenho outras missões para cumprir. Não tenho tempo a perder com você.",
  ui_story_9_4_1_X37_dialog_content = "Hah, não posso acreditar que você disse isso...",
  ui_story_9_4_1_37_dialog_content = "Ahem! Ei! Vamos mudar de assunto, Sinsa...",
  ui_story_9_4_1_38_option_content = "Quem é a garota atrás de você?",
  ui_story_9_4_1_39_dialog_content = "Ah, é a Bopper.",
  ui_story_9_4_1_40_dialog_content = "Olá, sou a Bopper.",
  ui_story_9_4_1_41_dialog_content = "Então você é PlayerName? Eve fala muito de você!",
  ui_story_9_4_1_42_dialog_content = "Vimos uma Colossus Negra cair por aqui e viemos procurar.",
  ui_story_9_4_1_43_dialog_content = "Aí, caímos num buraco e encontramos vocês depois que saímos.",
  ui_story_9_4_1_44_option_content = "O que está fazendo aqui?",
  ui_story_9_4_1_45_dialog_content = "Claro, estamos aqui pelos espólios! Hahahahaha!",
  ui_story_9_4_1_46_dialog_content = "Espólio? O que você quer dizer?",
  ui_story_9_4_1_47_dialog_content = "Vimos uma Colossus Negra cair por aqui e viemos procurar.",
  ui_story_9_4_1_48_dialog_content = "Aí, caímos num buraco e encontramos vocês depois que saímos.",
  ui_story_9_4_1_49_dialog_content = "Oi, sou a Bopper. Você deve ser PlayerName? Eva fala muito de você!",
  ui_story_9_4_1_50_dialog_content = "Você também tá caçando tesouros, PlayerName?",
  ui_story_9_4_1_51_dialog_content = "Bom, é uma longa história...",
  ui_story_9_4_1_52_dialog_content = "<color=#e8d9bb>Mais tarde...</color>",
  ui_story_9_4_1_53_dialog_content = "<size=45>Eraveil?!</size>",
  ui_story_9_4_1_54_dialog_content = "Então aqui é Eraveil...",
  ui_story_9_4_1_55_dialog_content = "Você já passou por muita coisa em pouco tempo, PlayerName.",
  ui_story_9_4_1_56_dialog_content = "Deve ser a provação e os tormentos que devo passar para voltar ao mundo da superfície.",
  ui_story_9_4_1_57_dialog_content = "Mas não vou perder a esperança.",
  ui_story_9_4_1_58_dialog_content = "Estou emocionada, então irei com você nesta viagem.",
  ui_story_9_4_1_59_dialog_content = "Hã?",
  ui_story_9_4_1_60_dialog_content = "Objeções?",
  ui_story_9_4_1_61_dialog_content = "Nenhuma. Bem-vinda ao time!",
  ui_story_9_4_1_62_dialog_content = "Precisamos de toda a ajuda que tivermos.",
  ui_story_9_4_1_63_dialog_content = "Acho que temos um consenso!",
  ui_story_9_4_1_64_dialog_content = "Mas e quanto a Regina e os outros?",
  ui_story_9_4_1_65_dialog_content = "Isso aí... Me diz, você viu mais alguém de Rediesel Wrench no caminho?",
  ui_story_9_4_1_66_dialog_content = "Tem mais de vocês?",
  ui_story_9_4_1_X66_dialog_content = "Sim, nós amamos passeios em grupo em Rediesel Wrench.",
  ui_story_9_4_1_67_dialog_content = "Não vimos ninguém além de Eclipsitas.",
  ui_story_9_4_1_X67_dialog_content = "Ai...",
  ui_story_9_4_1_68_dialog_content = "Bem, assim que você acaba de falar, os Eclipsitas aparecem... Típico.",
  ui_story_9_4_1_69_dialog_content = "Deixa eu ver se sua liderança melhorou, PlayerName!",
  ui_story_9_4_2_1_dialog_content = "(Falando em Eclipsiano) Um grupo de Aurorians se aproximando, minha senhora.",
  ui_story_9_4_2_2_dialog_content = "(Falando em Eclipsiano) Eles também estão com um Celestita.",
  ui_story_9_4_2_3_dialog_content = "(Falando em eclipsiano) Mas somos poucos para impedi-los.",
  ui_story_9_4_2_4_dialog_content = "Celestita?",
  ui_story_9_4_2_5_dialog_content = "Será que é PlayerName?",
  ui_story_9_4_2_6_dialog_content = "Não, o lixo deve ser...",
  ui_story_9_4_2_7_dialog_content = "...",
  ui_story_9_4_2_8_dialog_content = "Você não serve para nada, Schummer.",
  ui_story_9_4_2_9_dialog_content = "(Falando em Eclipsiano) Vá e me traga os peões de Lumópolis.",
  ui_story_9_4_2_10_dialog_content = "(Falando em Eclipsiano) Sim, senhora.",
  ui_story_9_4_2_11_dialog_content = "Eu desprezo complicações...",
  ui_story_9_4_2_12_dialog_content = "e odeio desperdiçar recursos.",
  ui_story_9_4_2_13_dialog_content = "Mas nada deve interromper o experimento.",
  ui_story_9_5_2_1_dialog_content = "<color=#e8d9bb>Esconderijo Secreto da True Order</color>",
  ui_story_9_5_2_2_dialog_content = "Qual é o seu pedido, Lady Victoria?",
  ui_story_9_5_2_3_dialog_content = "Você deve coletar mais <color=#FFB400>Sementes</color> para o grande Senhor da Verdade, Faust.",
  ui_story_9_5_2_4_dialog_content = "Será uma honra, Lady Victoria.",
  ui_story_9_5_2_5_dialog_content = "Traga Pact e Nails com você.",
  ui_story_9_5_2_6_dialog_content = "Sim, Lady Victoria. Que a Verdade lhe abençoe.",
  ui_story_9_5_2_7_dialog_content = "Foi isso que você falou antes?",
  ui_story_9_5_2_8_dialog_content = "O poder das trevas que é temido e cobiçado.",
  ui_story_9_5_2_9_dialog_content = "Existem indivíduos que, vivendo sob o sol brilhante, trairiam a Verdade e buscariam voluntariamente o poder da Semente.",
  ui_story_9_5_2_10_dialog_content = "Que pena dos que deram as costas para sua natureza Aurorian.",
  ui_story_9_5_2_11_dialog_content = "Tem certeza de que deseja ingerir isso?",
  ui_story_9_5_2_12_dialog_content = "Ah, esqueci, você é só um livro e provavelmente não sabe sobre a natureza.",
  ui_story_9_5_2_13_dialog_content = "Victoria Varaki.",
  ui_story_9_5_2_X13_dialog_content = "Chega. Tudo que você precisa fazer é colocar em mim.",
  ui_story_9_5_2_14_dialog_content = "Certo. Vamos ver se consegue devorar.",
  ui_story_9_5_2_15_dialog_content = "<color=#e8d9bb>Crunch! Gulp!</color>",
  ui_story_9_5_2_16_dialog_content = "Qual o gosto?",
  ui_story_9_5_2_17_dialog_content = "Tem um gosto de carne.",
  ui_story_9_5_2_18_dialog_content = "Esta é uma Semente extraída de um Celestita.",
  ui_story_9_5_2_19_dialog_content = "Celestita?",
  ui_story_9_5_2_20_dialog_content = "Então tem interesse na carne de Celestita agora?",
  ui_story_9_5_2_21_dialog_content = "Cuidado com suas palavras, Victoria Varaki!",
  ui_story_9_5_2_22_dialog_content = "Parece que você está aceitando muito bem.",
  ui_story_9_5_2_23_dialog_content = "Este é só o começo.",
  ui_story_9_5_2_24_dialog_content = "Sim. Está ficando cada vez mais intrigante.",
  ui_story_9_5_2_25_dialog_content = "Não esqueça do pacto que fizemos.",
  ui_story_9_5_2_26_dialog_content = "Como esqueceria? Já mandei mais gente buscar as Sementes.",
  ui_story_9_5_2_27_dialog_content = "Também não esqueça dos que você deve eliminar.",
  ui_story_9_5_2_28_dialog_content = "Não seja ganancioso.",
  ui_story_9_5_2_29_dialog_content = "Devemos esperar a oportunidade chegar.",
  ui_story_9_5_2_30_dialog_content = "<color=#e8d9bb>Em Eraveil</color>",
  ui_story_9_5_2_31_dialog_content = "Nada mal!",
  ui_story_9_5_2_32_dialog_content = "Você está ficando melhor nessa coisa de líder!",
  ui_story_9_5_2_33_dialog_content = "Valeu...",
  ui_story_9_5_2_X33_dialog_content = "*Cof*",
  ui_story_9_5_2_34_dialog_content = "Qual o problema, PlayerName?",
  ui_story_9_5_2_35_option_content = "Tá frio...",
  ui_story_9_5_2_36_dialog_content = "Aqui, beba um pouco de água quente.",
  ui_story_9_5_2_37_dialog_content = "Não esperava que você fosse tão atencioso...",
  ui_story_9_5_2_38_dialog_content = "Ele sempre carrega uma garrafa térmica pra irmãzinha dele.",
  ui_story_9_5_2_39_dialog_content = "Não é nada. Já acostumei.",
  ui_story_9_5_2_40_option_content = "Nada...",
  ui_story_9_5_2_41_dialog_content = "Me dá suas mãos, PlayerName.",
  ui_story_9_5_2_42_dialog_content = "Que mãos geladas!",
  ui_story_9_5_2_43_dialog_content = "Estou bem, Vice.",
  ui_story_9_5_2_44_dialog_content = "Estranho, por que está ficando mais frio conforme vamos indo?",
  ui_story_9_5_2_45_dialog_content = "Eraveil não deveria ser quente?",
  ui_story_9_5_2_46_dialog_content = "...",
  ui_story_9_5_2_47_dialog_content = "Cuidado, pessoal, o Fluxo Escuro está ficando mais intenso!",
  ui_story_9_5_2_48_dialog_content = "Acho que Eraveil se transformou em um covil para Eclipsitas.",
  ui_story_9_5_2_49_dialog_content = "!",
  ui_story_9_5_2_50_dialog_content = "Isso explicaria as hordas de Eclipsitas que encontramos.",
  ui_story_9_5_2_51_dialog_content = "Talvez não seja coincidência que a Aviduz tenha caído aqui.",
  ui_story_9_5_2_52_dialog_content = "Será que...",
  ui_story_9_7_1_1_dialog_content = "Graaah!",
  ui_story_9_7_1_2_dialog_content = "Ah, mais insetos?",
  ui_story_9_7_1_3_dialog_content = "Tá bom! Tá legal!",
  ui_story_9_7_1_4_dialog_content = "O que está fazendo, Bopper?",
  ui_story_9_7_1_5_dialog_content = "Procurando objetos de valor.",
  ui_story_9_7_1_6_dialog_content = "Por que você está revirando lixo?",
  ui_story_9_7_1_7_dialog_content = "Isso não é lixo, chefe!",
  ui_story_9_7_1_8_dialog_content = "Esta peça é perfeita para Lepidoz!",
  ui_story_9_7_1_9_dialog_content = "E eu nunca vi esse parafuso antes... Tenho que mostrar pra Tiny One!",
  ui_story_9_7_1_10_dialog_content = "E olha só, eu coletei vaga-lume vermelho, amarelo, azul e verde!",
  ui_story_9_7_1_11_dialog_content = "Bom trabalho, Bopper.",
  ui_story_9_7_1_12_dialog_content = "Nem percebi que haviam coisas tão legais aqui!",
  ui_story_9_7_1_13_dialog_content = "Ah, tem mais...",
  ui_story_9_7_1_14_dialog_content = "O que é isso, PlayerName?",
  ui_story_9_7_1_15_dialog_content = "Peças de Colossus, mas não da Aviduz...",
  ui_story_9_7_1_16_dialog_content = "Elas se separaram das outras Colossus?",
  ui_story_9_7_1_17_dialog_content = "Naquela noite há 17 anos?",
  ui_story_9_7_1_18_dialog_content = "A julgar pelo dano causado, foi uma atrocidade.",
  ui_story_9_7_1_19_dialog_content = "...",
  ui_story_9_7_1_20_dialog_content = "Eu sinto muito. Achei um desperdício deixá-las aqui.",
  ui_story_9_7_1_21_dialog_content = "Mas se PlayerName achar isso ofensivo, não vou levar nada...",
  ui_story_9_7_1_22_dialog_content = "Eu não ligo, Bopper.",
  ui_story_9_7_1_23_dialog_content = "Tenho certeza de que elas gostariam de um lar e de alguém que cuidasse delas.",
  ui_story_9_7_1_24_dialog_content = "Sério? Valeu, PlayerName!",
  ui_story_9_7_1_25_dialog_content = "Bopper!",
  ui_story_9_7_1_26_dialog_content = "Mas PlayerName já disse que tudo bem...",
  ui_story_9_7_1_27_dialog_content = "Não sabemos até onde temos que ir e nem em quantas lutas vamos entrar.",
  ui_story_9_7_1_28_dialog_content = "Você tem que aprender a eleger prioridades.",
  ui_story_9_7_1_29_dialog_content = "Tá bom...",
  ui_story_9_7_1_30_dialog_content = "Posso ficar com essa, então?",
  ui_story_9_7_1_31_dialog_content = "Tudo bem, é pequena.",
  ui_story_9_7_1_32_dialog_content = "!",
  ui_story_9_7_1_33_dialog_content = "Você reconhece isso, Carleen?",
  ui_story_9_7_1_34_dialog_content = "É um distintivo de <color=#FFB400>Guarda Lumo</color>... Mas como veio parar aqui?",
  ui_story_9_7_1_35_dialog_content = "Onde você achou isso, Bopper?",
  ui_story_9_7_1_36_dialog_content = "Na encruzilhada onde os Eclipsitas nos atacaram.",
  ui_story_9_7_1_37_dialog_content = "Posso ver?",
  ui_story_9_7_1_38_dialog_content = "Claro.",
  ui_story_9_7_1_39_option_content = "Varredura Psíquica",
  ui_story_9_7_1_40_dialog_content = "Finalmente, estou com o distintivo!",
  ui_story_9_7_1_41_dialog_content = "Você está vendo isso, mãe?",
  ui_story_9_7_1_42_dialog_content = "Seu filho agora é um Guarda Lumo oficial!",
  ui_story_9_7_1_43_dialog_content = "Não tenho mais que servir aos mesquinhos da Cidade Alta!",
  ui_story_9_7_1_44_dialog_content = "Mas você já se foi...",
  ui_story_9_7_1_45_dialog_content = "Por que está parado como um idiota, novato? Vá lutar contra os Eclipsitas!",
  ui_story_9_7_1_46_dialog_content = "Sim!",
  ui_story_9_7_1_47_dialog_content = "Aahhhhhh!",
  ui_story_9_7_1_48_dialog_content = "Me abençoe e proteja, mãe!",
  ui_story_9_7_1_49_dialog_content = "Onde... estou?",
  ui_story_9_7_1_50_dialog_content = "(Falando em Eclipsiano) Estes são os prisioneiros de Lumópolis, senhora.",
  ui_story_9_7_1_51_dialog_content = "(Falando em Eclipsiano) Muito bem.",
  ui_story_9_7_1_52_dialog_content = "Eclipsitas? O que estão fazendo comigo?",
  ui_story_9_7_1_53_dialog_content = "Me solta!",
  ui_story_9_7_1_54_dialog_content = "Não tenha medo, não vai doer nada.",
  ui_story_9_7_1_55_dialog_content = "Não chegue perto! Fique onde está!",
  ui_story_9_7_1_56_dialog_content = "Aaai!",
  ui_story_9_7_1_57_dialog_content = "!",
  ui_story_9_7_1_58_dialog_content = "O que está vendo, PlayerName?",
  ui_story_9_7_1_59_dialog_content = "Eu vejo...",
  ui_story_9_7_1_60_option_content = "Um guarda.",
  ui_story_9_7_1_61_dialog_content = "Este distintivo pertencia a um Guarda Lumo.",
  ui_story_9_7_1_62_dialog_content = "!",
  ui_story_9_7_1_63_dialog_content = "Ele foi enviado pra batalha logo após se juntar à Guarda.",
  ui_story_9_7_1_64_dialog_content = "Mas, no fim, ele foi transformado em um Eclipsita.",
  ui_story_9_7_1_65_option_content = "Eclipsita?",
  ui_story_9_7_1_66_dialog_content = "Este distintivo pertencia a um Eclipsita.",
  ui_story_9_7_1_67_dialog_content = "Impossível!",
  ui_story_9_7_1_68_dialog_content = "Mas o Eclipsita era um Guarda Lumo.",
  ui_story_9_7_1_69_dialog_content = "Como assim? É um Guarda ou um Eclipsita?",
  ui_story_9_7_1_70_dialog_content = "Alguém forçou este guarda a se transformar em um Eclipsita...",
  ui_story_9_7_1_71_dialog_content = "E eu sei exatamente quem foi... <color=#FFB400>Forsakin</color>!",
  ui_story_9_7_1_72_dialog_content = "A figura misteriosa ao lado de Schummer?",
  ui_story_9_7_1_73_dialog_content = "Sim! Lembra da Semente que você arrancou de mim, Vice?",
  ui_story_9_7_1_74_dialog_content = "Sim, quase te transformou em um Eclipsita!",
  ui_story_9_7_1_75_dialog_content = "Uau! Sério?",
  ui_story_9_7_1_76_dialog_content = "Eu vi Forsakin colocando a Semente no corpo do guarda.",
  ui_story_9_7_1_77_dialog_content = "!",
  ui_story_9_7_1_78_dialog_content = "E um homem com uma mala branca dizia que...",
  ui_story_9_7_1_79_dialog_content = "A Semente é a única forma de transformar outras criaturas em Eclipsitas.",
  ui_story_9_7_1_80_dialog_content = "Quer dizer que a Forsakin transformou um Guarda Lumo em Eclipsita?",
  ui_story_9_7_1_81_dialog_content = "Sim.",
  ui_story_9_7_1_82_dialog_content = "Então o Eclipsita que acabamos de matar era um guarda de Lumópolis?",
  ui_story_9_7_1_83_dialog_content = "Sim...",
  ui_story_9_7_1_84_dialog_content = "...",
  ui_story_9_7_1_85_dialog_content = "Parem de se culpar e ficar tristes!",
  ui_story_9_7_1_86_dialog_content = "Não matamos o guarda. Foi a Forsakin!",
  ui_story_9_7_1_87_dialog_content = "Sinsa está certo.",
  ui_story_9_7_1_88_dialog_content = "Apesar que matamos esse guarda com nossas mãos...",
  ui_story_9_7_1_89_dialog_content = "Mas se não fosse por Forsakin, ele não teria se tornado um Eclipsita.",
  ui_story_9_7_1_90_dialog_content = "...",
  ui_story_9_7_1_91_dialog_content = "Srta. Carleen...",
  ui_story_9_7_1_92_dialog_content = "Acho melhor você pegar o distintivo.",
  ui_story_9_7_1_93_dialog_content = "... Tá bem.",
  ui_story_9_7_1_94_dialog_content = "Eu, Carleen de Schwartz, lamento os mortos.",
  ui_story_9_7_1_95_dialog_content = "Um guarda de Lumópolis, portador deste distintivo.",
  ui_story_9_7_1_96_dialog_content = "Ele serviu bem seu posto e lutou bravamente.",
  ui_story_9_7_1_97_dialog_content = "Embora tenha sido capturado, se tornado um Eclipsita e atacado Aurorians, não foi por sua vontade.",
  ui_story_9_7_1_98_dialog_content = "Por favor, perdoe-nos por acabar com o sofrimento dele.",
  ui_story_9_7_1_99_dialog_content = "Que ele descanse em paz. Noite branca sempre.",
  ui_story_9_7_1_100_dialog_content = "Descanse em paz...",
  ui_story_9_7_1_101_dialog_content = "...",
  ui_story_9_7_1_102_dialog_content = "Aviduz, Eraveil, Forsakin... Isso é muito estranho.",
  ui_story_9_7_1_103_dialog_content = "Estou com um mau pressentimento...",
  ui_story_9_7_1_104_dialog_content = "Schummer...",
  ui_story_9_7_1_105_dialog_content = "Schummer ainda está viva?",
  ui_story_9_7_1_106_dialog_content = "!",
  ui_story_9_7_1_107_dialog_content = "Bom, temos que ir rápido!",
  ui_story_9_7_1_108_dialog_content = "Aahhhhhh!",
  ui_story_9_7_1_109_dialog_content = "Cuidado, lá vem outro!",
  ui_story_9_7_1_110_dialog_content = "Um Eclipsita de alto nível?",
  ui_story_9_7_1_111_dialog_content = "Nunca vi um Eclipsita tão ferido antes.",
  ui_story_9_7_1_112_dialog_content = "<anim type=Shake>Quero... casa...</anim>",
  ui_story_9_7_1_113_dialog_content = "<anim type=Shake>Quero... ir... casa...</anim>",
  ui_story_9_7_1_114_dialog_content = "Está falando Universês?",
  ui_story_9_7_1_115_dialog_content = "Não tenho ideia do que está tentando dizer...",
  ui_story_9_7_1_116_dialog_content = "Eu sinto a aura Aurorian nele.",
  ui_story_9_7_1_117_dialog_content = "Também era um Aurorian?",
  ui_story_9_7_1_118_dialog_content = "!",
  ui_story_9_7_1_119_dialog_content = "Eu consigo sentir as fortes emoções dele...",
  ui_story_9_7_1_120_dialog_content = "Dor, desespero, raiva, desamparo… Tudo reprimido.",
  ui_story_9_7_1_121_dialog_content = "O pobre Aurorian só quer ir para casa...",
  ui_story_9_7_1_122_dialog_content = "...",
  ui_story_9_7_1_123_dialog_content = "<anim type=Shake>Growl!</anim>",
  ui_story_9_7_1_124_dialog_content = "Parece que não sabe que foi transformado em um Eclipsita. Você não pode voltar pra casa, guarda...",
  ui_story_9_7_1_125_dialog_content = "Vamos acabar com seu sofrimento!",
  ui_story_9_7_2_1_dialog_content = "<anim type=Shake>Casa... Ir... Casa...</anim>",
  ui_story_9_7_2_2_dialog_content = "Noite Branca sempre, que você descanse em paz.",
  ui_story_9_7_2_3_dialog_content = "Você não está mais atormentado por sua forma física.",
  ui_story_9_7_2_4_dialog_content = "Desculpa não conseguir te libertar...",
  ui_story_9_7_2_5_dialog_content = "Fizemos o possível para minimizar seus sofrimentos na batalha.",
  ui_story_9_7_2_6_dialog_content = "Não se culpe, PlayerName.",
  ui_story_9_7_2_X6_dialog_content = "Agora, a única coisa que podemos fazer por esses Aurorians é encontrar Forsakin e detê-la.",
  ui_story_9_7_2_7_dialog_content = "Certo.",
  ui_story_9_7_2_8_dialog_content = "Verdade, temos que encontrar Forsakin e impedi-la de criar mais Eclipsitas!",
  ui_story_9_7_2_9_dialog_content = "Quem é essa Forsakin? O nome parece de um Aurorian.",
  ui_story_9_7_2_10_option_content = "Sim.",
  ui_story_9_7_2_11_dialog_content = "Sua estatura física, aura e jeito são parecidos com os dos Aurorians.",
  ui_story_9_7_2_12_dialog_content = "Mas ela se alinhou com os Eclipsitas.",
  ui_story_9_7_2_13_dialog_content = "E Vivian revelou que Forsakin já serviu Illumina...",
  ui_story_9_7_2_14_option_content = "Não.",
  ui_story_9_7_2_15_dialog_content = "Forsakin pode ter sido Aurorian, mas agora ela está do lado dos Eclipsitas.",
  ui_story_9_7_2_16_dialog_content = "Mas Vivian disse que ela já serviu Illumina...",
  ui_story_9_7_2_17_dialog_content = "Vivian?",
  ui_story_9_7_2_18_dialog_content = "A Chefe de Gabinete da Illumina, minha superior.",
  ui_story_9_7_2_19_dialog_content = "Antes de partirmos, ela disse pra tomarmos cuidado com a Forsakin.",
  ui_story_9_7_2_20_dialog_content = "Ela acertou em cheio.",
  ui_story_9_7_2_21_dialog_content = "Não entendo. Se Forsakin realmente trabalhou para a Illumina...",
  ui_story_9_7_2_22_dialog_content = "Como ela pôde ser tão insensível?",
  ui_story_9_7_2_23_dialog_content = "É como se ela estivesse obcecada em transformar Aurorians em Eclipsitas.",
  ui_story_9_7_2_24_dialog_content = "Nunca ouvi falar de alguém assim quando estive na Illumina...",
  ui_story_9_7_2_25_dialog_content = "Não acho que os chefões da Illumina te contariam uma coisa dessas.",
  ui_story_9_7_2_26_dialog_content = "Sinsa, sei que você não confia em Illumina pelo que aconteceu com Eva...",
  ui_story_9_7_2_27_dialog_content = "Mas os oficiais da Illumina estão sempre na frente da batalha, servindo de exemplo para aqueles que lutam sob eles...",
  ui_story_9_7_2_X27_dialog_content = "Talvez eles tenham investigado todo esse tempo...",
  ui_story_9_7_2_28_dialog_content = "Heh. Você deve ser ingênua para ainda acreditar nisso.",
  ui_story_9_7_2_29_dialog_content = "Minha irmã Eve sofreu uma complicação depois de ser atacada por Eclipsitas.",
  ui_story_9_7_2_30_dialog_content = "Eu acreditei na gloriosa propaganda da Illumina e a enviei para receber tratamento.",
  ui_story_9_7_2_31_dialog_content = "...",
  ui_story_9_7_2_32_dialog_content = "E o que aconteceu? Eles não só não conseguiram curar ela, como ela quase morreu em um incêndio!",
  ui_story_9_7_2_33_dialog_content = "O incêndio...",
  ui_story_9_7_2_34_dialog_content = "!",
  ui_story_9_7_2_35_dialog_content = "Eu deveria ter feito a conexão antes... Forsakin tem cicatrizes de um incêndio no rosto.",
  ui_story_9_7_2_36_dialog_content = "O que você disse?!",
  ui_story_9_7_2_37_dialog_content = "Incêndio em Illumina...",
  ui_story_9_7_2_38_dialog_content = "Aaai!",
  ui_story_9_7_2_39_dialog_content = "As cicatrizes da Forsakin...",
  ui_story_9_7_2_40_dialog_content = "Olha meu rosto, essas cicatrizes... Foram queimadas em minha carne por chamas abrasadoras. Tá vendo?",
  ui_story_9_7_2_41_dialog_content = "Será que...",
  ui_story_9_7_2_42_dialog_content = "Deixa eu perguntar uma coisa, Sinsa... O que aconteceu com o responsável pelo tratamento de Eve?",
  ui_story_9_7_2_43_dialog_content = "Quando cheguei à Illumina, disseram que...",
  ui_story_9_7_2_44_dialog_content = "O responsável pelo tratamento experimental morreu no incêndio.",
  ui_story_9_7_2_45_dialog_content = "Isso é verdade?",
  ui_story_9_7_2_46_dialog_content = "É claro que não acreditei nessa explicação.",
  ui_story_9_7_2_47_dialog_content = "Mas eles se recusaram a falar o nome da pessoa.",
  ui_story_9_7_2_48_dialog_content = "Então enviei meu próprio pessoal.",
  ui_story_9_7_2_49_dialog_content = "Mas não conseguiram descobrir nada novo.",
  ui_story_9_7_2_50_dialog_content = "Mas nunca vou esquecer o nome da pessoa, enquanto eu viver... <color=#FFB400>Denier</color>.",
  ui_story_9_7_2_X50_dialog_content = "As informações que obtivemos antes nos colocaram no caminho errado. Todos pensamos que a pesquisadora morreu no incêndio.",
  ui_story_9_7_2_51_dialog_content = "Por isso não reconhecemos Forsakin quando a vimos!",
  ui_story_9_7_2_52_dialog_content = "Certo... Mas pensando nisso agora, acho que a Forsakin é Denier.",
  ui_story_9_7_2_53_dialog_content = "!",
  ui_story_9_7_2_54_dialog_content = "Aaai!",
  ui_story_9_7_2_55_dialog_content = "Eve...",
  ui_story_9_7_2_56_dialog_content = "Droga, vou tirar a verdade dessa Forsakin!",
  ui_story_9_7_2_57_dialog_content = "Se ela machucou a Eve, vai pagar!",
  ui_story_9_8_1_1_dialog_content = "<color=#e8d9bb>Dentro da cápsula de cura da Aviduz</color>",
  ui_story_9_8_1_2_dialog_content = "Professor...",
  ui_story_9_8_1_3_dialog_content = "Com licença... Professor... De novo...",
  ui_story_9_8_1_4_dialog_content = "Por que...",
  ui_story_9_8_1_5_dialog_content = "<color=#e8d9bb>Hangar Educativo de Colossus em Eraveil</color>",
  ui_story_9_8_1_6_dialog_content = "Com licença, professor Handro, posso tentar de novo?",
  ui_story_9_8_1_7_dialog_content = "Você usou suas três chances, Schummer.",
  ui_story_9_8_1_8_dialog_content = "Sinto muito, mas não passou no teste pra pilotar a Colossus.",
  ui_story_9_8_1_9_dialog_content = "Mas não posso me inscrever para a seleção de Navegador de Aviduz se não passar!",
  ui_story_9_8_1_10_dialog_content = "Eu tenho que passar!",
  ui_story_9_8_1_11_dialog_content = "Eu entendo como se sente, Schummer.",
  ui_story_9_8_1_12_dialog_content = "Você é uma das minhas alunas mais talentosas e quero muito que faça parte da seleção.",
  ui_story_9_8_1_13_dialog_content = "Mas seja um teste ou a própria seleção, deve ser justo.",
  ui_story_9_8_1_14_dialog_content = "Estou pronta para a prova, professor Handro! Podemos começar agora?",
  ui_story_9_8_1_15_dialog_content = "Tá, já tô indo aí.",
  ui_story_9_8_1_16_dialog_content = "Estou satisfeito em saber que trabalha duro, Schummer.",
  ui_story_9_8_1_17_dialog_content = "Acredito que se você continuar praticando, suas habilidades psíquicas vão melhorar logo!",
  ui_story_9_8_1_18_dialog_content = "E tenho certeza que você será escolhida para pilotar a Aviduz na próxima vez!",
  ui_story_9_8_1_19_dialog_content = "Mas quando?",
  ui_story_9_8_1_20_dialog_content = "...",
  ui_story_9_8_1_21_dialog_content = "Você não vai estar lá, já que a última seleção foi há várias décadas!",
  ui_story_9_8_1_X1_dialog_content = "(Cale a boca, mulher... Lembra que você tem uma filha agora? Só porque vou participar da seleção?)",
  ui_story_9_8_1_X2_dialog_content = "Schummer, mesmo que tenha ficado em primeiro lugar no último teste...",
  ui_story_9_8_1_X3_dialog_content = "Você não pode perder o foco agora. Vincular-se a uma Colossus é diferente. Você tem que dar tudo de si.",
  ui_story_9_8_1_X4_dialog_content = "(Eu sei... Não preciso que você me lembre.)",
  ui_story_9_8_1_22_dialog_content = "Você não gabarita todo exame que faz, Schummer?",
  ui_story_9_8_1_23_dialog_content = "Qual a dificuldade em lidar com algo tão simples quanto pilotar uma Colossus?",
  ui_story_9_8_1_X5_dialog_content = "(Eu consigo...Espere e verá.)",
  ui_story_9_8_1_X6_dialog_content = "Ela nem conseguiu se vincular à Colossus! Você é mesmo uma Celestita, Schummer?",
  ui_story_9_8_1_X7_dialog_content = "(Cale-se! Você se acha tanto só porque consegue se vincular um pouquinho.)",
  ui_story_9_8_1_24_dialog_content = "A Schummer falhou no teste de piloto? Vixe...",
  ui_story_9_8_1_X8_dialog_content = "(É só mais um teste. Da próxima vez ...)",
  ui_story_9_8_1_X9_dialog_content = "Handro disse que você seria um Navegador bom para a Aviduz?",
  ui_story_9_8_1_X10_dialog_content = "Você deveria só desistir.",
  ui_story_9_8_1_X11_dialog_content = "Você não tem o talento nem a qualificação para isso...",
  ui_story_9_8_1_X12_dialog_content = "(Calem a boca! Vocês são todos idiotas! Não entendem nada!)",
  ui_story_9_8_1_X13_dialog_content = "(Um dia, vou mostrar pra vocês!)",
  ui_story_9_8_1_X14_dialog_content = "...",
  ui_story_9_8_1_25_dialog_content = "Ela nem conseguiu se vincular à Colossus! Você é mesmo uma Celestita, Schummer?",
  ui_story_9_8_1_26_dialog_content = "Você...!",
  ui_story_9_8_1_27_dialog_content = "Ah, olhe, é Mendelson, o covarde!",
  ui_story_9_8_1_28_dialog_content = "Por que você não nos diz o que está pensando?",
  ui_story_9_8_1_29_dialog_content = "Para, já chega...",
  ui_story_9_8_1_30_dialog_content = "Quem é você para nos dizer o que fazer?",
  ui_story_9_8_1_31_dialog_content = "Professor Handro...",
  ui_story_9_8_1_32_dialog_content = "Ah? E o professor?",
  ui_story_9_8_1_33_dialog_content = "Eu... vou contar...",
  ui_story_9_8_1_34_dialog_content = "Você vai contar pro professor Handro? Você só é boa em bajular.",
  ui_story_9_8_1_35_dialog_content = "Tá, só para de falar.",
  ui_story_9_8_1_36_dialog_content = "Tá bom. Vamos!",
  ui_story_9_8_1_X15_dialog_content = "Estão fazendo bullying com ela de novo.?! Vou contar ao Professor!",
  ui_story_9_8_1_37_dialog_content = "Tudo bem?",
  ui_story_9_8_1_38_dialog_content = "Quem é você? Parece que preciso da sua ajuda?! Não se intrometa!",
  ui_story_9_8_1_39_dialog_content = "Eu sou o Mendelson... Eu vi eles fazendo bullying...",
  ui_story_9_8_1_X16_dialog_content = "Eu só pensei que... você precisava de ajuda...",
  ui_story_9_8_1_X17_dialog_content = "Então você achou que viu eles fazendo bullying e pensou em usar isso como uma oportunidade para vir me incomodar?",
  ui_story_9_8_1_40_dialog_content = "Você está apenas tentando me manipular. Acha que isso faz você se sentir melhor?",
  ui_story_9_8_1_X18_dialog_content = "Isso não te torna igual a eles?",
  ui_story_9_8_1_X19_dialog_content = "Quando você está de bom humor, você chega e finge que se importa, e quando está de mau humor, você simplesmente vem e ri?",
  ui_story_9_8_1_41_dialog_content = "Não...",
  ui_story_9_8_1_X20_dialog_content = "Não? Então por quê?",
  ui_story_9_8_1_42_dialog_content = "Por que você me ajudaria?",
  ui_story_9_8_1_43_dialog_content = "Eu... sei que eles estavam errados...",
  ui_story_9_8_1_44_dialog_content = "(Claro, eles estão errados...)",
  ui_story_9_8_1_45_dialog_content = "(Eles pensam que são tão grandes...)",
  ui_story_9_8_1_46_dialog_content = "O que você está fazendo aqui sozinha, Schummer?",
  ui_story_9_8_1_47_dialog_content = "!",
  ui_story_9_8_1_48_dialog_content = "É a Schummer que não consegue pilotar a Colossus!",
  ui_story_9_8_1_49_dialog_content = "Você está tentando se vincular  à Colossus? Que diligente!",
  ui_story_9_8_1_50_dialog_content = "Vamos deixar ela em paz...",
  ui_story_9_8_1_51_dialog_content = "Espera aí, tive uma ideia.",
  ui_story_9_8_1_52_dialog_content = "Que tal uma aposta?",
  ui_story_9_8_1_53_dialog_content = "O que você quer apostar?",
  ui_story_9_8_1_54_dialog_content = "Schummer, você tem coragem de sair de Eraveil com a gente?",
  ui_story_9_8_1_X21_dialog_content = "Hã? Não é isso que estávamos planejando da última vez...",
  ui_story_9_8_1_X22_dialog_content = "Haha! Olha para Schummer, ela nem ousa levantar a cabeça. Talvez esteja com medo de você...",
  ui_story_9_8_1_55_dialog_content = "Me diz se você teve coragem.",
  ui_story_9_8_1_56_dialog_content = "Vai nessa!",
  ui_story_9_8_1_57_dialog_content = "Talvez seja possível se vincular às Colossi, mas você arriscaria sair de Eraveil?",
  ui_story_9_8_1_58_dialog_content = "Mas como eu disse da última vez... Professor Handro disse que é perigoso lá fora por causa dos Eclipsitas.",
  ui_story_9_8_1_59_dialog_content = "Tá com medo?",
  ui_story_9_8_1_60_dialog_content = "Do que você tá com medo? Vamos levar a Colossus para um passeio!",
  ui_story_9_8_1_61_dialog_content = "Você ganha se fizer um bate e volta em uma Colossus.",
  ui_story_9_8_1_62_dialog_content = "Quando ganharmos, você vai entender!",
  ui_story_9_8_1_63_dialog_content = "Vamos levar Aprendiz I!",
  ui_story_9_8_1_64_dialog_content = "Certeza que não vou ser pego?",
  ui_story_9_8_1_65_dialog_content = "Não se preocupe, professor Handro tem certeza que você será o próximo Navegador de Aviduz!",
  ui_story_9_8_1_66_dialog_content = "!",
  ui_story_9_8_1_67_dialog_content = "Isso aí, acreditamos nas suas habilidades!",
  ui_story_9_8_1_68_dialog_content = "Mesmo se você for pego, ninguém vai te culpar!",
  ui_story_9_8_1_69_dialog_content = "Tá bom... Mas só dessa vez.",
  ui_story_9_8_1_70_dialog_content = "Hora de zarpar!",
  ui_story_9_8_1_X23_dialog_content = "Schummer, você vem ou não?",
  ui_story_9_8_1_X24_dialog_content = "Aposto três livros que ela não vem!",
  ui_story_9_8_1_71_dialog_content = "(Aviduz... é minha...)",
  ui_story_9_8_1_72_dialog_content = "(Você não entende nada... Então...)",
  ui_story_9_8_1_73_dialog_content = "<color=#e8d9bb>Exterior de Eraveil</color>",
  ui_story_9_8_1_74_dialog_content = "A Colossus não tá se mexendo!",
  ui_story_9_8_1_75_dialog_content = "...",
  ui_story_9_8_1_76_dialog_content = "Os Eclipsitas tão derrubando a porta!",
  ui_story_9_8_1_77_dialog_content = "O que a gente faz agora?",
  ui_story_9_8_1_78_dialog_content = "Tsc!",
  ui_story_9_8_1_79_dialog_content = "Não acredito que foram entregues de bandeja pra mim!",
  ui_story_9_8_1_X25_dialog_content = "(É melhor que estejam mortos.)",
  ui_story_9_8_1_80_dialog_content = "Precisamos lutar!",
  ui_story_9_8_1_81_dialog_content = "Afe!",
  ui_story_9_8_1_82_dialog_content = "Idiotas estúpidos. Deveria ter pegado mais leve.",
  ui_story_9_8_1_83_dialog_content = "Err...",
  ui_story_9_8_1_84_dialog_content = "Oh...",
  ui_story_9_8_1_85_dialog_content = "É só isso?",
  ui_story_9_8_1_86_dialog_content = "Mas isso foi só um pequeno teste. Odeio quando morrem sem permissão.",
  ui_story_9_8_1_87_dialog_content = "...",
  ui_story_9_8_1_88_dialog_content = "Isso é tudo que você pode tomar? Tudo que eu preciso é apertar meu aperto para esmagar seus ossos.",
  ui_story_9_8_1_89_dialog_content = "？？？（斐桀洛）",
  ui_story_9_8_1_90_dialog_content = "...",
  ui_story_9_8_1_91_dialog_content = "(Escapar... Como... posso escapar?)",
  ui_story_9_8_1_X91_dialog_content = "Ai...",
  ui_story_9_8_1_92_dialog_content = "Quê? Quer dizer que tem uma criaturazinha se escondendo nas ruínas?",
  ui_story_9_8_1_X92_dialog_content = "Tsc, tsc, tsc... Que interessante.",
  ui_story_9_8_1_X26_dialog_content = "(...!)",
  ui_story_9_8_1_S1_dialog_content = "Fique onde está!",
  ui_story_9_8_1_X27_dialog_content = "Silêncio... Tenho boas notícias pra você.",
  ui_story_9_8_1_X28_dialog_content = "Você gostaria de ouvi-la?",
  ui_story_9_8_1_X29_dialog_content = "...Você fala Universês?",
  ui_story_9_8_1_S2_dialog_content = "Tsc! Você ainda tá pensando nessas coisas!? Não tem medo que eu te mate?",
  ui_story_9_8_1_S3_dialog_content = "...Sim.",
  ui_story_9_8_1_X30_dialog_content = "Tsc, tsc tsc! Preste bem atenção em mim.",
  ui_story_9_8_1_93_dialog_content = "A Grande Mãe decretou que os Celestitas devem ser completamente erradicados no dia do julgamento.",
  ui_story_9_8_1_94_dialog_content = "É o julgamento final contra os Celestitas, e o final feliz garantido pela Mãe!",
  ui_story_9_8_1_95_dialog_content = "Por isso, celebre o fato de que você testemunhará um momento histórico!",
  ui_story_9_8_1_96_dialog_content = "...O-O quê?!",
  ui_story_9_8_1_97_dialog_content = "Você não tem o direito de fazer perguntas!",
  ui_story_9_8_1_98_dialog_content = "Os fracos merecem apenas a morte!",
  ui_story_9_8_1_99_dialog_content = "Assim como seus amiguinhos, amassados em pequenas bolas e morrendo em agonia.",
  ui_story_9_8_1_100_dialog_content = "...!",
  ui_story_9_8_1_101_dialog_content = "Tsc, tsc... Não se preocupe. Eu decidi selecionar você. Decidi lhe dar uma chance.",
  ui_story_9_8_1_102_dialog_content = "Vou lhe presentear com o poder para superar os Celestitas! Vou lhe presentear com a oportunidade de esquecer sua existência patética!",
  ui_story_9_8_1_103_dialog_content = "Esquecer...",
  ui_story_9_8_1_104_dialog_content = "Você não gabarita todo exame que faz, Schummer?",
  ui_story_9_8_1_105_dialog_content = "Qual a dificuldade em lidar com algo tão simples quanto pilotar uma Colossus?",
  ui_story_9_8_1_106_dialog_content = "A Schummer falhou no teste de piloto? Vixe...",
  ui_story_9_8_1_107_dialog_content = "Ela nem conseguiu se vincular à Colossus! Você é mesmo uma Celestita, Schummer?",
  ui_story_9_8_1_108_dialog_content = "Certeza que não vou ser pego?",
  ui_story_9_8_1_109_dialog_content = "Não se preocupe, professor Handro tem certeza que você será o próximo Navegador de Aviduz!",
  ui_story_9_8_1_110_dialog_content = "Vê essa Semente? É sua esperança.",
  ui_story_9_8_1_111_dialog_content = "Minha... Esperança...",
  ui_story_9_8_1_112_dialog_content = "Excelente. Posso sentir seu desejo por poder.",
  ui_story_9_8_1_113_dialog_content = "Poder...",
  ui_story_9_8_1_114_dialog_content = "O que está fazendo, Schummer?",
  ui_story_9_8_1_115_dialog_content = "Sim, apenas tornando-se uma criança da Mãe você pode viver!",
  ui_story_9_8_1_116_dialog_content = "Eu preciso viver...",
  ui_story_9_8_1_117_dialog_content = "Você não deve mais ser fraco ou ter medo!",
  ui_story_9_8_1_118_dialog_content = "Aceite o presente, fique forte... E junte-se a nós!",
  ui_story_9_8_1_119_dialog_content = "Você vai dominar o mundo... Dominar tudo!",
  ui_story_9_8_1_120_dialog_content = "Dominar... Tudo...",
  ui_story_9_8_1_121_dialog_content = "Não, Schummer...",
  ui_story_9_8_1_122_dialog_content = "Sim, isso. Venha.",
  ui_story_9_8_1_123_dialog_content = "Não... Por favor, eu te imploro...",
  ui_story_9_8_1_124_dialog_content = "...",
  ui_story_9_8_1_125_dialog_content = "O que foi?",
  ui_story_9_8_1_126_dialog_content = "Eu...",
  ui_story_9_8_1_127_dialog_content = "Pega a faca!",
  ui_story_9_8_1_128_dialog_content = "Eu...",
  ui_story_9_8_1_129_dialog_content = "Não hesite! Não teste minha paciência! O que tá esperando!?",
  ui_story_9_8_1_130_dialog_content = "V-Vou virar um Eclipsita... Certo?",
  ui_story_9_8_1_131_dialog_content = "Esquece...",
  ui_story_9_8_1_132_dialog_content = "Afe!",
  ui_story_9_8_1_133_dialog_content = "Você...",
  ui_story_9_8_1_134_dialog_content = "Você odeia ela, né?",
  ui_story_9_8_1_135_dialog_content = "...",
  ui_story_9_8_1_136_dialog_content = "Deveria me agradecer por tê-la eliminado.",
  ui_story_9_8_1_137_dialog_content = "Vai me matar também?",
  ui_story_9_8_1_138_dialog_content = "Por que eu faria isso?",
  ui_story_9_8_1_139_dialog_content = "Vejo que é diferente deles. Tem o potencial para ser incrível.",
  ui_story_9_8_1_140_dialog_content = "Claro. Se você se tornar um Eclipsita, conseguirá poder para superar os Celestitas, e até mesmo os Aurorians!",
  ui_story_9_8_1_141_dialog_content = "Mas... Que tipo de poder é esse?",
  ui_story_9_8_1_142_dialog_content = "Uma benção da Mãe que nutre o mundo, o presente mais especial que alguém poderia receber.",
  ui_story_9_8_1_143_dialog_content = "Você seguirá sua vida, sem temer nada.",
  ui_story_9_8_1_144_dialog_content = "Ou seja... Só viverei se aceitar?",
  ui_story_9_8_1_145_dialog_content = "Claro. Pode viver até mais que o vale onde estamos.",
  ui_story_9_8_1_146_dialog_content = "E nunca serei fraco novamente?",
  ui_story_9_8_1_147_dialog_content = "É claro. Todos te chamarão de “Formidável” daqui em diante.",
  ui_story_9_8_1_S147_dialog_content = "Se aceitar... Estarei qualificado para possuir a Aviduz?",
  ui_story_9_8_1_S148_dialog_content = "Aviduz? É uma Colossus?",
  ui_story_9_8_1_S149_dialog_content = "Tsc, tsc, tsc... Me diz, que tipo de Colossus você deseja?",
  ui_story_9_8_1_S150_dialog_content = "Aviduz... é a Colossus mais poderosa que existe. Apenas o Celestita mais forte... tem o direito de comandá-la.",
  ui_story_9_8_1_S151_dialog_content = "Tsc, tsc, tsc! Então será mais qualificado para comandá-la que qualquer outro Celestita! E superará a todos!",
  ui_story_9_8_1_148_dialog_content = "...",
  ui_story_9_8_1_149_dialog_content = "Eu...",
  ui_story_9_8_1_150_dialog_content = "Aceito.",
  ui_story_9_8_1_151_dialog_content = "Tsc!",
  ui_story_9_8_1_152_dialog_content = "Ah...",
  ui_story_9_8_1_153_dialog_content = "Você ganhou outro servo, ó Grande Mãe!",
  ui_story_9_8_1_154_dialog_content = "Você me deu poder?",
  ui_story_9_8_1_155_dialog_content = "Não sinto nenhuma diferença...",
  ui_story_9_8_1_156_dialog_content = "Schummer... É o seu nome, certo?",
  ui_story_9_8_1_157_dialog_content = "Mantenha isso em mente, Schummer, nunca duvide da Grande Mãe. Precisa aprender a ser paciente.",
  ui_story_9_8_1_158_dialog_content = "...",
  ui_story_9_8_1_159_dialog_content = "Aonde está me levando agora?",
  ui_story_9_8_1_160_dialog_content = "Não estamos indo pra lugar nenhum, Schummer. Quero você de volta em Eraveil. Comigo, é claro.",
  ui_story_9_8_1_161_dialog_content = "De volta a Eraveil?",
  ui_story_9_8_1_162_dialog_content = "Esqueceu que a Aviduz ainda te espera por lá?",
  ui_story_9_8_1_163_dialog_content = "Você não será completo e invencível até possuir a Aviduz!",
  ui_story_9_8_1_164_dialog_content = "Eu não esqueci. É que não sou como os outros.",
  ui_story_9_8_1_165_dialog_content = "Eu... não consigo me vincular a nenhuma Colossus. Pensei que podia esperar até tudo isso acabar.",
  ui_story_9_8_1_166_dialog_content = "Quê? Uma Celestita que não consegue se vincular às Colossi?",
  ui_story_9_8_1_167_dialog_content = "Cale a boca! Não quero desculpas!",
  ui_story_9_8_1_168_dialog_content = "Deixa pra lá, a Semente já está lhe possuindo.",
  ui_story_9_8_1_169_dialog_content = "A partir de agora você não é mais Celestita.",
  ui_story_9_8_1_170_dialog_content = "Pode tentar iniciar a Colossus agora.",
  ui_story_9_8_1_171_dialog_content = "... Tá bem.",
  ui_story_9_8_1_172_dialog_content = "Isso não pode ser real...",
  ui_story_9_8_1_173_dialog_content = "Eu não perdi... Eu não perdi!",
  ui_story_9_8_1_174_dialog_content = "Schummer!",
  ui_story_9_8_1_175_dialog_content = "Olhe nos meus olhos antes de morrer!!!",
  ui_story_9_8_1_176_dialog_content = "Não, não...",
  ui_story_9_8_1_177_dialog_content = "Não!",
  ui_story_9_9_1_1_dialog_content = "Cuidado onde pisam, pessoal!",
  ui_story_9_9_1_2_dialog_content = "O que houve?",
  ui_story_9_9_1_3_dialog_content = "<color=#e8d9bb>Lamento... lamento... lamento...</color>",
  ui_story_9_9_1_4_dialog_content = "Estou ouvindo muitos sons...",
  ui_story_9_9_1_5_dialog_content = "Tipo a terra tremendo?",
  ui_story_9_9_1_6_dialog_content = "Não, é... É a Aviduz, lamentando e chorando...",
  ui_story_9_9_1_7_dialog_content = "<color=#e8d9bb>Lamento... lamento... lamento...</color>",
  ui_story_9_9_1_8_dialog_content = "(É... É o lamento das Colossi... Parece que até as Colossi enterradas aqui estão se lamentando...)",
  ui_story_9_9_1_9_dialog_content = "<color=#e8d9bb><anim type=Shake>Lamento... lamento... lamento...</anim></color>",
  ui_story_9_9_1_10_dialog_content = "(Parece uma faca cortando meu coração...)",
  ui_story_9_9_1_11_dialog_content = "(Sinto um líquido quente fluir...)",
  ui_story_9_9_1_12_dialog_content = "Lágrimas?",
  ui_story_9_9_1_13_dialog_content = "PlayerName...",
  ui_story_9_9_1_14_dialog_content = "PlayerName... Você tá chorando?",
  ui_story_9_9_1_15_dialog_content = "PlayerName...",
  ui_story_9_9_1_16_dialog_content = "Não é nada... Eu só... Tava pensando em Soroz por um momento.",
  ui_story_9_9_1_X16_dialog_content = "PlayerName...",
  ui_story_9_9_1_17_dialog_content = "Vice.",
  ui_story_9_9_1_18_dialog_content = "Você sentiu alguma coisa? Estamos aqui se você precisar!",
  ui_story_9_9_1_19_dialog_content = "Tome isso aqui, por favor.",
  ui_story_9_9_1_20_dialog_content = "Hmm...?",
  ui_story_9_9_1_21_dialog_content = "Um lenço para secar suas lágrimas, PlayerName.",
  ui_story_9_9_1_22_dialog_content = "Desculpa, eu não sei porquê...",
  ui_story_9_9_1_23_dialog_content = "Você não precisa se desculpar, PlayerName.",
  ui_story_9_9_1_24_dialog_content = "Lágrimas não são só pros fracos. Todo mundo precisa se aliviar às vezes.",
  ui_story_9_9_1_25_dialog_content = "Está bem.",
  ui_story_9_9_1_26_dialog_content = "O que você sente, jovem?",
  ui_story_9_9_1_27_dialog_content = "Escutei um choro vindo das Colossi, sem parar.",
  ui_story_9_9_1_28_dialog_content = "Soava como luto, como se alguém estivesse lamentando a morte de um ente querido…",
  ui_story_9_9_1_29_dialog_content = "Eu senti sua tristeza… como se fossem minha.",
  ui_story_9_9_1_30_dialog_content = "Tem mais Colossi por perto?",
  ui_story_9_9_1_31_dialog_content = "Acho que não. Os sons que eu ouvi, não eram reais...",
  ui_story_9_9_1_32_dialog_content = "O que ouvi eram pensamentos ecoantes.",
  ui_story_9_9_1_33_dialog_content = "Mas por que agora?",
  ui_story_9_9_1_34_dialog_content = "...",
  ui_story_9_9_1_35_dialog_content = "Ainda pode sentir a Aviduz, PlayerName?",
  ui_story_9_9_1_36_dialog_content = "O Fluxo Escuro está mais denso em Eraveil.",
  ui_story_9_9_1_37_dialog_content = "Mal posso sentir a presença fraquejante de Aviduz.",
  ui_story_9_9_1_38_dialog_content = "Agora, não tô captando nada.",
  ui_story_9_9_1_39_dialog_content = "Invejo seu poder de sentir as Colossi, PlayerName.",
  ui_story_9_9_1_40_dialog_content = "É o talento inato de Celestitas, assim como você pode usar Lúmina para lutar.",
  ui_story_9_9_1_41_dialog_content = "Sabe, tenho uma curiosidade...",
  ui_story_9_9_1_42_dialog_content = "Qual a sensação ao se vincular à Colossus?",
  ui_story_9_9_1_43_dialog_content = "O que você sente?",
  ui_story_9_9_1_44_dialog_content = "Ah, não sei bem como responder isso.",
  ui_story_9_9_1_45_dialog_content = "(Tô acostumada a ter Soroz por perto, já faz 17 anos.)",
  ui_story_9_9_1_46_dialog_content = "(E se não puder mais me vincular ao Soroz...)",
  ui_story_9_9_1_47_dialog_content = "Se não estiver confortável em responder, tudo bem, PlayerName.",
  ui_story_9_9_1_48_dialog_content = "Eu tô bem, não é nem uma questão de conforto.",
  ui_story_9_9_1_49_dialog_content = "Só percebi que nunca parei pra pensar sobre isso.",
  ui_story_9_9_1_50_dialog_content = "Me sinto seguro e aquecido quando me vinculo à Colossus.",
  ui_story_9_9_1_51_dialog_content = "Como um grande amigo que sempre sabe o que você tá pensando.",
  ui_story_9_9_1_52_dialog_content = "E só você o entende.",
  ui_story_9_9_1_53_dialog_content = "Claro, pode parecer irritante devido às reclamações ocasionais.",
  ui_story_9_9_1_54_dialog_content = "Mas quando elas param, você sente falta.",
  ui_story_9_9_1_55_dialog_content = "Eu diria que me vincular à Colossus traz um sentimento feliz.",
  ui_story_9_9_1_56_dialog_content = "Sentimento feliz...",
  ui_story_9_9_1_57_dialog_content = "Eu adoraria saber o que Lepidoz está pensando.",
  ui_story_9_9_1_58_dialog_content = "Essa Lepidoz é uma Colossus?",
  ui_story_9_9_1_59_dialog_content = "Lepidoz é o orgulho de Rediesel Wrench!",
  ui_story_9_9_1_60_dialog_content = "Nós achamos um casco meio enterrado no Deserto Rediesel.",
  ui_story_9_9_1_61_dialog_content = "A gente escavou e percebeu que era uma Colossus despedaçada.",
  ui_story_9_9_1_62_dialog_content = "Nossos técnicos tiveram dificuldade em remontá-la.",
  ui_story_9_9_1_63_dialog_content = "Mas a Lepidoz só deixa o Bopper pilotá-la.",
  ui_story_9_9_1_64_dialog_content = "Não move um músculo sequer por outras pessoas.",
  ui_story_9_9_1_65_dialog_content = "Demorei muito pra aprender a pilotar a Lepidoz.",
  ui_story_9_9_1_66_dialog_content = "Antes você a pilotava sem se vincular?",
  ui_story_9_9_1_67_dialog_content = "Pois é. Sei lá como.",
  ui_story_9_9_1_68_dialog_content = "Às vezes eu sinto que sei o que a Lepidoz está sentindo.",
  ui_story_9_9_1_69_dialog_content = "Quando a encontramos, ela devia se sentir muito perdida e sozinha.",
  ui_story_9_9_1_70_dialog_content = "Não saber o que ela pensa, não me impede de falar com ela todo dia.",
  ui_story_9_9_1_71_dialog_content = "Hoje, ela ama viver como uma Rediesel Wrench!",
  ui_story_9_9_1_72_dialog_content = "Com ou sem vínculo, tanto faz para Bopper.",
  ui_story_9_9_1_73_dialog_content = "As habilidades de piloto que ela tem são suficientes!",
  ui_story_9_9_1_74_dialog_content = "Nunca pensei que bandidos do deserto teriam sua própria Colossus.",
  ui_story_9_9_1_75_dialog_content = "O mundo real é uma caixinha de surpresas, princesa.",
  ui_story_9_9_1_76_dialog_content = "Faz bem sair do castelo de vez em quando.",
  ui_story_9_9_1_77_dialog_content = "...",
  ui_story_9_9_1_78_dialog_content = "Cuidado, atrás de você!",
  ui_story_9_9_1_79_dialog_content = "Será que são... mais Eclipsitas que costumavam ser Aurorians?",
  ui_story_9_9_1_80_dialog_content = "Tantos assim? São muitos...",
  ui_story_9_9_1_81_dialog_content = "Obviamente, os guardas de Lumópolis que vieram investigar foram todos capturados e usados como cobaia.",
  ui_story_9_9_1_82_dialog_content = "!",
  ui_story_9_9_1_83_dialog_content = "PlayerName, me dê suas ordens! Vamos acabar com eles o quanto antes, antes que sintam dor.",
  ui_story_9_13_1_1_dialog_content = "Avante, Noite Branca! Que descansem em paz.",
  ui_story_9_13_1_2_dialog_content = "Descanse em paz...",
  ui_story_9_13_1_3_dialog_content = "Ainda falta muito, PlayerName?",
  ui_story_9_13_1_4_dialog_content = "O sinal está fraco, mas Aviduz deve estar próxima.",
  ui_story_9_13_1_X4_dialog_content = "Em qual direção? Esquerda? Direita? Pela frente?",
  ui_story_9_13_1_5_dialog_content = "Aahhhhhh!",
  ui_story_9_13_1_6_dialog_content = "Tem um grande grupo de Eclipsitas avançando pela frente!",
  ui_story_9_13_1_7_dialog_content = "PlayerName, indique a direção que eu abrirei caminho!",
  ui_story_9_13_2_1_dialog_content = "Eu vejo um, no pescoço daquele Eclipsita morto logo ali.",
  ui_story_9_13_2_2_dialog_content = "Esse Eclipsita é absurdamente sujo! Não sei nem por onde começar.",
  ui_story_9_13_2_3_dialog_content = "Você poderia ajudar Pact, Nails?",
  ui_story_9_13_2_4_dialog_content = "...",
  ui_story_9_13_2_5_dialog_content = "Por favor, me perdoe, grande Senhor da Verdade.",
  ui_story_9_13_2_6_dialog_content = "A doutrina o proíbe de tocar tudo que não é limpo.",
  ui_story_9_13_2_7_dialog_content = "Mas pra procurar seus rastros, eu preciso ver o que não deveria, tocar o que não deveria.",
  ui_story_9_13_2_8_dialog_content = "Devo me banhar por 3 dias em reparação quando retornar.",
  ui_story_9_13_2_9_dialog_content = "...",
  ui_story_9_13_2_10_dialog_content = "Por favor, dê para a Mala Branca comer.",
  ui_story_9_13_2_11_dialog_content = "<color=#e8d9bb>Vuuush!</color>",
  ui_story_9_13_2_12_dialog_content = "Por que eu daria a Semente para a Mala Branca?",
  ui_story_9_13_2_X12_dialog_content = "Mala Branca parece gostar dessas coisas... O que fazemos se ela não cuspir fora depois?",
  ui_story_9_13_2_X13_dialog_content = "Deixa pro Nails, já que tá tão interessado.",
  ui_story_9_13_2_X14_dialog_content = "...",
  ui_story_9_13_2_13_dialog_content = "Me perdoe, Lady Victoria. Vou tentar me acalmar...",
  ui_story_9_13_2_14_dialog_content = "Pact, não subestime a Semente.",
  ui_story_9_13_2_X15_dialog_content = "Mesmo sendo pequena, o Fluxo Escuro contido na Semente pode afetar significativamente o espírito de um Aurorian.",
  ui_story_9_13_2_X16_dialog_content = "Nossos corpos contêm uma poderosa Lúmina, mas só resistimos aos seus efeitos brevemente.",
  ui_story_9_13_2_X17_dialog_content = "Não podemos encostar por muito tempo.",
  ui_story_9_13_2_15_dialog_content = "Parece que temos outra regra vital. Melhor levar a sério...",
  ui_story_9_14_1_1_dialog_content = "É logo ali.",
  ui_story_9_14_1_2_dialog_content = "Atenção!",
  ui_story_9_14_1_3_dialog_content = "Essa é Aviduz?",
  ui_story_9_14_1_4_dialog_content = "Assustadora... Lepidoz é mais bonitinha.",
  ui_story_9_14_1_5_dialog_content = "A explosão do canhão Lúmina e o impacto da batida...",
  ui_story_9_14_1_6_dialog_content = "Aviduz tá em péssimo estado agora.",
  ui_story_9_14_1_7_dialog_content = "Humm... Agorinha... Quando Aviduz lamentou, parecia um grito final antes de deixar esse mundo...",
  ui_story_9_14_1_8_dialog_content = "Vamos entrar e procurar o corpo de Schummer, mesmo assim.",
  ui_story_9_14_1_9_dialog_content = "Espera, tem alguém vindo!",
  ui_story_9_14_1_10_dialog_content = "É a Schummer?",
  ui_story_9_14_1_11_dialog_content = "Não, definitivamente não é a Schummer.",
  ui_story_9_14_1_12_dialog_content = "É a <color=#FFB400>Forsakin</color>!",
  ui_story_9_14_1_13_dialog_content = "!!!",
  ui_story_9_14_1_14_dialog_content = "!",
  ui_story_9_14_1_15_dialog_content = "Estava me perguntando quem veio me interromper agora.",
  ui_story_9_14_1_16_dialog_content = "Vejo que é você.",
  ui_story_9_14_1_17_dialog_content = "Ninguém te avisou que é educado telefonar antes da visita?",
  ui_story_9_14_1_18_dialog_content = "Dizemos o mesmo pra você.",
  ui_story_9_14_1_19_dialog_content = "Isso é Eraveil, não deveriam estar aqui!",
  ui_story_9_14_1_20_dialog_content = "Se eu já estou aqui, obviamente não ligo pra essas regras.",
  ui_story_9_14_1_21_dialog_content = "É você!",
  ui_story_9_14_1_22_dialog_content = "Não tinha morrido no incêndio?",
  ui_story_9_14_1_23_dialog_content = "Mas eu reconheceria até mesmo suas cinzas, mudar de nome não adiantará de nada!",
  ui_story_9_14_1_24_dialog_content = "...",
  ui_story_9_14_1_25_dialog_content = "O que você fez com minha irmã, <color=#FFB400>Denier</color>?",
  ui_story_9_14_1_26_dialog_content = "...",
  ui_story_9_14_1_27_dialog_content = "Alô, tá me ouvindo?!",
  ui_story_9_14_1_28_dialog_content = "PlayerName, não sinto Fluxo Escuro em você...",
  ui_story_9_14_1_29_option_content = "Quem é você, de verdade?",
  ui_story_9_14_1_30_dialog_content = "Não me diga que é uma pesquisadora de Illumina.",
  ui_story_9_14_1_31_dialog_content = "O que isso tem a ver contigo?",
  ui_story_9_14_1_32_dialog_content = "Isso importa?",
  ui_story_9_14_1_33_dialog_content = "Isso não me incomoda.",
  ui_story_9_14_1_34_dialog_content = "Agora, cadê a sua Semente, PlayerName?",
  ui_story_9_14_1_35_dialog_content = "Então foi você que armou pra mim!",
  ui_story_9_14_1_36_dialog_content = "Fiquei me coçando todo.",
  ui_story_9_14_1_37_dialog_content = "Coçando?",
  ui_story_9_14_1_38_dialog_content = "E o que aconteceu? Quanto tempo essa coceira durou?",
  ui_story_9_14_1_39_dialog_content = "Cerca de... Ei, por que eu deveria dizer?",
  ui_story_9_14_1_40_dialog_content = "Cuidado, PlayerName, não deixa ela te enganar.",
  ui_story_9_14_1_41_dialog_content = "Como removeu a Semente das suas costas?",
  ui_story_9_14_1_42_dialog_content = "Se quer mesmo saber, precisa me responder primeiro...",
  ui_story_9_14_1_43_option_content = "Por que está em Eraveil?",
  ui_story_9_14_1_44_dialog_content = "Por que transformou Aurorians em Eclipsitas? Por que os experimentos bizarros?",
  ui_story_9_14_1_45_option_content = "Por que plantou a Semente em mim?",
  ui_story_9_14_1_46_dialog_content = "Se eu não a tirasse, eu viraria um Eclipsita?",
  ui_story_9_14_1_47_dialog_content = "Você faz perguntas demais.",
  ui_story_9_14_1_48_dialog_content = "Só posso dizer que estou desapontada, PlayerName.",
  ui_story_9_14_1_49_dialog_content = "Te dei a chance de ser poderoso e entender a verdade sobre o mundo.",
  ui_story_9_14_1_50_dialog_content = "Mas desperdiçou sua chance e foi embora.",
  ui_story_9_14_1_51_dialog_content = "Que pena.",
  ui_story_9_14_1_52_dialog_content = "Agora jamais vai saber, PlayerName.",
  ui_story_9_14_1_53_dialog_content = "Não dê ouvidos a ela!",
  ui_story_9_14_1_54_dialog_content = "Ela só pode ser a ex-pesquisadora de Illumina, Denier!",
  ui_story_9_14_1_55_dialog_content = "Denier? Não conheço esse nome.",
  ui_story_9_14_1_56_dialog_content = "Mentirosa!",
  ui_story_9_14_1_57_dialog_content = "Eve sofreu anos por sua causa!",
  ui_story_9_14_1_58_dialog_content = "Eve?",
  ui_story_9_14_1_59_dialog_content = "Lembrou-se de algo?",
  ui_story_9_14_1_60_dialog_content = "Um pouco, mas não está claro.",
  ui_story_9_14_1_61_dialog_content = "Afinal, tive muitos experimentos e cobaias.",
  ui_story_9_14_1_62_dialog_content = "Você...",
  ui_story_9_14_1_63_dialog_content = "Calma, Sinsa. Forsakin tá tentando te provocar.",
  ui_story_9_14_1_64_dialog_content = "Tô bem!",
  ui_story_9_14_1_65_dialog_content = "Tão bem que já pensei em mil maneiras de cortar ela em pedacinhos!",
  ui_story_9_14_1_66_dialog_content = "Na verdade, você pensou em mil maneiras de apanhar, isso sim.",
  ui_story_9_14_1_67_dialog_content = "Quem sabe uns sopapos te ajudam a pensar melhor!",
  ui_story_9_14_1_68_dialog_content = "...",
  ui_story_9_14_1_69_dialog_content = "Muita falação pra pouca ação.",
  ui_story_9_14_1_70_dialog_content = "Você tá bem, Chefe?",
  ui_story_9_14_1_71_dialog_content = "*Cof Cof*... Estou bem!",
  ui_story_9_14_1_72_dialog_content = "O que aconteceu?",
  ui_story_9_14_1_73_dialog_content = "Ela balançou a mão e Sinsa saiu voando.",
  ui_story_9_14_1_74_dialog_content = "Ela tá usando Eclipsium.",
  ui_story_9_14_1_75_dialog_content = "A Forsakin diante de nós abandonou seu passado como Aurorian para se tornar um monstro!",
  ui_story_9_14_1_76_dialog_content = "Vou te matar, sua bruxa!",
  ui_story_9_14_1_77_dialog_content = "Silêncio... Não seja tão ingrato.",
  ui_story_9_14_1_78_dialog_content = "Não gosto de brigar.",
  ui_story_9_14_1_79_dialog_content = "Mas já que insiste, consigo um oponente a altura pra você.",
  ui_story_9_14_1_80_dialog_content = "Vem brincar com os novos amigos, Chifre Feroz.",
  ui_story_9_14_1_81_dialog_content = "<anim type=Shake>Taba... nunca... morre!</anim>",
  ui_story_9_14_1_82_dialog_content = "Chifre Feroz? Esse é claramente aquele Tabaad com quem lutamos antes!",
  ui_story_9_14_1_X82_dialog_content = "Esse nome é só um código criado por conveniência...",
  ui_story_9_14_1_83_dialog_content = "Você já conhece esse Eclipsita?",
  ui_story_9_14_1_84_dialog_content = "O Comandante Hiiro lhe atingiu fatalmente em Mantiz...",
  ui_story_9_14_1_85_dialog_content = "É outra reanimação.",
  ui_story_9_14_1_86_dialog_content = "Então é a Forsakin que tá reanimando os mortos!",
  ui_story_9_14_1_87_dialog_content = "Vamos chamar de reciclagem eficiente.",
  ui_story_9_14_1_88_dialog_content = "Mas é mais do que suficiente pra você.",
  ui_story_9_14_1_89_dialog_content = "<anim type=Shake>Ahhhhhh!</anim>",
  ui_story_9_14_1_90_dialog_content = "<anim type=Shake>Taba... nunca... morre!</anim>",
  ui_story_9_14_2_1_dialog_content = "<anim type=Shake>Argh!</anim>",
  ui_story_9_14_2_2_dialog_content = "Fica de olho em Forsakin!",
  ui_story_9_14_2_3_dialog_content = "Cuidado, PlayerName!",
  ui_story_9_14_2_4_dialog_content = "!",
  ui_story_9_14_2_5_dialog_content = "Você não vai encostar em ninguém!",
  ui_story_9_14_2_6_dialog_content = "...",
  ui_story_9_14_2_7_dialog_content = "Chefe!",
  ui_story_9_14_2_8_dialog_content = "Você tá bem, Sinsa?",
  ui_story_9_14_2_9_dialog_content = "Tó ótimo! *Cof*",
  ui_story_9_14_2_10_dialog_content = "Dê mais um passo, Aurorian caída, e farei justiça às suas custas!",
  ui_story_9_14_2_11_dialog_content = "Não se empolgue demais.",
  ui_story_9_14_2_12_dialog_content = "Só quero dar uma boa olhada em PlayerName.",
  ui_story_9_14_2_13_dialog_content = "O que você quer com PlayerName, Forsakin?",
  ui_story_9_14_2_14_dialog_content = "Você se recusou a responder minhas perguntas, então farei própria pesquisa.",
  ui_story_9_14_2_15_dialog_content = "De fato, sem sinal da Semente em você, PlayerName.",
  ui_story_9_14_2_16_dialog_content = "Pela última vez, como você conseguiu tirá-la?",
  ui_story_9_14_2_17_dialog_content = "Primeiro me diz por que você faria tal experimento.",
  ui_story_9_14_2_18_dialog_content = "Você ainda não notou a situação em que se encontra, PlayerName.",
  ui_story_9_14_2_19_dialog_content = "Você não é capaz e nem tem o poder para negociar comigo.",
  ui_story_9_14_2_20_dialog_content = "Não gasta saliva com ela, PlayerName.",
  ui_story_9_14_2_21_dialog_content = "Hã?",
  ui_story_9_14_2_22_dialog_content = "Eu tirei de PlayerName. Algum problema?",
  ui_story_9_14_2_23_dialog_content = "Como pôde Illumina criar uma traidora como você?",
  ui_story_9_14_2_24_dialog_content = "Não faça nenhuma burrice, Vice!",
  ui_story_9_14_2_25_dialog_content = "Melhor me dizer a verdade.",
  ui_story_9_14_2_26_dialog_content = "Ahhhhhh! Ah...",
  ui_story_9_14_2_27_dialog_content = "Vice!",
  ui_story_9_14_2_28_dialog_content = "Forsakin! Solte a Vice, agora!",
  ui_story_9_14_2_29_dialog_content = "Vou parar, mas espero a mesma cortesia de você.",
  ui_story_9_14_2_30_dialog_content = "Me diz, pra onde a Semente foi?",
  ui_story_9_14_2_31_dialog_content = "...",
  ui_story_9_14_2_32_dialog_content = "(Não posso colocar a Vice em perigo...)",
  ui_story_9_14_2_33_dialog_content = "(Tenho de contar a ela.)",
  ui_story_9_14_2_34_dialog_content = "Eu falo o que você quiser, mas liberte-a primeiro! Eu prometo!",
  ui_story_9_14_2_X34_dialog_content = "Está bem.",
  ui_story_9_14_2_X35_dialog_content = "薇丝",
  ui_story_9_14_2_X36_dialog_content = "Vice, vem pra cá!",
  ui_story_9_14_2_X37_dialog_content = "Agora, fale.",
  ui_story_9_14_2_35_dialog_content = "A Semente foi levada por um homem com uma mala branca.",
  ui_story_9_14_2_36_dialog_content = "Um homem com uma mala branca...",
  ui_story_9_14_2_37_dialog_content = "Quem é ele?",
  ui_story_9_14_2_38_dialog_content = "Não conheço, nem sei por que levou a Semente.",
  ui_story_9_14_2_39_dialog_content = "Mas ele me disse que podia transformar Aurorians em Eclipsitas!",
  ui_story_9_14_2_40_dialog_content = "Você tentava usar isso não só pra me transformar em Eclipsitas, mas também transformar os soldados de Lumópolis em Eclipsitas!",
  ui_story_9_14_2_41_dialog_content = "Os experimentos, como você os chama, são vítimas da Semente!",
  ui_story_9_14_2_42_dialog_content = "Não é?",
  ui_story_9_14_2_43_dialog_content = "Já que está sua decisão foi feita, não tem nada mais que eu possa dizer.",
  ui_story_9_14_2_44_dialog_content = "Não, quero saber por que você cometeria experimentos tão desumanos?",
  ui_story_9_14_2_45_dialog_content = "Por que conspirar com a escuridão quando você é Aurorian?",
  ui_story_9_14_2_46_dialog_content = "Eu te disse, PlayerName. Você não tem mais chances de descobrir.",
  ui_story_9_14_2_47_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_9_14_2_48_dialog_content = "Humm, tá na hora.",
  ui_story_9_14_2_49_dialog_content = "Que som é esse?",
  ui_story_9_14_2_50_dialog_content = "Veio da Aviduz.",
  ui_story_9_14_2_51_dialog_content = "É o barulho de quando a Colossus para de funcionar.",
  ui_story_9_14_2_52_dialog_content = "(Não consigo mais sentir a Aviduz.)",
  ui_story_9_14_2_53_dialog_content = "(Ela... morreu?)",
  ui_story_9_14_2_54_dialog_content = "Você não vai poupar nem a Aviduz, Forsakin?!",
  ui_story_9_14_2_55_dialog_content = "O que você fez com ela?",
  ui_story_9_14_2_56_dialog_content = "Você realmente faz muitas perguntas, PlayerName.",
  ui_story_9_14_2_57_dialog_content = "Por que não entra na Colossus e pergunta para uma <color=#FFB400>velha amizade</color>, se quer mesmo saber?",
  ui_story_9_14_2_58_dialog_content = "Forsakin entrou na Colossus!",
  ui_story_9_14_2_59_dialog_content = "Ei, volta já aqui!",
  ui_story_9_14_2_60_dialog_content = "\"<color=#FFB400>Velha amizade</color>\"?",
  ui_story_9_14_2_61_dialog_content = "...",
  ui_story_9_14_2_62_dialog_content = "Schummer...",
  ui_story_9_14_2_63_dialog_content = "<size=45>Schummer ainda está viva!</size>",
  ui_story_10_1_1_1_dialog_content = "<color=#e8d9bb>Lumópolis, na frente do centro médico</color>",
  ui_story_10_1_1_2_dialog_content = "Então é assim que o Pátio de Lumópolis está agora, miau?",
  ui_story_10_1_1_S1_dialog_content = "Esses prédios... Um mais chique que o outro.",
  ui_story_10_1_1_3_dialog_content = "Espero mesmo que a Oficial Vivian fique mais um pouco para recuperar suas forças. Assim, Philyshy pode descansar um pouco mais...",
  ui_story_10_1_1_4_dialog_content = "Miau?",
  ui_story_10_1_1_5_dialog_content = "Cadê o novo paciente? Estou a caminho!",
  ui_story_10_1_1_6_dialog_content = "Madame, por favor, não voe por aqui!",
  ui_story_10_1_1_7_dialog_content = "Já foi, miau?",
  ui_story_10_1_1_8_dialog_content = "Hehehe, agora é a chance da Philyshy...",
  ui_story_10_1_1_9_dialog_content = "<color=#e8d9bb>Vuuush!</color>",
  ui_story_10_1_1_10_dialog_content = "Afe, cansei de ficar aqui! Não me deixam fazer nada até me recuperar...",
  ui_story_10_1_1_11_dialog_content = "Kiuu!",
  ui_story_10_1_1_12_dialog_content = "Obrigado por me consolar, Curie. A ansiedade bateu, só isso...",
  ui_story_10_1_1_13_dialog_content = "Por que não me ajuda a vigiar lá fora um pouco?",
  ui_story_10_1_1_14_dialog_content = "Kiuu!",
  ui_story_10_1_1_15_dialog_content = "Ah, uma coisinha...",
  ui_story_10_1_1_16_dialog_content = "<color=#e8d9bb>*Sussurros*</color>",
  ui_story_10_1_1_17_dialog_content = "Ei, você aí. Suas orelhas tão quase varrendo o chão... A curiosidade matou a gata.",
  ui_story_10_1_1_18_dialog_content = "Miau? Mas a Philyshy não tá varrendo o chão!",
  ui_story_10_1_1_19_dialog_content = "Philyshy só tá tentando detectar inimigos pela vibração do chão!",
  ui_story_10_1_1_20_dialog_content = "Eu sei o que te preocupa.",
  ui_story_10_1_1_21_dialog_content = "Mesmo que tenham preparado esse quarto só pra mim, não há dúvidas...",
  ui_story_10_1_1_22_dialog_content = "Não há vigilância aqui.",
  ui_story_10_1_1_S2_dialog_content = "Só querem que eu fique um pouco mais em Lumópolis.",
  ui_story_10_1_1_23_dialog_content = "Que novidades você traz pra mim?",
  ui_story_10_1_1_24_dialog_content = "Hehehe, essa é a Vivian que eu conheço! Já sacou a Philyshy!",
  ui_story_10_1_1_25_dialog_content = "A-ham, sempre que Philyshy consegue informações sobre <color=#FFB400>Forsakin</color>, Philyshy traz pra você.",
  ui_story_10_1_1_26_dialog_content = "O que mais você descobriu sobre ela?",
  ui_story_10_1_1_27_dialog_content = "Difícil dizer, miau.",
  ui_story_10_1_1_28_dialog_content = "Afinal de contas... Mesmo no relatório interno, ela está <color=#FFB400>morta</color> há 9 anos.",
  ui_story_10_1_1_29_dialog_content = "Depois que o grande incêndio consumiu a Subcidade inteirinha...",
  ui_story_10_1_1_30_dialog_content = "Todos presumiram que ela morreu no incêndio.",
  ui_story_10_1_1_31_dialog_content = "Mas depois, uma equipe de investigação achou corpos de Eclipsitas e Aurorians nas ruínas.",
  ui_story_10_1_1_32_dialog_content = "Quando ouvi que Forsakin plantou a <color=#FFB400>Semente</color> dentro do corpo de PlayerName...",
  ui_story_10_1_1_33_dialog_content = "Foi só juntar todas as peças, miau!",
  ui_story_10_1_1_34_dialog_content = "Você acha que isso tem alguma relação com a pesquisa de Forsakin?",
  ui_story_10_1_1_35_dialog_content = "É bem provável que ela... <color=#FFB400>já tenha virado Eclipsita</color>.",
  ui_story_10_1_1_36_dialog_content = "Como a Grande Marechal reagiu ao descobrir que Forsakin ainda está viva?",
  ui_story_10_1_1_37_dialog_content = "Miau... Sobre isso...",
  ui_story_10_1_1_38_dialog_content = "O que foi? Por que o nervosismo?",
  ui_story_10_1_1_39_dialog_content = "Vo-Você sabe do relacionamento que elas tinham, né? Então...",
  ui_story_10_1_1_40_dialog_content = "Eu sei o que te preocupa. É sobre <color=#FFB400>Forsakin ser a irmã mais nova da Grande Marechal</color>, correto?",
  ui_story_10_1_1_41_dialog_content = "Exato! Minha mestra nunca erra, miau. Só uma pista e você já sacou tudo que a Philyshy quer dizer.",
  ui_story_10_1_1_42_dialog_content = "Conte o que aconteceu.",
  ui_story_10_1_1_43_dialog_content = "A Grande Marechal pegou todos os Comandantes da Legião e partiu. Ela disse que é para a reunião dos comandantes, mas...",
  ui_story_10_1_1_44_dialog_content = "Philyshy acha que é diferente dessa vez.",
  ui_story_10_1_1_45_dialog_content = "A Grande Marechal confia muito nos quatro Comandantes da Legião, os guerreiros mais poderosos de Illumina.",
  ui_story_10_1_1_46_dialog_content = "Madame... Você acha que a Grande Marechal os levou para caçar Forsakin?",
  ui_story_10_1_1_47_dialog_content = "Sua avaliação sobre Eclipsitas é exemplar, Philyshy.",
  ui_story_10_1_1_48_dialog_content = "No entanto, quando se trata de nossos aliados, parece que precisa melhorar suas análises.",
  ui_story_10_1_1_49_dialog_content = "Miau...",
  ui_story_10_1_1_50_dialog_content = "Pode só me contar a resposta, madame? O cérebro de Philyshy não consegue acompanhar...",
  ui_story_10_1_1_51_dialog_content = "Você acredita mesmo que a Grande Marechal abusaria de seus poderes e ficaria cega por vingança?",
  ui_story_10_1_1_52_dialog_content = "Miau? A Philyshy não quis acusar a Grande Marechal! De verdade!",
  ui_story_10_1_1_53_dialog_content = "Eu sei... Tudo bem, só me deixa explicar.",
  ui_story_10_1_1_54_dialog_content = "A aparência de Forsakin é um sinal pra nós.",
  ui_story_10_1_1_55_dialog_content = "Quando predadores encurralam suas presas e se preparam pra matar... Aí é que ficam vulneráveis.",
  ui_story_10_1_1_56_dialog_content = "Miau! Entendi! Philyshy não deveria se meter nos assuntos da Grande Marechal, certo?",
  ui_story_10_1_1_57_dialog_content = "Afinal, a Grande Marechal certamente tem um plano!",
  ui_story_10_1_1_58_dialog_content = "Sim. Espero que você saiba disso. Em todo caso, não fique criando teorias sobre a Grande Marechal, Philyshy.",
  ui_story_10_1_1_59_dialog_content = "Certo, Miau!",
  ui_story_10_1_1_60_dialog_content = "Então a Philyshy continua investigando a Semente?",
  ui_story_10_1_1_61_dialog_content = "Mas é claro!",
  ui_story_10_1_1_62_dialog_content = "Então a Philyshy pode procurar Vice e os demais, miau?",
  ui_story_10_1_1_63_dialog_content = "Quê? Como você chegou a essa conclusão?",
  ui_story_10_1_1_64_dialog_content = "Simples, consegui minha informação sobre a Semente da Vice e de PlayerName!",
  ui_story_10_1_1_65_dialog_content = "No caminho pra cá, eu escutei algo sobre Aviduz sendo derrubada do céu, miau!",
  ui_story_10_1_1_66_dialog_content = "Então disseram que uma Colossus deixou Lumópolis alguns dias atrás!",
  ui_story_10_1_1_67_dialog_content = "Então quase certeza que a Vice e seus amigos partiram <color=#FFB400>em busca da Aviduz</color>, miau!",
  ui_story_10_1_1_68_dialog_content = "Se a Semente e a Aviduz estão relacionadas... Por que não ir atrás da Aviduz?",
  ui_story_10_1_1_69_dialog_content = "Philyshy... Você é brilhante...",
  ui_story_10_1_1_70_dialog_content = "Você está absolutamente certa. PlayerName e Vice estão indo atrás de Aviduz nesse momento.",
  ui_story_10_1_1_71_dialog_content = "Philyshy pode ir junto?",
  ui_story_10_1_1_72_dialog_content = "Só pra garantir, você não tá indo só pra se divertir, certo?",
  ui_story_10_1_1_73_dialog_content = "Eu? Miaugina! Philyshy tem um mau pressentimento sobre isso...",
  ui_story_10_1_1_74_dialog_content = "Afinal, tem relação com Schummer e Forsakin. Não só pra investigar, mas por segurança também.",
  ui_story_10_1_1_75_dialog_content = "É melhor que eu vá com eles!",
  ui_story_10_1_1_76_dialog_content = "Além do mais, só de pensar em toda essa informação sobre Forsakin fico tão animada que não consigo ficar quieta, miau!",
  ui_story_10_1_1_77_dialog_content = "E se Forsakin conseguir capturar PlayerName e Vice e fizer experimentos neles?",
  ui_story_10_1_1_78_dialog_content = "Certo... Entendi seu raciocínio.",
  ui_story_10_1_1_79_dialog_content = "Mas não se preocupe tanto com Vice e seus amigos.",
  ui_story_10_1_1_80_dialog_content = "Antes de partirem, discutimos possibilidades do que pode acontecer quando encontrarem Forsakin.",
  ui_story_10_1_1_81_dialog_content = "O que importa é que a Capitã Carleen está com eles também.",
  ui_story_10_1_1_82_dialog_content = "O que significa... Que Lumópolis tomou frente em tudo que diz respeito a Schummer.",
  ui_story_10_1_1_83_dialog_content = "Miau? Entendi...",
  ui_story_10_1_1_84_dialog_content = "Então melhor eu ficar, eu acho...",
  ui_story_10_1_1_85_dialog_content = "De fato. Até que a situação esteja resolvida, primeiro aguardamos por notícias de Vice.",
  ui_story_10_2_1_1_dialog_content = "Hã...",
  ui_story_10_2_1_2_dialog_content = "O que vamos fazer agora?",
  ui_story_10_2_1_3_dialog_content = "Eliminar quem estiver no caminho, claro! Tem outra opção? Ou quer que ela fuja?",
  ui_story_10_2_1_4_dialog_content = "Acalme-se.",
  ui_story_10_2_1_5_dialog_content = "É óbvio que estamos sendo atraídos pra lá de propósito.",
  ui_story_10_2_1_6_dialog_content = "Dã, claro!",
  ui_story_10_2_1_7_dialog_content = "Se entrarmos, cairemos na armadilha de Forsakin.",
  ui_story_10_2_1_8_dialog_content = "Se não entrarmos, estaremos facilitando sua fuga!",
  ui_story_10_2_1_9_dialog_content = "Sem contar que você também tá atrás de <color=#FFB400>Schummer</color>.",
  ui_story_10_2_1_10_dialog_content = "Só sei que Schummer ainda está viva e dentro da Aviduz!",
  ui_story_10_2_1_11_dialog_content = "Posso sentir sua presença, mas é muito fraca... Acho que está ferida.",
  ui_story_10_2_1_12_dialog_content = "Precisamos ter cuidado. Talvez se fortalecermos e defendermos essa posição...",
  ui_story_10_2_1_13_dialog_content = "Parece que você quer pedir reforços à Lumópolis ou Illumina. Certo?",
  ui_story_10_2_1_14_dialog_content = "Nem pense nisso. Até eles aparecerem, vai ser tarde demais.",
  ui_story_10_2_1_15_dialog_content = "Pensa com a cabeça, o instinto nem sempre resolve.",
  ui_story_10_2_1_16_dialog_content = "Ha! Se eles só enviaram você... Tá meio óbvio, né?",
  ui_story_10_2_1_17_dialog_content = "Tantos soldados de Lumópolis morreram aqui... Eles sabem da situação aqui!",
  ui_story_10_2_1_18_dialog_content = "Se quisessem mesmo ajudar, não esperariam por seu chamado.",
  ui_story_10_2_1_19_dialog_content = "Ãh, n-não acho que discutir seja a melhor opção agora...",
  ui_story_10_2_1_20_dialog_content = "Talvez se gritarmos bem alto, nossos aliados vão ouvir e vir nos salvar...",
  ui_story_10_2_1_21_dialog_content = "Vai esperar que eles nos encontrem? A gente caiu aqui! Ninguém vai nos achar se não caírem também!",
  ui_story_10_2_1_22_dialog_content = "Verdade... Além do mais, não acho que eles conseguiriam encontrar esse lugar...",
  ui_story_10_2_1_23_dialog_content = "Forsakin realmente preparou uma armadilha só pra nos matar?",
  ui_story_10_2_1_24_dialog_content = "Eu não acho que seja esse o caso...",
  ui_story_10_2_1_25_dialog_content = "Quando lutamos mais cedo, sequer acertei ela.",
  ui_story_10_2_1_26_dialog_content = "Mesmo que seja tão poderosa, parece até que...",
  ui_story_10_2_1_27_dialog_content = "<color=#FFB400>Ela não planeja nos atacar.</color>",
  ui_story_10_2_1_28_dialog_content = "Será que ela quer que vejamos a Schummer?",
  ui_story_10_2_1_29_dialog_content = "Não sabemos o suficiente...",
  ui_story_10_2_1_30_dialog_content = "PlayerName, você consegue usar seus poderes psíquicos para saber o que Forsakin tá pensando?",
  ui_story_10_2_1_31_dialog_content = "Na verdade... Eu tentei isso antes...",
  ui_story_10_2_1_32_dialog_content = "Perdão, <color=#FFB400>não consigo usar meus poderes em Forsakin dessa forma</color>.",
  ui_story_10_2_1_33_dialog_content = "Por quê?",
  ui_story_10_2_1_34_dialog_content = "Não sei explicar. É só que...",
  ui_story_10_2_1_35_dialog_content = "Ouvir os pensamentos de alguém sempre é difícil.",
  ui_story_10_2_1_36_dialog_content = "Distância, o poder do usuário, se o alvo está ou não resistindo... Muitos fatores podem influenciar o resultado dessa habilidade.",
  ui_story_10_2_1_37_dialog_content = "Na verdade, só funcionou bem quando eu senti a Schummer agorinha...",
  ui_story_10_2_1_38_dialog_content = "E também... parece estar ficando mais fácil.",
  ui_story_10_2_1_39_dialog_content = "A única coisa que sei com certeza é que Schummer está seriamente ferida.",
  ui_story_10_2_1_40_dialog_content = "Vice, Carleen... Eu...",
  ui_story_10_2_1_41_dialog_content = "Vamos! A gente sempre foi com tudo quando as coisas pareciam perigosas, e hoje não vai ser diferente!",
  ui_story_10_2_1_42_dialog_content = "Beleza, vamos observar a área. Vou liderar o caminho.",
  ui_story_10_2_1_43_dialog_content = "Agora você quer entrar? Tá até correndo mais rápido que eu!",
  ui_story_10_2_1_44_dialog_content = "Vocês realmente conversaram pra caramba e no fim chegaram à mesma conclusão...",
  ui_story_10_2_1_45_dialog_content = "Sei que você e Vice são próximos, mas quando a Carleen começou a lhe dar ouvidos também?",
  ui_story_10_2_1_46_dialog_content = "Elas não tão me ouvindo... Vice e Carleen têm me ajudado todo esse tempo, não o contrário, então tenho muita gratidão a elas.",
  ui_story_10_2_1_47_dialog_content = "Só espero que eu possa retribuir a ajuda delas depois que isso acabar.",
  ui_story_10_2_1_48_dialog_content = "Vamos lá...",
  ui_story_10_2_1_49_dialog_content = "Então essa é Aviduz, hein?",
  ui_story_10_2_1_50_dialog_content = "Haha, nada de assustador aqui! Tá tudo tão detonado, sequer seria capaz de matar um verme da areia.",
  ui_story_10_2_1_51_dialog_content = "É porque Lumópolis a derrubou.",
  ui_story_10_2_1_52_dialog_content = "Sim, sim, não precisa me lembrar disso.",
  ui_story_10_2_1_53_dialog_content = "Só estava respondendo suas dúvidas... Ou pensou que Lumópolis não era poderosa o suficiente pra isso?",
  ui_story_10_2_1_54_dialog_content = "*Cof* Hã, também pode ser porque Aviduz gastou todo seu poder...",
  ui_story_10_2_1_55_dialog_content = "*Cof*",
  ui_story_10_2_1_56_dialog_content = "Tá com alguma coisa na garganta? Medo de discutirmos de novo?",
  ui_story_10_2_1_57_dialog_content = "Não... É por causa do Fluxo Escuro...",
  ui_story_10_2_1_58_dialog_content = "Aviduz está em pedaços, mas o Fluxo Escuro ainda é tão denso aqui...",
  ui_story_10_2_1_59_dialog_content = "Grrr...",
  ui_story_10_2_1_60_dialog_content = "Um Eclipsita? Fiquem alerta!",
  ui_story_10_2_1_61_dialog_content = "Aahhhhhh!",
  ui_story_10_2_2_1_dialog_content = "Graaah!",
  ui_story_10_2_2_2_dialog_content = "Essa não! Cuidado, PlayerName!",
  ui_story_10_2_2_3_dialog_content = "Fora daqui!",
  ui_story_10_2_2_4_dialog_content = "Você tá bem?",
  ui_story_10_2_2_5_dialog_content = "*Arfando* Ah... Valeu...",
  ui_story_10_2_2_6_dialog_content = "Tô bem, mas minhas calças quase pegaram fogo...",
  ui_story_10_2_2_7_dialog_content = "Foi mal! Um escapou...",
  ui_story_10_2_2_8_dialog_content = "Tá ali!",
  ui_story_10_2_2_9_dialog_content = "Aahhhhhh!",
  ui_story_10_2_2_10_dialog_content = "Quê? Por que ele fugiu? Volta aqui...",
  ui_story_10_2_2_11_dialog_content = "Aonde você pensa que vai?!",
  ui_story_10_2_2_12_dialog_content = "Grrr...",
  ui_story_10_2_2_13_dialog_content = "Estranho... É como se esses Eclipsitas fossem cegos. Eles não podem nos ver?",
  ui_story_10_2_2_14_dialog_content = "Que estranho... Normalmente, Eclipsitas atacam logo que nos veem.",
  ui_story_10_2_2_15_dialog_content = "Mas esses Eclipsitas parecem não querer nos atacar...",
  ui_story_10_2_2_16_dialog_content = "E sim fugir de nós.",
  ui_story_10_2_2_17_dialog_content = "Pra mim tanto faz. Esquece esses vermes, vamos direto pra Forsakin acabar logo com isso.",
  ui_story_10_2_2_18_dialog_content = "Esse comportamento inconstante pode estar relacionado à Forsakin. De qualquer forma, fiquem alertas.",
  ui_story_10_2_2_19_dialog_content = "É possível, concordo.",
  ui_story_10_2_2_20_dialog_content = "Precisamos tirar esses Eclipsitas do caminho enquanto progredimos. Do contrário...",
  ui_story_10_2_2_21_dialog_content = "Podemos acabar encurralados por Eclipsitas e atacados de todos os lados.",
  ui_story_10_2_2_22_dialog_content = "Eu sei que o Fluxo Escuro é pesado pra você encarar, PlayerName...",
  ui_story_10_2_2_23_dialog_content = "Consegue usar suas habilidades psíquicas para analisar o caminho?",
  ui_story_10_2_2_24_dialog_content = "Tentarei.",
  ui_story_10_2_2_25_dialog_content = "...",
  ui_story_10_2_2_26_dialog_content = "<color=#e8d9bb>Zuuup...</color>",
  ui_story_10_2_2_27_dialog_content = "Brrr! Da onde tá vindo essa corrente de ar?",
  ui_story_10_2_2_28_dialog_content = "Shh! Fala mais baixo, não tá vendo que o PlayerName tá se concentrando?",
  ui_story_10_2_2_29_dialog_content = "Mas, chefe... Você tá fazendo bem mais barulho que eu...",
  ui_story_10_2_2_30_dialog_content = "Xiu...",
  ui_story_10_2_2_31_dialog_content = "(O Fluxo Escuro...)",
  ui_story_10_2_2_32_dialog_content = "(O Fluxo Escuro parece estar se concentrando em uma direção.)",
  ui_story_10_2_2_33_dialog_content = "(Que nojo... A densidade fica alternando entre grossa e fina... Não posso suportar mais disso.)",
  ui_story_10_2_2_34_dialog_content = "(Eclipsita... Eclipsita...)",
  ui_story_10_2_2_35_dialog_content = "(São todos Eclipsitas.)",
  ui_story_10_2_2_36_dialog_content = "(Meu estômago tá revirando... Que cheiro é esse?)",
  ui_story_10_2_2_37_dialog_content = "(E...)",
  ui_story_10_2_2_38_dialog_content = "<color=#e8d9bb>Crunch...</color>",
  ui_story_10_2_2_39_dialog_content = "(Que barulho é esse?)",
  ui_story_10_2_2_40_dialog_content = "<color=#e8d9bb>Crunch</color>",
  ui_story_10_2_2_41_dialog_content = "(Algo rangendo os dentes?)",
  ui_story_10_2_2_42_dialog_content = "<color=#e8d9bb>Crunch</color>",
  ui_story_10_2_2_43_dialog_content = "(Não, tá mastigando alguma coisa...)",
  ui_story_10_2_2_44_dialog_content = "<color=#e8d9bb>Crunch</color>",
  ui_story_10_2_2_45_dialog_content = "(Uma coisa... grudenta... e fedida...)",
  ui_story_10_2_2_46_dialog_content = "(Esse cheiro... é nojento...)",
  ui_story_10_2_2_47_dialog_content = "(Também consigo sentir dor...)",
  ui_story_10_2_2_48_dialog_content = "(O que é isso? Entre os dentes e debaixo da língua...)",
  ui_story_10_2_2_49_dialog_content = "(Na garganta também... Algo com grumos e molhado?!)",
  ui_story_10_2_2_50_dialog_content = "Ai...",
  ui_story_10_2_2_51_dialog_content = "Esses Eclipsitas... têm um gosto horrível.",
  ui_story_10_3_1_1_dialog_content = "Ugh!",
  ui_story_10_3_1_2_dialog_content = "PlayerName! Sai dessa!",
  ui_story_10_3_1_3_dialog_content = "Ugh... *Tosse*",
  ui_story_10_3_1_4_dialog_content = "Eu... voltei... Ugh!",
  ui_story_10_3_1_5_dialog_content = "O que houve com você? Nunca te vi assim depois de usar seus poderes!",
  ui_story_10_3_1_6_dialog_content = "*Tossindo* Foi mal... Senti uma coisa bem nojenta. Ugh!",
  ui_story_10_3_1_7_dialog_content = "Tá bem, tá bem, agora deixa isso sair.",
  ui_story_10_3_1_8_dialog_content = "Uh... T-Talvez você devesse vomitar primeiro, ou então pode engasgar enquanto fala.",
  ui_story_10_3_1_9_dialog_content = "Os Celestitas têm esse tipo de reação depois de usar as habilidades psíquicas, Vice?",
  ui_story_10_3_1_10_dialog_content = "Não, isso nunca tinha acontecido... a não ser que algo tenha acontecido.",
  ui_story_10_3_1_11_dialog_content = "Algo realmente horrível.",
  ui_story_10_3_1_12_dialog_content = "Grrr...",
  ui_story_10_3_1_13_dialog_content = "Venha aqui, é uma ordem!",
  ui_story_10_3_1_14_dialog_content = "Grrr...",
  ui_story_10_3_1_15_dialog_content = "Entre rastejando!",
  ui_story_10_3_1_16_dialog_content = "Grrr...",
  ui_story_10_3_1_17_dialog_content = "Excelente.",
  ui_story_10_3_1_18_dialog_content = "Graagh!",
  ui_story_10_3_1_19_dialog_content = "Cale-se. Você tá me esmagando.",
  ui_story_10_3_1_20_dialog_content = "Gah... gah!",
  ui_story_10_3_1_21_dialog_content = "...",
  ui_story_10_3_1_22_dialog_content = "Assim é melhor.",
  ui_story_10_3_1_23_dialog_content = "Forsakin, não tem como pedir pra eles serem mais cuidadosos ao entrar?",
  ui_story_10_3_1_24_dialog_content = "Meu corpo tá me matando... Você tá tentando me esmagar com essas coisas imundas também?",
  ui_story_10_3_1_25_dialog_content = "O quê? Não ouvi direito.",
  ui_story_10_3_1_26_dialog_content = "Não se faça de desentendida.",
  ui_story_10_3_1_27_dialog_content = "Consigo te ouvir muito bem... Como é que você não me ouve se eu tô gritando?",
  ui_story_10_3_1_28_dialog_content = "Você acha que o volume da sua voz tem algo a ver com eu te ouvir ou não?",
  ui_story_10_3_1_29_dialog_content = "Mas se isso vai te fazer comer um pouco mais, acho que não me importo de conversar um pouco com você.",
  ui_story_10_3_1_30_dialog_content = "Quem consegue comer essas coisas?",
  ui_story_10_3_1_31_dialog_content = "A raiva vai estimular seu crescimento. Você precisa aprender a usá-la.",
  ui_story_10_3_1_32_dialog_content = "Não é pra comer os Eclipsitas, é só uma ou duas mordidas pra absorver o Fluxo Escuro deles.",
  ui_story_10_3_1_33_dialog_content = "Esse já é o jeito mais fácil. Não me diga que chegou até aqui sem aprender a comer direito.",
  ui_story_10_3_1_34_dialog_content = "Não ouse me tratar como criança...",
  ui_story_10_3_1_35_dialog_content = "As Sementes nas costas deles são duras demais... Não consigo comer.",
  ui_story_10_3_1_36_dialog_content = "Só a casca é dura. É só moer, seus dentes de Eclipsita são mais fortes do que você pensa.",
  ui_story_10_3_1_37_dialog_content = "Eu sei... Só quis desabafar, só isso.",
  ui_story_10_3_1_38_dialog_content = "...",
  ui_story_10_3_1_39_dialog_content = "Parece que seu humor tá melhorando bastante, agora que você tá se recuperando das feridas.",
  ui_story_10_3_1_40_dialog_content = "Sinto que eu deveria te elogiar um pouco.",
  ui_story_10_3_1_41_dialog_content = "O que você quer dizer com isso?",
  ui_story_10_3_1_42_dialog_content = "Tenho que admitir, você leva jeito pra escolher pessoas, acho que o PlayerName não é inútil, afinal.",
  ui_story_10_3_1_43_dialog_content = "Meu convite pode não ter dado certo, mas aquele Celestita é um ótimo motivo pra continuar estimulando seu crescimento.",
  ui_story_10_3_1_44_dialog_content = "Acho que você deve estar bem feliz por ter sido tão machucada pelo seu velho amigo e por Lumópolis.",
  ui_story_10_3_1_45_dialog_content = "Mais um insulto e eu arranco os dentes da sua boca...",
  ui_story_10_3_1_46_dialog_content = "Que delicadeza. Você precisa desenvolver resistência mental, e rápido.",
  ui_story_10_3_1_47_dialog_content = "O que você tá tentando dizer?",
  ui_story_10_3_1_48_dialog_content = "Eu tô dizendo... que seu velho amigo PlayerName já entrou na Aviduz.",
  ui_story_10_3_1_49_dialog_content = "Aquele Celestita com certeza quer te matar e se vingar.",
  ui_story_10_3_1_50_dialog_content = "...",
  ui_story_10_3_1_51_dialog_content = "Mas saiba que vou ganhar um tempo pra você.",
  ui_story_10_3_1_52_dialog_content = "Vou tentar atrasá-los até você terminar de absorver energia suficiente pra concluir a transformação.",
  ui_story_10_3_1_53_dialog_content = "De qualquer forma, não temos muito tempo.",
  ui_story_10_3_1_54_dialog_content = "<color=#e8d9bb>Crunch</color>",
  ui_story_10_3_1_55_dialog_content = "Espero que você consiga finalmente se <color=#FFB400>completar</color>.",
  ui_story_10_3_1_56_dialog_content = "Se conseguir, tente não ser como sua Aviduz...",
  ui_story_10_3_1_57_dialog_content = "Chegar a Lumópolis não foi fácil, e ainda assim ela foi nocauteada com um só golpe.",
  ui_story_10_3_1_58_dialog_content = "Cala essa boca...",
  ui_story_10_3_1_59_dialog_content = "Não precisa me lembrar disso.",
  ui_story_10_3_1_60_dialog_content = "Subestimar o inimigo sempre foi seu ponto mais fraco...",
  ui_story_10_3_1_61_dialog_content = "...",
  ui_story_10_3_1_62_dialog_content = "Meu único exemplo de negligência... foi superestimar a mente do PlayerName.",
  ui_story_10_3_1_63_dialog_content = "Aproveitar oportunidades, ganhar força e poder...",
  ui_story_10_3_1_64_dialog_content = "Naquela mente teimosa, nada disso importava, até aqueles Aurorians eram mais valiosos!",
  ui_story_10_3_1_65_dialog_content = "Que piada. Fez amizade com uns Aurorians e se sentiu mais forte do que nunca? Patético!",
  ui_story_10_3_1_66_dialog_content = "Demonstrei minha sinceridade e generosidade, mas aonde isso me levou?",
  ui_story_10_3_1_67_dialog_content = "Ah, PlayerName, nada diferente daqueles Celestitas imundos, que não sabiam distinguir o bom do mau.",
  ui_story_10_3_1_68_dialog_content = "Tolos, todos eles.",
  ui_story_10_3_1_69_dialog_content = "Vou libertá-los de suas mentes tolas...",
  ui_story_10_3_1_70_dialog_content = "Eles vão pagar, vou levá-los à morte, assustados e arrependidos.",
  ui_story_10_3_1_71_dialog_content = "Tá melhor? Vamos, nos conte o que você sentiu.",
  ui_story_10_3_1_72_dialog_content = "Schummer tava comendo Eclipsitas...",
  ui_story_10_3_1_73_dialog_content = "Ahn? E eu achando que você sentiu algo realmente ruim, mas era só ela comendo Eclipsitas.",
  ui_story_10_3_1_74_dialog_content = "Relaxa, tenho certeza que os ferimentos só fizeram ela lembrar que não comia há alguns dias, então ela comeu o que podia.",
  ui_story_10_3_1_75_dialog_content = "Mas dá pra comer Eclipsitas? Eles não se despedaçam depois de morrer?",
  ui_story_10_3_1_76_dialog_content = "Dá pra dar uma ou duas mordidas antes disso, mas pelo que sei, o gosto é pior que vômito de monstro.",
  ui_story_10_3_1_77_dialog_content = "Quem tem estômago pra comer um Eclipsita com certeza tem algo de errado na cabeça.",
  ui_story_10_3_1_78_dialog_content = "Mas pelo que sabemos deles, os Eclipsitas não precisam comer e não apresentam comportamentos canibais.",
  ui_story_10_3_1_79_dialog_content = "Acho que ela tá absorvendo a energia deles... O Fluxo Escuro tava especialmente grosso lá.",
  ui_story_10_3_1_80_dialog_content = "Ela tá procurando um jeito de se recuperar. Precisamos nos apressar. Eca...",
  ui_story_10_3_1_81_dialog_content = "Ugh... Só de ouvir vocês eu fico com vontade de vomitar.",
  ui_story_10_3_1_82_dialog_content = "Tudo bem, acho que não tenho mais nada pra vomitar. Ugh...",
  ui_story_10_3_1_83_dialog_content = "Eca, até você arfando em seco é nojento... Olha pra você, o corpo todo tremendo!",
  ui_story_10_3_1_84_dialog_content = "Vamos lá...",
  ui_story_10_3_1_85_dialog_content = "Espera, você não consegue nem ficar de pé! Vem, senta um pouco!",
  ui_story_10_3_1_86_dialog_content = "Só um pouquinho!",
  ui_story_10_3_1_87_dialog_content = "Eu vou ficar bem. Ainda posso ajudar todo mundo...",
  ui_story_10_3_1_88_dialog_content = "Deixa disso, jovem. É pra descansar.",
  ui_story_10_3_1_89_dialog_content = "Se essa tal de Schummer escolheu se curar agora, isso só significa que ela não pode fugir.",
  ui_story_10_3_1_90_dialog_content = "Aqui, beba um pouco de água quente.",
  ui_story_10_3_1_91_dialog_content = "Por que não come alguma coisa pra recuperar a força também? Trouxemos algumas especialidades da Rediesel.",
  ui_story_10_3_1_92_dialog_content = "Bopper! Vem aqui e distribua seu charque de lagarto pra todos!",
  ui_story_10_3_1_93_dialog_content = "C-Claro! Se a Schummer tá recuperando energia, por que não fazemos o mesmo? Aqui, pegue um pouco!",
  ui_story_10_3_1_94_dialog_content = "Não fiquem muito relaxados.",
  ui_story_10_3_1_95_dialog_content = "Só me dê um pacote, e eu vou fazer o reconhecimento.",
  ui_story_10_3_1_96_dialog_content = "Tá, tudo bem. São bem convenientes também. Dá pra comer direto do pacote! São doces e picantes, além de serem bons pra reabastecer o vigor!",
  ui_story_10_3_1_97_dialog_content = "Viu, PlayerName? Até a Carleen tá disposta a comer, então você deveria pegar um pouco também.",
  ui_story_10_3_1_98_dialog_content = "Seu estômago deve estar completamente vazio depois de vomitar tanto. Você não vai conseguir lutar bem de estômago vazio!",
  ui_story_10_3_1_99_dialog_content = "Foi mal, eu realmente não quero comer nada depois daquilo. Capaz de eu vomitar de novo.",
  ui_story_10_3_1_100_dialog_content = "Ahn? Entendo... Então pelo menos beba mais água, tá?",
  ui_story_10_3_1_101_dialog_content = "Temos outra garrafa aqui. Toma.",
  ui_story_10_3_1_102_dialog_content = "Uma multidão de Eclipsitas à frente. Estarão aqui a qualquer momento.",
  ui_story_10_3_1_103_dialog_content = "Não se preocupe em dar instruções, PlayerName.",
  ui_story_10_3_1_104_dialog_content = "Enquanto estivermos lutando, aproveite pra recuperar o fôlego.",
  ui_story_10_3_1_105_dialog_content = "Isso aí! Não vamos deixar um único Eclipsita chegar perto de você, então relaxe e descanse!",
  ui_story_10_3_1_106_dialog_content = "Eclipsitas à vista! Preparem-se pra luta!",
  ui_story_10_3_2_1_dialog_content = "PlayerName! Você tava dando instruções agora mesmo?",
  ui_story_10_3_2_2_dialog_content = "Não falamos pra você descansar e recuperar energia?",
  ui_story_10_3_2_3_dialog_content = "Eu tô bem. Me sinto bem melhor agora.",
  ui_story_10_3_2_4_dialog_content = "Além disso, estabelecer um vínculo mental com vocês é muito melhor do que com Eclipsitas.",
  ui_story_10_3_2_5_dialog_content = "Esses Eclipsitas... Parece que encontraram a vontade de lutar de novo, não é mesmo?",
  ui_story_10_3_2_6_dialog_content = "É, parece que vamos ter que eliminá-los à medida que abrimos caminho.",
  ui_story_10_3_2_7_dialog_content = "Vamos lá. Tô melhor agora, eu juro.",
  ui_story_10_3_2_8_dialog_content = "Sinto muito. Se eu não tivesse te pedido pra fazer o reconhecimento com seus poderes, você não teria se machucado.",
  ui_story_10_3_2_9_dialog_content = "Tudo bem, não é culpa sua.",
  ui_story_10_3_2_10_dialog_content = "Eu fiquei enjoado porque de repente senti o inimigo se permitindo comer Eclipsitas.",
  ui_story_10_3_2_11_dialog_content = "Não vai me afetar da próxima vez.",
  ui_story_10_3_2_12_dialog_content = "Tudo bem, jovem, parece que você recuperou um pouco de força, afinal.",
  ui_story_10_3_2_13_dialog_content = "Então você conseguiu sentir a Forsakin ou não?",
  ui_story_10_3_2_14_dialog_content = "Vagamente, mas senti alguma coisa antes...",
  ui_story_10_3_2_15_dialog_content = "Acho que a Forsakin e a Schummer estão no mesmo lugar agora.",
  ui_story_10_3_2_16_dialog_content = "Então vamos seguir caminho. Temos todos o mesmo destino agora.",
  ui_story_10_3_2_17_dialog_content = "<color=#e8d9bb>Zuuup...</color>",
  ui_story_10_3_2_18_dialog_content = "Essa Colossus, é como se quanto mais avançamos, mais quebrada fica...",
  ui_story_10_3_2_19_dialog_content = "Realmente parece que ela vai desabar a qualquer momento. Nenhuma Colossus deveria chegar nesse estado.",
  ui_story_10_3_2_20_dialog_content = "Bom, o Dâmocles atingiu ela em cheio.",
  ui_story_10_3_2_21_dialog_content = "E ainda por cima, a Schummer drenou até a última gota de energia dela.",
  ui_story_10_3_2_22_dialog_content = "Essa Colossus já tá <color=#FFB400>morta</color>...",
  ui_story_10_3_2_23_dialog_content = "Você tá dizendo que a Schummer, como Navegadora dessa Colossus...",
  ui_story_10_3_2_24_dialog_content = "Matou a Colossus com as próprias mãos?",
  ui_story_10_3_2_25_dialog_content = "Nem os Eclipsitas machucam uns aos outros, mas ela sim. Se alguém poderia fazer algo tão maléfico, é ela.",
  ui_story_10_3_2_26_dialog_content = "Eu acreditaria se você dissesse que ela destruiria a Colossus, então o que é drenar a energia pra ela?",
  ui_story_10_3_2_27_dialog_content = "Ela é podre até o talo. PlayerName sabe disso melhor do que qualquer um de nós.",
  ui_story_10_3_2_28_dialog_content = "Vamos. Não podemos deixar que ela se recupere totalmente...",
  ui_story_10_7_1_1_dialog_content = "Absorver energia de outros Eclipsitas é um bom jeito de incorporar Fluxo Escuro...",
  ui_story_10_7_1_2_dialog_content = "Mas só certos Eclipsitas são capazes de dominar a arte da absorção de Fluxo Escuro...",
  ui_story_10_7_1_3_dialog_content = "...",
  ui_story_10_7_1_4_dialog_content = "Ah? Já dormiu, parece que ainda há esperança pra esse experimento.",
  ui_story_10_7_1_5_dialog_content = "Quem foi que veio conversar comigo sobre poder da última vez? Ah, agora eu lembro.",
  ui_story_10_7_1_6_dialog_content = "Alguém de Lumópolis... com cauda de inseto... Qual era o nome mesmo?",
  ui_story_10_7_1_7_dialog_content = "<color=#FFB400>Tédio</color>?",
  ui_story_10_7_1_8_dialog_content = "<color=#e8d9bb>Zuuup...</color>",
  ui_story_10_7_1_9_dialog_content = "Ugh... Outra corrente de ar?",
  ui_story_10_7_1_10_dialog_content = "Não... Isso é...",
  ui_story_10_7_1_11_dialog_content = "*Soluços*",
  ui_story_10_7_1_12_dialog_content = "Lágrimas?",
  ui_story_10_7_1_13_dialog_content = "Eclipsitas também podem chorar?",
  ui_story_10_7_1_14_dialog_content = "Pra trás, estão chegando.",
  ui_story_10_7_1_15_dialog_content = "E-Esse Eclipsita é assustador.",
  ui_story_10_7_1_16_dialog_content = "Espera um pouco... Por que parece que eu já vi esse Eclipsita?",
  ui_story_10_7_1_17_dialog_content = "Não... Não me diga que é outro Aurorian que foi transformado em um Eclipsita?!",
  ui_story_10_7_1_18_dialog_content = "Essa aparência, esses membros parecidos com raízes, e essa voz... A única coisa que me vem à cabeça...",
  ui_story_10_7_1_19_dialog_content = "Aquelas irmãs, <color=#FFB400>Shelt</color> e <color=#FFB400>Shire</color>, por fim se transformaram naquele monstro.",
  ui_story_10_7_1_20_dialog_content = "Irmãs? Não é só um Eclipsita?",
  ui_story_10_7_1_21_dialog_content = "Vimos elas se fundirem à força.",
  ui_story_10_7_1_22_dialog_content = "Sim, elas ficam dizendo, \"a mestra nos deu poder\", e agora elas vieram parar aqui.",
  ui_story_10_7_1_23_dialog_content = "*Soluços*",
  ui_story_10_7_1_24_dialog_content = "Hm, elas parecem estar correndo pra cá, embora bem lentamente... Deveríamos nos preparar pra lutar?",
  ui_story_10_7_1_25_dialog_content = "*Soluços* Mate...",
  ui_story_10_7_1_26_dialog_content = "Mate? Elas disseram \"mate\"? Estão planejando nos matar?",
  ui_story_10_7_1_27_dialog_content = "Não... Elas querem ser libertadas.",
  ui_story_10_7_1_28_dialog_content = "<color=#FFB400>\"Mate-nos\"</color>... Foi o que nos disseram uma vez.",
  ui_story_10_7_1_29_dialog_content = "Mas agora parece que ainda estão presas na dor.",
  ui_story_10_7_1_30_dialog_content = "Seus corpos foram trazidos pra cá e revividos, pra que pudessem ser usados de novo.",
  ui_story_10_7_1_31_dialog_content = "Usar métodos tão cruéis e inescrupulosos de novo e de novo. Só alguém realmente perturbado faria isso!",
  ui_story_10_7_1_32_dialog_content = "Ugh!",
  ui_story_10_7_1_33_dialog_content = "A essa altura, não há vestígio de humanidade ou consciência naquela figura.",
  ui_story_10_7_1_34_dialog_content = "Acabe com elas.",
  ui_story_10_7_1_35_dialog_content = "Depois disso, encontraremos o monstro responsável por essa atrocidade, e a mandaremos pra cova!",
  ui_story_10_7_2_1_dialog_content = "E-Elas estão aquietando?",
  ui_story_10_7_2_2_dialog_content = "Sim. Estão mortas agora, pela segunda vez.",
  ui_story_10_7_2_3_dialog_content = "Vice, PlayerName, encontrem materiais inflamáveis.",
  ui_story_10_7_2_4_dialog_content = "Vamos cremá-las.",
  ui_story_10_7_2_5_dialog_content = "Só espero que possamos ajudá-las a encontrar a paz, como <color=#FFB400>Gertzurde</color> encontrou.",
  ui_story_10_7_2_6_dialog_content = "Claro. Vamos dar uma olhada ao redor.",
  ui_story_10_7_2_7_dialog_content = "Quem raios é Gertzurde?",
  ui_story_10_7_2_8_dialog_content = "Um cavaleiro de Lumópolis, e o amor de Shelt.",
  ui_story_10_7_2_9_dialog_content = "Ele e Shelt se alistaram aos Eclipsitas, mas no final...",
  ui_story_10_7_2_10_dialog_content = "Ele se sacrificou por nós.",
  ui_story_10_7_2_11_dialog_content = "Lumópolis, de novo... Mesmo que não seja o lugar ou a hora certa, preciso te perguntar uma coisa.",
  ui_story_10_7_2_12_dialog_content = "Por que vocês de Lumópolis escolheriam se juntar aos Eclipsitas?",
  ui_story_10_7_2_13_dialog_content = "Você não precisa se preocupar com ataques de Eclipsitas, e sua vida também não é tão difícil.",
  ui_story_10_7_2_14_dialog_content = "Isso não é meio estranho?",
  ui_story_10_7_2_15_dialog_content = "Estamos todos trabalhando por um objetivo comum agora, Sinsa.",
  ui_story_10_7_2_16_dialog_content = "Então não mencione esse tipo de coisa.",
  ui_story_10_7_2_17_dialog_content = "Tudo bem.",
  ui_story_10_7_2_18_dialog_content = "Só estava falando o que penso. Afinal, não é todo dia que se tem a chance de falar com alguém de Lumópolis.",
  ui_story_10_7_2_19_dialog_content = "Enfim, se não se importa de usar meu fogo, também posso ajudar com a cremação.",
  ui_story_10_7_2_20_dialog_content = "Eu mesma vou resolver tudo isso, Sinsa. Não precisa se preocupar.",
  ui_story_10_7_2_21_dialog_content = "Também não preciso da sua ajuda.",
  ui_story_10_7_2_22_dialog_content = "Eu não estava planejando ajudar. Desde que você saiba o que deve fazer, isso já basta pra mim.",
  ui_story_10_7_2_23_dialog_content = "Vou fazer a vigia.",
  ui_story_10_7_2_24_dialog_content = "...",
  ui_story_10_7_2_25_dialog_content = "Uh, vou ajudar a encontrar coisas inflamáveis também.",
  ui_story_10_7_2_26_dialog_content = "O Sinsa pode ser um pouco exagerado às vezes, e não consegue não falar o que pensa...",
  ui_story_10_7_2_27_dialog_content = "Mas ele realmente não tem nada contra você ou seu povo.",
  ui_story_10_7_2_28_dialog_content = "Sim, entendi.",
  ui_story_10_7_2_29_dialog_content = "Acenda o fogo.",
  ui_story_10_7_2_30_dialog_content = "Avante, Noite Branca...",
  ui_story_10_7_2_31_dialog_content = "Em busca da liberdade, Shelt e Shire foram duas irmãs que se perderam. Que encontrem paz, e então a liberdade que tanto ansiaram.",
  ui_story_10_7_2_32_dialog_content = "Que o juízo recaia sob aqueles que as enganaram e manipularam.",
  ui_story_10_7_2_33_dialog_content = "E que <color=#FFB400>Schummer</color>, a perpetradora desses crimes hediondos, seja enviada ao túmulo em seguida.",
  ui_story_10_7_2_34_dialog_content = "Posso tentar encontrar a próxima direção que devemos seguir...",
  ui_story_10_7_2_35_dialog_content = "PlayerName? Você tá usando suas habilidades psíquicas de novo?",
  ui_story_10_7_2_36_dialog_content = "Uhum.",
  ui_story_10_7_2_37_dialog_content = "Para! E se você se machucar de novo?",
  ui_story_10_7_2_38_dialog_content = "Ugh.",
  ui_story_10_7_2_39_dialog_content = "PlayerName?!",
  ui_story_10_7_2_40_dialog_content = "Professor...",
  ui_story_10_7_2_41_dialog_content = "Espere um pouco, o que tá acontecendo aqui?",
  ui_story_10_7_2_42_dialog_content = "Eu tô bem, vou descobrir uma maneira de explorar à frente. Relaxa.",
  ui_story_10_7_2_43_dialog_content = "Professor Handro...",
  ui_story_10_7_2_44_dialog_content = "Mas que raios você fez? Por que você fez isso?!",
  ui_story_10_7_2_45_dialog_content = "Por que matou seus colegas estudantes?! Responda!!",
  ui_story_10_7_2_46_dialog_content = "Eu não fiz nada, professor.",
  ui_story_10_7_2_47_dialog_content = "Tudo que fiz foi provar minha coragem.",
  ui_story_10_7_2_48_dialog_content = "Qual é o seu problema?!",
  ui_story_10_7_2_49_dialog_content = "Provar sua coragem? Matando seus colegas?!",
  ui_story_10_7_2_50_dialog_content = "De novo não, professor, você nunca escuta tudo que as pessoas têm a dizer antes de julgá-las.",
  ui_story_10_7_2_51_dialog_content = "Você?!",
  ui_story_10_7_2_52_dialog_content = "T-Tá! Fala, então!",
  ui_story_10_7_2_53_dialog_content = "Eles apostaram comigo. Isso foi só eu mantendo a minha parte da aposta!",
  ui_story_10_7_2_54_dialog_content = "Aqueles tolos pensaram que já eram fortes o suficiente pra lutar contra Eclipsitas.",
  ui_story_10_7_2_55_dialog_content = "Então apostamos pra ver quem era corajoso o suficiente pra sair.",
  ui_story_10_7_2_56_dialog_content = "Isso tudo aconteceu por isso?",
  ui_story_10_7_2_57_dialog_content = "Só saímos pra dar uma olhada ao redor, professor. Nenhum de nós esperava encontrar mesmo Eclipsitas...",
  ui_story_10_7_2_58_dialog_content = "Eles sempre me excluíram! Me subestimaram! Tudo porque eu não conseguia usar minhas habilidades psíquicas tão bem quanto eles!",
  ui_story_10_7_2_59_dialog_content = "Você sempre disse que nunca devemos subestimar o potencial dos outros, professor! Mas algum dia eles te escutaram?",
  ui_story_10_7_2_60_dialog_content = "Não! Não escutaram!",
  ui_story_10_7_2_61_dialog_content = "Mas no final eu encontrei minha prova! Só eu sobrevivi!",
  ui_story_10_7_2_62_dialog_content = "Isso significa que eu sou a mais forte!",
  ui_story_10_7_2_63_dialog_content = "*Suspira*",
  ui_story_10_7_2_64_dialog_content = "Você ter voltado com vida foi sorte, Schummer!",
  ui_story_10_7_2_65_dialog_content = "Eu já te disse isso várias vezes...",
  ui_story_10_7_2_66_dialog_content = "Nós Celestitas somos, e sempre seremos, uma raça gentil e pacífica.",
  ui_story_10_7_2_67_dialog_content = "Sendo assim, não precisamos provar nada pra ninguém.",
  ui_story_10_7_2_68_dialog_content = "O mais importante em questão de força não é quem é mais forte, mas como ajudamos uns aos outros a enfrentar os perigos e difíceis realidades do mundo.",
  ui_story_10_7_2_69_dialog_content = "Enfrentar os perigos? Professor, você acredita mesmo que se esconder em Eraveil e nunca se arriscar a sair é enfrentar o perigo?",
  ui_story_10_7_2_70_dialog_content = "De novo, você está interpretando mal minhas palavras. Já te avisei mais vezes do que posso contar...",
  ui_story_10_7_2_71_dialog_content = "Há incontáveis Eclipsitas vagando pelo mundo fora de Eraveil.",
  ui_story_10_7_2_72_dialog_content = "Não somos como os Aurorians. Não podemos aproveitar o poder de Lúmina para lutar e nos defender.",
  ui_story_10_7_2_73_dialog_content = "Sem um jeito de nos defender, encontrar até mesmo um Eclipsita mais ou menos forte é a morte da nossa espécie.",
  ui_story_10_7_2_74_dialog_content = "Felizmente, temos tanto Eraveil quanto as Colossi.",
  ui_story_10_7_2_75_dialog_content = "Eraveil nos protege, e as Colossi podem nos levar muito acima do solo, pra longe de ataques Eclipsitas.",
  ui_story_10_7_2_76_dialog_content = "Mas ainda melhor que isso, temos nossas <color=#FFB400>habilidades psíquicas</color>, um poder único da nossa raça.",
  ui_story_10_7_2_77_dialog_content = "Com elas, podemos sentir rastros de luz, entender os pensamentos de nossos colegas e detectar inimigos e outros perigos.",
  ui_story_10_7_2_78_dialog_content = "Mas sem técnicas adequadas e experiência, não há como usar as habilidades psíquicas para detectar e evitar perigos.",
  ui_story_10_7_2_79_dialog_content = "Ter saído de Eraveil assim foi equivalente ao suicídio!",
  ui_story_10_7_2_80_dialog_content = "Detectar, escapar, todo mundo aqui é igual!",
  ui_story_10_7_2_81_dialog_content = "Algum de vocês já pensou o que faríamos se Eclipsitas de repente aparecessem aqui?!",
  ui_story_10_7_2_82_dialog_content = "Você realmente acha que Eraveil pode nos proteger pra sempre?!",
  ui_story_10_7_2_83_dialog_content = "Me diz, o que faríamos? Entraríamos nas Colossi e voaríamos pra longe? Pra onde iríamos?",
  ui_story_10_7_2_84_dialog_content = "Pro mundo grande e mau lá fora, onde morreríamos a qualquer momento?",
  ui_story_10_7_2_85_dialog_content = "Quem nesse mundo te disse que você morreria a qualquer momento lá fora?!",
  ui_story_10_7_2_86_dialog_content = "Eu já não te disse vezes o suficiente? Enquanto tivermos as Colossi...",
  ui_story_10_7_2_87_dialog_content = "Chega, eu já sei o que você vai dizer.",
  ui_story_10_7_2_88_dialog_content = "Professor, a verdadeira razão de sermos uma raça gentil e pacífica é que não temos força pra lutar por nós mesmos.",
  ui_story_10_7_2_89_dialog_content = "*Suspira* Teimosa até o fim, entendi. Não posso te culpar, Schummer.",
  ui_story_10_7_2_90_dialog_content = "Um dia você vai entender...",
  ui_story_10_7_2_91_dialog_content = "Eu não entendo. E não acho que um dia entenderei...",
  ui_story_10_7_2_92_dialog_content = "Pode sair agora, professor.",
  ui_story_10_7_2_93_dialog_content = "Você não vai fazer eu me arrepender de nada do que aconteceu.",
  ui_story_10_7_2_94_dialog_content = "Parece que você ainda precisa de mais tempo pra se acalmar.",
  ui_story_10_7_2_95_dialog_content = "Os anciãos já providenciaram a investigação do assunto.",
  ui_story_10_7_2_96_dialog_content = "Acredito que você não teve intenção de levar seus colegas à morte...",
  ui_story_10_7_2_97_dialog_content = "Mas até que os anciãos decidam sua punição, eu não tenho escolha senão te manter trancada aqui.",
  ui_story_10_7_2_98_dialog_content = "Além disso, esse livro é de um amigo seu. Ele me pediu pra trazê-lo para você.",
  ui_story_10_7_2_99_dialog_content = "Um amigo? Quem? Eu não tenho amigos...",
  ui_story_10_7_2_100_dialog_content = "Foi o <color=#FFB400>Mendelson</color>. Ele se preocupa com você. As notas dele também já foram péssimas.",
  ui_story_10_7_2_101_dialog_content = "Acredito que ele entende suas circunstâncias, e quer ser seu amigo.",
  ui_story_10_7_2_102_dialog_content = "Ele se preocupa comigo?",
  ui_story_10_7_2_103_dialog_content = "Schummer... Eu desejo com todo coração que um dia você perceba que todos a amam.",
  ui_story_10_7_2_104_dialog_content = "Peço que reflita profundamente sobre o que aconteceu durante seu confinamento e jejum. Todos esperam grandes coisas de você, então não os decepcione.",
  ui_story_10_7_2_105_dialog_content = "...",
  ui_story_10_7_2_106_dialog_content = "Perceber que <color=#FFB400>todos me amam</color>?",
  ui_story_10_7_2_107_dialog_content = "Sempre usam isso como desculpa pra me infernizarem. Que raiva...",
  ui_story_10_7_2_108_dialog_content = "...",
  ui_story_10_7_2_109_dialog_content = "Um livro, é?",
  ui_story_10_7_2_110_dialog_content = "<color=#FFB400>Ada e a Colossus</color>?!",
  ui_story_10_7_2_111_dialog_content = "Que brincadeira idiota é essa?! Estão me zoando porque sabem que não consigo me conectar a uma Colossus?",
  ui_story_10_7_2_112_dialog_content = "...",
  ui_story_10_7_2_113_dialog_content = "Mendelson...",
  ui_story_10_7_2_114_dialog_content = "Ah, o cara de cabelo ainda mais ruivo que o meu, parece ainda mais fraco do que eu.",
  ui_story_10_7_2_115_dialog_content = "Ele também não deve conseguir se conectar a uma Colossus.",
  ui_story_10_7_2_116_dialog_content = "<color=#e8d9bb>Tinido</color>",
  ui_story_10_7_2_117_dialog_content = "O que é isso?",
  ui_story_10_7_2_118_dialog_content = "<color=#FFB400>Uma chave</color>?!",
  ui_story_10_7_2_119_dialog_content = "Tsc. Essa porta, eu conseguiria quebrá-la agora mesmo se eu quisesse...",
  ui_story_10_8_1_1_dialog_content = "Depois de incorporar o Fluxo Escuro da Semente.",
  ui_story_10_8_1_2_dialog_content = "O Fluxo Escuro vai começar a deixá-los mais confortáveis.",
  ui_story_10_8_1_3_dialog_content = "Ao mesmo tempo que vai lentamente corroer o discernimento deles.",
  ui_story_10_8_1_4_dialog_content = "No geral, as cobaias que adquirem Fluxo Escuro têm mais facilidade pra revelar seus maiores desejos.",
  ui_story_10_8_1_5_dialog_content = "Nesse ponto, o que mais afeta seu livre arbítrio é o apego a certas coisas...",
  ui_story_10_8_1_6_dialog_content = "Calma! Aos poucos, mas certamente, suas habilidades psíquicas podem ser melhoradas com treino.",
  ui_story_10_8_1_7_dialog_content = "A Aviduz é especial por si só. Normalmente, demora mais pra aparecer um Navegador adequado.",
  ui_story_10_8_1_8_dialog_content = "Desde que você estude bastante e fique mais forte, então talvez um dia você...",
  ui_story_10_8_1_9_dialog_content = "Aviduz... Cadê você...",
  ui_story_10_8_1_10_dialog_content = "Colossus...",
  ui_story_10_8_1_11_dialog_content = "Colossus...",
  ui_story_10_8_1_12_dialog_content = "Uma Colossus normal...",
  ui_story_10_8_1_13_dialog_content = "Não, não é essa...",
  ui_story_10_8_1_14_dialog_content = "Essa também não...",
  ui_story_10_8_1_15_dialog_content = "O que devo fazer mesmo?",
  ui_story_10_8_1_16_dialog_content = "Destruir todos os núcleos de força, mas deixar um intacto.",
  ui_story_10_8_1_17_dialog_content = "Isso é uma ordem.",
  ui_story_10_8_1_18_dialog_content = "Destruir os núcleos de força...",
  ui_story_10_8_1_19_dialog_content = "Destruir os núcleos de força de todas as Colossi, menos da Aviduz...",
  ui_story_10_8_1_20_dialog_content = "Achei você...",
  ui_story_10_8_1_21_dialog_content = "Se eu destruir seu Modelo Eco, você vai me obedecer, né?",
  ui_story_10_8_1_22_dialog_content = "<color=#e8d9bb>Motor normal. Iniciando...</color>",
  ui_story_10_8_1_23_dialog_content = "Preto azeviche, poderoso, especial...",
  ui_story_10_8_1_24_dialog_content = "<color=#e8d9bb>16%... 33%...</color>",
  ui_story_10_8_1_25_dialog_content = "<color=#FFB400>Minha Aviduz.</color>",
  ui_story_10_8_1_26_dialog_content = "<color=#e8d9bb>100%. Inicialização bem-sucedida.</color>",
  ui_story_10_8_1_27_dialog_content = "Sabia que ia funcionar!",
  ui_story_10_8_1_28_dialog_content = "Enquanto eu tiver você, Aviduz...",
  ui_story_10_8_1_29_dialog_content = "SCHUMMER!",
  ui_story_10_8_1_30_dialog_content = "?!",
  ui_story_10_8_1_31_dialog_content = "Foi você que falou?!",
  ui_story_10_8_1_32_dialog_content = "Que modos são esses... de responder seus superiores?!",
  ui_story_10_8_1_33_dialog_content = "Você deveria dizer, \"Sim, Mestre Figerald! Eu humildemente espero suas ordens!\"",
  ui_story_10_8_1_34_dialog_content = "Sim... <color=#FFB400>m-mestre Figerald</color>...",
  ui_story_10_8_1_35_dialog_content = "Incapaz de sequer repetir minhas palavras, palerma.",
  ui_story_10_8_1_36_dialog_content = "Tsc, tsc, tsc, mas não posso te comparar aos outros, então tudo bem.",
  ui_story_10_8_1_37_dialog_content = "Você tem um valor especial pra nós agora.",
  ui_story_10_8_1_38_dialog_content = "Você acabou de virar um Eclipsita, ainda não entende o que tá acontecendo.",
  ui_story_10_8_1_39_dialog_content = "É assim que os Eclipsitas normalmente se comunicam, um poder concedido a nós pela Mãe.",
  ui_story_10_8_1_40_dialog_content = "Mesmo se estivermos em lugares completamente diferentes, ainda posso transmitir minha voz pra você...",
  ui_story_10_8_1_41_dialog_content = "Um poder da Mãe?",
  ui_story_10_8_1_42_dialog_content = "Nunca se esqueça, foi por vontade da Mãe que eu te escolhi e te concedi poder e uma nova oportunidade.",
  ui_story_10_8_1_43_dialog_content = "Você ser capaz de se adaptar à Semente tão rapidamente e ganhar tamanho poder é uma prova do discernimento impecável da Mãe.",
  ui_story_10_8_1_44_dialog_content = "No entanto, no seu estado atual, você não é capaz de saber nada além disso.",
  ui_story_10_8_1_45_dialog_content = "Somente se tornando mais forte e demonstrando sua devoção você ganhará o privilégio de ouvir os ensinamentos da Mãe.",
  ui_story_10_8_1_46_dialog_content = "Agora me diga, você terminou a tarefa que lhe dei?",
  ui_story_10_8_1_47_dialog_content = "Terminei.",
  ui_story_10_8_1_48_dialog_content = "Muito bem. Agora pilote sua Colossus pro meu lado.",
  ui_story_10_8_1_49_dialog_content = "O exército Eclipsita entrou em Eraveil, como programado. O juízo está próximo.",
  ui_story_10_8_1_50_dialog_content = "Mas você não tem muito tempo. Não esqueça de que você tem uma função como enviada.",
  ui_story_10_8_1_51_dialog_content = "Err... Enviada?",
  ui_story_10_8_1_S1_dialog_content = "Sim. Você deve me levar aos Celestitas que achar dignos do nosso poder.",
  ui_story_10_8_1_52_dialog_content = "Darei a eles uma chance de alcançar a <color=#FFB400>salvação</color>.",
  ui_story_10_8_1_S2_dialog_content = "Hmm...",
  ui_story_10_8_1_S3_dialog_content = "Schummer... Por que a hesitação?",
  ui_story_10_8_1_S4_dialog_content = "De repente... sinto... tanta coceira...",
  ui_story_10_8_1_S5_dialog_content = "Coceira?",
  ui_story_10_8_1_S6_dialog_content = "Tsc, tsc, tsc! Você tá começando a se sentir doente, né? Há outras anormalidades que eu deva saber?",
  ui_story_10_8_1_S7_dialog_content = "Outras anormalidades...",
  ui_story_10_8_1_S8_dialog_content = "Não consigo abrir os olhos. A luz lá fora é muito forte...",
  ui_story_10_8_1_S9_dialog_content = "De fato... Incrível você ter sido capaz de permitir que a Semente dentro de você se transformasse tão rápido!",
  ui_story_10_8_1_S10_dialog_content = "Sinto que o Fluxo Escuro dentro de você amadureceu.",
  ui_story_10_8_1_S11_dialog_content = "Você deve possuir uma perspectiva completamente nova agora. Venha conosco pra Eraveil.",
  ui_story_10_8_1_S12_dialog_content = "Uma perspectiva completamente nova...",
  ui_story_10_8_1_S13_dialog_content = "Sim. Você ultrapassou os Celestitas. Aquele sangue fraco não combinava com você, de qualquer forma.",
  ui_story_10_8_1_S14_dialog_content = "Mas... eu nasci assim...",
  ui_story_10_8_1_S15_dialog_content = "Mas você pode se livrar disso, assim como do seu destino de ser uma fraca Celestita pra sempre, condenada à destruição...",
  ui_story_10_8_1_S16_dialog_content = "Me livrar disso... O que devo fazer?",
  ui_story_10_8_1_S17_dialog_content = "O que você deve fazer? Tsc, tsc, tsc...",
  ui_story_10_8_1_S18_dialog_content = "Você deve desejar força! Só assim o poder oculto dentro de você dirá o que você deve fazer!",
  ui_story_10_8_1_S19_dialog_content = "...",
  ui_story_10_8_1_S20_dialog_content = "Desejar... poder...",
  ui_story_10_8_1_S21_dialog_content = "Desejar me livrar da fraqueza...",
  ui_story_10_8_1_S22_dialog_content = "Desejar transformação...",
  ui_story_10_8_1_S23_dialog_content = "Não... Não sou igual a eles.",
  ui_story_10_8_1_S24_dialog_content = "Tenho tudo agora!",
  ui_story_10_8_1_53_dialog_content = "Olha ali! Depressa!",
  ui_story_10_8_1_54_dialog_content = "Tragam armas! Tragam armas!!",
  ui_story_10_8_1_55_dialog_content = "O que é todo esse tumulto?",
  ui_story_10_8_1_56_dialog_content = "O que houve?",
  ui_story_10_8_1_57_dialog_content = "Então é aqui que você esteve se escondendo...",
  ui_story_10_8_1_58_dialog_content = "Q-Quem é você?!",
  ui_story_10_8_1_59_dialog_content = "Hah! Sou eu, Schummer! Não acredita no que vê?",
  ui_story_10_8_1_60_dialog_content = "Schummer? Não... Seus chifres, e seu cabelo... Você tá completamente diferente!",
  ui_story_10_8_1_61_dialog_content = "Não duvide de mim, e não tema. Tudo isso é prova de que sou a enviada escolhida.",
  ui_story_10_8_1_62_dialog_content = "Fui escolhida e recebi um poder muito além daquele dos Celestitas.",
  ui_story_10_8_1_63_dialog_content = "E-Enviada? Poder? Do que você tá falando?!",
  ui_story_10_8_1_64_dialog_content = "...",
  ui_story_10_8_1_65_dialog_content = "Sabia que você não entenderia! Só lembre disso: sou mais forte do que todos os Celestitas!",
  ui_story_10_8_1_66_dialog_content = "Agora me responda, por que você me ajudou? Por que colocou aquela chave no livro que você me deu?",
  ui_story_10_8_1_67_dialog_content = "D-Disseram que i-iriam te p-prender até que m-morresse...",
  ui_story_10_8_1_68_dialog_content = "Que se eu dissesse qualquer coisa pro professor, e-eu seria o próximo...",
  ui_story_10_8_1_69_dialog_content = "Mas somos parentes! E parentes não deveriam...",
  ui_story_10_8_1_70_dialog_content = "Ah, que chatice de empatia.",
  ui_story_10_8_1_71_dialog_content = "Pra simplificar, você estava comovido com a minha situação?",
  ui_story_10_8_1_72_dialog_content = "Quando aqueles caras me viram trancada, começaram a dizer todo tipo de mentiras, que piada.",
  ui_story_10_8_1_73_dialog_content = "Eu, eu não entendo. O que houve exatamente? Eles não estavam fazendo bullying com você?",
  ui_story_10_8_1_74_dialog_content = "Estudantes deixaram Eraveil sem permissão e foram mortos por Eclipsitas... Os anciãos não se atrevem a dizer nada.",
  ui_story_10_8_1_75_dialog_content = "Eles têm medo... Se todos souberem que o juízo está chegando, ninguém vai obedecer às regras estúpidas deles.",
  ui_story_10_8_1_76_dialog_content = "Presta atenção, pra não entender errado. Eu nunca quis aceitar aquele livro ou a chave dentro dele.",
  ui_story_10_8_1_77_dialog_content = "Mas não sou completamente sem coração. Como você tentou me ajudar no passado, estou disposta a te dar uma chance de sobreviver.",
  ui_story_10_8_1_78_dialog_content = "Assim como uma chance de ganhar um poder inacreditável. De agora em diante...",
  ui_story_10_8_1_79_dialog_content = "D-Do que você tá falando... Que tipo de chance?",
  ui_story_10_8_1_80_dialog_content = "Ainda não entendeu?",
  ui_story_10_8_1_81_dialog_content = "O fim de Eraveil chegou, e os Eclipsitas trouxeram o juízo do mundo com eles.",
  ui_story_10_8_1_82_dialog_content = "Todo mundo vai morrer...",
  ui_story_10_8_1_83_dialog_content = "Então torne-se um Eclipsita como eu!",
  ui_story_10_8_1_84_dialog_content = "Não, não... E-Eu...",
  ui_story_10_8_1_85_dialog_content = "É esse aqui?",
  ui_story_10_8_1_86_dialog_content = "Não tenho tempo, termine logo...",
  ui_story_10_8_1_87_dialog_content = "!!!",
  ui_story_10_8_1_88_dialog_content = "Se recusar, você vai morrer.",
  ui_story_10_8_1_89_dialog_content = "Diga em alto e bom som, você quer viver ou morrer?",
  ui_story_10_8_1_90_dialog_content = "Eu...",
  ui_story_10_8_1_91_dialog_content = "Hum...",
  ui_story_10_8_1_92_dialog_content = "Até um único Eclipsita é mais do que podemos lidar...",
  ui_story_10_8_1_93_dialog_content = "Handro! Foram encontrados Eclipsitas à leste também!",
  ui_story_10_8_1_94_dialog_content = "Todos vocês vão na frente! Estarei logo atrás!",
  ui_story_10_8_1_95_dialog_content = "Professor! Voltei!",
  ui_story_10_8_1_96_dialog_content = "Vem comigo!",
  ui_story_10_8_1_97_dialog_content = "Você?!",
  ui_story_10_8_1_98_dialog_content = "Schummer?!",
  ui_story_10_8_1_99_dialog_content = "Não tema, professor.",
  ui_story_10_8_1_100_dialog_content = "Os anciãos nunca contaram a todos que Eraveil está condenada a ser destruída pelos Eclipsitas. É por isso que todos estão em pânico.",
  ui_story_10_8_1_101_dialog_content = "O que você tá dizendo?",
  ui_story_10_8_1_102_dialog_content = "O juízo de Eraveil foi predeterminado há muito tempo.",
  ui_story_10_8_1_103_dialog_content = "O mundo fez uma escolha, e essa escolha é a evolução.",
  ui_story_10_8_1_104_dialog_content = "Os Eclipsitas não vão machucar quem não devem machucar. Então desde que você seja digno...",
  ui_story_10_8_1_105_dialog_content = "Você pode sobreviver ao juízo deles!",
  ui_story_10_8_1_106_dialog_content = "Eu me tornei uma enviada dos Eclipsitas. Posso te recomendar pra eles também!",
  ui_story_10_8_1_107_dialog_content = "Agarrem ela! Rápido, amarrem ela!",
  ui_story_10_8_1_108_dialog_content = "Rápido! Todo mundo junto!",
  ui_story_10_8_1_109_dialog_content = "...?",
  ui_story_10_8_1_110_dialog_content = "Abra a porta do quarto oculto! Rápido!",
  ui_story_10_8_1_111_dialog_content = "Tranquem ela. Peguem a Schummer e tranquem-na lá.",
  ui_story_10_8_1_112_dialog_content = "...",
  ui_story_10_8_1_113_dialog_content = "Então essa é a sua resposta?",
  ui_story_10_8_1_114_dialog_content = "Quanta covardia...",
  ui_story_10_8_1_115_dialog_content = "Mas não importa...",
  ui_story_10_8_1_116_dialog_content = "Logo você vai se arrepender.",
  ui_story_10_8_1_117_dialog_content = "Quando chegarem, todos vocês vão se arrepender! E depois virão me implorar...",
  ui_story_10_8_1_118_dialog_content = "Implorar por outra chance.",
  ui_story_10_8_1_119_dialog_content = "Ah!",
  ui_story_10_8_1_120_dialog_content = "Corre! Ali, rápido!",
  ui_story_10_8_1_121_dialog_content = "Restaram Colossi que ainda podem se mover?",
  ui_story_10_8_1_122_dialog_content = "Quem puder sentir o inimigo, encontrem um jeito de fugir! Levem as crianças com vocês!",
  ui_story_10_8_1_123_dialog_content = "Impossível, os Eclipsitas, são muitos deles...",
  ui_story_10_8_1_124_dialog_content = "Ahh... Que som maravilhoso.",
  ui_story_10_8_1_125_dialog_content = "Desde que erradicamos aqueles semi-humanos, que não eram melhores do que animais comuns...",
  ui_story_10_8_1_126_dialog_content = "Faz muito tempo desde que ouvi gritos de agonia assim, de partir o coração.",
  ui_story_10_8_1_127_dialog_content = "Esses Celestitas podem não ser tão barulhentos como os semi-humanos, mas seus gritos agudos são igualmente agradáveis.",
  ui_story_10_8_1_128_dialog_content = "Eu não esperaria menos de uma raça amante da música como eles. Tsc, tsc, tsc.",
  ui_story_10_8_1_129_dialog_content = "Grrr...",
  ui_story_10_8_1_130_dialog_content = "Vai! Faça-os gritar ainda mais, por mim! Mate todos eles!",
  ui_story_10_8_1_131_dialog_content = "Aaarrgh!",
  ui_story_10_8_1_132_dialog_content = "Tragam as Colossi que ainda podem se mover!",
  ui_story_10_8_1_133_dialog_content = "Rápido! Ajudem os sobreviventes!",
  ui_story_10_8_1_134_dialog_content = "*Tosse*",
  ui_story_10_8_1_135_dialog_content = "*Tosse*",
  ui_story_10_8_1_136_dialog_content = "Ainda há um sobrevivente. Que bom...",
  ui_story_10_8_1_137_dialog_content = "Professor! Professor!",
  ui_story_10_8_1_138_dialog_content = "Mendelson, você está vivo, venha, precisamos ir.",
  ui_story_10_8_1_139_dialog_content = "Professor, tá todo mundo morto...",
  ui_story_10_8_1_140_dialog_content = "Podemos continuar, professor? Podemos realmente escapar?",
  ui_story_10_8_1_141_dialog_content = "Claro que ainda podemos escapar. *Tosse* Venha comigo...",
  ui_story_10_8_1_142_dialog_content = "Por aqui, rápido... O <color=#FFB400>Mantiz</color> tá aqui por perto...",
  ui_story_10_8_1_143_dialog_content = "...",
  ui_story_10_8_1_144_dialog_content = "Professor?",
  ui_story_10_8_1_145_dialog_content = "Escuta, Mendelson. Posso sentir que todo mundo já foi eliminado...",
  ui_story_10_8_1_146_dialog_content = "Vou distrair os Eclipsitas a nossa volta e levá-los pra longe. Essa vai ser sua chance de entrar no Mantiz e ativá-lo.",
  ui_story_10_8_1_147_dialog_content = "Dentro do Mantiz tem um quarto especial. Quando escapar de Eraveil, você deve encontrar esse quarto especial.",
  ui_story_10_8_1_148_dialog_content = "Dentro dele, tem um <color=#FFB400>módulo especial</color>. Esse módulo...",
  ui_story_10_8_1_149_dialog_content = "Pode mudar completamente as funções cognitivas de uma Colossus.",
  ui_story_10_8_1_150_dialog_content = "Se ele cair nas mãos erradas, as consequências podem ser desastrosas.",
  ui_story_10_8_1_151_dialog_content = "A única pessoa capaz de pilotar o Mantiz já se foi. Só sobrou você.",
  ui_story_10_8_1_152_dialog_content = "M-Mas eu não consigo. Eu nunca consegui me conectar efetivamente a uma Colossus...",
  ui_story_10_8_1_153_dialog_content = "Eu acredito em você, Mendelson. Você tem muito potencial, só precisa de confiança.",
  ui_story_10_8_1_154_dialog_content = "No passado, percebemos que você é capaz de pilotar o Mantiz, e queríamos fazer de você o próximo Navegador.",
  ui_story_10_8_1_155_dialog_content = "Mas, professor, você consegue se conectar à Colossi. Não seria melhor se fôssemos juntos?",
  ui_story_10_8_1_156_dialog_content = "Não posso ir com você, Mendelson. <color=#FFB400>Liebowitz</color> ainda espera por mim.",
  ui_story_10_8_1_157_dialog_content = "Eu acredito em você. Sei que vai conseguir ativá-lo.",
  ui_story_10_8_1_158_dialog_content = "Há dois guardiões dentro do Mantiz, <color=#FFB400>Filex</color> e <color=#FFB400>Vani</color>. Eles vão te ajudar, e vão te fazer companhia...",
  ui_story_10_8_1_159_dialog_content = "Eu... Mas, professor... Não consigo isso sozinho! Nunca consegui me conectar...",
  ui_story_10_8_1_160_dialog_content = "Eu sei que você pode fazer isso, e muito bem. Não é hora de duvidar de si mesmo!",
  ui_story_10_8_1_161_dialog_content = "Mas aqueles Eclipsitas estão em todos os lugares! E também tem um lá fora que parece particularmente perigoso...",
  ui_story_10_8_1_162_dialog_content = "Mesmo se eu conseguir ativar a Colossus, não vou conseguir escapar...",
  ui_story_10_8_1_163_dialog_content = "Nesse ritmo, nós vamos morrer, todos nós vamos morrer.",
  ui_story_10_8_1_164_dialog_content = "Professor, a Schummer disse que ela tinha um jeito de sobrevivermos...",
  ui_story_10_8_1_165_dialog_content = "Você?! Ela falou com você também?!",
  ui_story_10_8_1_166_dialog_content = "Talvez haja uma outra maneira de sobrevivermos.",
  ui_story_10_8_1_167_dialog_content = "Uma maneira de sobrevivermos ao dia do nosso juízo.",
  ui_story_10_8_1_168_dialog_content = "Já se divertiu o bastante, Schummer?",
  ui_story_10_8_1_169_dialog_content = "Mestre Figerald, não há ninguém para eu escolher.",
  ui_story_10_8_1_170_dialog_content = "É uma pena, mas já esperei demais.",
  ui_story_10_8_1_171_dialog_content = "Eles não terão outra chance de sobreviver.",
  ui_story_10_8_1_172_dialog_content = "Tsc! Tsc! Tsc! Nesse caso, venha testemunhar a glória do dia do julgamento deles!",
  ui_story_10_8_1_173_dialog_content = "O Eclipse está aqui!",
  ui_story_10_9_1_1_dialog_content = "PlayerName?!",
  ui_story_10_9_1_2_dialog_content = "O dia do julgamento e o <color=#FFB400>Eclipse</color>...",
  ui_story_10_9_1_3_dialog_content = "Dia do julgamento? O que isso significa? Controle-se e conte o que viu.",
  ui_story_10_9_1_4_dialog_content = "Já vi isso antes, a destruição de Eraveil.",
  ui_story_10_9_1_5_dialog_content = "É tudo real.",
  ui_story_10_9_1_6_dialog_content = "Vi as memórias de Schummer agora mesmo, sobre o dia em que Eraveil foi atacada pelos Eclipsitas.",
  ui_story_10_9_1_7_dialog_content = "Schummer levou os Eclipsitas para Eraveil.",
  ui_story_10_9_1_8_dialog_content = "O céu ficou escuro, e houve o Eclipse...",
  ui_story_10_9_1_9_dialog_content = "Mas o mais importante, havia um Eclipsita de forma humanoide chamado <color=#FFB400>Figerald</color>.",
  ui_story_10_9_1_10_dialog_content = "Esse Eclipsita liderou o ataque que destruiu Eraveil inteira!",
  ui_story_10_9_1_11_dialog_content = "Você está bem?",
  ui_story_10_9_1_12_dialog_content = "Estou. Há uma multidão enorme de Eclipsitas se aproximando. Precisamos nos preparar pra batalha.",
  ui_story_10_9_1_13_dialog_content = "Consegue sentir um ataque Eclipsita em um lugar totalmente silencioso assim?",
  ui_story_10_9_1_14_dialog_content = "Consigo ouvir alguma coisa! Os Eclipsitas estão aqui!",
  ui_story_10_9_1_15_dialog_content = "Ha, e eu que achei que você estava perdendo a cabeça.",
  ui_story_10_9_1_16_dialog_content = "Achei que não estava em condições de avaliar o campo de batalha.",
  ui_story_10_9_1_17_dialog_content = "Mas deixe-me dizer uma coisa, focar em vingança não vai ser suficiente.",
  ui_story_10_9_1_18_dialog_content = "Não perca a cabeça quando vir a pessoa que está procurando. Mantenha a calma e lidere como sempre, e ficaremos bem.",
  ui_story_10_9_1_19_dialog_content = "Vou fazer isso. Eu agradeço, Sinsa.",
  ui_story_10_9_1_20_dialog_content = "Vou enfrentá-la com calma e racionalidade... e acabar com tudo.",
  ui_story_10_13_1_1_dialog_content = "Se tornar um Eclipsita não garante a habilidade de controlar o poder deles.",
  ui_story_10_13_1_2_dialog_content = "Sempre há a chance do Fluxo Escuro te consumir, e te fazer perder o controle...",
  ui_story_10_13_1_3_dialog_content = "Até mesmo alguém como Schummer, que tem sede de força mais do que tudo, tem um limite do poder que pode ganhar.",
  ui_story_10_13_1_4_dialog_content = "Se as coisas continuarem assim... não haverá necessidade de registrar nenhum dos resultados desse experimento.",
  ui_story_10_13_1_5_dialog_content = "(Falando em Eclipsiano) Minha senhora! O que devemos fazer agora?",
  ui_story_10_13_1_6_dialog_content = "(Falando em Eclipsiano) Os Aurorians nos alcançarão aqui muito em breve.",
  ui_story_10_13_1_7_dialog_content = "Parece que não posso mais depender de Schummer para progredir sozinha.",
  ui_story_10_13_1_8_dialog_content = "Terei que encorajá-la.",
  ui_story_10_13_1_9_dialog_content = "Continue observando os movimentos dos Aurorians.",
  ui_story_10_13_1_10_dialog_content = "(Eclipsiano) Entendido.",
  ui_story_10_13_1_11_dialog_content = "Schummer.",
  ui_story_10_13_1_12_dialog_content = "Silêncio...",
  ui_story_10_13_1_13_dialog_content = "Ainda está dormindo?",
  ui_story_10_13_1_14_dialog_content = "Hã?",
  ui_story_10_13_1_15_dialog_content = "Apague essa expressão idiota do rosto. Vim contar os resultados do experimento.",
  ui_story_10_13_1_16_dialog_content = "O quê?",
  ui_story_10_13_1_17_dialog_content = "A conclusão é que você é um <color=#FFB400>total e completo fracasso</color>.",
  ui_story_10_13_1_18_dialog_content = "For... sakin...",
  ui_story_10_13_1_19_dialog_content = "Não se ofenda, Schummer. Só estou dizendo a verdade objetiva da questão.",
  ui_story_10_13_1_20_dialog_content = "Você consumiu todo o poder de Aviduz, e uma pilha inteira de Eclipsitas, e ainda não completou sua transformação.",
  ui_story_10_13_1_21_dialog_content = "Consumi... Aviduz?",
  ui_story_10_13_1_22_dialog_content = "Isso mesmo. Vê esse casulo de cura? Está conectado à sua preciosa Aviduz.",
  ui_story_10_13_1_23_dialog_content = "Você o usou para sugar cada gota de poder dela. Aviduz não é nada mais que um pedaço de sucata agora.",
  ui_story_10_13_1_24_dialog_content = "Por que, por que não me disse...",
  ui_story_10_13_1_25_dialog_content = "Porque sei o quanto se importa com essa Colossus.",
  ui_story_10_13_1_26_dialog_content = "Como uma criança que finalmente tem o brinquedo que sempre quis, você não consegue abandoná-la nem por um segundo. O que é perfeitamente normal.",
  ui_story_10_13_1_27_dialog_content = "E perfeitamente óbvio também que, por dentro, você não passa de uma Celestita fraca.",
  ui_story_10_13_1_28_dialog_content = "É por isso que quando se encontrava com PlayerName, não queria matar nem se desfazer de seu compatriota.",
  ui_story_10_13_1_29_dialog_content = "Após todo esse tempo, você ainda está acorrentada ao passado. É uma pena.",
  ui_story_10_13_1_30_dialog_content = "Espero que não estivesse criando ilusões de ter controle sobre seu próprio destino, ou estava?",
  ui_story_10_13_1_31_dialog_content = "Os fracos não são dignos disso.",
  ui_story_10_13_1_32_dialog_content = "Maldição.",
  ui_story_10_13_1_33_dialog_content = "Você tem mesmo que estar com raiva.",
  ui_story_10_13_1_34_dialog_content = "Porque é culpada disso tudo.",
  ui_story_10_13_1_35_dialog_content = "Por ser tão fraca, imatura, medíocre e tola.",
  ui_story_10_13_1_36_dialog_content = "Te matar...",
  ui_story_10_13_1_37_dialog_content = "Errado. Não sou eu quem merece seu ódio.",
  ui_story_10_13_1_38_dialog_content = "Você esqueceu.",
  ui_story_10_13_1_39_dialog_content = "Quem foram aqueles que a fizeram chegar a esse ponto?",
  ui_story_10_13_1_40_dialog_content = "Lembra o que aquele Celestita disse?",
  ui_story_10_13_1_41_dialog_content = "Está sempre ajoelhada no chão, implorando por poder.",
  ui_story_10_13_1_42_dialog_content = "Seu compatriota te enxergou totalmente...",
  ui_story_10_13_1_43_dialog_content = "Mas estão aqui agora.",
  ui_story_10_13_1_44_dialog_content = "E quando a encontrarem, vão matar você.",
  ui_story_10_13_1_45_dialog_content = "Ou pode tentar implorar pelo perdão deles.",
  ui_story_10_13_1_46_dialog_content = "Impossível...",
  ui_story_10_13_1_47_dialog_content = "Pode implorar para que a deixem ir. Implore a PlayerName para não matar você.",
  ui_story_10_13_1_48_dialog_content = "Nem em um milhão de anos...",
  ui_story_10_13_1_49_dialog_content = "Então se não quer morrer...",
  ui_story_10_13_1_50_dialog_content = "Se quer sobreviver e matar aqueles tolos...",
  ui_story_10_13_1_51_dialog_content = "Resta apenas uma opção.",
  ui_story_10_13_1_52_dialog_content = "Precisa desejar ainda mais poder.",
  ui_story_10_13_1_53_dialog_content = "Poder...",
  ui_story_10_13_1_54_dialog_content = "...",
  ui_story_10_13_1_55_dialog_content = "Schummer?",
  ui_story_10_13_1_56_dialog_content = "<size=45>Me dê poder!</size>",
  ui_story_10_13_1_57_dialog_content = "...",
  ui_story_10_13_1_58_dialog_content = "Apesar de ter antecipado que você teria dificuldades em controlar suas emoções nesse momento,",
  ui_story_10_13_1_59_dialog_content = "não esperava que fosse perder totalmente o controle.",
  ui_story_10_13_1_60_dialog_content = "<size=45>Poder!!!</size>",
  ui_story_10_13_1_61_dialog_content = "Totalmente sem esperança.",
  ui_story_10_13_1_62_dialog_content = "<color=#e8d9bb>Ahhhhhh!</color>",
  ui_story_10_13_1_63_dialog_content = "O-O que foi isso?",
  ui_story_10_13_1_64_dialog_content = "Consegue sentir o que aconteceu, PlayerName?",
  ui_story_10_13_1_65_dialog_content = "Não tenho certeza. Mesmo usando toda a minha força, só consigo ter um pouco de acesso à mente de Schummer.",
  ui_story_10_13_1_66_dialog_content = "São pensamentos abstratos como \"força, poder, especial\" passando pela cabeça dela.",
  ui_story_10_13_1_67_dialog_content = "E mais uma coisa também. Um sentimento intenso...",
  ui_story_10_13_1_68_dialog_content = "<color=#FFB400>Ódio.</color>",
  ui_story_10_13_1_69_dialog_content = "Parece que ela ficou completamente louca!",
  ui_story_10_13_1_70_dialog_content = "Já tinha achado bem louca quando você me disse que ela estava comendo Eclipsitas.",
  ui_story_10_13_1_71_dialog_content = "Mas parece estranho.",
  ui_story_10_13_1_72_dialog_content = "Deve ter alguma coisa a ver com Forsakin.",
  ui_story_10_13_1_73_dialog_content = "Ela provavelmente contou a Schummer a notícia de que estamos aqui.",
  ui_story_10_13_1_74_dialog_content = "Parece que está planejando nos enfrentar, afinal.",
  ui_story_10_13_1_75_dialog_content = "Se ela colocou você como alvo, então provavelmente terá alguma forma de passar pelo resto de nós.",
  ui_story_10_13_1_76_dialog_content = "Considerando que Forsakin também está aqui... Talvez não possamos proteger você quando chegar a hora.",
  ui_story_10_13_1_77_dialog_content = "Vou verificar as coisas por enquanto. Mantenham PlayerName em segurança a todo custo.",
  ui_story_10_13_1_78_dialog_content = "Entendi.",
  ui_story_10_13_1_79_dialog_content = "Eclipsitas, logo em frente!",
  ui_story_10_13_1_80_dialog_content = "Acabem com eles, rápido!",
  ui_story_10_13_1_81_dialog_content = "Graagh!",
  ui_story_10_13_1_82_dialog_content = "O que está acontecendo? De repente esses Eclipsitas estão muito irritados!",
  ui_story_10_13_1_83_dialog_content = "Foi por causa desse terremoto ainda há pouco?",
  ui_story_10_13_1_84_dialog_content = "Estou com um mau pressentimento...",
  ui_story_10_13_1_85_dialog_content = "Até Pact consegue sentir.",
  ui_story_10_13_1_86_dialog_content = "Alguma coisa realmente perigosa deve ter aparecido.",
  ui_story_10_13_1_87_dialog_content = "As ordens de Lady Victoria...",
  ui_story_10_13_1_88_dialog_content = "Foram para evitar se envolver em disputas, por enquanto.",
  ui_story_10_13_1_89_dialog_content = "De acordo. Já que muitas Sementes foram obtidas, devemos deixar esse lugar também.",
  ui_story_10_13_1_90_dialog_content = "A verdadeira batalha já vai começar!",
  ui_story_10_13_2_1_dialog_content = "Aaargh!",
  ui_story_10_13_2_2_dialog_content = "...",
  ui_story_10_13_2_3_dialog_content = "Schummer?!",
  ui_story_10_13_2_4_dialog_content = "E-Ela pulou naquele Eclipsita?",
  ui_story_10_13_2_5_dialog_content = "E o comeu?",
  ui_story_10_13_2_6_dialog_content = "É realmente a Schummer? Ela parece bem diferente!",
  ui_story_10_13_2_7_dialog_content = "Schummer!",
  ui_story_10_13_2_8_dialog_content = "Eu já sei toda a verdade sobre os seus crimes!",
  ui_story_10_13_2_9_dialog_content = "Você não queria morrer, então se juntou aos Eclipsitas, não foi o suficiente?",
  ui_story_10_13_2_10_dialog_content = "Por que teve que levá-los a Eraveil?!",
  ui_story_10_13_2_11_dialog_content = "Por que teve que matar todo mundo?!",
  ui_story_10_13_2_12_dialog_content = "...",
  ui_story_10_13_2_13_dialog_content = "Sua traidora... Vai pagar por tudo isso!",
  ui_story_10_13_2_14_dialog_content = "Aaarrgh!",
  ui_story_10_13_2_15_dialog_content = "Cuidado, PlayerName!",
  ui_story_10_13_2_16_dialog_content = "Grrr!?",
  ui_story_10_13_2_17_dialog_content = "Ela está... atacando aqueles Eclipsitas ali?",
  ui_story_10_13_2_18_dialog_content = "...",
  ui_story_10_13_2_19_dialog_content = "Poder...",
  ui_story_10_13_2_20_dialog_content = "Mas o que está acontecendo aqui?",
  ui_story_10_13_2_21_dialog_content = "É quase como se... ela não pudesse ver a gente!",
  ui_story_10_13_2_22_dialog_content = "Droga, PlayerName! Isso foi muita irresponsabilidade sua!",
  ui_story_10_13_2_23_dialog_content = "Você é o comandante, idiota! Por que saiu na frente de seus guerreiros?!",
  ui_story_10_13_2_24_dialog_content = "Desculpe, me deixei levar, mas já me acalmei.",
  ui_story_10_13_2_25_dialog_content = "...",
  ui_story_10_13_2_26_dialog_content = "E agora, o que faremos?",
  ui_story_10_13_2_27_dialog_content = "Schummer, sinto dizer que ela usou todos os truques sujos que conhecia para obter poder, mas por fim, perdeu a cabeça...",
  ui_story_10_13_2_28_dialog_content = "Fiquem todos em alerta. Nossa maior chance é testar a força dela antes de tentar vencê-la.",
  ui_story_10_13_2_29_dialog_content = "Grrr...",
  ui_story_10_13_2_30_dialog_content = "Ela está olhando para cá! É porque acabou de comer aqueles Eclipsitas?!",
  ui_story_10_13_2_31_dialog_content = "...",
  ui_story_10_13_2_32_dialog_content = "PlayerName...",
  ui_story_10_13_2_33_dialog_content = "Ela está respondendo!",
  ui_story_10_13_2_34_dialog_content = "PlayerName... eu vou te matar!",
  ui_story_10_13_2_35_dialog_content = "Vai ter que passar por mim primeiro!",
  ui_story_10_13_2_36_dialog_content = "<anim type=Shake><size=50>PlayerName! Morra!! MORRAAA!!!</size></anim>",
  ui_story_10_14_2_1_dialog_content = "Nós vencemos?",
  ui_story_10_14_2_2_dialog_content = "Agora! Acabe com ela!",
  ui_story_10_14_2_3_dialog_content = "Schummer! Esse é o fim!",
  ui_story_10_14_2_4_dialog_content = "Aahhhhhh!",
  ui_story_10_14_2_5_dialog_content = "Agh, que sonho longo e nojento...",
  ui_story_10_14_2_6_dialog_content = "Ah, vai, é uma memória de 17 anos atrás.",
  ui_story_10_14_2_7_dialog_content = "Já chega...",
  ui_story_10_14_2_8_dialog_content = "Chega!",
  ui_story_10_14_2_9_dialog_content = "Cuidado, PlayerName!",
  ui_story_10_14_2_10_dialog_content = "Bum!",
  ui_story_10_14_2_11_dialog_content = "*Tosse*",
  ui_story_10_14_2_12_dialog_content = "Droga, ela ainda consegue lutar depois disso tudo?",
  ui_story_10_14_2_13_dialog_content = "Deve ser brincadeira. Ela é tão forte assim?!",
  ui_story_10_14_2_14_dialog_content = "...",
  ui_story_10_14_2_15_dialog_content = "Vice, PlayerName... vocês estão bem?",
  ui_story_10_14_2_16_dialog_content = "Já estive melhor, mas sim.",
  ui_story_10_14_2_17_dialog_content = "Estou bem... Agradeço por me proteger, Bopper.",
  ui_story_10_14_2_18_dialog_content = "Tudo bem, o que importa é a sua segurança...",
  ui_story_10_14_2_19_dialog_content = "...",
  ui_story_10_14_2_20_dialog_content = "Ela morreu?",
  ui_story_10_14_2_21_dialog_content = "Não. Tem alguma coisa errada...",
  ui_story_10_14_2_22_dialog_content = "Ha, haha... hahaha...",
  ui_story_10_14_2_23_dialog_content = "Schummer voltou a ter controle sobre si mesma! Todo mundo preparado para lutar novamente! Ela ainda tem bastante força!",
  ui_story_10_14_2_24_dialog_content = "Controle?",
  ui_story_10_14_2_25_dialog_content = "Isso mesmo, agora mesmo, eu estava tão furiosa...",
  ui_story_10_14_2_26_dialog_content = "Mas agora que lembrei que você está aqui, PlayerName... me sinto muito mais feliz!",
  ui_story_10_14_2_27_dialog_content = "!",
  ui_story_10_14_2_28_dialog_content = "Que esquisitice é essa?!",
  ui_story_10_14_2_29_dialog_content = "PlayerName, se afaste!",
  ui_story_10_14_2_30_dialog_content = "Bopper! Vou deixar PlayerName em seus cuidados! Mantenha nosso comandante em segurança!",
  ui_story_10_14_2_31_dialog_content = "Entendido!",
  ui_story_10_14_2_32_dialog_content = "Ei, aberração! Me diga onde está Forsakin!",
  ui_story_10_14_2_33_dialog_content = "Aberração? Está querendo me insultar?",
  ui_story_10_14_2_34_dialog_content = "Não importa, não consigo me irritar com você... não vale a pena.",
  ui_story_10_14_2_35_dialog_content = "E quanto a Forsakin, não precisa se preocupar.",
  ui_story_10_14_2_36_dialog_content = "Juro que vou encontrar aquela covarde e fazê-la pagar.",
  ui_story_10_14_2_37_dialog_content = "Mas antes disso, você e eu temos contas a acertar, PlayerName.",
  ui_story_10_14_2_38_dialog_content = "E desta vez, prometo usar todo o meu poder...",
  ui_story_10_14_2_39_dialog_content = "Para te dar a morte mais dolorosa possível!!!",
  ui_story_10_14_2_40_dialog_content = "!!!",
  ui_story_10_14_2_41_dialog_content = "Vai lutar com eles até a morte? Isso não vai dar certo...",
  ui_story_10_14_2_42_dialog_content = "Forsakin?!",
  ui_story_10_14_2_43_dialog_content = "Muito bem, Schummer. A Semente respondeu à sua vontade de lutar e finalmente amadureceu.",
  ui_story_10_14_2_44_dialog_content = "Infelizmente, você usou a maior parte do seu poder na última luta.",
  ui_story_10_14_2_45_dialog_content = "Se continuar com isso, todo o trabalho que eu tive com a sua Semente terá sido por nada.",
  ui_story_10_14_2_46_dialog_content = "Você?!",
  ui_story_10_14_2_47_dialog_content = "Comporte-se até que eu possa colher minha Semente.",
  ui_story_10_14_2_48_dialog_content = "Sinsa! O alvo de Forsakin é Schummer e não a gente! Ela está em busca da <color=#FFB400>Semente</color>!",
  ui_story_10_14_2_49_dialog_content = "Como se eu fosse deixar você levá-la embora!",
  ui_story_10_14_2_50_dialog_content = "Não se irrite tanto. Considerando meu objetivo, posso estar salvando todos vocês.",
  ui_story_10_14_2_51_dialog_content = "Podem fazer o que quiserem com Schummer, depois que eu pegar minha Semente, é claro.",
  ui_story_10_14_2_52_dialog_content = "Todo mundo consegue o que quer, e todos vamos embora felizes.",
  ui_story_10_14_2_53_dialog_content = "Além disso, não podem me impedir.",
  ui_story_10_14_2_54_dialog_content = "Cuidado, Sinsa!!!",
  ui_story_10_14_2_55_dialog_content = "Um ataque em área grande?!",
  ui_story_10_14_2_56_dialog_content = "Fiquem quietos, todos vocês.",
  ui_story_10_14_2_57_dialog_content = "Agora...",
  ui_story_10_14_2_58_dialog_content = "Algo a dizer antes de morrer, Schummer?",
  ui_story_10_14_2_59_dialog_content = "Me diga como é ter perdido seu poder. Ou melhor, como é ser Celestita novamente.",
  ui_story_10_14_2_60_dialog_content = "Se tiver algo importante a dizer, prometo escrever nas notas da minha pesquisa.",
  ui_story_10_14_2_61_dialog_content = "...",
  ui_story_10_14_2_62_dialog_content = "Tsc...",
  ui_story_10_14_2_63_dialog_content = "Muito bem.",
  ui_story_10_14_2_64_dialog_content = "Então como recompensa por sua ajuda para concluir meu experimento, deixo Schummer em suas mãos agora.",
  ui_story_10_14_2_65_dialog_content = "Adeus, Schummer.",
  ui_story_10_14_2_66_dialog_content = "*Tosse*",
  ui_story_10_14_2_67_dialog_content = "Sinsa, o que quer que faça... não vá atrás dela.",
  ui_story_10_14_2_68_dialog_content = "Eu sei.",
  ui_story_10_14_2_69_dialog_content = "O que vamos fazer com Schummer, PlayerName? A decisão é sua.",
  ui_story_10_14_2_70_dialog_content = "Ela não vai aguentar muito tempo com esses ferimentos, mal consegue se mover nessas condições.",
  ui_story_10_14_2_71_dialog_content = "Não pense no que acabou de acontecer. Faça o que o seu coração mandar.",
  ui_story_10_14_2_72_dialog_content = "Se quiser, posso fazer uma estaca de gelo pra você acertar as contas pessoalmente, PlayerName.",
  ui_story_10_14_2_73_dialog_content = "Antes disso, tenho perguntas que precisam de respostas.",
  ui_story_10_14_2_74_dialog_content = "Ha! Acertar as contas? Me questionar?",
  ui_story_10_14_2_75_dialog_content = "Por que você não... me pergunta agora? Vou responder...",
  ui_story_10_14_2_76_dialog_content = "Me diga, onde estão aqueles três módulos de Colossus?",
  ui_story_10_14_2_77_dialog_content = "Vá para o inferno!",
  ui_story_10_14_2_78_dialog_content = "Marginal Celestita imundo! Quer meus módulos?! Sem chance!",
  ui_story_10_14_2_79_dialog_content = "Não faz ideia do que eles valem. Essas peças pertencem a Aviduz, e a mais ninguém!",
  ui_story_10_14_2_80_option_content = "Tem razão, não faço, mas Aviduz é tão importante assim para você?",
  ui_story_10_14_2_81_dialog_content = "O motivo para trair os Celestitas foi para poder colocar as mãos em Aviduz?",
  ui_story_10_14_2_82_dialog_content = "Não culpo você por não querer morrer enfrentando um ataque Eclipsita.",
  ui_story_10_14_2_83_dialog_content = "Vá viver sua vida Eclipsita! Vá embora e não volte mais! Por que os levou a invadir Eraveil?!",
  ui_story_10_14_2_84_dialog_content = "Por quê?!",
  ui_story_10_14_2_85_dialog_content = "Hehe...",
  ui_story_10_14_2_86_dialog_content = "Você não entenderia.",
  ui_story_10_14_2_87_dialog_content = "Não viu o fim com seus próprios olhos. Não testemunhou o verdadeiro julgamento pessoalmente, você não entenderia...",
  ui_story_10_14_2_88_dialog_content = "Eraveil, eles atacaram Eraveil!",
  ui_story_10_14_2_89_dialog_content = "Sem escapatória! Não havia escapatória para ninguém!",
  ui_story_10_14_2_90_dialog_content = "E o mesmo vale para vocês... Todos vocês serão destruídos...",
  ui_story_10_14_2_91_dialog_content = "Bobagem! Você sofreu lavagem cerebral dos Eclipsitas para acreditar nisso!",
  ui_story_10_14_2_92_dialog_content = "Não deixe que as mentiras dela te enganem, PlayerName!",
  ui_story_10_14_2_93_option_content = "Não sei, nem quero saber. Entregue os módulos!",
  ui_story_10_14_2_94_dialog_content = "Eles nem são realmente seus!",
  ui_story_10_14_2_95_dialog_content = "Eles pertencem aos Celestitas!",
  ui_story_10_14_2_96_dialog_content = "Foram guardados pelos Celestitas, para eles!",
  ui_story_10_14_2_97_dialog_content = "Eles sempre pertenceram aos Celestitas!",
  ui_story_10_14_2_98_dialog_content = "Uma traidora como você não tem nenhum direito de pegá-los!!!",
  ui_story_10_14_2_99_dialog_content = "...",
  ui_story_10_14_2_100_dialog_content = "Você não sabe de nada!",
  ui_story_10_14_2_101_dialog_content = "E o que eram mesmo os Celestitas? Um bando de fracos que não sabiam o que era bom para eles!",
  ui_story_10_14_2_102_dialog_content = "Aqueles tolos não sabiam o verdadeiro valor das Colossi, o verdadeiro valor do poder!",
  ui_story_10_14_2_103_dialog_content = "Eram todos um bando de tolos incompetentes desmiolados, assim como você!",
  ui_story_10_14_2_104_dialog_content = "Cale a boca!",
  ui_story_10_14_2_105_dialog_content = "PlayerName, não perca a cabeça!",
  ui_story_10_14_2_106_dialog_content = "Eu sei.",
  ui_story_10_14_2_107_dialog_content = "Eu sei...",
  ui_story_10_14_2_108_dialog_content = "Percebi no caminho até aqui. Se o objetivo dos Eclipsitas era destruir Eraveil desde o começo...",
  ui_story_10_14_2_109_dialog_content = "De alguma forma, algum dia, eles iriam finalmente atacar.",
  ui_story_10_14_2_110_dialog_content = "Schummer, você não passou de um sacrifício lamentável nisso tudo.",
  ui_story_10_14_2_111_dialog_content = "Hã?",
  ui_story_10_14_2_112_dialog_content = "Do que está falando?",
  ui_story_10_14_2_113_dialog_content = "Eu fui eleita, eleita para viver porque eu mereci!",
  ui_story_10_14_2_114_dialog_content = "Como estão seus ferimentos, Vice?",
  ui_story_10_14_2_115_dialog_content = "H-Hã? Estão bem... eu estou bem.",
  ui_story_10_14_2_116_dialog_content = "Ei!",
  ui_story_10_14_2_117_dialog_content = "Não me ouviu?!",
  ui_story_10_14_2_118_dialog_content = "A maioria das Colossi têm uma estrutura similar. Acho que consigo encontrar os módulos, Vice.",
  ui_story_10_14_2_119_dialog_content = "Me dá uma mãozinha, vai?",
  ui_story_10_14_2_120_dialog_content = "Está bem.",
  ui_story_10_14_2_121_dialog_content = "...",
  ui_story_10_14_2_122_dialog_content = "...",
  ui_story_10_14_2_123_dialog_content = "E a sua vingança?",
  ui_story_10_14_2_124_dialog_content = "Pra onde foram todos os gritos e xingamentos? Não quer mais se vingar? Só porque vai enfrentar Eclipsitas?",
  ui_story_10_14_2_125_dialog_content = "Ah, agora acha que vai conseguir só pegar os módulos, me matar, ir para casa, e tomar chá com seus amigos queridos?",
  ui_story_10_14_2_126_dialog_content = "É só falar, PlayerName, e eu calo a boca dela rapidinho...",
  ui_story_10_14_2_127_dialog_content = "É só ignorar! Você também precisa cuidar de seus ferimentos, Sinsa.",
  ui_story_10_14_2_128_dialog_content = "Bopper, se importa em me ajudar a pegar os módulos?",
  ui_story_10_14_2_129_dialog_content = "Tá bom...",
  ui_story_10_14_2_130_dialog_content = "Ha! Hahaha...",
  ui_story_10_14_2_131_dialog_content = "Não esperava nada menos de uma raça gentil e pacífica.",
  ui_story_10_14_2_132_dialog_content = "Celestitas realmente são idiotas.",
  ui_story_10_14_2_133_dialog_content = "Carleen, me faça uma estaca de gelo, por favor.",
  ui_story_10_14_2_134_dialog_content = "Entendi.",
  ui_story_10_14_2_135_dialog_content = "...",
  ui_story_10_14_2_136_dialog_content = "Me diga, Schummer, quem é <color=#FFB400>Figerald</color>?",
  ui_story_10_14_2_137_dialog_content = "E o que é o <color=#FFB400>Eclipse</color>?",
  ui_story_10_14_2_138_dialog_content = "!",
  ui_story_10_14_2_139_dialog_content = "Você viu minhas memórias?!",
  ui_story_10_14_2_140_dialog_content = "Isso mesmo, mas infelizmente só consegui ver partes delas.",
  ui_story_10_14_2_141_dialog_content = "Por isso vou ouvir o resto da história direto da sua boca.",
  ui_story_10_14_2_142_dialog_content = "...",
  ui_story_10_14_2_143_dialog_content = "Hahaha...",
  ui_story_10_14_2_144_dialog_content = "Muito bem. Chegue mais perto, e eu conto...",
  ui_story_10_14_2_145_dialog_content = "Só um pouco mais perto.",
  ui_story_10_14_2_146_dialog_content = "Não vai acabar com meu sofrimento com essa estaca de gelo, de todo jeito?",
  ui_story_10_14_2_147_dialog_content = "Tem algo errado, PlayerName! Não caia nos truques dela!",
  ui_story_10_14_2_148_dialog_content = "Não se preocupe, não estava planejando chegar perto dela.",
  ui_story_10_14_2_149_dialog_content = "Já é tarde demais...",
  ui_story_10_14_2_150_dialog_content = "Grrr...",
  ui_story_10_14_2_151_dialog_content = "Grrr...",
  ui_story_10_14_2_152_dialog_content = "Atrás de você!",
  ui_story_10_14_2_153_dialog_content = "Graagh!",
  ui_story_10_14_2_154_dialog_content = "Hahaha... haha...",
  ui_story_10_14_2_155_dialog_content = "Eu disse que fui eleita! Sou a enviada do Eclipse!",
  ui_story_10_14_2_156_dialog_content = "Venham, venham cercá-los...",
  ui_story_10_14_2_157_dialog_content = "Grrr...",
  ui_story_10_14_2_158_dialog_content = "Grrr...",
  ui_story_10_14_2_159_dialog_content = "No fim, eu venço.",
  ui_story_10_14_2_160_dialog_content = "PlayerName.",
  ui_story_10_14_2_161_dialog_content = "Competição, evolução, a única forma de realizá-las é pisar nas cabeças de outras pessoas!",
  ui_story_10_14_2_162_dialog_content = "Você e Eraveil são os verdadeiros sacrifícios aqui!",
  ui_story_10_14_2_163_dialog_content = "Eu ultrapassei todos vocês, ultrapassei esses desafios, e agora me tornei invencível!",
  ui_story_10_14_2_164_dialog_content = "...",
  ui_story_10_14_2_165_dialog_content = "Todos preparem-se para recuar...",
  ui_story_10_14_2_166_dialog_content = "O quê?! Não vamos ter outra chance como essa! Vamos enfrentá-los!",
  ui_story_10_14_2_167_dialog_content = "É óbvio que nenhum de nós está em condições de lutar contra tantos Eclipsitas agora, não com nossos ferimentos.",
  ui_story_10_14_2_168_dialog_content = "Vocês devem saber mais do que eu.",
  ui_story_10_14_2_169_dialog_content = "Quero minha vingança, mas não vou sacrificar nenhum de vocês por isso.",
  ui_story_10_14_2_170_dialog_content = "Recuar? Fiquem à vontade. Adoraria ver isso...",
  ui_story_10_14_2_171_dialog_content = "Quem é mais rápido, meus Eclipsitas ou vocês, tolos machucados!",
  ui_story_10_14_2_172_dialog_content = "Rasguem eles em pedaços!",
  ui_story_10_14_2_173_dialog_content = "Grrr...",
  ui_story_10_14_2_174_dialog_content = "O que estão esperando?! Ataquem!",
  ui_story_10_14_2_175_dialog_content = "Graagh!",
  ui_story_10_14_2_176_dialog_content = "O quê?!",
  ui_story_10_14_2_177_dialog_content = "Argh! Me soltem!",
  ui_story_10_14_2_178_dialog_content = "Eu não! Não!",
  ui_story_10_14_2_179_dialog_content = "Nãooo!!!",
  ui_story_10_14_2_180_dialog_content = "Graagh!",
  ui_story_10_14_2_181_dialog_content = "...",
  ui_story_10_14_2_182_dialog_content = "Não há tempo a perder... Devemos fugir enquanto podemos!",
  ui_story_10_14_2_183_dialog_content = "Senão, somos o próximo prato!",
  ui_story_10_14_2_184_dialog_content = "PlayerName!",
  ui_story_10_14_2_185_dialog_content = "Tirem PlayerName daqui! Rápido!",
  ui_story_10_14_2_186_dialog_content = "Vai!",
  ui_story_10_14_2_187_dialog_content = "Esse final...",
  ui_story_10_14_2_188_dialog_content = "(Eu não aceito!)",
  ui_story_10_14_2_189_dialog_content = "(Lutei tanto pra sobreviver, para merecer tudo isso...)",
  ui_story_10_14_2_190_dialog_content = "(São todos mentirosos!)",
  ui_story_10_14_2_191_dialog_content = "(É tudo falso!)",
  ui_story_10_14_2_192_dialog_content = "(Poder falso! Julgamento falso!)",
  ui_story_10_14_2_193_dialog_content = "(Forsakin, Figerald, o Eclipse...)",
  ui_story_10_14_2_194_dialog_content = "(Desde o começo, eles nunca planejavam me libertar...)",
  ui_story_10_14_2_195_dialog_content = "(Amaldiçoo todos vocês...)",
  ui_story_10_14_2_196_dialog_content = "(Uma raça fraca, destinada a ser destruída...)",
  ui_story_10_14_2_197_dialog_content = "(Celestitas foram amaldiçoados, desde o dia em que nasceram...)",
  ui_story_10_14_2_198_dialog_content = "(E você não é diferente, terá uma morte horrível e trágica, assim como eu...)",
  ui_story_10_14_2_199_dialog_content = "(Amaldiçoado seja...)",
  ui_story_10_14_2_200_dialog_content = "(PlayerName...)",
  ui_story_10_14_2_201_dialog_content = "(Aceite o terror da sua destruição predestinada...)",
  ui_story_10_14_2_202_dialog_content = "(<color=#FFB400>O Eclipse já chegou!</color>)",
  ui_story_10_15_1_1_dialog_content = "(O que mais posso fazer?)",
  ui_story_10_15_1_2_dialog_content = "(Ela já está morta.)",
  ui_story_10_15_1_3_dialog_content = "(Comida por Eclipsitas... Que forma horrível de morrer...)",
  ui_story_10_15_1_4_dialog_content = "(O que devemos fazer agora? O que devo fazer...)",
  ui_story_10_15_1_5_dialog_content = "Grrr...",
  ui_story_10_15_1_6_dialog_content = "(Todos estão feridos, e esses Eclipsitas... não vão nos deixar ir tão facilmente...)",
  ui_story_10_15_1_7_dialog_content = "(Da mesma forma que o Eclipse...)",
  ui_story_10_15_1_8_dialog_content = "(Todos foram mortos naquele dia...)",
  ui_story_10_15_1_9_dialog_content = "O que faremos?",
  ui_story_10_15_1_10_dialog_content = "Corram!",
  ui_story_10_15_1_11_dialog_content = "Ajudem o PlayerName!",
  ui_story_10_15_1_12_dialog_content = "Anda! Vamos sair daqui!",
  ui_story_10_15_1_13_dialog_content = "Corram! Voltem por onde viemos!",
  ui_story_10_15_1_14_dialog_content = "O-Os Eclipsitas estão nos alcançando...",
  ui_story_10_15_1_15_dialog_content = "Vou cuidar da retaguarda!",
  ui_story_10_15_1_16_dialog_content = "Graagh!",
  ui_story_10_15_1_17_dialog_content = "Carleen?!",
  ui_story_10_15_1_18_dialog_content = "*Tosse* Estou bem, corra!",
  ui_story_10_15_1_19_dialog_content = "Quando está tudo prestes a terminar, arrumamos mais problemas...",
  ui_story_10_15_1_20_dialog_content = "...",
  ui_story_10_15_1_21_dialog_content = "Estão nos perseguindo até aqui? Que persistentes!",
  ui_story_10_15_1_22_dialog_content = "Graagh!",
  ui_story_10_15_1_23_dialog_content = "!",
  ui_story_10_15_1_24_dialog_content = "PlayerName! Se recomponha!",
  ui_story_10_15_1_25_dialog_content = "Precisamos da sua ajuda!",
  ui_story_10_15_1_26_dialog_content = "...",
  ui_story_10_15_1_27_dialog_content = "...",
  ui_story_10_15_1_28_dialog_content = "Vice, Eclipsitas estão bloqueando o caminho à frente! Atire neles!",
  ui_story_10_15_1_29_dialog_content = "Carleen, tome um pouco de distância primeiro, flanqueie do lado direito, e ataque!",
  ui_story_10_15_1_30_dialog_content = "Torrente Rápida!",
  ui_story_10_15_1_31_dialog_content = "Entendido!",
  ui_story_10_15_1_32_dialog_content = "Graagh!",
  ui_story_10_15_1_33_dialog_content = "Já era hora de você recobrar o juízo!",
  ui_story_10_15_1_34_dialog_content = "Desculpe, Schummer me afetou um pouco antes de morrer. Me deixou tonto.",
  ui_story_10_15_1_35_dialog_content = "Não precisa se desculpar, mas tente se recompor assim que possível.",
  ui_story_10_15_1_36_dialog_content = "Ainda não acabamos com isso.",
  ui_story_10_15_1_37_dialog_content = "Ainda preciso me reportar a Lumópolis, e você precisa consertar seu Soroz.",
  ui_story_10_15_1_38_dialog_content = "Então vamos eliminar esses Eclipsitas, e sair daqui vivos!",
  ui_story_10_15_1_39_dialog_content = "Você tem toda a razão.",
  ui_story_10_15_1_40_dialog_content = "Estou me sentindo bem novamente... Posso ajudar todo mundo a lutar agora!",
  ui_story_10_15_1_41_dialog_content = "Fico feliz que esteja melhor, PlayerName.",
  ui_story_10_15_1_42_dialog_content = "Mas esse Eclipsita!",
  ui_story_10_15_1_43_dialog_content = "Aahhhhhh!",
  ui_story_10_15_1_44_dialog_content = "Quero dizer que a morte não é tão assustadora...",
  ui_story_10_15_1_45_dialog_content = "Mas tenho uma irmãzinha me esperando em casa!",
  ui_story_10_15_1_46_dialog_content = "<size=45>Vamos lutar até a morte agora, pessoal! Mas não se atrevam a morrer!</size>",
  ui_story_10_15_1_47_dialog_content = "Fala baixo, Sinsa! Não é você quem dá as ordens aqui!",
  ui_story_10_15_1_48_dialog_content = "Grrr...",
  ui_story_10_15_1_49_dialog_content = "Graagh!",
  ui_story_10_15_1_50_dialog_content = "Venha aqui!",
  ui_story_10_15_1_51_dialog_content = "Os Eclipsitas estão sendo sugados?",
  ui_story_10_15_1_52_dialog_content = "E se abaixe!",
  ui_story_10_15_1_53_dialog_content = "Graagh!",
  ui_story_10_15_1_54_dialog_content = "Ei, Sinsa! Seu herói Brock está aqui pra te salvar!",
  ui_story_10_15_1_55_dialog_content = "Hahaha! Nunca pensou que esse dia chegaria, hein? Hahahaha!",
  ui_story_10_15_1_56_dialog_content = "Cuidado com a explosão!",
  ui_story_10_15_1_57_dialog_content = "Aaaaaah!",
  ui_story_10_15_1_58_dialog_content = "Ei, olha onde atira essa coisa! Você quase me explodiu!",
  ui_story_10_15_1_59_dialog_content = "Foi você quem trouxe todos os Eclipsitas pra cá sem acabar com eles!",
  ui_story_10_15_1_60_dialog_content = "O que é isso?!",
  ui_story_10_15_1_61_dialog_content = "Haha...",
  ui_story_10_15_1_62_dialog_content = "Desculpe, mas parece que meus amigos da Rediesel Wrench estão aqui pra ajudar.",
  ui_story_10_15_1_63_dialog_content = "Eles são fortes, não me entenda mal, mas um pouco barulhentos, só isso.",
  ui_story_10_15_1_64_dialog_content = "Ufa, estamos salvos! Vocês são incríveis!",
  ui_story_10_15_1_65_dialog_content = "É... estamos salvos...",
  ui_story_10_15_1_66_dialog_content = "Uau, que luta cansativa! Tem Eclipsitas demais.",
  ui_story_10_15_1_67_dialog_content = "Ei, Sinsa! Quer saber como chegamos aqui? Vou contar, tudo começou quando aquela montanha tremeu...",
  ui_story_10_15_1_68_dialog_content = "Chefe! Está tudo bem?!",
  ui_story_10_15_1_69_dialog_content = "Estou bem, são só arranhões...",
  ui_story_10_15_1_70_dialog_content = "Uau, que bela Colossus!",
  ui_story_10_15_1_71_dialog_content = "Tudo vai valer a pena se conseguirmos levar essa coisa com a gente!",
  ui_story_10_15_1_72_dialog_content = "Todos vocês, venham aqui me ajudar a desmontá-la para podermos movê-la!",
  ui_story_10_15_1_73_dialog_content = "Espera aí!",
  ui_story_10_15_1_74_dialog_content = "Vocês são de Lumópolis?",
  ui_story_10_15_1_75_dialog_content = "Desculpe, Odi, não tive a chance de lhe apresentar antes.",
  ui_story_10_15_1_76_dialog_content = "Essa é Carleen, de Lumópolis. Esses dois são Vice e PlayerName.",
  ui_story_10_15_1_77_dialog_content = "Espera, espera, espera... Chefe, não é a Carleen, de Lumópolis, Capitã dos Guardiões?",
  ui_story_10_15_1_78_dialog_content = "Cala a boca, Brock!",
  ui_story_10_15_1_79_dialog_content = "Somos todos companheiros de luta hoje.",
  ui_story_10_15_1_80_dialog_content = "Não é mesmo, Carleen?",
  ui_story_10_15_1_81_dialog_content = "...",
  ui_story_10_15_1_82_dialog_content = "Bom, então, eles estão atrás dessa Colossus?",
  ui_story_10_15_1_83_dialog_content = "Então sugiro que nos separemos de acordo com quem trabalhou mais. O que acham?",
  ui_story_10_15_1_84_dialog_content = "Eu tomo a decisão, só calem a boca e escutem, todos vocês.",
  ui_story_10_15_1_85_dialog_content = "Se ainda têm alguma dúvida, lidamos com isso quando voltarmos pra base.",
  ui_story_10_15_1_86_dialog_content = "PlayerName!",
  ui_story_10_15_1_87_dialog_content = "Quer essa Colossus preta? Vamos ajudar a levá-la de volta se quiser!",
  ui_story_10_15_1_88_dialog_content = "Hã?",
  ui_story_10_15_1_89_dialog_content = "Como assim, ainda atordoado? Acorda, garoto!",
  ui_story_10_15_1_90_dialog_content = "Estou bem. Já melhorei há um tempo.",
  ui_story_10_15_1_91_dialog_content = "Que bom, então.",
  ui_story_10_15_1_92_dialog_content = "O que estou tentando dizer é que essa coisa deveria ser sua. Afinal, é uma Colossus dos Celestitas.",
  ui_story_10_15_1_93_dialog_content = "No entanto, se eu puder dar uma sugestão...",
  ui_story_10_15_1_94_dialog_content = "O que foi?",
  ui_story_10_15_1_95_dialog_content = "Por que não se junta à Rediesel Wrench? Seria muito mais justificável levar essa coisa pra nossa base!",
  ui_story_10_15_1_96_dialog_content = "Eu...",
  ui_story_10_15_1_97_dialog_content = "Não precisa me responder agora! Só estava dando essa opção.",
  ui_story_10_15_1_98_dialog_content = "Se quiser se juntar a nós na Rediesel Wrench, a porta está sempre aberta.",
  ui_story_10_15_1_99_dialog_content = "Obrigado.",
  ui_story_10_15_1_100_dialog_content = "Mas só preciso de três módulos da Colossus.",
  ui_story_10_15_1_101_dialog_content = "Vocês podem fazer o que quiserem com o resto da Aviduz.",
  ui_story_10_15_1_102_dialog_content = "Tudo bem, e vocês? Alguma ideia que querem compartilhar?",
  ui_story_10_15_1_103_dialog_content = "Se Lumópolis ou Illumina tiverem interesse nela, acho que vocês não vão nos deixar levá-la assim.",
  ui_story_10_15_1_104_dialog_content = "Se PlayerName diz que vocês podem levá-la, não tenho a mínima intenção de impedir.",
  ui_story_10_15_1_105_dialog_content = "Não precisamos dela.",
  ui_story_10_15_1_106_dialog_content = "Pra falar a verdade, sabia que vocês estavam aqui pela Colossus assim que nos encontramos.",
  ui_story_10_15_1_107_dialog_content = "Naquele momento, eu já havia decidido que não tentaria tirar a Aviduz de vocês.",
  ui_story_10_15_1_108_dialog_content = "Que bom! Que lealdade sua!",
  ui_story_10_15_1_109_dialog_content = "Isso não é lealdade, eu só não tenho interesse nela.",
  ui_story_10_15_1_110_dialog_content = "PlayerName.",
  ui_story_10_15_1_111_dialog_content = "Sei que provavelmente está sentindo várias coisas depois do que acabamos de passar.",
  ui_story_10_15_1_112_dialog_content = "Mas tente não pensar demais nisso. Você já fez mais do que o suficiente!",
  ui_story_10_15_1_113_dialog_content = "Se quiser voltar e ter uma vida pacífica, ninguém o culparia por isso!",
  ui_story_10_15_1_114_dialog_content = "Sinsa...",
  ui_story_10_15_1_115_dialog_content = "Obrigado.",
  ui_story_10_15_1_116_dialog_content = "Uau, o que é isso que estou ouvindo entre vocês?",
  ui_story_10_15_1_117_dialog_content = "Só estava elogiando o garoto, só isso! Não faça essa cara!",
  ui_story_10_15_1_118_dialog_content = "Tudo bem, terminamos por aqui! Voltem ao trabalho!",
  ui_story_10_15_1_119_dialog_content = "Uh, descanse se precisar. Os demais venham trabalhar!",
  ui_story_10_15_1_120_dialog_content = "Andando.",
  ui_story_10_15_1_121_dialog_content = "Vou contar até três e puxamos! Entenderam?",
  ui_story_10_15_1_122_dialog_content = "Sim!",
  ui_story_10_15_1_123_dialog_content = "Brock! Que droga você está fazendo aí sozinho?!",
  ui_story_10_15_1_124_dialog_content = "Me aquecendo, obviamente!",
  ui_story_10_15_1_125_dialog_content = "Realmente acha que eu ia esperar você me dizer quando começar?",
  ui_story_10_15_1_126_dialog_content = "Não tem jeito de levar isso de volta! Minha nossa, é uma Colossus!",
  ui_story_10_15_1_127_dialog_content = "Ou devemos desmontá-la e levar de volta o que for útil?",
  ui_story_10_15_1_128_dialog_content = "Concordo.",
  ui_story_10_15_1_129_dialog_content = "Ei, Bopper, vocês ainda precisam de ajuda? Eu realmente gostaria de voltar pra Soroz primeiro.",
  ui_story_10_15_1_130_dialog_content = "Não, acho que conseguimos.",
  ui_story_10_15_1_131_dialog_content = "Vamos pensar em alguma coisa, não se preocupe.",
  ui_story_10_15_1_132_dialog_content = "Voltem para a Colossus e descansem. Cuidar dos ferimentos vem em primeiro lugar!",
  ui_story_10_15_1_133_dialog_content = "Não se preocupe, não vamos esquecer. Ainda estão doendo.",
  ui_story_10_15_1_134_dialog_content = "Mas queremos nos despedir de Sinsa. Onde ele está?",
  ui_story_10_15_1_135_dialog_content = "É, então, ele disse que não tem necessidade de despedidas sentimentais, então não se preocupe com isso.",
  ui_story_10_15_1_136_dialog_content = "Tá bom...",
  ui_story_10_15_1_137_dialog_content = "Acho que vamos embora agora. Tchau...",
  ui_story_10_15_1_138_dialog_content = "É, tchau...",
  ui_story_10_15_1_139_dialog_content = "Se cuidem, certo? Nos vemos de novo algum dia!",
  ui_story_10_15_1_140_dialog_content = "É! Até a próxima...",
  ui_story_10_15_1_141_dialog_content = "Como eu cheguei aqui?",
  ui_story_10_15_1_142_dialog_content = "No começo acho que foi... aquele sonho.",
  ui_story_10_15_1_143_dialog_content = "\"Viver...\"",
  ui_story_10_15_1_144_dialog_content = "Você <color=#FFB400>sonhou aquilo</color> novamente?",
  ui_story_10_15_1_145_dialog_content = "Sim.",
  ui_story_10_15_1_146_dialog_content = "Sonhos são a visualização da mente de esperanças e desejos pelo desconhecido. São ilusões.",
  ui_story_10_15_1_147_dialog_content = "E então... Mendelson morreu.",
  ui_story_10_15_1_148_dialog_content = "Naquele dia, 17 anos atrás, eu aceitei o <color=#FFB400>Poder dos Eclipsitas</color> para conseguir sobreviver.",
  ui_story_10_15_1_149_dialog_content = "Gostaria de poder ver o céu, mesmo que fosse a última vez...",
  ui_story_10_15_1_150_dialog_content = "E não muito tempo depois, vi Schummer morrer diante dos meus olhos...",
  ui_story_10_15_1_151_dialog_content = "(Amaldiçoado seja...)",
  ui_story_10_15_1_152_dialog_content = "(PlayerName...)",
  ui_story_10_15_1_153_dialog_content = "Na verdade, não eram sonhos, era tudo real...",
  ui_story_10_15_1_154_dialog_content = "Soroz...",
  ui_story_10_15_1_155_dialog_content = "Peguei o Módulo de Tanque Pensante, mas não sei... se você tem um sistema pra conectar esse componente...",
  ui_story_10_15_1_156_dialog_content = "Afinal, você é uma Colossus nível 6, e isso é só o que os outros me disseram...",
  ui_story_10_15_1_E1_dialog_content = "...",
  ui_story_10_15_1_E2_dialog_content = "É melhor guardar minhas reclamações para quando você voltar.",
  ui_story_10_15_1_157_dialog_content = "As três entradas do Módulo de Tanque Pensante...",
  ui_story_10_15_1_158_dialog_content = "Parecem todas iguais.",
  ui_story_10_15_1_159_dialog_content = "...",
  ui_story_10_15_1_160_dialog_content = "<color=#e8d9bb>Controle Primário normal.</color>",
  ui_story_10_15_1_161_dialog_content = "<color=#e8d9bb>Módulos biológicos em hibernação.</color>",
  ui_story_10_15_1_162_dialog_content = "<color=#e8d9bb>\"Suporte de vida... operacional. Capacidade atual: 1 pessoa.\"</color>",
  ui_story_10_15_1_163_dialog_content = "<color=#e8d9bb>Motor normal.</color>",
  ui_story_10_15_1_164_dialog_content = "<color=#e8d9bb>Módulo de Tanque Pensante detectado. Conectando...</color>",
  ui_story_10_15_1_165_dialog_content = "<color=#e8d9bb>1%... 3%... 8%...</color>",
  ui_story_10_15_1_166_dialog_content = "Então...",
  ui_story_10_15_1_167_dialog_content = "Foi assim que terminou, né?",
  ui_story_10_15_1_168_dialog_content = "Não sobrou quase nada do corpo de Schummer...",
  ui_story_10_15_1_169_dialog_content = "É... PlayerName nem quis verificar.",
  ui_story_10_15_1_170_dialog_content = "Acho que PlayerName já sentiu a morte de Schummer com as habilidades psíquicas.",
  ui_story_10_15_1_171_dialog_content = "Bom, agora que ela morreu, podemos esquecê-la.",
  ui_story_10_15_1_172_dialog_content = "Mas... podemos mesmo fazer isso?",
  ui_story_10_15_1_173_dialog_content = "Schummer pode ter morrido, mas os Eclipsitas que destruíram Eraveil...",
  ui_story_10_15_1_174_dialog_content = "Ainda estão por todo o mundo.",
  ui_story_10_15_1_175_dialog_content = "Sem contar que ainda há um Eclipsita que PlayerName mencionou antes, <color=#FFB400>Figerald</color>.",
  ui_story_10_15_1_176_dialog_content = "Mas PlayerName não perguntou quem era Figerald até o último momento.",
  ui_story_10_15_1_177_dialog_content = "Aconteceu tanta coisa em tão pouco tempo...",
  ui_story_10_15_1_178_dialog_content = "Talvez PlayerName não tenha conseguido perguntar a tempo.",
  ui_story_10_15_1_179_dialog_content = "Depois de ver Schummer morrer, PlayerName pareceu atordoado.",
  ui_story_10_15_1_180_dialog_content = "PlayerName melhorou pouco tempo depois, mas de alguma forma parece que algo não está certo.",
  ui_story_10_15_1_181_dialog_content = "Talvez PlayerName não quisesse nos preocupar e então voltou ao normal.",
  ui_story_10_15_1_182_dialog_content = "Ou talvez, PlayerName esteja se concentrando em algo mais importante agora...",
  ui_story_10_15_1_183_dialog_content = "De qualquer forma, tenho certeza de que PlayerName não vai hesitar em pedir ajuda se for necessário.",
  ui_story_10_15_1_184_dialog_content = "Hum... Você tem razão.",
  ui_story_10_15_1_185_dialog_content = "A propósito, PlayerName entrou em Soroz já faz um tempo e ainda não saiu...",
  ui_story_10_15_1_186_dialog_content = "Me preocupo um pouco...",
  ui_story_10_15_1_187_dialog_content = "PlayerName queria levar os componentes para dentro sozinho, com certeza com bons motivos.",
  ui_story_10_15_1_188_dialog_content = "Vamos esperar um pouquinho mais.",
  ui_story_10_15_1_189_dialog_content = "Tá bom...",
  ui_story_10_15_1_190_dialog_content = "<color=#e8d9bb>10%... 23%...</color>",
  ui_story_10_15_1_191_dialog_content = "<color=#e8d9bb>33%... 35%...</color>",
  ui_story_10_15_1_192_dialog_content = "<color=#e8d9bb>Conexão falhou. Contagem de falhas: 1</color>",
  ui_story_10_15_1_193_dialog_content = "Tudo bem, apenas tente de novo.",
  ui_story_10_15_1_194_dialog_content = "Conecte o Módulo de Tanque Pensante...",
  ui_story_10_15_1_195_dialog_content = "<color=#e8d9bb>Módulo de Tanque Pensante detectado. Conectando...</color>",
  ui_story_10_15_1_196_dialog_content = "<color=#e8d9bb>1%... 3%... 8%...</color>",
  ui_story_10_15_1_197_dialog_content = "<color=#e8d9bb>61%... 67%...</color>",
  ui_story_10_15_1_198_dialog_content = "<color=#e8d9bb>76%... 85%...</color>",
  ui_story_10_15_1_199_dialog_content = "<color=#e8d9bb>Conexão falhou. Contagem de falhas: 2</color>",
  ui_story_10_15_1_200_dialog_content = "São apenas duas tentativas sem sucesso. Lembra quantas vezes tentamos ativar seus motores?",
  ui_story_10_15_1_201_dialog_content = "Levamos quase três mil tentativas.",
  ui_story_10_15_1_202_dialog_content = "Tudo bem.",
  ui_story_10_15_1_203_dialog_content = "De novo. Vamos tentar de novo.",
  ui_story_10_15_1_204_dialog_content = "Vamos começar do primeiro passo, e tentar de novo.",
  ui_story_10_15_1_205_dialog_content = "<color=#e8d9bb>Controle Primário normal.</color>",
  ui_story_10_15_1_206_dialog_content = "<color=#e8d9bb>Módulos biológicos em hibernação.</color>",
  ui_story_10_15_1_207_dialog_content = "<color=#e8d9bb>Modelo Eco danificado.</color>",
  ui_story_10_15_1_208_dialog_content = "<color=#e8d9bb>Suporte de vida operacional. Capacidade atual: 1 pessoa.</color>",
  ui_story_10_15_1_209_dialog_content = "<color=#e8d9bb>Gerador normal.</color>",
  ui_story_10_15_1_210_dialog_content = "<color=#e8d9bb>Módulo de Tanque Pensante detectado. Conectando...</color>",
  ui_story_10_15_1_211_dialog_content = "<color=#e8d9bb>1%... 3%... 8%...</color>",
  ui_story_10_15_1_212_dialog_content = "<color=#e8d9bb>10%... 25%...</color>",
  ui_story_10_15_1_213_dialog_content = "...",
  ui_story_10_15_1_214_dialog_content = "...",
  ui_story_10_15_1_215_dialog_content = "Já chega, vamos entrar para dar uma olhada!",
  ui_story_10_15_1_216_dialog_content = "No mínimo, precisamos ver se PlayerName está bem!",
  ui_story_10_15_1_217_dialog_content = "Você pode atrapalhar PlayerName se fizer isso, Vice.",
  ui_story_10_15_1_218_dialog_content = "Eu sei, mas...",
  ui_story_10_15_1_219_dialog_content = "Se não conseguir conectar o Módulo de Tanque Pensante na Colossus...",
  ui_story_10_15_1_220_dialog_content = "Se não tiver jeito de consertar Soroz...",
  ui_story_10_15_1_221_dialog_content = "Não quero que PlayerName lide com isso sem ajuda.",
  ui_story_10_15_1_222_dialog_content = "Só vou verificar PlayerName! Vou fazer o possível pra não atrapalhar, prometo!",
  ui_story_10_15_1_223_dialog_content = "*suspira* Ali.",
  ui_story_10_15_1_224_dialog_content = "Se está tão preocupada, por que não chama da entrada?",
  ui_story_10_15_1_225_dialog_content = "PlayerName é Celestita, afinal de contas. Com os sentidos aguçados e habilidades psíquicas de Celestita...",
  ui_story_10_15_1_226_dialog_content = "Tenho certeza que PlayerName vai te ouvir.",
  ui_story_10_15_1_227_dialog_content = "Dessa forma, você não vai contra o desejo de PlayerName de entrar a sós.",
  ui_story_10_15_1_228_dialog_content = "Tem razão! Vou fazer isso!",
  ui_story_10_15_1_229_dialog_content = "Só você para ter uma ideia tão brilhante, Carleen!",
  ui_story_10_15_1_230_dialog_content = "Do que está falando? Aprendi com você, afinal...",
  ui_story_10_15_1_231_dialog_content = "*respira*",
  ui_story_10_15_1_232_dialog_content = "PlayerName!",
  ui_story_10_15_1_233_dialog_content = "<color=#e8d9bb>89%... 97%...</color>",
  ui_story_10_15_1_234_dialog_content = "<color=#e8d9bb>100%. Conexão completa.</color>",
  ui_story_10_15_1_235_dialog_content = "<color=#e8d9bb>Agradecemos por usar o Módulo de Tanque Pensante.</color>",
  ui_story_10_15_1_236_dialog_content = "Vice! Carleen!",
  ui_story_10_15_1_237_dialog_content = "A conexão foi um sucesso! Encontrei uma forma de consertar o Modelo Eco!",
  ui_story_10_15_1_238_dialog_content = "Acho que consigo salvar Soroz!",
  ui_story_10_15_1_239_dialog_content = "Então está dizendo...",
  ui_story_10_15_1_240_dialog_content = "Aquele Celestita chamado PlayerName conseguiu derrotar Schummer, a Celestita traidora?",
  ui_story_10_15_1_241_dialog_content = "E depois, o Celestita deixou a Rediesel Wrench levar a Colossus preta?",
  ui_story_10_15_1_242_dialog_content = "Forsakin não somente falhou em impedi-los, mas também ajudou ainda mais em seus objetivos. Isso está correto?",
  ui_story_10_15_1_243_dialog_content = "Sim.",
  ui_story_10_15_1_244_dialog_content = "Acha que o Celestita vai interferir em nossos planos?",
  ui_story_10_15_1_245_dialog_content = "Não, PlayerName simplesmente vai deixar as coisas mais interessantes.",
  ui_story_10_15_1_246_dialog_content = "Tenho certeza de que Schwartz também acha a mesma coisa.",
  ui_story_70000101_1_dialog_content = "<color=#e8d9bb>\"Executando autodiagnóstico.\"</color>",
  ui_story_70000101_2_dialog_content = "<color=#e8d9bb>\"Verificação do sistema de controle principal... Em execução. Integridade do componente reduzida em 39%. Manutenção necessária.\"</color>",
  ui_story_70000101_3_dialog_content = "<color=#e8d9bb>\"Verificação do módulo biológico... Em execução. Integridade do módulo reduzida em 46%. Manutenção necessária.</color>",
  ui_story_70000101_4_dialog_content = "<color=#e8d9bb>\"Verificação do sistema de suporte à vida... Em execução. Aviso: Carga cheia. Manutenção necessária.\"</color>",
  ui_story_70000101_5_dialog_content = "<color=#e8d9bb>\"Verificação do sistema de manutenção... Normal. Ativando...\"</color>",
  ui_story_70000101_6_dialog_content = "<color=#e8d9bb>\"Erro: Modelo de eco ausente. As funções de manutenção não podem ser ativadas.\"</color>",
  ui_story_70000101_7_dialog_content = "<color=#e8d9bb>\"Falha ao iniciar. Contagem de falhas: 1012.\"</color>",
  ui_story_70000101_8_dialog_content = "<color=#e8d9bb>\"Instale o Echo Template para acessar as funções de manutenção.\"</color>",
  ui_story_70000101_9_dialog_content = "<color=#e8d9bb>\"Aviso: as funções relevantes não estarão mais acessíveis se a integridade do componente cair em 50%.\"</color>",
  ui_story_70000101_10_dialog_content = "<color=#e8d9bb>\"Informe seu nome e confirme.\"</color>",
  ui_story_70000101_11_dialog_content = "Soroz...",
  ui_story_70000101_12_dialog_content = "PlayerName, como está o Soroz?",
  ui_story_70000101_13_dialog_content = "...",
  ui_story_70000101_14_dialog_content = "Ainda o mesmo. Faltando modelo de eco. Não é possível realizar a automanutenção. A situação é crítica.",
  ui_story_70000101_15_dialog_content = "Eu deveria ter reparado Soroz sem demora; em vez disso, deixei-me levar por muitas outras coisas.",
  ui_story_70000101_16_dialog_content = "Não culpe tudo em você. Não percebi o estado anormal de Soroz depois de passar tanto tempo nele. Devo ser responsabilizado por isso.",
  ui_story_70000101_17_dialog_content = "Mas não se preocupe muito. Já encontramos uma solução, não foi?",
  ui_story_70000101_18_dialog_content = "Encontrei algumas pistas!",
  ui_story_70000101_19_dialog_content = "O Think Tank Module nos deu um conjunto de coordenadas, mas... onde está isso?",
  ui_story_70000101_20_dialog_content = "Entendo?",
  ui_story_70000101_21_dialog_content = "Essas coordenadas estão no <color=#FFB400>Zona Cega</color>?!",
  ui_story_70000101_22_dialog_content = "Se bem me lembro... é aí <color=#FFB400>Cidade Baixa 80</color> está localizado.",
  ui_story_70000101_23_option_content = "A Zona Escura...?",
  ui_story_70000101_24_option_content = "Cidade Baixa 80...?",
  ui_story_70000101_25_dialog_content = "A Zona Escura é um nome coletivo para as regiões próximas à Noite Eterna.",
  ui_story_70000101_26_dialog_content = "Undercity 80 é o local para o qual as coordenadas apontam.",
  ui_story_70000101_27_dialog_content = "A Zona Escura é um lugar muito perigoso.",
  ui_story_70000101_28_dialog_content = "O dia é curto e a noite é longa lá. Diz-se também que há grandes aglomerados de Eclipsites reunidos lá.",
  ui_story_70000101_29_dialog_content = "Ei você aí, PlayerName?",
  ui_story_70000101_30_dialog_content = "Huh? Comunicação do Sheol...?",
  ui_story_70000101_31_dialog_content = "Ouvi dizer que você está investigando a Zona Cega. Acontece que eu tenho algumas informações.",
  ui_story_70000101_32_dialog_content = "Huh? Como você sabia?!",
  ui_story_70000101_33_dialog_content = "Os comerciantes da Umbraton estão sempre atentos a potenciais oportunidades de negócios.",
  ui_story_70000101_34_dialog_content = "Eu vejo. Deve ser alguma \"rede especial de inteligência\" ou algo assim, certo?",
  ui_story_70000101_35_dialog_content = "Como esperado de um regular, você me conhece bem.",
  ui_story_70000101_X35_dialog_content = "Estou me sentindo um pouco generoso, então vou te dar uma informação de graça.",
  ui_story_70000101_36_dialog_content = "O conjunto de coordenadas que você tem é um lugar chamado <color=#FFB400>Lama</color>. É um lugar muito perigoso.",
  ui_story_70000101_37_dialog_content = "... Mesmo assim, eu ainda vou.",
  ui_story_70000101_38_dialog_content = "É a única pista do Módulo Think Tank. Não posso ficar aqui sentado e não ajudar o Soroz.",
  ui_story_70000101_39_dialog_content = "PlayerName, pense com seu cérebro, não com seu coração.",
  ui_story_70000101_40_dialog_content = "Não é sábio entrar no Mire sem informações e preparação.",
  ui_story_70000101_41_dialog_content = "...",
  ui_story_70000101_42_dialog_content = "Está correto. Isso é exatamente o que eu aconselharia.",
  ui_story_70000101_43_dialog_content = "No entanto, se você estiver disposto a fazer algo por mim em troca, verei se consigo reunir informações mais pertinentes para você.",
  ui_story_70000101_44_dialog_content = "Não me diga... Nightium de novo?",
  ui_story_70000101_45_dialog_content = "Lumopolis deve ter algumas informações sobre essa região.",
  ui_story_70000101_46_dialog_content = "Posso ir ver se acho alguma coisa.",
  ui_story_70000101_47_dialog_content = "Então eu deixo para você, por favor me ajude.",
  ui_story_70000101_48_dialog_content = "Verifiquei novamente a situação do Soroz. Ainda está operacional. Nada para se preocupar no momento.",
  ui_story_70000101_49_dialog_content = "Faz algum tempo. Carleen e Sheol devem voltar com informações em breve.",
  ui_story_70000101_50_dialog_content = "Também pedi ao meu pessoal na Illumina que ajudasse a procurar pistas. Não se preocupe.",
  ui_story_70000101_51_dialog_content = "Espero que encontrem algo útil, pois...",
  ui_story_70000101_52_dialog_content = "Esta é a única maneira de salvar Soroz.",
  ui_story_70000101_53_dialog_content = "Se este conjunto de coordenadas estiver correto, temo que teremos que procurar em toda a Cidade Baixa.",
  ui_story_70000101_54_dialog_content = "Mesmo que seja a menor Cidade Baixa, ainda levaria dias para passar.",
  ui_story_70000101_55_dialog_content = "Não conseguimos uma localização mais precisa?",
  ui_story_70000101_56_dialog_content = "Não. Isso é tudo o que temos para continuar agora.",
  ui_story_70000101_57_dialog_content = "Talvez se pudermos chegar mais perto do alvo...",
  ui_story_70000101_58_dialog_content = "Você pode me ouvir, PlayerName?",
  ui_story_70000101_59_dialog_content = "Carleen! Sim, eu posso te ouvir!",
  ui_story_70000101_60_dialog_content = "Bom. Estou na biblioteca da Dawn Academy. A recepção é ruim aqui, então vou ser breve.",
  ui_story_70000101_61_dialog_content = "Existem alguns registros de guerras antigas em Undercity 80 aqui.",
  ui_story_70000101_62_dialog_content = "De acordo com os registros, Undercity 80 já foi um posto avançado e centro de transporte da Illumina.",
  ui_story_70000101_63_dialog_content = "Está perto da Noite Eterna, por isso costumava servir como frente de batalha da Federação Illumina e dos Eclipsites.",
  ui_story_70000101_64_dialog_content = "No entanto, durante o <color=#FFB400>Guerra da Zona Escura</color>, sua localização remota dificultava o reforço contra a ofensiva feroz dos Eclipsitas.",
  ui_story_70000101_65_dialog_content = "Illumina logo evacuou e abandonou Undercity 80.",
  ui_story_70000101_66_option_content = "A Guerra da Zona Escura?",
  ui_story_70000101_67_dialog_content = "Ouvi falar dessa guerra. Foi uma invasão de Eclipsite em grande escala que aconteceu há mais de vinte anos.",
  ui_story_70000101_68_dialog_content = "Um grande número de Eclipsite veio da Noite Eterna... Foi uma guerra brutal.",
  ui_story_70000101_69_dialog_content = "Embora a Federação Illumina tenha vencido a guerra, inúmeras Cidades Baixas e soldados foram sacrificados.",
  ui_story_70000101_70_dialog_content = "É o que diz aqui também.",
  ui_story_70000101_71_dialog_content = "Quando a Illumina se retirou, muitos equipamentos foram deixados para trás. Você pode encontrar o que precisa.",
  ui_story_70000101_72_dialog_content = "Eu vejo! Muito obrigado!",
  ui_story_70000101_73_dialog_content = "Sem problemas. Qualquer coisa para ajudar.",
  ui_story_70000101_X74_dialog_content = "<color=#e8d9bb>Bwooommm... Bwooommm...</color>",
  ui_story_70000101_75_dialog_content = "Outra comunicação recebida? Olá?",
  ui_story_70000101_76_dialog_content = "Wsou eu, PlayerName.",
  ui_story_70000101_77_dialog_content = "Oi, Seol. O que você tem?",
  ui_story_70000101_X77_dialog_content = "Eu obtive mais informações... mas não é o ideal.",
  ui_story_70000101_78_dialog_content = "Minhas fontes me dizem que aquele lugar está fervilhando de Eclipsitas.",
  ui_story_70000101_79_dialog_content = "Sem Soroz, não há como chegar perto do Mire.",
  ui_story_70000101_80_dialog_content = "Quanto à Cidade Baixa... Não há nada lá, exceto ruínas com vestígios de batalhas passadas.",
  ui_story_70000101_81_dialog_content = "O núcleo de energia ainda está funcionando por enquanto, mas em seu estado comprometido, não pode manter o sistema de defesa. Provavelmente vai desligar a qualquer segundo.",
  ui_story_70000101_82_dialog_content = "A única pessoa afortunada o suficiente para sair viva diz que a única maneira de entrar ou sair da cidade subterrânea é...",
  ui_story_70000101_83_dialog_content = "UMA <color=#FFB400>abismo</color> causado pelo colapso.",
  ui_story_70000101_84_dialog_content = "Entendo...",
  ui_story_70000101_85_dialog_content = "Entendido.",
  ui_story_70000101_86_dialog_content = "Boa sorte, pessoal.",
  ui_story_70000101_87_dialog_content = "É melhor você voltar vivo e pagar.",
  ui_story_70000101_88_dialog_content = "T-Tá...",
  ui_story_70000101_89_dialog_content = "Estranho. Ainda não há informações de Philyshy?",
  ui_story_70000101_90_dialog_content = "<color=#e8d9bb>Bip Bip...</color>",
  ui_story_70000101_91_dialog_content = "Huh? Philyshy enviou um arquivo.",
  ui_story_70000101_92_dialog_content = "O que é isso? Deixe-me ver.",
  ui_story_70000101_93_dialog_content = "<color=#FFB400>Manual de combate da zona escura?</color>",
  ui_story_70000101_94_option_content = "Vocês têm manuais assim?",
  ui_story_70000101_95_dialog_content = "Nunca ouvi falar de tal coisa antes...",
  ui_story_70000101_96_dialog_content = "Parece barato e grosseiramente montado...",
  ui_story_70000101_97_dialog_content = "Não há índice e o formato não está correto.",
  ui_story_70000101_98_dialog_content = "Não parece nem remotamente autêntico.",
  ui_story_70000101_99_dialog_content = "Que suspeito...",
  ui_story_70000101_100_dialog_content = "Philyshy não forneceria informações não confiáveis.",
  ui_story_70000101_101_option_content = "Ela realmente concordou em ajudar?",
  ui_story_70000101_102_dialog_content = "Isso é tão diferente dela.",
  ui_story_70000101_103_dialog_content = "Esse não é o ponto... Bem, não há mal nenhum em lhe dizer, eu acho...",
  ui_story_70000101_104_dialog_content = "Philyshy quer que eu fique de boca fechada sobre como ela faltou ao trabalho da última vez para tirar uma soneca...",
  ui_story_70000101_105_dialog_content = "Então ela concordou em nos dar informações sobre Undercity 80 em troca do meu silêncio.",
  ui_story_70000101_106_dialog_content = "Isso soa mais como ela...",
  ui_story_70000101_107_dialog_content = "Quero dizer, Philyshy sempre tem as informações mais confiáveis.",
  ui_story_70000101_108_dialog_content = "Mas... por que este manual parece tão de má qualidade?",
  ui_story_70000101_109_dialog_content = "O que diz aí?",
  ui_story_70000101_110_dialog_content = "\"Regra de Combate da Zona Escura 1\"",
  ui_story_70000101_111_dialog_content = "\"Combate na Zona Cega deve ser evitado a menos que seja absolutamente necessário!\"",
  ui_story_70000101_112_dialog_content = "O quê?!",
  ui_story_70000101_113_dialog_content = "A Zona Escura é realmente um lugar tão perigoso?",
  ui_story_70000101_114_dialog_content = "\"De acordo com todas as informações conhecidas, a Zona Cega é uma região altamente perigosa.\"",
  ui_story_70000101_115_dialog_content = "\"O Darkflow concentrado dificulta o movimento dos Aurorianos, e os efeitos são ainda mais pronunciados à noite.\"",
  ui_story_70000101_116_dialog_content = "\"A Zona Escura é o lar dos Eclipsites, por isso existem Eclipsites extremamente poderosos que residem dentro dela. É muito perigoso!\"",
  ui_story_70000101_117_dialog_content = "Soldados da Illumina estão proibidos de entrar... Isso complicaria as coisas para você?",
  ui_story_70000101_119_dialog_content = "Eu não posso deixar você se meter em problemas por isso.",
  ui_story_70000101_120_dialog_content = "Talvez eu possa pedir um favor ao Hiiro!",
  ui_story_70000101_121_dialog_content = "PlayerName...",
  ui_story_70000101_122_dialog_content = "Não se preocupe comigo.",
  ui_story_70000101_123_dialog_content = "Soroz é importante para nós dois.",
  ui_story_70000101_124_dialog_content = "De jeito nenhum eu vou ficar de fora quando meus amigos precisam de mim.",
  ui_story_70000101_125_dialog_content = "Além disso, já estou envolvido. Não relatar isso seria considerado um crime pelos militares da Illumina.",
  ui_story_70000101_126_dialog_content = "Guarde isso do Grande Marechal e dos Comandantes da Legião, e eu ficarei bem...",
  ui_story_70000101_127_dialog_content = "Com certeza vai ficar tudo bem!",
  ui_story_70000101_128_dialog_content = "Desculpe por fazer você correr tanto risco...",
  ui_story_70000101_129_dialog_content = "Este manual parece detalhar tudo sobre combate na Zona Cega...",
  ui_story_70000101_130_dialog_content = "Mas quem escreveu...?",
  ui_story_70000101_131_dialog_content = "Vamos olhar para isso outra hora.",
  ui_story_70000101_132_dialog_content = "Neste momento, nossa prioridade é formar um plano baseado no que temos.",
  ui_story_70000101_133_dialog_content = "Há tantos Eclipsites, além disso a influência do Darkflow é mais pronunciada à noite... e a noite é longa...",
  ui_story_70000101_134_dialog_content = "Esta vai ser uma operação difícil.",
  ui_story_70000101_135_dialog_content = "Poderíamos levar Soroz até lá, contornando todos os Eclipsitos ao longo do caminho.",
  ui_story_70000101_136_dialog_content = "Assim que chegarmos à Cidade Baixa, podemos usar o Módulo Think Tank para localizar o objetivo.",
  ui_story_70000101_137_dialog_content = "Faremos um trabalho rápido e faremos tudo antes do anoitecer...",
  ui_story_70000101_138_dialog_content = "É tão arriscado quanto. E se formos emboscados por Eclipsites de Alto Nível no subsolo?",
  ui_story_70000101_139_dialog_content = "Contorne-os. Devemos evitar o combate a todo custo. Assim que encontrarmos o módulo, vamos recuar.",
  ui_story_70000101_140_dialog_content = "Entendi.",
  ui_story_70000101_141_dialog_content = "Tudo bem então. Vamos sair. Destino: Cidade Baixa 80!",
  ui_story_70000101_142_dialog_content = "<color=#e8d9bb>Linha Segura da Illumina</color>",
  ui_story_70000101_143_dialog_content = "O Soroz está prestes a passar pela linha segura, em direção à Cidade Baixa 80.",
  ui_story_70000101_144_dialog_content = "Você... realmente vai deixá-los passar?",
  ui_story_70000101_145_dialog_content = "Hum? Você me disse algo?",
  ui_story_70000101_146_dialog_content = "S-Sim... Você é o Grande Marechal. Esta é a sua decisão.",
  ui_story_70000101_147_dialog_content = "Desde que você descobriu que eles fizeram Philyshy investigar Undercity 80, então você deve saber o objetivo deles.",
  ui_story_70000101_148_dialog_content = "Sim. PlayerName obteve informações de que existe um item tecnológico de origem antiga que poderia reparar o Modelo de Eco do Colossus em Undercity 80.",
  ui_story_70000101_149_dialog_content = "Por que você acha que ele está procurando por isso?",
  ui_story_70000101_150_dialog_content = "Seu Colosso, o Soroz, perdeu seu Echo Template na luta com Schummer e Forsakin...",
  ui_story_70000101_151_dialog_content = "Para ele, o Colosso é sua família. Perder o Echo Template é provavelmente como se o Colossus tivesse perdido a vida.",
  ui_story_70000101_152_dialog_content = "Se você colocar assim...",
  ui_story_70000101_153_dialog_content = "Que razões tenho para impedir um homem de salvar sua família?",
  ui_story_70000101_154_dialog_content = "Ele não tem más intenções. Acho que posso fechar os olhos desta vez.",
  ui_story_70000101_155_dialog_content = "Vamos tratá-lo como pagamento por seu serviço contra os Eclipsitas.",
  ui_story_70000101_156_dialog_content = "Mas como explicamos isso ao Comitê? Eles proíbem qualquer um de explorar a Zona Escura, especialmente você, Grande Marechal.",
  ui_story_70000101_157_dialog_content = "Isso com certeza é um problema...",
  ui_story_70000101_158_dialog_content = "Diga-lhes então: O celestita entrou na Zona Escura sem autorização. Tentamos interceptá-lo, mas falhamos.",
  ui_story_70000101_159_dialog_content = "Devido às restrições do Comitê, nossas tropas não podem perseguir a linha de segurança.",
  ui_story_70000101_160_dialog_content = "O Caelestite não é um cidadão da Illumina e está ligado a todas as facções.",
  ui_story_70000101_161_dialog_content = "Acredito que o Comitê não faria nada com ele baseado apenas nisso.",
  ui_story_70000101_162_dialog_content = "Mas, Grande Marechal, ainda acho muito perigoso lá dentro.",
  ui_story_70000101_163_dialog_content = "Eles viram sua cota de batalhas. Eu confio que eles têm a capacidade de lidar com o perigo.",
  ui_story_70000101_164_dialog_content = "Desde que sejam diligentes... e sigam o Manual. Eles devem estar bem.",
  ui_story_70000101_165_dialog_content = "Então... por que estamos aqui?",
  ui_story_70000101_166_dialog_content = "Apesar de suas habilidades de combate, eles precisarão de algo mais para sair vivos...",
  ui_story_70000101_167_dialog_content = "Como uma corda de segurança que pode puxá-los para fora do Mire, se necessário.",
  ui_story_70000101_168_dialog_content = "Fique em alerta amarelo e continue monitorando a Zona Cega.",
  ui_story_70000101_169_dialog_content = "Sim, Grande Marechal.",
  ui_story_70000101_170_dialog_content = "Philyshy?",
  ui_story_70000101_171_dialog_content = "Miau!?",
  ui_story_70000101_172_dialog_content = "Vou guardar seu terminal de comunicação por enquanto.",
  ui_story_70000101_173_dialog_content = "Quanto a você faltar ao trabalho... Falaremos sobre isso quando acabar.",
  ui_story_70000101_174_dialog_content = "Entendo...",
  ui_story_70000101_175_dialog_content = "Agora, vá monitorar Undercity 80 e me avise se houver alguma mudança na situação.",
  ui_story_70000101_176_dialog_content = "Sim...",
  ui_story_70000101_177_dialog_content = "Vice... agora você está em apuros...",
  ui_story_70000101_178_dialog_content = "Cidade Baixa 80...",
  ui_story_70000101_179_dialog_content = "Não é lugar para qualquer um. Esses dois com certeza são ousados.",
  ui_story_70000201_1_dialog_content = "Passamos pela linha segura perto da fronteira da Noite Eterna estabelecida pela Federação Illumina.",
  ui_story_70000201_2_dialog_content = "Chegaremos à Cidade Baixa 80 em breve.",
  ui_story_70000201_3_dialog_content = "Está claramente ficando mais escuro. Esta é a Zona Escura?",
  ui_story_70000201_4_dialog_content = "Esse ambiente realmente me deixa desconfortável. Parece que estou respirando com meio pulmão...",
  ui_story_70000201_5_dialog_content = "Espero que isso não afete nossas capacidades de combate...",
  ui_story_70000201_6_dialog_content = "O que diz no Manual?",
  ui_story_70000201_7_dialog_content = "Vejamos...",
  ui_story_70000201_8_dialog_content = "\"Regra 3: Evite o combate a todo custo no Pântano. Saiba quando parar.\"",
  ui_story_70000201_9_dialog_content = "\"Undercity 80 também é conhecido como o Mire por seu Darkflow fortemente concentrado que torna a respiração uma tarefa árdua.\"",
  ui_story_70000201_10_dialog_content = "“O Darkflow também interfere fortemente nos sinais de comunicação, até mesmo paralisando-os completamente a apenas alguns metros de distância”.",
  ui_story_70000201_11_dialog_content = "\"Os efeitos negativos do Darkflow são intensificados ao longo do tempo.\"",
  ui_story_70000201_12_dialog_content = "\"Nightfall também multiplica os efeitos negativos por um fator de 2 no mínimo.\"",
  ui_story_70000201_13_dialog_content = "Em outras palavras, mesmo Eclipsites normais se tornarão extremamente difíceis de manusear.",
  ui_story_70000201_14_dialog_content = "Parece que realmente temos que evitar o combate.",
  ui_story_70000201_15_dialog_content = "E estamos em um cronômetro. As coisas seriam ainda piores à noite.",
  ui_story_70000201_16_dialog_content = "Teremos que contar com a mobilidade do Soroz para entrar durante o dia e acabar com isso o mais rápido possível.",
  ui_story_70000201_17_dialog_content = "PlayerName... você parece mais confiável, de alguma forma.",
  ui_story_70000201_18_dialog_content = "Ah, é mesmo?",
  ui_story_70000201_19_dialog_content = "Você está me fazendo corar...",
  ui_story_70000201_20_dialog_content = "Mas eu estive pensando em algo por um tempo.",
  ui_story_70000201_21_dialog_content = "Quem escreveu o Manual sabe claramente tudo o que há para saber sobre Undercity 80. Ele ou ela poderia ser um veterano de guerra?",
  ui_story_70000201_22_dialog_content = "Não saberíamos...",
  ui_story_70000201_23_dialog_content = "Este Manual não é oficial de forma alguma. Não tem nem o nome do autor.",
  ui_story_70000201_24_dialog_content = "Parece mais uma lista de pontos de atenção elaborados por um comandante da linha de frente para os soldados.",
  ui_story_70000201_25_dialog_content = "Estranho...",
  ui_story_70000201_26_dialog_content = "Mas desde que Philyshy nos deu, tenho certeza que podemos confiar.",
  ui_story_70000201_27_dialog_content = "Só espero que não vejamos o pior que a Zona Cega tem a oferecer.",
  ui_story_70000201_28_dialog_content = "PlayerName, olhar!",
  ui_story_70000201_29_dialog_content = "Isso é Cidade Baixa 80?",
  ui_story_70000201_30_dialog_content = "Estamos aqui?",
  ui_story_70000201_31_dialog_content = "Não se parece com nada do que eu esperava...",
  ui_story_70000201_32_dialog_content = "Pelo que me lembro, as Cidades Baixas da Illumina têm paredes grossas e um grande número de baterias de armas...",
  ui_story_70000201_33_dialog_content = "Mas tudo o que posso ver aqui são ruínas e prédios desmoronados com buracos de bala... e armas quebradas descartadas.",
  ui_story_70000201_34_dialog_content = "Quase parece que este lugar foi devastado por guerras e desastres. . .",
  ui_story_70000201_35_dialog_content = "O que estamos procurando... realmente está aqui?",
  ui_story_70000201_36_dialog_content = "É de se esperar. Uma guerra terrível aconteceu aqui, e está abandonada há muito tempo...",
  ui_story_70000201_37_dialog_content = "Provavelmente é um ninho para os Eclipsites agora...",
  ui_story_70000201_38_dialog_content = "Acredito que um dia a Illumina recuperará este lugar.",
  ui_story_70000201_39_dialog_content = "Cada cidade subterrânea possui energia, recursos e tecnologia preciosos.",
  ui_story_70000201_40_dialog_content = "A Illumina... nunca deixará os Eclipsitas tê-lo.",
  ui_story_70000201_41_dialog_content = "...",
  ui_story_70000201_42_dialog_content = "Há um monte de Eclipsites vagando na superfície. Não podemos perder tempo lutando contra eles.",
  ui_story_70000201_43_dialog_content = "Encontre um lugar tranquilo para pousar. Vamos nos esgueirar a pé.",
  ui_story_70000201_44_dialog_content = "É madrugada agora. Devemos ter tempo suficiente para completar a operação.",
  ui_story_70000201_45_dialog_content = "<color=#e8d9bb>Pouco tempo depois...</color>",
  ui_story_70000201_46_dialog_content = "É isso que Darkflow faz conosco?",
  ui_story_70000201_47_dialog_content = "Meu corpo está tão pesado... como se eu estivesse carregando pesos nas costas...",
  ui_story_70000201_48_dialog_content = "O mesmo aqui... Leva apenas alguns passos antes de eu começar a ofegar...",
  ui_story_70000201_49_dialog_content = "Deve ser o que o Manual disse... o impacto da Zona Cega...",
  ui_story_70000201_50_dialog_content = "É quase impossível lutar nestas circunstâncias...",
  ui_story_70000201_51_dialog_content = "Vamos encontrar uma maneira de entrar primeiro.",
  ui_story_70000201_52_dialog_content = "Tudo desmoronou. Não há como encontrar a entrada original para a Cidade Baixa.",
  ui_story_70000201_53_dialog_content = "Apenas o número 80 branco vagamente visível na placa de aço descartada pode provar que esta já foi uma Cidade Baixa dos Illumina...",
  ui_story_70000201_54_dialog_content = "A estrutura principal comprometida, a parede externa completamente desmoronada, a estrutura arquitetônica toda retorcida...",
  ui_story_70000201_55_dialog_content = "Um terremoto de 9.0 deve ter acontecido aqui, isso, ou ser atacado por Eclipsites de elite por 24 horas sem parar...",
  ui_story_70000201_56_dialog_content = "Caso contrário, não há como danificar as defesas da Cidade Baixa da Illumina nesse grau.",
  ui_story_70000201_57_dialog_content = "Como estão os portões da frente?",
  ui_story_70000201_58_dialog_content = "Completamente enterrado.",
  ui_story_70000201_59_dialog_content = "Não há nenhuma rota para a área subterrânea à vista.",
  ui_story_70000201_60_dialog_content = "Parece que vamos ter que encontrar isso <color=#FFB400>abismo</color> Sheol nos falou.",
  ui_story_70000201_61_dialog_content = "*Rugindo*",
  ui_story_70000201_62_dialog_content = "Observe seu flanco, PlayerName!",
  ui_story_70000201_63_dialog_content = "De onde eles vieram!?",
  ui_story_70000201_64_dialog_content = "Parece haver uma rachadura ou algum tipo na direção de onde os Eclipsitas apareceram!",
  ui_story_70000201_65_dialog_content = "Parece que não vamos sair dessa batalha...",
  ui_story_70000201_66_dialog_content = "Vice, siga o Manual e tome cuidado.",
  ui_story_70000201_67_dialog_content = "Pode deixar!",
  ui_story_70000202_1_dialog_content = "*Ronca*",
  ui_story_70000202_2_dialog_content = "Acabou... finalmente?",
  ui_story_70000202_3_dialog_content = "Estou com dor de cabeça...",
  ui_story_70000202_4_dialog_content = "Eu nem consigo mais ver o rastro de luz...",
  ui_story_70000202_5_dialog_content = "PlayerName?!",
  ui_story_70000202_6_dialog_content = "Estou bem... Quase desmaiei.",
  ui_story_70000202_7_dialog_content = "Vamos manter um perfil discreto a partir de agora para evitar problemas...",
  ui_story_70000202_8_dialog_content = "Não esperava que as coisas fossem tão difíceis aqui...",
  ui_story_70000202_9_dialog_content = "Não posso desistir... preciso salvar o Soroz...",
  ui_story_70000202_10_dialog_content = "Vamos verificar o abismo.",
  ui_story_70000202_11_dialog_content = "Bom...",
  ui_story_70000202_12_dialog_content = "Este não é um abismo.",
  ui_story_70000202_13_dialog_content = "Isso é um penhasco!",
  ui_story_70000202_14_dialog_content = "Quase consigo distinguir algo brilhando lá embaixo.",
  ui_story_70000202_15_dialog_content = "Parece a luz de sinal de uma máquina de algum tipo!",
  ui_story_70000202_16_dialog_content = "A cidade ainda está operacional!?",
  ui_story_70000202_17_dialog_content = "Essa tubulação de extrusão deve servir como base...",
  ui_story_70000202_18_dialog_content = "A esta altura, eu posso tomar PlayerName e pousar no fundo.",
  ui_story_70000202_19_dialog_content = "Mas precisamos encontrar outra saída.",
  ui_story_70000202_20_dialog_content = "A saída... Diz alguma coisa no Manual?",
  ui_story_70000202_21_dialog_content = "Eu penso que sim! Deixe-me ver!",
  ui_story_70000202_22_dialog_content = "\"Undercity 80 tem uma passagem de fuga que leva da Sala do Núcleo à superfície.\"",
  ui_story_70000202_23_dialog_content = "No entanto, para evitar que inimigos externos penetrem na cidade através do túnel, só é acessível por dentro.",
  ui_story_70000202_24_dialog_content = "A entrada do túnel está bem escondida atrás de uma porta secreta ao lado do núcleo de energia da Cidade Baixa.",
  ui_story_70000202_25_dialog_content = "\"Dê 3 batidas leves, 3 batidas pesadas e, em seguida, 3 batidas leves ao longo da parede norte da Sala do Núcleo para abrir a porta secreta.\"",
  ui_story_70000202_26_dialog_content = "Há coisas que nem Sheol sabe!?",
  ui_story_70000202_27_dialog_content = "O autor deve ter trabalhado ou lutado aqui para saber tanto sobre Undercity 80.",
  ui_story_70000202_28_dialog_content = "Agora que garantimos a rota de fuga, é hora de nos movermos.",
  ui_story_70000202_29_dialog_content = "Segure para mim, PlayerName.",
  ui_story_70000202_30_dialog_content = "Posso dizer não? Isso quase parece...",
  ui_story_70000202_31_dialog_content = "Ei!",
  ui_story_70000202_32_dialog_content = "<anim type=Shake>Ahhhhhhhhhh!</anim>",
  ui_story_70000202_33_dialog_content = "Quase como...",
  ui_story_70000202_34_dialog_content = "PlayerName, cuidado para não morder a língua!",
  ui_story_70000202_35_dialog_content = "<size=45><anim type=Shake>Ahhhhhhh!</anim></size>",
  ui_story_70000202_36_dialog_content = "Ei!",
  ui_story_70000202_37_dialog_content = "<size=50><anim type=Shake>Ahhhhhhh!</anim></size>",
  ui_story_70000202_38_dialog_content = "Já desembarcamos, PlayerName...",
  ui_story_70000202_39_dialog_content = "Ah... É isso mesmo?",
  ui_story_70000202_40_dialog_content = "Você está bem?",
  ui_story_70000202_41_dialog_content = "Estamos no chão?",
  ui_story_70000202_42_dialog_content = "Estou tão tonto... Espere...",
  ui_story_70000202_43_dialog_content = "Huh? É porque foi um pouso difícil? Precisa descansar um pouco?",
  ui_story_70000202_44_dialog_content = "Apenas deixe-me recuperar o fôlego...",
  ui_story_70000202_45_dialog_content = "Como está a situação ao redor?",
  ui_story_70000202_46_dialog_content = "Ainda não há eclipses à vista.",
  ui_story_70000202_47_dialog_content = "Parece ser o terreno mais baixo da Cidade Baixa nas proximidades.",
  ui_story_70000202_48_dialog_content = "Restos da ruína e máquinas em todos os lugares. Também parece haver fragmentos do equipamento padrão da Illumina.",
  ui_story_70000202_49_dialog_content = "A marcação na parede diz... <color=#FFB400>Eixo de Ventilação 02</color>?",
  ui_story_70000202_50_dialog_content = "Parece que estamos dentro da Cidade Baixa, certo.",
  ui_story_70000202_51_dialog_content = "Buracos de bala em todas as paredes... Uma batalha feroz aconteceu aqui.",
  ui_story_70000202_52_dialog_content = "A Guerra da Zona Escura?",
  ui_story_70000202_53_dialog_content = "Os projéteis de bala no chão são consistentes com as armas padrão da antiga Illumina. Então, isso é provavelmente um sim.",
  ui_story_70000202_54_dialog_content = "Não é à toa que quem escreveu este manual não quer que ninguém volte aqui.",
  ui_story_70000202_55_dialog_content = "É quase como um lodo que... devora a vida.",
  ui_story_70000202_56_dialog_content = "...",
  ui_story_70000202_57_option_content = "(Toque nos buracos de bala)",
  ui_story_70000202_58_option_content = "(Pegue os cartuchos de bala)",
  ui_story_70000202_59_dialog_content = "D-Não chegue mais perto!",
  ui_story_70000202_60_dialog_content = "*Rugindo*",
  ui_story_70000202_61_dialog_content = "Ajuda... Ajuda-me...",
  ui_story_70000202_62_dialog_content = "Hã?",
  ui_story_70000202_63_dialog_content = "Não me coma! Eu não sou bom para comer!",
  ui_story_70000202_64_dialog_content = "*Rugindo*",
  ui_story_70000202_65_dialog_content = "Mamãe... eu quero minha mamãe...",
  ui_story_70000202_66_dialog_content = "Eu... não posso mais voltar...",
  ui_story_70000202_67_dialog_content = "...",
  ui_story_70000202_68_dialog_content = "Você viu, não é, PlayerName?",
  ui_story_70000202_69_dialog_content = "Hmm...",
  ui_story_70000202_70_dialog_content = "Não há nada que possamos fazer sobre isso... Deixa pra lá.",
  ui_story_70000202_71_dialog_content = "Vamos verificar a localização do nosso objetivo.",
  ui_story_70000202_72_dialog_content = "OK. Deixe-me tentar senti-lo.",
  ui_story_70000202_73_option_content = "Estabeleça uma ligação mental!",
  ui_story_70000202_74_dialog_content = "...!",
  ui_story_70000202_75_dialog_content = "O que estamos procurando ainda está abaixo de nós.",
  ui_story_70000202_76_dialog_content = "A interferência é pesada. Só consegui uma direção geral.",
  ui_story_70000202_77_dialog_content = "Dessa maneira!",
  ui_story_70000202_78_dialog_content = "Outro penhasco...",
  ui_story_70000202_79_dialog_content = "Parece ser mais profundo que o anterior, e não há como descer...",
  ui_story_70000202_80_dialog_content = "Os Eclipsites definitivamente vão nos notar se pularmos assim.",
  ui_story_70000202_81_dialog_content = "Então talvez seremos emboscados.",
  ui_story_70000202_82_dialog_content = "Mas meus sentidos nos trouxeram aqui, o que deve significar que este é o caminho mais rápido.",
  ui_story_70000202_83_dialog_content = "Quanto nos resta?",
  ui_story_70000202_84_dialog_content = "Não muito.",
  ui_story_70000202_85_dialog_content = "O dia aqui é muito mais curto do que em outros lugares. 6 horas no máximo.",
  ui_story_70000202_86_dialog_content = "Se quisermos fugir durante o dia, temos apenas cerca de 3 horas restantes.",
  ui_story_70000202_87_dialog_content = "Vamos apenas por aqui. Vamos nos esconder no momento em que pousarmos. Deve ser o suficiente.",
  ui_story_70000202_88_dialog_content = "Tudo bem... eu confio em você.",
  ui_story_70000301_1_dialog_content = "Onde estão aqueles dois agora?",
  ui_story_70000301_2_dialog_content = "A julgar pelo ping neles, eles ainda estão dentro da Undercity 80.",
  ui_story_70000301_3_dialog_content = "Mas a interferência pesada do Darkflow está atrapalhando o sinal. Eles talvez... no fundo?",
  ui_story_70000301_4_dialog_content = "Espero que tudo corra bem para eles.",
  ui_story_70000301_5_dialog_content = "Não se preocupe. Mantenha sua cabeça clara.",
  ui_story_70000301_6_dialog_content = "Nenhuma notícia é a melhor notícia sobre agentes secretos.",
  ui_story_70000301_7_dialog_content = "Por que diz isso?",
  ui_story_70000301_8_dialog_content = "Cada indivíduo da Illumina está sob meu comando. Como Grande Marechal, conheço muito bem as habilidades do meu povo.",
  ui_story_70000301_9_dialog_content = "Além disso, desde que a Vice começou a trabalhar com <color=#FFB400>aquele indivíduo</color>, eu prestei a ela \"atenção especial\".",
  ui_story_70000301_10_dialog_content = "Então você não precisa se preocupar. Deixei algumas medidas de segurança no Manual.",
  ui_story_70000301_11_dialog_content = "Medidas de segurança...?",
  ui_story_70000301_12_dialog_content = "Se eles ainda estiverem na Cidade Baixa em uma hora e meia, entre em contato com eles através do comunicador.",
  ui_story_70000301_13_dialog_content = "Sim.",
  ui_story_70000301_14_dialog_content = "...",
  ui_story_70000301_15_dialog_content = "PlayerName, Por aqui.",
  ui_story_70000301_16_dialog_content = "Nós claramente vimos mais Eclipses aqui...",
  ui_story_70000301_17_dialog_content = "Também está ficando mais difícil apenas andar...",
  ui_story_70000301_18_dialog_content = "Apenas espere, PlayerName.",
  ui_story_70000301_19_dialog_content = "Eu não posso... estou exausta...",
  ui_story_70000301_20_dialog_content = "É muito perigoso aqui. Precisamos encontrar um lugar seguro se precisarmos descansar.",
  ui_story_70000301_21_dialog_content = "Olha, estamos a apenas algumas centenas de metros de chegar ao topo da Sala Núcleo.",
  ui_story_70000301_22_dialog_content = "Se você realmente não pode andar... eu posso carregá-lo.",
  ui_story_70000301_23_dialog_content = "Não, está tudo bem.",
  ui_story_70000301_24_dialog_content = "Eu só preciso recuperar o fôlego, só isso!",
  ui_story_70000301_25_dialog_content = "Assim que voltarmos a Soroz com o alvo, prepararei um banquete para você!",
  ui_story_70000301_26_dialog_content = "Não há necessidade disso... sério!",
  ui_story_70000301_27_dialog_content = "Não estou nem um pouco cansado! Vamos lá!",
  ui_story_70000301_28_dialog_content = "Eclipses à frente! Não consigo ver quantos... Está muito escuro.",
  ui_story_70000301_29_dialog_content = "Bem do lado de fora da entrada do túnel para a câmara do núcleo? Isso é difícil.",
  ui_story_70000301_30_dialog_content = "Podemos contorná-los?",
  ui_story_70000301_31_dialog_content = "Deixe-me verificar o mapa.",
  ui_story_70000301_32_dialog_content = "Onde você conseguiu um mapa!?",
  ui_story_70000301_33_dialog_content = "Huh? Você não percebeu?",
  ui_story_70000301_34_dialog_content = "Encontrei meio mapa nas ruínas enquanto você descansava. Então eu apenas copiei no caderno.",
  ui_story_70000301_35_dialog_content = "Sua memória é tão boa?",
  ui_story_70000301_36_dialog_content = "É um desenho estrutural, então, moleza!",
  ui_story_70000301_37_dialog_content = "Todas as Cidades Baixas foram construídas seguindo uma certa lógica. Não é difícil lembrar do mapa se você conhece a lógica da construção.",
  ui_story_70000301_38_dialog_content = "Por exemplo, sempre haverá duas ou mais saídas de emergência, e os poços de ventilação estão localizados...",
  ui_story_70000301_39_dialog_content = "Pare! Só preciso saber se podemos dar a volta nos Eclipsites.",
  ui_story_70000301_40_dialog_content = "Sim, mas não sei se está bloqueado ou não.",
  ui_story_70000301_41_dialog_content = "Além disso, é um desvio e tanto. A julgar pela velocidade que estamos indo agora, vai nos custar pelo menos meia hora a mais.",
  ui_story_70000301_42_dialog_content = "Meia hora, não é? Não temos muito tempo para começar... Quanto mais tempo estamos aqui, mais perigoso é para nós...",
  ui_story_70000301_43_dialog_content = "Então, o que fazemos, PlayerName?",
  ui_story_70000301_44_dialog_content = "Eu estou correndo contra o tempo.",
  ui_story_70000301_45_dialog_content = "Não temos tempo e não podemos correr o risco de um desvio.",
  ui_story_70000301_46_dialog_content = "Que tal isso, vamos flanquear os Eclipsites.",
  ui_story_70000301_X46_dialog_content = "Eu chamarei a atenção deles e você os atacará por trás. Apenas certifique-se de obtê-los rapidamente.",
  ui_story_70000301_47_dialog_content = "Vamos fazê-lo.",
  ui_story_70000301_48_dialog_content = "Assista, PlayerName.",
  ui_story_70000302_1_dialog_content = "Você notou que aqueles Eclipsites eram muito mais fortes do que os que encontramos?",
  ui_story_70000302_2_dialog_content = "Talvez não sejam eles... Somos nós que estamos ficando mais fracos.",
  ui_story_70000302_3_dialog_content = "Quanto mais fundo vamos, mais difícil acho até mesmo respirar.",
  ui_story_70000302_4_dialog_content = "Além do tempo, a profundidade também pode desempenhar um papel na flutuação da concentração do Darkflow aqui.",
  ui_story_70000302_5_dialog_content = "Quanto menor a probabilidade de escaparmos, mais fundo vamos... Não é à toa que se chama Mire.",
  ui_story_70000302_6_dialog_content = "Estamos bem no topo da Sala do Núcleo agora. Não há eclipses ao redor. Estamos seguros no momento.",
  ui_story_70000302_7_dialog_content = "PlayerName, você não parece muito bom. É melhor você fazer uma pausa.",
  ui_story_70000302_8_dialog_content = "Ainda temos uma hora e meia. Alguns minutos não vão afetar nada.",
  ui_story_70000302_9_dialog_content = "Eu ainda posso aguentar um pouco mais... Mal posso esperar...",
  ui_story_70000302_10_dialog_content = "O Manual diz que você precisa aproveitar todas as oportunidades para descansar para manter sua força ao lutar na Zona Cega.",
  ui_story_70000302_11_dialog_content = "Se você não vai me ouvir, então ouça este veterano.",
  ui_story_70000302_12_dialog_content = "Certo... Desculpe, Vice. As emoções tomaram conta de mim.",
  ui_story_70000302_13_dialog_content = "Não se preocupe com isso. Nós somos amigos.",
  ui_story_70000302_14_dialog_content = "Aqui. Sente-se nesta pedra.",
  ui_story_70000302_15_dialog_content = "Onde estamos agora?",
  ui_story_70000302_16_dialog_content = "De acordo com o Manual, devemos estar no armazém agora. Estamos bem fundo agora.",
  ui_story_70000302_17_dialog_content = "Tem várias coisas espalhadas.",
  ui_story_70000302_18_dialog_content = "Latas, caixas médicas vazias e cartuchos de bala...",
  ui_story_70000302_19_dialog_content = "Bem como fortificações improvisadas e esfarrapadas feitas com gaze suja e restos de ferro.",
  ui_story_70000302_20_dialog_content = "O Soldado Illumina aqui deve ter lutado até o último homem.",
  ui_story_70000302_21_dialog_content = "No entanto, eles ainda o perderam.",
  ui_story_70000302_22_dialog_content = "...",
  ui_story_70000302_23_dialog_content = "Só sei que a Illumina perdeu muita gente boa naquela guerra...",
  ui_story_70000302_24_dialog_content = "Se tivermos tempo, provavelmente podemos encontrar as placas de identificação deles aqui...",
  ui_story_70000302_25_dialog_content = "Se pudermos levá-los de volta para a Illumina, seria o fechamento de suas famílias...",
  ui_story_70000302_26_dialog_content = "Vice...",
  ui_story_70000302_27_dialog_content = "Só se eu também puder ajudar...",
  ui_story_70000302_28_dialog_content = "Hã?",
  ui_story_70000302_29_dialog_content = "Isso é...",
  ui_story_70000302_30_dialog_content = "O que você achou, PlayerName?",
  ui_story_70000302_31_dialog_content = "Aqueles fragmentos enterrados nas ruínas... parecem familiares.",
  ui_story_70000302_32_dialog_content = "Eles têm poeira em cima, mas parecem ser brancos, e os padrões em cima lembram...",
  ui_story_70000302_33_dialog_content = "<color=#FFB400>O Colosso?</color>",
  ui_story_70000302_34_dialog_content = "Hã?",
  ui_story_70000302_35_dialog_content = "Agora que você falou...",
  ui_story_70000302_36_dialog_content = "Pode parecer nada além de fragmentos de relance, mas se eu olhar mais de perto...",
  ui_story_70000302_37_dialog_content = "São partes do Colosso?",
  ui_story_70000302_38_dialog_content = "Mesmo que não sejam, definitivamente são algo que só existe no Eraveil.",
  ui_story_70000302_39_dialog_content = "Não é à toa que o Módulo Think Tank diz que o que precisamos para reparar o Colossus está aqui.",
  ui_story_70000302_40_dialog_content = "Parece que estamos no caminho certo.",
  ui_story_70000302_41_dialog_content = "Deixe-me sentir a localização do alvo novamente.",
  ui_story_70000302_42_option_content = "Mindlink!",
  ui_story_70000302_43_dialog_content = "Isso é...",
  ui_story_70000302_44_dialog_content = "*Rugido*",
  ui_story_70000302_45_dialog_content = "?!",
  ui_story_70000302_46_dialog_content = "PlayerName? Você está bem?",
  ui_story_70000302_47_dialog_content = "Senti algo... poderoso...",
  ui_story_70000302_48_dialog_content = "Eclipsita?",
  ui_story_70000302_49_dialog_content = "Parece que... mas não tenho certeza...",
  ui_story_70000302_50_dialog_content = "Eu posso sentir o poderoso Darkflow emanando dele, mas também Lumina escondido dentro.",
  ui_story_70000302_51_dialog_content = "É como...",
  ui_story_70000302_52_dialog_content = "Eles são monstros criados por Forsakin aqui?",
  ui_story_70000302_53_dialog_content = "Não tenho certeza.",
  ui_story_70000302_54_dialog_content = "Só sei que essa coisa é muito poderosa.",
  ui_story_70000302_55_dialog_content = "Não está perto de nós. Acho que podemos passar por ela e sair com o que precisamos.",
  ui_story_70000302_56_dialog_content = "Silenciosamente...",
  ui_story_70000302_57_dialog_content = "Silenciosamente...",
  ui_story_70000302_58_dialog_content = "Acabou o tempo. Você consegue contatá-los?",
  ui_story_70000302_59_dialog_content = "Não, o sinal deles sumiu completamente, miau.",
  ui_story_70000302_60_dialog_content = "Devo enviar uma equipe de busca e salvamento?",
  ui_story_70000302_61_dialog_content = "Prepare a equipe... Eu mesmo a lidero.",
  ui_story_70000302_62_dialog_content = "Você está indo!?",
  ui_story_70000302_63_dialog_content = "É claro. É hora de eu fazer algum exercício, de qualquer maneira.",
  ui_story_70000302_64_dialog_content = "É muito cedo para um desafio a este nível?",
  ui_story_70000302_65_dialog_content = "Parece que eu realmente tenho que jogar pelos livros...",
  ui_story_70000302_66_dialog_content = "Eu vejo. Equipe de resgate, prepare-se!",
  ui_story_70000302_67_dialog_content = "(Eclipsian) As tropas de Illumina estão se reunindo perto da fronteira da Noite Eterna.",
  ui_story_70000302_68_dialog_content = "(Eclipsiano) \"Ele\" está entre eles.",
  ui_story_70000302_69_dialog_content = "(Eclipsiano) Quase ao mesmo tempo, o Caelestite entrou na Cidade Baixa 80.",
  ui_story_70000302_70_dialog_content = "Cidade Baixa 80...",
  ui_story_70000302_71_dialog_content = "Ela também está procurando <color=#FFB400>\"que\"</color>?",
  ui_story_70000302_72_dialog_content = "Verdade o suficiente. É o único lugar onde uma pista ainda pode existir neste mundo.",
  ui_story_70000302_73_dialog_content = "Mostre-me o que você pode encontrar...",
  ui_story_70000302_74_dialog_content = "Minha irmã.\"",
  ui_story_70000401_1_dialog_content = "Me dê sua mão, PlayerName.",
  ui_story_70000401_2_dialog_content = "Ei!",
  ui_story_70000401_3_dialog_content = "Finalmente... estamos... aqui...",
  ui_story_70000401_4_dialog_content = "Não é brincadeira o quão concentrado o Darkflow está aqui... Mover um músculo nunca foi tão difícil.",
  ui_story_70000401_5_dialog_content = "PlayerName, é o que estamos procurando realmente aqui?",
  ui_story_70000401_6_dialog_content = "Eu posso sentir isso. Está perto.",
  ui_story_70000401_7_dialog_content = "Deve estar... em cima da máquina na Sala do Núcleo.",
  ui_story_70000401_8_dialog_content = "Deve ser aquela coisa!",
  ui_story_70000401_9_dialog_content = "Isso é... realmente um modelo de eco?",
  ui_story_70000401_10_dialog_content = "Não se parece em nada com o que Soroz tinha.",
  ui_story_70000401_11_dialog_content = "Mas o Módulo Think Tank nos apontou para isso.",
  ui_story_70000401_12_dialog_content = "Nada ao redor poderia ser um modelo de eco.",
  ui_story_70000401_13_dialog_content = "Vamos levá-lo de volta ao Soroz e ver.",
  ui_story_70000401_14_dialog_content = "Ok, mas está instalado no núcleo.",
  ui_story_70000401_15_dialog_content = "Vou ver se consigo tirar.",
  ui_story_70000401_16_dialog_content = "Hmm...",
  ui_story_70000401_17_dialog_content = "Nenhuma alegria. Está realmente embutido lá.",
  ui_story_70000401_18_dialog_content = "PlayerName, me dê uma mão com isso.",
  ui_story_70000401_19_dialog_content = "Aí vem eles!",
  ui_story_70000401_20_dialog_content = "Na contagem de três...",
  ui_story_70000401_21_dialog_content = "Três...",
  ui_story_70000401_22_dialog_content = "Dois...",
  ui_story_70000401_23_dialog_content = "Um...",
  ui_story_70000401_24_dialog_content = "Agora!",
  ui_story_70000401_25_dialog_content = "Afe!",
  ui_story_70000401_26_dialog_content = "Acho que bati em alguma coisa na nuca... O módulo está intacto?",
  ui_story_70000401_27_dialog_content = "Parece bem. Vamos nos apressar e sair daqui!",
  ui_story_70000401_28_dialog_content = "<color=#e8d9bb>*resmunga*</color>",
  ui_story_70000401_29_dialog_content = "É um terremoto?",
  ui_story_70000401_30_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_70000401_31_dialog_content = "A fonte de alimentação da Cidade Baixa... acabou de parar?",
  ui_story_70000401_32_dialog_content = "É porque pegamos o módulo?",
  ui_story_70000401_33_dialog_content = "Não sei, mas posso sentir...",
  ui_story_70000401_34_dialog_content = "<color=#e8d9bb>Bum!!—</color>",
  ui_story_70000401_36_dialog_content = "Está se aproximando!",
  ui_story_70000401_37_dialog_content = "Está caindo!",
  ui_story_70000401_37X1_dialog_content = "PlayerName, afaste-se dessa parede!",
  ui_story_70000401_37X2_dialog_content = "*COF cof*",
  ui_story_70000401_37X3_dialog_content = "Tão empoeirado...",
  ui_story_70000401_37X4_dialog_content = "...",
  ui_story_70000401_37X5_dialog_content = "Há um espaço aberto na parte de trás da parede desmoronada...?",
  ui_story_70000401_37X6_dialog_content = "O que tem dentro...?",
  ui_story_70000401_37X7_dialog_content = "...",
  ui_story_70000401_37X8_dialog_content = "O Darkflow é sufocante!",
  ui_story_70000401_37X9_dialog_content = "Poderia ser o Eclipse PlayerName sentiu...?",
  ui_story_70000401_37X10_dialog_content = "...!",
  ui_story_70000401_37X11_dialog_content = "É realmente um Eclipse! Um tipo que nunca vimos antes!",
  ui_story_70000401_37X12_dialog_content = "Não parece estar reagindo à nossa presença... Poderia estar dormindo?",
  ui_story_70000401_37X13_dialog_content = "Não vamos perturbá-lo. Vamos passar por ela e encontrar a saída...",
  ui_story_70000401_37X14_dialog_content = "No entanto, devemos vencer a parede para revelar a saída, que definitivamente o despertará.",
  ui_story_70000401_37X15_dialog_content = "Se isso acontecer, você—",
  ui_story_70000401_37X16_dialog_content = "Ilu...",
  ui_story_70000401_37X17_dialog_content = "Ele está falando em seu sono?",
  ui_story_70000401_37X18_dialog_content = "Fica muito longe. Eu não consigo entender.",
  ui_story_70000401_37X19_dialog_content = "Há um monte de Eclipses que falam...",
  ui_story_70000401_37X20_dialog_content = "Não importa. Vamos tentar sair daqui primeiro!",
  ui_story_70000401_37X21_dialog_content = "Você tem razão.",
  ui_story_70000401_37X22_dialog_content = "Ilu...mina...!",
  ui_story_70000401_37X23_dialog_content = "Espere, você ouviu isso? Disse—",
  ui_story_70000401_37X24_dialog_content = "*Rugido*",
  ui_story_70000401_37X25_dialog_content = "Caramba! Está acordado!",
  ui_story_70000401_37X26_dialog_content = "Correr! Ele nos viu!",
  ui_story_70000401_38_dialog_content = "Cuidado, PlayerName!",
  ui_story_70000401_39_dialog_content = "Vice, você tá bem?",
  ui_story_70000401_39X1_dialog_content = "O Darkflow é muito forte. Não podemos lutar contra isso aqui! Procure uma chance de sair daqui!",
  ui_story_70000401_40_dialog_content = "Você o mantém distraído enquanto eu encontro a saída!",
  ui_story_70000401_41_dialog_content = "Argh...",
  ui_story_70000401_42_dialog_content = "Entendi! Eu não posso aguentar por muito tempo, então é melhor você se apressar e encontrar aquela porta secreta!",
  ui_story_70000402_1_dialog_content = "A luz bate...",
  ui_story_70000402_2_dialog_content = "<color=#e8d9bb>Toc toc toc..</color>",
  ui_story_70000402_3_dialog_content = "Três batidas pesadas...",
  ui_story_70000402_4_dialog_content = "<color=#e8d9bb>Bater! Bater! Bater!</color>",
  ui_story_70000402_5_dialog_content = "A luz bate...",
  ui_story_70000402_6_dialog_content = "<color=#e8d9bb>Toc toc toc..</color>",
  ui_story_70000402_7_dialog_content = "...",
  ui_story_70000402_8_dialog_content = "Nada!? Sério?",
  ui_story_70000402_9_dialog_content = "Abra!",
  ui_story_70000402_10_dialog_content = "Você conseguiu ainda, PlayerName?",
  ui_story_70000402_11_dialog_content = "Não está fazendo nada!",
  ui_story_70000402_12_dialog_content = "*Rugindo*",
  ui_story_70000402_13_dialog_content = "Urgh...!",
  ui_story_70000402_14_dialog_content = "Isso não vai funcionar! Vamos recuar ainda mais!",
  ui_story_70000402_15_dialog_content = "É um beco sem saída lá atrás!",
  ui_story_70000402_16_dialog_content = "Não há outra maneira!",
  ui_story_70000402_17_dialog_content = "Mas essa coisa está em nosso caminho de volta à superfície... Não podemos romper!",
  ui_story_70000402_18_dialog_content = "Podemos ter uma chance nas profundezas!",
  ui_story_70000402_19_dialog_content = "Você tem razão...",
  ui_story_70000402_20_dialog_content = "Então pare de ficar parado e corra!",
  ui_story_70000402_21_dialog_content = "*Rugindo*",
  ui_story_70000402_22_dialog_content = "<color=#e8d9bb>Estrondo...!</color>",
  ui_story_70000402_23_dialog_content = "R-Relatório!",
  ui_story_70000402_24_dialog_content = "Um forte terremoto é detectado na direção das ruínas de Undercity 80!",
  ui_story_70000402_25_dialog_content = "Estável! Estável!",
  ui_story_70000402_26_dialog_content = "Mantenha sua formação defensiva. Continue para a Cidade Baixa 80.",
  ui_story_70000402_27_dialog_content = "Sim!",
  ui_story_70000402_28_dialog_content = "<color=#e8d9bb>Ahhhhhh!</color>",
  ui_story_70000402_29_dialog_content = "Que som é esse?!",
  ui_story_70000402_30_dialog_content = "Isso...",
  ui_story_70000402_31_dialog_content = "...!",
  ui_story_70000402_32_dialog_content = "Essa sensação...",
  ui_story_70000402_33_dialog_content = "Não, não é possível...",
  ui_story_70000402_34_dialog_content = "Grande Marechal, você está bem?",
  ui_story_70000402_35_dialog_content = "...",
  ui_story_70000402_36_dialog_content = "Não. Não posso enviá-los.",
  ui_story_70000402_37_dialog_content = "Não é algo que eles possam lidar.",
  ui_story_70000402_38_dialog_content = "Resgate, retorne à Linha Segura imediatamente! Isso é uma ordem!",
  ui_story_70000402_39_dialog_content = "Não vá para a Zona Cega, não importa o quê.",
  ui_story_70000402_40_dialog_content = "Sim senhor! Mas... Grande Marechal...",
  ui_story_70000402_41_dialog_content = "Não se preocupe. Certas coisas eu devo cuidar de mim mesmo.",
  ui_story_70000402_42_dialog_content = "Além disso, me dê uma mensagem para Vivian...",
  ui_story_70000402_43_dialog_content = "Peça a ela para lidar com \"essas pessoas\" antes de eu voltar.",
  ui_story_70000402_44_dialog_content = "Sim!",
  ui_story_70000402_45_dialog_content = "<color=#e8d9bb>Ahhhhhh!</color>",
  ui_story_70000402_46_dialog_content = "...",
  ui_story_70000402_47_dialog_content = "Portanto, há \"pistas\" deixadas aqui, de fato.",
  ui_story_70000402_48_dialog_content = "\"Nada deixa nenhum rastro.\"",
  ui_story_70000402_49_dialog_content = "Vou pegar esta peça do quebra-cabeça, então.",
  ui_story_70000402_50_dialog_content = "Abandonado...",
  ui_story_70000402_51_dialog_content = "Não esqueça sua promessa.",
  ui_story_70000402_52_dialog_content = "Tsc...",
  ui_story_70000402_53_dialog_content = "Tá bom.",
  ui_story_70000402_54_dialog_content = "Tudo o que você precisa fazer é esperar pelo meu sinal e expulsar esses vermes.",
  ui_story_70000402_55_dialog_content = "Sua hesitação só levará ao seu fracasso.",
  ui_story_70000402_56_dialog_content = "Amador.",
  ui_story_70000402_57_dialog_content = "Que tolice...",
  ui_story_70000501_1_dialog_content = "Há vestígios de Luminatics ainda não devorados pelo Darkflow. É bem recente.",
  ui_story_70000501_2_dialog_content = "Rastros de Eclipses... Cerca de dez deles. Não é sinal de uma grande batalha, no entanto.",
  ui_story_70000501_3_dialog_content = "Deve ser um ataque furtivo para evitar uma batalha prolongada.",
  ui_story_70000501_4_dialog_content = "As táticas foram usadas lindamente. Até o terreno foi bem levado em consideração...",
  ui_story_70000501_5_dialog_content = "Bem feito. Você está finalmente se tornando um líder.",
  ui_story_70000501_6_dialog_content = "Mas... quanto tempo você consegue ficar vivo em um lugar como este?",
  ui_story_70000501_7_dialog_content = "<color=#e8d9bb>*resmunga*</color>",
  ui_story_70000501_8_dialog_content = "Encurralado?",
  ui_story_70000501_9_dialog_content = "É repetidamente enfatizado no Manual, mas eles ainda cometeram um erro de novato como este.",
  ui_story_70000501_10_dialog_content = "Eu deveria ensinar-lhes uma lição quando eles voltarem.",
  ui_story_70000501_11_dialog_content = "Vice, fuja para trás à sua direita!",
  ui_story_70000501_12_dialog_content = "Beleza!",
  ui_story_70000501_13_dialog_content = "Tenha um gostinho disso!",
  ui_story_70000501_14_dialog_content = "*Rugindo*",
  ui_story_70000501_15_dialog_content = "Nossos ataques não estão funcionando!",
  ui_story_70000501_16_dialog_content = "O Darkflow é muito forte aqui!",
  ui_story_70000501_17_dialog_content = "Vou tentar conter!",
  ui_story_70000501_18_option_content = "Controle forçado...",
  ui_story_70000501_19_dialog_content = "Ilu...",
  ui_story_70000501_20_dialog_content = "Ilu?",
  ui_story_70000501_21_dialog_content = "O que... está tentando dizer?",
  ui_story_70000501_22_dialog_content = "Ilu...mina...",
  ui_story_70000501_23_dialog_content = "Ilumina? A Federação Illumina?",
  ui_story_70000501_24_dialog_content = "Illumina!",
  ui_story_70000501_25_dialog_content = "Eca! Que ódio tão forte!",
  ui_story_70000501_26_dialog_content = "PlayerName?!",
  ui_story_70000501_27_dialog_content = "Estou bem!",
  ui_story_70000501_28_dialog_content = "Aquele Eclipsite é diferente... Parece abrigar um forte ódio pela Illumina!",
  ui_story_70000501_29_dialog_content = "Illu...mina! Rugido!",
  ui_story_70000501_30_dialog_content = "Ele nos atacou porque me viu usando o uniforme da Illumina?",
  ui_story_70000501_31_dialog_content = "PlayerName, vou mantê-lo ocupado enquanto você tenta sair!",
  ui_story_70000501_32_dialog_content = "E você!?",
  ui_story_70000501_33_dialog_content = "Não se preocupe comigo! Preocupe-se consigo mesmo!",
  ui_story_70000501_34_dialog_content = "Illumina!",
  ui_story_70000501_35_dialog_content = "Urgh...!",
  ui_story_70000501_36_dialog_content = "Vice!",
  ui_story_70000501_37_dialog_content = "Eu tenho que salvar Vice...!",
  ui_story_70000501_38_dialog_content = "Ei! Seu grande estúpido! Ei! Eu estou bem aqui!",
  ui_story_70000501_39_dialog_content = "*Rugindo*",
  ui_story_70000501_40_dialog_content = "PlayerName... Corra corra...!",
  ui_story_70000501_41_dialog_content = "Venha me pegar!",
  ui_story_70000501_42_dialog_content = "*Rugindo*",
  ui_story_70000501_43_dialog_content = "Tão rápido!",
  ui_story_70000501_44_dialog_content = "Argh!",
  ui_story_70000501_45_dialog_content = "PlayerName?!",
  ui_story_70000501_46_dialog_content = "Eu... vou morrer aqui...?",
  ui_story_70000501_47_dialog_content = "Qualquer um... Por favor... Salve-nos...",
  ui_story_70000501_48_dialog_content = "*Ruge*",
  ui_story_70000501_49_dialog_content = "<color=#e8d9bb>Clang!</color>",
  ui_story_70000501_50_dialog_content = "Um comandante nunca deve tirar os olhos do campo de batalha.",
  ui_story_70000501_51_dialog_content = "Isso...",
  ui_story_70000501_52_dialog_content = "Reinhardt!?",
  ui_story_70000501_53_dialog_content = "PlayerName o celestita, você tem potencial para ser um bom comandante, mas precisa de muito treinamento.",
  ui_story_70000501_54_dialog_content = "Vou pedir a Barton e Gram para te deixarem em forma!",
  ui_story_70000501_55_dialog_content = "Hã?!",
  ui_story_70000501_56_dialog_content = "Ilumina! Ilumina!",
  ui_story_70000501_57_dialog_content = "!",
  ui_story_70000501_58_dialog_content = "Grande Marechal... Reinhardt...!",
  ui_story_70000501_59_dialog_content = "Se você ainda pode se mover, encontre alguma cobertura.",
  ui_story_70000501_60_dialog_content = "Vice! Deste jeito!",
  ui_story_70000501_61_dialog_content = "*Rugido*",
  ui_story_70000501_62_dialog_content = "Então, realmente é você.",
  ui_story_70000501_63_dialog_content = "Mesmo que tenha transformado você em meio Eclipsite, ainda não mudou a forma como você luta.",
  ui_story_70000501_64_dialog_content = "Reinhardt está... falando com aquele Eclipsite?",
  ui_story_70000501_65_dialog_content = "Você esqueceu quem você é?",
  ui_story_70000501_66_dialog_content = "Meu velho amigo.\"",
  ui_story_70000501_67_dialog_content = "\"Velho amigo\"...?",
  ui_story_70000501_68_dialog_content = "Aaarrgh!",
  ui_story_70000501_69_dialog_content = "O Darkflow é forte aqui! Reinhardt está em desvantagem!",
  ui_story_70000501_70_dialog_content = "Teremos que tentar distrair aquele Eclipsite...",
  ui_story_70000501_71_dialog_content = "Ligação da mente!",
  ui_story_70000501_72_dialog_content = "*Ruge*",
  ui_story_70000501_73_dialog_content = "Ahhh!",
  ui_story_70000501_74_dialog_content = "<color=#e8d9bb>Estrondo...!</color>",
  ui_story_70000501_75_dialog_content = "Esse cara... está literalmente jogando sua vida fora!",
  ui_story_70000501_76_dialog_content = "Ele se importa que isso possa derrubar toda a Cidade Baixa!?",
  ui_story_70000501_77_dialog_content = "PlayerName, deixe isso comigo.",
  ui_story_70000501_78_dialog_content = "Tenha calma.",
  ui_story_70000501_78X1_dialog_content = "!",
  ui_story_70000501_78X2_dialog_content = "Reinhardt! Saia daí!",
  ui_story_70000501_78X3_dialog_content = "Grande marechal!",
  ui_story_70000501_78X4_dialog_content = "Não se preocupe. De verdade eu estou bem.",
  ui_story_70000501_78X5_dialog_content = "Há uma coisa... que eu tenho que tentar primeiro.",
  ui_story_70000501_79_dialog_content = "Mas...",
  ui_story_70000501_80_dialog_content = "PlayerName, apenas confie no Grande Marechal...",
  ui_story_70000501_81_dialog_content = "Reinhardt... Por que ela não está revidando?",
  ui_story_70000501_82_dialog_content = "Você ainda se lembra?",
  ui_story_70000501_83_dialog_content = "Uma vez lutamos lado a lado e repelimos inúmeros inimigos.",
  ui_story_70000501_84_dialog_content = "...",
  ui_story_70000501_85_dialog_content = "Cavamos as trincheiras, resistimos a ondas após ondas de ataques inimigos apenas para proteger nossa casa, Gannon.",
  ui_story_70000501_86_dialog_content = "Gan... não...",
  ui_story_70000501_87_dialog_content = "Sim. Gannon. Éramos seus filhos e fizemos votos em seu nome.",
  ui_story_70000501_88_dialog_content = "Você ainda se lembra do seu nome?",
  ui_story_70000501_89_dialog_content = "Argh...",
  ui_story_70000501_90_dialog_content = "Tu es... <color=#FFB400>Hélio</color>.",
  ui_story_70000501_91_dialog_content = "Ilu...mina...",
  ui_story_70000501_92_dialog_content = "Illumina!",
  ui_story_70000501_93_dialog_content = "*Rugindo*",
  ui_story_70000501_94_dialog_content = "Tsk... Não funcionou...?",
  ui_story_70000501_95_dialog_content = "Grande marechal! Atenção!",
  ui_story_70000501_96_dialog_content = "A estrutura aqui é muito frágil para suportar outro golpe!",
  ui_story_70000501_97_dialog_content = "Se isso continuar, toda a Cidade Baixa pode entrar em colapso!",
  ui_story_70000501_98_dialog_content = "*Rugido*",
  ui_story_70000501_99_dialog_content = "Tem que se olhar no espelho as vezes...",
  ui_story_70000501_100_dialog_content = "Lembre-se... Lembre-se de quem você realmente é.",
  ui_story_70000501_101_dialog_content = "Volte para a Illumina comigo. Eu vou encontrar uma maneira de tratá-lo e transformá-lo de volta!",
  ui_story_70000501_102_dialog_content = "*Rugindo*",
  ui_story_70000501_103_dialog_content = "*Tosse*",
  ui_story_70000501_104_dialog_content = "PlayerName, Por aqui!",
  ui_story_70000501_105_dialog_content = "<color=#e8d9bb>Ding...</color>",
  ui_story_70000501_106_dialog_content = "!!!",
  ui_story_70000501_107_dialog_content = "Aqui...",
  ui_story_70000501_108_dialog_content = "O som de um sino... De onde vem?",
  ui_story_70000501_109_dialog_content = "*Rugido*",
  ui_story_70000501_110_dialog_content = "Aquele Eclipsite de Alto Nível... Subiu o penhasco e decolou sem olhar para trás?",
  ui_story_70000501_111_dialog_content = "O sino controla Eclipsites?",
  ui_story_70000501_112_dialog_content = "Não.",
  ui_story_70000501_113_dialog_content = "Aquele sino só significa uma coisa: <color=#FFB400>\"Reforço chegou. Retirada.\"</color>",
  ui_story_70000501_114_dialog_content = "Aquele Eclipse... é alguém que você conhecia?",
  ui_story_70000501_115_dialog_content = "Mais do que conhecidos. Éramos irmãos de armas.",
  ui_story_70000501_116_dialog_content = "Alguém em quem eu pudesse confiar minha vida.",
  ui_story_70000501_117_dialog_content = "Ele foi MIA nesta Cidade Baixa durante a Guerra da Zona Cega.",
  ui_story_70000501_118_dialog_content = "Achei que ele tinha morrido... Achei que não...",
  ui_story_70000501_119_dialog_content = "Eu não acho que ele se transformou em um Eclipse em vez disso.",
  ui_story_70000501_120_dialog_content = "Virou um Eclipse? Isso quase soa como...",
  ui_story_70000501_121_dialog_content = "Estou realmente confuso sobre o que realmente aconteceu com ele agora.",
  ui_story_70000501_122_dialog_content = "<color=#e8d9bb>Estrondo...!</color>",
  ui_story_70000501_123_dialog_content = "Receio que este seja o fim desta Cidade Baixa.",
  ui_story_70000501_124_dialog_content = "Vamos sair daqui, e falaremos sobre isso no caminho de volta.",
  ui_story_70000501_125_dialog_content = "É o que faremos então.",
  ui_story_70000501_126_dialog_content = "Eu sei a saída. Me siga.",
  ui_story_70000601_1_dialog_content = "Uma vez eu tive dois amigos queridos. <color=#FFB400>Hélios</color>, Ele era um deles.",
  ui_story_70000601_1X1_dialog_content = "Eu acredito que o outro não é estranho para você também. Naquela época ela era conhecida como <color=#FFB400>Negador</color>.",
  ui_story_70000601_1X2_dialog_content = "Forsakin?",
  ui_story_70000601_1X3_dialog_content = "Sim. Esse é o nome dela agora.",
  ui_story_70000601_2_dialog_content = "Juntos, crescemos no Hospital Fundador da Illumina. Juntos nos juntamos ao exército e lutamos em batalhas.",
  ui_story_70000601_3_dialog_content = "Denier, Reinhardt, vocês sabem o que vão fazer?",
  ui_story_70000601_4_dialog_content = "Eu sou bastante talentoso de acordo com meu instrutor. Eu poderia me tornar um olheiro excepcional um dia.",
  ui_story_70000601_5_dialog_content = "Eu sou diferente de todos vocês. O laboratório é meu campo de batalha.",
  ui_story_70000601_6_dialog_content = "Parece que alguém se encaixa melhor para o papel de idiota do que eu.",
  ui_story_70000601_7_dialog_content = "Você ainda gosta de sarcasmo como sempre.",
  ui_story_70000601_8_dialog_content = "E você, Reinhardt?",
  ui_story_70000601_9_dialog_content = "Eu?",
  ui_story_70000601_10_dialog_content = "Ainda estou pensando nisso. Mas talvez eu comece pequeno.",
  ui_story_70000601_11_dialog_content = "Vou começar sendo o Grande Marechal da Illumina.",
  ui_story_70000601_12_dialog_content = "Logo depois, nossa conquista foi finalmente reconhecida pela liderança e pelo comitê da Illumina.",
  ui_story_70000601_13_dialog_content = "E todos nos tornamos candidatos ao próximo Grande Marechal.",
  ui_story_70000601_14_dialog_content = "Vocês são os melhores soldados da Illumina. O futuro da Illumina está em seus ombros.",
  ui_story_70000601_15_dialog_content = "E você está prestes a passar pelo treinamento mais brutal e intenso de toda a Illumina.",
  ui_story_70000601_16_dialog_content = "Todos os dias, todas as horas, alguém será eliminado.",
  ui_story_70000601_17_dialog_content = "O vencedor no final se tornará o Grande Marechal da Illumina.",
  ui_story_70000601_18_dialog_content = "Você tem a confiança?",
  ui_story_70000601_19_dialog_content = "Para ser o mais forte do seu grupo!?",
  ui_story_70000601_20_dialog_content = "Sim.",
  ui_story_70000601_21_dialog_content = "Sim!",
  ui_story_70000601_22_dialog_content = "SIM!",
  ui_story_70000601_23_dialog_content = "<color=#FFB400>O Comitê</color>? O que é aquilo?",
  ui_story_70000601_24_dialog_content = "Huh? Você não ouviu falar do Comitê, PlayerName?",
  ui_story_70000601_25_dialog_content = "Nada mesmo!",
  ui_story_70000601_26_dialog_content = "A agência que administra todos os assuntos da Illumina ao lado do Grande Marechal Reinhardt!",
  ui_story_70000601_27_dialog_content = "Bem, todo mundo fala sobre o Grande Marechal...",
  ui_story_70000601_28_dialog_content = "Mas ninguém realmente diz nada sobre algum comitê.",
  ui_story_70000601_29_dialog_content = "*Tosse*",
  ui_story_70000601_30_dialog_content = "(Ah, droga! Esqueci que o Grande Marechal está bem aqui!)",
  ui_story_70000601_31_dialog_content = "O Comitê é curto para <color=#FFB400>O Comitê de Assuntos Militares e Políticos da Federação Illumina</color>.",
  ui_story_70000601_32_dialog_content = "Eles são um bando de antiguidades desatualizadas que gostam de microgerenciar tudo relacionado à Illumina.",
  ui_story_70000601_33_dialog_content = "Mas eles sabem como manter um perfil baixo, então é normal que as pessoas raramente saibam sobre eles.",
  ui_story_70000601_34_dialog_content = "(Graças a Deus a própria Reinhardt vem em meu socorro...)",
  ui_story_70000601_35_dialog_content = "Huh? Espere... Isso significa...",
  ui_story_70000601_36_dialog_content = "O Comitê decide quem será o Grande Marechal?",
  ui_story_70000601_37_dialog_content = "Hã?",
  ui_story_70000601_38_dialog_content = "O Grande Marechal não deveria ser alguém altamente condecorado?",
  ui_story_70000601_39_dialog_content = "Pelo menos o livro dos meus tempos de escola dizia isso...",
  ui_story_70000601_40_dialog_content = "Isso é apenas uma parte.",
  ui_story_70000601_41_dialog_content = "É uma coisa difícil unir as pessoas.",
  ui_story_70000601_41X_dialog_content = "A Federação Illumina é composta por muitas Cidades Baixas. A reputação por si só não pode conquistá-los.",
  ui_story_70000601_42_dialog_content = "Se a reputação militar por si só determina quem será o Grande Marechal... E se eles não tiverem nenhuma habilidade de liderança?",
  ui_story_70000601_43_dialog_content = "E se fosse um sujeito grosseiro que se engajasse em uma agressão militar desenfreadamente?",
  ui_story_70000601_44_dialog_content = "Devemos segui-los e colocar todos os recursos da Illumina na construção de muros e baterias de armas?",
  ui_story_70000601_44X_dialog_content = "E então esperar para murchar e morrer?",
  ui_story_70000601_45_dialog_content = "Bom...",
  ui_story_70000601_46_dialog_content = "Estamos aqui.",
  ui_story_70000601_47_dialog_content = "Estamos... completamente cercados por ruínas aqui!",
  ui_story_70000601_48_dialog_content = "Não entrar em pânico. Lembro que a entrada é...",
  ui_story_70000601_49_dialog_content = "Uma passagem escondida, aqui!?",
  ui_story_70000601_50_dialog_content = "Para ser preciso, é um túnel de fuga.",
  ui_story_70000601_51_dialog_content = "Os túneis de fuga da Cidade Baixa foram reforçados provavelmente devido a terremotos frequentes.",
  ui_story_70000601_52_dialog_content = "Uma vez eu liderei homens para quebrar um cerco aqui.",
  ui_story_70000601_53_dialog_content = "Pode entrar.",
  ui_story_70000601_54_dialog_content = "Está tão quieto...",
  ui_story_70000601_55_dialog_content = "Vice, me dê sua mão.",
  ui_story_70000601_56_dialog_content = "Obrigada, PlayerName.",
  ui_story_70000601_57_dialog_content = "Eu estou bem com isso.",
  ui_story_70000601_58_dialog_content = "Você estava sob ataque feroz. É melhor você economizar sua força.",
  ui_story_70000601_59_dialog_content = "Você sabe... Mesmo que vocês dois sejam extremamente capazes, vocês devem conhecer seus limites.",
  ui_story_70000601_60_dialog_content = "Só se você seguir o Manual e voltar à superfície quando o tempo acabar...",
  ui_story_70000601_60X_dialog_content = "Você teria evitado tudo isso.",
  ui_story_70000601_61_dialog_content = "Você sabia sobre o Manual? Pode ser isso...",
  ui_story_70000601_62_dialog_content = "Eu escrevi, claro. E também sei que pediu ao Philyshy para investigar a Cidade Baixa 80.",
  ui_story_70000601_63_dialog_content = "!!!",
  ui_story_70000601_64_dialog_content = "Por que você está me encarando?",
  ui_story_70000601_65_dialog_content = "Eu sou o único em toda a Federação Illumina que lutou na Guerra da Zona Cega e voltou vivo.",
  ui_story_70000601_66_dialog_content = "Este Undercity 80 era onde eu estava estacionado.",
  ui_story_70000601_67_dialog_content = "Como não saberia se alguém está investigando esta Cidade Baixa?",
  ui_story_70000601_68_dialog_content = "Então por que você está aqui...?",
  ui_story_70000601_69_dialog_content = "Achei que você estaria em Gannon.",
  ui_story_70000601_70_dialog_content = "Eu permiti que você explorasse esta região porque confio em suas habilidades.",
  ui_story_70000601_71_dialog_content = "Mas isso não significa que eu não pense em possíveis acidentes. Nem vou deixar nenhum de vocês em perigo.",
  ui_story_70000601_72_dialog_content = "É dever de um Grande Marechal proteger todos na Illumina.",
  ui_story_70000601_73_dialog_content = "O que inclui você, um aliado da Illumina, PlayerName.",
  ui_story_70000601_74_dialog_content = "Ui... Certo...",
  ui_story_70000601_75_dialog_content = "Assim que soube que você ia investigar a Cidade Baixa 80...",
  ui_story_70000601_75X_dialog_content = "Imediatamente levei os homens a esperar na Linha Segura na fronteira da Zona Cega.",
  ui_story_70000601_76_dialog_content = "Eu queria que fosse um teste para sua força.",
  ui_story_70000601_77_dialog_content = "Se você completasse sua missão sem problemas, eu fingiria que nada aconteceu.",
  ui_story_70000601_78_dialog_content = "Mas, para minha surpresa, você correu um perigo real.",
  ui_story_70000601_79_dialog_content = "Tudo estava indo bem, até que encontramos um inimigo poderoso que não esperávamos no subsolo...",
  ui_story_70000601_79X_dialog_content = "As consequências seriam horríveis demais para contemplar se eu não tivesse sentido a presença de Helios e corrido para resgatá-lo.",
  ui_story_70000601_80_dialog_content = "Confie na informação, mas esteja preparado para mais.",
  ui_story_70000601_81_dialog_content = "Você faria bem em se lembrar disso se quiser ser um bom comandante.",
  ui_story_70000601_82_dialog_content = "Entendo...",
  ui_story_70000601_83_dialog_content = "Você não retornou no tempo previsto. Eu tive que assumir o pior.",
  ui_story_70000601_84_dialog_content = "Inicialmente, pensei que fossem apenas alguns Eclipsites. Eu realmente não esperava que fosse ele...",
  ui_story_70000601_85_dialog_content = "Oh, como o destino tem um senso de humor distorcido.",
  ui_story_70000601_86_dialog_content = "...",
  ui_story_70000601_87_dialog_content = "Esqueça isso.",
  ui_story_70000601_88_dialog_content = "Abra este portão e estaremos no túnel de fuga.",
  ui_story_70000601_89_dialog_content = "Siga-o para cima para chegar à superfície.",
  ui_story_70000601_90_dialog_content = "<color=#e8d9bb>Creee...</color>",
  ui_story_70000601_91_dialog_content = "Realmente não foi danificado por terremotos.",
  ui_story_70000601_92_dialog_content = "Posso até sentir uma brisa fresca.",
  ui_story_70000601_93_dialog_content = "Isso significa que leva para o exterior!",
  ui_story_70000601_94_dialog_content = "Tranquilo. O túnel amplifica sua voz.",
  ui_story_70000601_95_dialog_content = "Pode haver eclipsites à espreita no túnel.",
  ui_story_70000601_96_dialog_content = "*Rugindo*",
  ui_story_70000601_97_dialog_content = "Falando no diabo...",
  ui_story_70000601_98_dialog_content = "D-Desculpa!",
  ui_story_70000601_99_dialog_content = "Prepare-se para lutar, Celestita. Mostre-me como você é bom como comandante!",
  ui_story_70000602_1_dialog_content = "Por que...",
  ui_story_70000602_2_dialog_content = "Estamos subindo, mas, de alguma forma, o Darkflow só fica mais forte... Por quê?",
  ui_story_70000602_3_dialog_content = "De fato...",
  ui_story_70000602_4_dialog_content = "Até agora, eu consegui lidar com alguns Eclipses, mas agora, mesmo um ou dois é mais do que posso lidar...",
  ui_story_70000602_5_dialog_content = "Anotei o motivo no Manual. Você ainda se lembra por quê?",
  ui_story_70000602_6_dialog_content = "Exaustão física?",
  ui_story_70000602_7_dialog_content = "Não.",
  ui_story_70000602_8_dialog_content = "Essa é uma razão, com certeza, mas não a principal.",
  ui_story_70000602_9_dialog_content = "Poderia ser... hora?",
  ui_story_70000602_10_dialog_content = "Sim.",
  ui_story_70000602_11_dialog_content = "Porque já é noite?",
  ui_story_70000602_12_dialog_content = "Bom trabalho.",
  ui_story_70000602_13_dialog_content = "Parece que você leu o Manual.",
  ui_story_70000602_14_dialog_content = "Tentei avisar em várias ocasiões para manter o controle do tempo para evitar o pior cenário, no qual estamos agora.",
  ui_story_70000602_15_dialog_content = "Mas mesmo que eu lhe contasse, você não se importaria, não é?",
  ui_story_70000602_16_dialog_content = "Afinal, Soroz também é um amigo e uma família importante para você.",
  ui_story_70000602_17_dialog_content = "Você vê através de mim...",
  ui_story_70000602_18_dialog_content = "É você que é fácil de ler.",
  ui_story_70000602_19_dialog_content = "Isso, e Vice continuou falando sobre você sem parar.",
  ui_story_70000602_20_dialog_content = "Mesmo que eu não quisesse ouvir, eu não poderia bloquear todos eles.",
  ui_story_70000602_21_dialog_content = "Grande Marechal Reinhardt!",
  ui_story_70000602_22_dialog_content = "Mas, tenho outra pergunta.",
  ui_story_70000602_23_dialog_content = "Como é que você pode sentir Helios?",
  ui_story_70000602_24_dialog_content = "Provavelmente um vínculo compartilhado entre nós.",
  ui_story_70000602_25_dialog_content = "Fomos muito próximos crescendo.",
  ui_story_70000602_26_dialog_content = "E você sempre pode dizer quando um membro da família está com problemas.",
  ui_story_70000602_27_dialog_content = "Esta Cidade Baixa está isolada há muito tempo. Tanto o Darkflow quanto a distância cortaram essa conexão entre nós.",
  ui_story_70000602_28_dialog_content = "Mas você o abriu. Você até acordou Helios, que está preso lá embaixo há anos.",
  ui_story_70000602_29_dialog_content = "O vínculo entre nós se renova...",
  ui_story_70000602_30_dialog_content = "Reinhardt também tem a habilidade psíquica?",
  ui_story_70000602_31_dialog_content = "Eu adoraria isso.",
  ui_story_70000602_32_dialog_content = "Isso tornará a distribuição de ordens muito mais fácil.",
  ui_story_70000602_33_dialog_content = "Costumava haver algum tipo de vínculo entre nós, camaradas.",
  ui_story_70000602_34_dialog_content = "Se partiu…",
  ui_story_70000602_34X_dialog_content = "Mas sua operação reacendeu nosso vínculo e nos uniu mais uma vez.",
  ui_story_70000602_35_dialog_content = "Pessoalmente, eu atribuiria isso a uma certa experiência compartilhada...",
  ui_story_70000602_36_dialog_content = "A experiência de passar pela vida e pela morte juntos.",
  ui_story_70000602_36X1_dialog_content = "Essas são as memórias que nós três compartilhamos.",
  ui_story_70000602_36X2_dialog_content = "O que aconteceu com você?",
  ui_story_70000602_36X3_dialog_content = "Uma batalha sangrenta. Mas para eles, era mais como a traição final.",
  ui_story_70000602_36X4_dialog_content = "Eles foram traídos por Illumina e por mim... Nós os abandonamos.",
  ui_story_70000602_36X5_dialog_content = "Abandono?",
  ui_story_70000602_36X6_dialog_content = "Mas Reinhardt... não acredito que você deixaria ninguém para trás!",
  ui_story_70000602_37_dialog_content = "Longa história. Por favor, permita-me organizar meus pensamentos.",
  ui_story_70000602_38_dialog_content = "Receio que seja esta traição que transformou Helios neste monstro.",
  ui_story_70000602_39_dialog_content = "E Denier… Não, ela adotou um novo nome agora…",
  ui_story_70000602_40_dialog_content = "<color=#FFB400>Forsakin.</color>",
  ui_story_70000602_41_dialog_content = "Abandonado...",
  ui_story_70000602_42_dialog_content = "A decepção causada por esse abandono levou à sua deserção posterior da Illumina?",
  ui_story_70000602_43_dialog_content = "Não sei.",
  ui_story_70000602_44_dialog_content = "Mas isso não a justifica usar humanos como cobaias e prejudicar o povo de Illumina.",
  ui_story_70000602_45_dialog_content = "Eu sei que ela guarda um profundo rancor por não ter sido resgatada.",
  ui_story_70000602_46_dialog_content = "Era minha culpa ser fraco e fraco. Eu deveria ser o único a suportar o ódio dela.",
  ui_story_70000602_47_dialog_content = "Mas, ainda assim, ela descontava nos outros...",
  ui_story_70000602_48_dialog_content = "Schummer, eu e tantas outras pessoas inocentes...",
  ui_story_70000602_49_dialog_content = "Sim. Esse é o crime dela.",
  ui_story_70000602_50_dialog_content = "Um crime pelo qual ela precisa responder.",
  ui_story_70000602_51_dialog_content = "Concordo com você. Essas duas coisas não são a mesma coisa.",
  ui_story_70000602_51X1_dialog_content = "Às vezes não consigo deixar de pensar...",
  ui_story_70000602_51X2_dialog_content = "Se eles não fizessem parte do plano de treinamento do comitê e não lutassem naquela batalha horrível...",
  ui_story_70000602_51X3_dialog_content = "Eles estariam vivendo uma vida melhor agora como humanos, não como Eclipsitas?",
  ui_story_70000602_52_dialog_content = "Que tipo de treinamento foi esse?",
  ui_story_70000602_52X1_dialog_content = "Não soa como algo que um homem comum poderia suportar.",
  ui_story_70000602_53_dialog_content = "O projeto de desenvolvimento do Comitê não é qualquer <color=#FFB400>Treinamento</color>.",
  ui_story_70000602_54_dialog_content = "Vocês três... passaram pelo treinamento do Comitê?",
  ui_story_70000602_55_dialog_content = "O projeto de desenvolvimento do Comitê não é um treinamento qualquer.",
  ui_story_70000602_56_dialog_content = "Perder a vida é um risco possível.",
  ui_story_70000602_57_dialog_content = "Isso soa duro.",
  ui_story_70000602_58_dialog_content = "A Illumina tem que... escolher seu Grande Marechal dessa maneira?",
  ui_story_70000602_59_dialog_content = "Para o povo de Illumina, o Grande Marechal é uma luz na escuridão.",
  ui_story_70000602_60_dialog_content = "Apenas a chama mais brilhante pode iluminar o canto mais escuro, dando esperança a todo homem desesperado.",
  ui_story_70000602_61_dialog_content = "A esperança é o que une as pessoas da Illumina e as motiva a seguir em frente neste mundo difícil.",
  ui_story_70000602_62_dialog_content = "Mas se você quisesse esperar que um ser supremo nascesse neste mundo, as chances de ver um em sua vida são quase nulas.",
  ui_story_70000602_63_dialog_content = "Para isso, quero me tornar o Grande Marechal da Illumina, não importa quanto sofrimento e dor eu tenha que passar.",
  ui_story_70000602_63X_dialog_content = "O ser mais poderoso da terra.",
  ui_story_70000602_64_dialog_content = "...",
  ui_story_70000602_65_dialog_content = "Garoto, não me olhe assim.",
  ui_story_70000602_66_dialog_content = "Como é esse ditado?",
  ui_story_70000602_67_dialog_content = "\"Inquieta está a cabeça que usa a coroa.\"",
  ui_story_70000602_68_dialog_content = "Não se preocupe. Mesmo que o céu caísse, o mais alto de nós o manteria acima de suas cabeças.",
  ui_story_70000602_69_dialog_content = "A mesma coisa se aplica aqui. Quando a Illumina está com problemas, o Grande Marechal está lá.",
  ui_story_70000602_70_dialog_content = "Incluindo você.",
  ui_story_70000602_71_dialog_content = "Estamos aqui.",
  ui_story_70000701_1_dialog_content = "Estes parecem ser os níveis superiores da Cidade Baixa, semelhantes à área de onde entramos.",
  ui_story_70000701_2_dialog_content = "Mas o túnel está mexendo com meu senso de direção. Eu realmente não sei o meu caminho agora...",
  ui_story_70000701_3_dialog_content = "PlayerName, não é o mesmo lugar onde entramos.",
  ui_story_70000701_4_dialog_content = "Na verdade, estamos em um local completamente diferente.",
  ui_story_70000701_5_dialog_content = "O quê?!",
  ui_story_70000701_6_dialog_content = "É difícil dizer? Você pode ver isso apenas olhando para o layout da tubulação no teto, também os poços de ventilação são...",
  ui_story_70000701_7_dialog_content = "(Puxa... Lá vai o Vice de novo...)",
  ui_story_70000701_8_dialog_content = "Ugh... Eu tenho uma pergunta!",
  ui_story_70000701_9_dialog_content = "Seria a curiosidade uma das características distintivas dos celestitas?",
  ui_story_70000701_10_dialog_content = "Eu sinto Muito. Prometo que este é o último!",
  ui_story_70000701_11_dialog_content = "Está tudo bem. Não é ruim ter.",
  ui_story_70000701_12_dialog_content = "O Eclipsite de alto nível que fugiu... era um amigo seu da guerra, não é, Reinhardt?",
  ui_story_70000701_13_dialog_content = "Como ele ficou assim?",
  ui_story_70000701_14_dialog_content = "Isso também foi feito por Forsakin? Mas eu não notei nenhum traço da semente nele.",
  ui_story_70000701_15_dialog_content = "A resposta para sua pergunta é: não sei.",
  ui_story_70000701_16_dialog_content = "Foi uma guerra brutal. Todos nós acreditávamos que ele estava morto.",
  ui_story_70000701_17_dialog_content = "O que aconteceu... naquela época?",
  ui_story_70000701_18_dialog_content = "...",
  ui_story_70000701_19_dialog_content = "Naquela época, todos os candidatos ao Grande Marechal foram colocados em uma equipe especializada.",
  ui_story_70000701_20_dialog_content = "Onze anos atrás, recebemos uma ordem do comitê para recuperar os materiais científicos perdidos da Cidade Baixa 80, há muito abandonada.",
  ui_story_70000701_21_dialog_content = "Nossa inteligência sugeriu que, apesar de Undercity 80 estar no controle dos Eclipsites, eles não eram grandes em número.",
  ui_story_70000701_22_dialog_content = "Então tomamos a mesma decisão que a sua, de viajar leve.",
  ui_story_70000701_22X_dialog_content = "Planejamos entrar na Cidade Baixa e recuperar o alvo durante as curtas horas do dia.",
  ui_story_70000701_23_dialog_content = "No entanto... A inteligência que tínhamos estava longe.",
  ui_story_70000701_24_dialog_content = "De jeito nenhum! Há apenas muitos deles!",
  ui_story_70000701_25_dialog_content = "Solicitando suporte! Solicitando⁠—",
  ui_story_70000701_26_dialog_content = "Os Eclipsites na Cidade Baixa estavam embalados como sardinhas em lata. Não importa quantos matamos, havia mais deles.",
  ui_story_70000701_27_dialog_content = "20% do corpo foi morto antes de chegarmos ao Armazém alvo.",
  ui_story_70000701_28_dialog_content = "Então, as fortificações e equipamentos quebrados que vimos no armazém eram...",
  ui_story_70000701_29_dialog_content = "Restos de nossos valentes soldados.",
  ui_story_70000701_30_dialog_content = "...",
  ui_story_70000701_31_dialog_content = "E quando recuperamos o item alvo e estávamos prontos para evacuar...",
  ui_story_70000701_32_dialog_content = "A noite caiu.",
  ui_story_70000701_33_dialog_content = "Muitos Eclipsites poderosos atacaram a Cidade Baixa 80 como se fossem atraídos por algo...",
  ui_story_70000701_34_dialog_content = "Igual ao que está acontecendo agora.",
  ui_story_70000701_35_dialog_content = "*Rugido*",
  ui_story_70000701_36_dialog_content = "Vice, PlayerName, prepare-se para lutar!",
  ui_story_70000702_1_dialog_content = "Argh...",
  ui_story_70000702_2_dialog_content = "Batalha terminada!",
  ui_story_70000702_3_dialog_content = "Sem hostis na área imediata... por enquanto.",
  ui_story_70000702_4_dialog_content = "Vice!",
  ui_story_70000702_5_dialog_content = "Ugh... Meu corpo parece... tão pesado...",
  ui_story_70000702_6_dialog_content = "É meia-noite, quando a concentração de Darkflow está em seu ponto mais alto.",
  ui_story_70000702_7_dialog_content = "Vocês dois estão indo bem. Da última vez, muitos desmaiaram.",
  ui_story_70000702_8_dialog_content = "E tivemos que lutar contra centenas, milhares de Eclipsites...",
  ui_story_70000702_9_dialog_content = "<color=#e8d9bb>Durante a Guerra da Zona Cega</color>",
  ui_story_70000702_10_dialog_content = "Cuidado com as 3 horas!",
  ui_story_70000702_11_dialog_content = "*Rugindo*",
  ui_story_70000702_12_dialog_content = "<color=#e8d9bb>Dadá...</color>",
  ui_story_70000702_13_dialog_content = "Alvo para baixo!",
  ui_story_70000702_14_dialog_content = "Eclipsites de alto nível no seu 10!",
  ui_story_70000702_15_dialog_content = "1, 2, 3... São muitos!",
  ui_story_70000702_16_dialog_content = "Precisamos de apoio de fogo imediato!",
  ui_story_70000702_17_dialog_content = "Eu não vou deixar você passar por aqui!",
  ui_story_70000702_18_dialog_content = "Graaoooooohhh!!",
  ui_story_70000702_19_dialog_content = "Não disse que encontraríamos tantos Eclipsites na intel!",
  ui_story_70000702_20_dialog_content = "Até as informações do Comitê podem estar erradas...?",
  ui_story_70000702_21_dialog_content = "É algo que todos queremos evitar, mas o que está feito está feito. Tudo o que podemos fazer agora é tentar sair daqui com os dados!",
  ui_story_70000702_22_dialog_content = "Você sabe o que aconteceu em seguida, não sabe?",
  ui_story_70000702_23_dialog_content = "O Darkflow na Cidade Baixa cortou nossas comunicações, então eu fui encarregado de romper para chegar.",
  ui_story_70000702_24_dialog_content = "Quando voltei para o outro lado da Linha Segura... a Cidade Baixa submergiu e desmoronou.",
  ui_story_70000702_25_dialog_content = "Nessa situação... indo para a Cidade Baixa cercada, lutando enquanto cavava para salvar nosso povo...",
  ui_story_70000702_26_dialog_content = "A pequena taxa de sucesso e as grandes perdas estimadas...",
  ui_story_70000702_27_dialog_content = "No final, não fazia sentido aprovar uma missão de resgate como aquela depois de muita consideração.",
  ui_story_70000702_28_option_content = "Como você pode fazer aquilo?",
  ui_story_70000702_29_dialog_content = "Eles eram soldados da Illumina... pessoas vivas...",
  ui_story_70000702_30_dialog_content = "Por quê? Por que eles foram deixados para morrer?",
  ui_story_70000702_31_dialog_content = "...",
  ui_story_70000702_32_dialog_content = "Essa pergunta me incomodou por muito tempo. É compreensível que você não possa vê-lo.",
  ui_story_70000702_33_dialog_content = "Nossa equipe que foi enviada para a Cidade Baixa era a equipe de elite mais bem equipada de toda a Illumina.",
  ui_story_70000702_34_dialog_content = "Mesmo que não tenhamos conseguido a vitória na Cidade Baixa 80, então quais são as chances das tropas regulares que guardam a Linha Segura?",
  ui_story_70000702_35_dialog_content = "Os presos no subsolo eram meus irmãos e irmãs. Eu não queria perdê-los.",
  ui_story_70000702_36_dialog_content = "Mas os soldados regulares da Illumina não eram meus irmãos e irmãs?",
  ui_story_70000702_37_dialog_content = "Se salvar um significa custar a vida de dez... Você faria essa troca?",
  ui_story_70000702_38_dialog_content = "Eu...",
  ui_story_70000702_39_dialog_content = "Tenho certeza que você pode entender... Cada um de nós tem uma família, amigos e pessoas importantes para nós.",
  ui_story_70000702_40_dialog_content = "Darkflow só pode me atrapalhar, mas pode ser letal para uma pessoa normal.",
  ui_story_70000702_41_dialog_content = "Além disso, há a questão dos infinitos Eclipsites...",
  ui_story_70000702_42_dialog_content = "Se mesmo nós não conseguíamos sair dessa situação perigosa, que chances eles tinham?",
  ui_story_70000702_43_option_content = "Entendo...",
  ui_story_70000702_44_dialog_content = "Só se você pudesse entender.",
  ui_story_70000702_45_option_content = "Eu ainda não concordo.",
  ui_story_70000702_46_dialog_content = "Não importa o que aconteça, eu nunca vou desistir dos meus amigos.",
  ui_story_70000702_47_dialog_content = "Nunca.",
  ui_story_70000702_48_dialog_content = "Não preciso que você concorde. Eu só preciso que você entenda...",
  ui_story_70000702_49_dialog_content = "Como o Grande Marechal da Illumina, minha decisão deve ser do melhor interesse de todos na Illumina.",
  ui_story_70000702_50_dialog_content = "...",
  ui_story_70000702_51_dialog_content = "(Eu... conduzi esta conversa por um caminho sombrio...?)",
  ui_story_70000702_52_dialog_content = "Bem... Esta rota é realmente muito suave...",
  ui_story_70000702_53_dialog_content = "Claro que sim.",
  ui_story_70000702_54_dialog_content = "Foi pavimentado com intermináveis sacrifícios e sangue.",
  ui_story_70000702_55_dialog_content = "E só consegui escapar pisando em seus sacrifícios.",
  ui_story_70000702_56_dialog_content = "<color=#e8d9bb>Ding...</color>",
  ui_story_70000702_57_dialog_content = "PlayerName, você ouviu isso?",
  ui_story_70000702_58_dialog_content = "O som daquele sino novamente!",
  ui_story_70000702_59_dialog_content = "Eu ouvi! Está perto!",
  ui_story_70000702_60_dialog_content = "O Eclipsite de Alto Nível que fugiu imediatamente após ouvir o sino...",
  ui_story_70000702_61_dialog_content = "Ainda pode estar por aqui?",
  ui_story_70000702_62_dialog_content = "Droga... Só que se o Darkflow fosse menos forte, eu poderia ter usado minha habilidade psíquica...",
  ui_story_70000702_63_dialog_content = "Está bem. Tenho certeza que ele está por aqui em algum lugar.",
  ui_story_70000702_64_dialog_content = "Como você pode ter certeza, Grande Marechal Reinhardt?",
  ui_story_70000702_65_dialog_content = "Antes da minha tentativa de fuga, fiz uma promessa a eles.",
  ui_story_70000702_66_dialog_content = "Vou sinalizar sua evacuação assim que voltar com os reforços.",
  ui_story_70000702_67_dialog_content = "Como sempre, a evacuação será sinalizada pelo som da campainha.",
  ui_story_70000702_68_dialog_content = "Tudo bem, eu entendo.",
  ui_story_70000702_69_dialog_content = "Não se preocupe. Podemos manter nossa posição.",
  ui_story_70000702_70_dialog_content = "Eu esperaria pelo seu sinal mesmo que eu me transformasse em um Eclipsite!",
  ui_story_70000702_71_dialog_content = "Certo...",
  ui_story_70000702_72_dialog_content = "Assim que ouvirmos o som do sino, vamos atacar!",
  ui_story_70000702_73_dialog_content = "Que ironia que sua piada se tornou real no final...",
  ui_story_70000702_74_dialog_content = "Sempre amaldiçoando as coisas...",
  ui_story_70000702_75_dialog_content = "Então... Ele ainda se lembra dessa promessa?",
  ui_story_70000702_76_dialog_content = "Ou talvez \"ele\" tenha perdido completamente a cabeça e esteja se movendo apenas por instinto.",
  ui_story_70000702_77_dialog_content = "...",
  ui_story_70000702_78_dialog_content = "...",
  ui_story_70000702_79_dialog_content = "Prepare-se para uma batalha. \"Ele\" pode estar esperando por nós.",
  ui_story_70000702_80_dialog_content = "Só por favor me dê uma última chance...",
  ui_story_70000702_81_dialog_content = "Não posso desperdiçar outra chance de salvá-lo... Não depois da última vez.",
  ui_story_70000801_1_dialog_content = "<color=#e8d9bb>Ding...</color>",
  ui_story_70000801_2_dialog_content = "Estamos finalmente fora!",
  ui_story_70000801_3_dialog_content = "Mas... O Darkflow não é mais fácil de manusear...",
  ui_story_70000801_4_dialog_content = "Não exagere, PlayerName.",
  ui_story_70000801_5_dialog_content = "Deixe-me ajudá-lo.",
  ui_story_70000801_6_dialog_content = "<color=#e8d9bb>Ding...</color>",
  ui_story_70000801_7_dialog_content = "O sino... Está perto...",
  ui_story_70000801_8_dialog_content = "Lá!",
  ui_story_70000801_9_dialog_content = "Argh...",
  ui_story_70000801_10_dialog_content = "Ele está procurando a fonte do anel?",
  ui_story_70000801_11_dialog_content = "Esses são todos os Eclipsites ao redor dele?",
  ui_story_70000801_12_dialog_content = "Vamos mesmo tentar chegar perto assim?",
  ui_story_70000801_13_dialog_content = "Este é um pedido pessoal. Por favor, dê-me apenas cinco minutos.",
  ui_story_70000801_14_dialog_content = "Esta será minha última tentativa de salvá-lo.",
  ui_story_70000801_15_dialog_content = "Vamos evacuar imediatamente assim que os cinco minutos acabarem.",
  ui_story_70000801_16_dialog_content = "Eu ajudo!",
  ui_story_70000801_17_dialog_content = "E você, PlayerName?",
  ui_story_70000801_18_dialog_content = "Conte comigo.",
  ui_story_70000801_19_dialog_content = "Desta vez, vamos salvá-lo!",
  ui_story_70000801_20_dialog_content = "Bem, é melhor abrir os olhos e assistir.",
  ui_story_70000801_21_dialog_content = "Testemunhe a vontade de Illumina.",
  ui_story_70000801_22_dialog_content = "O mesmo da última vez. Vamos nos separar.",
  ui_story_70000801_23_dialog_content = "Vice, vamos circular pelos Eclipsites para o lado oposto.",
  ui_story_70000801_24_dialog_content = "Claro.",
  ui_story_70000801_25_dialog_content = "Acho que estamos em posição agora.",
  ui_story_70000801_26_dialog_content = "Bom. Reinhardt também está pronto.",
  ui_story_70000801_27_dialog_content = "Bom...",
  ui_story_70000801_28_dialog_content = "Ei, seus Eclipses estúpidos! Venha me pegar!",
  ui_story_70000801_29_dialog_content = "Rugido...!",
  ui_story_70000801_30_dialog_content = "*Rugido*",
  ui_story_70000801_31_dialog_content = "Uhh?",
  ui_story_70000801_32_dialog_content = "Tantos!?",
  ui_story_70000801_33_dialog_content = "Espere, PlayerName!",
  ui_story_70000802_1_dialog_content = "Você esqueceu?",
  ui_story_70000802_2_dialog_content = "O sonho da Illumina?",
  ui_story_70000802_3_dialog_content = "A vontade da Illumina?",
  ui_story_70000802_4_dialog_content = "A glória da Illumina?",
  ui_story_70000802_5_dialog_content = "As memórias da Illumina...",
  ui_story_70000802_6_dialog_content = "Esqueceu-se de todos eles!?",
  ui_story_70000802_7_dialog_content = "*Rugindo*",
  ui_story_70000802_8_dialog_content = "Diga-me...",
  ui_story_70000802_9_dialog_content = "Por que você abandonou a luz e abraçou a escuridão?",
  ui_story_70000802_10_dialog_content = "Para sua sobrevivência?",
  ui_story_70000802_11_dialog_content = "Ou você está fazendo o lance de outra pessoa?",
  ui_story_70000802_12_dialog_content = "Me dê...",
  ui_story_70000802_13_dialog_content = "<size=45>Sua resposta!</size>",
  ui_story_70000802_14_dialog_content = "*Rugindo*",
  ui_story_70000802_15_dialog_content = "<color=#e8d9bb>Ding...</color>",
  ui_story_70000802_16_dialog_content = "...!",
  ui_story_70000802_17_dialog_content = "São os sinos de novo!",
  ui_story_70000802_18_dialog_content = "Está perto... muito perto! Bem ali!",
  ui_story_70000802_19_dialog_content = "<color=#e8d9bb>Ding...</color>",
  ui_story_70000802_20_dialog_content = "É que...",
  ui_story_70000802_21_dialog_content = "Abandonado!?",
  ui_story_70000802_22_dialog_content = "...",
  ui_story_70000802_23_dialog_content = "Muito tempo sem ver. Você está ficando tagarela.",
  ui_story_70000802_24_dialog_content = "Reinhardt.",
  ui_story_70000802_25_dialog_content = "Negador... Não. Renegado.",
  ui_story_70000802_26_dialog_content = "Você também tem algo a ver com o que aconteceu com Helios?",
  ui_story_70000802_27_dialog_content = "Eu não sei nada mais do que você sobre este assunto.",
  ui_story_70000802_28_dialog_content = "Mas, inegavelmente, é uma boa cobaia.",
  ui_story_70000802_29_dialog_content = "Então como ele se tornou isso...",
  ui_story_70000802_30_dialog_content = "Ainda não entendeu?",
  ui_story_70000802_31_dialog_content = "Ele não esqueceu nada.",
  ui_story_70000802_32_dialog_content = "Muito pelo contrário... Ele se lembra muito bem.",
  ui_story_70000802_33_dialog_content = "...?!",
  ui_story_70000802_34_dialog_content = "O filho excluído. A única coisa que ele esqueceu, é o ódio contra a Illumina.",
  ui_story_70000802_35_dialog_content = "É hora de lembrá-lo.",
  ui_story_70000802_36_dialog_content = "<size=45>Graah! Rugido!</size>",
  ui_story_70000802_37_dialog_content = "Urgh...!",
  ui_story_70000802_38_dialog_content = "Isso é... memórias!?",
  ui_story_70000802_39_dialog_content = "Já se passaram quatro horas desde que Reinhardt rompeu...",
  ui_story_70000802_40_dialog_content = "Ainda sem sinos...",
  ui_story_70000802_41_dialog_content = "Ainda tenho força em mim. Vou mostrar aos Eclipsites o que tenho mesmo com meus punhos de urso.",
  ui_story_70000802_42_dialog_content = "E você? Quanta munição e suprimentos você tem?",
  ui_story_70000802_43_dialog_content = "10 rodadas e... dois pães de serragem.",
  ui_story_70000802_44_dialog_content = "Se eu soubesse que isso ia acontecer, eu teria ficado em Gannon e lidado com aqueles péssimos regulamentos de laboratório.",
  ui_story_70000802_45_dialog_content = "Sou muito mais proficiente em dissecar Eclipsitas com bisturis do que com rifles e balas.",
  ui_story_70000802_46_dialog_content = "Hahaha! Que estrela em ascensão de pesquisador você é.",
  ui_story_70000802_47_dialog_content = "Aposto que você ainda pode dar nós nos Eclipsites com pontos.",
  ui_story_70000802_48_dialog_content = "Ah. Obrigado pelo voto de confiança.",
  ui_story_70000802_49_dialog_content = "Mas até quando podemos aguentar?",
  ui_story_70000802_50_dialog_content = "Ou... Todos nós fomos abandonados?",
  ui_story_70000802_51_dialog_content = "...",
  ui_story_70000802_52_dialog_content = "Não importa. Não podemos perder a esperança.",
  ui_story_70000802_53_dialog_content = "Reinhardt... Ela voltará com reforços da Illumina.",
  ui_story_70000802_54_dialog_content = "Antes que isso aconteça, teremos que esperar.",
  ui_story_70000802_55_dialog_content = "Olha, a saída está à frente!",
  ui_story_70000802_56_dialog_content = "Há muitos Eclipsitas vagando por perto... Também...",
  ui_story_70000802_57_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_70000802_58_dialog_content = "A última batalha foi muito feroz. Vai desmoronar a qualquer segundo.",
  ui_story_70000802_59_dialog_content = "Está amanhecendo agora, quando os Eclipsitas estão no seu ponto mais fraco.",
  ui_story_70000802_60_dialog_content = "Se não aproveitarmos esta oportunidade para sair, morreremos aqui.",
  ui_story_70000802_61_dialog_content = "Me siga. Tentaremos romper quando os Eclipsitas se afastarem.",
  ui_story_70000802_62_dialog_content = "11 horas!",
  ui_story_70000802_63_dialog_content = "Eu sei!",
  ui_story_70000802_64_dialog_content = "Droga! Não há fim para isso!",
  ui_story_70000802_65_dialog_content = "Eu ainda posso aguentar! Denier, vá em direção à saída!",
  ui_story_70000802_66_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_70000802_67_dialog_content = "O chão está quebrando! Atenção!",
  ui_story_70000802_68_dialog_content = "Afe!",
  ui_story_70000802_69_dialog_content = "Hélio!",
  ui_story_70000802_70_dialog_content = "Eu tenho... que sobreviver.",
  ui_story_70000802_71_dialog_content = "Tenho que esperar... pelo reforço.",
  ui_story_70000802_72_dialog_content = "Quantos dias se passaram...?",
  ui_story_70000802_73_dialog_content = "Meu corpo... algo ruim está acontecendo comigo...",
  ui_story_70000802_74_dialog_content = "Sinos... Por favor, deixe-me ouvir o som dos sinos...",
  ui_story_70000802_75_dialog_content = "Um dia... dois dias...",
  ui_story_70000802_76_dialog_content = "Um ano... dois anos...",
  ui_story_70000802_77_dialog_content = "Onde está meu reforço?",
  ui_story_70000802_78_dialog_content = "Por que você me abandonou!?",
  ui_story_70000802_79_dialog_content = "*Rugido*",
  ui_story_70000802_80_dialog_content = "Parece que você está se lembrando agora.",
  ui_story_70000802_81_dialog_content = "Mas isso não é suficiente.",
  ui_story_70000802_82_dialog_content = "Assim como a Semente. A raiva é a melhor nutrição...",
  ui_story_70000802_83_dialog_content = "Deixe-me ajudá-lo.",
  ui_story_70000802_84_dialog_content = "O que você está fazendo, Forsakin!?",
  ui_story_70000802_85_dialog_content = "...",
  ui_story_70000802_86_dialog_content = "Reinhardt...",
  ui_story_70000802_87_dialog_content = "Por que... você não voltou com reforços?",
  ui_story_70000802_88_dialog_content = "Porque…",
  ui_story_70000802_89_dialog_content = "Sob a terrível situação, sacrificar você é a única resposta lógica.",
  ui_story_70000802_90_dialog_content = "Então, você realmente...",
  ui_story_70000802_91_dialog_content = "... não mudou.",
  ui_story_70000802_92_dialog_content = "Tanto você quanto a Illumina.",
  ui_story_70000802_93_dialog_content = "*Rugido*",
  ui_story_70000802_94_dialog_content = "Atenção! Está vindo por aqui!",
  ui_story_70000802_95_dialog_content = "Fúria! E... crescer.",
  ui_story_70000802_96_dialog_content = "Devore tudo... nesta Zona Escura!",
  ui_story_70000802_97_dialog_content = "*Rugido*",
  ui_story_70000802_98_dialog_content = "É hora de acabar com isso.",
  ui_story_70000802_99_dialog_content = "Vice, prepare-se para lutar!",
  ui_story_70000802_100_dialog_content = "Sim!",
  ui_story_70000902_1_dialog_content = "Graah! Rugido!",
  ui_story_70000902_2_dialog_content = "Ainda suprimido mesmo nesta condição?",
  ui_story_70000902_3_dialog_content = "Eu acho que você ainda é apenas um <color=#FFB400>assunto defeituoso</color>.",
  ui_story_70000902_4_dialog_content = "Mas, ser capaz de se mover já é um avanço no experimento.",
  ui_story_70000902_5_dialog_content = "Pelo menos isso é um pouco valioso.",
  ui_story_70000902_6_dialog_content = "Infelizmente não tenho tempo infinito.",
  ui_story_70000902_7_dialog_content = "Urgh...!",
  ui_story_70000902_8_dialog_content = "O Darkflow está... se concentrando na área!",
  ui_story_70000902_9_dialog_content = "O Darkflow é... muito forte! Não posso...",
  ui_story_70000902_10_dialog_content = "*tosse* Então, depois de todos esses anos, até um pesquisador fraco pode se tornar um lutador.",
  ui_story_70000902_11_dialog_content = "Feche.",
  ui_story_70000902_12_dialog_content = "Os fracos devem ficar no chão.",
  ui_story_70000902_13_dialog_content = "Quanto a você... Pegue este Darkflow e me mostre seu valor!",
  ui_story_70000902_14_dialog_content = "*Rugido*",
  ui_story_70000902_15_dialog_content = "O Eclipse está... desaparecendo...!",
  ui_story_70000902_16_dialog_content = "Graah! Rugido!",
  ui_story_70000902_17_dialog_content = "Eles estão... chorando de dor!",
  ui_story_70000902_18_dialog_content = "Forsakin está tomando sua força vital... atraindo o Darkflow!",
  ui_story_70000902_19_dialog_content = "Se essa quantidade de Darkflow for convertida em um ataque...",
  ui_story_70000902_20_dialog_content = "Mesmo uma explosão destruiria toda a Cidade Baixa!",
  ui_story_70000902_21_dialog_content = "Reinhardt, cuidado!",
  ui_story_70000902_22_dialog_content = "...!",
  ui_story_70000902_23_dialog_content = "PlayerName, encontre cobertura!",
  ui_story_70000902_24_dialog_content = "Muito devagar.",
  ui_story_70000902_25_dialog_content = "(Essa é a coisa mais devastadora que eu já vi.)",
  ui_story_70000902_26_dialog_content = "(O abrangente Darkflow e a escuridão da Noite Eterna acenando como o mar, devastando a terra e tudo à vista.)",
  ui_story_70000902_27_dialog_content = "(Vice e eu, presos ao chão pela tremenda pressão, ficamos impotentes contra uma força tão terrível.)",
  ui_story_70000902_28_dialog_content = "(Tudo o que posso fazer é levantar a cabeça e assistir enquanto o Darkflow me devora.)",
  ui_story_70000902_29_dialog_content = "E então, na escuridão sem fim...",
  ui_story_70000902_30_dialog_content = "Eu vi <color=#FFB400>leve</color>.",
  ui_story_70000902_31_dialog_content = "Não. Eu não vou fazer do seu jeito!",
  ui_story_70000902_32_dialog_content = "Reinhardt!?",
  ui_story_70000902_33_dialog_content = "(Em meio a essa escuridão eterna, a luz pode ser apenas um vislumbre que pode se apagar a qualquer momento...)",
  ui_story_70000902_34_dialog_content = "(Mas ainda assim persistiu e resistiu à escuridão, espalhando seu brilho.)",
  ui_story_70000902_35_dialog_content = "(Como o sol nascente no horizonte, anunciando a chegada do dia.)",
  ui_story_70000902_36_dialog_content = "É só... algum Darkflow mesquinho.",
  ui_story_70000902_37_dialog_content = "E eu carrego a Luz de Illumina em meus ombros!",
  ui_story_70000902_38_dialog_content = "Eu vou segurar o céu mesmo que ele caia na Illumina!",
  ui_story_70000902_39_dialog_content = "(Lentamente, a escuridão é afastada...)",
  ui_story_70000902_40_dialog_content = "(Luz, atravessa as nuvens.)",
  ui_story_70000902_41_dialog_content = "Argh!",
  ui_story_70000902_42_dialog_content = "...!",
  ui_story_70000902_43_dialog_content = "Reinhardt!",
  ui_story_70000902_44_dialog_content = "Abandonar a defesa completamente por um ataque completo... não é?",
  ui_story_70000902_45_dialog_content = "Mesmo assim, a maioria dos ataques pode ser facilmente bloqueada...",
  ui_story_70000902_46_dialog_content = "Ha... que tolo",
  ui_story_70000902_47_dialog_content = "Um tolo louco.",
  ui_story_70000902_48_dialog_content = "Este nível de potência está dentro dos parâmetros esperados.",
  ui_story_70000902_49_dialog_content = "Qualquer outro auroriano comum teria enlouquecido pelo Darkflow dessa magnitude.",
  ui_story_70000902_50_dialog_content = "Você é digno.",
  ui_story_70000902_51_dialog_content = "Tão digno quanto o maior \"monstro\" que saiu vivo do Mire pode ser.",
  ui_story_70000902_52_dialog_content = "Essas pessoas realmente te \"ensinaram\" bem.",
  ui_story_70000902_53_dialog_content = "Da mesma maneira.",
  ui_story_70000902_54_dialog_content = "Segurando uma tecnologia tão avançada, mas apenas se imaginando herói em um jogo infantil...",
  ui_story_70000902_55_dialog_content = "E você realmente parece estar se divertindo.",
  ui_story_70000902_56_dialog_content = "Porque era o nosso sonho... não era?",
  ui_story_70000902_57_dialog_content = "Para se tornar o Grande Marechal da Illumina e levar o povo da Illumina a um mundo melhor.",
  ui_story_70000902_58_dialog_content = "Para a Illumina e seu povo...",
  ui_story_70000902_59_dialog_content = "Que ingênuo. O que eles realmente fizeram por você? Nada, a não ser tomar você como garantido e pedir sua proteção sem fim.",
  ui_story_70000902_60_dialog_content = "Aos olhos deles, você é apenas um símbolo em forma humana. Facilmente substituído e descartado.",
  ui_story_70000902_61_dialog_content = "A verdade é que você não é diferente daqueles animais de teste vivos.",
  ui_story_70000902_62_dialog_content = "Um pesquisador se preocupa apenas com os dados obtidos dos sujeitos do teste.",
  ui_story_70000902_63_dialog_content = "E essas pessoas se importam apenas com... uma imagem aparentemente poderosa. Não importa para eles a quem essa imagem está sobreposta.",
  ui_story_70000902_64_dialog_content = "Hehe...",
  ui_story_70000902_65_dialog_content = "Hahaha!",
  ui_story_70000902_66_dialog_content = "Renegado... Não. Negador...",
  ui_story_70000902_67_dialog_content = "Você se tornou um tagarela também.",
  ui_story_70000902_68_dialog_content = "Ainda me lembro de como você sempre se trancava em um laboratório, fazendo seus experimentos.",
  ui_story_70000902_69_dialog_content = "Não importa o que eu te disse, você só quer provar ao mundo que você foi o melhor.",
  ui_story_70000902_70_dialog_content = "...",
  ui_story_70000902_71_dialog_content = "Naquela época, você nunca se importava com a forma como os outros o viam.",
  ui_story_70000902_72_dialog_content = "Estou no seu lugar agora. Eu sou o Grande Marechal de Illumina. Eu protegerei a Illumina e seu povo. Isso é tudo o que há para isso.",
  ui_story_70000902_73_dialog_content = "Quanto a como eles me vêem? Eu não poderia me incomodar com isso.",
  ui_story_70000902_74_dialog_content = "Quem sou hoje, aprendi isso com você.",
  ui_story_70000902_75_dialog_content = "...",
  ui_story_70000902_76_dialog_content = "Sabe o que? Vou colocar uma etiqueta em seus dados de teste: \"lunático\".",
  ui_story_70000902_77_dialog_content = "Agora que consegui os materiais de que preciso, é hora de voltar aos meus experimentos.",
  ui_story_70000902_78_dialog_content = "For... sakin...",
  ui_story_70000902_79_dialog_content = "A, mas isso simplesmente não vai morrer.",
  ui_story_70000902_80_dialog_content = "Não como este artigo experimental fracassado…",
  ui_story_70000902_81_dialog_content = "...",
  ui_story_70000902_82_dialog_content = "Isso é tudo...?",
  ui_story_70000902_83_dialog_content = "Bem... eu acho que é um pouco digno como assunto de estudo.",
  ui_story_70000902_84_dialog_content = "Não é um Auroriano nem um Eclipsite.",
  ui_story_70000902_85_dialog_content = "Apenas algo com... algum valor como peão.",
  ui_story_70000902_86_dialog_content = "O que você está fazendo!? Derrube ele!",
  ui_story_70000902_87_dialog_content = "Você acha que pode me impedir? Quem você pensa que é?",
  ui_story_70000902_88_dialog_content = "\"Está na hora.\"",
  ui_story_70000902_89_dialog_content = "Tremores e poeira... vindo do horizonte...?",
  ui_story_70000902_90_dialog_content = "PlayerName.... O que é aquilo?",
  ui_story_70000902_91_dialog_content = "não sei... deixe-me ver...",
  ui_story_70000902_92_option_content = "Aumento de Força!",
  ui_story_70000902_93_dialog_content = "...!",
  ui_story_70000902_94_dialog_content = "(Aqueles são... Eclipses!?)",
  ui_story_70000902_95_dialog_content = "(Uma legião inteira de... Eclipsites!)",
  ui_story_70000902_96_dialog_content = "(Eclipsiano) Socorro... Renegados!",
  ui_story_70000902_97_dialog_content = "(Eles estão vindo aqui!?)",
  ui_story_70000902_98_dialog_content = "(Mesmo que tenhamos Reinhardt, ainda há muitos deles...)",
  ui_story_70000902_99_dialog_content = "(E... ela sofreu ferimentos graves de seu ataque desesperado mais cedo...)",
  ui_story_70000902_100_dialog_content = "(Ela está segurando por sua pura vontade sozinha...)",
  ui_story_70000902_101_dialog_content = "(Temos que recuar agora!)",
  ui_story_70000902_102_dialog_content = "Reinhardt! É sério!",
  ui_story_70000902_103_dialog_content = "O quê?",
  ui_story_70000902_104_dialog_content = "Eu posso sentir um grande número de Eclipses vindo em nossa direção! Eles estarão aqui a qualquer segundo!",
  ui_story_70000902_105_dialog_content = "Existem também entidades poderosas entre eles!",
  ui_story_70000902_106_dialog_content = "Nós temos de ir agora!",
  ui_story_70000902_107_dialog_content = "Apenas três minutos... Isso é tudo que eu preciso!",
  ui_story_70000902_108_dialog_content = "*Rugido*",
  ui_story_70000902_109_dialog_content = "Não há tempo, Reinhardt!",
  ui_story_70000902_110_dialog_content = "Estaremos cercados se esperarmos!",
  ui_story_70000902_111_dialog_content = "...",
  ui_story_70000902_112_dialog_content = "\"Regra 3: Evite o combate a todo custo no Pântano. Saiba quando parar.\"",
  ui_story_70000902_113_dialog_content = "...",
  ui_story_70000902_114_dialog_content = "Fracos.",
  ui_story_70000902_115_dialog_content = "Você sabe em seu coração que ele é nosso irmão de armas.",
  ui_story_70000902_116_dialog_content = "Se você se atrever a ela ou ao povo de Illumina... Eu farei você pagar.",
  ui_story_70000902_117_dialog_content = "Ah.",
  ui_story_70000902_118_dialog_content = "Que tal você conseguir sobreviver primeiro e depois dizer isso na minha cara?",
  ui_story_70000902_119_dialog_content = "Você não tem o luxo de escolher agora.",
  ui_story_70000902_120_dialog_content = "...",
  ui_story_70000902_121_dialog_content = "Vice, PlayerName, prepare-se para evacuar.",
  ui_story_70000902_122_dialog_content = "...",
  ui_story_70000902_123_dialog_content = "Você está ficando sem tempo...",
  ui_story_70000902_124_dialog_content = "Minha irmã.\"",
  ui_story_70001001_1_dialog_content = "Vice, levante o Reinhardt e eu vou ativar o Colossus!",
  ui_story_70001001_2_dialog_content = "Vamos!",
  ui_story_70001001_3_dialog_content = "Estamos... no ar?",
  ui_story_70001001_4_dialog_content = "Sim, estamos no ar agora!",
  ui_story_70001001_5_dialog_content = "Mal saímos do chão a tempo...",
  ui_story_70001001_6_dialog_content = "RTB... Velocidade máxima...",
  ui_story_70001001_7_dialog_content = "Grande Marechal Reinhardt?",
  ui_story_70001001_8_dialog_content = "Seus ferimentos são muito graves... É uma maravilha que ela tenha se aguentado por tanto tempo.",
  ui_story_70001001_9_dialog_content = "PlayerName, você vai pilotar o Soroz. Vou pegar o kit de primeiros socorros.",
  ui_story_70001001_10_dialog_content = "Vamos!",
  ui_story_70001001_11_dialog_content = "Apenas espere... Reinhardt...",
  ui_story_70001001_12_dialog_content = "Err...",
  ui_story_70001001_13_dialog_content = "Não parece bom. O Grande Marechal está em condições críticas.",
  ui_story_70001001_14_dialog_content = "Ela precisa de tratamento médico imediato!",
  ui_story_70001001_15_dialog_content = "<color=#e8d9bb>\"Palavra-chave detectada: Tratamento médico.\"</color>",
  ui_story_70001001_16_dialog_content = "<color=#e8d9bb>\"Digitalizando dados... Verificação concluída.\"</color>",
  ui_story_70001001_17_dialog_content = "<color=#e8d9bb>\"Atualização do módulo de reparo do modelo de eco encontrada.\"</color>",
  ui_story_70001001_18_dialog_content = "<color=#e8d9bb>\"Instale o modelo de eco para atualizar o sistema de suporte de vida para o sistema médico de emergência.\"</color>",
  ui_story_70001001_19_option_content = "Soroz?",
  ui_story_70001001_20_dialog_content = "De repente ativou!?",
  ui_story_70001001_21_dialog_content = "Unidade de reparo Echo Template... Quer dizer isso? Como posso esquecer isso!?",
  ui_story_70001001_22_dialog_content = "Como é um sistema médico, provavelmente pode ajudar Reinhardt.",
  ui_story_70001001_23_dialog_content = "Vamos instalá-lo e ver!",
  ui_story_70001001_24_dialog_content = "<color=#e8d9bb>\"Módulo de reparo de modelo de eco detectado.\"</color>",
  ui_story_70001001_25_dialog_content = "<color=#e8d9bb>\"Estabelecendo conexão... Completo.\"</color>",
  ui_story_70001001_26_dialog_content = "<color=#e8d9bb>\"Priorização do sistema... Concluída.\"</color>",
  ui_story_70001001_27_dialog_content = "<color=#e8d9bb>\"Atualização do sistema de suporte à vida encontrada. Iniciando atualização.\"</color>",
  ui_story_70001001_28_dialog_content = "O módulo de reparo está... mudando!?",
  ui_story_70001001_29_dialog_content = "<color=#e8d9bb>\"Atualização concluída. Sistema de emergência médica operacional.\"</color>",
  ui_story_70001001_30_dialog_content = "<color=#e8d9bb>\"Carga Atual: 1; Slot Restante: 1\"</color>",
  ui_story_70001001_31_dialog_content = "<color=#e8d9bb>\"Informe seu nome e confirme.\"</color>",
  ui_story_70001001_32_dialog_content = "Mas... Não deveríamos fazer uma checagem completa primeiro?",
  ui_story_70001001_33_dialog_content = "Err...",
  ui_story_70001001_34_dialog_content = "Acho que não temos tempo para isso.",
  ui_story_70001001_35_dialog_content = "Temos que aproveitar a chance...",
  ui_story_70001001_36_dialog_content = "Sim!",
  ui_story_70001001_37_dialog_content = "Eu espero que isso funcione...",
  ui_story_70001001_38_dialog_content = "Ela vai ficar bem.",
  ui_story_70001001_39_dialog_content = "Eu acredito nela, e acredito na Soroz.",
  ui_story_70001001_40_dialog_content = "O comando de voz agora mesmo... O Soroz deve saber que precisávamos de ajuda, então ele forneceu...",
  ui_story_70001001_41_dialog_content = "Hmm...",
  ui_story_70001001_42_dialog_content = "O Sistema Médico de Emergência parece precisar de algum tempo com ela...",
  ui_story_70001001_43_dialog_content = "Vamos voltar nossa atenção para encontrar uma maneira de reparar o modelo de eco nesse meio tempo.",
  ui_story_70001001_44_dialog_content = "OK. Eu vou ajudar também.",
  ui_story_70001001_45_dialog_content = "<color=#e8d9bb>\"Retomar o procedimento de reparo do modelo de eco.\"</color>",
  ui_story_70001001_46_dialog_content = "<color=#e8d9bb>\"Passo um: Instale o plug-in de banco de dados padrão Colossus Echo Template.\"</color>",
  ui_story_70001001_47_dialog_content = "Hã?",
  ui_story_70001001_48_dialog_content = "Diga o quê...?",
  ui_story_70001001_49_dialog_content = "PlayerName, você colocou as mãos em outros módulos?",
  ui_story_70001001_50_dialog_content = "Ui... Só aquele...",
  ui_story_70001001_51_dialog_content = "Soroz, o que é esse plugin de banco de dados?",
  ui_story_70001001_52_dialog_content = "<color=#e8d9bb>\"Procurando informações sobre o plug-in de banco de dados padrão Colossus Echo Template... Pesquisa concluída.\"</color>",
  ui_story_70001001_53_dialog_content = "<color=#e8d9bb>\"Resposta: O plug-in de banco de dados padrão do modelo Colossus Echo é um modelo para o The Colossus' Echo.\"</color>",
  ui_story_70001001_54_dialog_content = "<color=#e8d9bb>\"Módulo atual no armazenamento: 0\"</color>",
  ui_story_70001001_55_dialog_content = "<color=#e8d9bb>\"Observação: os plug-ins de banco de dados padrão do Colossus Echo Template podem ser encontrados em Colossi Maintenance Bases.\"</color>",
  ui_story_70001001_56_dialog_content = "<color=#e8d9bb>\"Procurando a Base de Manutenção Colossus mais próxima... Pesquisa concluída.\"</color>",
  ui_story_70001001_57_dialog_content = "<color=#e8d9bb>\"Alvo localizado em: Eraveil.\"</color>",
  ui_story_70001001_58_dialog_content = "Eraveil...!?",
  ui_story_70001001_59_dialog_content = "Ainda há uma base em Eraveil!?",
  ui_story_70001001_60_dialog_content = "Como nunca ouvi falar...",
  ui_story_70001001_61_dialog_content = "<color=#e8d9bb>\"Observação: se o plug-in não puder ser instalado, o Echo Template Repair Module será suspenso no modo de espera.\"</color>",
  ui_story_70001001_62_dialog_content = "Entre no modo de espera...",
  ui_story_70001001_63_dialog_content = "<color=#e8d9bb>\"Módulo de reparo de modelo de eco Soroz entrando no modo de espera.\"</color>",
  ui_story_70001001_64_dialog_content = "Assim que voltarmos para Eraveil, eu vou encontrar isso <color=#FFB400>Base de Manutenção Colosso</color>.",
  ui_story_70001001_65_dialog_content = "Mesmo se eu tivesse que entregar o Eraveil, eu encontraria uma maneira de salvar o Soroz...",
  ui_story_70001001_66_dialog_content = "Mas nossa primeira prioridade é enviar o Grande Marechal de volta à Linha Segura.",
  ui_story_70001001_67_dialog_content = "De fato...",
  ui_story_70001001_68_dialog_content = "Como está Reinhardt?",
  ui_story_70001001_69_dialog_content = "O sistema médico está tratando dela.",
  ui_story_70001001_70_dialog_content = "Só não sei se é eficaz...",
  ui_story_70001001_71_dialog_content = "Espero que tudo corra bem.",
  ui_story_70001001_72_dialog_content = "<color=#e8d9bb>Bip, bip, bip!</color>",
  ui_story_70001001_73_dialog_content = "Um pedido de comunicação da Illumina...? Mas o chamador é desconhecido.",
  ui_story_70001001_74_dialog_content = "Podem ser nossos reforços. Vamos ouvi-los!",
  ui_story_70001001_75_dialog_content = "Saudando o Soroz... Tenente Vice, Caelestite PlayerName...",
  ui_story_70001001_76_dialog_content = "Me escuta?",
  ui_story_70001001_77_dialog_content = "Como devo responder a isso...?",
  ui_story_70001001_78_dialog_content = "Direita. Este é o Soroz. Nós recebemos você.",
  ui_story_70001001_79_dialog_content = "Este é o oficial de inteligência Aison da Illumina.",
  ui_story_70001001_80_dialog_content = "Qual é a sua localização atual?",
  ui_story_70001001_81_dialog_content = "Sudoeste de Undercity 80. Tempo estimado para a linha de defesa Illumina... 10 minutos.",
  ui_story_70001001_82_dialog_content = "Temos uma situação urgente a relatar!",
  ui_story_70001001_83_dialog_content = "O Grande Marechal Reinhardt é gravemente ferido em combate. Exigimos tratamento médico imediato.",
  ui_story_70001001_84_dialog_content = "Eu sabia.",
  ui_story_70001001_85_dialog_content = "Nada.",
  ui_story_70001001_86_dialog_content = "Farei com que uma equipe médica o receba na linha de defesa da Illumina. Basta levá-la lá o mais rápido possível.",
  ui_story_70001001_87_dialog_content = "Eu sei!",
  ui_story_70001001_88_dialog_content = "Fora.",
  ui_story_70001001_89_dialog_content = "Eles realmente estão com pressa.",
  ui_story_70001001_90_dialog_content = "Grande marechal!",
  ui_story_70001001_91_dialog_content = "Reinhardt...!",
  ui_story_70001001_92_dialog_content = "Como você está se sentindo?",
  ui_story_70001001_93_dialog_content = "Estou bem. Sinto que todo o meu corpo está prestes a explodir... mas não vou morrer hoje.",
  ui_story_70001001_94_dialog_content = "Você precisará de alguns dias de descanso para se recuperar.",
  ui_story_70001001_95_dialog_content = "A tecnologia do Caelestite é realmente algo.",
  ui_story_70001001_96_dialog_content = "Se tivéssemos algumas dessas unidades médicas nas Cidades Baixas de Illumina, a maioria das pessoas teria sobrevivido...",
  ui_story_70001001_97_dialog_content = "Não saberia dessa função se o Soroz não me lembrasse.",
  ui_story_70001001_98_dialog_content = "Ah, e como está o Soroz agora?",
  ui_story_70001001_99_dialog_content = "Temos o módulo necessário, mas ainda precisamos de algo mais para reparar o Soroz.",
  ui_story_70001001_100_dialog_content = "É assim tão...",
  ui_story_70001001_101_dialog_content = "Espero que você possa consertá-lo em breve.",
  ui_story_70001001_102_dialog_content = "...",
  ui_story_70001001_103_dialog_content = "Reinhardt, há algo que eu não entendo.",
  ui_story_70001001_104_dialog_content = "Hum? Você já não tinha sua \"última pergunta\"?",
  ui_story_70001001_105_dialog_content = "Não. Não é uma pergunta... Apenas algo que acho contraditório...",
  ui_story_70001001_106_dialog_content = "Você não é alguém que abandonaria seus amigos.",
  ui_story_70001001_107_dialog_content = "Mas por que você escolheria abandoná-los então?",
  ui_story_70001001_108_dialog_content = "Foi a decisão mais razoável... naquela época.",
  ui_story_70001001_109_dialog_content = "Não permitirei que os soldados da Illumina sejam sacrificados sem uma boa razão.",
  ui_story_70001001_110_dialog_content = "Mas naquela época, você não era o Grande Marechal. Você era apenas um soldado.",
  ui_story_70001001_111_dialog_content = "Tenho certeza de que há mais do que isso.",
  ui_story_70001001_112_dialog_content = "É estranho... na verdade.",
  ui_story_70001001_113_dialog_content = "Grande Marechal, você veio pessoalmente para nos salvar e tentou de tudo para atrair seus antigos camaradas.",
  ui_story_70001001_114_dialog_content = "Acho que você teria voltado para salvá-los, não importa o que acontecesse naquela época...",
  ui_story_70001001_115_dialog_content = "...",
  ui_story_70001001_116_dialog_content = "O celestita é difícil de lidar.",
  ui_story_70001001_117_option_content = "Eu vou aceitar isso como um elogio",
  ui_story_70001001_118_option_content = "Você pode dizer que estou mais atento aos detalhes",
  ui_story_70001001_119_dialog_content = "Eu não queria reviver o passado, mas se eu realmente pensar no passado...",
  ui_story_70001001_120_dialog_content = "Quando atravessei as linhas inimigas e voltei para a Safe Line naquela época...",
  ui_story_70001001_121_dialog_content = "Tenho notícias urgentes para relatar!",
  ui_story_70001001_122_dialog_content = "A informação anterior estava errada! O interior do Undercity 80 está repleto de Eclipsites!",
  ui_story_70001001_123_dialog_content = "Eu rompi sozinho para obter ajuda para minha equipe ainda presa lá. Temos baixas pesadas!",
  ui_story_70001001_124_dialog_content = "Precisamos de apoio!",
  ui_story_70001001_125_dialog_content = "Entendido. Nós vamos olhar para isso. Médico, cuide dos ferimentos dela.",
  ui_story_70001001_126_dialog_content = "Esse caminho por favor...",
  ui_story_70001001_127_dialog_content = "Não! Você não entende a urgência disso!",
  ui_story_70001001_128_dialog_content = "Eles precisam de apoio AGORA!",
  ui_story_70001001_129_dialog_content = "Caso contrário... meus amigos... eles vão morrer lá!",
  ui_story_70001001_130_dialog_content = "Uma operação de busca e salvamento precisa ser planejada e discutida. Esta não é sua preocupação agora. Você está dispensado.",
  ui_story_70001001_131_dialog_content = "Você nem vai tentar salvá-los, vai?",
  ui_story_70001001_132_dialog_content = "Não faça suposições malucas.",
  ui_story_70001001_133_dialog_content = "Multar. Se não enviar ajuda, eu mesmo volto.",
  ui_story_70001001_134_dialog_content = "Eu não vou abandoná-los!",
  ui_story_70001001_135_dialog_content = "Você é um soldado da Illumina e está sujeito a ordens. Desafie minhas ordens novamente, e vou prendê-lo.",
  ui_story_70001001_136_dialog_content = "Meus amigos ainda estão esperando que eu volte.",
  ui_story_70001001_137_dialog_content = "Médico!",
  ui_story_70001001_138_dialog_content = "Como você ousa...",
  ui_story_70001001_139_dialog_content = "Coloque-a debaixo e cuide de suas feridas. E observe-a de perto.",
  ui_story_70001001_140_dialog_content = "Sim.",
  ui_story_70001001_141_dialog_content = "Quando finalmente acordei, os dias já haviam se passado.",
  ui_story_70001001_142_dialog_content = "Fui transferido para o centro médico em Gannon. As pessoas que voltaram da Safe Line me disseram...",
  ui_story_70001001_143_dialog_content = "No final, o Comitê nunca enviou reforços para Undercity 80.",
  ui_story_70001001_144_dialog_content = "Eu fui o único sobrevivente desse incidente.",
  ui_story_70001001_145_dialog_content = "...",
  ui_story_70001001_146_dialog_content = "Depois que me acalmei, mergulhei em pensamentos e finalmente entendi suas razões.",
  ui_story_70001001_147_dialog_content = "Cada vida é Illumina é igualmente importante.",
  ui_story_70001001_148_dialog_content = "As necessidades de muitos superam as necessidades de poucos.",
  ui_story_70001001_149_dialog_content = "Isso é algo que um Grande Marechal deve aceitar e fazer. Este é o preço a ser pago.",
  ui_story_70001001_150_dialog_content = "Até que Denier voltou para a Illumina, apesar de seus ferimentos graves.",
  ui_story_70001001_151_dialog_content = "Quem é agora Renegados...?",
  ui_story_70001001_152_dialog_content = "Fiquei feliz em ver meu amigo vivo, mas algo mudou entre nós depois.",
  ui_story_70001001_153_dialog_content = "No final, nos separamos.",
  ui_story_70001001_154_dialog_content = "Você mentiu para ela. Não foi sua decisão abandoná-los.",
  ui_story_70001001_155_dialog_content = "Eu senti que preferia que ela me odiasse em vez de odiar toda a Illumina.",
  ui_story_70001001_156_dialog_content = "Ela é extremamente brilhante, mas também vingativa.",
  ui_story_70001001_157_dialog_content = "Se sua raiva estivesse focada apenas em mim, as pessoas inocentes de Illumina seriam poupadas.",
  ui_story_70001001_158_dialog_content = "Um \"monstro\" como eu seria difícil de matar, de qualquer maneira.",
  ui_story_70001001_159_dialog_content = "Agora eu entendo.",
  ui_story_70001001_160_dialog_content = "Parece que te entendi mal.",
  ui_story_70001001_161_dialog_content = "Oh? Como?",
  ui_story_70001001_162_dialog_content = "Eu pensei que você fosse um bastardo de sangue frio.",
  ui_story_70001001_163_dialog_content = "PlayerName... Isso não é algo para se dizer na frente do Grande Marechal...",
  ui_story_70001001_164_dialog_content = "Hahaha⁠—Ah! Ah! *tosse*",
  ui_story_70001001_165_dialog_content = "*tosse* Estou bem.",
  ui_story_70001001_166_dialog_content = "Estou acostumado a ser incompreendido. Um a menos, um a mais, não importa para mim.",
  ui_story_70001001_167_dialog_content = "Contanto que eu consiga manter o povo da Illumina a salvo... posso aguentar tudo.",
  ui_story_70001001_168_dialog_content = "Hmm...",
  ui_story_70001001_169_dialog_content = "Tivemos uma longa conversa. Em breve chegaremos à Linha Segura da Illumina.",
  ui_story_70001001_170_dialog_content = "Direita. Sair da frigideira e entrar no fogo... Tenho que lidar com \"eles\" agora.",
  ui_story_70001001_171_dialog_content = "Grande Marechal, você voltou!",
  ui_story_70001001_172_dialog_content = "Se não o tivesse feito, o Comitê estaria nos mandando para o tribunal militar...",
  ui_story_70001001_173_dialog_content = "Ouvimos sobre sua lesão. A equipe médica está de prontidão neste momento!",
  ui_story_70001001_174_dialog_content = "Está bem. Estou bem.",
  ui_story_70001001_175_dialog_content = "Graças ao Caelestite e Colossus, meu tratamento médico de emergência já foi realizado. Estou estável no momento.",
  ui_story_70001001_176_dialog_content = "É tudo graças ao lembrete oportuno do Soroz.",
  ui_story_70001001_177_dialog_content = "Por favor, deixe-nos realizar um check-up completo, só para ter certeza!",
  ui_story_70001001_178_dialog_content = "Não podemos nos dar ao luxo de perder o Grande Marechal.",
  ui_story_70001001_179_dialog_content = "Perder o \"Grande Marechal\"... não é?",
  ui_story_70001001_180_dialog_content = "Veja, é isso que quero dizer. Os procedimentos podem ser necessários, mas ainda são um incômodo.",
  ui_story_70001001_181_dialog_content = "Um físico, é? Multar. Eu vou fazer como você diz.",
  ui_story_70001001_182_dialog_content = "Por aqui, por favor.",
  ui_story_70001001_183_dialog_content = "Me dê um momento. Eu preciso ter algumas palavras com PlayerName.",
  ui_story_70001001_184_dialog_content = "Huh? Oh tudo bem.",
  ui_story_70001001_185_dialog_content = "Se eles perguntarem sobre o que aconteceu em Undercity 80, você apenas diga a verdade.",
  ui_story_70001001_186_dialog_content = "Apesar de ser conservador e teimoso por direito próprio, o Comitê ainda faz as coisas pelos números. Eles não vão colocar a culpa em você.",
  ui_story_70001001_187_dialog_content = "Mas, e você...?",
  ui_story_70001001_188_dialog_content = "Não se preocupe. Da última vez que olhei, ainda sou o Grande Marechal da Illumina.",
  ui_story_70001001_189_dialog_content = "Certo... Tome cuidado. Espero que nos cruzemos novamente.",
  ui_story_70001001_190_dialog_content = "Gostaria disso.",
  ui_story_70001001_191_dialog_content = "Observei Reinhardt por trás até ela desaparecer da Cidade Baixa.",
  ui_story_70001001_192_dialog_content = "Preocupações brotaram em meu coração.",
  ui_story_70001001_193_dialog_content = "De qualquer forma, eu deveria voltar e verificar o status do Soroz.",
  ui_story_70001001_194_dialog_content = "Então volte para Eraveil e encontre uma maneira de repará-lo."
}
return config
